pfDB["quests"]["zhCN-epoch"] = {
  [11] = {
    ["T"] = "悬赏河爪豺狼人",
    ["O"] = "给兵营的瑞尼尔副队长带去8个彩色豺狼人臂章。",
    ["D"] = "有人在艾尔文森林的边界处看见了豺狼人，这些野蛮的动物在这儿肯定不会干什么好事。在了望塔南边的树林里有一大群豺狼人到处游荡，凭我们自己的兵力很难应付他们。东边石碑湖附近也有另一群豺狼人盘踞着。\n\n任何帮忙清除这些豺狼人的勇士都会受到暴风城军方的嘉奖。把他们的彩色豺狼人臂章带给我，以证明你的战绩。",
  },
  [76] = {
    ["T"] = "玉石矿洞",
    ["O"] = "杀死10个狗头人矿工和5个狗头人地占师，调查玉石矿洞，然后回到闪金镇向治安官杜汉复命。",
    ["D"] = "多亏了你，我们才知道法戈第矿洞里出现了很多狗头人。现在我们还需要一个人去更远处的玉石矿洞侦察。\n\n去查看一下玉石矿洞，确定那里是否有狗头人。到了那里，如果你看见狗头人，就把他们清理掉。向东沿着大路走，一直走到阿祖拉之塔，然后往北走就会看到山脚下的矿洞。",
  },
  [109] = {
    ["T"] = "向格里安·斯托曼报到",
    ["O"] = "去和格里安·斯托曼谈一谈，他一般就在哨兵岭的石塔旁，这座石塔位于西部荒野中部地区的路边。",
    ["D"] = "看上去你参加过不少战斗，$c。如果你还没有去格里安·斯托曼那里报到的话，就赶快去吧。他是人民军的领袖，这是个专门负责保卫西部荒野的民兵组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。",
  },
  [26409] = {
    ["T"] = "猎人之路",
    ["O"] = "与闪金镇的詹姆斯·科贝特谈一谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经有足够的本事去驾驭一头野兽，把它训练成自己的伙伴了。\n\n你该去闪金镇见詹姆斯·科贝特。他会指引你走上获得自己宠物的道路。",
  },
  [26410] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一只石皮野猪。练习你的技能，然后将驯兽棒还给闪金镇的詹姆斯·科贝特。",
    ["D"] = "你好啊，$G小子:姑娘;！所以，你想知道该怎么拥有一只自己的宠物？\n\n那么，我们还是把注意力放到你肯定很感兴趣的事上：宠物！\n\n想学会这门本事，最好的办法就是亲自试试不同的野兽伙伴，看看你喜欢哪一种。所以，去找一只石皮野猪，然后用驯兽棒驯服它吧。",
  },
  [26411] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一只觅食的灰狼。练习你的技能，然后将驯兽棒还给闪金镇的詹姆斯·科贝特。",
    ["D"] = "这些石皮野猪相当魁梧；也许你会更喜欢灵巧一点的伙伴？好吧，我正有合适的。东边有一种名叫觅食的灰狼的大型狼类。就像一张精雕细琢的长弓一样，它们美丽的外表下藏着强大的战斗力，能够造成惊人的伤害。你会发现，它比你刚驯服的野猪更加敏捷迅速。\n\n带上这根驯兽棒，看看你是否喜欢灰狼。",
  },
  [26412] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一头森林熊幼崽。练习你的技能，然后将驯兽棒还给闪金镇的詹姆斯·科贝特。",
    ["D"] = "也许你更想要一头只凭蛮力取胜的野兽。对于像你这样初出茅庐的猎人来说，森林熊幼崽会是个极好的伙伴，它就在闪金镇东边。拿着这个驯兽棒，把这头野兽变成你的宠物，看看你是否喜欢！\n\n你回来以后，我会教你驯服任意野兽所需的本领；这头生物会与你一同面对挑战，也会陪你一起成长。我还会告诉你该怎样召唤它、解散它。",
  },
  [26414] = {
    ["T"] = "破旧的信件",
    ["O"] = "阅读破旧的信件，然后与北郡修道院的茜茜·赫伯特谈一谈。",
    ["D"] = "你刚从狗头人营地回来，就有人托我立刻把这东西交给你，$N。看起来这是我们本地猎人训练师茜茜寄来的信。你最好先读一读，再去忙修道院里的其他事情。",
