  [465] = {
    ["T"] = "古杰克的谋略",
    ["O"] = "摧毁龙喉投石车。",
    ["D"] = "当你在和龙喉氏族作战时，我们发现了更多他们的计划。\n古杰克建造了投石车，打算围攻米奈希尔！而且丹奥加兹那边战事正紧，我们实际上已经被援军隔断了！\n你必须毁掉那些投石车。它们就在龙喉营地里。\n给，带上这些火绒。一路杀到投石车旁，用火绒把它们点燃。\n做完之后，找到并杀死古杰克。我们必须从脖子那里斩断这头龙喉野兽。",
  },
  [474] = {
    ["T"] = "击败古杰克",
    ["O"] = "杀死古杰克将军\n把古杰克的头颅带给斯托菲队长。",
