  [487] = {
    ["T"] = "达纳苏斯之路",
    ["O"] = "将10个瘤背护身符交给多兰纳尔外的哨兵阿玛拉·夜行者。",
    ["D"] = "我们必须保证通往达纳苏斯的道路的安全。有报告说，从多兰纳尔去达纳苏斯的旅行者经常会受到来自瘤背熊怪的残忍袭击。\n\n每天都有无数重要的信息在这条路上进行传递，因此我们绝对不能容忍这帮堕落的熊怪整日恐吓无辜的旅者。\n\n以神圣森林的名义拿起武器，$c。熊怪们的巢穴就在这个高地下面的某个地方。把他们的神圣护身符带来交给我，然后回来复命。",
  },
  [537] = {
    ["T"] = "黑暗议会",
    ["O"] = "杀死阿古斯暗影法师，并把他们的一本法术书带回希尔斯布莱德丘陵南海镇的赫尼·马雷布镇长那里。",
    ["D"] = "你拿来的信是一个自称纳伽兹的人写的，他是阿古斯复苏的一员。我不知道这个阿古斯复苏是什么组织，不过如果他们和辛迪加结盟，那就一定是个威胁。\n\n我要你去找信中提到的阿古斯暗影法师。找到他们，杀掉他们。把他们身上任何能告诉我们纳伽兹究竟是谁、究竟是什么东西的物品带回来。\n\n去斯坦恩布莱德和北边的高地一带搜寻。运气好的话，你会在那里找到这些阿古斯复苏的使者。",
  },
  [991] = {
    ["T"] = "莱恩的净化",
    ["O"] = "在灰谷找到泰洛尼斯。",
    ["D"] = "$N，我有一个老朋友也在灰谷这里协助哨兵部队，但他一直没有回来。\n他掌握了一些线索，正在寻找一件他认为能减缓熊怪袭击我们同胞的物品——一根由早已死去的邪恶巫师制造的魔棒。\n离开这里之前，他提到要去寻找魔棒所需的一块宝石。\n他说那块宝石可能藏在西边山脚下法拉希姆湖的神殿里。那地方被攻陷以前，宝石一直保存在那里。\n请找到我的朋友，$N。",
  },
  [1132] = {
    ["T"] = "菲欧拉·长耳",
    ["O"] = "和塞拉摩的菲欧拉·长耳谈一谈。",
    ["D"] = "啊，真想再次回到海上！感受海风的亲吻，让浪涛像许多年前我那慈爱的母亲一样轻轻摇晃着我！\n啊，善良的$c，我真希望自己有你这样的好运，因为我看见大海就在你的未来之中！\n我的职责就是向渴望远行的人们讲述卡利姆多，那片充满机遇的土地！如果你愿意到海的另一边试试运气，就从这里乘船前往美丽的塞拉摩港吧。到了那里，去找我的伙伴，那位精灵菲欧拉·长耳谈一谈。\n她会引领你踏上卡利姆多的冒险！",
  },
  [1218] = {
