    ["D"] = "我喜欢做菜。地道的沼泽菜。油炸绿蛙腿之类的。\n要做菜，我就需要香料。舒心草。然后我就能炖上一锅，把它炖得香喷喷，再大口喝下去，也分你一点。\n你喜欢炖汤吗？",
