    ["O"] = "把维米斯的报告带给塞拉摩的吉安娜·普罗德摩尔女士。",
    ["D"] = "你干得很不错，$N，是我见过的业余人士里最出色的。\n普罗德摩尔女士要求我随时向她通报这件棘手局势的进展，而我已经有一阵子没和她谈过了。\n我原本打算晚些时候亲自把报告交给她，不过现在看来，由你去和她谈这件事更合适。你大概比我更能回答她的问题。",
  },
  [2038] = {
    ["T"] = "宾格斯的补给品",
    ["O"] = "找回并归还宾格斯的补给品：\n\n宾格斯的扳手、宾格斯的螺丝起子、宾格斯的榔头和宾格斯的气压炸弹。",
    ["D"] = "坠进洛克湖还不够倒霉，附近小岛上的穴居人又袭击了我，偷走了我的工具和特制的布拉斯特恩海默气压炸弹。没有旋翼机，也没有炸药，行动就完全没希望了！\n\n帮我找回工具，再找到我的气压炸弹，$N。为了诺莫瑞根！ ",
  },
  [3382] = {
    ["T"] = "受袭的船员",
    ["O"] = "保护瓦妮莎·贝蒂斯船长、她的船员和地平线轻帆号的乘客，抵御纳迦袭击。瓦妮莎·贝蒂斯船长必须存活。",
    ["D"] = "我们当时就在海岸外寻找一个安全的地方下锚。太阳落下还不到一个小时，他们就袭击了我们……那些该死的纳迦！\n我不知道他们在找什么，但显然他们没找到——他们已经回来过一次了。我的几个斥候正在山谷入口处守望，好在下一波袭击来临时提前示警。\n很抱歉你偏偏这时候来了，$n，但这已经不是我能控制的事了。\n你准备好迎接人生中最艰难的一战了吗？",
  },
  [9609] = {
    ["T"] = "帮助卫兵比格斯",
    ["O"] = "在悲伤沼泽找到卫兵比格斯。",
    ["D"] = "玛格图尔告诉我，附近有一名被困的卫兵。显然，他护送的商队从夜色镇出发后遭到了失落者袭击。听起来他是唯一的幸存者。\n他就在南边某处。请你帮帮他，$c。",
  },
  [9610] = {
    ["T"] = "泪水之池",
    ["O"] = "取得10件阿塔莱神器，并把它们带回悲伤沼泽避难营的芬米尔那里。",
    ["D"] = "我对研究艾泽拉斯的过去很感兴趣，不知道你愿不愿意帮忙？\n沼泽附近有一处具有历史意义的地方，我想请你去那里探查。泪水之池就在东南方。据说在它的岸边和水底，埋藏着阿塔莱巨魔文明的神器。\n不过要小心，那里由古老的绿龙索姆努斯和他的龙人守卫着，池中还有食肉鱼！",
  },
  [11160] = {
    ["T"] = "石槌战旗",
    ["O"] = "取回石槌战旗，并把它带到布洛格的洞穴交给布洛格。",
    ["D"] = "巨龙来了，占了布洛格以前的家，石槌食人魔逃走了，把所有东西都留在后面，包括氏族的战旗。\n布洛格知道战旗以前放在石槌食人魔山洞深处，可现在那里叫火焰洞穴。布洛格必须拿回氏族战旗，才能向杀死朋友们的巨龙复仇。\n布洛格氏族以前的山洞，也就是火焰洞穴，就在我的洞穴北边，里面到处都是龙人。战旗会在洞穴最深处。小心点，$N。",
  },
  [14087] = {
