    ["D"] = "这张宣传骑术训练和坐骑购买的传单是卡尔·雷歌寄来的。\n\n你可以在莫高雷的血蹄村找到卡尔。",
  },
  [26122] = {
    ["T"] = "湿地漫游",
    ["O"] = "在湿地中找回失落已久的鱼饵，并把它交给艾萨拉黑喉村的奥尔苏哈。",
    ["D"] = "我以前常在湿地待上很久，因为那里各种钓鱼的地方多得很。池塘、湖泊、河流、沼泽、大海，只要你说得出来，那儿就能钓。我在那里待得太久，连自己最喜欢的鱼饵都落下了。\n\n我说，要是哪天你去了那边，也许能帮我留意一下？奥尔苏哈很擅长修鱼饵，所以如果你碰巧找到它，他能帮忙修好。",
  },
  [26139] = {
    ["T"] = "迪菲亚杜卡特",
    ["O"] = "把迪菲亚杜卡特带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚迪菲亚杜卡特。\n\n这是迪菲亚为了从同情他们事业的商人手中换取货物而临时造出的货币。一面刻着石匠工具，另一面则是艘造型古怪的帆船图案。\n\n稀有钱币收藏家会对这件东西感兴趣。",
