    ["D"] = "你找到了一枚侏儒几尼。\n\n你可以推测，如果诺莫瑞根有朝一日被解放并清理干净，这些钱币会重新流通起来；但眼下，它们正受到钱币学家的追捧。\n\n稀有钱币收藏家会对这件东西感兴趣。",
