    ["O"] = "把铁炉堡弗罗林带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚铁炉堡弗罗林。\n\n这枚结实的矮人钱币在金本位以前铸造于铁炉堡最深处的大厅中，曾象征着繁荣与坚韧。虽然它早已不再流通，但它的工艺和历史意义让它成了收藏家眼中的珍品。\n\n稀有钱币收藏家会对这件东西感兴趣。",
