    ["O"] = "把铁炉堡先令带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚铁炉堡先令。\n\n这枚磨损严重的矮人钱币，带着米奈希尔繁忙市场中无数交易和酒馆消费留下的痕迹。它的设计虽然朴素，却见证了矮人商业经久不衰的本质。\n\n稀有钱币收藏家会对这件东西感兴趣。",
