    ["D"] = "你找到了一枚卡多雷月币。\n\n这枚古老的暗夜精灵钱币刻有艾露恩的新月标记，曾在第三次战争前的卡多雷中使用。虽然它的银色光泽已随岁月暗淡，但它的历史与精神意义并未减损。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26144] = {
