    ["D"] = "你找到了一枚卡多雷日币。\n\n这枚光彩夺目的金币压印着太阳纹饰，来自卡多雷文明接触联盟以前的时代。它的设计体现出暗夜精灵在工艺中对月亮与太阳同样怀有敬意。\n\n稀有钱币收藏家会对这件东西感兴趣。",
