    ["D"] = "你找到了一枚卡多雷星币。\n\n这枚精致而坚韧的钱币点缀着奥术蚀刻，代表着暗夜精灵社会曾经辉煌的巅峰。据说它曾在学者与贵族之间相赠，其美丽至今仍令懂得历史的人着迷。\n\n稀有钱币收藏家会对这件东西感兴趣。",
