  [26158] = {
    ["T"] = "暴风城克朗",
    ["O"] = "把暴风城克朗带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚暴风城克朗。\n\n这枚庄重的金币上压印着暴风城雄狮，曾是王国市场中财富与繁荣的象征。虽然历史学家仍认得它，但它如今的稀有程度让它作为收藏品比作为货币更有价值。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26159] = {
    ["T"] = "暴风城先令",
    ["O"] = "把暴风城先令带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚暴风城先令。\n\n这枚银币带有暴风城徽记，曾在城市繁忙的经济中自由流通。虽然它已不再日常使用，但它的工艺以及与暴风城历史的联系，让它成了珍贵的发现。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26160] = {
    ["T"] = "暴风城法新",
    ["O"] = "把暴风城法新带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚暴风城法新。\n\n这枚朴素的铜币曾是暴风城居民身边的常见之物，用于小额采购和日常交易。虽然它本身材质价值不高，历史价值却要大得多。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26161] = {
    ["T"] = "暴风城六便士",
    ["O"] = "把暴风城六便士带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚暴风城六便士。\n\n这枚铸造精良的钱币曾用于暴风城商业，因可靠而便利而广受青睐。它虽小，却承载着历史的分量，映照出这个王国的坚韧。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26162] = {
    ["T"] = "暴风城先令",
    ["O"] = "把暴风城先令带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚斯托姆加德先令。\n\n这枚粗犷的银币曾在斯托姆加德堡垒之城中使用，上面留有一个在战火中锻成的王国的印记。虽然它的人民已经四散，但这样的遗物仍让他们的传承延续下去。\n\n稀有钱币收藏家会对这件东西感兴趣。",
  },
  [26200] = {
    ["T"] = "森林的平衡",
    ["O"] = "杀死5只幼年枭兽和10只枭兽，然后回到奥伯丁的哨兵格琳达·纳尔希娅那里。",
    ["D"] = "愿艾露恩照拂你，$N。世间万物皆有平衡，艾露恩守望着森林，确保这一切不致偏斜。近来这份平衡正在动摇，我担心若再无人出手，连艾泽拉斯的根基都会受到撼动。我们向艾露恩祈祷，希望她派来援手，而你来了。\n\n眼下最主要的失衡源头，是东边那片枭兽栖地。有人回报说，泰达希尔也曾发生过类似的事——原本温顺的枭兽群忽然陷入了混乱。如今它们见到什么就攻击什么，扰乱了自然的流转。请你去处理那片巢群，让森林重新恢复平衡。",
  },
  [26201] = {
    ["T"] = "森林的平衡",
    ["O"] = "杀死3只枭兽先知和10只狂怒枭兽，然后回到奥伯丁的哨兵格琳达·纳尔希娅那里。",
    ["D"] = "不幸的是，我们净化的那片区域似乎只是整个巢群的一小部分。那些年长的枭兽生活在森林更东边的地方。亲手毁掉这些狂野的生灵让我感到悲伤，但我们必须做该做的事。\n\n回到那片枭兽栖地，继续往更深处搜寻。我们必须彻底清除这份威胁，才能确保奥伯丁的安全，也让森林的平衡得以恢复。",
  },
  [26202] = {
    ["T"] = "暮光之锤",
    ["O"] = "杀死8个暮光暴徒和8个暮光信徒，然后回到奥伯丁的奥兰达利亚·夜歌那里。",
    ["D"] = "奥伯丁正面临严重威胁，$N。他们自称暮光之锤，是一个散播混乱与动荡的邪教，专门扰乱森林的平衡。他们崇拜古神，妄图将其重新唤醒，把毁灭带遍整个艾泽拉斯。\n\n他们必须被阻止！在遥远南方、靠近灰谷边界的主宰之剑一带，他们设有一处据点。去吧，$N，洗净这个邪教留在黑海岸上的污痕。",
  },
  [26203] = {
    ["T"] = "欢迎来到奥伯丁",
    ["O"] = "向奥伯丁的军需官娜雅娜报到。",
    ["D"] = "欢迎来到奥伯丁，希望你一路平安。这里有许多事情亟待处理，我们若能得到你的协助，将感激不尽。枭兽、熊怪、鱼人、邪教徒、娜迦……麻烦制造者的名单可长着呢！\n\n我想，最好还是先去认识一下军需官娜雅娜。她就在镇屋里，一边查看报告，一边统筹我们当前面临的各种局势。期待再见到你，愿艾露恩赐福于你。",
  },
  [26204] = {
    ["T"] = "灰雾威胁",
    ["O"] = "为比尔·惠兰杀死奥伯丁南边的灰雾鱼人。",
    ["D"] = "我以前住在西部荒野，可自从金海岸采石场附近的海岸被鱼人占据以后，我就丢下那块地跑了。我一路逃到了黑海岸，本以为终于能把那些滑腻混账从记忆里赶出去。可根本没用，$C！就在镇子南边的海岸线上，这里也到处都是鱼人！\n\n如果你还有一点同情心，就趁它们还没壮大到能吞没我们的地步之前，把它们清理掉吧。我在噩梦里都能听见它们的叫声……",
  },
  [26205] = {
    ["T"] = "灰雾威胁",
    ["O"] = "为奥伯丁的比尔·惠兰杀死黑海岸南部海岸线上的灰雾鱼人。",
    ["D"] = "这帮祸害一天不除，$C，我就一天睡不安稳，所以我又沿着海岸往更南边走了一段。你能相信吗？黑海岸最南端的海边，竟然还有更厉害的鱼人！\n\n它们一定是从什么地方冒出来的。我打算去查清楚，而你来替我解决它们带来的威胁。\n\n你会替我处理好这件事，对吧？",
  },
  [26206] = {
    ["T"] = "滩须",
    ["O"] = "杀死滩须，然后回到奥伯丁的比尔·惠兰那里。",
    ["D"] = "西部荒野的那些鱼人或许也有个头领——只是我当时没敢留下来查清楚。可黑海岸这边的鱼人，肯定有。\n\n沿着海岸一路往南走，快到灰谷时，你会看见一头幼年的海巨人。那怪物就是这场鱼人入侵的幕后黑手！必须把它干掉，不然我们迟早会被它那支滑腻腻的大军淹没！",
  },
  [26207] = {
    ["T"] = "通缉：雾鳍",
    ["O"] = "找到并杀死在亚米萨兰废墟以东深海游荡的海兽“雾鳍”，然后到奥伯丁的哨兵格琳达·纳尔希娅那里领取赏金。",
    ["D"] = "注意！\n\n现悬赏取名为“雾鳍”的海兽性命。该生物近来多次袭击附近渔船，至少已造成两名渔夫丧生。\n\n据悉，雾鳍常在亚米萨兰废墟以东的深水边缘徘徊。完成悬赏者请前往奥伯丁，向哨兵格琳达·纳尔希娅领取报酬。\n\n奥伯丁村议会",
  },
  [26208] = {
    ["T"] = "通缉：灰牙",
    ["O"] = "找到并杀死那只名叫“灰牙”的熊，然后到奥伯丁的哨兵格琳达·纳尔希娅那里领取赏金。",
    ["D"] = "注意！\n\n现悬赏取名为“灰牙”的熊的性命。南边靠近灰谷边界的黑木洞穴中，黑木熊怪引来了一头灰谷的熊。我们必须在它彻底沦为黑木控制下的怪物之前，先把这头年轻的熊除掉。\n\n完成悬赏者请前往奥伯丁，向哨兵格琳达·纳尔希娅领取报酬。\n\n奥伯丁村议会",
  },
  [26271] = {
    ["T"] = "古代宝石切割",
    ["O"] = "坠星村的埃莉诺·月辉要你从冬泉谷较大的上层精灵废墟中找回一套上层精灵工匠工具。",
    ["D"] = "你好啊，希望你喜欢冬泉谷！我从阴郁的黑海岸来，特别喜欢这里干燥的空气。你是冒险者，对吧？\n\n我是个珠宝学徒，来这里是为了研究这一带到处可见的漂亮水晶。传闻它们是从天上落下来的——村子的名字大概就是这么来的吧！可我带来的工具根本没法加工它们。相信我，我试过了！我最好的磨石都碎了……\n\n这些水晶又不是什么新东西，所以古代上层精灵肯定有办法切割它们，对吧？你能找到什么我都愿意付钱！凯斯利尔在南边，还有……泰雷萨兰在东北边，不过通往那里的路上有个凶巴巴的老太婆。",
  },
  [26415] = {
    ["T"] = "雕文符文",
    ["O"] = "与安威玛尔里的玛瑞克·斯托姆努尔谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这块符文转交给你。有空的时候读一读吧。我想这应该是法师训练师玛瑞克寄来的。看完以后，有空就到安威玛尔里面去找他。",
  },
  [26276] = {
    ["T"] = "行动：法拉克斯",
    ["O"] = "为暴风城的沉默的舒尼从黑石深渊的法拉克斯身上取回一个黑曜石核心。",
    ["D"] = "我们还在研究怎样高效地钻进诺莫瑞根，开始修复这座城市遭受的破坏。我们需要的是更多动力！ \n\n我有个表亲在黑石深渊的某个实验室里找到了一份工作。他们在那里制造由黑曜石核心驱动的魔像。我想研究其中一个核心，看看它能不能为我所用。 \n\n我表亲提到，有个叫法拉克斯的老旧魔像使用的就是黑曜石核心。它很快就要退役了——所以如果你能弄到它的核心，应该不会有人想念它！",
  },
  [26280] = {
    ["T"] = "误入歧途的学生",
    ["O"] = "杀死驯犬者格雷布玛尔，并为暴风城的奥菲尔·铁须取回他的猎人学校文凭。",
    ["D"] = "真没想到！$N，很抱歉，我需要你这样的冒险者帮忙。 \n\n我刚听说，我以前的一个学生被人看见在黑石深渊训练恶魔犬。他本该杀恶魔，而不是跟它们混在一起！ \n\n我想撤销我颁给他的文凭——他叫格雷布玛尔——可我们铁炉堡矮人在黑铁城市里可不受欢迎。你能替我把这个坏消息带过去，并把文凭取回来吗？",
  },
  [26281] = {
    ["T"] = "永恒之焰",
    ["O"] = "把永恒余烬带给暴风城的黑暗缚灵者加科因。",
    ["D"] = "检查这块余烬时，你注意到它仿佛是活的，在你手中一阵阵搏动。你记得听说过，黑暗缚灵者加科因有处理这类奇怪物件的经验，也许能进一步调查。\n\n你可以在暴风城法师区的已宰的羔羊旅店找到他。",
  },
  [26283] = {
    ["T"] = "阿度斯遗物",
    ["O"] = "在铁炉堡寻找一位博学的史学家。",
    ["D"] = "你面前是一尊陈旧风化的偶像，轮廓隐约像一个古老到难以理解的人类。这东西也许会引起博学史学家的兴趣——其中最著名的那些人可以在铁炉堡探险者大厅找到。",
  },
  [26315] = {
    ["T"] = "造餐仪式",
    ["O"] = "与暴风城法师区的高阶巫师安多玛斯谈一谈。",
    ["D"] = "你好，$N。你的训练已经让你变得强大，我相信自己已经没多少能教你的了。我猜你已经厌倦了为盟友召唤食物和饮料，对吧？如果我没猜错，你应该去暴风城找高阶巫师安多玛斯谈谈。我相信他知道更好的办法。",
  },
  [26321] = {
    ["T"] = "未竟之事",
    ["O"] = "从托尔巴拉德岛上找回丽贝卡·马丁遗失的传家宝。",
    ["D"] = "你——对，就是你！冒险者！也许你会听我说！\n\n我已经在暴风要塞向各路有权势的人请愿了好几个星期，可他们根本不理会我的请求。第二次战争以前，我的家人曾住在托尔巴拉德岛上。他们大多死在那里，但我的一个叔叔逃了出来。他临终前告诉我，家里一件珍贵的传家宝藏在岛上一个安全的地方。可现在有传言说海盗出现在托尔巴拉德了！他们就是冲着那宝物去的，我敢肯定。\n\n听着，$C，我急需有人去岛上把那件宝物找回来。拿着这把钥匙！它能打开藏有宝物的暗格。求你了，把我家族的遗产还给我吧！",
  },
  [26322] = {
    ["T"] = "未竟之事",
    ["O"] = "把遗失的传家宝还给暴风城的丽贝卡·马丁。",
    ["D"] = "她给你的钥匙似乎打不开暗格里的小锁箱。你唯一能做的，就是把锁箱带回给丽贝卡·马丁，希望里面装着她正在寻找的宝物。",
  },
  [26334] = {
    ["T"] = "以王国换船",
    ["O"] = "取得维克建造自己的船所需的工具。",
    ["D"] = "我可不能只靠双手造船！我需要合适的工具来组装这些部件，而我要你替我把它们弄来。因为自从你上次来以后，我把这段时间都花在幻想奶酪和晒黑皮肤上了，根本没学游泳。梦想很重要！它能让人坚持下去。再说了，你见过几个晒黑的侏儒？我金灿灿的皮肤肯定会引起轰动。\n\n总之，我需要一把铁匠之锤、一把扳手、50把螺栓，以及一把侏儒尺寸的线锯。技艺娴熟的工程师能帮你解决其中几样，但线锯只来自一个地方——诺莫瑞根！",
  },
  [26336] = {
    ["T"] = "斯特维尔的复仇",
    ["O"] = "杀死洛林·雷姆卡。",
    ["D"] = "我希望自己能依靠司法制度给予合适的惩罚，但暴风城的领袖们几乎不可能关心多年前发生在洛丹伦的罪行。  \n\n我的父亲不会赞同我想为他复仇。他甚至让我发誓，如果行动出了差错，绝不亲手伤害那些蠢货。有个办法能让我遵守誓言的字面意思，也让我的良心得以安宁。你必须成为我的复仇之手。如果你愿意，我会告诉你想知道的事。\n\n洛林·雷姆卡必须死。血债要用血来偿。",
  },
  [26338] = {
    ["T"] = "巴拉丁监狱可能陷落",
    ["O"] = "在军情七处找一个能告诉你巴拉丁监狱现状的人。",
    ["D"] = "身为暴风城海军大将，我会收到各种关于公海事件和阴谋诡计的报告。最近，托尔巴拉德岛上的堡垒传来一份令人不安的报告。海盗也许已经攻占了那座旧肯瑞托监狱。\n\n眼下这个传言还没有证实。我需要有人前往托尔巴拉德评估情况。你看起来很能干——联盟需要你，冒险者。\n\n出发前先去一趟军情七处。他们也许掌握着更多情报。",
  },
  [26343] = {
    ["T"] = "献给我曾爱过的恶魔",
    ["O"] = "进入托尔巴拉德岛上的巴拉丁监狱，杀死莫鲁姆斯和达克玛尔。",
    ["D"] = "你好，$C。如果你是来找秘密差事的，我可以向你保证，你来对地方了。\n\n我听说巴拉丁监狱那座岛上监狱发生了一次小规模越狱。那里关着几个囚犯，我真的不希望他们逃出来。他们很可能会来找我，而我可不想让这种混乱波及暴风城。\n\n如果你不介意去阿拉希高地的法迪尔海湾跑一趟，再搭船前往托尔巴拉德，我会让你觉得这趟值得——只要你确保莫鲁姆斯和达克玛尔永远离不开那座岛。",
  },
  [26350] = {
    ["T"] = "又有好消息",
    ["O"] = "与铁炉堡探险者大厅的史学家卡尼克谈一谈。",
    ["D"] = "我会着手破译卡莱塔卡的讯息，不过你离开时，探险者协会的其他成员在解读奥丹姆石板位置方面取得了突破。\n\n如果你想了解更多，就去和史学家卡尼克谈谈。",
  },
  [26365] = {
    ["T"] = "战斗号召：希尔斯布莱德丘陵",
    ["O"] = "在希尔斯布莱德丘陵找到并杀死5名部落成员。",
    ["D"] = "希尔斯布莱德丘陵属于联盟，我们必须不断证明这一点。追猎部落成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26366] = {
    ["T"] = "战斗号召：希尔斯布莱德丘陵",
    ["O"] = "在希尔斯布莱德丘陵找到并杀死5名联盟成员。",
    ["D"] = "希尔斯布莱德丘陵属于部落，我们必须不断证明这一点。追猎联盟成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26369] = {
    ["T"] = "战斗号召：奥特兰克山脉",
    ["O"] = "在奥特兰克山脉找到并杀死5名部落成员。",
    ["D"] = "奥特兰克山脉属于联盟，我们必须不断证明这一点。追猎部落成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26370] = {
    ["T"] = "战斗号召：奥特兰克山脉",
    ["O"] = "在奥特兰克山脉找到并杀死5名联盟成员。",
    ["D"] = "奥特兰克山脉属于部落，我们必须不断证明这一点。追猎联盟成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26468] = {
    ["T"] = "未能找回的人",
    ["O"] = "在艾萨拉找到地平线斥候。",
    ["D"] = "嗯。不，除了你之外，我最近没有任何知名圣骑士抵达棘齿城的记录。我本来在等一艘客船一周前抵达，可它已经误点了；也许你要找的圣骑士就在船上。\n\n那艘船走的是北方海路，从米奈希尔前往艾萨拉南部海岸，再向南去棘齿城。艾萨拉南部海岸是片蛮荒之地。如果他们出了什么事，可能会在那里下锚。这就是我能告诉你的全部。",
  },
  [26478] = {
    ["T"] = "深地符文",
    ["O"] = "阅读深地符文，然后与寒脊山谷的乌尔凡·壮辫谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这块符文转交给你。有空的时候读一读吧。我想这应该是萨满祭司训练师乌尔凡寄来的。看完以后，有空就到安威玛尔里面去找他。",
  },
  [26480] = {
    ["T"] = "大地的召唤",
    ["O"] = "把2碗魔精交给安威玛尔的乌尔凡·壮辫。",
    ["D"] = "时候到了，年轻的$c。你的身躯已足够强健，精神也如大地般坚韧。既然你选择了萨满之路，就说明你在尚未证明自己之前，便已拥有了智慧。\n\n大地元素将指引你的命运；若你已经准备好，它也会成为你的一部分。但你必须亲自站在大地面前。只要你准备好了，就会看见那些只有萨满才能看见的东西。\n\n去西南边寻找霜鬃巨魔幼崽，从他们身上取回两碗魔精。回来以后，我们再谈你的未来。",
  },
  [26482] = {
    ["T"] = "大地的召唤",
    ["O"] = "把粗石英交给安威玛尔的乌尔凡·壮辫。",
    ["D"] = "把这块粗石英带回去交给乌尔凡·壮辫，作为我们已经相见的证明。他会为你制作一根图腾，而这块小石英就是那图腾的核心。它看起来也许很小，但你很快就会明白，大小并不重要——即使是最微小的东西，也可能比群山更加恒久。\n\n耐心些，$N。保持坚强，并追寻智慧。这正是大地向你索求的东西。终有一日，你将与大地融为一体——尊重它，它也会尊重你。",
  },
  [26483] = {
    ["T"] = "火焰的召唤",
    ["O"] = "在丹莫罗南门哨岗找到奥格恩·强眉。",
    ["D"] = "火焰与你同在，$n。我看得出你已经精通大地之道，而我想，你已经准备好去见奥格恩了。\n\n他目前正在丹莫罗四处勘查，最后一次现身是在南门哨岗。他在元素之道上造诣很深，如果你觉得自己准备好了，他就能教你火焰之道。\n\n他很容易找，就在冻石农场以东。只是别走得太远，一头闯进荒芜之地去了！",
  },
  [26484] = {
    ["T"] = "火焰的召唤",
    ["O"] = "把沉睡火焰的火炬交给洛克莫丹的朱尔杜格斯·火语。",
    ["D"] = "你已经足够强大，可以驾驭火焰图腾，但这并不代表你已经真正准备好了。\n\n在洛克莫丹塞尔萨玛南边，你会发现一条通往洛克湖高峰之一的隐秘小径；沿途立着萨满石作为标记。找到通往山顶的路，你就会见到我们的圣地之一，由朱尔杜格斯·火语看守——那便是禁锢之焰神龛。\n\n把这支火炬带给他——它象征着你正尝试驯服火焰。再把它点燃后从神龛的火盆旁带回来交给我，我就会确保你获得火焰图腾。",
  },
  [26485] = {
    ["T"] = "火焰的召唤",
    ["O"] = "把1份火焰焦油和1个药剂袋交给洛克莫丹的朱尔杜格斯·火语。",
    ["D"] = "但你来这里不是为了听一堂历史课，对吧？你是为永恒火焰和火焰图腾而来的。\n\n第一步，是制作一份灵契，让你与火焰相连。\n\n如果你能给我带来两样东西，我就能为你制作火焰灵契。第一样是火焰焦油，这东西并不罕见，碎石怪斥候通常会带着它。他们就在这里南边和西北边一带出没。\n\n第二样会更危险些：从黑铁成员身上取一个药剂袋来。你可以在丹莫罗东南方的铁环营地找到他们。",
  },
  [26487] = {
    ["T"] = "火焰的召唤",
    ["O"] = "把永恒火炬交给丹莫罗南门哨岗的奥格恩·强眉。",
    ["D"] = "你把火炬牢牢握在手中，转身离开火盆，眺望着整个洛克莫丹。随着风势渐起，你感到一阵兴奋牵动着自己的灵魂，火焰也被吹得猛烈跳动起来。\n\n你沿着道路启程，返回南门哨岗，去寻找奥格恩·强眉。",
  },
  [26488] = {
    ["T"] = "水之召唤",
    ["O"] = "在湿地找到吉尔娜·福酿。",
    ["D"] = "毋庸置疑，水存在于你的未来之中。我看得出你已经深谙火焰之道，而现在，我认为你已经准备好去和吉尔娜谈谈了。\n\n吉尔娜住在米奈希尔港西南方的湿地海岸边，你不会错过她——找那座房子和码头，抬头还能看见她威风的狮鹫在上方飞翔。\n\n她深谙元素之道，也能教你水之道……前提是你觉得自己已经准备好了。小心附近徘徊的鱼人，它们已经拥抱了水，并声称水属于它们。",
  },
  [26489] = {
    ["T"] = "水之召唤",
    ["O"] = "在吉尔娜码头下方的裂隙处装满空的棕色水囊，然后回到湿地的她那里。",
    ["D"] = "若想从我这里获得领悟与灵契，你必须只寻找最纯净形态的水。当你替我取来这些样本时，留意周围的一切。观察那些依赖水、守护水的生物。看看水如何影响森林与沙漠。见证这维系生命的物质，也会迫使生物夺取生命。\n\n我们先从一件简单的事开始：就在这里西北方的水下，有一道裂隙正把珍贵的天然泉水渗入海中。用这个水囊装满那里的泉水，然后带回来给我。",
  },

  [26491] = {
    ["T"] = "水之召唤",
    ["O"] = "在乌鸦岭的水井中装满空的蓝色水囊，然后回到湿地的吉尔娜那里。",
    ["D"] = "很久以前，我跟随几名同伴深入暮色森林。我们击退了那里游荡的一些顽强僵尸，最终来到一个尚未被僵尸占据的小聚落：乌鸦岭。\n\n我在那里发现了一件极为奇特的事：聚落中央有一口小井，井里是新鲜的泉水。我不确定附近镇上的居民是否意识到它的价值——那是在亵渎之海中残存的一点神圣遗迹。\n\n用这个水囊给我带一份那里的水样回来。",
  },
  [26492] = {
    ["T"] = "水之召唤",
    ["O"] = "击败腐化的水之显灵，并将腐化显灵的护腕与剩余的至纯水滴一起放到黑海岸泉涌祭坛的火盆上。",
    ["D"] = "在黑海岸东北方海上的一座小岛上，你会找到一处已被邪能腐蚀的神龛。那里的灵魂已不再与我们的族人交谈，因此你必须亲手击败那显现之灵，并净化那片水池。\n\n沿着道路一路向北，前往那处水池。击败那元素生物，取下它的护腕，再把它与吉尔娜药剂剩余的水滴一同放到火盆上。这个仪式应该足以召来一个纯净的灵魂，与你交谈。\n\n把任务完成的证明带回来，我就会把图腾赐给你。",
  },
  [26493] = {
    ["T"] = "水之召唤",
    ["O"] = "与黑海岸的小型水之显灵交谈。",
    ["D"] = "当你完成咒语时，光芒骤然迸发。水滴落入火焰的声响已经消失，你的感官也被彻底吞没，四周那些腐化的灵体在这一瞬间尽数湮灭。",
  },
  [26494] = {
    ["T"] = "水之召唤",
    ["O"] = "把水之碎片带给湿地的吉尔娜·福酿。",
    ["D"] = "带走碎片。带走碎片，赋予生命。\n\n赋予生命，然后理解。理解水即生命……腐化会阻断生命。\n\n你以水的力量守护生命，并赋予生命。",
  },
  [26498] = {
    ["T"] = "献给艾莉森的花",
    ["O"] = "从奥特兰克山脉收集8株霜蓟，并把它们放在南海镇墓地中艾莉森·蒙特克莱尔的坟墓上。",
    ["D"] = "向你致意，陌生人。你是要路过南海镇吗？如果是的话，我想请你帮个忙。\n\n战争之前，我爱着一个名叫艾莉森·蒙特克莱尔的姑娘。后来我出海了，天灾也来了。等我回到家时，我找到了艾莉森。她被埋在南海镇的墓地里。\n\n我无法再强迫自己去她的墓前，但我想纪念她。如果你愿意从奥特兰克山脉收集一些霜蓟，并把它们放在她的墓上，我会很感激。",
  },
  [26499] = {
    ["T"] = "魔法物资",
    ["O"] = "与达拉然召唤师交谈以取得开启符文，然后用它们打开达拉然周围魔法封印的保险箱，收集里面的魔法物资。把30份魔法物资带给奥特兰克山脉达拉然附近的大法师安斯雷姆·鲁因维沃尔。",
    ["D"] = "所以你想帮忙？我正好知道一件事！\n\n如你所见，在我们围绕达拉然架起的魔法穹顶外，还有一些废弃建筑。在部分废墟里，你会找到被魔法封印的容器。这些容器的奥术锁可以用开启符文打开。\n\n我要你去和这一带的达拉然召唤师谈谈，请他们借出开启符文。然后搜查箱子，收集里面的魔法物资。小心些——有些箱子可能被施了魔法，会召唤守卫。",
  },
  [26500] = {
    ["T"] = "奇怪的典籍",
    ["O"] = "把死灵法术典籍带给暴风城港口的温德尔·火辉。",
    ["D"] = "你收集来的那堆杂物里，我看见了一件令人不安的东西。这是一本死灵法术典籍，而死灵法术是禁忌魔法，它的实践导致了我们的城市和洛丹伦的陷落。我想你大概不记得这是从哪户人家拿来的了……？\n\n好在这本典籍上标有读者结界。我知道你一定已经听腻了结界和魔法防御，但请再听我解释一次。这个结界会扰乱典籍中的文字，只有预定读者才能看懂。我们可以辨认出是谁施加了这道结界，也就能知道这本典籍曾属于谁。\n\n把这本典籍带给暴风城的温德尔·火辉。他喜欢待在港口，靠近最南边的码头。",
  },
  [26501] = {
    ["T"] = "奇怪的典籍",
    ["O"] = "把死灵法术典籍带回奥特兰克山脉达拉然附近的大法师安斯雷姆·鲁因维沃尔那里。",
    ["D"] = "轰砰啪！就是这么简单！你是不是以为我会需要某种只有鱼人腋窝里才偶尔能找到的魔法试剂？并没有！这只是个非常简单的法术。真的！这本典籍保护得不怎么样。\n\n总之，这本典籍属于一个叫阿曼·嫩斯托克的人！我完全不知道那是谁。希望大法师知道。把它带回去给他，也替我问声好。",
  },
  [26502] = {
    ["T"] = "珍本书籍",
    ["O"] = "杀死奥特兰克废墟中的塔尔格和戈洛姆斯，取回他们可能持有的任何书籍。然后回到南海镇的博学者迪布斯那里。",
    ["D"] = "奥特兰克王国并不以学术研究闻名，但奥特兰克城的图书馆确实藏有几本珍稀典籍。如今食人魔占据了城市废墟，我想知道那些典籍是否还能找回来……\n\n食人魔喜欢收集他们认为有价值的书，就算他们自己根本不会读。食人魔首领会收集镀金封面的典籍，尤其是配有漂亮插图的那种。杀掉他们，也许能让我们找回几件这些失落宝物。",
  },
  [26503] = {
    ["T"] = "珍本书籍",
    ["O"] = "杀死奥特兰克废墟中的玛格索尔，从他那里取得《奥特兰克的黎明时代》，然后回到南海镇的博学者迪布斯那里。",
    ["D"] = "有一本特定的典籍是我希望你找回来的，而且我确信它一定还在废墟里。那本书名叫《奥特兰克的黎明时代》，是奥特兰克部族建立王国并加入联盟之前唯一已知的历史。它装订在金线封面里，所以我确信食人魔一定会把它当成宝物。 \n\n也许他们那个名叫玛格索尔的粗暴首领正占有着它？你能说服他交出来吗？",
  },
  [26504] = {
    ["T"] = "辛迪加文件",
    ["O"] = "搜查索菲拉高地和柯兰之匕的辛迪加营地，寻找任何能揭示辛迪加计划的文件。",
    ["D"] = "辛迪加刺杀南海镇前任镇长，是他们破坏希尔斯布莱德稳定、让影响力渗透进来的大胆举动。为了我自己的安全，也为了南海镇其他居民的安全，我们必须更了解他们的计划。\n\n如果你本来就在猎杀辛迪加成员，就顺便搜查他们的营地，看看有没有任何文件能让我们稍微窥见他们在谋划什么！",
  },
  [26505] = {
    ["T"] = "给拉文霍德的信",
    ["O"] = "把赫尼·马雷布镇长的信带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "我们知道自己已经除掉了辛迪加的不少贵族首领，但究竟是谁在统领这个组织，仍然是个谜。在我们砍掉辛迪加的头之前，南海镇都不会安全。\n\n该求援了。把这封信带给乔拉齐·拉文霍德公爵，他的庄园位于敦霍尔德城堡北边丘陵地带。乔拉齐曾是奥特兰克王国的贵族，应当和我们一样有兴趣铲除这些暴徒。",
  },
  [26540] = {
    ["T"] = "外来的威胁",
    ["O"] = "为希尔斯布莱德丘陵南海镇的列兵诺伊特杀死10个鱼人湖岸猎手和8个鱼人湖岸神谕者。",
    ["D"] = "虽然达拉然和安多哈尔在上次战争中被摧毁了，但幸存者仍要依靠我们供给食物和物资。这条宝贵的贸易联系绝不能受到威胁。\n\n我收到报告，说鱼人已经在洛丹米尔湖南岸，以及流经寒风营地的达隆米尔河沿岸建立了村落。过去，这些野兽本该由奥特兰克王国处理。如今防卫的责任落到了我们肩上。\n\n削减它们的数量，好让我们能保住贸易路线的安全。",
  },
  [26541] = {
    ["T"] = "外来的威胁",
    ["O"] = "为希尔斯布莱德丘陵南海镇的列兵诺伊特杀死10头雪人。",
    ["D"] = "搬进奥特兰克废墟的食人魔似乎和当地山地雪人相处融洽。这让我很担心，因为这些生物之间从来没有合作的历史。\n\n如果食人魔煽动雪人，它们也许也会开始袭击我们的商队。因此，先发制人，让它们畏惧联盟，才是谨慎之举。\n\n你会在奥特兰克山脉的无草洞附近找到大部分雪人，不过我听说它们也生活在奥特兰克废墟周围。",
  },
  [26542] = {
    ["T"] = "稀有品种",
    ["O"] = "从斯坦恩布莱德的苹果园收集6颗冬脆苹果种子，并把它们带给南海镇的尼玛。",
    ["D"] = "向你致意，旅人！希尔斯布莱德的农夫以苹果闻名。亮红苹果、金皮苹果和达拉然甜苹果都生长在我们本地的田地里。上次战争之前，奥特兰克山脉还种着另一种苹果，叫冬脆苹果。 \n\n天灾军团前往达拉然时，斯坦恩布莱德的苹果田被彻底摧毁了。但如果还有种子留存，我们就能重新种下冬脆苹果树。你愿意前往斯坦恩布莱德的果园，看看能不能找到种子吗？ \n\n小心些——斯坦恩布莱德现在由辛迪加控制。",
  },
  [26543] = {
    ["T"] = "西瓜潘趣酒",
    ["O"] = "从奥特兰克山脉的达伦德农场收集4个多汁西瓜，交给南海镇的尼玛。",
    ["D"] = "我们旅店供应的食物都来自本地农产。每年这个时候，我们通常都会收到希尔斯布莱德送来的西瓜，可我刚得知今年西瓜歉收，根本不会有货。这可是灾难，$N。没有西瓜，我就做不出我有名的西瓜潘趣酒！ \n\n前几晚有个鬼鬼祟祟的家伙来过旅店，还一直吐西瓜籽。我问他从哪弄来的，他说北边有个叫达伦德农场的地方正在种西瓜。你能去那里看看，替我弄些西瓜回来吗？只要最多汁的那种！",
  },
  [26544] = {
    ["T"] = "谁喜欢苹果？",
    ["O"] = "从斯坦恩布莱德的苹果园收集6颗冬脆苹果种子，并把它们带给塔伦米尔的杰森·勒米厄。",
    ["D"] = "哦看，又一个来塔伦米尔做客的$R。我知道，我知道，蘑菇并不是所有人最爱的开胃菜。我一直打算把菜单扩展到其他食物。也许你能帮我个忙？\n\n天灾军团前往达拉然时，斯坦恩布莱德的苹果田被彻底摧毁了。但如果还有种子留存，我们就能重新种下冬脆苹果树。你愿意前往斯坦恩布莱德的果园，看看能不能找到种子吗？\n\n小心些——斯坦恩布莱德现在由辛迪加控制。",
  },
  [26545] = {
    ["T"] = "谁喜欢西瓜？",
    ["O"] = "从奥特兰克山脉的达伦德农场收集4个多汁西瓜，交给塔伦米尔的杰森·勒米厄。",
    ["D"] = "我想也不是每个人都会喜欢苹果。也许这里还能种些别的、部落会喜欢的东西？\n\n我知道了——达伦德农场那边有一大片不错的西瓜地。$R都喜欢西瓜，对吧？好吧，给我弄几个回来！",
  },
  [26578] = {
    ["T"] = "一剂上好药水",
    ["O"] = "把10份浓缩水带给泉簧的德里兹尔。",
    ["D"] = "我清单上的下一种材料在阿拉希高地。具体来说，是东部禁锢法阵的水元素。它们体内含有一种强大的试剂，我要把它和你先前带来的核心结合起来。\n\n那些元素被杀死后，应该会化为浓缩水。我要你把这些东西带给我，好让我继续调制我的药水。\n\n你会在遥远的北方找到阿拉希高地，要经过洛克莫丹和湿地。小心点，$N，这是一段漫长而危险的旅程。",
  },
  [26600] = {
    ["T"] = "炼金术才是答案",
    ["O"] = "与守望堡法师塔内的尼娜·淡啤谈一谈。",
    ["D"] = "你见过塔上的尼娜了吗？她往来于这里和暮色森林之间，出售炼金补给。\n\n她告诉我，她真正热爱的其实是炼金术本身，只是对自己的成果缺乏信心。这正是请她尝试解决实际问题的好机会。\n\n你觉得呢，$N？能不能去请她帮忙，让这些东西变得能入口？另外，替我向她问声好！\n\n<伦格尔茨朝你和气地咧嘴一笑。>",
  },
  [26655] = {
    ["T"] = "不再止水",
    ["O"] = "在夜晚杀死赤脊山止水湖湖底的止水湖潜伏者，并收集它的雾气核心。",
    ["D"] = "你去过赤脊山吗？那地方不错。我和我的未婚妻以前住在那里。\n\n总之……到了夜里，湖水就会翻腾。有个巨大的怪物会从湖底翻起淤泥——就叫它入侵物种吧。我的错。它倒是不凶，可特别喜欢搅浑水。\n\n那东西身上有我制作这些雾石需要的东西。你何不去杀了它，把它的核心带给我？",
  },
  [26661] = {
