    ["D"] = "从这张巨魔羊皮纸上那些粗糙的图画来看，这似乎是某种针对铁炉堡机场的袭击计划。计划看上去像是要把巡山人引到冰面上去，好让攻城引擎无法追击，但你也不敢确定，因为你看不懂赞达利语。最好还是把这东西拿给凯尔西·钢火看看。",
