    ["O"] = "乘飞行器前往铁炉堡机场，然后与东边碉堡附近的吉尔达·雷酒谈一谈。",
    ["D"] = "你听说过铁炉堡机场吗，$R？我个人还是更喜欢狮鹫，不过我们矮人也以各种飞行机械闻名。第二次和第三次战争之后，我们失去了大部分飞行器，不过麦格尼国王已经下令修建一座强大的机场，好让我们重建这些机器。\n\n我绕了这么大个圈子，其实只是想问你一句：要不要免费去机场走一趟？像你这样的冒险者，应该能在那里帮上忙！",
