    ["D"] = "我被派到这里监视这些巨魔，确保他们别搞出什么名堂来。结果呢，$C，他们还真就在搞鬼。\n\n最让我意外的是，他们的高阶祭司——一个叫里卡里的巨魔——居然发现了我，还喊来卫兵围攻我。我好不容易才脱身，不过膝盖上也挨了狠狠一下。我需要你进去稍微削减一下他们的人手，但先别去招惹那个高阶祭司！",
