    ["O"] = "用任意火源点燃未点燃的火把，然后在瑞克瓦萨焚毁6份霜鬃军备。瑞克瓦萨里有一堆营火可供点火。",
    ["D"] = "瑞克瓦萨里的霜鬃巨魔正在为袭击机场做准备。他们把一批武器藏在村子四周的箱子里，我原本还以为那些箱子装的只是食物。结果根本不是——里面塞得全是武器！\n\n来，这是我临时给你做的火把。拿去他们的营火边，或者随便找个火源也行，把那些军备统统烧掉！",
