    ["D"] = "我们在卡拉诺斯打造了许多武器和护甲，还得把它们运往艾泽拉斯各地。我的兄弟格里姆纳尔原本就是负责其中一趟送货的，照理几天前就该回来了。\n\n有人说曾看见他经过霜鬃巨魔要塞，之后就再也没人见过他。你觉得会不会是巨魔抓走了他？我真希望不是……不过你能替我去看看吗？",
