    ["D"] = "$N，我有一件紧急任务要交给你。最近我们有些居民离奇失踪了。一开始大家并没太在意，可都过去好几个星期了，他们一个都没回来。\n\n自从这些失踪事件开始之后，霜鬃巨魔就在这里正西边建起了几处营地。我希望你去那里查看一下，看能不能找到我们的居民。",
