    ["D"] = "你感受到空气里的寒意了吗？就算站在火堆旁，我都觉得胡子快结冰了！我跟你说，这里的冬天一年比一年冷。\n\n要是能有些好兽皮，我就能给自己做件斗篷了。你愿意帮帮我吗？去西边的涌冰湖，替我弄些狼皮回来吧。",
