    ["D"] = "几天前下了一场大雪，农场的大门被吹坏了！我们那些宝贵的公羊跑丢了好多！我看见它们往南边跑了，可我根本拦不住。要是连卖的公羊都没有了，我还怎么赚钱？\n\n去南边的冻土岭找找看，看看能不能把我的公羊带回来。靠近它们，用我的套索骑着它们回农场！我一定会感激不尽！",
