    ["D"] = "欢迎回来！你是来学习更快的骑术，对吧？和上次一样，你那头山羊的费用已经有人替你付过了，不过训练费还得你自己出。很遗憾，更高级的训练可不便宜。\n\n学会骑术之后，就去围栏外面找维隆·冻石谈谈。他经营着这座农场，也负责出售山羊。要是你手头钱还不够，以后随时都可以再来。",
