    ["O"] = "向奥萨姆·铁角学习初级骑术，然后与丹莫罗的维隆·冻石谈一谈，领取你的山羊。",
    ["D"] = "你是来学怎么骑山羊的，是吗？巧得很，我正等着你呢！有位神秘的赞助者替你留下了一笔钱，正好够买一头普通山羊，而且收件人还写着你的名字，$N。不过对方没替你付训练费，所以很抱歉，这部分还是得照收。\n\n学会骑术之后，就去围栏外面找维隆·冻石谈谈。他经营着这座农场，也负责出售山羊。要是你手头钱还不够，之后再来也行。",
