    ["D"] = "欢迎回来。你是来学习更快的驾驶术，对吧？和上次一样，你那台机械陆行鸟的费用已经有人替你付过了，不过训练费还得你自己出。很遗憾，更高级的驾驶训练可不便宜。\n\n学会之后，就去旁边找我妹妹米利谈谈。机械陆行鸟是她制造和出售的。要是你手头钱还不够，以后随时都可以再来。",
