    ["D"] = "你是来学怎么驾驶机械陆行鸟的，是吗？巧得很，我正等着你呢！有位神秘的赞助者替你留下了一笔钱，正好够买一台学徒级机械陆行鸟，而且收件人还写着你的名字，$N。不过对方没替你付训练费，所以很抱歉，这部分还是得照收。\n\n学会之后，就去旁边找我妹妹米利谈谈。机械陆行鸟是她制造和出售的。要是你手头钱还不够，之后再来也行。",
