    ["D"] = "下面那些该死的穴居人让我们的采矿作业彻底停摆了——偏偏就在我们快要有重大发现的时候！\n\n我们撤离矿洞时，我手下有个矿工急匆匆跑来找我，说他在矿井深处发现了几处不寻常的新矿脉。可惜，自从穴居人发起袭击之后，我就一直没机会去确认这件事。\n\n你看起来挺有一股拼劲。要是你既识矿，又乐意顺手宰几个穴居人，就替我把里面找到的怪矿石带一些回来吧。我一定会好好报答你。",
