    ["D"] = "我原本是来这里挖掘一些过往的历史，可那些该死的巨魔偏偏占据了我正准备开挖的洞穴！\n\n我可不是战士，不过你看起来倒像是能胜任这份差事的人。你能进洞里去，把你觉得有研究价值的东西带回来吗？陶罐、骨灰瓮、石板之类的都行。\n\n只要你肯帮忙，我一定不会亏待你：这次挖掘可是直接奉铁炉堡之命进行的！",
