  [27526] = {
    ["T"] = "阿鲁-塔利斯的传说",
    ["O"] = "把阿鲁-塔利斯研究材料箱交给达纳苏斯月神殿的泰兰德·语风。",
    ["D"] = "我想，眼下你已经帮了我所有能帮的忙。等我恢复过来，就能自己继续这项工作了。\n\n不过，请你最后再帮我一个忙。把这些岩芯样本、石板拓片和我的报告带回达纳苏斯，交给我的上级。他们一定会很想知道我们发现了什么。",
  },
  [27557] = {
    ["T"] = "温暖的澡水",
    ["O"] = "用冰火温泉的温水装满雷沃·霜翼的擦洗桶，然后用它给他的冬泉霜刃豹伙伴格莱希尔洗澡。",
    ["D"] = "我的伙伴格莱希尔是个精力旺盛的家伙。有时它玩耍和狩猎时会把皮毛弄得很脏，脏到连它自己都很难清理。你愿意帮我给它洗个澡吗？\n\n把这个桶带到冰火温泉，装满热水。趁水还温着赶快回来，用它给格莱希尔快速洗个澡。它也许会冲你低吼、挥爪，但我向你保证，它心里是感激的。",
  },
  [27539] = {
    ["T"] = "风暴将至",
    ["O"] = "把J.D.考利的报告交给达纳苏斯的格拉希娜·灵风。",
    ["D"] = "$N，我们不能把这个发现压下来不说！我正好知道该把消息送给谁——炼金师匹斯特苏格提过，他一直在替达纳苏斯的议员格拉希娜·灵风研究异种虫。把这份报告亲手交给她吧！她会知道该怎么做！",
  },
  [27588] = {
    ["T"] = "给医师迈莉的委托",
    ["O"] = "医师迈莉要你用炼金技能制作5瓶初级法力药水，并把订单交给丹莫罗卡拉诺斯的医师迈莉。",
    ["D"] = "噢，你好！看你护甲上沾着宁神花的痕迹，我就知道你是个炼金师！也许你能帮帮我？\n\n我在这里负责处理其他侏儒实验室里各种层出不穷的小意外，可有时候我自己的法力也会见底。要是你能替我做几瓶初级法力药水，我很乐意付你报酬，再额外送你一些补给！",
  },
  [27589] = {
    ["T"] = "给安古斯的委托",
    ["O"] = "医师迈莉要你用炼金技能制作5瓶弱效巨魔之血药水，并把订单交给丹莫罗卡拉诺斯南边营地里的安古斯。",
    ["D"] = "你知道吗，如果你还想继续做下去，这附近其实很缺炼金师。\n\n卡拉诺斯南边那支矮人迫击炮小队也总会遇上各种……小意外。还不至于严重到要用治疗药水——不过我敢说，要是你愿意接这份委托，他们一定会对几瓶弱效巨魔之血药水很感兴趣。",
  },
  [27590] = {
    ["T"] = "给月之女祭司阿玛拉的委托",
    ["O"] = "玛洛尼·刃叶要你用炼金技能制作5瓶狮王之力药剂，并把订单交给泰达希尔西行达纳苏斯道路上的月之女祭司阿玛拉。",
    ["D"] = "冒昧打扰，不过我注意到你似乎懂炼金。辛德拉手上的委托已经堆成山了，而她又太好说话，从不肯把人拒之门外。也许你愿意替她分担几份订单？\n\n月之女祭司阿玛拉替她手下的巡路者订了五瓶狮王之力药剂。要是你能把这些药剂做出来，就去西边通往达纳苏斯的路上找她。",
  },
  [27591] = {
    ["T"] = "给哨兵阿瑞尼亚·碎云的委托",
    ["O"] = "玛洛尼·刃叶要你用炼金技能制作5瓶初级活力药水，并把订单交给泰达希尔神谕林地的哨兵阿瑞尼亚·碎云。",
    ["D"] = "我真希望辛德拉能直接告诉别人她忙不过来了，不过我也明白她总想帮到每一个来求助的人。现在有一份优先级很高的委托，是神谕林地那位独自驻守的碎云哨兵发来的。要是你能做几瓶初级活力药水给她送去，就能帮辛德拉减轻不少负担。",
  },
  [27594] = {
    ["T"] = "给奥兰纳的委托",
    ["O"] = "奥兰纳要你用炼金技能制作5瓶智慧药剂，并把订单交给黑海岸古树之林的奥兰纳。",
    ["D"] = "每隔几个月，就会有朝圣者前往古树之林向奥努请教。他的智慧有时并不容易理解，所以我想备上一些智慧药剂，或许能帮那些朝圣者更好地领会他的话。要是你愿意替我做几瓶送来，我会很乐意拿一些实用补给作为答谢。",
  },
  [27595] = {
    ["T"] = "给考古学家埃弗里特的委托",
    ["O"] = "奥兰纳要你用炼金技能制作5瓶初级坚韧药剂，并把订单交给黑海岸雷姆塔维尔挖掘场的考古学家埃弗里特。",
    ["D"] = "前阵子有一队矮人从这里经过，他们正赶往一处名为雷姆塔维尔挖掘场的遗迹。我听说他们最近正被魔像的问题闹得头疼，所以就在想，几瓶初级坚韧药剂说不定能帮他们撑住场面。你不觉得值得去试试吗？",
  },
  [27596] = {
    ["T"] = "给瓦格·深水的委托",
    ["O"] = "加克要你用炼金技能制作5瓶水下呼吸药剂，并把订单交给洛克莫丹洛克湖岸边的瓦格·深水。",
    ["D"] = "向你致意，$C……或者我该叫你炼金师$N？\n\n我这边的委托已经堆到耳朵边了。说不定你愿意替我调几瓶药剂，帮我分担一点？\n\n住在洛克湖边的瓦格·深水想要一包水下呼吸药剂。听说他想跑到湖里去钓鱼。这可真是怪事……总之，你要是愿意帮这个忙，我会很感激。",
  },
  [27597] = {
    ["T"] = "给马雷克·铁心的委托",
    ["O"] = "加克要你用炼金技能制作5瓶速游药水，并把订单交给洛克莫丹远行者小屋的马雷克·铁心。",
    ["D"] = "我这儿有一份马雷克·铁心从远行者小屋送来的订单，要几瓶速游药水。他觉得自己是个鳄鱼猎手，想靠这些药水在水里追上那些野兽，大概就是这么回事。你有兴趣替我把这份差事接过去吗？",
  },
  [27598] = {
    ["T"] = "给守夜人多兹的委托",
    ["O"] = "指挥官阿尔泰娅·埃伯洛克要你用炼金技能制作5瓶治疗药水，并把订单交给暮色森林中部守夜人营地的守夜人多兹。",
    ["D"] = "$C，我听说你也是炼金师。我想代表守夜人订购一些治疗药水。请把它们送到暮色森林中部我们营地里的守夜人多兹那里。你能办到吗？",
  },
  [27599] = {
    ["T"] = "给格拉德·克劳雷的委托",
    ["O"] = "格拉德·克劳雷要你用炼金技能制作5瓶火焰之油，并把订单交给赤脊山湖畔镇的格拉德·克劳雷。",
    ["D"] = "哦……一位炼金师。我想你会欣赏我对毒药的兴趣。说到底，这和炼金术也不是完全不同的技艺。\n\n其实，我正能用上你的服务。我想调制一种带有灼热底味的毒药……能造成一点烧灼感的那种。如果你能替我制作一些火焰之油，我可以给你一些对日后制作有用的材料。",
  },
  [27638] = {
    ["T"] = "给雷杰德·麦酒的委托",
    ["O"] = "考根·锻石要你用锻造技能制作10块劣质砂轮，并把订单交给丹莫罗烈酒村的雷杰德·麦酒。",
    ["D"] = "你好，$C。我看得出你也是个铁匠。想不想替我们分担一点积压的订单？\n\n我需要有人打造一大批劣质砂轮，送去西边烈酒村的雷杰德·麦酒那里。他正拿这些东西捣鼓某种新酒。你有兴趣吗？",
  },
  [27639] = {
    ["T"] = "给矿场主管瑟斯丁的委托",
    ["O"] = "考根·锻石要你用锻造技能制作3把铜质钉锤，并把订单交给丹莫罗古博拉采掘场的矿场主管瑟斯丁。",
    ["D"] = "铁匠之间说句实话，我手上的活儿永远多得做不完。要是你愿意帮忙，我这里正好有一份来自东边古博拉采掘场矿场主管瑟斯丁的委托，要几把铜质钉锤。你觉得自己能替我做出来吗？",
  },
  [27601] = {
    ["T"] = "给凯特琳·格拉斯曼的委托",
    ["O"] = "凯特琳·格拉斯曼要你用炼金技能制作5瓶次级法力药水，并把订单交给湿地米奈希尔港的凯特琳·格拉斯曼。",
    ["D"] = "我不是炼金师……其实不算。但你也看得见，我身后这些冒泡的小瓶说明，我确实喜欢摆弄药水和药剂。\n\n我大多数调合物都以次级法力药水为基底，可现在全用完了！如果你愿意替我再做一些，我很乐意把我的一些补给分给你。",
  },
  [27640] = {
    ["T"] = "给梅里·织铁的委托",
    ["O"] = "雷妮·熔栎要你用锻造技能制作1面重铜盾牌和1件铜质链甲外衣，并把订单交给泰达希尔多兰纳尔的梅里·织铁。",
    ["D"] = "伊露恩保佑，$C。我恐怕没工夫闲聊——自从我们开了这间工坊，涌来的订单就没停过。\n\n不过看起来，你在铁砧前也挺有天分。要是你愿意帮忙，就替我做1面重铜盾牌和1件铜质链甲外衣，送给多兰纳尔的护甲商梅里·织铁。",
  },
  [27641] = {
    ["T"] = "给艾瑞拉斯·琥珀的委托",
    ["O"] = "雷妮·熔栎要你用锻造技能制作2枚符文铜戒指，并把订单交给泰达希尔鲁瑟兰村的艾瑞拉斯·琥珀。",
    ["D"] = "我这里有一份来自艾瑞拉斯·琥珀的订单，也许你会愿意替我完成。他想要一对符文铜戒指。等你做好以后，到泰达希尔树根下的鲁瑟兰村去找他就行。穿过银行后面的传送门就能到那儿。",
  },
  [27651] = {
    ["T"] = "给冷面长须的委托",
    ["O"] = "布拉恩玛尔要你用锻造技能制作3副镀银青铜护手，并把订单交给湿地北部丹莫德的冷面长须。",
    ["D"] = "我的表兄长须是丹莫德那边一支民兵队的一员，他们正抵挡黑铁矮人。他为手下要了三副镀银青铜护手，可塞拉摩来的订单太多，我一直没时间打造。你看着像个能干的铁匠——要是你能完成这份订单并送过去，我个人会非常感激你。",
  },
  [27910] = {
    ["T"] = "血与荣誉的羁绊",
    ["O"] = "前往卡拉诺斯附近的墓地，使用仪式熏香来祭奠你的祖先。",
    ["D"] = "你想更多地了解我的族人？我想我和其他人比起来，至少算得上是个不错的老师，而且也更愿意开口。反正我哪儿也去不了。\n\n如果你真想理解我的族人，就必须先明白，荣誉是我们言语、行为与举止的根基。我们的氏族由漫长岁月里的荣耀事迹维系在一起。我们知道，自己的所作所为代表的不只是自己。\n\n向我证明你如何敬重他人。去你祖先安眠之地使用这份仪式熏香，然后再回来见我。",
  },
  [27912] = {
    ["T"] = "血与荣耀的羁绊",
    ["O"] = "前往暮色森林乌鸦岭墓地中的雕像旁，使用祭仪熏香祭奠你的祖先。",
    ["D"] = "你想进一步了解我的族人？我想我和任何人一样适合教你，而且比大多数人更愿意。毕竟，我哪儿也去不了。\n\n如果你真想理解我的族人，就必须先明白，荣耀是你的言语、行为与举止的根基。我们的氏族由漫长历史中的荣耀事迹维系。我们明白，自己的行动所反映的不只是自己。\n\n让我看看你如何尊敬他人。在你祖先的安息之地使用这份祭仪熏香，然后回来找我。",
  },
  [27586] = {
    ["T"] = "给达希嬷嬷的委托",
    ["O"] = "炼金师玛洛莉要你用炼金技能制作5瓶初级治疗药水，并把订单交给艾尔文森林闪金镇的达希嬷嬷。",
    ["D"] = "我看你是个初出茅庐的炼金师！也许你能帮我个忙。我现在手头的活已经多到做不完，而闪金镇的达希嬷嬷一直在为受伤矿工索要一些初级治疗药水。我还有暴风城卫兵的重要工作要完成，不过如果你愿意帮忙，就制作五瓶那种药水，并送给达希嬷嬷。",
  },
  [27644] = {
    ["T"] = "给奥兰纳的委托",
    ["O"] = "德尔弗拉姆·燧须要你用锻造技能制作3块粗制磨刀石和3块粗制平衡石，并把订单交给南边黑海岸古树之林的奥兰纳。",
    ["D"] = "啊，我一眼就能看出你也是个铁匠！说到离这儿不远，古树之林那边的奥兰纳刚捎来一张字条，说她那儿又缺磨刀石和配重石了。我一直抽不出空处理她的订单，不过要是你愿意在镇上顺手干点手艺活，我可很乐意把这份委托交给你。",
  },
  [27645] = {
    ["T"] = "给洛南·金叶的委托",
    ["O"] = "迪尔弗拉姆·火须要你用锻造技能制作1条暗影石坠饰和1件协调铜质护腿，并把订单交给灰谷边界金叶隐居地的洛南·金叶。",
    ["D"] = "黑海岸还有更远的地方，都有不少活儿等着像你这样有闯劲的年轻铁匠。瞧，我这里正好有一份来自洛南·金叶的公开订单——那家伙是个隐士，住在南边很远、紧挨灰谷边界的路边。要是你能做出暗影石坠饰和协调铜质护腿来完成这份订单，那可就替我卸下一副担子了。",
  },
  [27646] = {
    ["T"] = "给索瓦尔德·深炉的委托",
    ["O"] = "莫尔汉·铜舌要你用锻造技能制作4把白银万能钥匙，并把订单交给洛克莫丹东南部国王谷的索瓦尔德·深炉。",
    ["D"] = "向你致意，冒险者……原来还是位铁匠！我正需要你的手艺。\n\n驻守国王谷据点的索瓦尔德·深炉最近找到了一批旧锁箱，不过他不想靠蛮力把它们砸开。要是你能替他做几把白银万能钥匙，我相信他一定会好好酬谢你的手艺。",
  },
  [27647] = {
    ["T"] = "给巡山人卡尔·雷矛的委托",
    ["O"] = "莫尔汉·铜舌要你用锻造技能制作2把厚重的战斧，并把订单交给洛克莫丹北部奥加兹岗哨的巡山人卡尔·雷矛。",
    ["D"] = "想不想接下一份来自洛克莫丹最负盛名巡山人之一的委托？驻守奥加兹岗哨的巡山人卡尔·雷矛正需要几把斧子分给他的新兵。要是你能做出两把厚重的战斧并送过去，他一定会非常满意。",
  },
  [27648] = {
    ["T"] = "给基特斯的委托",
    ["O"] = "加文·纳尔特里要你用锻造技能制作1把青铜重锤和2块重砂轮，并把订单交给暮色森林西部乌鸦岭的基特斯。",
    ["D"] = "嘿，你是镇上新来的铁匠吗？我手头守夜人的订单已经堆得够多了，所以一直没顾上这个普通人的订单。如果你愿意帮我，就做一把青铜重锤和几块重砂轮，送到乌鸦岭去。下单的那个人最近一直在那边晃悠。",
  },
  [27649] = {
    ["T"] = "给卫兵帕克的委托",
    ["O"] = "弗纳·奥斯古要你用锻造技能制作1面纯银盾牌，并把订单交给赤脊山东部三角路口的卫兵帕克。",
    ["D"] = "你该不会正好是铁匠吧？哦，你还真是！我需要你帮忙。\n\n自从兽人搬来以后，我们上一位铁匠就直接走人了，卫兵们只能拿剩下的破烂凑合。我想委托人给卫兵帕克打造一面纯银盾牌，可我已经不得不向闪金镇请求护甲了，那东西要等很久才能送到。要是你能替我打造并送去这面盾牌，我会确保帕克拿补给品作为回报。",
  },
  [27884] = {
    ["T"] = "生存意志",
    ["O"] = "与暴风城光明大教堂的大主教本尼迪塔斯谈一谈。",
    ["D"] = "向你致意，$N。我带来了大主教本尼迪塔斯的口信。他正在寻找一位有兴趣研究被遗忘者的人。我想你会想知道这件事。\n\n如果你有兴趣，就去暴风城的大教堂找他。",
  },
  [27887] = {
    ["T"] = "生存意志",
    ["O"] = "向暴风城光明大教堂的克劳雷修士报到。",
    ["D"] = "我大概不该知道这件事，$N，但血色十字军把一名前洛丹伦居民带到了暴风城，大主教正把他囚禁在大教堂地下室。那个可怜人仍是天灾军团的一员，但还没有变成食尸鬼。也许这正是我们需要的区别？\n\n去大教堂找克劳雷修士谈谈，看看他是否允许我们在囚犯身上测试心灵隔绝水晶。如果成功，我们也许就能治好他！",
  },
  [27889] = {
    ["T"] = "生存意志",
    ["O"] = "与暴风城的档案员罗伊谈谈。",
    ["D"] = "我不认为这次实验完全白费。我会把大主教需要知道的一切转告给他。\n\n如果你想继续拓展在这里学到的东西，我想你可以去暴风城找档案员罗伊谈谈。\n\n在这之后，我们之间的人情就算两清了。",
  },
  [27903] = {
    ["T"] = "大地母亲的赐福",
    ["O"] = "与达纳苏斯月神殿的历史学家迪米特雷斯库谈一谈。",
    ["D"] = "凭你的作为，你已经有资格请求大地母亲的赐福了。我想，你们族里也有少数人懂得该如何呼唤她的力量。若你想进一步了解，就去达纳苏斯的月神殿找历史学家迪米特雷斯库谈谈。\n\n再会了，$N。能与一位$R和平相见，我很高兴。",
  },
  [27960] = {
    ["T"] = "碎矛节庆",
    ["O"] = "与达纳苏斯月神殿的使者克拉尔冯谈一谈。",
    ["D"] = "有个令人振奋的消息！黑海岸那支一向深居简出的碎矛巨魔正在举办节庆，而且破天荒地欢迎外来者前去观礼并参与他们的风俗。这可是难得的机会，让你能在不必担心脑袋挨斧头的情况下观察巨魔。\n\n如果你有兴趣，就去达纳苏斯月神殿找他们的使者吧。",
  },
  [27961] = {
    ["T"] = "碎矛节庆",
    ["O"] = "与奥格瑞玛精神谷的使者瓦尔克隆谈一谈。",
    ["D"] = "令人振奋的消息！黑海岸那支一向深居简出的碎矛巨魔正在举办节庆，而且破天荒地欢迎外来者前去观礼并参与他们的风俗。这可是难得的机会，让你能在不必担心脑袋挨斧头的情况下观察巨魔。\n\n如果你有兴趣，可以在奥格瑞玛的精神谷找到他们的使者。",
  },
  [27940] = {
    ["T"] = "智力的衡量",
    ["O"] = "与暴风城皇家图书馆的档案员罗伊谈谈。",
    ["D"] = "收工！你真是个小甜心，也帮了大忙。希望没太疼。\n\n随时回来再试一次，$N。只是别偷我的东西，听见了吗？\n\n我会把笔记汇编寄给我在暴风城的同事档案员罗伊。你想什么时候查阅都可以……磨炼心智之类的。\n\n现在出去吧。我还有活要干！",
  },
  [27947] = {
    ["T"] = "人类精神",
    ["O"] = "与暴风城旧城区军情七处的马迪亚斯·肖尔大师谈一谈。",
    ["D"] = "又见面了，$N。我听说你很喜欢奶酪——就像人类一样。\n\n马迪亚斯·肖尔大师已经放出消息，说他正在寻找一位特别的人替他办件事。事情和奶酪有关。也许就是你？\n\n你可以在暴风城旧城区的军情七处找到肖尔大师。",
  },
  [27948] = {
    ["T"] = "人类精神",
    ["O"] = "把20块符文布、1卷粗丝线和金色染料带给暴风城贸易区提亚斯奶酪坊的埃林·提亚斯。",
    ["D"] = "如果你愿意接下这份差事，就需要准备伪装用品。符文布、丝线，还有一种暴风城贵族特有的金色染料。前两样应该很容易弄到，但染料得从阿德尔伯特·佩里那里取得。佩里是迪菲亚的同伙，经营着花园区一家裁缝店作为掩护。除掉佩里，拿到染料……只要确保别被人看见。\n\n完成后，把这些用品带给贸易区的埃林·提亚斯。",
  },
  [27949] = {
    ["T"] = "人类精神",
    ["O"] = "品尝比托暴风城干酪、南怒河蓝纹奶酪和兽人奶酪，再用一瓶塞拉摩红酒送下。然后与暴风要塞里的泰莎·埃勒里安谈谈。",
    ["D"] = "要赢得那位贵族的信任，你得能自然地谈论当前的人类潮流和时尚。\n\n先从食物开始吧。我列了一张最上等人类奶酪的清单，这样你就能形成自己的喜好。顺便用我们最好的葡萄酒之一送下去也不错。你可以在城里的商店里品尝这些东西。之后，我想你应该去和泰莎·埃勒里安谈谈。\n\n很久以前，她也必须学习宫廷礼仪。",
  },
  [27950] = {
    ["T"] = "人类精神",
    ["O"] = "听泰莎·埃勒里安讲述她的故事，然后回到贸易区的埃林·提亚斯那里。",
    ["D"] = "埃林·提亚斯让你来找我？而且这和迪菲亚事件有关？我怀疑这其实并不是为了礼仪。他想让你明白自己为什么要做这件事。\n\n请原谅我，这是个漫长而至今仍令人痛苦的故事。但如果你愿意听，我会讲给你。",
  },
  [27951] = {
    ["T"] = "人类精神",
    ["O"] = "穿上华丽的暴风城宫廷长袍，然后与暴风要塞皇家画廊的法丁·莱斯科瓦女士谈谈。用任何必要手段从她那里取得迪菲亚成员名单。",
    ["D"] = "你将会见法丁·莱斯科瓦女士。她的父亲曾是迪菲亚的同情者，而她手中有一份前迪菲亚成员名单。她以为自己要见的是一位有意推动迪菲亚目标的代表。\n\n用你的政治眼光和高雅品味打动她，她应该会和平交出名单。但如果出了差错，就用任何必要手段取得它。",
  },
  [27952] = {
    ["T"] = "人类精神",
    ["O"] = "在暴风城寻找档案员罗伊。",
    ["D"] = "这些情报对我们清除王国内最后的迪菲亚残余会有极大帮助。你为暴风城效力良多，$N。请接受我的谢意。\n\n如果你以后还想再次拥抱人类精神，就去暴风城找档案员罗伊谈谈。",
  },
  [27953] = {
    ["T"] = "科技的魔法",
    ["O"] = "与湿地实验室里的韦林·巧簧谈一谈。",
    ["D"] = "向你致意，$C。一位侏儒发明家需要有人到他的工坊帮忙制作一台装置，那间工坊位于从洛克莫丹通往湿地的丹奥加兹路上。\n\n他需要像你这样能干的冒险者，而报酬就是让你保留那台原型装置。\n\n这里写着，你将能够获得类似暗夜精灵的能力——隐蔽、迅捷反应，还有……呃，吉奥斯——杰欧辛……啊，嗯。\n\n好吧，听起来确实很有意思。你想接这份活吗？",
  },
  [27957] = {
    ["T"] = "组装起来",
    ["O"] = "在湿地韦林·巧簧的实验室周围找回5个侏儒组件。",
    ["D"] = "真不敢相信，我们就快成功了，$N！我的梦想终于要实现了……！\n\n我相信你也想把能用的东西拿到手，所以让我们做最后的完善吧！我会开始摆放组件，但还需要你从工坊周围拿些工具和材料，才能把它们组装起来。\n\n愿意搭把手吗？为了这个东西，我几乎需要手头所有备用零件，所以翻找我的宝贝时别挑三拣四。请小心轻放！",
  },
  [27966] = {
    ["T"] = "返回达纳苏斯",
    ["O"] = "与达纳苏斯月神殿的历史学家迪米特雷斯库谈一谈。",
    ["D"] = "朋友，可别以为当个巨魔就只是会发怒而已。要是你还想多了解一些，我看达纳苏斯里倒是有人能跟你聊聊。\n\n使者克拉尔冯提到，有个叫迪米特雷斯库的迷人暗夜精灵，特别想了解我们的历史。你知道的，我们从前本是一族。\n\n不过那已经是很久以前的事了，久到大多数活着的人都不记得。\n\n<巫医哈尔德赫朝你眨了眨眼。>\n\n祝你好运，冒险者。",
  },
  [28018] = {
    ["T"] = "奥术仪式",
    ["O"] = "与艾尔文森林阿祖拉之塔的基塔·费温德谈一谈。",
    ["D"] = "啊，$N！自从你刚开始学习这门技艺以来，你的附魔技能已经长进了许多。我很欣赏！事实上，欣赏到想把你推荐给一份工作。\n\n基塔·费温德女士派人到幽暗城寻找一位附魔大师。我不想离开这座城市，而你显然更有……冒险精神。当然，这绝不是鲁莽！\n\n一辆前往湖畔镇的马车会正好经过阿祖拉之塔，基塔就在那里工作。我很好奇她想要什么。那座塔很少会请求外援。",
  },
  [28062] = {
    ["T"] = "给格雷姆洛克·皮尔斯诺的委托",
    ["O"] = "格雷姆洛克·皮尔斯诺要你用烹饪技能制作10份香辣狼肉，并把订单交给丹莫罗卡拉诺斯的格雷姆洛克·皮尔斯诺。",
    ["D"] = "嘿，$N！是来旅店吃顿热饭、再来上一大杯麦酒的吗？那我可得告诉你个坏消息——我们今天的招牌菜，香辣狼肉，已经全卖光了。\n\n话说回来，你自己不也会做点菜吗？要是你愿意帮我做几份今天的招牌菜，我很乐意按你体重送你等量的生肉！这买卖听起来不错吧？",
  },
  [28064] = {
    ["T"] = "给古博·布拉普的委托",
    ["O"] = "古博·布拉普要你用烹饪技能制作10份水煮蚌肉，并把订单交给黑海岸奥伯丁的古博·布拉普。",
    ["D"] = "还有什么能比钓鱼更让人肚子饿的吗？一想到鱼能用那么多种法子烹调，我的胃就开始咕咕直叫。\n\n不过大海的美味可不只有那些会游的家伙。$N，你吃过水煮蚌肉吗？我现在可真想来上一点。要是你愿意替我做些来，我肯定不会让你白忙。",
  },
  [28370] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "特工梅里根要你用急救技能制作20条厚符文布绷带，然后潜入黑石山的黑石塔下层，找到下士格鲁马尔。",
    ["D"] = "好吧，至少格鲁马尔还在部队指派名单上。这应该说明他还没死。\n\n坏消息是，他被派去黑石塔给军需官当卫兵。那地方大得离谱！他可能在里面的任何地方。\n\n霍尔登肯定不能陪我们进去。反正我也该回暴风城报告，并把这层幻象移除了。我只能把组队救回他的事交给你。一定要带些厚符文布绷带。他可能受伤了。",
  },
  [28371] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "黑石塔下层的下士格鲁马尔要你把抗毒剂样本带给奥格瑞玛的伊崔格，或暴风城的“剃刀”雷吉克。",
    ["D"] = "这样好多了。给我点时间，我会痊愈的。\n\n黑石兽人研制出了一种新的抗毒剂，还拿我来测试。我猜他们是厌烦了夜里被蝎子蜇。\n\n如果我们没有学到别的，至少也了解了这项可能的医疗突破。把这份抗毒剂样本带回给你的领袖。我休息一下后，就能自己离开黑石塔。",
  },
  [28372] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "用黑石抗毒剂治疗希利苏斯石鞭钳蝎造成的毒刺伤，然后回到奥格瑞玛的伊崔格或暴风城的“剃刀”雷吉克那里。",
    ["D"] = "据说这种抗毒剂能应对最强的蝎毒，那就让我们检验一下吧。\n\n我们收到了一支远征队的早期报告，他们前往了卡利姆多最东南方那片失落之地——希利苏斯。他们报告说那里有许多凶暴野兽，包括毒性强过以往所见任何蝎子的蝎类。\n\n我想不到比那里更适合检验这种抗毒剂效力的地方。去那里，尝试用这种抗毒剂治疗蝎子毒刺。回来报告它的效果。",
  },
  [28373] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "与暴风城旧城区军情七处的“剃刀”雷吉克谈谈。",
    ["D"] = "看来你已经完成了急救学业。干得好，$N。\n\n你此时来得正好。联盟需要一位经验丰富的医师效力。伯瓦尔亲自命令军情七处寻找合适人选，而我想不到比你更合适的人。\n\n如果你愿意响应号召，可以在旧城区的军情七处找到“剃刀”雷吉克。",
  },
  [28375] = {
    ["T"] = "给副官雷纳的委托",
    ["O"] = "基塔·费温德要你用附魔技能为提供的1件卫兵胸甲附上附魔胸甲 - 初级生命，并把订单交给艾尔文森林西泉要塞的副官雷纳。",
    ["D"] = "暴风城卫兵中有许多人都能从我们的服务中受益，可尘埃实在不够分。拿着这件卫兵胸甲，在给它附上胸甲 - 初级生命、使它成为附魔卫兵胸甲之后，把它带给西泉要塞的副官雷纳。",
  },
  [28376] = {
    ["T"] = "给巡山人麦酒的委托",
    ["O"] = "提尔利·草须要你用附魔技能为提供的1件守护者护腕附魔初级耐力，并把订单交给丹莫罗南门哨岗的巡山人麦酒。",
    ["D"] = "我手头有几份订单需要人帮忙。这一份是给南门哨岗的巡山人麦酒的。他把自己的守护者护腕留在这里，希望有人替它附上耐力魔法。请把附好魔的护腕送给他。",
  },
  [28377] = {
    ["T"] = "给议员梅尔·石谷的委托",
    ["O"] = "提尔利·草须要你用附魔技能为提供的1件演说者长袍附魔初级吸收，并把订单交给丹莫罗古博拉采掘场的议员梅尔·石谷。",
    ["D"] = "可别让一位议员久等。他正在古博拉采掘场视察，那里最近出了些麻烦。他想要一件附有初级吸收魔法的新演说者长袍。我想这份委托你应该应付得来吧？",
  },
  [28378] = {
    ["T"] = "给科瑞萨斯·月怒的委托",
    ["O"] = "奥兰纳·鸦眼要你用附魔技能制作1根次级魔法杖，并把订单交给泰达希尔多兰纳尔的科瑞萨斯·月怒。",
    ["D"] = "伊露恩与你同在，附魔师。你愿意接一份委托吗？多兰纳尔的科瑞萨斯·月怒很快就要卸下职守，转而踏上侍奉艾露恩的道路，只等法衣做好便会加入祭司团。他需要一根配得上新身份的魔杖。若你愿意做一根次级魔法杖送给他，他一定会十分感激，当然也会付你报酬。",
  },
  [28379] = {
    ["T"] = "给月之女祭司阿玛拉的委托",
    ["O"] = "奥兰纳·鸦眼要你用附魔技能为提供的1件女祭司斗篷附魔初级抗性，并把订单交给多兰纳尔与达纳苏斯之间道路上的月之女祭司阿玛拉。",
    ["D"] = "月之女祭司们负责守卫道路，阿玛拉希望我替她那件女祭司斗篷附上初级抗性魔法。看你似乎正需要多练练手，不如就接下这份活吧？她平时在多兰纳尔通往达纳苏斯的路上巡逻。至于报酬，自然少不了你的——我本来还想着今天偷个懒呢。",
  },
  [28426] = {
    ["T"] = "给驾驶员塞克·锤足的委托",
    ["O"] = "拉兹·滑链要你用工程学技能制作2把扳手，并把订单交给丹莫罗北门哨岗的驾驶员塞克·锤足。",
    ["D"] = "诺莫瑞根那场灾难让太多侏儒工程师丧生，如今我们的手艺可吃香得很。就拿驾驶员塞克·锤足来说——他居然开口想让我把我自己的工具交给他，好去修他的攻城引擎！\n\n哼，除非我死了，否则他别想拿走我的工具。不过如果你愿意做件好事，可以做几把扳手，替我送去北门哨岗给他。毕竟，我们还是想让那些攻城引擎正常运转的。",
  },
  [28382] = {
    ["T"] = "给奥兰纳的委托",
    ["O"] = "特伦希斯要你用附魔技能将提供的1件绒毛披风附魔为附魔披风 - 初级防护，并把订单交给黑海岸古树之林的奥兰纳。",
    ["D"] = "既然我已经察觉到黑海岸有腐化的迹象，提前做好防备总是明智的。我的表亲奥兰纳在南边古树之林经营着一个补给摊位。等你替这件绒毛披风附上初级防护后，就把它送去给她吧。她离镇子太远，我希望她能更安全些。",
  },
  [28383] = {
    ["T"] = "给特伦希斯的委托",
    ["O"] = "特伦希斯要你用附魔技能制作1根符文银棒，并把订单交给黑海岸奥伯丁的特伦希斯。",
    ["D"] = "也许这听起来有些迷信，不过我听说银对驱逐腐化很有效。附魔师，如果你愿意，就替我做一根符文银棒吧。我相信那上面的附魔铭文，总能在我的研究里派上用场。",
  },
  [28427] = {
    ["T"] = "给雷杰德·麦酒的委托",
    ["O"] = "拉兹·滑链要你用工程学技能制作5根铜管，并把订单交给丹莫罗烈酒村的雷杰德·麦酒。",
    ["D"] = "工程师和矮人一样，都懂得欣赏好酒。所以如果你有空，我想请你替我完成雷杰德·麦酒的这份委托。他需要一堆铜管来改良烈酒村的蒸馏器。雷杰德现在酿出来的酒已经相当不错了，我很想看看新蒸馏器运转起来之后，他还能做出什么佳酿。",
  },
  [28428] = {
    ["T"] = "给达扎拉的委托",
    ["O"] = "珊瑟尔要你用工程学技能制作1把劣质火枪，并把订单交给泰达希尔多兰纳尔的达扎拉。",
    ["D"] = "伊露恩庇佑你，$C。自从我从铁炉堡回来以后，我这点工程学手艺就变得格外抢手，订单多得我一个人根本忙不过来。\n\n如果你对机械也有些兴趣，也许可以替我分担一份？多兰纳尔的猎人训练师达扎拉想试试火枪。你能想象吗？这可真是够新潮的！\n\n总之，要是你愿意做一把劣质火枪给他送去，我会很感激你的帮忙。",
  },
  [28429] = {
    ["T"] = "给德纳兰的委托",
    ["O"] = "珊瑟尔要你用工程学技能制作20份劣质炸药，并把订单交给泰达希尔奥拉密斯湖的德纳兰。",
    ["D"] = "我手上有一份委托，实在让我有点摸不着头脑。你想不想看看？\n\n德纳兰最近在奥拉密斯湖边研究植物。前些天他捎来一张字条，说想要点“爆炸性的东西”来对付那些所谓“不听话的灌木”。老实说，我也不知道该怎么理解这话，不过如果你有兴趣做些劣质炸药，就送到多兰纳尔后方湖边的德纳兰那里去吧。",
  },
  [28432] = {
    ["T"] = "给考古学家埃弗里特的委托",
    ["O"] = "戈伯德·钢手要你用工程学技能制作5个活动假人，并把订单交给黑海岸雷姆塔维尔挖掘场的考古学家埃弗里特。",
    ["D"] = "这附近的大多数精灵都不太信任正经工程学，不过我最近和一位名叫埃弗里特的矮人聊过，他是南边雷姆塔维尔挖掘场的一员。他提到那些魔像带来了不小的麻烦，正想找些活动假人来帮忙周旋。我手头并没有现货——这玩意儿我平时也不常备——但要是你有兴趣做几个，我敢说他一定会给你一份像样的报酬。",
  },
  [28433] = {
    ["T"] = "给塞瑞利恩·白爪的委托",
    ["O"] = "戈伯德·钢手要你用工程学技能制作20份银触媒，并把订单交给黑海岸奥伯丁的塞瑞利恩·白爪。",
    ["D"] = "另一样我平时不怎么备货的东西，就是银触媒。不过镇上的一位暗夜精灵最近正想买一些。他说那是用来给他妻子画像时做“合适媒材”的。我不懂艺术……不过我懂得怎么赚钱。要是你能替塞瑞利恩·白爪凑来一些银触媒，这笔生意显然值得做。",
  },
  [28474] = {
    ["T"] = "给萨姆诺·普尔的委托",
    ["O"] = "萨姆诺·普尔要你用急救技能制作20卷亚麻绷带，并把订单交给丹莫罗卡拉诺斯的萨姆诺·普尔。",
    ["D"] = "卡拉诺斯如今挤满了年轻的新兵，一个个都急着证明自己。可一训练起来，擦伤、淤青和比脑子还大的自尊也就跟着来了。\n\n我们的绷带存货快见底了。要是你能给我带来20卷亚麻绷带，我们就能在这些小伤恶化之前先把它们处理好。",
  },
  [28475] = {
    ["T"] = "给考古学家埃弗里特的委托",
    ["O"] = "考古学家霍莉要你用急救技能制作20卷厚亚麻绷带，并把订单交给黑海岸雷姆塔维尔挖掘场的考古学家埃弗里特。",
    ["D"] = "我收到雷姆塔维尔挖掘场的考古学家埃弗里特传来的消息，说他们挖出来的那些魔像已经造成了几起小小的意外。\n\n你会急救包扎的手艺吗？如果会的话，能不能准备一些厚亚麻绷带，送去给挖掘场里的埃弗里特？那地方沿着南边的大路走很远才能到。",
  },
  [28476] = {
    ["T"] = "给守夜人多兹的委托",
    ["O"] = "布林克·扳柄要你用急救技能制作3份抗毒药剂，并把订单交给暮色森林中部守夜人营地的守夜人多兹。",
    ["D"] = "我懂毒药，$C。我研究过它们，调制过它们，也治过它们。在这片森林里？你最好随时准备处理一两次蜘蛛咬伤。\n\n守夜人在应对蜘蛛咬伤时用得上些实在的物资。把3份抗毒药剂带给守夜人多兹。这东西不花哨，但能让他的巡逻队继续站着，而不是死在沟里。",
  },
  [28477] = {
    ["T"] = "给艾米·达文波特的委托",
    ["O"] = "艾米·达文波特要你用急救技能制作20卷绒线绷带，并把订单交给赤脊山湖畔镇的艾米·达文波特。",
    ["D"] = "喂，你包里那些是绷带吗？我们正需要你的帮助。有些卫兵在山脊附近胆子太大，直接撞上了一支兽人巡逻队。现在他们回到湖畔镇了，可是……有几个人一时半会儿恐怕不能再出去站岗。\n\n我们的医疗补给不够了。如果你能给我带来20卷绒线绷带，我会确保它们送到卫兵手里。他们能活下来已经很幸运了——我们得让他们继续活下去。",
  },
  [28518] = {
    ["T"] = "给维隆·冻石的委托",
    ["O"] = "塞德里斯·叶眼要你用草药学技能采集20株银叶草，并把订单交给丹莫罗冻石农场的维隆·冻石。",
    ["D"] = "虽然我才刚到卡拉诺斯不久，不过大家似乎已经知道我擅长草药了。我手里有几份还没完成的订单，正需要个帮手。\n\n这里有一份来自冻石农场的订单。看起来，他们想要一大捆银叶草拿去喂公羊当零嘴。你能处理这份差事吗？",
  },
  [28519] = {
    ["T"] = "给奥兰纳·鸦眼的委托",
    ["O"] = "玛洛尼·刃叶要你用草药学技能采集20株地根草，并把订单交给泰达希尔神谕林地的奥兰纳·鸦眼。",
    ["D"] = "欢迎你，同行的草药师。想不想接份差事磨练一下手艺？\n\n奥兰纳·鸦眼也是位工匠，这会儿正在神谕林地练习附魔手艺。她想要一包地根草，这正是一份很适合你来完成的订单。",
  },
  [28521] = {
    ["T"] = "给洛南·金叶的委托",
    ["O"] = "雅尔达要你用草药学技能采集20株石南草，并把订单交给黑海岸金叶小屋的洛南·金叶。",
    ["D"] = "你看得见我吗？那你一定是个草药师……感谢艾露恩，总算来了个能听我说话的人！\n\n我在第三次战争中死去，却依旧被束缚在这个世界上。有些债我已经无力偿还，但我仍想尽自己所能——或者说，只能请你替我去做。你愿意采一些石南草，送去给住在通往灰谷道路西边小屋里的洛南·金叶吗？他会知道这些东西是谁托你带来的。",
  },
  [28522] = {
    ["T"] = "给玛蒂·詹罗斯的委托",
    ["O"] = "玛蒂·詹罗斯要你用草药学技能采集20株雨燕草，并把订单交给赤脊山湖畔镇的玛蒂·詹罗斯。",
    ["D"] = "那头该死的野猪贝利格拉布又跑进我的药草园了。这次它把我所有的雨燕草都吃光了！\n\n如果我想重新种满园子，就需要更多雨燕草枝条，可现在兽人到处都是，离镇子太远实在太危险。不过你看起来像是喜欢冒险的人。也许你能帮我一把？",
  },
  [28560] = {
    ["T"] = "给奥格恩·强眉的委托",
    ["O"] = "格雷塔要你用制皮技能制作2件雕花皮外衣，并把订单交给丹莫罗南门哨岗的奥格恩·强眉。",
    ["D"] = "你也是个学徒？那也许你不会介意替我分担几份积压订单吧？\n\n奥格恩在南门哨岗巡逻时连件上衣都不穿。照他的说法，是“跟风摔了一跤，把衣服输掉了”。是啊，对。\n\n如果你正好在练习制皮，就替他做两件雕花皮外衣吧。就算他嘴上不承认，山里的空气也绝对称不上暖和。",
  },
  [28561] = {
    ["T"] = "给格瑞夫的委托",
    ["O"] = "格雷塔要你用制皮技能制作2个皮质小弹药包，并把订单交给丹莫罗卡拉诺斯的格瑞夫。",
    ["D"] = "我很乐意把这份活儿交给你。格瑞夫近来对他的训练课程越来越没耐心——也越来越没地方装东西了。他说自己的弹药包已经磨得不成样子，铅弹一路漏得满雪地都是。\n\n如果你正打算提升制皮手艺，就做两个皮质小弹药包送去给他吧。他肯定用得上。说不定也能让他少冲那些学徒猎人咆哮几句。",
  },
  [28562] = {
    ["T"] = "给吉娜·羽弓的委托",
    ["O"] = "纳迪娅·织发要你用制皮技能制作2件皱褶皮短裤，并把订单交给泰达希尔多兰纳尔的吉娜·羽弓。",
    ["D"] = "啊，一位学徒制皮师。欢迎来到我的工坊。如果你是来磨练手艺的，我可以帮上点忙。\n\n我这里有几份简单差事，正适合新手来练手。多兰纳尔的吉娜·羽弓一直在泰达希尔深林里训练，裤子都磨破了好几个洞，正缺替换的。你可以做两件皱褶皮短裤给她送去。",
  },
  [28563] = {
    ["T"] = "给首席考古学家杜瑟·灰须的委托",
    ["O"] = "纳迪娅·织发要你用制皮技能制作1条手工皮带，并把订单交给泰达希尔达纳苏斯月神殿的首席考古学家杜瑟·灰须。",
    ["D"] = "我平时很少进达纳苏斯，不过如果你愿意去城里走一趟，我这儿还有一份很适合你来完成的订单。\n\n有位来访的矮人捎信来说，他那条腰带没能撑过从米奈希尔港一路颠簸的旅程。请做一条手工皮带，送给首席考古学家杜瑟·灰须。我想你会在月神殿找到他。",
  },
  [28566] = {
    ["T"] = "给克罗尼亚·恒影的委托",
    ["O"] = "马弗拉林要你用制皮技能制作5件中型护甲片，并把订单交给黑海岸古树之林的克罗尼亚·恒影。",
    ["D"] = "你是制皮师？感谢艾露恩！眼下森林危机四伏，我这边的订单已经堆得快处理不过来了。\n\n克罗尼亚·恒影总在清醒与沉睡之间徘徊，但即便身处冥想，他仍肩负着守卫古树之林的职责。他那身皮甲已经磨得很薄了。或许他在梦中察觉不到，可等他醒来，一定会在意。\n\n你愿意替他做五件中型护甲片送过去吗？也许等你到时他还没醒，但安静的帮助依然是帮助。",
  },
  [28567] = {
    ["T"] = "给格温妮丝·布莱勒贡德的委托",
    ["O"] = "马弗拉林要你用制皮技能制作1件优质皮外套，并把订单交给黑海岸奥伯丁的格温妮丝·布莱勒贡德。",
    ["D"] = "这份订单或许不是最紧急的，但绝对是最贴心的其中一份。\n\n格温妮丝这阵子一直在奥伯丁帮忙整理补给记录和德鲁伊的货运清单，可她从上个季度起就一直穿着那件破旧的外套。我觉得，是时候让她换上一件更结实、也更舒服些的新衣服了。\n\n你愿意替她做一件优质皮外套并送去吗？她就在镇上的飞行平台那边。",
  },
  [28608] = {
    ["T"] = "给格特·皮革匠的委托",
    ["O"] = "格特·皮革匠要你用剥皮技能收集5张轻毛皮，并把订单交给丹莫罗卡拉诺斯的格特·皮革匠。",
    ["D"] = "你想当个剥皮师？那就让我看看，你能找到的不只是些零碎皮料。\n\n给我带轻毛皮来——不是皮革，是毛皮。得有轮廓、有质地……得是值得拿来做工的东西。证明你知道自己在干什么，我才会认可你继续磨练这门手艺。",
  },
  [28609] = {
    ["T"] = "给拉德纳尔·织发的委托",
    ["O"] = "拉德纳尔·织发要你用剥皮技能收集20张轻皮，并把货物交回他在泰达希尔的住处。",
    ["D"] = "光会挥刀剥皮，谁都做得到。可你能不能剥得干净、稳定，还懂得对野兽怀有应有的敬意？\n\n给我带20张处理得体的轻皮来。要是你能在不糟蹋皮子的前提下收集到这些，也许就算真正准备好学这门手艺了。",
  },
  [28634] = {
    ["T"] = "给亚尔·锤石的委托",
    ["O"] = "矿场主管瑟斯丁要你用采矿技能收集20块劣质的石头，并把订单交给丹莫罗钢架补给站的亚尔·锤石。",
    ["D"] = "我看见你包里那把矿镐了！我这儿正焦头烂额，你可真能帮上大忙！\n\n采掘场里有穴居人捣乱，我们现在连民用石料订单都快交不上了，手头的库存全得优先供给军方。\n\n要是你能去采20块劣质的石头，再把它们送到钢架补给站交给亚尔·锤石，我心里这块石头可就真落地了。",
  },
  [28635] = {
    ["T"] = "给乌里安·熔栎的委托",
    ["O"] = "乌里安·熔栎要你用采矿技能收集20块铜锭，并把订单交回泰达希尔达纳苏斯的乌里安·熔栎。",
    ["D"] = "如今达纳苏斯的熔炉已经点燃，但再精致的造物也得先有根基。现在我们终于能在泰达希尔采矿了，需求大得惊人。\n\n给我带10块铜锭来。我手头还有一堆委托等着——精巧的配件，沉静的力量。而铜……铜会听从工匠的双手。",
  },
  [28636] = {
    ["T"] = "给瑟尔格拉姆·石锤的委托",
    ["O"] = "瑟尔格拉姆·石锤要你用采矿技能收集5块银锭，并把订单交给黑海岸奥伯丁的瑟尔格拉姆·石锤。",
    ["D"] = "啊，一位矿工。我这儿正好有活交给你。\n\n有时候，工艺讲究的可不只是常见的矿石和炉渣，还得用上那种带着特别光泽的材料——就像月光一样，也难怪精灵们会喜欢。\n\n总之，给我带5块银锭来。我在奥伯丁接了一份委托，正需要这种恰到好处的光泽，而银子最合适不过。",
  },
  [28675] = {
    ["T"] = "给维隆·冻石的委托",
    ["O"] = "阿斯拉·瑞克斯要你用裁缝技能制作2个亚麻包，并把订单交给丹莫罗冻石农场的维隆·冻石。",
    ["D"] = "这一季冻石农场把他们那些公羊使唤得够呛，老维隆来信说，他那两个鞍袋终于撑不住了——被尖石划得整个裂开。\n\n如果你会点裁缝活，就做两个结实的亚麻包送去给他吧。要不是我上次缝东西缝得像在给穴居人做袜子，我早就自己动手了。",
  },
  [28676] = {
    ["T"] = "给马莱斯·麦酒的委托",
    ["O"] = "阿斯拉·瑞克斯要你用裁缝技能制作1双高级亚麻手套，并把订单交给丹莫罗烈酒村的马莱斯·麦酒。",
    ["D"] = "烈酒村那边的马莱斯最近又把手指烫着了。她说自己那副旧手套用了太多年，整天碰滚烫的锅子，如今早就变得又硬又脆。\n\n如果你针线活还不错，就替她做一双新的高级亚麻手套吧。她自己是不会开口求人的，不过相信我，她要是每搅一次锅都疼得龇牙咧嘴，那些酒可就没现在这么好喝了。",
  },
  [28677] = {
    ["T"] = "给科瑞萨斯·月怒的委托",
    ["O"] = "蒂安娜要你用裁缝技能制作3件白色亚麻长袍，并把订单交给泰达希尔多兰纳尔的科瑞萨斯·月怒。",
    ["D"] = "科瑞萨斯多年来一直在为旅人指路、照料月亮井，但如今他的道路正在改变——他已经决定步入艾露恩祭司的行列。这是高贵的使命，也值得一个像样的开端。\n\n你愿意替他做三件白色亚麻长袍，并送到多兰纳尔去吗？这虽然只是小小的心意，却足以为新的开始添上一笔分量。",
  },
  [28678] = {
    ["T"] = "给维斯派塔斯的委托",
    ["O"] = "蒂安娜要你用裁缝技能制作1双简易的亚麻靴，并把订单交给泰达希尔鲁瑟兰村的维斯派塔斯。",
    ["D"] = "维斯派塔斯虽然常在天际翱翔，可他的靴子落在地上的时间一点也不短。照料角鹰兽、来回传送公文，他那双旧靴子早就磨得快开线了。\n\n如果你能做一双新的简易的亚麻靴，就送到鲁瑟兰村给他吧。他自己是不会开口要替换品的，不过我觉得，他理应拥有比脚底木刺更好的东西。",
  },
  [26689] = {
    ["T"] = "酒馆斗殴",
    ["O"] = "在闪金镇西南方的道路旁找到马迪根。",
    ["D"] = "就在几个小时前，我还得在狮王之傲旅店里制止一场斗殴。是为了爱情？荣誉？金钱？都不是。起因竟然只是一瓶怒药。\n\n我把他们拉开时，认出了其中一个打架的人——他叫马迪根，是大法师卡莱因的儿子。卡莱因正是这附近东边阿祖拉之塔的主人。\n\n马迪根踉踉跄跄地沿着镇子西南的道路走了，方向是西泉要塞。你能替我去看看他吗？要是他伤得太重，他父亲非得把本地卫兵骂个狗血淋头不可。",
  },
  [26690] = {
    ["T"] = "酒馆斗殴",
    ["O"] = "从艾尔文森林收集6片血瓣花叶，把它们交给狮王之傲旅店的威廉·匹斯特。",
    ["D"] = "我父亲派我来狮王之傲旅店，请威廉·匹斯特替他调制一瓶怒药。药一到手，我就想，顺便喝杯麦酒也无妨吧？可我连杯子都还没喝空，就被一个我从没见过的无赖扑了上来！\n\n事情很快闹大了，就在我们快要拔刀的时候，治安官杜汉出面制止了我们。可就在那阵混乱里，那个无赖偷走了药剂！\n\n我承认，过去我已经把父亲交代的几件事办砸过了；这次要是再拿不回那瓶药，他准会把我和我的狗一起扫地出门。\n\n如果治安官杜汉派你来帮我，那就请你去收集一些血瓣花叶，交给威廉·匹斯特，让他替我重新做一瓶药吧。",
  },
  [26691] = {
    ["T"] = "酒馆斗殴",
    ["O"] = "回到闪金镇西南方，把消息带给马迪根。",
    ["D"] = "如果马迪根每次来都要闹出这么大的乱子，那我可不想再接他的生意了。狮王之傲旅店是个舒适又体面的地方，可他每次一来，总会有人打起来！\n\n如果他还想买药剂和药瓶，以后就自己去暴风城吧。告诉他，从今往后他归卢米尔小姐管了！",
  },
  [26695] = {
    ["T"] = "酒馆斗殴",
    ["O"] = "把马迪根的情况告诉艾尔文森林阿祖拉之塔的塞欧克瑞图斯。",
    ["D"] = "如果你真想帮马迪根，那现在就继续替我跑这一趟。马迪根犯下的事，必须让他父亲知道；可我唯一知道能联系到他的人，只有阿祖拉之塔的塞欧克瑞图斯。那座塔就在闪金镇东边的道路旁。小心些——那座塔是强大奥术力量的汇聚之处，总让我觉得那里有些不对劲……",
  },
  [26696] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "在西部荒野中央的哨兵岭找到卡莱因。",
    ["D"] = "马迪根的父亲是我的同僚，大法师卡莱因。我派卡莱因前往西部荒野，希望找回一件极其重要的遗物：阿祖拉之手。\n\n阿祖拉之手是一件威力强大的武器，也因此引起了一群极其令人不安之徒的注意。我把它交给一位名叫坦诺斯的强大法师，让他先藏起来，可坦诺斯自从动身前往西部荒野后，就失去了踪影。\n\n如果你想找到卡莱因，就去哨兵岭吧。希望他已经踏上了坦诺斯的足迹。先帮他处理这件事，这样他才有余力照顾你的麻烦。",
  },
  [26697] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "从附近的迪菲亚拦路贼和迪菲亚走私者身上找出3条有关坦诺斯下落的线索。",
    ["D"] = "正如塞欧克瑞图斯告诉你的那样，我被派到这里寻找一个名叫坦诺斯的人，可到头来只听见了些风中耳语。\n\n我知道他来过这里，但在失踪之前，他没有向任何人透露自己的来意。\n\n斯托曼告诉我，坦诺斯曾四处打听本地迪菲亚的消息。他们也许就是找到他的关键。要是你想让我帮你处理马迪根的事，就先替我去敲打敲打他们吧，我留在这里继续调查。",
  },
  [26698] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "与哨兵岭旅店里的雷维尔·科斯特谈一谈。",
    ["D"] = "你离开这段时间里，我和这些人民军的人熟络了不少。他们已经不像一开始那样提防我，也愿意把自己知道的那点消息说出来。\n\n斯托曼告诉我，坦诺斯曾对迪菲亚兄弟会很感兴趣，还花了不少时间与一个叫雷维尔·科斯特的人交谈——那家伙是个替教会卖力气的打手，我们过去跟他们打过些交道。\n\n我们分手时闹得并不愉快。科斯特现在躲在旅店里，我觉得要是他认出我来，多半会立刻卷铺盖逃走。你何不去听听他自己打算怎么解释？",
  },
  [26699] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "从附近的迪菲亚强夺者和迪菲亚捕兽者身上再找出3条有关坦诺斯下落的线索。",
    ["D"] = "坦诺斯？那个灰头发的家伙？没错，他来过这里，嘴里念叨着迪菲亚，还在打听他们的一处据点。\n\n他当时看上去慌得很，连手都不肯跟我握。\n\n我不知道他后来去了哪儿，不过他显然是想找那些红面罩小子的麻烦。你说他们也在追他？那你又从他们身上查到了什么？\n\n看看你的笔记，你还缺了一半的信件呢。去找那些地位更高、更难对付的家伙下手吧，我打赌你需要的东西就在他们身上。",
  },
  [26413] = {
    ["T"] = "训练野兽",
    ["O"] = "与暴风城的霍维·希尔谈谈。",
    ["D"] = "$N，你现在已经有能力驯服宠物，但还必须掌握训练它的技巧。\n\n前往暴风城，找到矮人区。你必须在那里与我们最受尊敬的动物训练师之一霍维·希尔谈谈。他会赋予你训练新宠物的能力，所以快去吧，$G小子:姑娘;！\n\n霍维很友善；你要赢得他的认可应该不会有问题。祝你好运，$N。",
  },
  [26423] = {
    ["T"] = "造餐仪式",
    ["O"] = "与幽暗城法师区的贝索·冰沙谈一谈。",
    ["D"] = "你好，$N。你的训练已经让你变得强大，我相信自己已经没多少能教你的了。我猜你已经厌倦了为盟友召唤食物和饮料，对吧？如果我没猜错，你应该去暴风城找高阶巫师安多玛斯谈谈。我相信他知道更好的办法。",
  },
  [26513] = {
    ["T"] = "匹瑞诺德的遗产",
    ["O"] = "与暴风城市政厅的皇家代理人巴斯里洛谈谈，问他是否知道哈斯将军的下落。",
    ["D"] = "哈斯这个名字我听着并不熟悉，但这正是我们保存记录的原因！请稍等片刻。\n\n<昆德里克·赞登翻查一本厚厚的账册。>\n\n啊——确实有个哈斯，但只登记在旅店住了两晚，还带着一个女儿。他搭船南下了，事实上是去了暴风城。去那里找找吧。市政厅里应该有人能帮忙。",
  },
  [26514] = {
    ["T"] = "匹瑞诺德的遗产",
    ["O"] = "在暴风城花园区的黄水晶雄鹰旅店寻找哈斯将军。",
    ["D"] = "我熟悉这座城市里的每一位军官和卫兵——我们必须对他们全部做背景调查。暴风王国的军队里没有任何名叫哈斯的人。\n\n不过也许我可以指引你去找一位亲戚——伊莱亚斯·哈斯在花园区经营一家旅店。我记得叫黄水晶雄鹰。也许他能继续给你指路？",
  },
  [26606] = {
    ["T"] = "成熟可取",
    ["O"] = "从诅咒之地的要塞军械库偷取10箱守望堡矿石货物。",
    ["D"] = "<托斯拉克把头歪到一边，用右眼看着你。>\n\n俺这只眼不好，$C……但这不代表俺看不出好机会。\n\n在斯通纳德，我们需要金属来造武器、维护建筑、修理东西……你说得出的都要。这里西北边的高地上，守望堡有座矿，里面全是优质矿石。我敢打赌他们肯定有一箱箱矿石，堆在什么地方等着运回暴风城给那些娘娘腔铁匠。\n\n俺需要一些那种矿石，$C。",
  },
  [26612] = {
    ["T"] = "祈祷成真",
    ["O"] = "护送圣骑士谢尔曼离开魔石要塞。",
    ["D"] = "<那个人类猛地睁开眼，注意到了你的存在。>\n\n你……你不是邪教徒？今天是什么日子？我得离开这里！\n\n我的小队有一半被斥候屠杀……他、他们把剩下的人带到了这里，现在只剩我一个了。\n\n求你了，我们必须走！如果我们逃出去——愿圣光庇佑——请把你在其中的帮助告诉格雷森·沙东布瑞克公爵。他住在暴风城的大教堂。",
  },
  [26615] = {
    ["T"] = "更大的图景",
    ["O"] = "从魔石的精英居民身上取得20份魔石信函。",
    ["D"] = "兽人最初入侵艾泽拉斯时，这片土地资源丰饶。他们修建魔石作为立足点和集结地，源源不断地涌入我们的世界。魔石在第二次战争中与黑暗之门一同被摧毁。从那以后，很少有人冒险靠近这座要塞废墟。\n\n然而你取回的笔记却把它说得像一座城市。所有这些重建不可能一夜之间完成，也绝不可能没有人监督。驻扎在魔石的部队似乎来自暗影议会的不同派系，而我完全看不出是谁在主持大局。他们很少合作。\n\n我正在给我在暴风城的一位同僚准备报告，希望你收集更多质量更高的情报。我建议你找一些可靠的盟友帮忙。潜入要塞，在装备精良的人身上寻找信函。\n\n记住——这首先是一项侦察任务。不要低估我们的敌人。这些笔记证明，魔石里住着一些非常强大的人物，所以要小心。",
  },
  [26619] = {
    ["T"] = "还不算最糟",
    ["O"] = "把24瓶魔石烈酒带给格罗克斯·污摇。",
    ["D"] = "所以，守望堡也对水感兴趣？怎么……那些暴风城大人物把你们的供给掐了还是什么？别怕，别怕……\n\n嗯……来做点交换怎么样？我不喜欢那些魔石家伙——阴沉、两面三刀，有时还坏得要命！不过他们酿的老烈酒倒真不错。\n\n给我带回来，嗯……两打那玩意儿。做到这点，我就把我的水分给你一些，剩下的等我们离开这里港口后送去守望堡。",
  },
  [26621] = {
    ["T"] = "复苏的邪恶",
    ["O"] = "与暴风城法师区巫师圣殿里的高阶巫师安多玛斯谈一谈。",
    ["D"] = "我已经把我们了解到的一切整理成了一份报告，$N。我在暴风城的同僚是高阶巫师安多玛斯，他是一位睿智而力量深不可测的人。请尽快把这份报告带给他。等他读过之后，我相信他会运用自己巨大的影响力来扑灭这场威胁。\n\n我在信中写下了你的行动，详细说明了你在这里提供的所有帮助。你抵达时，高阶巫师应该会给你一些东西。\n\n愿圣光与你同在，$N。永远如此。我们会把这些黑暗势力挡在外面，哪怕这是我们最后要做的事。",
  },
  [26657] = {
    ["T"] = "看守者的请求",
    ["O"] = "杀死逆风食人魔并搜查他们的营地，看看他们是否在掠夺卡拉赞废墟，然后带着你的发现回到逆风小径埃瑞丁营地的埃瑞丁·埃利斯那里。",
    ["D"] = "向你致意，旅行者！通常我会建议那些穿越逆风小径的人赶紧过去，但你看起来更有胆量。\n\n我曾是老麦迪文庄园卡拉赞的看守者。魔法失控时我人在暴风城，如今事情稍微平息下来，我觉得自己必须去看看那里。我可不是个愚蠢的老头。我需要一位勇敢的灵魂先帮我侦察。\n\n你会听到各种关于那地方的可怕传闻，所以我不希望你直接冲进去。有一支食人魔部族搬进了南边道路沿线的洞穴。如果像你这样有进取心的年轻$g绅士:女士;愿意去查看那些食人魔营地，看看他们有没有从卡拉赞掠走贵重物品，我们就能知道那里是否安全，能不能展开调查。",
  },
  [26700] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "根据迪菲亚线索，在西部荒野找到坦诺斯。",
    ["D"] = "我奉命来到西部荒野，寻找一件据说落入某个名为黑暗骑手的团体手中的强大遗物。\n\n那些骑手是传说中的存在——邪恶而污秽的生物，在大地上游荡，四处搜寻拥有巨大力量的物件，好献给卡拉赞中那位黑暗的主人。\n\n我相信，坦诺斯手里的东西，力量至少与我正在寻找的遗物相当，甚至更强。\n\n要是那些骑手察觉到他持有此物，他就凶多吉少了。你必须尽快找到他！我这就去把事态的变化通知卡莱因。",
  },
  [26701] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "帮助坦诺斯清理金海岸矿洞，好把那里变成一处安全屋。",
    ["D"] = "小心！我控制不住这东西！塞欧克瑞图斯把这该死的手套交给我，叫我把它藏在西部荒野。\n\n可我一离开阿祖拉之塔，就像中了邪一样，非得把它戴到手上不可。它贴住我的手，像是长成了第二层皮，我怎么也摘不下来！现在只要我一害怕，它就会开始喷涌出原始的奥术能量。\n\n我得躲起来，$C！绝不能让任何人知道我藏在哪。\n\n前面的矿洞正好可以成为我的新住处。那些在这里作恶的迪菲亚占了这地方，镇上的人都不敢靠近。有这只手套在，我很容易就能把他们清干净。迪菲亚突然消失这种事，很长一段时间都不会有人起疑。",
  },
  [26702] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "回到艾尔文森林阿祖拉之塔的塞欧克瑞图斯那里。",
    ["D"] = "我们失败了……那些骑手如今掌握的力量，光是想想都让我心生畏惧。\n\n我们必须回去见塞欧克瑞图斯，把发生的事告诉他。\n\n至于该怎样收拾这个烂摊子，我实在毫无头绪。",
  },
  [26704] = {
