    ["O"] = "向夜色镇的守卫询问那对神秘搭档的消息。",
    ["D"] = "我认得你脸上的表情。我在最坚韧的$gmen:women;脸上也见过这种神情……只要他们和那些骑手打过照面。没错，不到两个小时前，他们就在附近出现过。\n\n不久前，一个举止古怪的法师和一名牧师带着同样的表情冲进镇子。他们似乎在找什么人，向好几个镇民逼问消息，然后又匆匆离开了。\n\n我没看见他们往哪边走。去问问我的守夜人，看看他们有没有看见那两人离开的方向。",
