    ["O"] = "在夜色镇南边找到雷维尔的营地。",
    ["D"] = "好吧，至少我们现在知道了一个名字：雷维尔。这个名字对你有意义吗？\n\n你见过他？那两个疯子是在找你？难怪你们三个脸上都是那副被什么东西缠上的表情……\n\n那就到镇子南边去，试着追上他们吧。他们已经离开一天多了——应该是在附近什么地方扎了营。",
