  [26706] = {
    ["T"] = "夜色中的骑手",
    ["O"] = "调查夜色镇北边的密斯特曼托庄园。",
    ["D"] = "雷维尔的日志：第247天——第二部分\n\n卡莱因说，黑暗骑手最近曾在密斯特曼托庄园出现，原因我们都不清楚。更重要的是，庄园附近又有人看见了狼人，而那里平常本该挤满亡灵。\n\n我们很快就要动身了。我希望我们能给他找到急需的慰藉。",
  },
  [26707] = {
    ["T"] = "夜色中的骑手",
    ["O"] = "从光明大教堂的达罗斯修士那里取得灌注之银锭，并从暴风城港口的罗伯特·达比那里取得优质橡木。",
    ["D"] = "要让这个顽固的狼人开口，我们就必须借助暗影——那是很少有人谈论的圣光另一面。\n\n我一直在为这样的时刻做准备，而现在正该把这些准备投入正义之事。卡莱因是个好人。他理应知道自己的儿子在哪里。\n\n首先，去暴风城港口区找码头管理员阿盖尔谈谈。他应该保管着一只箱子，里面有一位……朋友送来的特殊银材。你在那里的时候，也去船厂找造船匠罗伯特·达比。我们需要一些橡木，而他欠我一个人情，因为某次酒馆斗殴里我救过他的命。\n\n拿到银材后，你必须把它带给一位熟人，达罗斯修士。他负责看守光明大教堂图书馆中最受觊觎的典籍。\n\n你会在大教堂地下找到那座图书馆。把银材交给他，他会为它祝福。\n\n把灌注之银和优质橡木都带回来给我。",
  },
  [26708] = {
    ["T"] = "夜色中的骑手",
    ["O"] = "审问被俘的狼人。",
    ["D"] = "雷维尔已经把他的计划告诉了我，也把取得情报所需的工具交给了我。可现在我们到了这里，我……我觉得自己做不到。求你替我做这件事吧，$N。拜托！我必须知道马迪根去了哪里，他是否平安。",
  },
  [26709] = {
    ["T"] = "夜色中的骑手",
    ["O"] = "前往夜色镇南边的罗兰之墓。清出一条穿过狼人的道路，并在里面等待卡莱因和雷维尔。",
    ["D"] = "如果我的儿子在罗兰之墓，我们必须在一切太迟之前赶到那里。雷维尔和我会处理这个狼人的尸体，然后在那里与你会合。替我们清出一条穿过守卫那片区域的狼人的道路，我们会去找你。\n\n我必须抱着马迪根仍在那里且平安无事的希望，但我也担心最坏的结果。请快些，$n。",
  },
  [26710] = {
    ["T"] = "夜色中的骑手",
    ["O"] = "在等待卡莱因和雷维尔抵达时，守护罗兰之墓中的马迪根。",
    ["D"] = "这群家伙的头狼很快就会回来。他想用某种邪门的镰刀把我变成他们的一员。那东西用在我身上时，灼痛一路烧进我的脑子里，可我挺住了。他说我们得去“那个地方”，然后把我带到这里来完成仪式。\n\n我需要先恢复力气，然后我们就能离开这里去找我父亲，赶在那头狼回来把我们全都变成狼人之前！",
  },
  [26711] = {
    ["T"] = "死中求生",
    ["O"] = "在暮色森林各处收集8朵光明森林花。",
    ["D"] = "在麦迪文的腐化席卷之前，这片闹鬼的土地曾被称为光明森林，后来才变成如今的暮色森林。\n\n这片土地被污染得太深，以至于许多人相信这里已经长不出任何能滋养生命的东西。你在外面看见的南瓜？里面全烂透了。\n\n我和其他人不同。我相信在艾露恩的帮助，以及自然治愈之力的一点触碰下，这里仍有希望。\n\n要修复这片土地，我首先需要一件昔日残留之物。暮色森林各处仍生长着一种古老草药，名叫光明森林花。收集8朵给我，我就能在下一阶段实验中用上它们。",
  },
  [26712] = {
    ["T"] = "死中求生",
    ["O"] = "从暮色森林各处的亡灵身上收集新鲜骨粉。",
    ["D"] = "我实验所需的下一种关键材料很污秽。健康与生命的对立面，就是死亡与腐朽，而这片林地里到处都是这样的东西。\n\n去那些墓地，从游荡其间的亡灵身上收集新磨出的骨粉。请给我带回5份，$n。",
  },
  [26713] = {
    ["T"] = "死中求生",
    ["O"] = "找到黎明森林，并在月亮井中装满小瓶。",
    ["D"] = "在暮色森林深处，有一处绝美之地，即便在这片腐化之中，生命也依然繁盛。它名叫黎明森林。你会在那里找到我的先辈留下的一口月亮井。我相信这就是拯救暮色森林的最后关键。\n\n从夜色镇向南出发，走到通往荆棘谷的岔路前。从那里向北走，你会找到进入林地的小径。带上你收集到的材料，用月亮井的水装满这个小瓶，然后把它带回来给我。",
  },
  [26714] = {
    ["T"] = "女仆的陨落",
    ["O"] = "在夜色镇找到内尔昔日的恋人法林。",
    ["D"] = "我已经好几个星期没见到我的爱人法林了。只要能再见到他的脸，我就会满心欢喜，可他已经一个月没来了，而如今密斯特曼托庄园也落入了亡灵之手。\n\n我留下来服侍斯塔文领主，可他正在改变。我发誓我看见他的血肉正从骨头上脱落，虽然他试图把它藏起来。\n\n斯塔文领主声称外面的世界已经陷入混乱，我的法林也一定随之遇难了。否则他为什么不回来？\n\n没有他，我活不下去。永别了，我的爱人。圣光啊，请宽恕我。",
  },
  [26715] = {
    ["T"] = "女仆的陨落",
    ["O"] = "从血鸦旅店偷一些剩下的面包和一桶光明森林白葡萄酒。",
    ["D"] = "我不敢相信她的悲伤竟把她变成了女妖。我必须解放她的灵魂！让我想想……\n\n我想到了！我们得把她引出来，让她安息。我们以前最喜欢做的事，就是到干草地里野餐，所以也许再次邀请她去那里，会让她动心？\n\n我并不富裕，但绝望的时候就得采取绝望的手段。你愿意从血鸦旅店偷一些剩下的面包，还有一桶她最喜欢的光明森林白葡萄酒吗？",
  },
  [26716] = {
    ["T"] = "女仆的陨落",
    ["O"] = "从夜色镇西边的年幼黑色破坏者身上收集6份柔软的狼毛。",
    ["D"] = "以前我们去野餐时，我有时会忘记带毯子，然后她就会责备我。如今再也不会发生了，我却开始想念她的责备。\n\n<法林怅然一笑。>\n\n要让这件事成功，每个细节都必须完美，可我手边没有能用的毯子。我们得赶快做一条新的。\n\n去夜色镇外寻找年幼的黑色破坏者，把它们的毛带给我；有了这些毛，我就能让人做出一条不错的毯子。",
  },
  [26717] = {
    ["T"] = "女仆的陨落",
    ["O"] = "把准备好的野餐套装放在夜色镇西边的干草地里，并在内尔·奥克斯伯恩的灵魂出现时让她安息。",
    ["D"] = "我们终于能让我的内尔安息了。我祈祷她在这被诅咒的生命之后，无论去往何处，都能得到平静。\n\n我已经替你准备好了毯子和野餐套装。把它们带到我们过去见面的干草地，用它引出她的灵魂，然后杀死她。这是必须做的事，可我无法忍受亲眼看着它发生。",
  },
  [26718] = {
    ["T"] = "至死方休",
    ["O"] = "从毒液蛛网小蜘蛛身上收集10份闪亮的蜘蛛丝，并从暮色森林北边的河里收集7颗纯净的珍珠。",
    ["D"] = "等等！先别动手！求你了！我需要你的帮助。\n\n在那个金发混账阿尔萨斯王子毁掉洛丹伦之前，我和费伊·安德希尔小姐曾一起与世无争，过着幸福的日子。天灾军团来临时，我把她送走了——而我自己后来变成了什么样，你也看见了。\n\n她已经回到了夜色镇，而我无比渴望能和她说上话，重续旧情。可我现在这副模样怎么行？她还能认出我吗？\n\n不过，我已经想好了！我要给她做一份她最喜欢的礼物，再把自己尽可能收拾得体面些。只要她认出我来，我就知道她一定会扑进我怀里。\n\n我需要夜色镇东北方那些毒液蛛网小蜘蛛身上最上等的蜘蛛丝，可我现在这副样子根本没法离开谷仓。你能替我取来吗？\n\n另外，你在那边时，也请潜入暮色森林与艾尔文森林之间的河水深处。你会在蚌壳里找到最完美的珍珠。有了这些东西，我就能做出一条美得惊人的项链。",
  },
  [26719] = {
    ["T"] = "至死方休",
    ["O"] = "从暴风城运河区的花店取得一朵红玫瑰。",
    ["D"] = "这条项链非常适合我的费伊。她一直很喜欢珍珠，而你带来的这些珍珠搭配得也很漂亮！可是，唉，如果她隔着一里地就能闻到我腐烂的血肉味，珍珠也派不上用场。\n\n在洛丹伦时，我们常常自己调香玩。她总说我们做的玫瑰香水最适合我。如果我能重现那种香味，她一定会立刻认出我。\n\n我知道这附近唯一的花匠，就是暴风城运河区芳香花店的冈普一家。去找他们，给我弄一朵新鲜的红玫瑰，好让我摆脱这股死亡气味。",
  },
  [26720] = {
    ["T"] = "至死方休",
    ["O"] = "把杰克给费伊的信放进夜色镇外、废弃谷仓后面的她家里。",
    ["D"] = "我赢得她爱意的计划最后一步，就是这封我写给她的信，里面用了我们之间的秘密昵称。我相信它一定会把她带到我身边。你能把它带去，放在她家里吗？我不能冒险被守夜人看见。她的房子就在这座谷仓后面。",
  },
  [26721] = {
    ["T"] = "至死方休",
    ["O"] = "在夜色镇外的谷仓里等待费伊·安德希尔到来。",
    ["D"] = "你把信放好了？我激动得难以形容。我相信她随时都会到。香水已经擦好了，我知道这份礼物一定能帮我赢得她的心。等我向她解释是你让我们重逢，她也一定会很高兴认识你的。",
  },
  [26722] = {
    ["T"] = "至死方休",
    ["O"] = "结束杰克·阿彻的痛苦，杀死他。",
    ["D"] = "我不能再这样活下去了。再也不能了。没有她，我的不死生命便失去了意义，如今我一无所有。\n\n求你了，$n。趁守卫还没在广场上把我这个被遗忘者撕成碎片，快点结束我的生命吧。",
  },
  [26723] = {
    ["T"] = "通缉：染疫蹒跚者",
    ["O"] = "杀死潜伏在夜色镇北边河岸附近的染疫蹒跚者。",
    ["D"] = "有人发现一头污秽的染疫怪物只在夜间沿夜色镇北边的河岸巡行，所到之处留下一路死亡与毁灭。\n\n凡心志坚定、技艺自信的冒险者，请在它游荡到离夜色镇和商路太近之前将其消灭。",
  },
  [26772] = {
    ["T"] = "中级马术",
    ["O"] = "向兰达尔·亨特学习中级骑术，然后与艾尔文森林的凯蒂·亨特谈一谈，领取你的马。",
    ["D"] = "欢迎回来。你是来学习更快的骑术，对吧？和上次一样，你那匹马的费用已经有人替你付过了，不过训练费还得你自己出。很遗憾，更高级的训练可不便宜。\n\n学会骑术之后，就去围栏另一边找凯蒂·亨特谈谈。她负责出售我们的马。要是你手头钱还不够，以后随时都可以再来。",
  },
  [26773] = {
    ["T"] = "马术",
    ["O"] = "向兰达尔·亨特学习初级骑术，然后与艾尔文森林的凯蒂·亨特谈一谈，领取你的马。",
    ["D"] = "所以，你是来领马的，是吗？巧得很，我正等着你呢！有位神秘的赞助者替你留下了一笔钱，正好够买一匹普通坐骑，而且收件人还写着你的名字，$N。不过对方没替你付训练费，所以很抱歉，这部分还是得你自己出。\n\n学会骑术之后，就去围栏另一边找凯蒂·亨特谈谈。她负责出售我们的马。要是你手头钱还不够，之后再来也行。",
  },
  [26774] = {
    ["T"] = "蜘蛛药剂",
    ["O"] = "从艾尔文森林的玉石矿洞取回4个蜘蛛上颚，并释放4名被困的矿工。",
    ["D"] = "冒险者，你愿意助我一臂之力吗？这些可怜的矿工是在逃离玉石矿洞时被人发现的。他们还没能撑到回闪金镇，就因精疲力尽而倒下了。我一直问不出究竟发生了什么，因为他们神志不清；一定有什么东西扰乱了他们的心智。\n\n我听说矿洞深处已经成了蜘蛛的巢穴。要是这些矿工是中了蜘蛛的毒，那一切就说得通了！我需要一些矿洞蜘蛛的上颚样本，这样才能配制出对症的解毒剂。\n\n还有，拜托了——如果你在里面看见被困的矿工，请把他们放出来，让他们逃走。",
  },
  [26776] = {
    ["T"] = "迅爪",
    ["O"] = "把迅爪的鼻子带给北郡修道院外的梅丽莎·斯蒂尔维尔。",
    ["D"] = "你——$c——总算有人愿意来帮忙了，真是太好了。你听说最近那场惨事了吗？我儿子当时正在瀑布下方玩耍，突然有一头巨狼从树林里冲出来，把他活活咬死了！等我反应过来时，我可怜的孩子已经没救了。\n\n<梅丽莎的眼眶微微泛红。>\n\n我去找过几名卫兵，他们说那头狼叫迅爪，因为它每次都跑得飞快，根本抓不住！他们还说自己帮不上忙！如果你真想闯出点名声，就让一位母亲的心得到安息，杀掉那头可怕的野兽，别让同样的悲剧再发生在别人身上。",
  },
  [26777] = {
    ["T"] = "浸湿的酒桶",
    ["O"] = "在北郡修道院找一个也许知道这只酒桶来历的人。",
    ["D"] = "你沿着通往水晶湖的河边行走时，偶然发现了一只泡透的麦酒桶，桶身上印着一座寒冬山峰的标记。它散发出一种你从未闻过的奇妙香气。北郡修道院里也许有人知道这东西是从哪里来的。",
  },
  [26778] = {
    ["T"] = "寻找修士",
    ["O"] = "把浸湿的酒桶带给北郡修道院的尼尔斯修士。",
    ["D"] = "我自己可不是什么麦酒和葡萄酒的行家，我只是种葡萄而已。不过这里倒是有个人，我敢说他绝对算得上专家——尼尔斯修士。你会在修道院顶层找到他。",
  },
  [26779] = {
    ["T"] = "修士的嫌恶",
    ["O"] = "把这堆酒桶带给狮王之傲旅店的米利卡·艾森斯泰德。",
    ["D"] = "<尼尔斯修士看着那只酒桶，嫌恶地皱起了脸。>\n\n真是难以下咽的泔水！这里可是酒庄，$N！奥斯沃斯小姐种出了整个东部王国最好的葡萄，而我和其他修士则负责酿酒。这里没人喝麦酒。\n\n如果你真想知道这东西是从哪来的，就去闪金镇的狮王之傲旅店，把你找到的东西拿给米利卡·艾森斯泰德看看。她认识本地的常客和酿酒人。\n\n哦！既然你正好要去，也请把我们最新一批葡萄酒一起带给她。",
  },
  [26771] = {
    ["T"] = "遗失的设备",
    ["O"] = "从玉石矿洞找回8件采矿设备，然后回到闪金镇的罗伯特·密斯顿那里。",
    ["D"] = "在狗头人和蜘蛛占据玉石矿洞以前，我曾在那里工作。那里矿石丰富，也是暴风城铁匠的主要供应来源。\n\n怪物占据那里时，我们失去了许多矿工兄弟姐妹，也失去了所有设备。我无法替代那些矿工，但你能不能找到一些我们留在那里的设备并带回来给我？",
  },
  [26780] = {
    ["T"] = "法师的建议",
    ["O"] = "到狮王之傲旅店楼上与扎尔迪玛·维夫希尔特谈一谈。",
    ["D"] = "你这么一说，我倒想起来了……大概一周前，这里来过一个叫穆伦的矮人。他喝得昏天黑地，还不停向客人吹嘘，说自己正在北郡瀑布附近、修道院上方的高处寻找富矿。\n\n他带来的麦酒，看起来和闻起来都和你带来的这只酒桶一模一样。不过，我觉得像你这样年轻的$c，恐怕很难爬上那些峭壁。\n\n如果你有兴趣去追查穆伦，就去楼上找扎尔迪玛。他是个精明的法师，也许能帮上你。",
  },
  [26781] = {
    ["T"] = "莱纳斯·斯通提普斯",
    ["O"] = "把一块耗尽能量的移位石带给闪金镇狮王之傲旅店的扎尔迪玛。",
    ["D"] = "接下来就需要你帮忙了，$N。我最近发现我以前的助手竟然和本地的迪菲亚勾结在一起。莱纳斯就在我眼皮底下，把闪金镇卫兵的巡逻规律和货运情报一点点喂给他们！\n\n可惜的是，我把他逐出门下时，他还顺手偷走了我几件法器。更糟的是，他拿走了一块尚未充能的移位石。把那块石头替我取回来，我就很乐意帮你。\n\n我最后一次从卫兵那里听说，他正在闪金镇北边的一座小山上窥探镇子的动静。要是你顺手多给他一点教训，我也不会介意。",
  },
  [26782] = {
    ["T"] = "酿酒兄弟",
    ["O"] = "找到北郡山谷的瀑布，并用移位石到达顶端。",
    ["D"] = "既然这件事已经办妥，你现在应该能找到那桶麦酒的来源了。把这块石头带到北郡山谷瀑布下方，用它把自己送到上面去。希望你能在那里找到想找的东西。",
  },
  [26783] = {
    ["T"] = "无怨无悔！好吧，也许有点",
    ["O"] = "在北郡瀑布找到德罗穆尔·怪饮。",
    ["D"] = "我和我的伙伴德罗穆尔是从丹莫罗一路来到这里的。我们穿过燃烧平原，狠狠干了一路，就是为了来这片与世隔绝的山谷里发笔横财。\n\n可等到我们真要占下这份宝藏时，却闹翻了……他拿走了我的工具，我搬走了他大半套酿酒家伙——结果现在我们俩都被困在这儿了！\n\n那桶麦酒不是我酿的，$N。真正有这手艺的人是德罗穆尔，他就在上游那边。经过我之前说的那些话，我看他多半永远都不会再理我了……不过，你能不能替我去看看他是否安好？",
  },
  [26785] = {
    ["T"] = "真正的朋友",
    ["O"] = "把山脉烈酒带给北郡瀑布的穆伦·金吼。",
    ["D"] = "是时候让你、我，还有穆伦坐下来狠狠干上一杯，把这场争执彻底翻篇了。我和他可是老交情，真要没了他，我都不知道日子该怎么过。看在造物主的份上，我们可是姻亲啊！走吧，咱们去找他。",
  },
  [26786] = {
    ["T"] = "暴风城的蓄意破坏",
    ["O"] = "与暴风城港口的侦探马洛谈一谈。",
    ["D"] = "啊，又见面了，$N。我很高兴你来了——你以前替我们办过不少漂亮差事，而如今我们家门口正酝酿着一桩麻烦。我不觉得这和你先前调查过的迪菲亚活动有关——暴风城里又冒出了一伙心怀叵测的新角色。\n\n港口码头那边发生了一起明目张胆的破坏案。虽然没人受伤，但几位新来居民的货车被人射穿，还被放火烧了。那位妻子自然是惊魂未定，可她丈夫却古怪地闭口不谈。这事背后另有隐情，所以我派你去支援。去和侦探马洛会合，看看他目前查到了什么，又需要你帮什么忙。祝你好运！",
  },
  [26787] = {
    ["T"] = "暴风城的蓄意破坏",
    ["O"] = "向暴风城港口布拉德福德家货车附近的其他人询问线索，然后向侦探马洛报告。",
    ["D"] = "我已经确认这是纵火，昨晚值勤的卫兵确实看见一个人影冲了出去——但他们当时更担心在火势蔓延前把火扑灭，而不是追捕嫌疑人。\n\n我询问过维维安和德里克·布拉德福德。维维安看起来完全不知所措，但我怀疑德里克隐瞒了什么。具体来说，我认为这是一起有目标的行动，而他知道原因。可他不会告诉我们——至少现在不会。\n\n也许你可以去问问码头周围的其他人，看他们有没有看到什么，同时我在这里继续翻查灰烬，找找更多线索？",
  },
  [26788] = {
    ["T"] = "暴风城的蓄意破坏",
    ["O"] = "搜查暴风城的旅店和酒馆，寻找一名形迹可疑的女人，并与她对质。",
    ["D"] = "暴风城有六家旅店和酒馆，你可能得把它们全都查一遍，才能弄清这名神秘人物的更多情况。\n\n我建议从旧城区的猪和哨声旅店开始——那一带有不少粗野角色。不过矮人区还有醉酒女招待旅店，贸易区有镶金玫瑰旅店，法师区有蓝色隐士旅店和已宰的羔羊旅店，花园区还有黄水晶雄鹰旅店。都去查一查，看看旅店老板或酒保有没有听说过符合描述的人。\n\n你得去已宰的羔羊旅店，这我可一点也不羡慕。那地方让我毛骨悚然。",
  },
  [26789] = {
    ["T"] = "暴风城的蓄意破坏",
    ["O"] = "前往南海镇找到赫尔姆斯沃西少校，了解更多有关奥特兰克军团的事。",
    ["D"] = "五十年前，奥特兰克军团曾是传奇。可惜，他们大多数人在奥特兰克围城战以及之后的混乱中丧生了。若他们还在，我们本能借助他们的力量对抗天灾……\n\n既然德里克·布拉德福德可能有所隐瞒，最好还是从别处打听消息。我认识的前奥特兰克军团成员里，只有一个还活着。前往南海镇，和赫尔姆斯沃西少校谈谈。也许他能说明德里克·布拉德福德与辛迪加或军团之间的关系。",
  },
  [26790] = {
    ["T"] = "失落的旗帜",
    ["O"] = "与暴风城港口的德里克·布拉德福德谈一谈。",
    ["D"] = "<赫尔姆斯沃西少校听你说明情况。>\n\n我很高兴你来找我，$C。换成别人，几乎没人能帮得上你。\n\n德里克·布拉德福德是少数在奥特兰克陷落后幸存下来的前军团成员之一。几个月前，他给我写过一封信，打算找回我们部队三面失落多年的雄鹰旗帜。它们分别遗失在军团参战的几场关键战役中。那些旗帜在金钱上毫无价值——但它们是奥特兰克骄傲的强大象征。我相信辛迪加听到了这个计划，也想把同样的旗帜据为己有。如果他们拿到这些旗帜，就能号召新兵，重建一个扭曲版本的奥特兰克军团。\n\n经历这次谋杀未遂后，德里克不会再信任任何人，但如果你用你知道的事把他引出来，我相信他会接受你的帮助。",
  },
  [26791] = {
    ["T"] = "失落的旗帜",
    ["O"] = "从奥特兰克废墟、达拉然废墟和激流堡废墟找回荣誉旗帜，然后把它们带给希尔斯布莱德丘陵南海镇的赫尔姆斯沃西少校。",
    ["D"] = "我查过奥特兰克军团那些旗帜遗失的地点。\n\n军团显然参与了围城期间奥特兰克城的防务，他们的主旗就遗失在那里。但军团残部后来试图抵御天灾对达拉然的进攻，并在那附近失去了最后一面旗帜。\n\n最棘手的，是奥特兰克进攻激流堡时遗失的那面旗帜。那已经是很久以前的事了，也许几乎没有什么旗帜残片可找，但我相信托尔贝恩家族会把它当成古老宿怨的战利品保存在某处。\n\n如果你能找到这些旗帜，我们就能打击辛迪加的计划。把它们带给赫尔姆斯沃西少校保管。辛迪加显然正在监视我。",
  },
  [26792] = {
    ["T"] = "失落的旗帜",
    ["O"] = "把赫尔姆斯沃西少校的补偿金带给暴风城港口的德里克·布拉德福德。",
    ["D"] = "还有一件收尾的事，$C。德里克一家在火灾中失去了一切。我希望你把这笔补偿金带给他。他不会愿意接受施舍，但你要坚持说这是为了感谢他协助找回旗帜而支付的报酬。这样他应该就会愿意收下。\n\n祝他在南方的新生活顺利。告诉他，下次我休假时会去看他。",
  },
  [26793] = {
    ["T"] = "失落的旗帜",
    ["O"] = "与暴风城港口的侦探马洛谈一谈。",
    ["D"] = "侦探马洛不止一次来查看情况。你介意告诉他，他可以结案了吗？\n\n旗帜已经安全，辛迪加也没有理由继续监视我了，所以军情七处可以去处理其他更重要的事。\n\n如果辛迪加还是来找我，嗯，我现在已经有所准备了。",
  },
  [26794] = {
    ["T"] = "通缉：大蓝",
    ["O"] = "把大蓝的翅膀带给艾尔文森林阿祖拉之塔的金杰·麦格宾斯。大蓝只会在夜里出现。",
    ["D"] = "阿祖拉之塔的大法师们固然聪明绝顶，但他们对风险的管控嘛……实在不怎么样。\n\n倒霉的是，有只蝴蝶离某位大师的实验太近了些，结果变异成了一头彻底失控的怪物。\n\n它几乎每天夜里都会来糟蹋我们的花园，连我们的食物品质都因此受了影响！\n\n去收拾掉那头怪物，然后把它的翅膀带给阿祖拉之塔的金杰·麦格宾斯！它最后一次出现，是在阿祖拉之塔东北方、石碑湖沿岸一带。",
  },
  [26795] = {
    ["T"] = "失踪的战士",
    ["O"] = "在敦霍尔德城堡寻找托格萨的踪迹。你记得克鲁斯克说过，他可能在下水道里。",
    ["D"] = "我和我的兄弟托格萨奉大酋长之命，前往敦霍尔德城堡取回一件物品，并调查控制那里的所谓“辛迪加”。\n\n我们去了敦霍尔德四处查看，却被一大群人类打了个措手不及。我们英勇奋战，但他们人数实在太多，最终压倒了我们。\n\n我设法逃了出来，可我的兄弟就没那么幸运。我看见他们把他拖进城堡东侧、被他们当作监狱使用的下水道。\n\n你愿意去找找他吗，$N？如果能把我的兄弟带回来，我会永远感激你。",
  },
  [26796] = {
    ["T"] = "失踪的战士",
    ["O"] = "从敦霍尔德下水道的典狱官埃斯顿身上取得埃斯顿的钥匙，然后回到托格萨那里。",
    ["D"] = "真不敢相信有人来了！是我兄弟派你来的吗？\n\n你来了我就放心了，可这些镣铐还锁在我身上，我哪儿也去不了。镣铐钥匙在典狱官埃斯顿手里。我刚看见他去了下水道另一头。\n\n去拿到他的钥匙……必要时就动用武力。我不想死在这里！",
  },
  [26797] = {
    ["T"] = "失踪的战士",
    ["O"] = "和托格萨一起逃离敦霍尔德城堡。成功后，向塔伦米尔的克鲁斯克报告。",
    ["D"] = "该离开这里了，$N。不过先提醒你，这些该死的辛迪加一定会拼命阻拦！\n\n现在跟紧，我们不能走散。我已经等不及要看看我回到兄弟面前时，他脸上会是什么表情了。",
  },
  [26798] = {
    ["T"] = "斥候急需援手",
    ["O"] = "收集10块辛迪加护甲碎片，然后回到南海镇的萨伦队长那里。",
    ["D"] = "你好，$N！我现在急需帮助。我派了一名斥候去监视东北方的敦霍尔德城堡；那座要塞最近被辛迪加组织占据了。可是那名斥候一直没有回报。我担心最坏的情况已经发生，而作为队长，我有责任弄清他出了什么事。\n\n辛迪加成员在城堡里越聚越多，我不能冒险公开交战。这次行动需要隐秘行事。\n\n城堡附近有一座废弃的塔楼，我听说一些低阶辛迪加把那里当作据点。收集一些他们的护甲，我们就能用它做一套伪装。要找到那座塔楼，就沿着南海镇北边的道路走。到岔路口后右转，继续向东走，直到你看见塔楼。",
  },
  [26799] = {
    ["T"] = "斥候急需援手",
    ["O"] = "穿上辛迪加伪装，找到敦霍尔德城堡里的斥候维尔纳多。",
    ["D"] = "好了，$N，该做点潜入工作了。我要你穿上这套伪装，直接进入敦霍尔德城堡。我听说辛迪加把下水道系统当成监狱，它就在城堡东侧。你很可能在那里找到我们失踪的斥候。\n\n穿上伪装后，尽量别对辛迪加表现得太咄咄逼人；我对这套伪装能不能经受压力并没有十足把握。要是你还需要一套，就来找我。我也许能修补一下。\n\n要找到敦霍尔德城堡，只要从你取得护甲碎片的塔楼再往前走一小段就行。祝你好运！",
  },
  [26800] = {
    ["T"] = "斥候急需援手",
    ["O"] = "说服典狱官埃斯顿交出牢房钥匙，然后回到敦霍尔德城堡的斥候维尔纳多那里。",
    ["D"] = "是萨伦队长派你来的吗？很高兴你来了，可惜在我们弄掉这些镣铐之前，我哪里也去不了！\n\n钥匙在典狱官埃斯顿手里，他负责看守这些下水道。他刚离开，所以大概正在下水道另一头巡逻。\n\n告诉他，敦霍尔德的主人贝芙·匹瑞诺德要亲自审问我。你需要钥匙，好把我押送到城堡里。\n我敢肯定他会把钥匙给你，因为所有人都怕贝芙。拿到钥匙后快点回来，我们就能悄悄离开这里！",
  },
  [26801] = {
    ["T"] = "斥候急需援手",
    ["O"] = "和斥候维尔纳多一起逃离敦霍尔德城堡。成功后，向南海镇的萨伦队长报告。",
    ["D"] = "我们准备好逃出去了。一定要低调；就装作你本来就属于这里。\n\n在辛迪加看来，你只是在履行职责。我们就这样走出去时，他们不会怀疑什么。",
  },
  [26802] = {
    ["T"] = "毒液药剂",
    ["O"] = "收集8份苔藓毒液，然后回到南海镇的学徒霍尼韦尔那里。",
    ["D"] = "你好，$N。我搬到南海镇来深入研究炼金术，接下来想学习如何制作解毒药。\n\n我们有几位居民被蜘蛛咬伤后病倒了。你愿意替我收集它们的毒液吗？你可以在希尔斯布莱德各处找到蜘蛛。",
  },
  [26803] = {
    ["T"] = "破坏军械库",
    ["O"] = "从敦霍尔德城堡夺取10件敦霍尔德军备，然后回到南海镇的昆德里克·赞登那里。",
    ["D"] = "敦霍尔德城堡里的辛迪加很快就要成为大麻烦了。他们袭击旅人，又不断招募新成员，联盟居然还没向他们宣战，真叫人难以置信！\n\n保卫这片土地的责任落到了南海镇身上。我希望你前往城堡，偷走他们的军备。没了武器，他们的扩张就会暂时放慢。城堡就在这里东北方，沿路走就能找到。",
  },
  [26804] = {
    ["T"] = "烧成焦炭",
    ["O"] = "烧毁敦霍尔德城堡兵营里的辛迪加食物补给。完成后回到塔洛那里。",
    ["D"] = "我一辈子都住在塔伦米尔，$c。我可不打算眼睁睁看着它被一群暴徒毁掉。我说的当然是辛迪加。他们最近搬进了东南方的敦霍尔德城堡，还一直掠夺我们的农田粮食。\n\n我绝不容忍！是时候让他们尝尝自己的手段……或者说，尝尝没有粮食的滋味了。我要你烧掉他们的食物补给，那些东西就在他们的兵营里。\n\n一位朋友送过我一支永燃火炬。带上它，用它把他们的食物烧成焦炭。",
  },
  [26805] = {
    ["T"] = "装点旅店",
    ["O"] = "为南海镇的旅店老板安德森收集10张熊皮。",
    ["D"] = "我琢磨了一阵，决定该重新装点一下这家旅店了。我想在入口处铺一张地毯！\n\n我认识一位欠我人情的裁缝，所以你只需要替我弄到毛皮。这片土地上的熊应该正合适。",
  },
  [26806] = {
    ["T"] = "南海镇防务",
    ["O"] = "从丹加洛克的卫兵艾米莉、碧玉矿洞的卫兵帕克斯顿和希尔斯布莱德农场的卫兵特里斯坦那里收集报告，然后回到南海镇的萨伦队长那里。",
    ["D"] = "你好，$c。身为南海镇卫队的队长，我有责任确保这片土地安全。谁也不知道部落什么时候会决定在我们家门口开场派对。\n\n我需要有人从驻扎在希尔斯布莱德各处的卫兵那里带回报告。你可以在东南方的丹加洛克找到卫兵艾米莉，在正西方碧玉矿洞外找到卫兵帕克斯顿，在西北方农场镇政厅附近找到卫兵特里斯坦。\n\n去这里的马厩找达伦，说是我派你来的。他应该会借你一匹马办事。我就指望你了，$N！动作要快，我可不喜欢等人。",
  },
  [26809] = {
    ["T"] = "南海镇防务",
    ["O"] = "",
    ["D"] = "",
  },
  [26810] = {
    ["T"] = "南海镇防务",
    ["O"] = "把青铜、铁、钢和幽触军备箱带给希尔斯布莱德丘陵南海镇的萨伦队长。",
    ["D"] = "好嘞，这是一箱用你带来的那种幽灵矿石打造的各式武器。这并不完全是我想要的结果，这材料密度太低，做几把简单刀刃耗掉的矿石比我预想得多得多。 \n\n我本不想这么做，但那边那些箱子也一起带走吧。里面装着青铜、铁和钢制军备，本来是要运到热砂港出售的。南海镇更重要。现在快去！",
  },
  [26811] = {
    ["T"] = "南海镇防务",
    ["O"] = "与南海镇西北方希尔斯布莱德农场的卫兵特里斯坦谈一谈。",
    ["D"] = "我们会立刻开始分发这些武器。与此同时，希尔斯布莱德农场需要你。我们收到了一份请求增援的信，不过从信上看，似乎并不是为了抵御迫在眉睫的入侵。我们要忙着准备南海镇的防务，所以你代我们前去，看看那里需要做些什么。\n\n到达农场后，去镇政厅附近找卫兵特里斯坦。如果你忘了位置，就从南海镇出发沿路走，然后径直向西，就能抵达农场。祝你一路顺利，$N。",
  },
  [26812] = {
    ["T"] = "一日一苹果",
    ["O"] = "在希尔斯布莱德农场的果园里收集苹果，然后带到农场北端藤架下的苹果压榨机处压成苹果酒。之后，把苹果酒倒进压榨机旁的木桶里。",
    ["D"] = "考虑到我们请求的是援军，这项任务也许显得奇怪，但食物和水对我们的安全几乎和武器护甲一样重要。希尔斯布莱德农场是苹果和苹果酒的重要产地，可因为部落袭击，我们已经落后进度了。\n\n到果园里收集一些苹果，然后去农场北端藤蔓棚下的苹果压榨机那里做些苹果酒。做完后把它存进木桶里。别担心，你的时间会得到报酬。",
  },
  [26813] = {
    ["T"] = "挡住部落",
    ["O"] = "在希尔斯布莱德农场外围杀死6名部落斥候。完成后向希尔斯布莱德丘陵希尔斯布莱德农场的卫兵特里斯坦报告。",
    ["D"] = "部落斥候已经多次出现在我们农场外围。我不确定他们是想被人发现，还是单纯不擅长干斥候的活，但无论如何，都必须处理掉他们。你若能杀掉几个斥候，其他人也许就会想逃走，或者回去报告说希尔斯布莱德农场并不是那么容易下手的目标。\n\n祝你好运。",
  },
  [26814] = {
    ["T"] = "冲突之地",
    ["O"] = "在希尔斯布莱德农场内杀死1名部落玩家。",
    ["D"] = "巡逻时留意部落冒险者。他们偶尔会出现在这一带，屠杀我们的部队和农夫。与他们交战并消灭他们，是你的职责。如果你成功办到，就回来向我报告。",
  },
  [26815] = {
    ["T"] = "南海镇防务",
    ["O"] = "与希尔斯布莱德丘陵南海镇的萨伦队长谈一谈。",
    ["D"] = "很抱歉让他们把你派到这里来。我原本希望来的是更多卫兵。没想到派来的是有你这般本事的人，我想你最好回南海镇，把这一点转告给萨伦队长。\n\n我下次写报告时一定会替你美言几句。祝你今后的冒险顺利，$N。",
  },
  [26816] = {
    ["T"] = "南海镇防务",
    ["O"] = "与希尔斯布莱德丘陵南海镇的南海镇传令官谈一谈，保卫南海镇，抵御即将到来的部落进攻。",
    ["D"] = "可靠的报告告诉我们，部落很快就会发动进攻。现在该让我们的准备接受考验了！\n\n做好你需要的一切准备：召唤法术、武器磨砺，或是魔法强化。准备好后，就去我们的狮鹫管理员达拉附近找南海镇传令官报到。为了联盟！",
  },
  [26817] = {
    ["T"] = "未竟的正义",
    ["O"] = "在奥特兰克山脉洛丹米尔湖岸边的房子里找到“爷爷”保罗·维沙斯，将他绳之以法。",
    ["D"] = "我成为镇长时，发现还有一张保罗·维沙斯的未执行通缉令。显然，维沙斯因近二十年前犯下的一桩谋杀案而被通缉。我不知道为什么这张通缉令从未执行；这些年来，保罗·维沙斯一直有人在这一带见过。\n\n他的儿子西德尼在洛丹米尔湖岸边有座房子。也许维沙斯就藏在那里？ \n\n请去逮捕他，$C。如果他不肯乖乖就范，你可以自行伸张正义，把这桩旧案从案卷上了结。",
  },
  [26819] = {
    ["T"] = "清除狮患",
    ["O"] = "杀死10头饥饿的山地狮，然后回到南海镇的雷德帕斯元帅那里。",
    ["D"] = "你来得正好，$c。最近这一带的山地狮变得越来越躁动，还伤了好几个居民。必须采取行动！\n\n我要你清理本地的狮群，让南海镇的居民重新安全起来。它们通常就在这里北边游荡。",
  },
  [26820] = {
    ["T"] = "希尔斯布莱德突袭",
    ["O"] = "在中央哨塔由联盟控制时占领它。",
    ["D"] = "希尔斯布莱德中央的哨塔，是部落控制这片土地的关键。女妖之王亲自下令：只要联盟夺下它，我们就必须立刻夺回来。\n\n集结你的部队，$n，按她的命令行事。",
  },
  [26821] = {
    ["T"] = "希尔斯布莱德防御",
    ["O"] = "在中央哨塔由部落控制时守住它。",
    ["D"] = "希尔斯布莱德中央的哨塔，是部落控制这片土地的关键。女妖之王亲自下令：只要联盟试图夺取它，我们就必须不惜一切代价守住它。\n\n集结你的部队，$n，按她的命令行事。",
  },
  [26822] = {
    ["T"] = "希尔斯布莱德突袭",
    ["O"] = "在中央哨塔由部落控制时占领它。",
    ["D"] = "希尔斯布莱德中央的哨塔，是联盟控制这片土地的关键。普瑞斯托女士亲自下令：只要部落夺下它，我们就必须立刻夺回来。\n\n集结你的部队，$n，按她的命令行事。",
  },
  [26823] = {
    ["T"] = "希尔斯布莱德防御",
    ["O"] = "在中央哨塔由联盟控制时守住它。",
    ["D"] = "希尔斯布莱德中央的哨塔，是联盟控制这片土地的关键。普瑞斯托女士亲自下令：只要部落试图夺取它，我们就必须不惜一切代价守住它。\n\n集结你的部队，$n，按她的命令行事。",
  },
  [26824] = {
    ["T"] = "通缉：大法师齐格尔",
    ["O"] = "杀死敦霍尔德城堡里的大法师齐格尔。回到塔伦米尔的高级执行官达萨利亚那里领取奖赏。",
    ["D"] = "奉希尔瓦娜斯女士之命，名为齐格尔的大法师必须立刻处决。齐格尔犯有训练并指导一个名为辛迪加的危险组织使用黑暗魔法之罪。\n\n他就在敦霍尔德城堡里，很可能待在法师塔中。凡能把战绩证明带给高级执行官达萨利亚的人，都将获得丰厚奖赏。",
  },
  [26825] = {
    ["T"] = "辛迪加魔法",
    ["O"] = "收集5颗辛迪加宝珠，然后回到南海镇的菲恩·奥德利克那里。",
    ["D"] = "我研究魔法之艺，并且始终渴望了解更多。镇长认为辛迪加正在使用黑暗魔法推动他们的邪恶计划，但我对此有所怀疑。\n\n你愿意去敦霍尔德城堡，给我带一些他们法师使用的宝珠回来吗？城堡就在这里东北方，不过要小心……我听说那里守卫森严。",
  },
  [26826] = {
    ["T"] = "辛迪加人员",
    ["O"] = "杀死5名辛迪加潜行者和5名辛迪加巡路者。完成任务后，回到塔伦米尔的高级执行官达萨利亚那里。",
    ["D"] = "黑暗女王已经下令消灭辛迪加的所有成员。他们是一群危险的暴徒，专门欺凌弱者、四处劫掠。\n\n他们有一伙人正占据着东南方的一座塔楼。沿路向南走，在岔路口左转，你就会找到那座塔。尽可能多杀一些，$N——谁知道他们在谋划什么。",
  },
  [26827] = {
    ["T"] = "肃清敦霍尔德",
    ["O"] = "杀死10名辛迪加工头和10名辛迪加监工。完成任务后，回到塔伦米尔的高级执行官达萨利亚那里。",
    ["D"] = "我还有一项任务给你，$n。辛迪加现在控制了东南方的敦霍尔德城堡。让这片土地免受暴徒威胁，是部落的首要任务，所以我们必须清除他们的污秽。\n\n要找到敦霍尔德城堡，就经过你之前找到的塔楼，再继续往前走一段。城堡就在同一条路上。",
  },
  [26828] = {
    ["T"] = "泥嘴药剂",
    ["O"] = "收集8份泥嘴脓液，然后回到南海镇的南达尔·布兰森那里。",
    ["D"] = "搬进敦霍尔德城堡的辛迪加以劫掠我们的农田而臭名昭著，必须有人处理这事。我担心南海镇卫兵的努力还不够，所以决定借鉴被遗忘者的手段，给辛迪加的食物补给下毒！\n\n我知道这听起来很严酷，但非常时期就得用非常手段。如果你愿意帮我，我需要东边奈杉德哨岗那些豺狼人身上的脓液，就在河对岸。拿到之后，我就能调制出一种有效的毒药，拖慢辛迪加的行动！",
  },
  [26829] = {
    ["T"] = "给辛迪加下毒",
    ["O"] = "毒害敦霍尔德城堡里的辛迪加食物补给，然后回到南海镇的南达尔·布兰森那里。",
    ["D"] = "毒药已经准备好了，$N，我只需要有人去投放。敦霍尔德城堡就在这里东北方，沿路走就不会错过。不过要小心，辛迪加非常重视他们的据点，最好带上朋友一起去。\n\n进去以后，寻找他们的兵营。我相信你会在里面找到他们的食物补给。只要把毒液撒在补给周围，然后回到这里来。",
  },
  [26830] = {
    ["T"] = "通缉：贝芙·匹瑞诺德",
    ["O"] = "杀死贝芙·匹瑞诺德，并把她的头颅带给南海镇的萨伦队长。",
    ["D"] = "奉南海镇萨伦队长之命，贝芙·匹瑞诺德已被判处死刑。她是危险的罪犯，也是敦霍尔德城堡的监掌者，以铁腕控制着这片土地上的辛迪加。\n\n她很可能位于城堡要塞深处，而城堡就在南海镇东北方。把她的头颅带给萨伦队长，即可领取奖赏。",
  },
  [26831] = {
    ["T"] = "辛迪加计划",
    ["O"] = "把辛迪加计划交给南海镇的萨伦队长。",
    ["D"] = "你注意到一封信从贝芙·匹瑞诺德的口袋里掉了出来。它看起来很重要，已经封好，并写明收信人为奥里登·匹瑞诺德领主。\n\n南海镇的萨伦队长一定会对这封信很感兴趣，因为它可能详述了辛迪加后续的计划。",
  },
  [26832] = {
    ["T"] = "辛迪加计划",
    ["O"] = "把辛迪加计划交给塔伦米尔的高级执行官达萨利亚。",
    ["D"] = "你注意到一封信从贝芙·匹瑞诺德的口袋里掉了出来。它看起来很重要，已经封好，并写明收信人为奥里登·匹瑞诺德领主。\n\n塔伦米尔的高级执行官达萨利亚一定会对这封信很感兴趣，因为它可能详述了辛迪加后续的计划。",
  },
  [26833] = {
    ["T"] = "野棘疗药",
    ["O"] = "从灰谷的蜘蛛身上收集8份野棘药膏，然后回到南海镇的珍娜·雷酒那里。",
    ["D"] = "我的丈夫病得很重，$N。我试过所有知道的疗法，可什么都治不好他。\n\n前些时候，有个旅人路过这里，跟我说起远方某片土地上的蜘蛛。它们能分泌一种药膏，连最严重的创伤都能治愈。\n\n他说那些蜘蛛叫野棘，潜伏在灰谷——卡利姆多那片遥远大陆上的土地。我知道这要求太过分了，但如果你前往卡利姆多，能不能替我带些野棘药膏回来，好让我治好我的丈夫？",
  },
  [26834] = {
    ["T"] = "援助珍娜",
    ["O"] = "在希尔斯布莱德丘陵找到珍娜·雷酒。",
    ["D"] = "我收到了我们本地治疗者珍娜·雷酒的一封急信。她说她的丈夫病倒了，急需帮助。\n\n南海镇会帮助自己的居民，所以我需要你去看看她。她住在这里正西方一片林间空地的小屋里。",
  },
  [26851] = {
    ["T"] = "莫甘斯的情报",
    ["O"] = "把这张便笺交给艾尔文森林阿祖拉之塔的塞欧克瑞图斯。",
    ["D"] = "你好啊，朋友！看到这些锁链，你可能会以为我把自己搞进了天大的麻烦里！不过，其实一切都完全在计划之中！你看，我只要偷听周围那些兽人的谈话，就能弄到不少关于莫甘斯的宝贵情报。哈！是不是很天才？\n\n主人一定很想知道我目前发现了什么。趁我继续设法挖出更多消息的时候，请你先替我把这些笔记带给他吧。我相信，他一定会好好酬谢你的效劳！",
  },
  [26891] = {
    ["T"] = "掠取暗礁",
    ["O"] = "从邪恶暗礁内的沉船中收集10件浸水武器。",
    ["D"] = "格罗姆高周围的海域被称作邪恶暗礁。那是一片危险的水域，但曾经有一条走私者用来穿行的航线，他们想赚快钱，把货物从藏宝海湾运进暴风城。然而，大海是位残酷的女主人，不是所有人都能抵达。\n\n海底躺着各种沉船，里面有些武器我可以熔掉重铸，为部落所用。给我带回10件这样的武器，好让我武装我们的部队。",
  },
  [26968] = {
    ["T"] = "天灾植物学",
    ["O"] = "从北山伐木场的土堆中取得一份纯净的艾尔文土壤样本。",
    ["D"] = "有意思。你带回来的样本，比我原以为天灾瘟疫造物该有的性质脆弱得多。这意味着课程计划得改一改。\n\n达尔松之泪北边北山伐木场里的那群血色蠢货，特地从艾尔文森林运来了一大堆泥土，妄想用它重新种出健康的树木。我会先把真菌样本种在本地这片恶臭得恰到好处的土壤里，不过我也很想看看，要是把样本种进从艾尔文运来的土里，会发生什么。给我带一些来！",
  },
  [26987] = {
    ["T"] = "回家",
    ["O"] = "从迪菲亚身上找回南希的辫子，把它拿给唐纳德·伊斯特沃斯看，尽量说服他回到家人身边。",
    ["D"] = "请等一下！你能留一会儿吗？\n\n真抱歉，我女儿刚才有点……紧张。自从迪菲亚出现以后，我们就一直过得提心吊胆。你敢相信吗？我丈夫唐纳德竟然抛下了他心爱的农场和家人，跑去加入他们了！？他怎么能丢下我和小蒂娜？\n\n我试着劝他回心转意，可他那些新朋友后来找上了门。我们当时吓坏了！他们倒是没伤害我的女儿，可是……他们割掉了我的头发，还把我们赶出了农场。他们这么做，就是为了给我一个警告。我永远忘不了他们羞辱我时眼里那种掠食者般的神情。他们把我的辫子当成战利品带走，还警告我，要是我再插手，就不会只是这样了。\n\n从那以后，我只零零碎碎听到过一些关于我丈夫的传闻。有人说，他专门袭击从暮色森林前往月溪镇的倒霉商人。求你了，试着劝那个老糊涂回到我们身边吧。我们已经无家可归了，而唐纳德那些新同伙如今就像秃鹫一样，正围着哨兵岭打转！也许你能从某个迪菲亚身上找到我的辫子，把它拿给我丈夫看看，让他明白他那些新朋友究竟能做出什么事。",
  },
  [26988] = {
    ["T"] = "顽固的男人",
    ["O"] = "与南希·伊斯特沃斯谈一谈。",
    ["D"] = "有句老话说得好：既然打不过他们，那就加入他们。暴风城那些官老爷根本不在乎西部荒野的百姓，所以我们只能自己动手。没错，这里是有人民军，可我如今是替这里真正掌权的人办事。\n\n听着，再过几个星期，我赚到的钱就足够去南海镇租……不，是盖一座房子了。我必须冒这个险，南希也该接受这一点——顺便对迪菲亚多表现出一点尊重。\n\n不过你告诉她，我很想她。我爱她们，我很快就会回去。等我回去的时候，我们就把过去的一切抛在身后，也把这该死的红面罩一并丢掉！\n\n现在，让我清静点吧。听说很快会有个地精商人从桥那边经过。到时候你最好别待在这儿。",
  },
  [26989] = {
    ["T"] = "断指为戒",
    ["O"] = "把唐纳德带血的拇指交给南希·伊斯特沃斯。",
    ["D"] = "我不会再继续等那个老蠢货为了几个铜板，把我们所有人的命都搭进去。\n\n先是我的辫子，再下一次，说不定架在我喉咙上的就是刀子，甚至更糟！噢，圣光啊，请指引我们吧！黑暗的日子就要到了，我们需要光明。\n\n蒂娜和我现在就得学会坚强，学会独立。我们要继续往前走，就算我得把她扛在肩上穿过黑石山，我们也必须离开这一切。可为了保住我们的将来，我还想求你最后一件事。给唐纳德一个他永远忘不了的教训。\n\n狠狠揍他一顿，就像迪菲亚威胁要对我做的那样。把他那根好像巴不得丢掉的拇指带给我。也不用……你知道的，杀了他。打断他几根骨头就够了。只要确保他没法跟上我们——不管他走到哪里，霉运就跟到哪里。",
  },
  [26990] = {
    ["T"] = "河爪横行",
    ["O"] = "杀死8个河爪豺狼人和8个河爪斥候，然后回到哨兵岭的守卫者加瑞尔那里。",
    ["D"] = "人民军需要帮助！河爪豺狼人正在袭击西部荒野的居民！暴风城没有派来任何援军，我们只能靠自己保卫家园。要是你愿意协助我们，就请带头对那些豺狼人发起反击。\n\n你可以在北边找到他们的一些营地，靠近詹戈洛德矿洞和法布隆南瓜农场。西部荒野会非常感激你的帮助。现在就去，结束这些怪物的祸害吧！",
  },
  [26991] = {
    ["T"] = "河爪横行",
    ["O"] = "杀死8个混血河爪豺狼人和8个河爪草药师，然后回到哨兵岭的守卫者加瑞尔那里。",
    ["D"] = "你以为自己的活已经干完了？差得远呢……豺狼人的营地遍布整个西部荒野。我感激你先前的帮助，但可别太得意。还有更多豺狼人等着被收拾。\n\n去金海岸矿洞以南，把更多豺狼人从西部荒野赶出去吧。你会找到一些由他们氏族里更强成员把守的营地。希望你能胜任这份差事——我可不想看见你把命丢在那儿。",
  },
  [26992] = {
    ["T"] = "河爪横行",
    ["O"] = "杀死8个河爪强盗和8个河爪监工，然后回到哨兵岭的守卫者加瑞尔那里。",
    ["D"] = "真没想到你还活着。我还以为那些豺狼人会宰了你！不管怎么说，我的斥候回报，一些最强壮的河爪豺狼人已经在南边的尘埃平原扎营了。我真希望能抽出些士兵陪你一起去，可我们的兵力太分散。你只能独自前往。\n\n以人民军之名，去把正义带给那些豺狼人吧！西部荒野再也不能容忍他们了！",
  },
  [26993] = {
    ["T"] = "杀戮农田",
    ["O"] = "杀死10个生锈的麦田傀儡，然后回到贾森农场的农夫法布隆那里。",
    ["D"] = "看看这片土地都成什么样了！该死的迪菲亚兄弟会，居然让他们那些地精造出这些机械怪物，再把它们放到农田里来撒野！我们农夫从没想过要过这种日子。要是这些傀儡还赖在这里，我还怎么养活家里人和可怜的老杂斑？\n\n你能帮忙清理一下附近的傀儡吗？它们就在这附近，往西到我的南瓜农场那边也有。求你帮帮我们吧！暴风城已经不管我们了。",
  },
  [26994] = {
    ["T"] = "杀戮农田",
    ["O"] = "与萨丁农场的农夫萨丁谈一谈。",
    ["D"] = "你把这附近的傀儡收拾得很不错，不过遇到这麻烦的可不只我一个。我的老朋友萨丁也告诉我，那些傀儡正在毁掉他的农场。你愿意去帮帮他吗？你会在这儿南边找到他的农场。",
  },
  [26995] = {
    ["T"] = "杀戮农田",
    ["O"] = "杀死10个麦田傀儡，然后回到萨丁农场的农夫萨丁那里。",
    ["D"] = "很高兴看到有人肯来帮忙。这些傀儡把我们的乡亲都吓跑了，要是再不尽快解决，我担心西部荒野迟早会被迪菲亚兄弟会彻底占去。总之，出去多干掉些傀儡吧！你可以在这座农场里找到一些，西边的莫尔森农场也有。",
  },
  [26996] = {
    ["T"] = "杀戮农田",
    ["O"] = "杀死10个看守傀儡，然后回到萨丁农场的农夫萨丁那里。",
    ["D"] = "你之前杀掉的那些傀儡并不是唯一在糟蹋我们土地的东西！我有个农夫说，他在靠近金海岸矿洞的阿历克斯顿农场那边又看见了一些。要是你不介意再去杀掉一些傀儡，我们一定会非常感激你的帮助。",
  },
  [26997] = {
    ["T"] = "杀戮农田",
    ["O"] = "杀死10个收割傀儡，然后回到萨丁农场的农夫萨丁那里。",
    ["D"] = "我们大多数农场都已经夺回来了，但还有最后一片农地需要争夺。沿着哨兵岭继续往南走，你会找到死亡农地，那里游荡着最强大的傀儡，把土地烧得一片焦黑。我曾带着几个工人去过，可那些傀儡把我们赶了回来！希望你能应付得来，$n，这些傀儡可不是闹着玩的！",
  },
  [26998] = {
    ["T"] = "通缉：劫掠者格纳方",
    ["O"] = "杀死劫掠者格纳方，把它的爪子交给哨兵岭的丹努文队长。",
    ["D"] = "西部荒野的居民们，注意了！一个名叫劫掠者格纳方的危险豺狼人，已经把四散的河爪氏族重新集结起来，在我们的土地上横行肆虐，劫掠农场，袭击百姓！\n\n我们需要像你这样的勇敢冒险者来终结它的暴行。人们知道格纳方常在哨兵岭南边的丘陵间出没。把它的爪子带给哨兵岭的丹努文队长，作为你英勇无畏的证明，你将得到丰厚的奖赏。",
  },
  [27207] = {
    ["T"] = "我的妹妹伊莎贝塔",
    ["O"] = "前往西部荒野，把火灾与伊莎贝塔·惠兰之死的消息告诉伊万杰琳·惠兰。",
    ["D"] = "这……这是迪菲亚面罩上的一块碎布，我敢拿命担保。几乎可以肯定，这就是迪菲亚干的——那群在暴风王国境内四处恐吓平民的暴徒和恶棍。他们一路跟着我们……他们是想传递一个信息。\n\n我也必须传出我的消息。要是你愿意，就把这封信带给我们的另一位姐妹伊万杰琳。她在西部荒野的民兵队里效力，知道一些迪菲亚绝不愿让别人知道的事。要是他们为了伊莎贝塔一路追到黑海岸，那伊万杰琳的性命如今也有危险。\n\n这趟路很远，$C，但第一步就是先从这里坐船去米奈希尔港。",
  },
  [27208] = {
    ["T"] = "我的妹妹伊莎贝塔",
    ["O"] = "在金海岸矿洞杀死奥马尔·多恩，把他的迪菲亚钥匙带给西部荒野的伊万杰琳·惠兰。",
    ["D"] = "迪菲亚竟然一路追到黑海岸，烧了伊莎贝塔的房子，还杀了她？天啊！\n\n<伊万杰琳神情一震，接着眼中闪过一阵决意。>\n\n对不起，$C。你卷进了一场比你所知更大的风波里。而且，我需要帮助，只是我现在还不知道能不能信任你。\n\n如果你真想帮忙，愿不愿先替我办件事？有个迪菲亚副官把金海岸矿洞当成了老巢，就在这条路往西更远的地方。他叫奥马尔·多恩。干掉他，把他身上的钥匙带回来给我。",
  },
  [27209] = {
    ["T"] = "我的妹妹伊莎贝塔",
    ["O"] = "用迪菲亚钥匙打开藏在月溪镇的迪菲亚保险箱，把里面找到的东西带给西部荒野的伊万杰琳·惠兰。",
    ["D"] = "月溪镇曾经是一座繁荣的小镇。如今那里却成了盗匪窝，成了迪菲亚同情者的据点。\n\n月溪镇某处藏着一个保险箱，里面保管着一些文件。你从奥马尔·多恩身上找来的这把钥匙，应该能打开它。我希望你把里面的文书都带回来给我——至于其他东西，我就让你自己留下。",
  },
  [27210] = {
    ["T"] = "隐秘记录",
    ["O"] = "把伊万杰琳的便笺带给暴风城教堂广场的巴隆斯·阿历克斯顿。",
    ["D"] = "看看这个，$N？这是迪菲亚拼命想掩盖的秘密，一个与我妹妹有关的秘密。\n\n你看，伊莎贝塔曾是许多同情迪菲亚的人之一。说到底，他们对暴风城贵族的怨恨并非全无道理。可当迪菲亚开始在西部荒野、就在我们家门口恐吓普通百姓时，她就离开了他们。\n\n也是在离开之后，她才发现自己怀了孩子。\n\n这是她女儿出生证明的唯一一份副本。我想请你把它带去暴风城，交给一位老朋友代为保管。他叫巴隆斯·阿历克斯顿，是暴风城的城市建筑师。你可以在大教堂附近找到他。",
  },
  [27211] = {
    ["T"] = "隐秘记录",
    ["O"] = "把出生证明交给暴风城的皇家代理人巴瑟罗尔。",
    ["D"] = "<巴隆斯·阿历克斯顿飞快扫过那张便笺和出生证明。>\n\n这么说来，我的老朋友艾德温·范克里夫和伊莎贝塔·惠兰有个女儿。要是暴风城的贵族知道这件事，他们一定会设法把那孩子夺过去，当成人质。可显然，伊莎贝塔也不愿把自己的女儿交到艾德温手里。伊万杰琳请我帮她在两边之间走这条险路。\n\n接下来该怎么办，我还拿不准，不过我们至少可以先把这份记录正式登记存档。负责登记的人就在这栋楼楼上。要是你愿意替我把它交给他，也许等你回来时，我已经想到下一步了。",
  },
  [27212] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "回到西部荒野，向守卫者伊万杰琳复命。",
    ["D"] = "伊万杰琳在便笺里说，她现在也不知道瓦妮莎在哪里。回去告诉她，我会尽我所能帮她寻找瓦妮莎。\n\n出生证明上列出的见证人是艾德娜·莫尔森——范克里夫的姨妈。我已经很多年没见过她了。她们以前很亲近。要是她还活着，也许会知道更多消息。",
  },
  [27213] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "前往死亡农地，寻找任何有关艾德娜·莫尔森下落的线索。",
    ["D"] = "巴隆斯提出去找艾德娜·莫尔森，这主意不错，可正如他说的，我也有很多年没见过她了。\n\n她丈夫去世后，她搬到了暮色森林边界河畔的一座小农场。早在迪菲亚搬来之前，那座农场就已经经营不善，后来她也离开了。如今那里被叫作死亡农地。\n\n值得去那里看看。说不定还能找到她去了哪里的线索。有什么发现就回来告诉我。",
  },
  [27214] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "回到西部荒野，向守卫者伊万杰琳复命。",
    ["D"] = "“shire”可能指暴风王国里的好几个镇子。这个线索虽然单薄，但看起来已经是那座废弃农场里剩下的唯一头绪了。\n\n伊万杰琳·惠兰会想知道这件事的。",
  },
  [27215] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "去闪金镇、湖畔镇和夜色镇的旅店打听，看看能否找到艾德娜·莫尔森下落的线索。",
    ["D"] = "“shire”这个词？就只有这个？好吧，我想这总比什么都没有强。\n\n希望你有双结实的靴子，$N。你只能跑一趟附近几个镇子了——去闪金镇、湖畔镇和夜色镇看看，问问有没有人见过艾德娜·莫尔森。",
  },
  [27216] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "与暴风城教堂广场的皇家代理人巴瑟罗尔谈一谈。",
    ["D"] = "我第一次见到艾德娜·莫尔森是在两年前。她当时在暮色森林买了些产业，可后来一直没有搬进去，那座农场也就这样慢慢荒废了。\n\n我相信她一年多前就回暴风城了。她当时收到一封和外孙女有关的紧急传唤——唉，可怜的人，似乎是家里的纠纷。\n\n不过我记得她在暴风城应该还有亲戚。管户籍登记的人说不定会知道。",
  },
  [27217] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "在暴风城找到史蒂文·莫尔森。",
    ["D"] = "你是在城里的记录里找艾德娜·莫尔森？嗯，这个名字我没什么印象。不过城里倒是有个史蒂文·莫尔森。至少，有时候会在城里。他算是个……四处漂泊打零工的人。我也不确定他现在在哪。\n\n你去找史蒂文的时候，我会替你把记录再仔细翻一遍。等你回来，我会告诉你有没有查到艾德娜的消息。",
  },
  [27218] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "去暮色森林乌鸦岭的旅店弄一瓶乌鸦岭黑啤。",
    ["D"] = "艾德娜？是啊，我认识艾德娜。她是我……*嗝*……姐姐。\n\n你该不会是迪菲亚的人吧？\n\n<史蒂文打了个酒嗝。>\n\n不，你看着不像。你是想知道她在哪，对吧？那好，只要你先替我办件小事，我就告诉你。\n\n以前乌鸦岭有家热闹得很的旅店，就在从西部荒野过桥进暮色森林后不远。那里的酒好得很，我现在还惦记着。去那地方的废墟里替我翻一瓶出来，行吗？等你回来，我就把你想知道的告诉你。",
  },
  [27219] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "在暮色森林的腐草农场找到艾德娜·莫尔森。",
    ["D"] = "艾德娜以前在暮色森林那边买了块地，就是老腐草农场……*嗝*。她把那地方给了我们那个倒霉外甥艾德温用。她原本希望他有了自己的落脚处，就能别再往歪路上走。\n\n<史蒂文的神情清醒了些。>\n\n没用。\n\n几个星期前，艾德温捎信给艾德娜，要她到那农场去见他。从那以后我就再没见过她。我早劝她别去。八成已经死了。你要是继续把鼻子伸进迪菲亚的事里，你多半也会一样。",
  },
  [27220] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "杀死帕特里克·佩恩，把铁链钥匙带给暮色森林腐草农场的艾德娜·莫尔森。",
    ["D"] = "我会告诉你瓦妮莎后来怎么样了，但在那之前，求你先帮我摆脱这些锁链。\n\n腐草农场这里的迪菲亚头目是帕特里克·佩恩。想想看吧——他小时候，我还给他和他的朋友们烤过饼干呢，可他打我脑袋的时候可一点都没犹豫。\n\n他和这里其他迪菲亚一样擅长潜行，不过要是你能找到他，绑住我的钥匙就在他身上。",
  },
  [27221] = {
    ["T"] = "范克里夫姨妈",
    ["O"] = "回到西部荒野，向守卫者伊万杰琳复命。",
    ["D"] = "几个月前，艾德温的手下开始威胁伊莎贝塔。以前他从来没怎么在乎过自己的女儿，可后来却突然把“传承”挂在嘴边说个不停。\n\n伊莎贝塔把瓦妮莎托付给我，然后自己去了卡利姆多。我一直带着她四处躲藏。后来我们到了米奈希尔港，正准备前往塞拉摩，结果厄运还是找上了门。不知为什么，艾德温手下的几个人恰好在旅店里看见了我们。我也不知道他们为什么会在那里，但他们把瓦妮莎从我身边夺走了。我之所以来到腐草农场，就是希望能把她救回来。\n\n<艾德娜垂下了头。>\n\n我没能保护好她。我只能祈祷她父亲至少会善待她。可现在，我们也得离开这里了。我会走另一条路。祝你好运，$C，也谢谢你。",
  },
  [27222] = {
    ["T"] = "失而未忘",
    ["O"] = "与暴风城教堂广场的巴隆斯·阿历克斯顿谈一谈。",
    ["D"] = "就在你追查艾德娜下落的时候，艾德温已被几位勇敢的冒险者击败的消息也传开了。也许……你对此知道点什么？\n\n瓦妮莎当时并不在他身边。如今根本无从得知，迪菲亚残党把她藏在了什么地方。我除了等待新的线索出现之外，实在想不出别的办法。\n\n我最后还想求你一件事：回一趟暴风城，把发生的一切都告诉巴隆斯·阿历克斯顿。",
  },
  [26838] = {
    ["T"] = "体面的送别",
    ["O"] = "从银泉矿洞取回邦杜尔的遗骨，并将它们交给塞尔萨玛的亚尼·壮心。",
    ["D"] = "我的丈夫邦杜尔曾是北边银泉矿洞里的一名矿工。他是个体贴的男人，一直辛勤劳作，只为了养活家人。\n\n后来穴居人来了，他们对矿洞里的人毫不留情。我最亲爱的邦杜尔，就这样被撕成了碎片。\n\n我虽然已经接受了他的死讯，可他的遗骨至今还留在矿洞里。我希望能把他好好安葬在这里的墓地。\n\n你愿意帮一位悲伤的寡妇吗，$N？你能去银泉矿洞取回邦杜尔的遗骨，再把他安葬在塞尔萨玛的墓地里吗？",
  },
  [26839] = {
    ["T"] = "部落报告",
    ["O"] = "把部落报告带回塞尔萨玛，找一位会对其中内容感兴趣的人。",
    ["D"] = "你在那名被杀的兽人尸体上发现了这份看起来很正式的报告。你确定一定会有人想看看它的内容，但会是谁呢？\n\n塞尔萨玛里驻扎着不少铁炉堡卫兵，他们当中总会有一个人知道该如何处理这东西。",
  },
  [26840] = {
    ["T"] = "部落使者",
    ["O"] = "在侵扰洛克莫丹与湿地之间山道的龙喉兽人中找到那名部落使者并将其消灭。",
    ["D"] = "这份报告是写给一名我不熟悉的部落使者的，不过看起来，那小子正打算和搬进洛克莫丹与湿地之间丘陵地带的龙喉兽人做交易。你能想象吗？！部落都跑到我们家门口来了！\n\n我们绝不能让这笔交易谈成，$N。沿着通往湿地的道路向南走，在龙喉营地里找到那名使者。干掉他，别让他有机会把我们的弱点带回去报告！",
  },
  [26841] = {
    ["T"] = "失落的遗物",
    ["O"] = "从铁环挖掘场取回5件失落的遗物，并将它们交给洛克莫丹的奥德伦·科尔东。",
    ["D"] = "该死的穴居人，净会把事情搞得一团糟！在他们决定跑来这里之前，我们本来有一场完美的挖掘。为什么这种事总会落到我头上？\n\n我们撤离得太匆忙，把几件贵重的遗物留在了挖掘场里。这次挖掘可是麦格尼亲自下令的，要是这些遗物丢了，我们可就有大麻烦了！你愿意帮我们一个忙，把其中一些找回来吗？",
  },
  [26842] = {
    ["T"] = "药材补给",
    ["O"] = "从洛克湖采集8株洛克湖水草，然后交给塞尔萨玛的卡利。",
    ["D"] = "太好了，你来了，$N！我的药用补给快见底了，我需要帮忙。\n\n自从海兽变得愈发凶暴以后，长在水里的洛克湖水草就越来越难采了。守卫们都不肯冒险去洛克湖取药材。你够不够勇敢，愿不愿替我采一些回来，好让我补充药剂储备？",
  },
  [26843] = {
    ["T"] = "保卫洛克湖",
    ["O"] = "杀死10只幼年海兽，然后回到塞尔萨玛的巡山人奥兹莫克那里。",
    ["D"] = "是啊，$c，这里有活要干。我的职责是守卫这里，可不光得看着陆地，湖面也一样！\n\n洛克湖里现在有危险，而且已经给这一带带来了麻烦。栖息在洛克湖里的海兽近来变得越来越好斗，就好像有什么东西在暗中挑动它们似的。就在不久前，我们塞尔萨玛的一位居民还差点在钓鱼时被其中一只咬死！我要你去削减它们的数量，好让我们的人民能再次安稳地使用这片湖水。",
  },
  [26844] = {
    ["T"] = "奇怪的偶像",
    ["O"] = "把奇怪的偶像带给铁炉堡探险者大厅的勘察员塔伯斯·雷矛。",
    ["D"] = "我得研究这些偶像，弄清它们为什么会让穴居人发狂，可你看……这个偶像和其他的不一样。\n\n它有些不对劲。我说不清到底哪里不对。它看起来比其他偶像更新，可样式却相同，好像这处地点的使用时间比我们原先估计的还要更长。\n\n这超出了我的职权范围。你为什么不把它带回铁炉堡交给勘察员塔伯斯·雷矛呢？你也可以告诉他，在你的帮助下，我们现在已经取得了一些进展。",
  },
  [26845] = {
    ["T"] = "通缉：特萨之母",
    ["O"] = "杀死特萨之母，并把它的头带给塞尔萨玛的镇长埃罗恩·钝鼻。",
    ["D"] = "奉塞尔萨玛镇长之命：\n\n代号“特萨之母”的危险海兽目前在洛克湖游荡，现已被正式判处死刑。接连发生数起惨烈死亡事件后，在威胁解除之前，居民一律不得前往洛克湖钓鱼。\n\n想领取悬赏的冒险者请注意：特萨之母体型远比普通海兽更大，力量也更强。只要向塞尔萨玛的镇长埃罗恩·钝鼻证明它已被杀死，你就能得到奖赏。",
  },
  [26846] = {
    ["T"] = "各来一个",
    ["O"] = "杀死赤脊山每一种鱼人各一个。",
    ["D"] = "嘿，伙计！\n\n你也许不信，但我第一次猎杀成功就是在赤脊山这里。事实上，她现在就挂在我们头顶上！啊，真让人怀念……这也是我喜欢时不时回到这里的原因。当然，和我最近的胜利比起来，那算不了什么，但每个人总得有个起点！\n\n说到这个，如果你想证明自己，我这里有个挺有意思的挑战：试着确认你杀死过这一带所有不同种类的鱼人。这些滑溜溜的鱼人种类不少，要对付起来，多半也得各有各的办法。这正是证明你多才多艺的好机会！\n\n而且据报告说它们的数量正在增加，我相信你这么做也算是帮了镇上这些好人一把！\n怎么样，愿意接受挑战吗？",
  },
  [26847] = {
    ["T"] = "阿尔多的泥爪",
    ["O"] = "杀死阿尔多·泥爪，并把他的爪子带给湖畔镇的野牛威尔。",
    ["D"] = "又回来接受挑战了，嗯？那就坐稳了，伙计，因为这家伙可不是随便糊弄两下就会倒下的！\n\n他叫阿尔多·泥爪，近来在这一带闹得很凶。我已经追踪到那混蛋躲在湖畔镇后方北边山里的一个洞穴里。要是你能把他那只出名的爪子带回来给我，我就算你完成挑战，并奖励你一些我那些有名的狩猎补给！\n祝你好运！",
  },
  [26848] = {
    ["T"] = "克莱德的特制线",
    ["O"] = "从赤脊山的克莱德·兰萨尔那里取得克莱德的特制线，然后回到湖畔镇的艾米·达文波特那里。",
    ["D"] = "嘿，我能请你帮个忙吗？我想弄到一轴克莱德·兰萨尔出售的特制线，可他把店开在赤脊山最东边的山里。兽人和豺狼人让道路变得太危险，我自己实在没法过去，但你看起来能胜任这件事！\n\n一定要明确问他要那种特制线，因为你在他平常卖的货里找不到。我会报销你花掉的钱，再额外给你一点辛苦费。",
  },
  [26849] = {
    ["T"] = "豺狼人巡逻",
    ["O"] = "杀死7个暗皮蛮兵和7个暗皮战士，然后回到赤脊山的克莱德·兰萨尔那里。",
    ["D"] = "我的特制线？这样吧，要是你帮我们清理掉伊尔加拉之塔附近巡逻的那些卑鄙豺狼人，我就免费给你！\n\n我们想在这里好好做生意，可那些该死的家伙最近给我们惹了不少麻烦。它们就是一点也不懂得尊重商业！",
  },
  [26850] = {
    ["T"] = "以眼还眼",
    ["O"] = "杀死6个黑石召唤师和6个黑石追踪者，然后回到湖畔镇的治安官马瑞斯那里。",
    ["D"] = "可怕的消息，$N！我们的一支部队遭到黑石兽人伏击，伤亡惨重。只有少数士兵活着回来，许多人甚至下落不明。这种残暴的恶行绝不能不受惩罚，可我抽不出人手发动反击，士气也很低落。\n\n我必须请求你的帮助。黑石氏族必须知道，他们的袭击是要付出代价的。我们要打击敌人最痛的地方，给他们一次战术上的重创，$N。替我们除掉他们的追踪者和召唤师。这样一来，他们就很难再组织下一次伏击。\n\n你可以在北边的营地找到他们，就在通往燃烧平原道路的西侧。",
  },
  [26863] = {
    ["T"] = "暗炉图书馆员",
    ["O"] = "杀死暗炉图书馆员宾德罗尔，并为铁炉堡探险者大厅的图书馆员麦伊·苍尘取回《索瑞森的历史》。",
    ["D"] = "一个难得的机会出现了，$c，我需要有人好好利用它。\n\n暗炉图书馆员宾德罗尔是一位才华横溢的作者，也是出了名的隐士。出于某种原因，他去了熔渣之池，正住在那里的黑铁兵营里。这也许是我们取得他那份《索瑞森的历史》手稿副本的唯一机会。\n\n我不愿主张暴力，但我需要那本书。请你想办法替我拿到它，好吗？",
  },
  [26807] = {
    ["T"] = "南海镇防务",
    ["O"] = "把萨伦的报告交给湿地米奈希尔港的斯托特菲斯特船长。",
    ["D"] = "$N，你带来的这些报告满是坏消息。部落已经在整个希尔斯布莱德增强了进攻兵力。我不认为我们有足够人手抵挡塔伦米尔的全部力量。\n\n如果南海镇要活下来，我们就必须迅速行动。去米奈希尔港，到要塞里找斯托特菲斯特船长谈谈。我会起草一份报告，说明我们这里的处境。请他派援兵给我们……士兵、武器，任何能帮助我们应对即将到来的战斗的东西。请快些，南海镇指望着你。",
  },
  [26808] = {
    ["T"] = "南海镇防务",
    ["O"] = "从湿地银风洞穴开采8块幽触矿石，然后回到斯托特菲斯特船长那里。",
    ["D"] = "部落正在准备进攻南海镇？这……真是令人不安的消息。米奈希尔会尽力帮忙，但我不能保证太多。我现在抽不出任何士兵，不过如果你们真的走投无路，我倒有个主意。我们拥有铁炉堡之外最好的铁匠，要是这还不算点什么，那我就见鬼了！\n\n在丹奥加兹东南方，洛克莫丹瀑布落下的地方，你会找到银风洞穴。我们从未派探险队去过那里，因为那里有鬼魂出没，但现在正需要勇敢的行动。传闻洞穴中有一种强大的矿石，足以打造几乎坚不可摧的剑刃。\n\n去那座洞穴吧，$N。我会把我最结实的矿镐交给你；我相信你会怀着勇敢的心接下它。如果你能回来，就把矿石带给我们的武器匠布拉克·杜纳德。你可以在这里的铁匠铺里找到他。",
  },
  [26818] = {
    ["T"] = "横桨渡湾",
    ["O"] = "与湿地米奈希尔港桥东边的安德鲁·波特谈一谈。",
    ["D"] = "你去过南海镇吗，$C？那可是这片大陆上仍然屹立的最北方联盟城镇之一。南海镇过去是个繁忙的港口，俺可不知道后来出了啥事。听说因为礁石和别的乱七八糟的东西，从这儿去南海镇的船很难通行。\n\n总之，波特家那几个家伙在咱们两座城之间开了一条小船航线。要是你想去希尔斯布莱德，就该去桥边下面找安德鲁·波特谈谈。",
  },
  [26999] = {
    ["T"] = "耐克鲁斯必须死",
    ["O"] = "击败酋长耐克鲁斯，并把他的头颅带给橡木大师市长。",
    ["D"] = "现在轮到那个狠角色了，耐克鲁斯。个头巨大，还残暴得很。他很少离开他们在祖鲁玛那座巨大的堡垒。\n\n你杀掉的那三个首领每天都要向他汇报两次，所以他们没有出现时，他一定会起疑。我们不需要等任何人批准才说你该去砍下他的脑袋。\n\n我不知道他们在里面有什么防御，所以你要多加小心。\n\n祝你好运，$n。",
  },
  [27000] = {
    ["T"] = "暂时的胜利",
    ["O"] = "把伯恩杜拉尔胜利的消息带给斯托特菲斯特船长。",
    ["D"] = "你是斯托特菲斯特船长派来的，所以我们理应把这里发生的事告诉他。回到米奈希尔，把消息告诉他：我们不需要额外援助了。",
  },
  [27001] = {
    ["T"] = "古尔达尔豪赌",
    ["O"] = "抵达上沼泽的丹古尔达尔，并向市长提供帮助。",
    ["D"] = "该轮到我们把战火烧到龙喉那里去了。我需要你穿过他们的营地，抵达丹古尔达尔隘口。\n\n从米奈希尔出发向东，朝你找到那名信使的地方走，然后向南。\n\n到达上面之后，再折返回西，你就会遇到丹古尔达尔。\n\n到了那里以后，找到伯恩杜拉尔的市长并和他谈谈，告诉他你是来帮忙的。",
  },
  [27002] = {
    ["T"] = "向前线报到",
    ["O"] = "向伯恩杜拉尔前线的指挥官斯特朗伯恩报到。",
    ["D"] = "我以前是伯恩杜拉尔的市长，可当人们开始在丹古尔达尔隘口失踪时，我并没有太当回事……嗝。\n\n接着他们就在深夜发动了袭击，还没等我们组织起像样的反击，就夺走了半座城……嗝！\n\n我们的指挥官，人们叫他斯特朗伯恩，现在还在前线。请去为他效力吧，我还得继续确保龙喉没法顺走我们的好酒……嗝。从镇子向东走，伯恩杜拉尔就在你眼前……嗝。",
  },
  [27003] = {
