    ["O"] = "安抚5名惊慌的难民。",
    ["D"] = "平民怎么一遇到艰难局面就这么沉不住气？\n\n他们像没头鸡一样到处乱跑，还妨碍我们的防务。去和他们谈谈，把他们骂醒，让他们前往丹古尔达尔避难。",
  },
  [27004] = {
