    ["O"] = "在伯恩杜拉尔杀死6名龙喉学徒和6名龙喉守卫。",
    ["D"] = "我们在这里是为活命而战，但只要有些援手，我们就能把龙喉逼退。\n\n他们的前线已经压到我们最后一道防线前，我们必须在这里击败龙喉，否则就只能灭亡。\n\n进攻并击败他们前线上的学徒和守卫，然后我们才能开始计划如何真正扭转战局。",
