    ["O"] = "从前线偷取8件龙喉武器。",
    ["D"] = "如果我们想拖慢这场攻势，就必须除掉补给线中最重要的部分：他们的武器。\n\n那些兽人带来了成排看起来就很疼的斧头、匕首、长剑，还有更多东西。\n\n如果我们能把那些武器从前线移走，并据为己用，就能把龙喉赶回去。",
  },
  [27006] = {
    ["T"] = "祖鲁玛之眼",
    ["O"] = "在祖鲁玛附近的上沼泽找到斥候麦酒。",
    ["D"] = "我们必须把战斗推进到龙喉的据点祖鲁玛。我们有一名叫麦酒的斥候潜伏在那里观察道路，所以龙喉派出部队时，我们就能知道。\n\n他清楚祖鲁玛内部的一切动向。去找他，他会指引你打击我们需要摧毁的精准目标。\n\n根据我们收到的最后一份报告，他正躲在一辆被龙喉摧毁的马车后面，那辆马车是在逃离丹古尔达尔时被毁的。竟有这么多破坏……事情怎么会变成这样？",
  },
  [27007] = {
    ["T"] = "打在痛处",
    ["O"] = "替祖鲁玛外的斥候麦酒杀死6名龙喉剑圣和他们的首领索鲁克。",
    ["D"] = "耐克鲁斯麾下最凶悍的战士就是那些剑圣。他们由残暴的监视者索鲁克训练，索鲁克就在祖鲁玛入口处那座临时哨塔上虎视眈眈。\n\n如果你从源头切断他们的训练，不久之后，龙喉就会耗尽最强大的战士。这会造成内部裂痕，因为他们之中的强者会为了权力彼此争斗。\n\n没有强有力的领导，他们总会退回到旧日那套做法。",
  },
  [27008] = {
    ["T"] = "伯恩杜拉尔的屠夫",
    ["O"] = "替湿地的斥候麦酒杀死6名龙喉屠夫和驯兽师莫尔。",
    ["D"] = "从数量来看，龙喉屠夫手上的“猎获”最多。\n\n他们和首领驯兽师莫尔一起，在黎明时分骑马出击，袭击道路上的旅人，并猎杀湿地的野生动物。\n\n等龙喉意识到自己连士兵都喂不饱时，除掉他们就不只是给龙喉添堵了。\n\n让龙喉屠夫尝尝自己的手段，再把那名驯兽师也一起干掉。",
  },
  [27010] = {
    ["T"] = "撤离报告",
    ["O"] = "从长望哨站的山景下士那里取得最新撤离报告。",
    ["D"] = "龙喉还没有完全穿过伯恩杜拉尔……嗝。还有些人本来可以被救出去……嗝。去镇外的长望哨站找山景下士——你应该已经路过那里了。\n\n向他要一份完整报告，看看还有谁没离开。到了现在，剩下的人应该很少了……嗝。",
  },
  [27011] = {
    ["T"] = "魔像陀螺仪",
    ["O"] = "在上沼泽的丹古尔达尔找到安格斯·厚底。",
    ["D"] = "我的魔像坏掉之后，父亲把我派到这里来，我已经等零件等了好几个星期。\n\n不幸的是，从那以后，那些该死的龙喉已经彻底占据了隘口，现在我完全没有安全回去的办法。\n\n请告诉我父亲，我还活得好好的，只是没法把那些零件带给他。\n\n要找到他，你需要从米奈希尔向东走，直到看见龙喉，然后向南进入丹古尔达尔隘口之后的上沼泽，再径直向西抵达丹古尔达尔。",
  },
  [27012] = {
    ["T"] = "魔像陀螺仪",
    ["O"] = "从伯恩杜拉尔的锻炉取得2个陀螺仪。",
    ["D"] = "非常时期就得用非常办法，而我……在魔像修好之前，没法让它帮忙照顾我们的难民。\n\n既然你有勇气面对龙喉来到这里，也许你愿意进伯恩杜拉尔镇里走一趟。它就在丹古尔达尔外面，正遭围攻。我知道铁匠和大多数镇民都已经逃走了，但他们也许留下了一些边角料。\n\n去看看能不能找到两个陀螺仪，这样我或许就能让这台魔像重新动起来。",
  },
  [27014] = {
    ["T"] = "山羊牧场救援",
    ["O"] = "说服格洛里·克兰伯撤离他在上沼泽的家。",
    ["D"] = "伯恩杜拉尔北边山羊牧场的克兰伯一家已经在这里住了好几代，我知道格洛里那个老顽固不愿搬走。\n\n那家伙壮得像座该死的山，也和山一样固执。他一寸都不会挪！\n\n我试过让他们离开，可他们就是不肯。你为什么不去试试说服他们？",
  },
  [27015] = {
    ["T"] = "非常手段",
    ["O"] = "从伯恩杜拉尔的龙喉学徒和龙喉守卫身上找回制作粗糙的龙喉伪装所需的材料。",
    ["D"] = "我父亲就是个脾气暴躁、傲慢又固执的老糊涂。地平线上都看得见烟了。我以前还抓到过龙喉的人在农场附近鬼鬼祟祟地转悠，从伯恩杜拉尔传来的惨叫声更是听得一清二楚。\n\n可他就是不肯承认那边遭到了袭击，只因为他自己没亲眼看见。他还不停念叨，说这一切都是骗局，是冻石一家想趁机把我们的地盘吞掉。\n\n这事只能用点非常手段了。去伯恩杜拉尔，从那些七拼八凑的装备里找回足够的材料，做一套龙喉伪装。我有个主意……",
  },
  [27016] = {
    ["T"] = "非常手段",
    ["O"] = "伪装成龙喉，点燃两处山羊围栏和马厩。",
    ["D"] = "现在我得请你做件极端的事，$c。穿上你弄到的伪装，从一个围栏走到另一个围栏，把它们点着，吓跑那些山羊。\n\n没错……我知道……这很极端。但在我们真的陷入危险之前，我父亲不会相信我们有危险。与其让龙喉来做，不如由你来。",
  },
  [27017] = {
    ["T"] = "高地疾逃",
    ["O"] = "说服劳西一家撤离。",
    ["D"] = "在伯恩杜拉尔南边，你会找到劳西一家——这里唯一住着的人类。\n\n他们离开西部荒野后，买下了一处带土地和池塘的漂亮小地方。他们种出的作物在周围算是最好的。\n\n我没见他们过来，我想他们需要有人提醒一下，撤离已经刻不容缓。\n\n求你了，$n，去和他们谈谈，在龙喉推进过来之前把他们带走。",
  },
  [27020] = {
    ["T"] = "快离开这里",
    ["O"] = "护送萨迪拉·铁咬安全离开伯恩杜拉尔镇。",
    ["D"] = "轰！我对一切会爆炸的东西都颇有研究。这里就是我的收藏。\n\n龙喉推进得太快，我现在被困在敌后了。我相信只要你能把我带到下士那里，我就能让这些东西派上用场。\n\n至于剩下的东西，嗯，我们边走边把它们毁掉，免得龙喉拿来对付我们。\n\n等我安全了，请去丹古尔达尔告诉我的姑妈尼克茜。我知道她会担心，但我还有兽人要炸！",
  },
  [27021] = {
    ["T"] = "送往米奈希尔的消息",
    ["O"] = "把伯恩杜拉尔通知交给瓦斯塔格·铁颚。",
    ["D"] = "你面前的信使勉强抬起手，把一张沾满鲜血的字条牢牢塞进你手里，随后说出瓦斯塔格这个名字，便昏了过去。\n\n去米奈希尔港找到这张字条的收件人。",
  },
  [27022] = {
    ["T"] = "别杀信使",
    ["O"] = "治疗受伤的伯恩杜拉尔信使。",
    ["D"] = "那个试图把这张字条带给我的信使冒了生命危险。照你所说，他体内还有一口气。\n\n我们不能把他丢在沼泽里等死。拿着这个，用它给那名斥候恢复一点生机，让他能安全抵达这里。",
  },
  [27023] = {
    ["T"] = "雏龙驯服者",
    ["O"] = "杀死6名龙喉黑手和他们的首领征服者沙罗格。",
    ["D"] = "龙喉声称鄙视所有巨龙，但这并不会阻止他们把巨龙扭曲为自己的工具。\n\n祖鲁玛的黑手是他们最有本事的驯龙者之一。这些知识来自他们最熟练驯兽师征服者沙罗格的亲自教导。\n\n他和他的学生就在祖鲁玛北部那座俯瞰湿地的巨大法师塔中。",
  },
  [27024] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "在亚米萨兰找到那位旅行学者。",
    ["D"] = "旅人，向你致意。我是艾露恩姐妹会的女祭司泰拉斯。我奉命来到这里完成一项重要研究，但如今这项任务似乎陷入了僵局。\n\n在上古之战前，也就是卡多雷帝国鼎盛之时，一座名为哈吉里的城市坐落在如今佐拉姆海岸与黑海岸南部附近。最近有位途经阿斯特兰纳尔的旅行学者告诉我，娜迦正在那片废墟中搜寻帝国覆灭前的记录。我希望能把那些记录找回来。\n\n身为女祭司，我的职责不允许我离开阿斯特兰纳尔，但你可以自由行动。若你愿意帮忙，就请去寻找那位旅行学者。她说自己正朝黑海岸亚米萨兰的方向前进。",
  },
  [27025] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "在亚米萨兰保护阿莎伦，直到她突破结界。",
    ["D"] = "我叫阿莎伦，是一名研究失落技艺的学者。我相信自己知道泰拉斯要找的东西在哪里，但我也有自己的研究要完成。我想提出一项交换。\n\n在亚米萨兰废墟中，有一件古代施法者使用过的法器。它由结界保护着，虽然年代久远，防御依然强大。\n\n在我突破结界时保护我，我就帮你取得泰拉斯正在寻找的东西。",
  },
  [27026] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "在灰谷佐拉姆海岸与阿莎伦交谈，开始与莉亚拉斯的对决。",
    ["D"] = "既然你帮了我，现在也该由我解释一下为什么需要这件法器了。\n\n那个邪恶的海巫莉亚拉斯一直在细致地搜寻古代遗迹，寻找历史文献——也就是泰拉斯正在寻找的那些。可我与莉亚拉斯之间的仇怨，远不只是历史学家面对盗掠者那么简单。\n\n在上古之战期间，我的家族站在卡多雷抵抗军一边，这让我们引起了莉亚拉斯的注意。她来逮捕我们时，用一道几乎无法穿透的结界护住自己。我们没能阻止她，若不是永恒之井爆炸，她早就把我们赶尽杀绝了。\n\n多年来，我一直在寻找穿透她魔法的方法。如今有了这件法器，这一次她再也不能躲在她那邪恶魔法后面了。\n\n到佐拉姆海岸来找我。我们一起粉碎莉亚拉斯，把泰拉斯梦寐以求的文献拿到手。",
  },
  [27027] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "把哈吉里编年史带回阿斯特兰纳的泰拉斯那里。",
    ["D"] = "你也许已经猜到了，我的故事并不止我说出来的这些。我不能和你一起回镇上。\n\n你拿到了你的记录，而我也承诺会回到自己的流放之地。若你能把这里发生的一切留在我们之间，我会非常感激。我最不想看到的，就是因为违背神圣律法而被一位女祭司追捕。",
  },
  [27028] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "从星尘废墟的泉水中取得一份样本，然后回到阿斯特兰纳的泰拉斯那里。",
    ["D"] = "以这本书目前的状态，根本不可能判断娜迦最初为何要寻找它。不过这并不代表我已经没了主意。\n\n阿斯特兰纳南边有个曾被称为星尘的地方。虽然那里如今已成废墟，却仍有一处能找到最纯净水源的泉眼。\n\n去那里，用这个小瓶装满星尘之水。小心些，那片废墟里有危险的住民。",
  },
  [27029] = {
    ["T"] = "哈吉里编年史",
    ["O"] = "前往阿斯特兰纳以西的艾森娜神殿，寻求艾森娜的赐福。完成后回阿斯特兰纳与泰拉斯会合。",
    ["D"] = "我计划的最后一步，是把泉水和编年史一同带到艾森娜神殿。我希望以这份水作为供奉，请她赐予我们祝福，并修复这本编年史。我会在那里与你会合。\n\n如果你比我先到，不妨和其他访客谈谈，看看他们是否知道怎样才能最好地获得艾森娜的祝福。",
  },
  [27030] = {
    ["T"] = "砍！",
    ["O"] = "保护罗姆古尔，让他引诱灰谷先驱者攻击自己。任务完成后回去向工头巴兰复命。",
    ["D"] = "懦弱的暗夜精灵躲在阴影里，伏击任何进入他们领地的人。是时候想办法让他们别再盯着我们的苦工了。\n\n这次任务会把罗姆古尔派给你。他会像苦工那样笨拙地一路晃过去，尽可能弄出动静。等那些伏击者看见这个蠢货，就会嗅到软弱的味道，扑上去攻击他。你的任务就是确保罗姆古尔活下来，而那些精灵伏击者一个也别活。\n\n如果你能办成，我会付你报酬。",
  },
  [27031] = {
    ["T"] = "摧毁军团",
    ["O"] = "杀死6个玛诺洛克鞭笞者、6个恶魔守卫和6个灼热的地狱火，然后回到灰谷碎木岗哨的希瑞斯那里。",
    ["D"] = "恶魔的燃烧军团残部一直在袭击我们的战歌伐木营地！\n\n不能再这样下去了！\n\n这些恶魔正从东南方被称为冥火岭、屠魔峡谷和屠魔山的区域发起进攻。\n\n去尽可能多地消灭它们，为你自己和部落赢得荣耀！",
  },
  [27032] = {
    ["T"] = "摧毁军团",
    ["O"] = "杀死6个玛诺洛克鞭笞者、6个恶魔守卫和6个灼热的地狱火，然后回到灰谷林歌神殿的哨兵麦瑟琳那里。",
    ["D"] = "恶魔的燃烧军团残部一直在袭击战歌伐木营地。虽然我很不喜欢那些伐木工，但如果不阻止恶魔，它们就会越过伐木营地，开始猎杀道路上的旅人。\n\n这些恶魔正从南方被称为冥火岭、屠魔峡谷和屠魔山的区域发起进攻。\n\n去尽可能多地消灭它们，为森林和联盟带来安全！",
  },
  [27033] = {
    ["T"] = "恶魔计划",
    ["O"] = "把恶魔计划交给灰谷碎木岗哨的希瑞斯。",
    ["D"] = "这个恶魔掉下了这张羊皮纸，惊人的是，上面竟然用兽人语写着！其中提到的迪亚索鲁斯和戈加农，是控制这一带恶魔的两个臭名昭著的恐惧魔王。\n\n这份计划详细列出了恶魔准备袭击西北方碎木岗哨的安排。\n\n你确信碎木岗哨的希瑞斯会对这些东西感兴趣。",
  },
  [27034] = {
    ["T"] = "绝不再犯！",
    ["O"] = "进入屠魔峡谷，杀死戈加农和搜寻者迪亚索鲁斯。",
    ["D"] = "$N，你必须确保燃烧军团的这次袭击永远不会发生！去杀掉这些恐惧魔王！没有了他们，其余恶魔基本上就只剩下盲目的本能。\n\n你可以在冥火岭以南的屠魔峡谷里找到戈加农，就在玛诺洛斯那柄漂浮的断矛附近。\n\n搜寻者迪亚索鲁斯住在屠魔山顶上的某处。要找到那座山，就在格罗姆·地狱咆哮纪念碑附近，寻找从屠魔峡谷向上的坡道。",
  },
  [27035] = {
    ["T"] = "恶魔计划",
    ["O"] = "把恶魔计划交给灰谷林歌神殿的哨兵麦瑟琳。",
    ["D"] = "这个恶魔掉下了这张羊皮纸，惊人的是，上面竟然用通用语写着！其中提到的迪亚索鲁斯和戈加农，是控制这一带恶魔的两个臭名昭著的恐惧魔王。\n\n这份计划详细列出了恶魔准备袭击北方林歌神殿的安排。\n\n你确信林歌神殿的哨兵麦瑟琳会对这些东西感兴趣。",
  },
  [27036] = {
    ["T"] = "绝不再犯！",
    ["O"] = "进入屠魔峡谷，杀死戈加农和搜寻者迪亚索鲁斯。",
    ["D"] = "$N，你必须确保燃烧军团的这次袭击永远不会发生！去杀掉这些恐惧魔王！没有了他们，其余恶魔基本上就只剩下盲目的本能。\n\n你可以在冥火岭以南的屠魔峡谷里找到戈加农，就在玛诺洛斯那柄漂浮的断矛附近。\n\n搜寻者迪亚索鲁斯住在屠魔山顶上的某处。要找到那座山，就在格罗姆·地狱咆哮纪念碑附近，寻找从屠魔峡谷向上的坡道。",
  },
  [27037] = {
    ["T"] = "直接报复",
    ["O"] = "杀死黑暗深渊中的萨利维丝女士，然后回到阿斯特兰纳的泰拉斯那里。",
    ["D"] = "我已经有机会翻阅修复后的编年史，也许知道那些娜迦在寻找什么了。\n\n正如我之前告诉你的，哈吉里早在上古之战前就已存在，但后来和许多其他卡多雷城市一样失落了。这本书记载了一位高阶女祭司，据说她曾在哈吉里的神殿中升入群星。娜迦的目标也许是通过类似仪式获得艾露恩的力量。虽然我们已经让娜迦失去了这份文本，但可以推断，他们还会继续追寻其他类似的文献。\n\n袭击我们的娜迦都是萨利维丝女士的仆从。向西沿佐拉姆海岸前进，有一座废弃神殿的入口。萨利维丝女士就在这处深渊中与她的爪牙密谋。找到她，彻底终结她的阴谋。完成后回来找我，你会得到奖赏。",
  },
  [27038] = {
    ["T"] = "被遗忘者掠夺者",
    ["O"] = "在巴斯兰鬼屋杀死5个亡灵搜寻者、5个亡灵草药师和10个亡灵暴徒。完成后，回到迈斯特拉岗哨的净化者德尔格伦那里。",
    ["D"] = "被遗忘者已经侵入灰谷。他们也许曾经是我的同胞，但我亲眼见过，他们走到哪里就只会带来死亡。我不会允许他们继续在这里立足。\n\n到北边的巴斯兰鬼屋找到他们的哨站，终结他们在那里所做的一切。",
  },
  [27103] = {
    ["T"] = "向派遣指挥官鲁亚格报到",
    ["O"] = "向悲伤沼泽斯通纳德的派遣指挥官鲁亚格报到。",
    ["D"] = "部落的士兵！我必须回应派驻在悲伤沼泽斯通纳德的派遣指挥官鲁亚格传来的消息。\n\n你需要前往东部王国，从格罗姆高营地出发沿路向北，穿过暮色森林和逆风小径，抵达悲伤沼泽。这是一趟漫长却重要的旅程。我能指望你安全送达吗？",
  },
  [27167] = {
    ["T"] = "外来技术",
    ["O"] = "潜入死亡矿井，把重构铸造机带给十字路口的特劳格。",
    ["D"] = "我们在贫瘠之地这里的技术……还很有限。我一直想掌握一种能以自动方式制造更复杂工具和武器的本事。可我不懂这种门道，但总有人懂。\n\n你听说过死亡矿井吗？那是迪菲亚兄弟会在西部荒野的据点，远在东部王国。里面有个名叫基尔尼格的邪恶地精，专门替兄弟会制造器械。\n\n我听说他最近弄出了一台新机器，能把原材料直接铸造成武器！把这台机器给我带来，好让部落变得更强大！不过你也得小心，兄弟会可不会轻易把他们的机器交出来，所以最好带几个朋友一起去。",
  },
  [27205] = {
    ["T"] = "我的妹妹伊莎贝塔",
    ["O"] = "与住在奥伯丁南边海上小岛家中的伊莎贝塔·惠兰交谈。",
    ["D"] = "我在镇上为这场鱼人麻烦找帮手找了这么久，我妹妹伊莎贝塔肯定已经在担心我跑哪儿去了。\n\n反正你也正要出去处理鱼人的事，能不能顺路去我家一趟，告诉她我很快就会回去？\n\n我们在镇子南边的一座小岛上盖了间房子。",
  },
  [27206] = {
    ["T"] = "我的妹妹伊莎贝塔",
    ["O"] = "调查伊莎贝塔·惠兰家中的火灾。",
    ["D"] = "一具女子的尸体躺在这里。你猜她一定就是伊莎贝塔·惠兰。虽然她的头发被烧焦，双手也有灼伤，但真正的死因似乎是胸口的几处刺伤。\n\n看起来有人搜过她的尸体，她的口袋全被翻了出来。\n\n附近的房子仍因不久前的火灾冒着烟。也许在把发生的事告诉比尔·惠兰之前，你该先调查一下现场？",
  },
  [27223] = {
    ["T"] = "个人物品",
    ["O"] = "在雷姆塔维尔挖掘场周围收集考古学家埃弗里特的个人物品。",
    ["D"] = "你知道吗，$C，那些傀儡现在可把我吓得有点不敢回坑里去了。我看我还是在这上头、离那些怪物远点的地方重新搭个帐篷吧。\n\n可要这么做，我得拿回几件落在挖掘场里的宝贝东西。要是你本来就要下去，能不能顺手帮我捡回来？",
  },
  [27224] = {
    ["T"] = "暴走的傀儡",
    ["O"] = "为雷姆塔维尔挖掘场的考古学家埃弗里特杀死6个破损的傀儡或石巨兽。",
    ["D"] = "欢迎来到雷姆塔维尔挖掘场，$glad:lass;。我真高兴你来了，因为这片挖掘场眼下出了大麻烦。\n\n勘察员雷姆塔维尔一门心思扑在他的研究上，对我们周围的危险视而不见。其中一项危险，就是自从我们开始挖掘后爬起来的这些傀儡。我只是个考古学家，可你看起来像是个能打的人。你能不能帮我们削减一下它们的数量？",
  },
  [27225] = {
    ["T"] = "厄索塔石",
    ["O"] = "把这块奇怪的石头带到铁炉堡的探险者大厅。",
    ["D"] = "箱子里有一块石板，上面刻满了你从未见过的奇怪符号。你觉得这块石头对考古学家来说应该很有价值。铁炉堡的探险者协会也许会对这件东西感兴趣——说不定这艘船原本的目的地就是那里。\n\n你可以在暴风城的矮人区乘坐矿道地铁前往铁炉堡。",
  },
  [27226] = {
    ["T"] = "厄索塔石",
    ["O"] = "把厄索塔石交给黑海岸奥伯丁的考古学家霍莉。\n\n要到黑海岸，你得先穿过洛克莫丹和湿地，前往塞拉摩的港口。",
    ["D"] = "这块石头是研究古神的重要文物。古神是很久以前统治过艾泽拉斯的可怕存在。我们在奥伯丁的一位研究员非常需要这件东西，但那地方离这里很远——远在卡利姆多。\n\n前往那里一路凶险，$N，但若你愿意走这一趟，必定能得到丰厚回报。\n\n你得先沿着道路往东进入洛克莫丹，再一路向北前往湿地。到了那边以后，就一直沿着大路走到米奈希尔港，路上可得多加小心——这可不是一段短途。",
  },
  [27227] = {
    ["T"] = "斯托雷塔石",
    ["O"] = "从玛塞斯特拉废墟的娜迦身上收集10块斯托雷塔碎片。",
    ["D"] = "我很确定，这块石头正是解读这片区域其他古老石板的关键。可惜，因为废墟里那群敌意十足的娜迦，我一直没法顺利收集那些石板。而我正在寻找的其中一块，还被他们砸成了碎片！\n\n到目前为止，你已经证明了自己的本事。要是你愿意继续帮我，就去北边的玛塞斯特拉废墟，从如今盘踞那里的娜迦手中取回一些石板碎片。说不定我能把它重新拼起来。",
  },
  [27228] = {
    ["T"] = "特洛斯塔石",
    ["O"] = "从黑暗深渊的梦游者克尔里斯手中取得特洛斯塔石板。",
    ["D"] = "还有另一块石板是我研究的关键，但要取得它，会比你至今做过的任何事都危险得多，$C。\n\n沿着海岸向南，有一座名为黑暗深渊的神殿。传闻那座神殿里有一块与厄索塔石成对的姐妹石板。这块特洛斯塔石，是我解读古神古老文字所需的最后一块拼图。\n\n遗憾的是，那座神殿里满是敌对的娜迦，还有某种末日邪教。如果你真能找到一队有兴趣洗劫那座神殿的人，我希望你能留意这块石头，并把它带给我。",
  },
  [27229] = {
    ["T"] = "奇怪的遗物",
    ["O"] = "把奇怪的遗物交给达纳苏斯的首席考古学家杜瑟·灰须。",
    ["D"] = "看看这些遗物吧，年轻人。你有没有看出和我一样的异样？\n\n其中有一件不同。凡人的手能真切地触碰到它，可在我眼中，它却像是在摇曳……仿佛并不属于这个时代。我实在不知道该怎么向一位$R解释这种感觉。\n\n这件奇怪的遗物，也许正能解释暮光之锤为何会出现在这里，出现在他们那位早已死去的神明的墓旁。达纳苏斯里正好有位矮人在研究与古神及其宿敌泰坦有关的远古遗物。把它带给他吧，也许能帮助他的研究，也能让我们更看清暮光之锤的计划。",
  },
  [27303] = {
    ["T"] = "遏制污染",
    ["O"] = "把邪水净化器带到血毒瀑布的湖边并部署它，然后回到费伍德森林翡翠圣地的伊维·飘叶那里。",
    ["D"] = "向你致意，$C。我们是否能修复那可憎恶魔腐化对费伍德森林造成的伤害，目前仍不清楚，但我们可以采取措施阻止它继续扩散。\n\n被污染的软泥怪正在血毒河岸边不断增殖，而这条河会一路流入黑海岸。我担心下游的径流会继续传播腐化。幸运的是，我们的一位地精朋友制造出了一台净化装置，可以帮助从源头净化河水。\n\n把这台净化器带到血毒瀑布湖边的码头上，然后把它投进去。看看是否有什么效果，再回来告诉我。",
  },
  [27308] = {
    ["T"] = "第三次战争的遗物",
    ["O"] = "把这箱可怖的遗物交给达纳苏斯月神殿的泰兰德·语风。",
    ["D"] = "幸好你来了，$N。我查看这些物品时才发现，它们比我原先想的还要骇人——这些头骨属于军团进军海加尔山途中杀害的一部分受害者。\n\n那些邪教徒还在上面刻下了他们的名字。虽然我并不认识这些死者，但他们既然曾为保卫世界之树而战，就理应以英雄之礼得到安葬。\n\n请把这些战利品交给达纳苏斯的艾露恩高阶女祭司泰兰德·语风。我相信，在决定下一步该怎么做这件事上，没有谁比她更合适。",
  },
  [27477] = {
    ["T"] = "进攻瘤背熊怪",
    ["O"] = "消灭4个瘤背萨满祭司、4个瘤背防御者、4个瘤背伏击者和4个瘤背战士，然后回到泰达希尔多兰纳尔的梅拉瑞斯那里。",
    ["D"] = "瘤背部族对我们的袭击越来越频繁，我开始担心了。你愿意帮我们对抗他们吗？\n\n你可以在泰达希尔各处找到他们部族的成员，但斥候报告说，他们主要聚集在这里西边路旁，以及班奈希尔兽穴附近。出去杀掉他们吧，这样我才知道我们的人民会安然无恙。",
  },
  [27478] = {
    ["T"] = "进攻瘤背熊怪",
    ["O"] = "杀死阿加尔、纳格尔和绿爪，然后回到多兰纳尔的梅拉瑞斯那里。",
    ["D"] = "如果我们不打击瘤背熊怪的首领，他们的数量只会越来越多。没有了酋长，他们就没有可以追随的目标。到那时，他们的部族就会土崩瓦解，四散而去。\n\n第一个首领叫阿加尔，住在班奈希尔兽穴北边的一处洞穴里。第二个和第三个首领——纳格尔与绿爪——都住在兽穴深处。要是我是你，我可不会独自前往；那里纵深极大，很容易迷路。\n\n祝你好运，$n。务必小心，把瘤背熊怪彻底终结。",
  },
  [27479] = {
    ["T"] = "血羽之卵",
    ["O"] = "收集6枚血羽之卵，然后回到泰达希尔神谕林地的奥兰纳·鸦眼那里。",
    ["D"] = "你见过附近那些血羽鹰身人吗？她们侵入了这片土地，但同时也是充满魔力而又美丽的生物。\n\n我研究奥术，而我觉得她们产下的卵或许带有某种魔法特性。你愿意替我带些卵来，让我研究一下吗？",
  },
  [27480] = {
    ["T"] = "幽影谷的腐化",
    ["O"] = "杀死纳图克和8只狂乱的月夜枭兽，然后回到幽影谷奥达希尔的阿兰妮娅·雾击那里。",
    ["D"] = "一群月夜枭兽在幽影谷定居下来了！我们并不敌视月夜枭兽，事实上它们中的许多都是我们的盟友，但这一群已经失去了与艾露恩的联系，正在森林中肆意制造混乱。\n\n我相信，一定有什么东西腐化了它们，才让这些月夜枭兽变得狂躁而失控。\n\n它们占据了这里东边的一处熊怪营地。请杀掉它们的首领，再驱散其余的月夜枭兽，别让它们给幽影谷的自然平衡造成严重破坏！",
  },
  [27481] = {
    ["T"] = "中级豹骑术",
    ["O"] = "向贾萨姆学习中级骑术，然后与达纳苏斯的莱兰奈谈一谈，领取你的夜刃豹。",
    ["D"] = "欢迎回来。你是来学习更快的骑术，对吧？和上次一样，你那头夜刃豹的费用已经有人替你付过了，不过训练费还得你自己出。很遗憾，更高级的训练可不便宜。\n\n学会骑术之后，就去旁边找莱兰奈谈谈。她负责出售这些夜刃豹。要是你手头钱还不够，以后随时都可以再来。",
  },
  [27482] = {
    ["T"] = "豹骑术",
    ["O"] = "向贾萨姆学习初级骑术，然后与达纳苏斯的莱兰奈谈一谈，领取你的夜刃豹。",
    ["D"] = "你是来领夜刃豹的，是吗？巧得很，我正等着你呢！有位神秘的赞助者替你留下了一笔钱，正好够买一头普通夜刃豹，而且收件人还写着你的名字，$N。不过对方没替你付训练费，所以很抱歉，这部分还是得你自己出。\n\n学会骑术之后，就去旁边找莱兰奈谈谈。她负责出售这些夜刃豹。要是你手头钱还不够，之后再来也行。",
  },
  [27483] = {
    ["T"] = "地狱石中的恶魔",
    ["O"] = "从地狱石收集10份恶魔精华，然后回到多兰纳尔的吉娜·羽弓那里。",
    ["D"] = "你好，很高兴在多兰纳尔见到一位新的$c。想必你已经听说了最近泰达希尔发生的腐化吧？\n\n恶魔已经侵入了这片土地，我们有些斥候报告说，它们大量聚集在北边一座名为地狱石的洞穴里。\n\n你能杀掉它们，并把它们的恶魔精华带回来吗？这样我们就能将其净化。",
  },
  [27484] = {
    ["T"] = "净化精华",
    ["O"] = "在多兰纳尔的月亮井净化恶魔精华，然后回到吉娜·羽弓那里。",
    ["D"] = "恶魔精华会把恶魔束缚在它们被召唤而来的位面上，所以如果我们想把它们的灵魂从这个世界驱逐出去，就必须先净化这些精华。\n\n暗夜精灵的领地里有许多月亮井，但最近的一口就在多兰纳尔。去那里的月亮井净化这份精华吧，这样它们的灵魂就会永远被逐出艾泽拉斯。",
  },
  [27485] = {
    ["T"] = "草药疗法",
    ["O"] = "从阿里斯瑞恩之池采集8根百合根鞭，然后回到泰达希尔多兰纳尔的玛洛尼·刃叶那里。",
    ["D"] = "许多人以为草药只会被用来制作伤人的药剂，但草药最早是拿来治病救人的。你永远不知道什么时候会有猫头鹰突然发狂、袭击同伴，所以手边常备药物总是明智之举。\n\n如果你能从西边遥远的阿里斯瑞恩之池带一些百合根鞭回来，我就能替你调制一些药物。要是你的样本让我满意，说不定我还会教你怎么亲手做点东西。",
  },
  [27592] = {
    ["T"] = "给农夫萨丁的委托",
    ["O"] = "吉娜·马克葛瑞格要你用炼金技能制作5瓶次级治疗药水，并把订单交给西部荒野萨丁农场的农夫萨丁。",
    ["D"] = "我只是个普通商人，没有制作药剂和药水的天赋，但我希望能帮助西部荒野的同胞。农夫萨丁在处理他农场上横冲直撞的机器时受了些轻伤。要是你能制作一些次级治疗药水并送到萨丁农场，我也能稍微安心些，不至于觉得自己帮不上更多忙。",
  },
  [27593] = {
    ["T"] = "给葛瑞姆·雷酒的委托",
    ["O"] = "吉娜·马克葛瑞格要你用炼金技能制作5瓶黑口鱼油，并把订单交给西部荒野匕首岭的葛瑞姆·雷酒。",
    ["D"] = "说到帮忙……还有一个人也一直在找炼金师协助。你可以在匕首岭上方的营地找到葛瑞姆·雷酒。他一直想找人给他制作几瓶黑口鱼油。如果你有兴趣，我确信他会付钱给你。",
  },
  [27605] = {
    ["T"] = "给雷德帕斯元帅的委托",
    ["O"] = "学徒霍尼韦尔要你用炼金技能制作5瓶猫眼药剂，并把订单交给希尔斯布莱德丘陵南海镇的雷德帕斯元帅。",
    ["D"] = "辛迪加最近很猖狂，$N。他们甚至刺杀了南海镇的前任镇长！\n\n要是我能做出一些猫眼药剂，让我们的守卫看见那些鬼鬼祟祟的潜行者就好了，可我还没有那样的本事。\n\n不过你似乎有！我能不能劝你做件好事，把一些猫眼药剂送给镇里的雷德帕斯元帅？",
  },
  [27624] = {
    ["T"] = "给药剂师林度恩的委托",
    ["O"] = "药剂师林度恩要你用炼金技能制作5瓶火焰之油，并把订单交给希尔斯布莱德丘陵塔伦米尔的药剂师林度恩。",
    ["D"] = "哦……一位炼金师。我想你会欣赏我对毒药的兴趣。说到底，这和炼金术也不是完全不同的技艺。\n\n其实，我正能用上你的服务。我想为希尔斯布莱德调制另一种混合物……一种带有灼热底味的毒药……能造成一点烧灼感的那种。如果你能替我制作一些火焰之油，我可以给你一些对日后制作有用的材料。",
  },
  [27642] = {
    ["T"] = "给军需官刘易斯的委托",
    ["O"] = "军需官刘易斯要你用锻造技能制作5块粗制砂轮，并把订单交给西部荒野哨兵岭的军需官刘易斯。",
    ["D"] = "你好，$C。很高兴在镇上见到铁匠。我需要一批新的粗制砂轮，好让我们的武器和护甲免受锈蚀和污垢侵扰。要是你能制作五块并交给我，我会十分感激。",
  },
  [27643] = {
    ["T"] = "给守卫者伊万杰琳的委托",
    ["O"] = "军需官刘易斯要你用锻造技能制作1件铜质符文胸甲和1副铜质符文护腕，并把订单交给西部荒野南部道路上的守卫者伊万杰琳。",
    ["D"] = "如果你还想找更多活干，我听说西部荒野民兵有位新成员需要一件铜质符文胸甲和一副铜质符文护腕来补齐她的护甲。如果你能制作这些东西，就把它们交给守卫者伊万杰琳。她在哨兵岭南边的道路上巡逻。",
  },
  [27655] = {
    ["T"] = "给赫尔姆斯沃西少校的委托",
    ["O"] = "达伦·马尔维要你用锻造技能制作1件绿铁锁甲，并把订单交给希尔斯布莱德丘陵南海镇附近塔楼里的赫尔姆斯沃西少校。",
    ["D"] = "这里没有铁匠，新马掌很难弄到，但我更替南海镇卫队担心。他们只能拿用了多年的护甲和武器凑合。\n\n你是铁匠？嗯，如果你有兴趣帮忙，赫尔姆斯沃西少校正需要一件新的绿铁锁甲。他自己绝不会开口，但我们必须保证他护甲齐备。要是失去了少校，我真不知道我们该怎么抵御下一次部落进攻！",
  },
  [27674] = {
    ["T"] = "给亡灵哨兵莱什的委托",
    ["O"] = "奥特要你用锻造技能制作1面纯银盾牌，并把订单交给希尔斯布莱德丘陵西南部南点哨塔的亡灵哨兵莱什。",
    ["D"] = "你该不会正好是铁匠吧？哦，你还真是！我需要你帮忙。\n\n塔伦米尔上一位铁匠在第三次战争中死了，我们有些守卫只能拿剩下的破烂凑合。我想委托人给亡灵哨兵莱什打造一面纯银盾牌，可我已经不得不一路向幽暗城请求护甲，那东西要等很久才能送到。要是你能替我打造并送去这面盾牌，我会确保莱什拿补给品作为回报。",
  },
  [28066] = {
    ["T"] = "给利拉迪斯·月河的委托",
    ["O"] = "利拉迪斯·月河要你用烹饪技能制作10份蟹肉蛋糕，并把订单交给灰谷迈斯特拉岗哨的利拉迪斯·月河。",
    ["D"] = "Ishnu-dal-dieb，$C。海洋的丰饶近在咫尺，却又远在天边。你瞧，我必须在这里等我的朋友，她随时都可能抵达。可我真的很想吃美味的蟹肉蛋糕！\n\n如果你能给我做一些，那就是善举。当然，如果你太忙，我也理解。我会就在这里。等着……",
  },
  [28067] = {
    ["T"] = "给瓦格·深水的委托",
    ["O"] = "瓦格·深水要你用烹饪技能制作10份猪肉干，并把订单交给洛克莫丹洛克湖岸边的瓦格·深水。",
    ["D"] = "啊，$N！今天天气多好啊？太阳正暖，鱼也正上钩，而我现在最想来点猪肉干！\n\n怎么，你以为我会想再吃鱼？鱼我天天都能吃，而且经常吃。今天嘛，我想换点别的口味。你觉得自己能帮个老头子这个忙吗？",
  },
  [28068] = {
    ["T"] = "给卡尔·波兰的委托",
    ["O"] = "卡尔·波兰要你用烹饪技能制作10份刺须鲶鱼，并把订单交给湿地米奈希尔港的卡尔·波兰。",
    ["D"] = "看看它，$N。大海近在眼前，里面全是鱼。可这些船一艘接一艘进港，我根本没时间去抓鱼，更别说把鱼做熟了。\n\n你愿意帮我个忙吗？我想要几份热腾腾的刺须鲶鱼。看起来你在灶火边有点本事。我很乐意为你的服务付钱。",
  },
  [28070] = {
    ["T"] = "给乔丹·斯图尔的委托",
    ["O"] = "乔丹·斯图尔要你用烹饪技能制作10份地精芥末蘸蚌肉，并把订单交给希尔斯布莱德丘陵西部他家里的乔丹·斯图尔。",
    ["D"] = "欢迎来到我这简陋的家，$C。它看起来不怎么样，但它是我的。\n\n我以前常在海上待很久，发现自己很怀念那里的菜肴。自家花园做出的家常饭自有魅力，但要是能来一盘地精芥末蘸蚌肉，我几乎什么都愿意拿来换。要是你懂得怎么烹饪它们，给我带些来，我一定会让你觉得值得！",
  },
  [28086] = {
    ["T"] = "给亡灵哨兵莱什的委托",
    ["O"] = "亡灵哨兵莱什要你用烹饪技能制作10份地精芥末蘸蚌肉，并把订单交给希尔斯布莱德丘陵南点哨塔的亡灵哨兵莱什。",
    ["D"] = "欢迎来到部落最糟糕的岗位，$C：南点哨塔。它看起来不怎么样，但它是我的。\n\n生前，我以前常在海边待很久，发现自己很怀念那里的菜肴。幽暗城配发的口粮没什么魅力，而要是能来一盘地精芥末蘸蚌肉，我几乎什么都愿意拿来换。要是你懂得怎么烹饪它们，给我带些来，我一定会让你觉得值得！",
  },
  [28380] = {
    ["T"] = "给雷维尔·科斯特的委托",
    ["O"] = "雷维尔·科斯特要你用附魔技能制作1块小块微光碎片，并把订单交给西部荒野哨兵岭的雷维尔·科斯特。",
    ["D"] = "我离开我……之前的受雇地点时走得很匆忙，忘了带几样东西。你是附魔师，对吧？能不能匀给我一块小块微光碎片？我当然会付钱！",
  },
  [28381] = {
    ["T"] = "给守卫者加瑞尔的委托",
    ["O"] = "雷维尔·科斯特要你用附魔技能为提供的1副民兵护腕附上附魔护腕 - 初级敏捷，并把订单交给西部荒野哨兵岭的守卫者加瑞尔。",
    ["D"] = "大家似乎都以为我有大把空闲，可以替他们处理神秘杂事，可我没有。给，守卫者加瑞尔要我给这副民兵护腕附上初级敏捷，但我把它转交给你。你看起来更像那种乐于行善的人。完成后去哨兵岭的大塔找她。",
  },
  [28384] = {
    ["T"] = "给奥德伦·科尔东的委托",
    ["O"] = "镇长埃罗恩·钝鼻要你用附魔技能制作1根强效魔法杖，并把订单交给洛克莫丹铁环挖掘场的奥德伦·科尔东。",
    ["D"] = "你是个附魔师？那也许正好能替我解决一桩烦心事。铁环挖掘场那边的奥德伦·科尔东充其量也就是个半吊子法师，可他总在抱怨，说要是自己有根更好的魔杖，施法本事肯定会高明得多。给他做一根强效魔法杖吧，省得他再唠叨个没完。",
  },
  [28385] = {
    ["T"] = "给马雷克·铁心的委托",
    ["O"] = "镇长埃罗恩·钝鼻要你用附魔技能为提供的1把猎人之斧附上附魔武器 - 初级攻击，并把订单交给洛克莫丹远行者小屋的马雷克·铁心。",
    ["D"] = "对了，既然你人在镇上，要不要顺手帮帮洛克莫丹的乡亲们？远行者小屋的马雷克·铁心打猎时大概正缺点好运气。替这把猎人之斧附上初级攻击，也许他哪天终于能打到点像样的猎物了。哈哈！",
  },
  [28386] = {
    ["T"] = "给亚伯克隆比的委托",
    ["O"] = "亚伯克隆比要你用附魔技能制作1根符文金棒，并把订单交给暮色森林乌鸦岭墓地附近小屋里的亚伯克隆比。",
    ["D"] = "对，对，乖巧的小附魔师。帮这个住在小屋里的老人做一根符文金棒吧，它对我和我的工作会很有用。他们——我是说我，会付钱的。",
  },
  [28387] = {
    ["T"] = "给阿祖拉的仆从的委托",
    ["O"] = "阿祖拉的仆从要你用附魔技能制作1块大块微光碎片，并把订单交给赤脊山撕裂者山谷的阿祖拉的仆从。",
    ["D"] = "你是个附魔师，对吧？显然我一时半会儿哪也去不了，但我可以用一块大块微光碎片来增强自己替塞欧克瑞图斯刺探情报的能力。对这份委托感兴趣吗？",
  },
  [28389] = {
    ["T"] = "给温娜·丝须的委托",
    ["O"] = "凯特琳·格拉斯曼要你用附魔技能为提供的1件梦纹外衣附魔胸甲 - 法力，并把订单交给湿地日落沼泽的温娜·丝须。",
    ["D"] = "我不是附魔师，可大家看见我这间实验室，就以为我懂这个。比如日落沼泽那边的温娜·丝须。她把这件梦纹外衣和一张字条放在我这儿，要我给它附上法力魔法，可我根本不知道怎么做！但你懂！",
  },
  [28393] = {
    ["T"] = "给赫尔姆斯沃西少校的委托",
    ["O"] = "学徒霍尼韦尔要你用附魔技能为提供的1把少校之刃附上附魔武器 - 攻击，并把订单交给希尔斯布莱德丘陵南海镇的赫尔姆斯沃西少校。",
    ["D"] = "人们不知道我是炼金学徒，不是附魔师。马雷布镇长想让我给这把少校之刃附魔，交给南海镇防务的新负责人赫尔姆斯沃西少校，可我办不到。你能帮忙把它送到附近塔楼里的他手上吗？",
  },
  [28412] = {
    ["T"] = "给学徒塞万德的委托",
    ["O"] = "学徒塞万德要你用附魔技能制作1块大块微光碎片，并把订单交给希尔斯布莱德丘陵塔伦米尔的学徒塞万德。",
    ["D"] = "我一眼就能认出附魔师。我的力量不如赫尔库拉那样强大，但我可以用一块大块微光碎片来强化我的魔法研究，并像赫尔库拉本该做的那样更好地效力部落。你能给我弄一块吗？我会付钱给你。",
  },
  [28430] = {
    ["T"] = "给哨兵瑞尔的委托",
    ["O"] = "守卫者加瑞尔要你用工程学技能制作2个粗制瞄准镜，并把订单交给西部荒野哨兵岭的哨兵瑞尔。",
    ["D"] = "我已经获得征用人民军所需物资的授权。你是工程师，对吧？我需要给塔顶上的哨兵瑞尔弄一个粗制瞄准镜。那会让她在狙击任何袭击哨兵岭的东西时占据优势。如果你能制作几个并送给她，我们会给你报酬。",
  },
  [28431] = {
    ["T"] = "给守卫者多拉娜的委托",
    ["O"] = "守卫者加瑞尔要你用工程学技能制作1副敏捷虎眼护目镜，并把订单交给西部荒野北行道路巡逻线上的守卫者多拉娜。",
    ["D"] = "身为人民军的征用员，我还想请你为守卫者多拉娜制作一副敏捷虎眼护目镜。她独自在哨兵岭往北延伸的道路上巡逻，那副护目镜能保护她的眼睛，挡住沙尘暴扬起的泥土和刺眼烈日。要是你愿意替我把它送给她，我会非常感激。",
  },
  [28434] = {
    ["T"] = "给布洛克·寻石者的委托",
    ["O"] = "布洛克·寻石者要你用工程学技能制作5个铜质调节器，并把订单交给洛克莫丹塞尔萨玛的布洛克·寻石者。",
    ["D"] = "你好，$C。我知道这事听起来有点怪，一个矿工居然来向工程师求助，不过我正好有个新式自动挖掘工具的点子。要做出第一台原型，我得先弄到五个铜质调节器。要是你肯帮忙，除了工钱之外，我还愿意额外再给你点谢礼。",
  },
  [28435] = {
    ["T"] = "给年轻的达瑞尔的委托",
    ["O"] = "布洛克·寻石者要你用工程学技能制作5把练习锁，并把订单交给洛克莫丹远行者小屋的年轻的达瑞尔。",
    ["D"] = "说到帮忙，不久前有个年轻的人类路过这里，正往远行者小屋那边去。看起来像是对打猎有些腻了。他问镇上有没有人会做练习锁，可这里偏偏没人懂这门手艺。要是你想多赚点钱，他说自己还会在小屋那边待上一阵子。那孩子的名字叫达瑞尔。",
  },
  [28436] = {
    ["T"] = "给维克托·安特拉斯的委托",
    ["O"] = "科格·闪旋要你用工程学技能制作1架精制望远镜，并把订单交给暮色森林夜色镇的维克托·安特拉斯。",
    ["D"] = "隔壁有个人类正在试着造某种花哨的望远镜来看星星。我一直告诉他，我们侏儒早就有看星星的办法了——用精制望远镜！\n\n我自己不是工程师，但你看起来是。我很希望你能做一架望远镜送给维克托，这样我就不用再听他唠叨那个蠢发明了！\n\n<科格低声咕哝着什么，说人类正在侵占侏儒产业。>",
  },
  [28437] = {
    ["T"] = "给泽姆·里瓦尔德的委托",
    ["O"] = "泽姆·里瓦尔德要你用工程学技能制作10个水下诱鱼器，并把订单交给赤脊山湖畔镇的泽姆·里瓦尔德。",
    ["D"] = "嘿，$C。止水湖的鱼可真是好钓。我在这码头上钓到过不少又大又亮的太阳鱼——不过我觉得要是有些新奇的水下诱鱼器，我还能钓得更好。你认识会做那些东西的人吗？",
  },
  [28490] = {
    ["T"] = "给药剂师林度恩的委托",
    ["O"] = "药剂师林度恩要你用急救技能制作20根厚绒线绷带，并把订单交给希尔斯布莱德丘陵塔伦米尔的药剂师林度恩。",
    ["D"] = "炼金术很奇妙，$N。有用于灼烧的药水，用于止痛的药剂，用于增强力量的药剂……但有些伤口，有时候真正需要的只是一条干净的布条和稳定的双手。\n\n我的补给太宝贵，不能浪费在治疗药水上。因此，我要你给我带来20根厚绒线绷带。手头有了这些补给，我们就能处理守卫的小伤，把炼金补给留给真正严重的情况。",
  },
  [28495] = {
    ["T"] = "给守卫者加瑞尔的委托",
    ["O"] = "守卫者加瑞尔要你用钓鱼技能收集20条新鲜的滑皮鲭鱼，并把订单交给西部荒野哨兵岭的守卫者加瑞尔。",
    ["D"] = "我已经向暴风城请求更多食物来供给我们的人民，可得到的只有官僚扯皮。人民军需要的是蛋白质，不是空口承诺。\n\n我们的补给又短缺了，而眼下新鲜鱼比腌肉更容易弄到。你有鱼竿。能不能帮我填饱这些饥饿的肚子？如果可以，就钓20条新鲜的滑皮鲭鱼，送到哨兵岭这里交给我。",
  },
  [28496] = {
    ["T"] = "给哈尔·马克奥里斯特的委托",
    ["O"] = "哈尔·马克奥里斯特要你用钓鱼技能收集20条新鲜的长嘴泥鳅，并把订单交给希尔斯布莱德丘陵南海镇的哈尔·马克奥里斯特。",
    ["D"] = "今天早上我把最后的泥鳅做掉了。还没到中午就卖光了！大家都爱吃那东西，加点香料，用热锅一煎，谁也停不下来。\n\n要是你有时间钓鱼，就给我带20条新鲜的长嘴泥鳅来。烹饪交给我——你只要保证供货不断就行。",
  },
  [28498] = {
    ["T"] = "给哨兵奥奈雅的委托",
    ["O"] = "哨兵奥奈雅要你用钓鱼技能收集20条新鲜的鼠尾鱼，并把订单交给灰谷迈斯特拉岗哨的哨兵奥奈雅。",
    ["D"] = "迈斯特拉岗哨的哨兵补给已经越来越少了，尤其缺少新鲜食物。日夜侦察时，光靠肉干可撑不了多久。\n\n我们需要20条新鲜的鼠尾鱼。它们清淡、有营养，也容易在小火上烹调。要是你能带来，我会确保一点都不浪费。",
  },
  [28499] = {
    ["T"] = "给基尔克斯的委托",
    ["O"] = "基尔克斯要你用钓鱼技能收集20条新鲜的彩鳍鱼，并把订单交给贫瘠之地棘齿城的基尔克斯。",
    ["D"] = "我从藏宝海湾到黑暗深渊都钓过鱼，可还从没钓上过彩鳍鱼。听说它们像日出一样闪闪发亮，味道还要好上两倍。\n\n给我带20条新鲜的彩鳍鱼来。我想亲眼看看，也许还要把剩下的煎了。不知道该用什么调味？",
  },
  [28497] = {
    ["T"] = "给瓦格·深水的委托",
    ["O"] = "瓦格·深水要你用钓鱼技能收集20条新鲜的洛克湖狂鱼，并把订单交给洛克莫丹洛克湖岸边的瓦格·深水。",
    ["D"] = "你是这地方新来的$G钓手:钓客;吗？要不要比划比划？我钓洛克湖狂鱼的时候，你怕是连鱼钩都还不会挂饵呢。你觉得自己能比我钓得更多？\n\n给我带20条洛克湖狂鱼来，让我瞧瞧你到底有几分本事。只是等我钓上今天最大那条时，可别太失望。",
  },
  [28514] = {
    ["T"] = "给塔拉·寇德加兹的委托",
    ["O"] = "塔拉·寇德加兹要你用钓鱼技能收集20条新鲜的长嘴泥鳅，并把订单交给希尔斯布莱德丘陵塔伦米尔的塔拉·寇德加兹。",
    ["D"] = "活人以为只有亡灵才渴望血肉。但我们的坐骑……它们也渴望肉的味道。\n\n它们已经没法再啃干草捆了，但仍然渴望生肉。给我带20条新鲜的长嘴泥鳅来——马喜欢它们还在扭动的样子。",
  },
  [28520] = {
    ["T"] = "给维林·疾风的委托",
    ["O"] = "卡利要你用草药学技能收集20株魔皇草，并把订单交给洛克莫丹远行者小屋的维林·疾风。",
    ["D"] = "看你膝盖上沾的那些草渍，我就知道你是个草药师。谢天谢地！我刚收到远行者小屋送来的消息。女猎手维林·疾风急需一些魔皇草，好清理动物咬伤引起的感染。幸好，你看起来正有本事接下这份委托。\n\n尽快把20株魔皇草送给维林吧。我可不想辜负一位高等精灵，她们已经承受太多苦难了。",
  },
  [28525] = {
    ["T"] = "给学徒霍尼韦尔的委托",
    ["O"] = "学徒霍尼韦尔要你用草药学技能收集20株活根草，并把订单交给希尔斯布莱德丘陵南海镇的学徒霍尼韦尔。",
    ["D"] = "日安，$C。我已经准备好开始中级炼金师考试了，但有个问题。我想研究活根草，可最好的活根草产地不是满是饥饿的山地狮，就是离部落实在太近。\n\n你愿意替我采集一些活根草吗？我很乐意给你一些我制作的补给和药水作为回报。",
  },
  [28550] = {
    ["T"] = "给阿兰奈·维诺布拉德的委托",
    ["O"] = "阿兰奈·维诺布拉德要你用草药学技能收集20株活根草，并把订单交给希尔斯布莱德丘陵塔伦米尔的阿兰奈·维诺布拉德。",
    ["D"] = "药剂师林度恩执着于死亡，而我觉得生命要有趣得多……尤其是借由这种形态，或许还能实现的其他生命。\n\n我需要20株活根草来进行一项精细的实验。一项关于重生的实验……重生为蜘蛛！把它们带到塔伦米尔给我。",
  },
  [28564] = {
    ["T"] = "给哨兵加里安的委托",
    ["O"] = "守卫者加瑞尔要你用制皮技能制作2双黑皮战靴，并把订单交给西部荒野哨兵岭的哨兵加里安。",
    ["D"] = "我是人民军的征用官，现在需要一名制皮匠。就是你，对吧？\n\n哨兵加里安日夜在哨兵岭周围巡逻，他的靴子已经快从缝线处散架了。我正在征用替换品——要结实、安静，适合长时间行军。\n\n如果你的制皮手艺已经有些进展，就做几双黑皮战靴并送给他。",
  },
  [28565] = {
    ["T"] = "给守卫者伊万杰琳的委托",
    ["O"] = "守卫者加瑞尔要你用制皮技能制作1件优质皮披风，并把订单交给西部荒野南部道路巡逻线上的守卫者伊万杰琳。",
    ["D"] = "守卫者伊万杰琳日夜巡逻南部道路，从匕首岭吹来的风像迪菲亚的刀刃一样割人。我正在为她征用一件像样的披风。我需要耐用、能挡风雨，也体面的东西。\n\n如果你正在练习制皮，就做一件优质皮披风送给她。她不会主动要求舒适，但她同样配得上。",
  },
  [28568] = {
    ["T"] = "给巡山人奥兹莫克的委托",
    ["O"] = "凯特·桑普森要你用制皮技能制作2条轻皮短裤，并把订单交给洛克莫丹塞尔萨玛的巡山人奥兹莫克。",
    ["D"] = "哦，原来是位训练有素的制皮匠。既然你人在镇上，要不要顺手做点好事？巡山人奥兹莫克这些日子一直穿着一条大风一吹就要散架的裤子，在石头和雪地上爬上爬下。我已经受够了每次巡逻回来都得替他缝缝补补。\n\n要是你想磨炼自己的制皮手艺，就替他做两条轻皮短裤，送到塞尔萨玛交给他吧。他嘴上也许会抱怨几句，但绝不会拒绝。",
  },
  [28569] = {
    ["T"] = "给主工程师辛德维尔七世的委托",
    ["O"] = "凯特·桑普森要你用制皮技能制作1条优质皮带，并把订单交给洛克莫丹巨石水坝的主工程师辛德维尔七世。",
    ["D"] = "主工程师辛德维尔最近老在丢工具。不是比喻，是真的会丢。我是说，他上周皮带断了，扳手砸在巨石水坝上时，半个山谷都听见了那声脆响。我当时还以为大坝要裂开了！\n\n他托人订做一条优质皮带，送到巨石水坝去。要是你愿意拿自己的制皮本事挣点钱，这差事绝对值当。也算是为了大家的安全。",
  },
  [28438] = {
    ["T"] = "给奥雷迪尔·阔叶的委托",
    ["O"] = "净化者德尔格伦要你用工程学技能制作20个烈性炸药，并把订单交给灰谷迈斯特拉岗哨的奥雷迪尔·阔叶。",
    ["D"] = "你好，$C。我来到这里，是为了调查附近被遗忘者的活动。我的邻居奥雷迪尔·阔叶问过我许多关于工程学实践的问题。我相信，他并不像许多其他暗夜精灵看起来那样排斥技术。\n\n我想让奥雷迪尔见识一下工程学能够驾驭的力量。你愿意制作一些烈性炸药并带给他吗？",
  },
  [28439] = {
    ["T"] = "给指挥官斯特朗伯恩的委托",
    ["O"] = "弗拉德·快齿要你用工程学技能制作2个普通瞄准镜，并把订单交给湿地上沼泽伯恩杜拉尔的指挥官斯特朗伯恩。",
    ["D"] = "欢迎来到我简陋的工坊，$C。我收到了一份令人不安的报告，说上沼泽那边出了事。龙喉兽人正在那里集结兵力，我担心伯恩杜拉尔可能正遭到攻击。\n\n指挥官斯特朗伯恩是那边防务的负责人，我这里有他的一份订单，要给他的火枪手配几个普通瞄准镜。唉，我一直还没来得及处理。你能帮帮我，立刻动手做这个吗？",
  },
  [28571] = {
    ["T"] = "给拉尔斯的委托",
    ["O"] = "拉尔斯要你用制皮技能制作1个重型箭袋，并把订单交给暮色森林寂静河岸他自己的营地。",
    ["D"] = "我一直在寂静河岸一带追踪那些狼，可我把箭袋弄丢在乌鸦岭附近了。现在它肯定已经被撕成碎片，所以我需要一个新的。\n\n你受过制皮训练？那你能不能替我做一个像样的重型箭袋？我需要结实的东西，能装下足够的箭，让我撑过一整天的狩猎再回来。",
  },
  [28573] = {
    ["T"] = "给弗纳·奥斯古的委托",
    ["O"] = "克莱德·兰萨尔要你用制皮技能制作1副韧化皮手套，并把订单交给赤脊山湖畔镇的弗纳·奥斯古。",
    ["D"] = "弗纳·奥斯古在湖畔镇的马厩里干了很多年，在暴风城的王室似乎不怎么关心我们时，一直照看着镇上的人。也正因为这样，我们家才搬到这里来——以防兽人袭击……不过我不必拿本地政治烦你。我需要你的帮助。\n\n我想委托你给弗纳做一副非常特别的韧化皮手套。他有匹新小母马特别爱拽缰绳，旧手套已经把他的手磨出了水泡。让弗纳能继续干活，也算是为赤脊山所有人服务。",
  },
  [28574] = {
    ["T"] = "给埃纳尔·石钳的委托",
    ["O"] = "詹姆斯·哈洛兰要你用制皮技能制作1副造弓师手套，并把订单交给湿地绿带草地南边十字路口的埃纳尔·石钳。",
    ["D"] = "我看见你处理生皮的手法了。制皮匠？我这儿有份活给你。\n\n埃纳尔·石钳是我最好的猎人——可他的手套快散架了，我已经看够他用缠着布的手指和一股倔劲给弓搭箭。他不会开口要新的造弓师手套，所以我替他说。",
  },
  [28596] = {
    ["T"] = "给塔洛的委托",
    ["O"] = "乔治·坎达特要你用制皮技能制作1个重型箭袋，并把订单交给希尔斯布莱德丘陵塔伦米尔的塔洛。",
    ["D"] = "一个叫塔洛的猎人一直在塔伦米尔边缘追踪山地狮，可他把箭袋弄丢在绞刑场一带了。我敢肯定那些食人魔现在已经把它撕成碎片，所以他需要一个新的。\n\n你受过制皮训练？那你能不能替他做一个像样的重型箭袋？他需要结实的东西，能装下足够的箭，让他撑过一整天的狩猎再回来。别担心他的宠物。他进镇时会把那头凶东西关在马厩里。",
  },
  [28637] = {
    ["T"] = "给勘察员铁环的委托",
    ["O"] = "布洛克·寻石者要你用采矿技能收集10块银矿石，并把订单交给洛克莫丹铁环挖掘场的勘察员铁环。",
    ["D"] = "啊，是个矿工。我这儿正有份活给你。\n\n铁环那家伙又在念叨要银矿石了。他说挖掘场那边某种刻着符文的装置缺了这东西。什么泰坦遗物、银质矩阵，在我听来都只是神神叨叨的胡扯！\n\n总之，自从银泉矿洞挖空以后，我这边就再也没有多余的银矿了。你要是顺路能帮我留意一些，再给他送过去，那就太好了。还有，除非你时间多得很，不然可别让他缠着你讲矮人历史。",
  },
  [28638] = {
    ["T"] = "给加文·纳尔特里的委托",
    ["O"] = "加文·纳尔特里要你用采矿技能收集20块锡矿石，并把订单交给暮色森林夜色镇的加文·纳尔特里。",
    ["D"] = "我手头的铜多得不知道该怎么办，可没有锡，我就没法熔炼青铜。问题是，树林里潜伏着那些东西，离开镇子实在太危险。\n\n你能给我带来20块锡矿石吗？这样我就能让熔炉继续开工，还不用把自己喂给黑暗里的东西。",
  },
  [28639] = {
    ["T"] = "给赫尔姆斯沃西少校的委托",
    ["O"] = "卫兵帕克斯顿要你用采矿技能收集20块锡锭，并把订单交给希尔斯布莱德丘陵南海镇的赫尔姆斯沃西少校。",
    ["D"] = "嘿，你！拿矿镐的那个。联盟需要你的帮助。\n\n刚刚来了命令：南海镇那边的赫尔姆斯沃西少校需要20块锡锭来制作配件和进行修理。问题是，我们这座矿洞已经不再产锡了。\n\n找到这些锡锭，把它们送到南海镇给他。他可不喜欢等人。",
  },
  [28663] = {
    ["T"] = "给克里斯托弗·杰弗寇特的委托",
    ["O"] = "克里斯托弗·杰弗寇特要你用采矿技能收集20块锡锭，并把订单交给希尔斯布莱德丘陵塔伦米尔的克里斯托弗·杰弗寇特。",
    ["D"] = "嘿，你！拿矿镐的那个。我需要你的帮助。\n\n刚刚来了订单：我需要20块锡锭来制作配件和进行修理。问题是，我们这里可没法凭空变出锡来。\n\n你能不能去采矿、熔炼这些锡锭，然后把它们送给我？黑暗女王可不喜欢被人拖延。",
  },
  [28645] = {
    ["T"] = "给指挥官斯特朗伯恩的委托",
    ["O"] = "指挥官斯特朗伯恩要你用采矿技能收集10块钢锭，并把订单交给湿地伯恩杜拉尔的指挥官斯特朗伯恩。",
    ["D"] = "瞧瞧这肱二头肌！你要么是矿工，要么就是铁匠最怕遇见的噩梦。不管怎样，我需要你的力气。\n\n看见这道路障了吗？我们已经用尽所有办法才勉强撑住它，而兽人还在不断冲来。我需要10块钢锭来加固它，越快越好！",
  },
  [28679] = {
    ["T"] = "给达芙妮·斯迪威尔的委托",
    ["O"] = "守卫者加瑞尔要你用裁缝技能制作4件灰色毛纺衬衣，并把订单交给西部荒野西南部匕首岭她农场里的达芙妮·斯迪威尔。",
    ["D"] = "身为人民军的征用员，我有责任照顾仍留在西部荒野的平民，也要照顾民兵成员。\n\n达芙妮·斯迪威尔独自住在矿洞外面，西南部匕首岭水边的位置。那地方会变冷，我上次经过时，她穿的东西连蜡烛都保不住暖。如果你有裁缝手艺，一套像样的灰色毛纺衬衣会对她很有帮助。",
  },
  [28680] = {
    ["T"] = "给萨尔玛·萨丁的委托",
    ["O"] = "守卫者加瑞尔要你用裁缝技能制作2双毛纺靴，并把订单交给西部荒野萨丁农场的萨尔玛·萨丁。",
    ["D"] = "西部荒野的人民已经忍耐匮乏太久了——但你可以用一些办法帮忙。萨尔玛·萨丁从清晨忙到黄昏，一直在农场劳作，还总为民兵准备热饭。这个可怜女人脚上几乎只有一双凉鞋！我已经获准代她征用两双毛纺靴。现在只差裁缝了。是你吗？",
  },
  [28681] = {
    ["T"] = "给巴苏尔·影击的委托",
    ["O"] = "沙尔迪恩要你用裁缝技能制作1件珍珠披风，并把订单交给黑海岸奥萨拉克斯之塔的巴苏尔·影击。",
    ["D"] = "巴苏尔已经驻守在奥萨拉克斯之塔好几个星期了，海上吹来的寒风和塔中不断滋长的黑暗始终环绕着他。他绝不会离开岗位——哪怕只是去取件披风。\n\n这正是需要像你这样的裁缝出手的时候。我希望你替他做一件珍珠披风，多少为他添些温暖与慰藉。请把它送到黑海岸北部交给他，也让他知道，即便职责在身，他也没有被人遗忘。",
  },
  [28682] = {
    ["T"] = "给考古学家埃弗里特的委托",
    ["O"] = "沙尔迪恩要你用裁缝技能制作2双高级毛纺手套，并把订单交给黑海岸雷姆塔维尔挖掘场的考古学家埃弗里特。",
    ["D"] = "我之前接到一份订单，对方想要几双结实又厚实的手套，可我手头并没有适合交给那位矮人的现货。要是你愿意帮忙，就做两双高级毛纺手套，送到雷姆塔维尔挖掘场交给考古学家埃弗里特吧。",
  },
  [28683] = {
    ["T"] = "给巡山人库伯弗林特的委托",
    ["O"] = "奥德伦·科尔东要你用裁缝技能制作2个毛纺包，并把订单交给洛克莫丹国王谷的巡山人库伯弗林特。",
    ["D"] = "我手头正积着几份来自洛克莫丹的旧订单，正缺一位手艺熟练的裁缝来搭把手。你有兴趣吗？\n\n巡山人库伯弗林特眼神够利，专挑那些亮晶晶的石头往兜里塞，问题是他装得太多，把旧包都给撑破了。\n\n我这里正好有份给他的订单，要两只新的毛纺包。上次听说时，他还驻守在国王谷那边。",
  },
  [28684] = {
    ["T"] = "给巡山人哈吉尔的委托",
    ["O"] = "奥德伦·科尔东要你用裁缝技能制作1条手工亚麻裤，并把订单交给洛克莫丹巨石水坝的巡山人哈吉尔。",
    ["D"] = "大坝那边传来消息，说巡山人哈吉尔从支撑梁上往下爬时摔了一跤，把裤子扯了个大口子。打那以后，他就一直靠绳子和一股倔劲勉强把它缝在身上。\n\n要是你不介意顺手把这份订单也接了，就做一条手工亚麻裤，替我送到巨石水坝去吧。",
  },
  [28685] = {
    ["T"] = "给守夜人考拉哈恩的委托",
    ["O"] = "丹尼勒·希普斯迪要你用裁缝技能制作2个丝绸小包，并把订单交给暮色森林暗色河滩的守夜人考拉哈恩。",
    ["D"] = "我妹妹以为只要眨眨眼、烤点面包，就能赢得守夜人考拉哈恩的心。拜托。他需要的是像我这样实际的人！\n\n我们需要一个中立的评判者来评判我们的礼物。要是你能做几个丝绸小包，送到赤脊桥南边暗色河滩附近的守夜人考拉哈恩那里，我就能证明自己知道一个勤劳男人真正欣赏的是什么！",
  },
  [28686] = {
    ["T"] = "给基特斯的委托",
    ["O"] = "雪莉·希普斯迪要你用裁缝技能制作1件碧蓝丝质外衣，并把订单交给暮色森林暗色河滩的基特斯。",
    ["D"] = "所以丹尼勒以为我在讨好那个无聊的老守夜人？才不是！我的心上人有品味，有野心，还有门路。他是……好吧，他是个地精。但可不是随便哪个地精——他是基特斯，一个有品位的商人。\n\n既然丹尼勒想把这变成比赛，那我就奉陪。给基特斯做一件碧蓝丝质外衣。他一定会印象深刻，我敢打赌他会把湖畔镇那个荡妇忘得一干二净！",
  },
  [28688] = {
    ["T"] = "给格雷彻·沃格尔的委托",
    ["O"] = "格雷彻·沃格尔要你用裁缝技能制作2件次级巫师袍，并把订单交给赤脊山湖畔镇的格雷彻·沃格尔。",
    ["D"] = "我已经下定决心了！我不想再给那些不知感激的镇民倒酒了，我想研究卷轴。艾尔文森林的阿祖拉之塔已经答应给我一个学徒位置，我打算去。\n\n可要去塔里，我就得有个像样的样子。要是你能替我做几件次级巫师袍，那对我意义重大。我希望他们看到的不是一个学生，而是一个准备好成为法师的人。",
  },
  [28689] = {
    ["T"] = "给领航员克劳利的委托",
    ["O"] = "领航员克劳利要你用裁缝技能制作2副冥想手套，并把订单交给湿地米奈希尔港的领航员克劳利。",
    ["D"] = "大海要求专注。一个杂念，就可能让船漂向礁石，甚至更糟。我掌舵美德少女号时，需要清醒的头脑和稳定的双手。\n\n我听说过冥想手套：轻便、舒适，还附有安抚精神的魔法。如果你能做，我想要几副。不用花哨。只要能在我引我们回家时，让这个世界的喧嚣别在我脑子里乱撞就行。",
  },
  [28691] = {
    ["T"] = "给赫米特·阿姆斯特朗的委托",
    ["O"] = "塔玛拉·阿姆斯特朗要你用裁缝技能制作1件丝质长披风，并把订单交给希尔斯布莱德丘陵南海镇的赫米特·阿姆斯特朗。",
    ["D"] = "巴托罗居然想卖给我一件雪人毛皮做的披风——你能相信吗？太离谱了。赫米特需要的是轻便透气的东西，不是重到能拿去摔跤的玩意儿。\n\n要是你会缝纫，就请做一件丝质长披风，把它带到这里给我们。赫米特没有能保暖的东西，我们就没法继续旅行。",
  },
  [28710] = {
    ["T"] = "给亡灵哨兵莱什的委托",
    ["O"] = "玛伦·斯温要你用裁缝技能制作1件碧蓝丝质外衣，并把订单交给希尔斯布莱德丘陵南点哨塔的亡灵哨兵莱什。",
    ["D"] = "亡灵哨兵莱什的差事并不让人羡慕。她独自驻守在南点哨塔。我都不记得上次有人给她送补给是什么时候了。\n\n我年纪太大，已经很难把线穿过针眼了，$N。也许你能帮帮这把老骨头，给莱什做一件碧蓝丝质外衣。告诉她，她让她叔叔感到骄傲。",
  },
  [28722] = {
    ["T"] = "暗矛部族",
    ["O"] = "与杜隆塔尔暗矛岛的乔兹加兹谈一谈。",
    ["D"] = "啊，$N，你总算来找我了。准备好为部族效力了吗？\n\n我们找了很久才找到如今这个家园，而我觉得这次终于找对了。沃金与部落结盟，让我们得到了多年来一直追寻的安稳。\n\n但这并不表示我们就没有麻烦要处理了。你愿意自告奋勇吗？我这里正有一件适合新手的差事。",
  },
  [28723] = {
    ["T"] = "偷食的螃蟹",
    ["O"] = "消灭10只紫水晶螃蟹，然后向暗矛岛桥对面的达兹提罗复命。",
    ["D"] = "我们在暗矛岛上过得还算舒服，但如果不把这些螃蟹管住，这种日子可长不了。它们一直在闯进我们的粮仓偷东西！\n\n所以你的第一项任务很简单——清掉这些螃蟹，顺便别被它们夹着了。\n\n做完以后，就去桥对面找达兹提罗复命。她还会给你更多差事。",
  },
  [28725] = {
    ["T"] = "进入 G.E.A.R.",
    ["O"] = "为丹莫罗 G.E.A.R. 的工匠队长哨钉消灭10只瘦弱的穴居人。",
    ["D"] = "啊，又有一个健康的侏儒解除隔离了！我知道那次电车事故让人心烦意乱，但现在没时间沉浸在这种情绪里。我们正身处危机之中，我需要你的帮助！\n\n侏儒紧急集合路线——简称 G.E.A.R.——正受到从下方涌上来的穴居人的威胁。考虑到你在地下困了那么久，你的状态看起来还不错。你愿意帮我们吗？",
  },
  [28726] = {
    ["T"] = "无暇怜悯",
    ["O"] = "为丹莫罗 G.E.A.R. 的工匠队长哨钉消灭8团辐射软泥怪，并让4个被感染的侏儒彻底解脱。",
    ["D"] = "天哪，$N，你收拾那些穴居人的样子简直像个老练的$C。如果你愿意继续帮忙，我这里还有一件非做不可的任务。\n\n从诺莫瑞根灾难中爬出来的可不只有穴居人。辐射软泥怪让一些幸存者染上了古怪的病症，神志错乱、变得狂暴。现在还没有解药，如果我们不采取行动，就会有更多侏儒受到感染。求你做该做的事：消灭那些软泥怪，让受感染的侏儒得到解脱。\n\n你会在 G.E.A.R. 前方的洞穴里看见他们漫无目的地徘徊。",
  },
  [28727] = {
    ["T"] = "雕文备忘录",
    ["O"] = "阅读雕文备忘录，然后与丹莫罗 G.E.A.R. 内的玛瑞克·纳比特谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这份备忘录转交给你。有空的时候读一读吧。我想这应该是法师训练师玛瑞克寄来的。等你有空时，到 G.E.A.R. 里面去找她。",
  },
  [28728] = {
    ["T"] = "雕文石板",
    ["O"] = "阅读雕文石板，然后与暗矛岛村里的迈安谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是法师训练师迈安寄来的。去山坡上村子里找她。",
  },
  [28729] = {
    ["T"] = "神圣备忘录",
    ["O"] = "阅读神圣备忘录，然后与丹莫罗 G.E.A.R. 内的努尔茜·旋轮谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这份备忘录转交给你。有空的时候读一读吧。我想这应该是牧师训练师努尔茜寄来的。等你有空时，到 G.E.A.R. 里面去找他。",
  },
  [28730] = {
    ["T"] = "神圣石板",
    ["O"] = "阅读神圣石板，然后与暗矛岛村里的肯杰谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是牧师训练师肯杰寄来的。去山坡上村子里找他。",
  },
  [28731] = {
    ["T"] = "加密备忘录",
    ["O"] = "阅读加密备忘录，然后与丹莫罗 G.E.A.R. 内的温德尔·火簧谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这份备忘录转交给你。有空的时候读一读吧。我想这应该是潜行者训练师温德尔寄来的。等你有空时，到 G.E.A.R. 里面去找他。",
  },
  [28732] = {
    ["T"] = "密文石板",
    ["O"] = "阅读密文石板，然后与暗矛岛村里的塔凯谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是潜行者训练师塔凯寄来的。去山坡上村子里找他。",
  },
  [28733] = {
    ["T"] = "大地的召唤",
    ["O"] = "把2瓶沉积物交给杜隆塔尔暗矛岛的坎纳甘·地鸣。",
    ["D"] = "时候到了，年轻的$C。你的身躯已足够强健，精神也如大地般坚韧。既然你选择了萨满之路，就说明你在尚未证明自己之前，便已拥有了智慧。\n\n大地元素将指引你的命运；若你已经准备好，它也会成为你的一部分。但你必须先亲自站到大地面前。只要你准备好了，就会看见那些只有萨满才能看见的东西。\n\n去南边的洞穴寻找活泥怪，从它们身上收集两瓶沉积物。回来以后，我们再谈你的未来。",
  },
  [28734] = {
    ["T"] = "大地的召唤",
    ["O"] = "找到暗矛岛上的升腾大地祭坛，并在那里喝下大地灵契。",
    ["D"] = "灵契是一种能在我们的灵魂与元素之间建立联系的药水。这种融入了魔法的药水，会让意志坚定之人看见别人所看不见的元素。你的灵魂将与灵契对应的元素相连，只有极少数萨满才知道这种配方。\n\n灵契只能在神圣之地饮下，绝不能在别处使用——记住这一点。\n\n去北边寻找升腾大地祭坛吧。它藏在西侧山丘背后的一条隐秘小径尽头。到了那里再喝下你的灵契，然后……你自然就会明白。",
  },
  [28735] = {
    ["T"] = "大地的召唤",
    ["O"] = "把粗石英交给杜隆塔尔暗矛岛村里的坎纳甘·地鸣。",
    ["D"] = "把这块粗石英带回去交给坎纳甘·地鸣，作为我们已经相见的证明。他会为你制作一根图腾，而这块小石英就是那图腾的核心。它看起来也许很小，但你很快就会明白，大小并不重要——即使是最微小的东西，也可能比许多庞然大物更加恒久。\n\n耐心些，$N。保持坚强，并追寻智慧。这正是大地向你索求的东西。终有一日，你将与大地融为一体——尊重它，它也会尊重你。",
  },
  [28736] = {
    ["T"] = "符文石板",
    ["O"] = "阅读符文石板，然后与暗矛岛村里的伊希谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是萨满祭司训练师伊希寄来的。去山坡上村子里找他。",
  },
  [28737] = {
    ["T"] = "腐蚀备忘录",
    ["O"] = "阅读腐蚀备忘录，然后与丹莫罗 G.E.A.R. 内的阿拉玛·格里姆谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这份备忘录转交给你。有空的时候读一读吧。我想这应该是术士训练师阿拉玛寄来的。等你有空时，到 G.E.A.R. 里面去找他……不过你要知道，我会盯着你的。这里很多人都不信任你所修习的黑暗魔法。",
  },
  [28738] = {
    ["T"] = "开端",
    ["O"] = "把3枚羽饰符咒交给丹莫罗 G.E.A.R. 内的阿拉玛·格里姆。",
    ["D"] = "我答应过要训练你，现在也该开始了。你越快成功——或者死在尝试的路上——我就越快能回到自己的研究里去。\n\n你将学会的召唤法术中，最基础的就是召唤小鬼。在我把这项知识交给你之前，你得先证明自己具备控制魔法的能力。\n\n去北边的霜鬃洞穴，从住在那里的霜鬃新兵身上带回三枚羽饰符咒。",
  },
  [28739] = {
    ["T"] = "艾萨拉神像",
    ["O"] = "把3尊艾萨拉神像交给杜隆塔尔暗矛岛村里的乌瓦。",
    ["D"] = "暗影的黑暗之道在部落里并不受信任。我们这些术士只是被勉强容忍着……勉强而已。\n\n妖术若落到门外汉手里，只会带来危险。我不会逼你走上哪条路，但我确实想请你帮我收拾一个小麻烦。当然，作为回报，我会赐予你力量。\n\n去南边的纳迦洞穴，带三尊艾萨拉神像回来给我。那些纳迦侍僧身上带着这东西，它们会对我的研究有用。",
  },
  [28740] = {
    ["T"] = "被污染的石板",
    ["O"] = "阅读被污染的石板，然后与暗矛岛村里的乌瓦谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是术士训练师乌瓦寄来的。去山坡上村子里找她。",
  },
  [28741] = {
    ["T"] = "简易备忘录",
    ["O"] = "阅读简易备忘录，然后与丹莫罗 G.E.A.R. 内的法兹巴尔·陀钮谈一谈。",
    ["D"] = "在你帮我办事的时候，有人托我把这份备忘录转交给你。有空的时候读一读吧。我想这应该是战士训练师法兹巴尔寄来的。等你有空时，到 G.E.A.R. 里面去找他。",
  },
  [28742] = {
    ["T"] = "普通石板",
    ["O"] = "阅读普通石板，然后与暗矛岛村里的塔瑟蕾谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是战士训练师塔瑟蕾寄来的。去山坡上村子里找她。",
  },
  [28743] = {
    ["T"] = "工匠的工具",
    ["O"] = "从寒脊山谷西南部的营地里找回格伦德尔的护腕、格伦德尔的胸甲和格伦德尔的战锤，把它们交给安威玛尔的格伦德尔·哈金。",
    ["D"] = "直到巨魔搬到附近来之前，我一直都在寒脊山谷西南边一处不错的营地里做手工活。元素一被搅得不安分，我就赶紧逃回了安威玛尔，把我的工作和工具全都落在了那里。现在它们多半已经散落得到处都是。\n\n我可不是冒险者，但你看起来挺有精神。你能帮我把那些东西找回来，带到这里给我吗？",
  },
  [28744] = {
    ["T"] = "躁动的元素",
    ["O"] = "格瑞林·白须希望你在寒脊山谷消灭14个冰元素。",
    ["D"] = "我的兄弟森内尔和我被派到丹莫罗的不同区域，调查霜鬃巨魔带来的威胁。议会现在正忙着对付穴居人，可不需要再添别的麻烦。\n\n就我目前所见，寒脊山谷这里没有巨魔，只有一群不安分的冰元素。我们还是得解决这个问题。我看用不着出动军队，几个有力气的人就足够了。\n\n也许你愿意帮上一把？我有权为你的帮助提供报酬。",
  },
  [28745] = {
    ["T"] = "寒霜法师",
    ["O"] = "格瑞林·白须要你前往西南边的洞穴进行调查，并干掉那个搅动冰元素的家伙。",
    ["D"] = "我越想越觉得，一定有人在背后搅动这些元素。也许这才是我兄弟想找的巨魔威胁？\n\n你对付那些元素干得不错，所以我想让你进那边的洞穴搜查一番，找出它们的头目。要是你真找到了，你知道该怎么做。",
  },
  [28746] = {
    ["T"] = "难民的困境",
    ["O"] = "把费利克斯的箱子、费利克斯的提箱和费利克斯的一桶螺栓交给丹莫罗 G.E.A.R. 的费利克斯·旋栓。",
    ["D"] = "我们把穴居人赶出了诺莫瑞根，可接下来一切都变得糟透了！如今我们的家园被彻底辐射污染，侏儒们也四散在丹莫罗各处。\n\n我为了逃离辐射，慌忙中把所有私人物品和工具都弄丢了。都是那些穴居人干的！他们偷走了我的箱子、提箱和那桶螺栓，把它们带回了 G.E.A.R. 外面、霜鬃峰迎风山壁上的营地。\n\n我不是冒险者——你能帮我把那些东西找回来，带到这里给我吗？",
  },
  [28747] = {
    ["T"] = "紧急补给",
    ["O"] = "把紧急补给包交给丹莫罗霜鬃峰的安东·火辉。",
    ["D"] = "你能帮我个忙吗？我看见你在帮工匠队长哨钉，而且你看起来值得信赖。我需要有人把这些紧急补给送给安东·火辉。\n\n你可以在 G.E.A.R. 外面找到他，他就在霜鬃峰另一边的营地里。怎么样？你愿意帮忙吗？",
  },
  [28748] = {
    ["T"] = "紧急补给",
    ["O"] = "把紧急毛毯交给丹莫罗霜鬃峰的迪兹雷·旋卡。",
    ["D"] = "这条紧急毛毯交给迪兹雷·旋卡会更有用。你为什么不替我把它送过去呢？\n\n据我所知，他驻扎在东南边那条通往山顶的小路附近。",
  },
  [28749] = {
    ["T"] = "霜鬃洞穴",
    ["O"] = "为丹莫罗霜鬃峰的莱拉·链火消灭14个霜鬃巨魔幼崽。",
    ["D"] = "安东·火辉担心那些穴居人，这一点没错……但我害怕的是，地平线上还潜伏着一个更古老也更危险的敌人。\n\n霜鬃巨魔一直把猎杀侏儒当成消遣。诺莫瑞根建立之后，他们就消失了。如今城市陷落，他们又回到了北边洞穴里的旧巢穴。\n\n我们不能让他们在我们的紧急出口附近站稳脚跟。也许你愿意帮我们清除这个威胁？我得到授权，可以奖励任何愿意为诺莫瑞根而战的人。",
  },
  [28750] = {
    ["T"] = "失窃的眼镜",
    ["O"] = "丹莫罗霜鬃峰的莱拉·链火要你进入霜鬃洞穴，杀死弗拉基尔，并取回她的目镜放大阵列。",
    ["D"] = "我的眼镜！我敢打赌那些巨魔把它带到北边的洞穴里去了——霜鬃洞穴。他们一直在偷我们的东西，把那些玩意儿当作献给他们酋长弗拉基尔的礼物。\n\n你对付这些巨魔已经挺有办法了。也许你能帮我把目镜放大阵列拿回来？",
  },
  [28751] = {
    ["T"] = "霜鬃报告",
    ["O"] = "把莱拉·链火的报告交给丹莫罗寒脊山小径上的迪兹雷·旋卡。",
    ["D"] = "像这样对霜鬃巨魔取得的重大胜利，必须上报给有关当局……只是我不太确定该找谁，也不太清楚他们在哪儿。\n\n既然这是你的功劳，那就该由你亲自去递交这份报告。去找迪兹雷·旋卡吧。他会知道该把报告交给谁。你可以在东南边寒脊山小径旁的一处营地里找到他。",
  },
  [28752] = {
    ["T"] = "霜鬃报告",
    ["O"] = "把莱拉·链火的报告交给丹莫罗卡拉诺斯的森内尔·白须。",
    ["D"] = "霜鬃峰顶上的那些野兽都很凶恶。你沿着寒脊山小径往下走的时候，肯定会受到袭击。不过你看起来挺硬朗的，尤其是你还收拾了霜鬃洞穴里的那些巨魔。\n\n至于你接下来该去哪儿，穿过洞穴下到通往卡拉诺斯的道路上就行。你会在镇上找到森内尔·白须。他是这里的负责人，知道该怎么处理这份报告。",
  },
  [28753] = {
    ["T"] = "冰冻蛛丝",
    ["O"] = "迪兹雷·旋卡要你收集4份冰霜蜘蛛丝，把它们交给丹莫罗卡拉诺斯的格特·皮革匠。",
    ["D"] = "既然你正好要穿过寒脊山小径，不如顺便赚点小钱，怎么样？\n\n我在卡拉诺斯有个朋友，是处理各种野兽材料的行家，而且她也喜欢用蜘蛛丝做东西。你下山的时候会碰见不少冰霜蜘蛛。收集一些蛛丝带给她，格特会为这些东西付你报酬的。",
  },
  [28754] = {
    ["T"] = "给提迪·废栓的信",
    ["O"] = "把拉兹尔·废栓的信交给卡拉诺斯雷酒酿制厂的提迪·废栓。",
    ["D"] = "你要离开 G.E.A.R. 了吗？如果你正好要去卡拉诺斯，我这里有一封信想请你替我带给那边的兄弟。只要你穿过寒脊山小径，就一定会想在雷酒酿制厂歇上一歇。\n\n到了那里以后，去找提迪·废栓。谢谢你！",
  },
  [28755] = {
    ["T"] = "蜘蛛坦克零件",
    ["O"] = "在寒脊山小径找到那批蜘蛛坦克零件，把它们交给丹莫罗的齐尔菲兹·爆柄。",
    ["D"] = "$C！能请你稍微留步一下吗？我知道你大概正急着赶去卡拉诺斯，可我需要帮忙。\n\n我正等着一批替换零件，好修理这台我设法从诺莫瑞根里弄出来的蜘蛛坦克。送货员迟迟没有到，我担心他可能被冰霜蜘蛛截住了。\n\n你能不能沿着寒脊山小径找找那些零件的下落？如果你找到了，能抽空替我把它们带回来，我会非常感激。",
  },
  [28756] = {
    ["T"] = "穴居人之城",
    ["O"] = "为丹莫罗霜鬃峰的安东·火辉消灭6个瘦小的石腭穴居人和6个粗野的石腭穴居人。",
    ["D"] = "G.E.A.R. 的负责人正尽力保证紧急集合路线的安全，好让我们继续把被隔离的市民从诺莫瑞根下层撤离出来。可事实很简单——这里的穴居人实在太多了！看看他们在山顶上晃来晃去的样子，简直像这地方是他们的一样！里面是穴居人之城，外面也是！\n\n击倒他们并不能让我们失去的人回来，但从长远来看，这会让我们夺回城市的努力轻松一些。你愿意帮忙吗？",
  },
  [28757] = {
    ["T"] = "香蕉大丰收",
    ["O"] = "达兹提罗要你为杜隆塔尔暗矛岛的阿兹萨里收集10根日晒成熟的香蕉。",
    ["D"] = "你也许已经阻止了那些螃蟹袭击我们的粮仓，但它们糟蹋掉的食物还得有人补回来。\n\n到岛上去，在每一棵棕榈树周围找找那些香甜成熟的香蕉。那儿应该多得很。收集好以后，把它们带给村里的阿兹萨里。他会拿仓库里的好吃的跟你换。",
  },
  [28758] = {
    ["T"] = "贝壳收集",
    ["O"] = "从暗矛岛四周的潮滩和浅水区收集8枚热带海贝，交给阿兹萨里。",
    ["D"] = "你最近帮了不少忙，如果你有兴趣，阿兹萨里这儿还有一件差事。\n\n这里的海贝都很漂亮，做小工具和首饰都很合适。我们还能再多弄一些。去暗矛岛四周的浅水区收集一些吧。",
  },
  [28759] = {
    ["T"] = "猛虎之爪",
    ["O"] = "从幼虎身上收集10只锋利的虎爪，把它们带给杜隆塔尔暗矛岛的猎手邦朱鲁。",
    ["D"] = "暗矛部族征服了这些岛上的纳迦，但当地的威胁依旧存在。如今老虎比以往任何时候都多，谁离开村子都可能遭到它们袭击。\n\n你想为暗矛而战吗？去干掉那些老虎，把它们的爪子带回来给我当作证明！",
  },
  [28760] = {
    ["T"] = "中邪的巨魔",
    ["O"] = "替杜隆塔尔暗矛岛的巫医莉瑞娅教训8个中邪的巨魔。",
    ["D"] = "一个初出茅庐的$C？这差事正适合你这样的$R。\n\n最近，我们有些族人老往南边的旧废墟跑，举止也越来越古怪，村里的长者们却弄不清缘由。\n\n过去看看吧。也许你得先把他们打醒，他们才肯开口！",
  },
  [28761] = {
    ["T"] = "邪咒之源",
    ["O"] = "替杜隆塔尔暗矛岛的巫医莉瑞娅在暗矛岛上某处找到邪咒的源头。",
    ["D"] = "这么说，那些中邪的巨魔是因为读了卷轴才中了妖术？我们得把那东西找出来，终结这场诅咒。\n\n到目前为止，你一直是个可靠的$C。去岛上四处找找那张卷轴吧！\n\n要我猜的话，它多半在岛另一头的废墟附近，就在最南边、靠岸边码头的地方。那些中邪的巨魔最喜欢在那里晃荡。",
  },
  [28762] = {
    ["T"] = "向加德林大师汇报",
    ["O"] = "与杜隆塔尔森金村的加德林大师谈一谈。",
    ["D"] = "我对这张卷轴的来历已经有些猜测，但还是该由森金村的加德林大师亲自查看。\n\n把这张卷轴带给他。你会在西南边水对岸的森金村找到他。沿着码头和海边的沙洲走，很快就能到了。",
  },
  [28763] = {
    ["T"] = "向剃刀岭汇报",
    ["O"] = "向剃刀岭的当权者报告库尔提拉斯人袭击了拉兹菲里的小屋。",
    ["D"] = "昨晚我去森金村参加节庆，今早回来时，小屋就成了这副模样……被烧得只剩焦炭！\n\n我知道是谁干的，$N。就是水对岸提拉加德城堡里的那些库尔提拉斯人。\n\n部落不是该保护我们不受人类侵害吗？去剃刀岭告诉那些管事的人，让他们狠狠收拾这些恶狗。\n\n我可不建议你穿过提拉加德过去。沿着海岸先到森金村，再顺着内陆道路去剃刀岭就行。你甚至还能搭辆车，让路程快一些。",
  },
  [28764] = {
    ["T"] = "死亡洛阿",
    ["O"] = "阅读洞穴里和泉水旁的邦桑迪石板，然后回到杜隆塔尔暗矛岛的马卡斯加那里。",
    ["D"] = "你小时候肯定听说过洛阿。自从我们脱离古拉巴什帝国之后，这些强大的灵魂大多都不再理会暗矛。\n\n但邦桑迪没有。\n\n长者们在村外的洞穴里和镇南边的泉水旁立下了石板，把那些不能直说的事写在上面。在你踏上更广阔的世界之前，先好好温习我们与邦桑迪之间的约定吧——不然等你真的遇到他时，很可能会中了他的把戏！",
  },
  [28765] = {
    ["T"] = "潮汐威胁",
    ["O"] = "为杜隆塔尔暗矛岛的猎手邦朱鲁消灭12个鱼人潮汐战士。",
    ["D"] = "说到敌人……纳迦虽已被击退，它们的爪牙却还留着。我说的就是岛南海岸那些鱼人。到那里的潮滩去，在问题蔓延之前把它们处理掉。这些家伙可不只是些野兽那么简单。希望我们还能再见……",
  },
  [28766] = {
    ["T"] = "奇异贝壳袋",
    ["O"] = "把奇异贝壳袋交给杜隆塔尔暗矛岛的猎手邦朱鲁。",
    ["D"] = "这只鱼人身上带着一袋奇怪的贝壳。你不确定它们有什么用，但猎手邦朱鲁多半会对这东西感兴趣。",
  },
  [28767] = {
    ["T"] = "纳迦威胁",
    ["O"] = "杀死潮汐女主人莉亚娜，把她的三叉戟带给杜隆塔尔暗矛岛的猎手邦朱鲁。",
    ["D"] = "这些可不是什么普通贝壳，$N。这些是纳迦用来支付海中盟友的货币。我早就怀疑这些鱼人不可能自己组织得这么严密，它们背后一定有某个纳迦首领在操纵。\n\n你必须杀了这个纳迦，否则它们很可能会集结更多兵力回来夺回这座岛。去东南边潮滩附近的洞穴找找。要藏身的话，那里最像是那个首领会待的地方。",
  },
  [28768] = {
    ["T"] = "风蚀羊皮纸",
    ["O"] = "阅读风蚀石板，然后与暗矛岛村里的简珊谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是猎人训练师简珊寄来的。去山坡上村子里找她。",
  },
  [28769] = {
    ["T"] = "风蚀石板",
    ["O"] = "阅读风蚀石板，然后与暗矛岛村里的简珊谈一谈。",
    ["D"] = "你帮我干活的时候，有人托我把这块石板转交给你。有空就读一读吧。我想这应该是猎人训练师简珊寄来的。去山坡上村子里找她。",
  },
  [28425] = {
    ["T"] = "给哈格德元帅的委托",
    ["O"] = "主管瑞琳要你用工程学技能制作20枚劣质铜壳炸弹，并把订单交给艾尔文森林东谷伐木场的哈格德元帅。",
    ["D"] = "喂，既然你是工程师，这里还有另一件事可以请你帮忙。\n\n那边的哈格德元帅在暴风城卫兵中服役几十年了。有时候他半夜醒来，还会想起第二次和第三次战争的情景……他再也没有安全感了。我想他需要的是一点火力。你知道的，能放在身边让人安心的东西。我说的是炸药，$N。一大堆劣质铜壳炸弹会让他觉得自己拥有一座私人军火库。",
  },
  [31002] = {
    ["T"] = "向逝者致敬",
    ["O"] = "暴风城的梅尔瑞斯·玛拉甘要你向一群在冬泉谷东部阵亡的士兵致敬。",
    ["D"] = "",
  },
  [31044] = {
    ["T"] = "为吉利吉姆之岛而战",
    ["O"] = "在吉利吉姆之岛取得3次胜利，然后回到暴风城港口的麦克斯韦尔·扎诺斯那里。（该任务每周可以完成一次。）",
    ["D"] = ""
  },
  [31045] = {
    ["T"] = "为吉利吉姆之岛而战",
    ["O"] = "在吉利吉姆之岛取得3次胜利，然后回到暴风城港口的麦克斯韦尔·扎诺斯那里。（该任务每周可以完成一次。）",
    ["D"] = ""
  },
  [26186] = {
    ["T"] = "远方零件",
    ["O"] = "把点心篮带给铁炉堡的米洛尔·怒斩，以换取攻城车零件。",
    ["D"] = "离铁炉堡这么远还要维护攻城车，真是要命。我们并不算正式隶属于联盟，所以我拿不到最新最好的零件。\n\n我可以去找外面那个外交官请求正式援助，可要是他答应了，我们就会被卷进一堆繁文缛节和废话里。我妻子想出了一个更简单的办法，可以让我们直接拿到货：食物！每个矮人都抵挡不了这一招。\n\n把这篮点心带给铁炉堡的米洛尔·怒斩，然后替我把换来的零件带回来。",
  },
  [26187] = {
    ["T"] = "远方零件",
    ["O"] = "把攻城车零件箱带回鹰巢山的首席工程师乌鲁尔那里。",
    ["D"] = "通常我不会让任何零件离开铁炉堡的防务库存，不过看在你带来的东西份上……好吧……这次就算了，不是吗？我已经等不及要大快朵颐了。把这些零件带回去给蛮锤部族，我们就算两清。\n\n下次告诉他们，再捎点麦酒来！",
  },
  [26311] = {
    ["T"] = "圣光之材",
    ["O"] = "把信和付款送到奥格瑞玛荣誉谷的铁砧阿图尔克那里。",
    ["D"] = "现在该打造一柄配得上圣骑士的战锤了。我知道奥格瑞玛有个好铁匠，他叫铁砧阿图尔克。把这封写有规格的信和付款带给他，他会给你一份需要替他收集的材料清单。你可以在荣誉谷的锻造训练师附近找到他。\n\n在我生前那个年代，我会向铁炉堡订制一件工艺品，但我有种感觉，如今他们也许不会接受这样的请求了。",
  },
  [26349] = {
    ["T"] = "坏消息",
    ["O"] = "把卡勒塔卡的加密便笺带给铁炉堡的资深探险家麦格拉斯。",
    ["D"] = "<穆林努力让自己平静下来时，你向他描述了你在泥地里看到的蹄印。>\n\n我希望自己能帮上你，可我现在没办法集中精神。不过在你离开前，我母亲留给我一件东西，要我交给你，$R。\n\n妈妈告诉我，如果她真的出了事，就把这张便笺交给你。我希望它能帮上你找她的忙。\n\n如果我说自己再也不想见到另一个$R了，请原谅我。",
  },
  [26352] = {
    ["T"] = "又一个坏消息",
    ["O"] = "带着唤地者的口信回到铁炉堡的史学家卡尼克那里。",
    ["D"] = "我知道你在寻找什么，也看见了你寻找它时表现出的勇气。请相信，我说这些并非轻率，因为我见过凡人为了追求知识愿意牺牲多少。\n\n我要警告你，你还没有准备好面对奥丹姆石板。你还没有准备好面对那些门后等待着的东西。就连泰坦也没有准备好面对他们发现的事物，这就是石板与圆盘被分开并散落四方的原因。\n\n如果你继续沿着这条线索追查下去，将会释放出难以言喻的厄运。现在走吧，$R。这个任务到此为止。我劝你另寻新的目标。",
  },
  [26353] = {
    ["T"] = "好消息",
    ["O"] = "前往藏宝海湾与赫德里格·铁石会面，讨论诺甘农圆盘。",
    ["D"] = "我有个大好消息，$N！博学者们已经成功破译了诺甘农圆盘上的部分符文。它们是用古代矮人语写成的。\n\n我们找到了一位愿意协助我们解读这些符文的矮人联系人，希望你去见见他。他同意从铁炉堡前往棘齿城与你会面。去那里的旅店见赫德里格·铁石，我们就离开启奥丹姆更近一步了！",
  },
  [26724] = {
    ["T"] = "黑魔法",
    ["O"] = "从东瘟疫之地的黑暗教徒和暗影法师那里收集3本黑魔法典籍，然后回到铁炉堡荒弃的洞穴里的寻尸者祖贝尔那里。",
    ["D"] = "诅咒教派训练法师掌握各种禁忌魔法和形形色色的黑暗技艺。虽然他们最擅长的是通灵术，但我们术士也能从他们的研究中学到一两样东西。 \n\n前往东瘟疫之地，杀死诅咒教派的黑暗教徒和暗影法师。你可以在他们的据点找到他们——剧毒林地和蘑菇谷。收集三本他们的法术书，好让我研究他们的技巧。",
  },
  [26857] = {
    ["T"] = "文件送往铁炉堡！",
    ["O"] = "把暮光联盟文件带给铁炉堡的梅瑞达·坚炉。",
    ["D"] = "既然我们拿到了这批文……<*嗝*>……文件，我想让你把它们带给铁炉堡的梅瑞达·坚炉。她正等着见国王，这东西能帮她说上话。",
  },
  [26858] = {
    ["T"] = "瑟银兄弟会",
    ["O"] = "与灼热峡谷瑟银哨塔的侦查队长洛洛尔谈一谈。",
    ["D"] = "$C！对，就是你！求你别像铁炉堡里那么多人一样无视我。\n\n我来自灼热峡谷的瑟银兄弟会驻地。虽然黑铁矮人与铜须矮人之间关系紧张，但暗炉城里已经有人开始和暮光之锤搅在一起。我必须警告国王麦格尼，$C，可我求见他的预约一直被往后推。\n\n瑟银哨塔现在就需要帮助！如果你是喜欢冒险的人，就去找侦查队长洛洛尔，向他提供你的服务。",
  },
  [26860] = {
    ["T"] = "煤渣挖掘场",
    ["O"] = "杀死4名黑铁地质学家，并从灼热峡谷的煤渣挖掘场找回一箱文物。",
    ["D"] = "黑铁矮人很少离开他们位于黑石山深处的暗炉城老家，可不知为什么，他们派了一支地质学家队伍前往西部边界外、灼热峡谷里的煤渣挖掘场。还把在那里作业的一支铁炉堡队伍赶跑了！\n\n我必须弄清这些矮人到底对什么东西产生了兴趣。去破坏他们的行动，把他们收集的一箱文物带回来。",
  },
  [27097] = {
    ["T"] = "给摇晃谷的消息",
    ["O"] = "在艾萨拉南部海岸门纳尔湖南面的峭壁上找到摇晃谷。",
    ["D"] = "注意，$R！你打算前往艾萨拉吗？如果是的话，我必须征召你去办一件事。\n\n我的哨站收到了一封来自铁炉堡的消息，收件人名叫温迪·摇匠。我不认识这个名字，但消息显示，一群侏儒可能在艾萨拉南部边缘的峭壁上某处建立了行动基地。你能带着这封消息，在门纳尔湖南边寻找收件人吗？我不能离开自己的岗位去送信。",
  },
  [27101] = {
    ["T"] = "黑曜钢",
    ["O"] = "把熔化的黑曜熔渣带回艾萨拉瓦罗莫克的格鲁尔·黑刃那里。",
    ["D"] = "既然格鲁尔想把这些东西熔掉，那我就照办。我的炉煤可不比铁炉堡的差。\n\n<克拉索克慢慢把盾牌熔成一团浓稠、油亮的液态熔渣。>\n\n它们熔得可不漂亮，这点肯定没错。要我是你，就会小心处理这东西。不过格鲁尔是最出色的铁匠之一。我倒想看看他能用这玩意儿做出什么。",
  },
  [27885] = {
    ["T"] = "生存意志",
    ["O"] = "从东瘟疫之地的食尸鬼和憎恶身上取得30份腐烂的器官，把它们带给铁炉堡侏儒区的莱达·晶爆。",
    ["D"] = "被遗忘者已经证明自己是我们最阴险的敌人，$C。他们狡诈、奸猾、不可信任，更不用说他们本身就是对自然秩序和圣光的亵渎。\n\n然而，他们在摆脱巫妖王控制时展现出了惊人的意志力。如果我们想在天灾军团的下一次进攻中幸存，尽可能了解被遗忘者是如何做到这一点的，对我们最有利。先去宰杀他们在东瘟疫之地的近亲，尤其是食尸鬼和憎恶。收集他们身上那些精细的部件，交给炼金师莱达·晶爆。你可以在铁炉堡的炼金实验室找到她。",
  },
  [27918] = {
    ["T"] = "血与荣耀的约束",
    ["O"] = "在铁炉堡找到档案管理员登吉姆。",
    ["D"] = "既然你已经更了解兽人的荣誉，就能在战斗中用这些原则指引自己。如果你想更彻底地拥抱它们，就去铁炉堡寻找档案管理员登吉姆。祝你好运，$C。",
  },
  [27931] = {
    ["T"] = "火酒的佳酿",
    ["O"] = "与铁炉堡平民区石火旅店的旅店老板洛雷·火酒谈一谈。",
    ["D"] = "$C，铁炉堡石火旅店的旅店老板洛雷·火酒想请你帮忙酿造一种非常特别的酒！\n\n他说这酒能让你胸口都长出毛来，还能让你更坚韧，就像普通矮人一样。\n\n如果你对此有兴趣，石火旅店就在铁炉堡的平民区。",
  },
  [27936] = {
    ["T"] = "随时有货",
    ["O"] = "与铁炉堡的档案管理员登吉姆谈一谈。",
    ["D"] = "真不敢相信我们的旅程已经到头了，$N……不过能跟你一起干活可真痛快！\n\n我会尽力继续酿这种酒，但你放心，以后想要多少都会有。需要补货的时候就去找铁炉堡的档案管理员登吉姆！\n\n现在说这个有点晚了，但还是恭喜你，$N——在我心里，你已经是个荣誉矮人了！随时欢迎你到我炉边来坐坐；可别成了陌生人。",
  },
  [27959] = {
    ["T"] = "需要修理吗？",
    ["O"] = "与铁炉堡的档案管理员登吉姆谈一谈。",
    ["D"] = "我想你已经准备好踏上下一场冒险了，$N。\n\n我喜欢把实验室设在这里；这里远离所有喧嚣！每次装备坏掉时，你大概也不想一路跑到这里来，所以如果你以后需要修理工具包，我会把它们寄到铁炉堡的档案管理员登吉姆那里。\n\n和你共事很愉快。如果你只是想回来看看，也随时欢迎！",
  },
  [28008] = {
    ["T"] = "火焰仪式",
    ["O"] = "与铁炉堡的埃姆鲁尔·鲁克努森谈话，汇报你的成功。",
    ["D"] = "我已经准备好了。美食评论家尽管来吧。我会保住我的米什伦星级，而伊莎贝尔可以继续默默无闻。\n\n你现在必须赶紧走。可不能让评论家以为你才是我成功的关键！把你派到我这里来的那位朋友埃姆鲁尔大概也想知道发生了什么。\n\n你可以告诉他，我认可你的表现。",
  },
  [28441] = {
    ["T"] = "给提昂工头的委托",
    ["O"] = "卫兵拜伦要你使用工程学技能制作5个发条式同步协调陀螺仪，并把订单带给尘泥沼泽塞拉摩岛的提昂工头。",
    ["D"] = "嘿——你，就是你！我想我以前在铁炉堡的工程学训练师那里见过你，那时候我还驻守在东部王国。你是工程师，对吧？\n\n提昂工头正想让我们的伐木场运转起来，可他在调整传送带同步上遇到了点麻烦。他说需要几枚发条式同步协调陀螺仪才能让它正常运作。这事你能帮忙吗？",
  },
  [31007] = {
    ["T"] = "觐见国王",
    ["O"] = "与铁炉堡的麦格尼·铜须谈谈冬泉谷传来的令人不安的报告。",
    ["D"] = "",
  },
  [31032] = {
    ["T"] = "奥术疫病",
    ["O"] = "返回铁炉堡，向国王麦格尼·铜须报告你的成功。",
    ["D"] = "再次感谢你，冒险者。你今天为艾泽拉斯立下了伟大的功绩。 \n\n毫无疑问，你的领袖会想听听你的英雄事迹。"
  },
  [26768] = {
    ["T"] = "应得的甜点",
    ["O"] = "把萨拉·坦普沃斯制作特别点心所需的材料带给她。",
    ["D"] = "我们光荣的主人邀请了特别的客人共进晚餐，而我被分派去负责烹调这顿饭。我花了好几个星期搜罗最好的食材，研究最好的食谱，只为给他们一顿难忘的晚餐。\n\n到了那个特别的日子，我在厨房里忙了好几个小时，把每一种香料和酱汁都调配到完美。只有在我确信这顿饭会在他们舌尖上起舞之后，我才允许它上桌。\n\n一开始一切都很顺利。客人们闻到开胃菜的香气，已经馋得直流口水。等所有人都分到食物后，我们的主人邀请他们全都“开动”。\n\n就在那时，我受到了这辈子最大的侮辱。他连菜都没尝一口，就打了个响指，变出一个松饼来吃！他还开玩笑说自己对糕点上瘾了，连我盛宴中的一口都没碰。接着客人们也都想要他吃的东西！整顿饭全浪费了！\n\n我受够了他的忘恩负义，而且我已经有了复仇计划。我只缺几样材料。\n\n给我带些金杰照料的花园里长出的法力浆果，再从闪金镇的萨瑞恩·博丁那里买些面粉、甜香料和盐。",
  },
  [26784] = {
    ["T"] = "山烈麦酒",
    ["O"] = "收集6根北郡芦苇和半打微光瀑布之水，让德罗穆尔·怪饮酿造一批新的山烈麦酒。",
    ["D"] = "你是说穆伦担心我？担心我？哈！我还真没想到有生之年能看到那个倔驴改口。\n\n几天前，我划船去了他的营地，给他留下了我的道歉礼物。那是我新发明的一种酒，上面还印着他的家族徽记。我管它叫山烈麦酒。\n\n如果你找到了它，那它一定是在他看见之前就被冲到下游去了。<德罗穆尔沉思起来。>\n\n是时候别再磨磨蹭蹭了！去给我弄些这些河边元素身上的魔法水，再带一把附近生长的芦苇回来，我就能重新酿一批。",
  },
  [27587] = {
    ["T"] = "给卫兵托马斯的委托",
    ["O"] = "炼金师玛洛瑞要你使用炼金术技能制作5瓶初级防御药剂，并把订单交给艾尔文森林东谷伐木场的卫兵托马斯。",
    ["D"] = "我还有另一份委托可以请你帮忙——非常简单，只需要最基础的技艺。\n\n沿路往东走，你会在东谷伐木场附近找到一些驻守的卫兵。其中一位卫兵托马斯报告说，有卫兵在林子里失踪了，他想要些炼金制品帮忙。我虽然没法阻止他们迷路，但几瓶初级防御药剂也许能让他们多几分胜算。你愿意接下这份委托吗？",
  },
  [27636] = {
    ["T"] = "给治安官哈迦德的委托",
    ["O"] = "铁匠阿古斯要你使用锻造技能制作1条铜质符文短裤和1副铜质符文护手，并把订单交给艾尔文森林东谷伐木场的治安官哈迦德。",
    ["D"] = "向你致意，$C。我认得出一双同为铁匠的手。你想不想亲自接下我的一份委托？\n\n东谷伐木场那边的治安官哈迦德订了一条铜质符文短裤和一副铜质符文护手。如果你有兴趣，只要亲手把这些东西做出来，然后送过去就行。\n\n伐木场就在闪金镇以东。",
  },
  [27637] = {
    ["T"] = "给瑞尼尔副队长的委托",
    ["O"] = "铁匠阿古斯要你使用锻造技能制作2把铜质战斧，并把订单交给艾尔文森林西泉要塞的瑞尼尔副队长。",
    ["D"] = "你好，$C。我还需要些帮手，好把更多委托完成交出去。瑞尼尔副队长为他的部队征用了几把铜质战斧。\n\n如果你有兴趣完成这份委托，可以把斧头送到西边西泉要塞的副队长那里。",
  },
  [28063] = {
    ["T"] = "给厨师托马斯的委托",
    ["O"] = "厨师托马斯要你使用烹饪技能制作10条美味小鱼，并把订单交给艾尔文森林闪金镇的厨师托马斯。",
    ["D"] = "呼！今天真是忙坏了，我在炉边待了这么久，自己连一口东西都没吃。\n\n也许你能帮个忙？你自己也挺会使煎锅，我很想要一大盘煎好的美味小鱼。如果你能办到，我就拿一些我特制的生鲜烹饪材料跟你交换。成交吗？",
  },
  [28087] = {
    ["T"] = "给基塔·费温德的委托",
    ["O"] = "基塔·费温德要你使用附魔技能制作1根符文铜棒，并把订单交给艾尔文森林阿祖拉之塔的基塔·费温德。",
    ["D"] = "嗯，一个新手附魔师？让我看看你进步到什么程度了。给我制作一根符文铜棒，带来让我检查。如果你做得好，我想等你的技艺更成熟时，我们还会再见。",
  },
  [28424] = {
    ["T"] = "给管理员莱琳的委托",
    ["O"] = "管理员莱琳要你使用工程学技能制作24把螺栓，并把订单交给艾尔文森林东谷伐木场的管理员莱琳。",
    ["D"] = "小心点，$N——你耳朵后面漏了一点油污！这说明你是个工程师，我正好有件事可以请你帮忙。\n\n要让锯木厂持续运转，每个小时都得操心。感觉只要看它一眼不顺，它就会坏掉。我需要两打螺栓来让锯片继续转动。你觉得能帮上忙吗？",
  },
  [28494] = {
    ["T"] = "给贾森·玛瑟斯的委托",
    ["O"] = "贾森·玛瑟斯要你使用钓鱼技能收集20条新鲜的美味小鱼，并把订单交给艾尔文森林水晶湖的贾森·玛瑟斯。",
    ["D"] = "我的小鱼全卖光了。今天早上最后一批卖给了一个看起来都准备为它打架的厨子。\n\n如果你有鱼竿，手也够稳，我就需要一批新鲜货。给我带来20条新鲜的美味小鱼。附近的人都指望我备足货，我可不想开始把他们拒之门外。",
  },
  [28517] = {
    ["T"] = "给萨拉·坦普沃斯的委托",
    ["O"] = "草药师博米洛伊要你使用草药学技能采集20朵宁神花，并把订单交给艾尔文森林阿祖拉之塔的萨拉·坦普沃斯。",
    ["D"] = "见习草药师，是吧？想证明你有成功的本事吗？我们先从基础开始。采集20朵宁神花，把它们带给阿祖拉之塔的萨拉·坦普沃斯。她要用它们给塔里的法师们做点东西，而且你要是偷懒，她一定看得出来。",
  },
  [28558] = {
    ["T"] = "给拉里克·费恩的委托",
    ["O"] = "艾德勒·费欧德要你使用制皮技能制作1个轻皮箭袋，并把订单交给艾尔文森林东谷伐木场的拉里克·费恩。",
    ["D"] = "有志成为制皮师？介意帮我处理几份订单吗？\n\n东谷那边的拉里克·费恩订了一个新箭袋。他说旧的快散架了，箭都从缝里戳出来。那可是危险事。\n\n这对初学者来说是个很合适的活。制作一个轻皮箭袋，把它送到伐木场交给他。就当是练习，也是服务大家。",
  },
  [28559] = {
    ["T"] = "给托米·乔·斯通菲尔德的委托",
    ["O"] = "艾德勒·费欧德要你使用制皮技能制作2条手工皮短裤，并把订单交给艾尔文森林斯通菲尔德农场的托米·乔·斯通菲尔德。",
    ["D"] = "如果你愿意，这里还有一份：托米·乔最近一直为某个神秘姑娘神魂颠倒，现在又想要点东西让自己看起来“体面些”。\n\n如果你的制皮技艺正在进步，这正好是制作几条手工皮短裤的好理由。把它们带给斯通菲尔德农场的他吧。也许打扮得像回事，能帮他采取行动。",
  },
  [28633] = {
    ["T"] = "给军需官哈德森的委托",
    ["O"] = "铁匠阿古斯要你使用采矿技能采集20块铜矿石，并把订单交给艾尔文森林西泉要塞的军需官哈德森。",
    ["D"] = "你是矿工？我正需要你的帮助。\n\n西泉要塞那边的军需官哈德森征用了一批铜矿石，可我现在一点也匀不出来。也许你可以发挥自己的本事，替闪金镇完成这份订单？",
  },
  [28673] = {
    ["T"] = "给瑞尼尔副队长的委托",
    ["O"] = "萨拉·迪博雷恩要你使用裁缝技能制作2件蓝色亚麻衬衣，并把订单交给艾尔文森林西泉要塞的瑞尼尔副队长。",
    ["D"] = "瑞尼尔副队长一直穿着一件看起来更像破布的衬衣在西泉要塞巡逻，都是上周那次豺狼人伏击害的。他拒绝停下来修补——还说这能磨练性格。\n\n如果你有这门手艺，能做几件蓝色亚麻衬衣带给他吗？他也许不会承认，但我知道他会感激这份心意。只是别让他说服你替他裁完整个衣柜。",
  },
  [28674] = {
    ["T"] = "给梅贝尔·马科伦的委托",
    ["O"] = "萨拉·迪博雷恩要你使用裁缝技能制作1条简易的裙子，并把订单交给艾尔文森林马科伦农场的梅贝尔·马科伦。",
    ["D"] = "梅贝尔·马科伦这整整一周都在坐立不安，到处问缝线和染料的事。她终于承认自己想要一条新裙子——甜美又简单的那种。\n\n如果你能给她缝一条简易的裙子，能把它带到马科伦农场交给她吗？她没说为什么，不过有传言说她终于有了心上人！",
  },
  [27039] = {
    ["T"] = "实践科学",
    ["O"] = "找到碎木岗哨南边、多丹尼尔兽穴附近的药剂师营地。",
    ["D"] = "有人要我转告路过的冒险者，如果想找有报酬的活，就去拜访那些药剂师。如果你不介意目标可疑又臭烘烘的尸体，也许会有兴趣。\n\n药剂师营地在碎木岗哨南边，靠近多丹尼尔兽穴。",
  },
  [27040] = {
    ["T"] = "实践科学",
    ["O"] = "对灰谷先驱者使用5次邪恶混合剂，然后回到药剂师维克托那里。",
    ["D"] = "你，站住！你有兴趣赚钱吗？喜欢帮助部落吗？\n\n正好，我在这里的工作需要一名研究助手。任务其实很简单。你拿上我这些美妙的混合剂，丢到这片区域周围游荡的那些先驱者身上。\n我提到的这种混合剂，是反暗夜精灵技术中最新也最棒的成果，它能帮助我们的战歌盟友守住这里。\n\n完成之后，请把结果报告给我。",
  },
  [27041] = {
    ["T"] = "实践科学",
    ["O"] = "对银翼伏击者使用5次邪恶混合剂，然后回到药剂师维克托那里。",
    ["D"] = "你，站住！你有兴趣赚钱吗？喜欢帮助部落吗？\n\n等等，不对，我们已经说过这个了。抱歉，$n。不过这份工作和上次很像，只是这次我要看看它用在南边那些伏击者身上的效果。他们是战歌氏族的眼中钉，所以把这些敌方士兵从局面中剔除，也算是帮他们一个忙。\n\n把混合剂大量涂到那些精灵身上，然后看看会发生什么！",
  },
  [27042] = {
    ["T"] = "改良迅捷药水",
    ["O"] = "把改良迅捷药水交给5名部落斥候，然后回到药剂师莉迪娅那里。",
    ["D"] = "你可真是个不错的研究助手，$n。我叫莉迪娅，隶属于皇家药剂师协会。我正在做一个独立于维克托的项目，也许你愿意协助我。\n\n南边有不少战歌斥候，他们一直警戒着暗夜精灵伏击者。虽然他们在战斗中足以自保，但我们必须尽可能给他们每一点优势。\n\n我一直在研究一种特殊的迅捷药水变体。它应该能赋予他们更出色的反应和整体敏捷，足以击败任何来袭的伏击者。你愿意替我把一些药水分发给战歌斥候吗？我很乐意为你的工作付酬。",
  },
  [27043] = {
    ["T"] = "道德困境",
    ["O"] = "向工头巴兰报告药剂师维克托和莉迪娅的活动。",
    ["D"] = "你叫$n，对吧？我听到莉迪娅跟你谈她项目时说的一些话。我觉得她的解释很奇怪，毕竟我们都在做同一个项目，而且根本不存在什么她让你交给斥候的“改良迅捷药水”。\n\n我直说吧。她骗了你。她交给你的，和你用在那些暗夜精灵身上的混合剂是同一种东西。莉迪娅一直急于扩大我们项目的试验对象范围，但在你来之前，她只有暗夜精灵可以实验。\n\n必须有人阻止莉迪娅和维克托。只要皇家药剂师协会能看到成果，他们似乎根本不在乎自己在谁身上做实验。我无力对付他们，但如果你去找工头巴兰……也许她会有办法解决这个问题，同时安抚皇家药剂师协会和战歌氏族。",
  },
  [27045] = {
    ["T"] = "大地震响",
    ["O"] = "询问碎木矿洞里的苦工。",
    ["D"] = "通常来说，这座矿洞的产出对部落的战争努力至关重要。最近那些该死的苦工一直在偷懒；有些甚至丢下工具，胡言乱语地跑了出去！\n\n你能去问问他们，艾泽拉斯到底出了什么事吗？",
  },
  [27046] = {
    ["T"] = "大地震响",
    ["O"] = "找出并消灭在碎木矿洞里吓坏苦工的怪物。",
    ["D"] = "所以他们说矿洞深处有个怪物？我怀疑这是不是也是我们最近一直感到震动的原因。\n\n我得让这项作业重新顺利运转起来。你能再深入矿洞，把它处理掉吗？",
  },
  [27047] = {
    ["T"] = "大地震响",
    ["O"] = "从水岸边收集6根结实的芦苇，并从腐烂的泥浆怪身上收集4块碎玻璃。",
    ["D"] = "现在你肯定引起我的注意了。这些震动仍在继续，苦工们也没变得更能干。我们得试着找出这些骚动的真正源头。\n\n我有个主意，但需要你替我弄几样东西。在灰谷各处的水域边，你能找到结实的芦苇，我可以把它们掏空，做成临时瞄准镜。\n\n我还需要玻璃来做镜片。不过玻璃可不是什么自然形成的东西……嗯……我知道了！附近的腐烂泥浆怪会吞下旅人掉在地上的任何东西。我敢说它们肯定吸收过一些玻璃器皿。",
  },
  [27048] = {
    ["T"] = "大地震响",
    ["O"] = "在碎木矿洞外测试震测仪MK I。",
    ["D"] = "有了你给我的东西，我就能造出我的最新发明：震测仪MK I！把它带到矿洞外试试看。我确信它会给我们指明正确方向。",
  },
  [27050] = {
    ["T"] = "大地震响",
    ["O"] = "回到碎木矿洞的工头弹簧栓那里。",
    ["D"] = "<伊兹朝袋子里瞥了一眼。>\n\n这个地精很合我的胃口。\n\n给你，这里就是工头想要的一切。我承认，你勾起了我的好奇心。你以后可得回到这里，告诉我结果如何。到底是什么东西能让他终于来找我帮忙，肯定是不得了的发现。\n\n带上这个箱子，回碎木岗哨把它交给他。",
  },
  [27051] = {
    ["T"] = "大地震响",
    ["O"] = "使用震测仪MK II，找出灰谷震动的源头。",
    ["D"] = "这就是震测仪MK II。漂亮吧？把它放在地上，它就会指向灰谷震动的源头。\n\n我能帮的就这么多了。请追踪源头并阻止它，看在那些该死苦工理智的份上。",
  },
  [27052] = {
    ["T"] = "大地震响",
    ["O"] = "把震测仪MK II带给烈日石居的迪茨·弹簧栓。",
    ["D"] = "我妹妹迪茨驻扎在烈日石居。她也许能帮你推进下一步。把震测仪带去给她，好让她给它加上自己的巧思。不管是什么造成了这些震动，它既强大，又深藏在艾泽拉斯之内。\n\n要去找迪茨，你可以走碎木岗哨西南方的石爪小径。如果你更熟悉贫瘠之地的地形，也可以从那片满是尘土的鬼地方西侧，沿着通往荣耀岗哨的道路前往烈日石居。",
  },
  [27053] = {
    ["T"] = "索兰萨尔报告",
    ["O"] = "把报告带给阿斯特兰纳的某个人。",
    ["D"] = "<这份报告详细记录了纳迦对一处名为索兰萨尔的废墟产生了兴趣。细节本身很含糊，也没有说明纳迦的数量或进攻计划。这些情报也许对阿斯特兰纳的某个人有用。>",
  },
  [27054] = {
    ["T"] = "古树之心",
    ["O"] = "在阿斯特兰纳找个能告诉你这颗心脏来历的人。",
    ["D"] = "你拾起古树之心，感觉到其中散发出奇异的搏动。也许阿斯特兰纳有人能告诉你更多。",
  },
  [27055] = {
    ["T"] = "古树之心",
    ["O"] = "在碎木岗哨找个能告诉你这颗心脏来历的人。",
    ["D"] = "你拾起古树之心，感觉到其中散发出奇异的搏动。也许碎木岗哨有人能告诉你更多。",
  },
  [27057] = {
    ["T"] = "以太中的波动",
    ["O"] = "在灰谷碎木岗哨找到希莉丝。",
    ["D"] = "我听说你最近在鬼雾峰顶摧毁了恶魔之种。这个行动值得称赞，也证明你能够对抗火刃氏族的爪牙。\n\n然而，种子的毁灭在阴影笼罩的以太中响起了一道信标，而术士和恶魔对这种信号格外敏感。新的危险已经到来。\n\n尼尔鲁·火刃提到，火刃氏族曾在贫瘠之地和灰谷活动。你已经袭击了他们在贫瘠之地的据点，所以我相信这个危险会出现在灰谷。前往灰谷的碎木岗哨，和我的代理人希莉丝谈谈。她会协助你寻找这份危险。",
  },
  [27058] = {
    ["T"] = "以太中的波动",
    ["O"] = "在石爪山脉搜寻火刃氏族。如果找到他们，就取回4个火刃项圈，交给灰谷碎木岗哨的希莉丝。",
    ["D"] = "萨尔提醒我你会来。我不愿再让你踏上一段旅程，但如果没有他们魔法的样本，我无法在灰谷找到火刃氏族，而我在这里也没有任何线索。\n\n我听到传闻，说火刃氏族也许在石爪山脉的恐怖图腾牛头人那里找到了避风港。鬼雾峰不再安全之后，我猜他们已经转移到那里。\n\n在石爪山寻找任何恐怖图腾的踪迹，弄清他们是否真的与火刃氏族结盟。看看能不能带回一点他们的魔法——也许就是他们使用的那些魔法项圈。",
  },
  [27059] = {
    ["T"] = "以太中的波动",
    ["O"] = "在雷霆崖长者高地与玛加萨·野性图腾对质。",
    ["D"] = "为了在灰谷找到火刃氏族，我必须研究这个项圈。那需要一些时间。\n\n在我研究期间，我要你以大酋长代表的身份，去和恐怖图腾氏族的领袖谈谈。\n\n玛加萨·野性图腾住在雷霆崖的长者高地。燃烧军团是部落可怕的敌人，她的氏族与他们合作是不可容忍的。这必须立刻停止。\n\n让她明白大酋长在此事上的意志。",
  },
  [27061] = {
    ["T"] = "以太中的波动",
    ["O"] = "回到灰谷碎木岗哨的希莉丝那里。",
    ["D"] = "我知道你真正寻找的是什么，$C。所有与暗影调谐的生物都感受到了恶魔之种被摧毁时扩散出的能量波。其中一部分能量仍在你周围回荡。\n\n灰谷某处正在生长另一枚种子。它与我氏族的目标无关，所以我没有更多细节。但我把这个情报告诉你，是为了向大酋长表示善意……现在你可以暂时跑回你的主人那里去了。我期待你稍后回来接受我的任务。",
  },
  [27062] = {
    ["T"] = "以太中的波动",
    ["O"] = "回到奥格瑞玛的萨尔那里。",
    ["D"] = "你离开期间，我设法解开了你带来的项圈中的一些秘密。不幸的是，我认为我们在灰谷面对的东西太强大了，没有更多情报就无法挑战。\n\n请把这份报告带给萨尔。我猜你会有些空闲时间，可以在他决定下一步之前去处理玛加萨的差事。",
  },
  [27063] = {
    ["T"] = "新的恶魔之种",
    ["O"] = "与灰谷碎木岗哨的希莉丝谈一谈。",
    ["D"] = "$N，是时候再次拿起武器对抗火刃氏族了。希莉丝有一个计划，可以熄灭这枚新的恶魔之种，而且不会像上次那样引发以太扰动。\n\n立刻去碎木岗哨向她报到。",
  },
  [27064] = {
    ["T"] = "新的恶魔之种",
    ["O"] = "穿过萨提纳尔前往灰谷的萨维亚，杀死尼佐里斯。取回妖牙匣，并把它带给碎木岗哨的希莉丝。",
    ["D"] = "我们不能像你在贫瘠之地那样直接摧毁这枚新的恶魔之种。我们必须把它锁在某个无法继续生长的地方。幸运的是，这样的地方近在眼前。\n\n一群萨特在东边扎下了营地。在萨维亚的上层，你会找到尼佐里斯，一个稀有神器收藏家。他手中有一件名为妖牙匣的东西。这个魔法箱专门用来容纳强大的暗影物品。杀死尼佐里斯，把那个匣子带给我。我们可以用它封存恶魔之种。",
  },
  [27065] = {
    ["T"] = "新的恶魔之种",
    ["O"] = "潜入屠魔峡谷，使用妖牙匣封存新的恶魔之种。",
    ["D"] = "现在到了我们任务中最危险的部分，$N。\n\n我要你前往战歌伐木营地和冥火岭以南的屠魔峡谷。那里正是格罗姆·地狱咆哮击败玛诺洛斯的地方。火刃氏族正在利用玛诺洛斯残留的血液，在那里培育新的恶魔之种。\n\n找到种子，把它放进匣子里。然后把匣子带回给我。\n\n遗憾的是，我不能陪你去。恶魔会察觉到我的存在，而你将遭遇更猛烈的抵抗。",
  },
  [27067] = {
    ["T"] = "葬影之行",
    ["O"] = "在凄凉之地的葬影村找到皮普乔特和扎卡拉。",
    ["D"] = "希莉丝已经排除了灰谷是恶魔之种毁灭所召唤出的强大恶魔所在地的可能。我的另一名代理人前往凄凉之地，并报告说火刃氏族在那一带也有活动。\n\n前往西南海岸的葬影村，找到扎卡拉和她的小鬼皮普乔特。\n\n扎卡拉是一名能干的术士，但她无法说话。她的小鬼会负责交谈。",
  },
  [26124] = {
    ["T"] = "美丽水域",
    ["O"] = "在灰谷收集10条飞尾镖鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "灰谷苍翠的美景是一处宁静的避风港，最适合想从世界混乱中寻求慰藉的人。在这片宁静之中，藏着大量正等着上钩的鱼儿。灰谷的河流和湖泊生机盎然，是时候抛下鱼线，分享自然的馈赠了。\n\n我说的是暗夜精灵眼中的珍品，飞尾月镖鱼——奥苏哈的最爱！我跟你说，在满月最盛的时候，看着一群月镖鱼从你垂钓的位置下方掠过水中，可没有什么比得上那景象。要是你能替我们钓一些上来，我会很感激的！",
  },
  [26363] = {
    ["T"] = "小规模冲突：灰谷",
    ["O"] = "在灰谷找到并杀死5名部落成员。",
    ["D"] = "灰谷属于联盟，我们必须不断证明这一点。猎杀部落成员，代表军队消灭他们，证明你的价值并提升军阶。",
  },
  [26364] = {
    ["T"] = "小规模冲突：灰谷",
    ["O"] = "在灰谷找到并杀死5名联盟成员。",
    ["D"] = "灰谷属于部落，我们必须不断证明这一点。猎杀联盟成员，代表军队消灭他们，证明你的价值并提升军阶。",
  },
  [26469] = {
    ["T"] = "未能寻回者",
    ["O"] = "与奥格瑞玛格罗玛什堡垒里的纳兹格雷尔谈一谈。",
    ["D"] = "狮心公爵曾是人类远征灰谷队伍的一员。当时，联盟和部落正共同对抗天灾军团和燃烧军团。暗夜精灵袭击了外来者，杀死了远征队中的许多人——公爵也在其中。\n\n我原本打算去寻找羽月将军，她是杀死他的人之一。如今这对我们任何一方来说似乎都不可能了。作为替代，当年有几个兽人曾在灰谷与远征队共事。我知道纳兹格雷尔就是其中之一，因为他参加了海加尔山之战。我不知道他有多难找，但如果你能找到他，就问问他是否知道关于狮心公爵的事。",
  },
  [26470] = {
    ["T"] = "未能寻回者",
    ["O"] = "把狮心公爵的披风带给艾萨拉的帕特里克·米尔斯，看看他能从中得知什么。",
    ["D"] = "部落信任联盟，在我们进军灰谷时与人类并肩而立，但我一直观察着这位狮心公爵，寻找任何背叛的迹象。他死后，天灾军团和燃烧军团立刻扑向了基地里的其他人。\n\n我曾试图在天灾军团夺走那个人类的尸体前抢回它，可等我赶到他倒下的地方时，尸体已经不见了。剩下的只有他的披风。我拿走了它，打算有朝一日如果人类证明值得信任，就把它归还给他们。现在，我把它交给你。拿着它，然后离开。",
  },
  [26490] = {
    ["T"] = "水之召唤",
    ["O"] = "在石爪山脉的峭壁湖装满空的红色水囊。",
    ["D"] = "在卡利姆多石爪山脉深处，有一座被污染的湖泊，当地人称之为峭壁湖。风险投资公司在这一地区造成了难以估量的破坏。我曾试图纠正这一切，却徒劳无功。\n\n沿着南部山脉深入灰谷，直到抵达石爪小径。从那里你就会进入石爪山。给我带回峭壁湖中泉眼裂隙的样本，我们就离你的灵契又近了一步。",
  },
  [27188] = {
    ["T"] = "战歌峡谷的补给",
    ["O"] = "赢得一场战歌峡谷比赛，以取得战歌补给箱。",
    ["D"] = "烟林牧场的生意遍布整个艾泽拉斯，包括一些最危险的地方。我们甚至和某些战场阵营达成了协议，只要我们为他们的行动贡献战斗人员，就能收到补给箱。\n\n我需要灰谷来的补给。从战歌峡谷凯旋而归，你就能领取一个战歌补给箱，里面装有节日装饰用的油和纳迦鳞片。你愿意加入战斗吗？",
  },
  [27238] = {
    ["T"] = "小鬼的差使",
    ["O"] = "前往凄凉之地西北部的萨格隆，再次寻找尼佐里斯。取回恶魔六分仪，并把它带给葬影村的皮普乔特。",
    ["D"] = "我不知道这算不算当恶魔的好处，但我们的契约里有一条小条款：当我们被召唤到并非自己起源的世界时，通常并不会真正死去。\n\n我是说，我们会死，但也会回来。有时候要很久，有时候几乎不用等。\n\n好吧，希莉丝当初让你在灰谷杀掉的那个恶魔——尼佐里斯——他就属于回来得很快的那种。他现在就在这里，在一个叫萨格隆的萨特集会地里，这次他还带着一件名叫恶魔六分仪的遗物。通常它会被用来做……别的事……但我们可以用它找到你的恶魔之种恶魔。所以出去，把那个六分仪拿回来。\n\n不然就像我们派去的前两个家伙一样，被烧成一堆灰。",
  },
  [27412] = {
    ["T"] = "进攻污林",
    ["O"] = "收集15枚污林护符，然后回到阿斯特兰纳的哨兵塞恩希尔那里。",
    ["D"] = "如果你仔细听，就能听见污林部族紧绷的哭嚎。这些该死的熊怪祸害着这片土地，恐吓村庄，猎杀平民。是时候把战斗带到他们面前了，我们要狠狠出击！\n\n他们把营地建在东边道路以南，就在你抵达林中树居前不远。我们绝不能手下留情，$N。杀光他们，并把他们用来标记部族身份的护符带给我，作为他们灭亡的证明。祝你好运，阿斯特兰纳正指望着你。",
  },
  [27564] = {
    ["T"] = "援助德莱文",
    ["O"] = "与永望镇东北、隐秘小林以南营地里的德莱文·霜凝谈一谈。",
    ["D"] = "你干得漂亮，孩子。让那个毛胡子重新害怕起来了！想不想再干一票？\n\n我在冬泉谷有个朋友——人不错，很会跟动物打交道，在费伍德、灰谷那边帮过我好多忙……总之，他叫德莱文，正打算对北边的枭兽做点什么。\n\n<罗克希摊开双手。>\n\n别问我是什么！他说话的时候我从来听不懂。他让我留意像你这样的人，把他们送到他那边。他提到了危险，听起来正合你的胃口。",
  },
  [27880] = {
    ["T"] = "为战歌峡谷而战",
    ["O"] = "在战歌峡谷取得3次胜利，然后回到灰谷银翼树林的哨兵艾蒂亚·轻歌那里。（该任务每周可以完成一次。）",
    ["D"] = "由于兽人正在破坏森林，银翼哨兵正与战歌侦查骑兵交战。不过，保卫这片特殊森林的理由，并不只是对自然的单纯热爱。\n\n这片森林形成了一道战略屏障，使灰谷能够抵御大规模进攻。没有它，阿斯特兰纳用不了一两天就会被并入贫瘠之地。\n\n尽你的一份力，去对抗战歌侦查骑兵吧，$N！为了联盟！",
  },
  [27881] = {
    ["T"] = "为战歌峡谷而战",
    ["O"] = "在战歌峡谷取得3次胜利，然后回到灰谷银翼树林的哨兵艾蒂亚·轻歌那里。（该任务每周可以完成一次。）",
    ["D"] = "由于兽人正在破坏森林，银翼哨兵正与战歌侦查骑兵交战。不过，保卫这片特殊森林的理由，并不只是对自然的单纯热爱。\n\n这片森林形成了一道战略屏障，使灰谷能够抵御大规模进攻。没有它，阿斯特兰纳用不了一两天就会被并入贫瘠之地。\n\n尽你的一份力，去对抗战歌侦查骑兵吧，$N！为了联盟！",
  },
  [27882] = {
    ["T"] = "战歌峡谷之战",
    ["O"] = "在战歌峡谷取得3次胜利，然后回到贫瘠之地摩尔沙农场的沙塔尔·碎颅那里。（该任务每周可以完成一次）",
    ["D"] = "对抗银翼哨兵的战歌峡谷之战意义重大。联盟打着保护一片并不属于他们的森林的幌子，企图剥夺部落最大的木材来源之一。\n\n绝不能让这种事发生，$N！为部落效力，带着荣耀战斗！",
  },
  [27883] = {
    ["T"] = "战歌峡谷之战",
    ["O"] = "在战歌峡谷取得3次胜利，然后回到贫瘠之地摩尔沙农场的沙塔尔·碎颅那里。（该任务每周可以完成一次）",
    ["D"] = "对抗银翼哨兵的战歌峡谷之战意义重大。联盟打着保护一片并不属于他们的森林的幌子，企图剥夺部落最大的木材来源之一。\n\n绝不能让这种事发生，$N！为部落效力，带着荣耀战斗！",
  },
  [27911] = {
    ["T"] = "血与荣耀的约束",
    ["O"] = "深入灰谷的多丹尼尔兽穴，在下层一座桥对面的某个壁龛中使用仪式熏香，向你的祖先致敬。",
    ["D"] = "你想更多地了解我的人民？我想我和任何人一样适合当老师，而且比大多数人更愿意。毕竟，我哪儿也去不了。\n\n如果你真的想理解我的人民，就必须先明白，荣誉是你的言语、事迹和行动的根基。我们的氏族由悠久的荣耀事迹所维系。我们明白，自己的行动所反映的不只是自己。\n\n向我展示你如何尊重他人。在你祖先的安息之地使用这份仪式熏香，然后回到我这里。",
  },
  [28367] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "在燃烧平原搜寻密探梅里根和格鲁玛尔下士。",
    ["D"] = "拒绝加入新部落的黑石兽人与黑暗势力结盟。联盟找到我们，希望我们潜入他们位于黑石山的力量堡垒，而我们同意了。然而，我们派去执行这项任务的特工还没有回报。\n\n我需要一位医术高明的人前往燃烧平原，查明他们出了什么事。你要寻找的是格鲁玛尔下士，一个战歌氏族的步兵，或是伪装成人类的密探梅里根。如果他们已经死了，立刻回来报告。如果没有，就看看你能做些什么，帮助他们完成任务。",
  },
  [28374] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "在燃烧平原搜寻密探梅里根和格鲁玛尔下士。",
    ["D"] = "拒绝加入新部落的黑石兽人与黑暗势力结盟。联盟找到我们，希望我们潜入他们位于黑石山的力量堡垒，而我们同意了。然而，我们派去执行这项任务的特工还没有回报。\n\n我需要一位医术高明的人前往燃烧平原，查明他们出了什么事。你要寻找的是格鲁玛尔下士，一个战歌氏族的步兵，或是伪装成人类的密探梅里根。如果他们已经死了，立刻回来报告。如果没有，就看看你能做些什么，帮助他们完成任务。",
  },
  [27600] = {
    ["T"] = "给哨兵艾蒂亚·轻歌的委托",
    ["O"] = "凯兰娜要你使用炼金术技能制作5瓶强力巨魔之血药水，并把订单交给灰谷银翼树林的哨兵艾蒂亚·轻歌。",
    ["D"] = "很高兴在这里见到一位炼金师同道。银翼哨兵的订单我已经积压了不少，正需要多一双手帮忙。\n\n你能制作五瓶强力巨魔之血药水，并把它们送到银翼树林的哨兵艾蒂亚·轻歌那里吗？我们必须确保哨兵们在战歌峡谷的战争中补给充足。",
  },
  [27623] = {
    ["T"] = "给洛克·奥卡尔的委托",
    ["O"] = "希莉丝要你使用炼金术技能制作5瓶治疗药水，并把订单交给灰谷碎木岗哨的洛克·奥卡尔。",
    ["D"] = "$C，听说你也是一名炼金师。大酋长派我来这里整顿这处岗哨，而情况比我预想的更糟。我们每天都有更多步兵死在联盟手里，所以我想委托你制作一些治疗药水，分发给士兵。你能办到吗？",
  },
  [27650] = {
    ["T"] = "给尤萨恩的委托",
    ["O"] = "塞安德尔要你使用锻造技能制作2把迅捷青铜匕首，并把订单交给灰谷中部银风避难所的尤萨恩。",
    ["D"] = "啊，一位铁匠！也许你能帮我——银风避难所的尤萨恩一直缠着我问有没有新刀。他显然想要一把适合切刃豹肉排的刀。我做的东西都不合他意，但我听说熟练的铁匠能打造迅捷青铜匕首，正适合尤萨恩的用途。如果你能做一对送过去，也许他终于会放过我！",
  },
  [27670] = {
    ["T"] = "给卡纳尔·菲斯的委托",
    ["O"] = "特劳弗要你使用锻造技能制作1条暗影宝石坠饰和1条调谐铜质护腿，并把订单交给贫瘠之地格罗多姆农场的卡纳尔·菲斯。",
    ["D"] = "十字路口和更远的地方，有的是适合你这样有进取心的年轻铁匠的活。我这里有一份卡纳尔·菲斯的未完成订单，他是个隐士，住在北边道路旁，离灰谷边界不远。如果你能制作一条暗影宝石坠饰和一条调谐铜质护腿来完成这份订单，那可真能让我轻松不少。",
  },
  [27673] = {
    ["T"] = "给托雷克的委托",
    ["O"] = "工头巴兰要你使用锻造技能制作1把青铜重锤和2块重平衡石，并把订单交给灰谷银翼哨站以东山丘上的托雷克。",
    ["D"] = "嘿，你是城里的新铁匠吗？战歌那边的订单把我压得喘不过气来，而且这里有一份优先委托。如果你愿意帮忙，就做一把青铜重锤和几块重平衡石，把它们带给银翼哨站附近山丘上的托雷克。他正带着小队在那里准备一次突袭。",
  },
  [28075] = {
    ["T"] = "给西蒙尼·坎提瑞尔的委托",
    ["O"] = "西蒙尼·坎提瑞尔要你使用烹饪技能制作10份美味鼠尾鱼，并把订单交给奥特兰克山脉拉文霍德庄园的西蒙尼·坎提瑞尔。",
    ["D"] = "我发现东部王国非常需要我的技艺，所以我很庆幸能来到这里。我只希望这里的食物能更……可口一些。我怀念美味鼠尾鱼那轻盈细腻的味道，就像我从前在阿斯特兰纳吃到的那样。\n\n你该不会也擅长用炉火吧？如果是，我很乐意为一些新鲜烹好的鼠尾鱼给你报酬。",
  },
  [28082] = {
    ["T"] = "给卡拉恩·阿玛卡的委托",
    ["O"] = "卡拉恩·阿玛卡要你使用烹饪技能制作10份蟹肉蛋糕，并把订单交给灰谷佐拉姆加前哨站的卡拉恩·阿玛卡。",
    ["D"] = "欢迎来到佐拉姆海岸，$C。大海的馈赠近在眼前，却又远在天边。你看，我被派来指挥这个小小的前哨站，整天都得调度部队，应对四周的各种威胁。可我实在太想吃美味的蟹肉蛋糕了！\n\n如果你能给我做一些，那真是帮了大忙，不过如果你太忙，我也能理解。我就在这里。等着……",
  },
  [28388] = {
    ["T"] = "给凯尼斯·静风的委托",
    ["O"] = "达利亚要你使用附魔技能制作1根亲和法杖，并把订单交给灰谷林歌神殿的凯尼斯·静风。",
    ["D"] = "哦，如果我没看错的话，你是一名附魔师？林歌神殿的凯尼斯·静风一直在找一根亲和法杖，但镇上没有附魔师。如果你愿意帮忙，我相信他会让你觉得值得。",
  },
  [28392] = {
    ["T"] = "给奈莱·月天的委托",
    ["O"] = "奈莱·月天要你使用附魔技能制作1根强效秘法杖，并把订单交给凄凉之地扭线前哨的奈莱·月天。",
    ["D"] = "真是粗心，我们收拾行装来这里的时候，我把魔杖忘在阿斯特兰纳了。也可能是在石爪小径上弄丢了。不管怎样，请给我制作一根强效秘法杖。",
  },
  [28411] = {
    ["T"] = "给皮克希尔的委托",
    ["O"] = "皮克希尔要你使用附魔技能制作1根符文金棒，并把订单交给灰谷碎木岗哨的皮克希尔。",
    ["D"] = "噢，一个可爱的小附魔师。听着，你能帮我做一根符文金棒吗？别问它是干什么用的，地精生意！哦，不过我会付钱的。",
  },
  [28461] = {
    ["T"] = "给希莉丝的委托",
    ["O"] = "希莉丝要你使用工程学技能制作1个精制望远镜，并把订单交给灰谷碎木岗哨的希莉丝。",
    ["D"] = "大酋长派我来这里整顿这处岗哨，而我发现有很多事情要做。碎木岗哨这里有侦查骑兵，却几乎没有侦察装备。\n\n你是工程师，对吧？我需要一个精制望远镜来观察道路，也盯着那些工人。我会付钱。",
  },
  [28502] = {
    ["T"] = "给西蒙尼·坎提瑞尔的委托",
    ["O"] = "西蒙尼·坎提瑞尔要你使用钓鱼技能收集20条新鲜的大鼠尾鱼，并把订单交给奥特兰克山脉拉文霍德庄园的西蒙尼·坎提瑞尔。",
    ["D"] = "在阿斯特兰纳的家乡，我们珍视鼠尾鱼那简单、细腻而微妙的味道。我从没想到会在奥特兰克找到它们，更没想到会找到更大的！\n\n这些大鼠尾鱼带来的是记忆与惊喜。请给我带来20条新鲜的大鼠尾鱼。我想看看它的味道是否还和我记忆中一样。",
  },
  [28516] = {
    ["T"] = "给维克塔的委托",
    ["O"] = "维克塔要你使用钓鱼技能收集20条新鲜的鼠尾鱼，并把订单交给灰谷佐拉姆加前哨站的维克塔。",
    ["D"] = "哟，伙计，我听说这片森林的溪流里有种鱼叫鼠尾鱼。据说它们滑溜、聪明，还充满古老魔法……或者至少很有味道。\n\n你能给我带来20条新鲜的鼠尾鱼吗？我想看看这些故事是不是真的。也想看看它们是不是像听起来那么好吃。",
  },
  [28523] = {
    ["T"] = "给皮尔图拉斯·怀特姆恩的委托",
    ["O"] = "塞兰妮娅·伏根要你使用草药学技能采集20株跌打草，并把订单交给灰谷阿斯特兰纳的皮尔图拉斯·怀特姆恩。",
    ["D"] = "很高兴见到一位愿意在部落进攻东边森林时四处奔波的草药师。我在这里一直帮助银翼哨兵照料伤员，但我听说阿斯特兰纳有个生病的孩子需要跌打草。也许你能帮我采集20株跌打草，并把它们送到那里的皮尔图拉斯·怀特姆恩手中？",
  },
  [28548] = {
    ["T"] = "给耶努萨克雷的委托",
    ["O"] = "耶努萨克雷要你使用草药学技能采集20株跌打草，并把订单交给灰谷佐拉姆加前哨站的耶努萨克雷。",
    ["D"] = "暮光之锤在这里的活动扰乱了自然平衡，奴役元素并腐化这片土地的灵魂。\n\n我必须向灵魂献上一份祭品。为此，我需要20株跌打草。佐拉姆加前哨站必须在元素反噬我们所有人之前作出弥补。",
  },
  [28572] = {
    ["T"] = "给哨兵迈瑟琳的委托",
    ["O"] = "哈鲁恩·暗纹要你使用制皮技能制作2条黑皮腰带，并把订单交给灰谷林歌神殿的哨兵迈瑟琳。",
    ["D"] = "我最近听说了一个英勇故事，$C。在冥火岭那边，恶魔从南方涌来时，哨兵迈瑟琳坚守阵地，但并非没有代价。她的护甲被烧焦，腰带也被彻底撕裂。她失去了武器，还有她的……呃……尊严，如果你懂我的意思。\n\n下一场战斗前，她需要重新装备起来。如果你的制皮技艺足够高，就制作几条黑皮腰带，并把它送到林歌神殿的迈瑟琳那里。没有时间可以浪费。我听说恶魔还在源源不断地涌来。",
  },
  [28595] = {
    ["T"] = "给卡德拉克的委托",
    ["O"] = "希莉丝要你使用制皮技能制作5片重型护甲片，并把订单交给灰谷莫尔杉壁垒的卡德拉克。",
    ["D"] = "我需要你的协助，制皮师。奉大酋长之命，我正努力把这里的部队整顿起来，而补给短缺。虽然我在照应碎木岗哨的需求，也不能忽视我们的斥候和侦查骑兵。\n\n制作几片重型护甲片，把它们送到驻扎在贫瘠之地入口处莫尔杉壁垒的部队手中。我们不能让壁垒落入银翼的推进之下，否则我们就会与南方的部队被切断。",
  },
  [28610] = {
    ["T"] = "给拉尔丹的委托",
    ["O"] = "拉尔丹要你使用剥皮技能收集20张中皮，并把订单交给灰谷阿斯特兰纳的拉尔丹。",
    ["D"] = "你好，$N。你擅长使用剥皮刀吗？我日夜不停地工作，想满足哨兵和途经阿斯特兰纳的冒险者的需求，现在急需原料。\n\n如果你能给我带来20张中皮，我很乐意为你的服务付钱。",
  },
  [28627] = {
    ["T"] = "给弗兰·强风的委托",
    ["O"] = "弗兰·强风要你使用剥皮技能收集20张中皮，并把订单交给灰谷碎木岗哨的弗兰·强风。",
    ["D"] = "向你致意，$N。你擅长使用剥皮刀吗？我日夜不停地工作，想满足战歌和途经碎木岗哨的冒险者的需求，现在急需原料。\n\n如果你能给我带来20张中皮，我很乐意为你的服务付钱。",
  },
  [28662] = {
    ["T"] = "给工头弹簧栓的委托",
    ["O"] = "工头弹簧栓要你使用采矿技能采集20块锡矿石，并把订单交给灰谷碎木岗哨的工头弹簧栓。",
    ["D"] = "啊，看呐，一位专业矿工来了。你知道吗，我们这里的铜多得我都不知道该怎么办，可没有锡，我就没法熔炼青铜。问题是，林子里潜伏着那些东西，派苦工出城太危险了。\n\n你能给我带来20块锡矿石，好让我开始熔炼一些青铜吗？",
  },
  [28687] = {
    ["T"] = "给哨兵迈瑟琳的委托",
    ["O"] = "艾欧琳要你使用裁缝技能制作1条白色毛绒裙，并把订单交给灰谷林歌神殿的哨兵迈瑟琳。",
    ["D"] = "我急需一名裁缝，而且从你手指上的老茧来看，你知道怎么拿针。日子快到了——迈瑟琳和塞利姆·梦歌将在林歌神殿的枝叶下结为夫妻。庆典会很简单，但她仍希望穿上一件手工制作、充满意义的衣服。\n\n如果你有这门手艺，就做一条白色毛绒裙，送到灰谷另一边交给她。",
  },
  [28709] = {
    ["T"] = "给塞娜尼·雷心的委托",
    ["O"] = "塞娜尼·雷心要你使用裁缝技能制作2个丝绸小包，并把订单交给灰谷碎木岗哨的塞娜尼·雷心。",
    ["D"] = "灰谷的猎手们把战利品带给我，而在我们等待把它们装裱起来时，我已经快没地方存放了。如果你能给我做几个丝绸小包，我就能小心地装着这些供品。猎人的骄傲不该被塞进粗麻布袋里。",
  },
  [26497] = {
    ["T"] = "被污染的羊皮纸",
    ["O"] = "阅读被污染的羊皮纸，并与试炼谷兽穴里的纳托克谈一谈。",
    ["D"] = "啊，你离开的时候，有一张羊皮纸送来给你，$N。\n\n如果可以的话，我通常会避开术士的事，不过我想你有空时应该读一读。要是我没弄错，这是你新任训练师纳托克送来的。等你准备好了，他有话要跟你说。",
  },
  [26607] = {
    ["T"] = "后天口味",
    ["O"] = "从诅咒之地各处的红石晶鳞蜥蜴身上收集10块红石侧肉。",
    ["D"] = "我们的补给快见底了，而这片土地比杜隆塔尔盛夏还要严酷！这里的一切都有毒，不能吃……除非你懂解剖。\n\n在这片土地上游荡的红色蜥蜴最容易屠宰，也最容易处理成能吃的东西。只要记得把头和身体分开，然后从脖子里伸手进去，在毒液扩散前把橙色腺体扯出来。动作不够快的话，肉就不好了。\n\n给我带些侧肉来，我们就开火做饭！别担心，你也会有吃的。",
  },
  [26938] = {
    ["T"] = "猎人之道",
    ["O"] = "与剃刀岭的索塔尔谈一谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经足够熟练，能够驾驭一头野兽，并将它训练成你的伙伴。\n\n如果这听起来吸引你，就必须去杜隆塔尔的剃刀岭见索塔尔。他能让你踏上获得自己宠物的道路。",
  },
  [27119] = {
    ["T"] = "地平线上的沉船",
    ["O"] = "在艾萨拉南部海岸某处找到沉船幸存者。",
    ["D"] = "啊嘿，$C！我在摇晃谷这里视野极好，能看清艾萨拉沿岸上下，甚至能望到杜隆塔尔。\n\n不久前，我看到远处有一艘船遇险。它沉在相当远的地方，但我想有些幸存者到了岸上。你也许该沿着海岸过去看看他们。如果他们需要我们能提供的任何帮助，我们都会乐意尽力。",
  },
  [27169] = {
    ["T"] = "搜寻残骸",
    ["O"] = "在曼科里克的村庄寻找纳迪娅的踪迹，然后回到十字路口的曼科里克那里。",
    ["D"] = "这么说她逃出了半人马的魔掌！那纳迪娅为什么没有来这里？也许她不知道我在哪里。既然如此，我们必须找到她。她一定回到了我们的村子，以为我会在那里。\n\n$N，去我的村子找她。沿路向北走，到岔路口右转。沿着这片土地与杜隆塔尔交界的海岸向南走。你会在那里找到我们的村子，也希望能找到纳迪娅。",
  },
  [27204] = {
    ["T"] = "通缉：深皮",
    ["O"] = "杀死深皮，并把它的牙齿带给十字路口的索克。",
    ["D"] = "许多冒险者都成了这头格外凶暴的鳄鱼的猎物。它在贫瘠之地与杜隆塔尔交界的河流附近游荡。\n\n把它的一颗尖牙带给十字路口的索克，作为它已死亡的证明。",
  },
  [27266] = {
    ["T"] = "一触闪电",
    ["O"] = "将5份闪电精华吸入乔贡的法杖，然后回到剃刀岭的乔贡那里。",
    ["D"] = "你好，伙计。如果你有时间，我可以用得上你的帮助。我正在练习萨满技艺，想学会操控物品。要做到这一点，我需要一些闪电精华。\n\n最好的来源就在雷霆山那边。拿上我的法杖，对那些野兽使用它。那些蜥蜴的皮里富含闪电，而这根法杖会把它吸收进去。",
  },
  [27267] = {
    ["T"] = "急需援助的村庄",
    ["O"] = "为试炼谷的加罗基收集5份蓟草、3瓶地狱捕猎者之血和3只血爪利爪。",
    ["D"] = "你好，伙计。我收到一份本地村庄的报告，说他们需要一些补给。如果你在找活干，他们会很感激你的帮助。\n\n报告说他们需要一些蓟草，你可以在这片山谷里到处找到。接下来是北边洞穴里地狱捕猎者的血。最后，他们还需要南边迅猛龙群落里的血爪迅猛龙利爪。",
  },
  [27269] = {
    ["T"] = "中级迅猛龙骑术",
    ["O"] = "向克萨尔迪学习中级骑术，然后与杜隆塔尔的祖尼尔谈话领取你的迅猛龙。",
    ["D"] = "欢迎回来。你是来学习中级骑术的，对吧？和之前一样，你的迅猛龙费用已经有人付过了，但训练费用还得你自己出。很遗憾，迅捷骑术可不便宜。\n\n学会骑术后，跟我旁边的祖尼尔谈谈。他负责出售我们的迅猛龙。如果你现在还没有足够的钱，以后也可以再回来。",
  },
  [27270] = {
    ["T"] = "迅猛龙骑术",
    ["O"] = "向克萨尔迪学习初级骑术，然后与杜隆塔尔的祖尼尔谈话领取你的迅猛龙。",
    ["D"] = "所以你是来领迅猛龙的，是吧？正巧，我一直在等你！一位神秘资助者替你支付了一头普通迅猛龙的费用，而且是写着你的名字，$N。不过他们没有替你付训练费，所以恐怕你还是得自己购买训练。\n\n学会骑术后，跟我旁边的祖尼尔谈谈。他负责出售我们的迅猛龙。如果你现在还没有钱，以后也可以再回来。",
  },
  [27273] = {
    ["T"] = "沙格里",
    ["O"] = "杀死沙格里的灵魂，然后回到森金村的邦贝那里。",
    ["D"] = "你好，伙计。很久以前，有个名叫沙格里的巨魔曾是回音群岛的领袖。他被一名和你差不多的冒险者杀死。\n\n如今他的灵魂充满愤怒，正把怒火散播到群岛各处。必须阻止它！你可以在最北边岛屿的顶部找到巨魔为他建造的神龛。摧毁它，让他的存在彻底消失。",
  },
  [27274] = {
    ["T"] = "被诅咒的舰队",
    ["O"] = "杀死8名库尔提拉斯水手和3名库尔提拉斯上将，然后回到剃刀岭的加索克那里。",
    ["D"] = "干得好，$N，解决了要塞的问题，不过还有事情要做。几年前，库尔提拉斯人从海上袭击杜隆塔尔。大炮和爆炸差点杀死我的部下。后来我们终于等到奥格瑞玛的援军，把他们逼退并屠杀了许多人。\n\n我听说死去的库尔提拉斯船员无法安息，因为他们的任务尚未完成，只能在海上游荡。\n\n我要你去他们舰队的残骸那里，消灭所有还在惹麻烦的库尔提拉斯人。你可以在东边流亡海岸的沉船处找到他们。",
  },
  [27275] = {
    ["T"] = "通缉：尘爪",
    ["O"] = "把尘爪的鼻子带给试炼谷的工头塔兹利尔。",
    ["D"] = "奉卫兵之命，一头名叫尘爪的危险野狼在此被判处死刑！尘爪已经在试炼谷杀死了数十名居民，对想领取这笔赏金的冒险者来说将是一场挑战。\n\n有人看到尘爪在山谷东侧山脊巡逻。如果你成功了，就把它的鼻子带给工头塔兹利尔。",
  },
  [27276] = {
    ["T"] = "主管欣克",
    ["O"] = "向杜隆塔尔飞艇塔的主管欣克报到。",
    ["D"] = "我的一名斥候刚送来一封信。显然，那些正在建造我们新飞艇塔的地精遇上了麻烦。我不太确定这意味着什么……但既然工头请求帮助，剃刀岭就会回应。\n\n大酋长说，建成飞艇塔是最优先事项，所以我们必须协助地精解决他们遇到的任何问题！去向主管欣克报到，他负责监督施工。你会在奥格瑞玛大门东南不远处找到那座新飞艇塔。",
  },
  [27277] = {
    ["T"] = "锐齿龙停工危机",
    ["O"] = "杀死10只血爪锐齿龙，然后回到杜隆塔尔飞艇塔的主管欣克那里。",
    ["D"] = "我就知道接下杜隆塔尔这份活是个错误！艾泽拉斯这么多地方，我偏偏选了个迅猛龙和蝎子经常到处乱跑的地方。我告诉你，我之所以还在这里，唯一的原因就是大酋长付了我一大笔钱来建这座塔。\n\n自从施工开始，我们就一直在对付这些该死的迅猛龙！它们晚上不断袭击我们的营地，白天还吃我的工人。我需要你去把它们的数量“修剪”一下，好让工程进度重新跟上计划！",
  },
  [27278] = {
    ["T"] = "逃离尘风",
    ["O"] = "帮助吉兹尔·剪螺逃出尘风洞穴。如果成功，就向杜隆塔尔飞艇塔的主管欣克报告。",
    ["D"] = "我没想到还能再见到另一个$R！你得把我从这里救出去，这些教徒疯了！他们早些时候想对我施行一个仪式，但我觉得他们材料不全。\n\n等他们回来，肯定还会再试一次。这次可能就成功了！我们快点冲出去吧。",
  },
  [27279] = {
    ["T"] = "寻找吉兹尔",
    ["O"] = "找到吉兹尔·剪螺。你记得主管欣克说过，他可能被关在尘风洞穴。",
    ["D"] = "我最好的工程师吉兹尔·剪螺几天前外出补给时神秘失踪了。我很担心他，而且他的设计对飞艇塔的开发至关重要。\n\n要我猜的话，是火刃氏族抓走了他。我听说他们占据了剃刀岭北边一个名叫尘风洞穴的洞穴。他们会对俘虏进行恶魔仪式和其他恶行。\n\n我想你去尘风洞穴的话，很有机会找到吉兹尔。如果你找到他，我会为你的努力给你丰厚的报酬。",
  },
  [27611] = {
    ["T"] = "给主管欣克的委托",
    ["O"] = "米奥赞要你使用炼金术技能制作5瓶初级治疗药水，并把订单交给杜隆塔尔奥格瑞玛城外飞艇塔的主管欣克。",
    ["D"] = "我看你是个刚起步的炼金师！也许你能帮我。我现在手头的活多得做不完，奥格瑞玛城外飞艇塔那边的主管欣克一直在要一些初级治疗药水给受伤工人用。我正在给步兵们做一件重要的事，不过如果你愿意帮忙，就做五瓶那种药水，送给欣克。",
  },
  [27612] = {
    ["T"] = "给加索克的委托",
    ["O"] = "米奥赞要你使用炼金术技能制作5瓶初级防御药剂，并把订单交给杜隆塔尔剃刀岭的加索克。",
    ["D"] = "我还有另一份委托可以请你帮忙——非常简单，只需要最基础的技艺。\n\n沿着路往东走，你会找到剃刀岭。加索克指挥这一带的步兵，他就驻扎在那里。他想给部下要一些初级防御药剂。你愿意接下这份委托吗？",
  },
  [27661] = {
    ["T"] = "给拉尔·猎齿的委托",
    ["O"] = "沃克要你使用锻造技能制作1条铜质符文短裤和1副铜质符文护手，并把订单交给杜隆塔尔森金村的拉尔·猎齿。",
    ["D"] = "向你致意，$C。我认得出一双同为铁匠的手。你想不想亲自接下我的一份委托？\n\n森金村那边的拉尔·猎齿订了一条铜质符文短裤和一副铜质符文护手。如果你有兴趣，只要亲手把这些东西做出来，然后送过去就行。\n\n村子就在剃刀岭南边——你来这里的路上肯定经过了。",
  },
  [27662] = {
    ["T"] = "给主管欣克的委托",
    ["O"] = "沃克要你使用锻造技能制作2把铜质战斧，并把订单交给杜隆塔尔奥格瑞玛城外飞艇塔的主管欣克。",
    ["D"] = "你好，$C。我还需要些帮手，好把更多委托完成交出去。主管欣克为他的工人征用了几把铜质战斧，用来把蝎子赶离飞艇塔。\n\n如果你有兴趣完成这份委托，可以把斧头送给北边奥格瑞玛城外飞艇塔的主管。",
  },
  [28399] = {
    ["T"] = "给夏格的委托",
    ["O"] = "夏格要你使用附魔技能制作1根符文铜棒，并把订单交给杜隆塔尔剃刀岭的夏格。",
    ["D"] = "你也是像我一样的附魔师吗？我需要帮助来完善我的符文铜棒。你能做一根让我比较一下，看看我哪里做错了吗？之后我会给你一点小费作为谢礼！",
  },
  [28400] = {
    ["T"] = "给塔绍尔·锯痕的委托",
    ["O"] = "夏格要你使用附魔技能，用附魔胸甲 - 初级生命为提供的1件卫兵胸甲附魔，并把订单交给杜隆塔尔剃刀岭的塔绍尔·锯痕。",
    ["D"] = "有人要我给剃刀岭的战士训练师塔绍尔·锯痕的这件卫兵胸甲附魔，可我很怕他。他戴着眼罩，而且大家说他以前是个残忍嗜血的海盗！拜托，替我完成这事，然后把它送过去。",
  },
  [28449] = {
    ["T"] = "给主管欣克的委托",
    ["O"] = "穆德拉克要你使用工程学技能制作24把螺栓，并把订单交给杜隆塔尔奥格瑞玛城外飞艇塔的主管欣克。",
    ["D"] = "小心点，$N——你耳朵后面漏了一点油污！这说明你是个工程师，我正好有件事可以请你帮忙。\n\n有一队地精正在奥格瑞玛城外建造新的飞艇塔，他们需要两打螺栓。我一直忙着给那些货车做零件的订单，没顾上这件事。你觉得能帮上忙吗？",
  },
  [28450] = {
    ["T"] = "给拉尔·猎齿的委托",
    ["O"] = "穆德拉克要你使用工程学技能制作20枚劣质铜壳炸弹，并把订单交给杜隆塔尔森金村的拉尔·猎齿。",
    ["D"] = "嘿，既然你是工程师，这里还有另一件事可以请你帮忙。\n\n森金村那边的拉尔·猎齿需要一些帮助，来解决一伙讨厌的半人马。他问我能贡献点什么，我说，嗯，我能让他们轰的一声。嘿嘿。\n\n我说的是炸药，$N。\n\n一大堆劣质铜壳炸弹会让他觉得自己拥有一座私人军火库。",
  },
  [28542] = {
    ["T"] = "给杜拉的委托",
    ["O"] = "米什基要你使用草药学技能采集20朵宁神花，并把订单交给杜隆塔尔剃刀岭的杜拉。",
    ["D"] = "见习草药师，是吧，伙计？想证明你有成功的本事吗？我们先从基础开始。采集20朵宁神花，把它们带给剃刀岭的杜拉。你要是偷懒，她一定看得出来。",
  },
  [28583] = {
    ["T"] = "给索塔尔的委托",
    ["O"] = "卡玛瑞要你使用制皮技能制作1个轻皮箭袋，并把订单交给杜隆塔尔剃刀岭的索塔尔。",
    ["D"] = "有志成为制皮师？介意帮我处理几份订单吗？\n\n剃刀岭那边的索塔尔订了一个新箭袋。他说旧的快散架了，箭都从缝里戳出来。那可是危险事。\n\n这对初学者来说是个很合适的活。制作一个轻皮箭袋，把它送到马厩交给他。就当是练习，也是为部落服务。",
  },
  [28584] = {
    ["T"] = "给洛卡·刃影的委托",
    ["O"] = "卡玛瑞要你使用制皮技能制作2条手工皮短裤，并把订单交给杜隆塔尔剃刀岭东北方、枯水谷上方农场里的洛卡·刃影。",
    ["D"] = "如果你愿意，这里还有一份：洛卡说他一直在剃刀岭东北方“务农”。据我听说，那更像是乱挥乱砍，不像收割。显然，他从枯水谷爬出来时把裤子扯破了。\n\n如果你想练练手，就做几条手工皮短裤，带给他。他的农场就在峡谷上方，剃刀岭外面。",
  },
  [28607] = {
    ["T"] = "给卡玛瑞的委托",
    ["O"] = "雷尔科要你使用制皮技能制作2双夜色长靴，并把订单交给杜隆塔尔奥格瑞玛的卡玛瑞。",
    ["D"] = "哦！既然你是制皮师，我能再请你帮个忙吗？\n\n我欠卡玛瑞的太多，怎么也还不清。她是我孩子们的母亲，而且忍受了我大部分时间不在身边。大多数时候吧。\n\n总之，我现在手头没有皮料，但如果你能做几双夜色长靴，送到奥格瑞玛暗巷区她的店里交给她，我会很感激的，伙计。",
  },
  [28657] = {
    ["T"] = "给主管欣克的委托",
    ["O"] = "克鲁恩要你使用采矿技能采集20块铜矿石，并把订单交给杜隆塔尔奥格瑞玛城外飞艇塔的主管欣克。",
    ["D"] = "见习矿工，我正需要你的帮助。\n\n奥格瑞玛城外飞艇塔那边的主管欣克征用了一批铜矿石，可我现在一点也匀不出来。也许你可以发挥自己的本事，替剃刀岭完成这份订单？",
  },
  [28697] = {
    ["T"] = "给雷兹拉克的委托",
    ["O"] = "斯诺恩要你使用裁缝技能制作2个亚麻包，并把订单交给杜隆塔尔烈风峡谷的雷兹拉克。",
    ["D"] = "雷兹拉克在烈风峡谷北边有个营地，想靠几个口袋和一堆糟糕主意把生意打理好。自然，他开口要的是包。\n\n我忙着处理正经订单，没法帮忙，但如果你有兴趣接下来练练手，他承诺会让你觉得值得。",
  },
  [28698] = {
    ["T"] = "给泰塔希的委托",
    ["O"] = "斯诺恩要你使用裁缝技能制作1条简易的裙子，并把订单交给杜隆塔尔森金村的泰塔希。",
    ["D"] = "别把这事闹得太大，不过……我有件东西想请你替我制作。\n\n森金村那边的泰塔希总是在工作，帮所有人，就是不帮自己。我想着，如果她有件漂亮衣服穿，也许会笑一笑。可要我自己给她做，总觉得有点奇怪。所以……你替我做，好吗？",
  },
  [26449] = {
    ["T"] = "神圣卷轴",
    ["O"] = "把生命十字章带给雷霆崖的桑加·云骑者。",
    ["D"] = "拿着这个，$n。它叫生命十字章。\n\n你已经证明了自己的仁善与耐心，现在该看看你是否足够强大，能引导太阳最伟大的恩赐之一。\n\n我的朋友桑加最近在血蹄村附近遭遇了一些风险投资公司的人——他差点丧命。\n\n拿上十字章去找他谈谈。如果你能帮他，我们很快还会再谈。愿你沐浴在太阳的温暖中。",
  },
  [26450] = {
    ["T"] = "神圣卷轴",
    ["O"] = "带上生命十字章，复活莫高雷的达科达·自由吼。",
    ["D"] = "达科达和我已经抵达血蹄村东北方的风险投资公司矿洞。我们听说他们渗入了我们的平原，想拿到证据带给大酋长。\n\n我们看见几个败类正在翻看文件，于是发起了攻击。不幸的是，涌来的人远比我们能对付的更多。\n\n达科达替我挡住了他们，让我逃了出来……那个傻瓜，偏要逞英雄。\n\n我确定自己看见他倒在湖岸边，但我没法回去。他现在还在那里，你能帮帮我们吗，$n？",
  },
  [26451] = {
    ["T"] = "神圣卷轴",
    ["O"] = "从莫高雷的风险投资公司监工那里取回一份风险投资公司文件，然后回到雷霆崖的桑加·云骑者那里。",
    ["D"] = "关于十字章，我们以后还有时间再谈。现在最要紧的是从风险投资公司手里拿到那些文件。只要拿到它们，我们就能证明他们已经渗入莫高雷，并查出背后可能是谁在指使。\n\n我现在还不适合战斗，$n。你觉得自己有足够的力量，从矿洞里的监工手中夺回那些文件吗？如果你拿到了，就把它们带回给桑加，并告诉他我没事。",
  },
  [26462] = {
    ["T"] = "浸日羊皮纸",
    ["O"] = "阅读浸日羊皮纸，然后与纳拉其营地的凯雅谈谈。",
    ["D"] = "刚才有个信使在找你，$N。我想她是圣骑士训练师凯雅·日鬃派来的。如果这封信来自太阳行者，我建议你马上去见她。",
  },
  [26472] = {
    ["T"] = "太阳的眷顾",
    ["O"] = "与莫高雷的玛尔·软蹄谈谈。",
    ["D"] = "$N，等你处理完红云台地的事务后，必须前往血蹄村。在那里，你会找到玛尔·软蹄。她会教你更多关于永恒太阳安舍的知识，也会让你进一步了解大地母亲。你还会得到一些衣物，帮助你踏上旅途。",
  },
  [26473] = {
    ["T"] = "太阳法衣",
    ["O"] = "找到勇士晨露，用次级治疗术（等级2）治疗他的伤口。之后为他施放真言术：韧，然后回到血蹄村的玛尔·软蹄那里。",
    ["D"] = "身为牧师，我们有责任治愈盟友的伤口，并赐予他们坚韧，使他们能够度过余下的一天。\n\n去找到勇士晨露，用你的治疗力量帮助他，随后再赐予他韧性祝福。你可以在北边桥的另一端找到他。",
  },
  [26474] = {
    ["T"] = "神圣便笺",
    ["O"] = "阅读神圣便笺，然后与红云台地的马格鲁姆·迷雾行者谈谈。",
    ["D"] = "我刚收到一封给你的信，$N。它很可能来自我们的牧师训练师马格鲁姆。如果真是这样，我建议你读读内容，然后尽快去见他。",
  },
  [26879] = {
    ["T"] = "迅蹄的消息",
    ["O"] = "把萨曼莎·迅蹄的消息带给荆棘谷格罗姆高的肯维雷。",
    ["D"] = "很久以前，我们牛头人修习过一种古老的平原奔跑之术——能像科多兽奔越莫高雷辽阔草原那样疾速前行。后来族人学会驯养野兽，便放弃了这种技艺，但我还是小牛犊时，这门古老技艺就在召唤我。我天生擅长奔跑，也赢过许多比赛。\n\n可惜，我受了伤，恐怕再也无法奔跑了。我来到荆棘谷寻找传说中藏在丛林里的疗法，但我如今跛着腿，没法离开道路太远。\n\n你能帮我个忙，把这封信带给格罗姆高的肯维雷吗？我想感谢他的帮助，即使我的寻求最终没有成功。",
  },
  [26950] = {
    ["T"] = "猎人之道",
    ["O"] = "与血蹄村的雅文·刺鬃谈谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经有足够的本事驾驭野兽，并训练它成为你的伙伴。\n\n你必须去莫高雷血蹄村见雅文·刺鬃。他会引导你走上获得自己宠物的道路。",
  },
  [27249] = {
    ["T"] = "杀死入侵者！",
    ["O"] = "为杰文·恐怖图腾在幽暗台地杀死10名科卡尔劫掠者。",
    ["D"] = "我曾希望部落在莫高雷击败半人马会让我们与他们的关系有所改变。是我太愚蠢了。有些事永远不会变。\n\n你看起来是个有能力的战士。我需要你帮忙清理那些盘踞在幽暗台地附近的科卡尔劫掠者。",
  },
  [27252] = {
    ["T"] = "合适的安葬",
    ["O"] = "把恐怖图腾遗骨包带到莫高雷东北部赤色石的仪式篝火处。",
    ["D"] = "长老议会的事由我来处理。你已经按自己所说为我效力，也守住了诺言。\n\n我最后请求你一件事——把这些遗骨带到莫高雷东北部赤色石的神圣墓地。将它们投入仪式之火，让我族人的灵魂得以安息。然后你就不再欠我什么了，$N。",
  },
  [27339] = {
    ["T"] = "恐怖图腾的侵扰",
    ["O"] = "杀死4名恐怖图腾恶霸和4名恐怖图腾散兵，然后向纳拉其营地的格鲁尔·鹰风报告。",
    ["D"] = "走路当心，红云台地的和平居民。恐怖图腾氏族的成员已经离开我们的营地，在东边建立了自己的聚落。他们只为自己索取土地，从不考虑所有牛头人的需要。即使我们都是同一轮太阳下的孩子，也阻止不了他们玷污这片神圣的台地。\n\n我们的外交努力被他们拒绝，上一位使者也没有回来。我们别无选择：必须把恐怖图腾从红云台地清除出去。",
  },
  [27340] = {
    ["T"] = "寻找莫恩",
    ["O"] = "找到莫恩·日鬃。他最后一次被人看见，是朝红云台地的恐怖图腾聚落往东去了。",
    ["D"] = "我非常担心我的丈夫莫恩。两天前，他离开这里，去东边恐怖图腾的聚落和他们谈话。他想请求他们停止在台地上过度狩猎，但他一直没有回来。\n\n请去调查一下，把他平安带回我身边。你可以凭他角尖上的金色认出他。",
  },
  [27341] = {
    ["T"] = "寻找莫恩",
    ["O"] = "把简易绿色坠饰带给红云台地的凯雅·日鬃。",
    ["D"] = "你在倒下的牛头人脖子上发现了一条项链，上面挂着一枚简易绿色坠饰。你怀疑这就是凯雅·日鬃的丈夫，于是决定把坠饰带回红云台地。",
  },
  [27342] = {
    ["T"] = "豺狼人掳掠者",
    ["O"] = "在血蹄村西边的豺狼人洞穴中找到并释放8名被绑架的牛头人。",
    ["D"] = "我们需要你的帮助，$c。人们在采集食物或带孩子打猎时不断失踪。起初只是少数几个人，但现在已经有几十人不见了。\n\n有传言说，是本地豺狼人把他们带到了镇子西边的洞穴里。\n\n请你调查那个洞穴！如果我们的邻人被关在那里，请把他们带回来。",
  },
  [27343] = {
    ["T"] = "中级科多兽骑术",
    ["O"] = "向卡尔·雷歌学习中级骑术，然后与莫高雷的哈布·爪蹄谈话领取你的科多兽。",
    ["D"] = "欢迎回来。你是来学习中级骑术的，对吧？和之前一样，你的科多兽费用已经有人付过了，但训练费用还得你自己出。很遗憾，迅捷骑术可不便宜。\n\n学会骑术后，跟我旁边的哈布·爪蹄谈谈。他负责出售我们的坐骑。如果你现在还没有足够的钱，以后也可以再回来。",
  },
  [27344] = {
    ["T"] = "科多兽骑术",
    ["O"] = "向卡尔·雷歌学习初级骑术，然后与莫高雷的哈布·爪蹄谈话领取你的科多兽。",
    ["D"] = "所以你是来领科多兽的，是吧？正巧，我一直在等你！一位神秘资助者替你支付了一头普通科多兽的费用，而且是写着你的名字，$N。不过他们没有替你付训练费，所以恐怕你还是得自己购买训练。\n\n学会骑术后，跟我旁边的哈布·爪蹄谈谈。他负责出售我们的坐骑。如果你现在还没有钱，以后也可以再回来。",
  },
  [27345] = {
    ["T"] = "贤者暴雨图腾",
    ["O"] = "在莫高雷东北部赤色石附近找到贤者暴雨图腾。",
    ["D"] = "你愿意帮我个忙吗，$C？\n\n贤者暴雨图腾昨天离开这里，去赤色石的神圣墓地拜访，但他一直没有回来。你能去看看他，确认他没事吗？\n\n你可以从雷霆崖北边的升降梯下去，然后向东前往赤色石。",
  },
  [27346] = {
    ["T"] = "石牛湖污染",
    ["O"] = "把10块风险投资公司残骸带给血蹄村的阿加莎·长线。",
    ["D"] = "石牛湖的神圣泉水滋养了我们数百年。它是莫高雷真正的生命之源，是大地母亲赐福的圣杯。\n\n$C，看看它现在成了什么样！精炼金属碎片、残骸，还有某种连我丈夫都不敢碰的油污……他甚至钓到过肚子里有金属螺栓的鲶鱼！\n\n风险投资公司为了利润要蹂躏莫高雷，把我们埋进一座由它亵渎的馈赠扭成的坟墓里，而这些馈赠对我们的人民如此神圣。\n\n请你帮我稍微清理一下湖水好吗？大部分垃圾都集中在东北岸附近。",
  },
  [27347] = {
    ["T"] = "现在凝固也不晚",
    ["O"] = "取回侏儒凝固器，并用它净化石牛湖。完成后回到阿加莎·长线那里。",
    ["D"] = "等等，你脸上是什么？哦，是那种脏油。我愿意相信它没有毒，但我担心它正在腐蚀水源和土地。\n\n血蹄村的一位猎人提到过一种奇怪装置，东北方矿洞里的风险投资公司工人和监工会用它清理油污。\n\n试着把它弄来。如果他们能在矿洞里中和污染，我们也能用它处理石牛湖。",
  },
  [27348] = {
    ["T"] = "阻止掠夺者",
    ["O"] = "杀死巴尔丹鉴定师，收集他们携带的上古牛头人遗物。把其中6件带给雷霆崖灵魂高地的帕维·迷雾行者。",
    ["D"] = "你好，$C。你和村子里的布莱恩·血蹄谈过了吗？他正在找人前往莫高雷西部的巴尔丹矮人挖掘场，阻止他们继续挖掘。\n\n布莱恩的目标可以理解，但有时我们也必须挖掘，才能重见历史。既然破坏已经造成，我希望你尽量善用这一点。挖掘场里的鉴定师携带着在那里发现的文物。我希望你收集那些文物，好让我们研究它们。",
  },
  [27349] = {
    ["T"] = "阻止掠夺者",
    ["O"] = "从莫高雷东南部矿洞的风险投资公司人员手中夺回8件上古遗物。",
    ["D"] = "在莫高雷，矮人并不是唯一侵占我们历史的人。风险投资公司在莫高雷东南部开了一座矿。他们只为掠夺资源而来，毫不在意自己鲁莽的行为正在摧毁多少历史！\n\n我知道矿洞里的工人会把找到的古物据为己有。与其让那些遗物填满贪婪地精的口袋，不如让它们留在牛头人手中。请去矿洞把它们夺回来！",
  },
  [27350] = {
    ["T"] = "走失的小牛",
    ["O"] = "在血蹄村找到走失科多兽幼崽的主人。",
    ["D"] = "你在一头惊慌的科多兽幼崽脖子上发现了一个损坏的项圈，上面的主人身份已经磨损得看不清了。\n\n突然，这头科多兽幼崽飞奔而去，只把项圈留在你手中。血蹄村里也许有人就是它的主人。去找找看，把你的发现告诉他们。",
  },
  [27351] = {
    ["T"] = "走失的小牛",
    ["O"] = "从莫高雷平原上的陆行鸟和猛鹫身上收集8颗莫高吉浆果。",
    ["D"] = "那个小捣蛋鬼！我很喜欢他，但他的不听话越来越让人头疼了。\n\n你找到的那头小牛叫奥多克。自从它母亲去世后，我一直在照顾它，因为它还小，没法自己照料自己。我很担心它独自在平原上！我们必须把它带回来。\n\n它特别喜欢一种零食，我知道那东西能把它引回来，但需要你收集一些材料来制作。\n\n村子北边的猛鹫和陆行鸟会在胃里发酵本地的莫高吉浆果，不知为什么，奥多克特别喜欢那种味道。把这些浆果带给我，我们就可以开始做诱饵了。",
  },
  [27352] = {
    ["T"] = "走失的小牛",
    ["O"] = "从石牛湖的湖石斑鱼身上收集石斑鱼泥。",
    ["D"] = "如果你觉得刚才那东西很恶心，那我只能遗憾地说，接下来还会更糟。我们还需要湖里石斑鱼身上的一些石斑鱼泥。\n\n每隔一天，我都会带奥多克去钓石斑鱼，然后把边角料给它。我敢说那股刺鼻气味一定会让它直奔我们而来。",
  },
  [27353] = {
    ["T"] = "走失的小牛",
    ["O"] = "把小牛诱饵放在血蹄村旅店外面，引诱奥多克回到主人身边。",
    ["D"] = "把这些浆果和鱼泥混在一起，就成了给奥多克的\"美味\"零食。不过，为了其他旅店客人的利益，请把它放在旅店外面。",
  },
  [27489] = {
    ["T"] = "峡谷巡逻",
    ["O"] = "莫特加·火鬃要你在千针石林杀死8只杂毛土狼。",
    ["D"] = "尽管这些土地上的土狼以凶残的食腐者闻名，它们其实也是能干的猎手。它们是大地母亲生命循环的一部分，并不比贫瘠之地的狮子或莫高雷的伟大科多兽更不重要。\n\n不幸的是，这也使它们成了千针石林旅人的威胁。你能帮我个忙，削减一下它们的数量吗？",
  },
  [27897] = {
    ["T"] = "星辰中的征兆",
    ["O"] = "与莫高雷和贫瘠之地之间山丘中、大地母亲安息地的观星者纳洛谈谈。",
    ["D"] = "伟大的薄翼狮鹫啊，你看见了吗？一颗流星从天上落下来了！这就是我们等待的征兆——它表示大地母亲安息地的洞穴终于开启了。观星者纳洛守护着那里，就在雷霆崖东北方边境山丘里，位于莫高雷和贫瘠之地之间。那里是部落领地，所以我才希望找到像你这样大胆的冒险者前往那里，协助观星者夺回双子之心。\n\n你也许会奇怪，为什么我不派自己的族人去？嗯，预言说只有外来者才能安全地带走大地母亲的宝物。所以如果你愿意，下一班去卡利姆多的船上就有你的位置。",
  },
  [27898] = {
    ["T"] = "星辰中的征兆",
    ["O"] = "与雷霆崖的赞金·石蹄谈谈。",
    ["D"] = "你好，$N！你对天文学感兴趣吗？我听说很快会发生一次非常特别的天象——而萨满祭司赞金·石蹄一直在寻找一位大胆的冒险者，协助他完成某种与此有关的重要仪式。\n\n你可以在雷霆崖中央高地、凯恩·血蹄附近找到他。",
  },
  [27899] = {
    ["T"] = "星辰中的征兆",
    ["O"] = "与莫高雷和贫瘠之地之间山丘中、大地母亲安息地的观星者纳洛谈谈。",
    ["D"] = "你看见天空中的那道光了吗？那就是征兆——大地母亲安息地的洞穴终于开启了。观星者纳洛守护着那里，就在雷霆崖东北方的边境山丘里，位于莫高雷和贫瘠之地之间。预言说，只有外来者才能协助观星者夺回大地母亲子女的双子之心。如果你愿意帮助我们，现在正是时候。你可以沿着赤色石北边悬崖上的小路上去找到观星者。",
  },
  [27914] = {
    ["T"] = "血与荣耀的羁绊",
    ["O"] = "前往莫高雷赤色石的墓地，使用仪式熏香祭拜你的先祖。",
    ["D"] = "你想进一步了解我的人民？我想我也算是个老师，而且比大多数人更愿意教。毕竟，我哪儿也去不了。\n\n如果你真的想理解我的人民，就必须先明白，荣耀是言语、行为和行动的根基。我们的氏族由漫长的荣耀事迹维系在一起。我们明白，自己的行动反映的不只是自己。\n\n让我看看你如何尊敬他人。在你先祖的安息之地使用这份仪式熏香，然后回到我这里。",
  },
  [26883] = {
    ["T"] = "给萨曼莎的药膏",
    ["O"] = "把完成的药膏带给萨曼莎·迅蹄，她在荆棘谷的主路上徘徊。",
    ["D"] = "给我一点时间，$N。\n\n<安格伦把疾跑蓟磨成细末，然后拌进药膏里。>\n\n现在这份药膏应该可以安全地给萨曼莎用了。请把它带给她，祝你们两位好运。",
  },
  [27203] = {
    ["T"] = "黑曜石圣物",
    ["O"] = "把黑曜石圣物带给雷霆崖的帕维·迷雾行者。",
    ["D"] = "如果矮人对这样的东西感兴趣，我就不得不担心了。如果这东西哪怕有一点可能是武器，我们的盟友都必须知情。\n\n把这件圣物带给雷霆崖灵魂高地的帕维·迷雾行者。她对古物很感兴趣，也许能帮上忙。",
  },
  [27354] = {
    ["T"] = "通缉：贾索恩",
    ["O"] = "追杀在雷霆崖下方游荡的半人马贾索恩。",
    ["D"] = "一名被流放的加拉克半人马正在雷霆崖城下游荡，袭击男人、女人和孩子。这绝不能容忍！召集你的朋友，猎杀这个半人马。\n\n把你战胜这头野兽的证明带给雷霆崖上的赞金·石蹄，你会得到奖赏。",
  },
  [27490] = {
    ["T"] = "峭壁潜猎",
    ["O"] = "莫特加·火鬃要你在千针石林杀死6只峭壁潜伏者。",
    ["D"] = "土狼并不是千针石林中唯一的危险，$n。人必须时刻准备面对看得见和看不见的威胁。\n\n峭壁潜伏者精于伪装，比普通的山狮危险得多。那些愚蠢到偏离标记道路的人，很快就会亲身体会到这一点。\n\n虽然我看得出你并不愚蠢，但你仍需要深入峡谷去面对它们。保持警觉，$c。我们都指望你。",
  },
  [27495] = {
    ["T"] = "毒蛇之咬",
    ["O"] = "把10个致命毒腺带给莫特加·火鬃。",
    ["D"] = "千针石林危机四伏，朋友。不只是半人马，本地野兽同样危险。许多旅人不听我的警告，结果受伤，我已经处理过太多这样的伤势。\n\n风蛇的咬伤需要特别处理，尤其是它们的毒液。只有用风蛇毒液制成的解毒剂才能彻底中和其效果，而我的补给快用完了。\n\n我并不想让你为这事冒生命危险，但如果你能帮我弄些风蛇的毒腺来，我会给你丰厚报酬。",
  },
  [27613] = {
    ["T"] = "给博学者暴雨图腾的委托",
    ["O"] = "克雷要你使用炼金术技能制作5瓶初级法力药水，并把订单交给莫高雷赤色石的博学者暴雨图腾。",
    ["D"] = "我从你护甲上的宁神花污渍就看得出你是炼金师！也许你能帮帮我？\n\n我的课业落后了，手头又堆着一堆我填不上的订单。如果你能帮忙，我就能回去学习，好在实验室里派上更多用场。如果你愿意帮忙，就制作一些初级法力药水，然后送给东边赤色石的贤者暴雨图腾。",
  },
  [27614] = {
    ["T"] = "给摩林·云行者的委托",
    ["O"] = "克雷要你使用炼金术技能制作5瓶弱效巨魔之血药剂，并把订单交给莫高雷血蹄村南边道路上的摩林·云行者。",
    ["D"] = "你知道吗，如果你有兴趣多做点事，这一带有很多炼金师能接的活。\n\n摩林·云行者巡逻通往贫瘠之地的南边道路，经常会遇到……小意外。倒也不是值得用治疗药水的伤——但我敢说他会对一些弱效巨魔之血药剂感兴趣。如果你愿意接这份委托，就制作五瓶弱效巨魔之血药剂送给他。",
  },
  [27663] = {
    ["T"] = "给博学者暴雨图腾的委托",
    ["O"] = "马诺特·糙创要你使用锻造技能制作10块劣质砂轮，并把订单交给莫高雷东北部赤色石的博学者暴雨图腾。",
    ["D"] = "向你致意，$C。我看得出你是铁匠。不知道你是否能帮忙完成一位传承者托我办理的请求？\n\n我需要有人制作并送一批劣质砂轮给东北方赤色石的贤者暴雨图腾。他会在我们为亡者举行的神圣仪式中使用它们，但我现在已经完全没有存货了。你有兴趣帮忙吗？",
  },
  [27664] = {
    ["T"] = "给伊恩·鹰爪的委托",
    ["O"] = "马诺特·糙创要你使用锻造技能制作3把铜质钉锤，并把订单交给莫高雷雷霆崖的伊恩·鹰爪。",
    ["D"] = "伊恩·鹰爪不久前来过这里，想找几把铜质钉锤，作为他兄弟即将举行的仪式上的礼物。他想委托制作三把，但我没有存货，雷霆崖的铁匠也忙得没法及时制作。如果你能迅速处理这份订单，我知道他会很感激。",
  },
  [28078] = {
    ["T"] = "给皮亚尔·静行的委托",
    ["O"] = "皮亚尔·静行要你使用烹饪技能制作10份香辣狼肉，并把订单交给莫高雷血蹄村的皮亚尔·静行。",
    ["D"] = "向你致意，$N！既然你表现出对烹饪的兴趣，我正好需要你的帮助。血蹄村这些天有许多饥饿的训练新手，而我的香辣狼肉已经用完了。如果你愿意帮我再烹制一些，我很乐意给你一些练习烹饪时用得上的补给！你能帮忙吗？",
  },
  [28401] = {
    ["T"] = "给博学者暴雨图腾的委托",
    ["O"] = "莫特·晨行者要你使用附魔技能，用附魔护腕 - 初级耐力为提供的1副守护者护腕附魔，并把订单交给莫高雷赤色石的博学者暴雨图腾。",
    ["D"] = "附魔师，我有几份订单需要帮手。这份是给赤色石的贤者暴雨图腾的。他留下了自己的守护者护腕，想给它们附上耐力。请把附魔后的护腕送给他，你会得到报酬。",
  },
  [28402] = {
    ["T"] = "给玛加萨·恐怖图腾的委托",
    ["O"] = "莫特·晨行者要你使用附魔技能，用附魔胸甲 - 初级吸收为提供的1件演说者长袍附魔，并把订单交给雷霆崖长者高地的玛加萨·恐怖图腾。",
    ["D"] = "你好，附魔师，如果你不介意帮忙，我可不想让一位长者等着。雷霆崖那边的玛加萨·恐怖图腾要求给几件新的演说者长袍附上初级吸收。我想这一单你能处理吧？",
  },
  [28451] = {
    ["T"] = "给梅洛尔·石蹄的委托",
    ["O"] = "特维兹维克·链磨要你使用工程学技能制作1把劣质火枪，并把订单交给莫高雷雷霆崖的梅洛尔·石蹄。",
    ["D"] = "卡利姆多的工程师太少，我们的服务供不应求。就拿梅洛尔·石蹄来说吧——他传来消息，说想要一把新枪，但我一直忙得没空回应。我不喜欢放弃委托，不过如果你愿意做件好事，可以制作一把劣质火枪，然后送到雷霆崖猎人高地交给他。",
  },
  [28452] = {
    ["T"] = "给贝恩·血蹄的委托",
    ["O"] = "特维兹维克·链磨要你使用工程学技能制作5根铜管，并把订单交给莫高雷血蹄村的贝恩·血蹄。",
    ["D"] = "我知道贝恩·血蹄是酋长的儿子，也知道他讨厌科技。我承认，如果牛头人不高兴，风险投资公司和探险者协会在莫高雷做的事确实不太妥。你可不能惹潜在顾客生气！\n\n风险投资公司一直往湖里倾倒废料，贝恩可以用一些铜管来抽走部分油污和淤泥。也许你能让他看到，工程学（还有地精）除了炸东西，也能帮上忙？",
  },
  [28486] = {
    ["T"] = "给维拉·幼蹄的委托",
    ["O"] = "维拉·幼蹄要你使用急救技能制作20条亚麻绷带，并把订单交给莫高雷血蹄村的维拉·幼蹄。",
    ["D"] = "营地里很快挤满了年轻战士，一群新蹄子，全都急着证明自己。训练随之而来的，是瘀伤、擦伤，还有比理智更多的自尊。\n\n我们的绷带储备快用完了。如果你能带给我20条亚麻绷带，我们就能继续处理这些小伤，免得它们变得更糟。",
  },
  [28512] = {
    ["T"] = "给乌萨恩·静水的委托",
    ["O"] = "乌萨恩·静水要你使用钓鱼技能收集20条新鲜的美味小鱼，并把订单交给莫高雷血蹄村的乌萨恩·静水。",
    ["D"] = "没有什么比水面的宁静、鱼线的牵动、抛竿之间的寂静更美妙了。这是一种与大地母亲及她所有造物交流的方式。\n\n如果你和我一样享受钓鱼，就带给我20条新鲜的美味小鱼。不是为了交易，不是为了钱。只是为了分享收获的喜悦。",
  },
  [28543] = {
    ["T"] = "给克雷的委托",
    ["O"] = "鲁尔·鹰爪要你使用草药学技能采集20朵银叶草，并把订单交给莫高雷雷霆崖的克雷。",
    ["D"] = "我的侄子克雷是雷霆崖上的炼金学徒。他给我妻子捎来消息，说自己的银叶草又不够了。\n\n我担心他没有认真对待学业，但也不想看他失败。你愿意采集20朵银叶草并带给他吗？如果你带着草药出现，他就会明白，这样的善意很少是免费的。",
  },
  [28585] = {
    ["T"] = "给赞金·石蹄的委托",
    ["O"] = "乔·硬皮要你使用制皮技能制作2件雕花皮外衣，并把订单交给莫高雷雷霆崖上层高地的赞金·石蹄。",
    ["D"] = "又来一个制皮学徒？也许你不介意帮我处理几份积压订单？\n\n赞金·石蹄在仪式火焰旁烧焦了上一件雕花皮外衣，需要一件新的。这单很简单，如果你不介意接下的话。",
  },
  [28586] = {
    ["T"] = "给梅洛尔·石蹄的委托",
    ["O"] = "乔·硬皮要你使用制皮技能制作2个小皮弹药包，并把订单交给莫高雷雷霆崖猎人高地的梅洛尔·石蹄。",
    ["D"] = "赞金的兄弟梅洛尔是一位伟大的猎人。他也下了一份订单，我希望你来处理这一单。\n\n制作几个小皮弹药包，把它们带到雷霆崖猎人高地交给梅洛尔。他刚从一位工程师那里订了一把新枪，想试试新的弹药。",
  },
  [28599] = {
    ["T"] = "给萨曼莎·迅蹄的委托",
    ["O"] = "布劳恩要你使用制皮技能制作1副制箭师手套，并把订单交给在荆棘谷主路上巡逻的萨曼莎·迅蹄。",
    ["D"] = "我看见你处理生皮的手法了。制皮师？我有份活给你。\n\n萨曼莎·迅蹄来到荆棘谷，是为了寻找治疗跛脚的方法。但我看得出，她开始接受猎人那种潜行和狙击的生活了。给她做一副制箭师手套，好吗？我本来可以自己做，但我问了她太多问题，不想让她觉得我喜欢她。或者类似那种事。\n\n<布劳恩咳嗽。>",
  },
  [28625] = {
    ["T"] = "给约恩·深切的委托",
    ["O"] = "约恩·深切要你使用剥皮技能收集5张轻毛皮，并把订单交给莫高雷血蹄村的约恩·深切。",
    ["D"] = "向你致意，$N。你想成为剥皮师？那就让我看看你不只是会找些碎料。\n\n带给我一张轻毛皮——不是皮革，是毛皮。要有形状，有结构……值得加工的东西。证明你知道自己在做什么，我就会认可你继续训练这项技能。",
  },
  [28628] = {
    ["T"] = "给莫特加·火鬃的委托",
    ["O"] = "莫特加·火鬃要你使用剥皮技能收集5张中毛皮，并把订单交给千针石林白沙岗哨的莫特加·火鬃。",
    ["D"] = "向你致意，$N。请原谅我，但我忍不住注意到你那把剥皮刀正仔细绑在背包上。我一直有兴趣收集原料，用来制作护甲，保护那些进入这里荒野的人。你愿意为我收集5张中毛皮吗？",
  },
  [28658] = {
    ["T"] = "给哈兰特·铁腕的委托",
    ["O"] = "阿查克·余烬梦要你使用采矿技能采集20块劣质的石头，并把订单交给莫高雷血蹄村的哈兰特·铁腕。",
    ["D"] = "我看见你包里的矿工锄了！真勤快，不是吗？也许你想接一份委托，一份真正属于你的订单？\n\n村里大帐篷中的哈兰特要了一批劣质的石头。你何不出去替他装满这份订单？帮助邻人是一种祝福……而你也正好需要练习。",
  },
  [28699] = {
    ["T"] = "给马格林·河鬃的委托",
    ["O"] = "凡恩要你使用裁缝技能制作2件蓝色亚麻衬衣，并把订单交给莫高雷血蹄村的马格林·河鬃。",
    ["D"] = "血蹄村下面的马格林已经穿着同一件旧淡紫背心好几个季节了，现在那东西与其说是衬衣，不如说全是补丁。他不会主动要新的——说它“还能穿”。\n\n我希望自己有时间做件好事帮帮他，但我被订单和训练压得喘不过气。如果你有时间，能制作两件蓝色亚麻衬衣送过去吗？我想他会感激一份用心制作的礼物。",
  },
  [28700] = {
    ["T"] = "给帕维·迷雾行者的委托",
    ["O"] = "凡恩要你使用裁缝技能制作1副高级亚麻手套，并把订单交给莫高雷雷霆崖灵魂高地的帕维·迷雾行者。",
    ["D"] = "帕维·迷雾行者一直在灵魂高地协助传承者处理古老遗物——精致的雕刻、羽饰护符，甚至还有裂开的符文石。她要求一副手套，好避免光着蹄子接触它们。\n\n我希望你接下这份订单，好让它能及时送达。帕维说，我们应该尊重过去，而这要从不把它弄脏开始。",
  },
  [26310] = {
    ["T"] = "自愿者的试炼",
    ["O"] = "击败血色修道院东边墓地中的三名前圣骑士幽灵。安抚这些灵魂后，回到幽暗城的堕落骑士那里。",
    ["D"] = "你的第一次试炼需要远赴提瑞斯法林地东北部。那里在血色修道院东边，但小心不要太靠近修道院，因为你现在还没有强大到足以进入那地方。你应该能找到一条通往墓地的小石路。\n\n在那座墓地里，你会找到三名圣骑士幽灵。他们生前并肩作战，死后也葬在自己的安息之地。我感觉他们仍眷恋着这个世界。去释放他们，让他们终于得以安息。",
  },
  [26428] = {
    ["T"] = "神圣卷轴",
    ["O"] = "阅读神圣卷轴，然后与丧钟镇的达内尔谈谈。",
    ["D"] = "你走之前，我刚从信使那里收到这卷卷轴。它来自附近的圣骑士训练师达内尔。看看吧，被遗忘者行列中的圣骑士可不多。",
  },
  [26436] = {
    ["T"] = "阿图尔克的杰作",
    ["O"] = "把奥金马铠带给提瑞斯法林地安息露台的血色圣骑士。你需要灵魂图腾才能看见他们。",
    ["D"] = "<阿图尔克擦去额头上的汗水，脸上洋溢着自豪。>\n\n我在德拉诺开始当学徒时，从没想过自己会为一位圣光战士打造马铠。但这件作品，我的被遗忘者朋友，是我最出色的作品之一。感谢你信任我，让我为你献上最好的手艺。\n\n毫无疑问，你的向导会想亲自评判这件工艺品的质量。把你的马铠带给他们，如果有什么问题再回来找我。",
  },
  [26437] = {
    ["T"] = "马灵",
    ["O"] = "前往安多哈尔废墟，释放那里的马灵。与马灵交谈，为奥金马铠祝福。然后回到提瑞斯法林地安息露台的血色圣骑士那里。你需要灵魂图腾才能看见他们。",
    ["D"] = "你的马铠需要一种特殊形式的祝福，来自合适灵魂的祝福。不远处的安多哈尔废墟里，我能感觉到城市陷落时被困在那里的马匹灵魂。释放它们，它们会赐予你的马铠祝福作为回报。\n\n你必须释放所有灵魂，$N，否则祝福会失败。虽然我本就预料它会失败，毕竟你是这样的憎恶之物。",
  },
  [26438] = {
    ["T"] = "占卜水晶",
    ["O"] = "把一颗艾泽拉斯钻石和一颗原始黑钻石带给提瑞斯法林地安息露台的血色圣骑士。你需要灵魂图腾才能看见他们。",
    ["D"] = "如果你真心想完成这件事，我们就需要一种方法来唤起一匹死去的战马。你用来与我交谈的灵魂图腾将成为这个装置的基础。\n\n还需要的其他材料是两颗钻石。它们的光辉必须彼此映照，才能让圣光穿透帷幕。因此，我需要一颗艾泽拉斯钻石和一颗原始黑钻石。有了它们作为聚焦媒介，灵魂图腾就能成为你神圣意志的信标。\n\n<血色圣骑士颤抖了一下。>\n\n听听我在说什么，居然像对一个配得上的存在那样对你说话。",
  },
  [26460] = {
    ["T"] = "被遗忘的身躯",
    ["O"] = "使用你的生命符记，在布瑞尔东边、巴尼尔农场北边十字军前哨附近救活兰斯·哈特斯托伦。\n\n如果你弄丢了生命符记，幽暗城的杰克·哈特斯托伦可以再给你一个。",
    ["D"] = "我和我的兄弟兰斯在布瑞尔东边的十字军前哨附近。我们在侦察并射杀几名血色十字军，但我们惹上了超出自己能力的麻烦。我们逃跑了，可我回头一看，他不见了！请去找到他。\n\n我希望自己能和你一起去，但我逃跑时中了好几箭。愿黑暗女王看护你。",
  },
  [26463] = {
    ["T"] = "亡灵壁垒",
    ["O"] = "与亡灵壁垒的乔纳森·贝雷斯福德谈谈。",
    ["D"] = "时候到了，$C $N。你一直证明自己是真理与正义的守护者。你的下一场试炼正在亡灵壁垒的乔纳森·贝雷斯福德那里等着你。从提瑞斯法林地向东走，你不会错过它。",
  },
  [26464] = {
    ["T"] = "乔纳森的任务",
    ["O"] = "收集20块爪牙的天灾石，并把它们带给布瑞尔的梅里尔·温德尔。",
    ["D"] = "瘟疫之地亡灵携带的天灾石中蕴含着力量。作为你试炼的第一部分，你必须取得相当数量的这些石头，并把它们带给一位名叫梅里尔·温德尔的女祭司，她住在布瑞尔。\n\n还有，$n，记住你必须携带银色黎明委任徽章才能找到这些石头。那个叫加鲁什的兽人正在把它们丢给任何有脉搏的人，也丢给我们这些没有脉搏的人。",
  },
  [26465] = {
    ["T"] = "乔纳森的任务",
    ["O"] = "把惰性天灾石带给亡灵壁垒的乔纳森·贝雷斯福德。",
    ["D"] = "这些石头已经净化了，$N。这样做风险极大，但我在布瑞尔觉得足够安全。\n\n你应该把这些东西带回给乔恩。以我对他的了解，他心里一定有个更宏大的用途。",
  },
  [26681] = {
    ["T"] = "中级亡灵马术",
    ["O"] = "向维尔玛·瓦纳姆学习中级骑术，然后与提瑞斯法林地的撒迦利亚·普斯特谈话领取你的骸骨战马。",
    ["D"] = "欢迎回来。你是来学习中级骑术的，对吧？和之前一样，你的骸骨战马费用已经有人付过了，但训练费用还得你自己出。很遗憾，迅捷骑术可不便宜。\n\n学会骑术后，跟我身后的撒迦利亚·普斯特谈谈。他负责出售我们的战马。如果你现在还没有足够的钱，以后也可以再回来。",
  },
  [26683] = {
    ["T"] = "亡灵马术",
    ["O"] = "向维尔玛·瓦纳姆学习初级骑术，然后与提瑞斯法林地的撒迦利亚·普斯特谈话领取你的骸骨战马。",
    ["D"] = "所以你是来领骸骨战马的，是吧？正巧，我一直在等你！一位神秘资助者替你支付了一匹普通战马的费用，而且是写着你的名字，$N。不过他们没有替你付训练费，所以恐怕你还是得自己承担。\n\n学会骑术后，跟我身后的撒迦利亚·普斯特谈谈。他负责出售我们的战马。如果你现在还没有钱，以后也可以再回来。",
  },
  [26925] = {
    ["T"] = "给历史学家的消息",
    ["O"] = "找到布瑞尔的历史学家托德·佩奇，告诉他鱼人已经占据北岸矿洞。",
    ["D"] = "你好，朋友……你碰巧要去布瑞尔吗？如果是的话，能替我带个消息过去吗？\n\n我叫贾斯珀·格林，是传承者的新晋成员。我的上级佩奇历史学家正在布瑞尔等我从北岸矿洞收集一些遗物回来。但我没法完成他的要求——鱼人已经占据了矿洞周围。\n\n他告诉我，任务没完成就别回去。你能解释一下这个问题吗？也许他会知道该怎么办。",
  },
  [26926] = {
    ["T"] = "一箱遗物",
    ["O"] = "调查北岸矿洞，为布瑞尔的历史学家托德·佩奇找回那箱收集来的遗物。",
    ["D"] = "北岸矿洞是在洛丹伦陷落前不久建立的。你可以在索利丹农场西边、道路尽头再往前、靠近耳语海岸稍微内陆的位置找到它。\n\n这座矿洞从来没靠矿石赚过钱，但曾经有一份报告送往首都，声称矿工发现了奇怪而古老的遗物。最近，幽暗城找回的旧文件中重新发现了这份报告。\n\n据我判断，那只箱子从未被取走，现在应该还在矿洞里发霉。\n\n所以去那里，把它找回来！",
  },
  [26927] = {
    ["T"] = "一箱遗物",
    ["O"] = "把那箱收集来的遗物带给幽暗城魔法区的历史学家伊娃·特雷莱恩。",
    ["D"] = "你充分完成了我交给你的任务，所以我会再次把这箱遗物托付给你。\n\n沿着布瑞尔南边的道路走。它会直接通往幽暗城。在魔法区，你会找到传承者历史学家伊娃·特雷莱恩。把这只箱子交给她，并告诉她我的任务已经完成。",
  },
  [26932] = {
    ["T"] = "逼近的座狼",
    ["O"] = "杀死5只饥饿的座狼，然后回到提瑞斯法林地中布瑞尔和洛丹伦废墟之间某处巡逻的亡灵卫兵特伦斯那里。",
    ["D"] = "啊，你好，$C。你看起来像那种喜欢替别人解决麻烦、换点零钱的人。在我们西南方，不断有座狼从银松森林越界过来。这里对活狼来说没什么食物，所以它们偶尔会袭击前往幽暗城的货车或路人。我们必须行动起来保护道路。\n\n那就去吧！",
  },
  [26933] = {
    ["T"] = "符文卷轴",
    ["O"] = "阅读符文卷轴，然后与丧钟镇的阿波洛斯·亡射谈谈。",
    ["D"] = "不久前有人走过来，把这卷卷轴交给我。他们显然是我们猎人训练师阿波洛斯·亡射派来的。我想这是给你的。读吧。",
  },
  [26934] = {
    ["T"] = "填充军械库",
    ["O"] = "找回6箱矿石，然后回到布瑞尔的奥利弗·德沃尔那里。",
    ["D"] = "那些该死的人类！他们杀害我们的士兵，唾弃我们的坟墓，现在又夺走了我们的矿洞！我敢说他们正用那里的矿石打造护甲和武器……这绝不能允许！\n\n$N，我需要你去东南方、巴尼尔农场附近的基萨佩尔矿洞，把他们正在开采的矿石带回来一些。如果我们不行动，他们就会用这些矿石打造军备，并带兵袭击布瑞尔！",
  },
  [26935] = {
    ["T"] = "萨匹塔的藏物",
    ["O"] = "在提瑞斯法林地飞艇塔底层找到萨匹塔的藏物。",
    ["D"] = "萨匹塔感谢你给他带来地精陀螺，便把这把钥匙交给了你。他告诉你，它能打开提瑞斯法林地飞艇塔底层的一个藏物箱。\n\n里面会有什么呢？",
  },
  [26939] = {
    ["T"] = "死后安宁",
    ["O"] = "在夜行蜘蛛洞穴矿洞中找到属于约瑟夫·斯特林布劳的东西，用它让他的灵魂安息。然后回到丧钟镇墓地的露娜·斯特林布劳那里。",
    ["D"] = "你好，$N。我想你一定在好奇我为什么跪在这座坟前。这里埋的是我的丈夫约瑟夫。\n\n约瑟夫曾是这里西北方夜行蜘蛛洞穴矿洞里的矿工。他被蜘蛛咬伤，然后死了。瘟疫到来前，我们没能找回他的尸体。\n\n现在约瑟夫的灵魂不得安宁，恐吓那些想夺回矿洞的被遗忘者。他的尸身早已不在，但我仍把这座坟视作属于他。我想，如果你能带回一件他的东西，我们就能把它埋在这里，让他的灵魂安息。你能去矿洞里找找任何可能属于他的东西吗？",
  },
  [26940] = {
    ["T"] = "夺回矿洞",
    ["O"] = "杀死10名血色矿工和3名血色工头，然后回到布瑞尔的弗格斯·基萨佩尔那里。",
    ["D"] = "你听说过基萨佩尔矿洞吗？那是提瑞斯法最富有的矿洞！瘟疫到来前，它由我拥有并维护，但瘟疫一来，血色十字军就自作主张地把矿洞从我们手中\"解放\"了出去。是时候给他们一个教训了。\n\n我要你前往矿洞，为被遗忘者夺回它！沿着布瑞尔出城的南路走，在岔路口左转，继续前进直到抵达巴尼尔农场。农场正南方、沿着丘陵你就能找到矿洞。小心，$N，血色十字军不会不战而退。",
  },
  [26941] = {
    ["T"] = "血色情报",
    ["O"] = "杀死桑德斯中尉，收集密封的血色文件，然后回到布瑞尔的亡灵卫兵塞勒斯那里。",
    ["D"] = "我听说你对付血色十字军颇有成效，$N。如果你想找点活干，我有个任务给你。\n\n远东边是毒蛛峡谷。血色十字军在那里建立了一个小哨站，而我有可靠消息说，他们正在策划某种邪恶行动。我需要知道他们在计划什么，最好的办法就是杀掉他们的中尉，把他的命令带给我。",
  },
  [26942] = {
    ["T"] = "静水鳗鱼",
    ["O"] = "从静水池钓起10条静水鳗鱼，然后回到布瑞尔的杰尼尔·伯奇那里。",
    ["D"] = "即使死了，我们也得吃饭，$N！我猜你已经厌倦了到现在为止只能凑合啃的陈面包。是时候来一顿真正的饭了！\n\n如果你把材料带给我，我能做些好吃的东西。你为什么不去西边的静水池，给我钓些鳗鱼呢？把它们带回来，我会给我们俩做点美味的东西。",
  },
  [26943] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一只巨型夜行蝙蝠。练习你的技能，然后把驯兽棒还给布瑞尔的达娜·沃德。",
    ["D"] = "你好，年轻的猎人。我相信你现在已经准备好学习如何驯服属于自己的野兽，让它在冒险中帮助你。\n\n我们虽然已经死了，但仍能赢得动物的尊重与信任。甚至比某些活人的尊重与信任更容易。拿上这根驯兽棒，我要你出去用它驯服一只巨型夜行蝙蝠。别被这个名字吓到，它们比你以后会见到的其他蝙蝠温顺得多。成功后回来见我。",
  },
  [26944] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一只饥饿的座狼。练习你的技能，然后把驯兽棒还给布瑞尔的达娜·沃德。",
    ["D"] = "你的下一场试炼，我要你驯服一只饥饿的座狼。这样饥饿的野兽应该比吃饱的稍微容易一些，因为它们并不总有力气反抗，可能是因为它们常常被迫吞食邪恶的血肉。它们出没在连接提瑞斯法和银松森林的土地上，就在布瑞尔西南方。",
  },
  [26945] = {
    ["T"] = "驯服野兽",
    ["O"] = "使用驯兽棒驯服一只凶猛的夜行蜘蛛。练习你的技能，然后把驯兽棒还给布瑞尔的达娜·沃德。",
    ["D"] = "最后，到了你最后一场试炼的时候。我们不玩花样：我要直接把你送进蜘蛛巢。你会没事的。大概吧。\n\n前往远东边、靠近山脉的地方，驯服一只凶猛的夜行蜘蛛。注意身后，也小心附近扎营的血色十字军。\n\n祝你好运，$N。",
  },
  [26947] = {
    ["T"] = "猎人之道",
    ["O"] = "与提瑞斯法林地布瑞尔的达娜·沃德谈谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经有足够的本事驾驭野兽，并训练它成为你的伙伴。\n\n你必须去布瑞尔见达娜·沃德。她会引导你走上获得自己宠物的道路。",
  },
  [26948] = {
    ["T"] = "猎人之道",
    ["O"] = "与提瑞斯法林地布瑞尔的达娜·沃德谈谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经有足够的本事驾驭野兽，并训练它成为你的伙伴。\n\n你必须去布瑞尔见达娜·沃德。她会引导你走上获得自己宠物的道路。",
  },
  [26949] = {
    ["T"] = "猎人之道",
    ["O"] = "与提瑞斯法林地布瑞尔的达娜·沃德谈谈。",
    ["D"] = "你好，年轻的猎人。在我看来，你已经有足够的本事驾驭野兽，并训练它成为你的伙伴。\n\n你必须去布瑞尔见达娜·沃德。她会引导你走上获得自己宠物的道路。",
  },
  [27102] = {
    ["T"] = "向高级执行官德灵顿报到",
    ["O"] = "向提瑞斯法林地亡灵壁垒的高级执行官德灵顿报到。",
    ["D"] = "部落的士兵！我们有紧急公文，必须从这里的部队送往艾泽拉斯各地的其他部落前哨。你能胜任这项任务吗？\n\n把这份报告带给提瑞斯法林地亡灵壁垒的高级执行官德灵顿。你需要前往东部王国，沿着幽暗城向东的道路前进，直到抵达他的营地。\n\n迅速出发，带着荣耀！",
  },
  [27915] = {
    ["T"] = "血与荣耀的羁绊",
    ["O"] = "前往布瑞尔附近墓地的喷泉，使用仪式熏香祭拜你的先祖。",
    ["D"] = "你想进一步了解我的人民？我想我也算是个老师，而且比大多数人更愿意教。毕竟，我哪儿也去不了。\n\n如果你真的想理解我的人民，就必须先明白，荣耀是言语、行为和行动的根基。我们的氏族由漫长的荣耀事迹维系在一起。我们明白，自己的行动反映的不只是自己。\n\n让我看看你如何尊敬他人。在你先祖的安息之地使用这份仪式熏香，然后回到我这里。",
  },
  [27615] = {
    ["T"] = "给戈多的委托",
    ["O"] = "药剂师乔汉要你使用炼金术技能制作5瓶狮王之力药剂，并把订单交给提瑞斯法林地布瑞尔西边道路上的戈多。",
    ["D"] = "我忍不住注意到你是个炼金师。我被各种请求围得喘不过气，其中一些低优先级的活不值得我亲自花时间。如果你想练练手，也许不介意接下几份订单？\n\n亡灵卫兵为那个笨重的蠢货戈多征用了五瓶狮王之力药剂。如果你能制作这些药剂，就能在布瑞尔西边道路上的某处找到他。",
  },
  [27616] = {
    ["T"] = "给梅里尔·温德尔的委托",
    ["O"] = "药剂师乔汉要你使用炼金术技能制作5瓶初级活力药水，并把订单交给提瑞斯法林地布瑞尔墓地的梅里尔·温德尔。",
    ["D"] = "在我收到的所有琐碎请求中，这一项最重要。梅里尔·温德尔经常处理天灾石，那东西似乎会消耗她的身体和心智。如果你能制作一些初级活力药水并送过去，会帮梅里尔很大的忙。你可以在附近的墓地找到她。",
  },
  [27665] = {
    ["T"] = "给亡灵卫兵辛默的委托",
    ["O"] = "艾比·温特斯要你使用锻造技能制作1面重铜盾和1件铜质链甲外衣，并把订单交给提瑞斯法林地丧钟镇入口处的亡灵卫兵辛默。",
    ["D"] = "恐怕我没时间聊天——自从血色十字军加强行动以来，涌来的订单太多，我已经落后了。\n\n等等——你似乎自己也有些铁砧上的本事。如果你愿意帮我，可以制作并送一面重铜盾和一件铜质链甲外衣给亡灵卫兵辛默，他驻守在丧钟镇入口外。",
  },
  [27666] = {
    ["T"] = "给亡灵卫兵林奈的委托",
    ["O"] = "艾比·温特斯要你使用锻造技能制作2枚铜质符文戒指，并把订单交给提瑞斯法林地布瑞尔东边道路营地中的亡灵卫兵林奈。",
    ["D"] = "我这里有一份亡灵卫兵林奈的订单，你也许有兴趣替我完成。她想要一对铜质符文戒指。制作完成后，你可以沿着布瑞尔出城的道路向东找到她。如果你走到基萨佩尔矿洞，就走太远了。",
  },
  [28079] = {
    ["T"] = "给杰尼尔·伯奇的委托",
    ["O"] = "杰尼尔·伯奇要你使用烹饪技能制作10条美味小鱼，并把订单交给提瑞斯法林地布瑞尔旅店里的杰尼尔·伯奇。",
    ["D"] = "呼！今天真是忙坏了，我在炉边待了太久，自己连一口东西都没吃。\n\n也许你能帮忙？你煎锅用得还不错，而我很想要一堆烹好的美味小鱼。如果你能处理这事，我就拿一些特别的生烹饪材料跟你交换。成交吗？",
  },
  [28403] = {
    ["T"] = "给康斯坦斯·布里斯博瓦的委托",
    ["O"] = "范斯·阴郁要你使用附魔技能制作1根次级魔法杖，并把订单交给提瑞斯法林地布瑞尔西边炉灰庄园的康斯坦斯·布里斯博瓦。",
    ["D"] = "嗯，你似乎是个附魔师，对吧？炉灰庄园的布里斯博瓦一家报告说，田地里有些小规模天灾亡灵复苏。制作一根次级魔法杖并带给康斯坦斯，好让他们保护自己。这当然是一份委托。",
  },
  [28404] = {
    ["T"] = "给梅里尔·温德尔的委托",
    ["O"] = "范斯·阴郁要你使用附魔技能，用附魔披风 - 初级抗性为提供的1件女祭司披风附魔，并把订单交给提瑞斯法林地布瑞尔墓地的梅里尔·温德尔。",
    ["D"] = "附魔师，如果你愿意，这里有一份委托。布瑞尔墓地那边的梅里尔在为圣骑士处理天灾石。我不知道那些蠢货为什么还要坚持当圣骑士，但至少我们能为她提供一些抵御腐蚀的保护。给这件女祭司披风附上初级抗性，然后带给他们。",
  },
  [28453] = {
    ["T"] = "给托马斯·阿伦托的委托",
    ["O"] = "格雷厄姆·范塔伦要你使用工程学技能制作2把扳手，并把订单交给提瑞斯法林地布瑞尔的托马斯·阿伦托。",
    ["D"] = "自从死亡卫兵开始唤醒丧钟镇的沉睡者以来，我的工程服务就变得非常抢手。抢手到我手头订单已经多得处理不过来。\n\n如果你自己也有些机械天分，也许能帮忙处理一份订单？托马斯·阿伦托维护着穿行提瑞斯法和银松森林的马车，他订了几把扳手，用来替换那些磨损的旧工具。\n\n如果你能制作并送几把给他，我会感谢你的帮助。",
  },
  [28454] = {
    ["T"] = "给亡灵卫兵林奈的委托",
    ["O"] = "格雷厄姆·范塔伦要你使用工程学技能制作20根劣质炸药，并把订单交给提瑞斯法林地幽暗城东边营地中的亡灵卫兵林奈。",
    ["D"] = "我有一份来自亡灵卫兵林奈的订单，她在幽暗城外道路边扎营。城镇更东边的农场最近遭到一些天灾入侵，她想要一些劣质炸药来……做点什么？我不知道，我只负责制作和送货。你能处理这一单吗？",
  },
  [28544] = {
    ["T"] = "给康斯坦斯·布里斯博瓦的委托",
    ["O"] = "法鲁萨要你使用草药学技能采集20份地根草，并把订单交给提瑞斯法林地炉灰庄园的康斯坦斯·布里斯博瓦。",
    ["D"] = "炉灰庄园那位花哨的“服装师”康斯坦斯说她正在研究什么“自然时尚”的胡话。天知道那是什么意思。\n\n她要20份地根草。趁她又开始把苔藓织进披肩之前，把东西带给她，好吗？\n\n我希望“时髦腐朽”这个说法永远别流行起来。",
  },
  [28587] = {
    ["T"] = "给谢尔登·格里姆斯比的委托",
    ["O"] = "亡灵卫兵林奈要你使用制皮技能制作2条皱褶皮短裤，并把订单交给提瑞斯法林地亡灵壁垒的谢尔登·格里姆斯比。",
    ["D"] = "去看看那边的舍琳吧。最近所有新近复苏的被遗忘者都在下订单，她已经忙得不可开交。但我见过你和她谈话，也知道你能接下一些活。所以我现在交给你一项任务。\n\n谢尔登·格里姆斯比动身前往亡灵壁垒，执行寻找伟大游侠纳萨诺斯·玛瑞斯的任务，但我知道他不会成功。为什么？因为他穿着破裤子，撑不过这趟路。所以给他做几条皱褶皮短裤，我们看看他能不能避免在银色黎明面前丢脸。",
  },
  [28588] = {
    ["T"] = "给奥利弗·德沃尔的委托",
    ["O"] = "亡灵卫兵林奈要你使用制皮技能制作1条手工皮带，并把订单交给提瑞斯法林地布瑞尔的奥利弗·德沃尔。",
    ["D"] = "你见过奥利弗·德沃尔吗？他是布瑞尔的武器匠，而且恕我直言，他手艺不错。武器很拿手，衣着一塌糊涂。简而言之，他需要一条腰带。\n\n我们也许是亡灵，但火焰依旧会烧伤人。我可不想看到他因为裤子系不住，结果在熔炉边着火。所以给他做一条手工皮带，我们就能避免事故。",
  },
  [28626] = {
    ["T"] = "给亡灵卫兵林奈的委托",
    ["O"] = "亡灵卫兵林奈要你使用剥皮技能收集20块轻皮，并把订单交给提瑞斯法林地布瑞尔南边营地中的亡灵卫兵林奈。",
    ["D"] = "你，过来。我看见你和剥皮训练师说话了！我需要你的本事。\n\n任何人都能挥刀剥下一张皮，但你能剥得干净吗？稳定吗？带着对野兽应有的尊重吗？\n\n带给我20块切割良好的轻皮。如果你能在不糟蹋毛皮的情况下收集到这些，也许你就准备好正式学习这门手艺了。",
  },
  [28659] = {
    ["T"] = "给亡灵卫兵林奈的委托",
    ["O"] = "弗格斯·基萨佩尔要你使用采矿技能采集20块铜锭，并把订单交给提瑞斯法林地布瑞尔南边营地中的亡灵卫兵林奈。",
    ["D"] = "亡灵卫兵林奈最近征用她看得见的一切，现在又要我交出铜锭，好让死亡卫兵们去做不知什么计划。如果我真交出去，就一点材料都不剩了！\n\n所以我们这样办——你出去给她开采20块铜锭，并告诉他们这些是我出的。然后你可以留下他们给的那点微薄报酬。我的意思是，丰厚报酬。它对你比对我更有用。",
  },
  [28670] = {
    ["T"] = "给暗影牧师范蒂丝的委托",
    ["O"] = "高级执行官德灵顿要你使用采矿技能采集10块真银矿石，并把订单交给提瑞斯法林地亡灵壁垒的暗影牧师范蒂丝。",
    ["D"] = "嗯，我忍不住注意到你是个矿工。正是我要找的人。\n\n暗影牧师范蒂丝需要真银矿石，以继续制作她用于瘟疫之地大锅的中和剂。劳驾，替她取几把回来，好吗？",
  },
  [28701] = {
    ["T"] = "给梅里尔·温德尔的委托",
    ["O"] = "康斯坦斯·布里斯博瓦要你使用裁缝技能制作3件白色亚麻长袍，并把订单交给提瑞斯法林地布瑞尔墓地的梅里尔·温德尔。",
    ["D"] = "梅里尔·温德尔代表我们的圣骑士处理天灾石，那些石头的污秽把她的长袍染得面目全非？这是个词吗？\n\n总之，她需要一些新的白色亚麻长袍，但我一直没时间做。你正好可以练练手，为什么不做几件呢？",
  },
  [28702] = {
    ["T"] = "给贾斯珀·格林的委托",
    ["O"] = "康斯坦斯·布里斯博瓦要你使用裁缝技能制作1双简易的亚麻靴，并把订单交给提瑞斯法林地索利丹农场的贾斯珀·格林。",
    ["D"] = "贾斯珀·格林是传承者的新晋成员，他们派他去调查北岸矿洞。有一个问题——他没有靴子。也没有任何鞋。\n\n贾斯珀也许会因为其他原因无法通过传承者训练，但我可不希望只是因为他穿得不够体面。我一直没时间给他做什么东西，不过你看起来并不忙。为什么不由你来做呢？",
  },
  [26981] = {
    ["T"] = "高年级恶作剧",
    ["O"] = "点燃乌瑟尔之墓、亡灵壁垒和冰风岗的粪便袋。",
    ["D"] = "我差点没通过拉文尼亚人的战斗考试，不过现在我的头发长回来了，他允许我补考。我得靠你来完成这个恶作剧。\n\n我把粪便袋放在了乌瑟尔之墓、冰风岗和亡灵壁垒。去替我把它们点着吧，$N。经典！如果有人问是谁干的，记得告诉他们是我。\n\n除非问的人是老师。那就是你干的。",
  },
  [26217] = {
    ["T"] = "遗失湖底",
    ["O"] = "从洛丹米尔湖底找回扬斯家族传家宝。",
    ["D"] = "阿尔萨斯背叛洛丹伦后，城中爆发了大规模恐慌。我和家人也是许多乘船穿过洛丹米尔湖逃亡的人之一。\n\n我比家里其他人更不幸——我乘上了两条漏水的小船，离瑟伯切尔东边码头不远就翻了。我凡人生命中最后记得的，是一只冰冷的手——比湖水还冷——把我拉上了岸……\n\n总之，我的家族传家宝沉到了湖底，至今仍在那里。如果你愿意找回那些东西，我会付钱酬谢你的服务。",
  },
  [26218] = {
    ["T"] = "红隼号残骸",
    ["O"] = "在瑟伯切尔北边北流海岸的红隼号残骸中寻找一个烟林牧场货运箱。",
    ["D"] = "几个月前，我从烟林牧场订购了一大批制作材料。这些补给由一艘名叫红隼号的船从卡利姆多运来。不幸的是，那艘船在浓雾中搁浅在瑟伯切尔北边的海岸上。\n\n我一直没去查看残骸，因为敌对的狼人占据了北流海岸附近的树林，那艘船就搁浅在那里。如果你能替我从红隼号货舱里取回货运箱，我很乐意分给你里面的一些补给。",
  },
  [26869] = {
    ["T"] = "来世解剖学",
    ["O"] = "瑟伯切尔的药剂师伦弗利尔要你收集1个变异头颅、1副畸形胸腔、2条被啃咬的手臂和2条残缺的腿。",
    ["D"] = "瑟伯切尔需要你的帮助，$N！有一头危险的灰熊正在杀害我们的卫兵。我们的武器和魔法都没能杀死它，所以幽暗城命令我制造一个能击杀这头野兽的憎恶。\n\n憎恶是由变异的肉块缝合而成。不幸的是，我现在没有身体部件了，所以需要你帮忙收集一些。我需要附近狼人身上的一个头颅、豺狼人的胸腔、东边亡灵的两条手臂，以及湖边鱼人的双腿。\n\n你把这些带回来后，我们就能开始施法，把憎恶缝合起来。请快点，免得那头灰熊杀死更多卫兵。",
  },
  [26870] = {
    ["T"] = "来世解剖学",
    ["O"] = "瑟伯切尔的药剂师伦弗利尔要你从安伯米尔的人类身上收集10份浓缩血液。",
    ["D"] = "你带来的身体部件会非常适合制作憎恶，不过我还需要最后一样东西。你外出期间，我不得不用掉最后的人类血液来处理镇上的一个……状况。制作憎恶所需的最后材料，就是新鲜的人类血液。\n\n这一带最好的血来自安伯米尔的人类。沿着这里的道路向南走，然后朝那座城镇向东，就能找到安伯米尔。不过要小心，那些人类上次可是很能打！",
  },
  [26871] = {
    ["T"] = "来世解剖学",
    ["O"] = "召唤并控制憎恶，然后用它杀死瑟伯切尔南边的阿卡吉。任务完成后回到药剂师伦弗利尔那里。",
    ["D"] = "通常我们会在幽暗城制作憎恶，但情况紧急，只能在这里凑合。因为我们没有幽暗城那样齐全的材料，恐怕这个憎恶不会有自己的心智，所以你必须控制它。我已经把法术咒语写下来了。我一完成施法，憎恶的心智就会受你控制。\n\n刚才我收到卫兵的报告，说我们一直在找的那头灰熊出现在这里南边。它叫阿卡吉。\n\n沿着飞行管理员旁边的崎岖小路走，在第一个开口处右转。你会在那里找到那头野兽。动作快点，这个法术只能维持几分钟！",
  },
  [26872] = {
    ["T"] = "鸦爪脓液",
    ["O"] = "把鸦爪脓液样本带给瑟伯切尔的药剂师伦弗利尔。",
    ["D"] = "你在这个亡灵身上发现了一个样本瓶，里面装着一种咸涩灰色物质的残留物，类似芬里斯岛腐皮怪身上的脓液。瑟伯切尔的药剂师伦弗利尔也许会对此感兴趣。",
  },
  [26873] = {
    ["T"] = "失踪的新晋成员",
    ["O"] = "在安伯米尔寻找凯文·温特。",
    ["D"] = "很抱歉打扰你，$C，但我需要帮助。\n\n我是银松森林的外来者，本该在瑟伯切尔与一名传承者新兵会面，但他还没有到。他留给旅店老板的便条说，见面前要去安伯米尔附近快速查看一下。旅店老板说安伯米尔在这里南边，但我不想离开去找他，结果他又在我离开时赶到，让情况变得更糟。你愿意去找找他吗？他叫凯文·温特。",
  },
  [26874] = {
    ["T"] = "失踪的新晋成员",
    ["O"] = "杀死法师达诺德，把安伯米尔牢笼钥匙带给凯文·温特。",
    ["D"] = "这里有个管事的人——我想他叫达诺德。他有这座牢笼的钥匙。如果你愿意说服他把钥匙交给你，我很想离开这个笼子。",
  },
  [26875] = {
    ["T"] = "失踪的新晋成员",
    ["O"] = "回到瑟伯切尔，与贤者绿角谈谈。",
    ["D"] = "偷听这些法师让我有了一些有趣的发现。因此，在我去瑟伯切尔见贤者绿角之前，还有一件小差事想办。但如果你愿意先回去告诉她我很快就到，我会很感激。",
  },
  [26876] = {
    ["T"] = "感兴趣的典籍",
    ["O"] = "从安伯米尔北部或博伦的巢穴附近的达拉然巫师身上收集5本旧典籍。",
    ["D"] = "我本来有个任务想交给我的新学徒，但你也许更适合完成它。\n\n达拉然的大部分知识都随着城市一同被毁，但他们的一些巫师显然逃到了安伯米尔。如果他们带着来自那座城市的旧典籍，我希望收集几本。\n\n这样的知识应该与所有人共享，而不是被联盟巫师藏起来。",
  },
  [26877] = {
    ["T"] = "感兴趣的典籍",
    ["O"] = "杀死4名病弱难民，并从格雷迈恩之墙的难民身上收集5本吉尔尼斯典籍。",
    ["D"] = "我听说，在天灾军团穿过洛丹伦后幸存下来的吉尔尼斯人聚集在银松森林南部边境的格雷迈恩之墙。他们因为被怀疑携带瘟疫而被拒绝进入自己的家园。\n\n就像牧羊人面对病羊一样，有时必须淘汰少数，才能拯救整体。如果他们是瘟疫携带者，我们最好在他们进一步传播疾病之前消灭他们。\n\n这些难民也可能带着一些吉尔尼斯的著作，如果有的话，我希望收集起来。",
  },
  [26878] = {
    ["T"] = "感兴趣的典籍",
    ["O"] = "从银松森林南部的废弃房屋中收集《历史理论》。",
    ["D"] = "还有最后一本书想请你去找，$C。\n\n这里的卫兵告诉我，一位著名的洛丹伦历史学家在银松南部、格雷迈恩之墙东边有一间小屋。那间小屋里也许有一本《历史理论》。这部著作讨论的是……算了，我怀疑你并不关心细节。如果你能找到去那里的路，把书取回来，可以吗？\n\n哦，我还要提醒你，卫兵反复强调要小心。有人在小屋周围看到过一头强大的狼人。你最好招募几个朋友同行。",
  },
  [26928] = {
    ["T"] = "阿鲁高的伏击",
    ["O"] = "在瑟伯切尔北边伏击地点附近的桥下寻找商队成员的任何踪迹。",
    ["D"] = "这支商队车队原本正前往幽暗城，却遭到那些名叫狼人的邪恶野兽袭击。我赶到时，卫兵和工人已经全被拖进树林——或者更糟。\n\n狼人正在搜查商队里的某样东西，我用尽全力才把它们击退。替我四处看看，找找它们为何发动袭击的原因。爪痕和足印明显通向附近桥下。",
  },
  [26929] = {
    ["T"] = "阿鲁高的伏击",
    ["O"] = "收集8份萨斯蘑菇孢子和4夸脱座狼血，帮助亡灵卫兵基萨佩尔治疗一匹受伤的马。",
    ["D"] = "以洛丹伦之名，那些可怜的亡灵卫兵到底发现了什么？我们必须尽快把它带回瑟伯切尔，这样我才能决定下一步该怎么办。那个箱子太重，搬不动。我们需要一匹坐骑。\n\n这些马伤得几乎站不起来，但我们必须用其中一匹把这个箱子带回去。给我从附近水边带些萨斯蘑菇孢子，再从这里西北方的座狼身上取4夸脱血，我看看能不能把一匹马救回来。",
  },
  [26930] = {
    ["T"] = "阿鲁高的伏击",
    ["O"] = "把商队剩余的补给带给瑟伯切尔的军需官科尔。",
    ["D"] = "我要把这个箱子赶紧送到这里西南方的瑟伯切尔，交给军需官科尔保管。\n\n把我设法从这支车队里收集到的最后一批补给带来，在那里和我会合。它们在瑟伯切尔会比在路边腐烂更有用。",
  },
  [27617] = {
    ["T"] = "给亡灵卫兵基萨佩尔的委托",
    ["O"] = "药剂师伦弗利尔要你使用炼金术技能制作5瓶次级治疗药水，并把订单交给银松森林瑟伯切尔北边道路上的亡灵卫兵基萨佩尔。",
    ["D"] = "我是个忙人，还有比制作药剂和药水重要得多的事要占用我的时间。尽管如此，我还是希望帮助同胞被遗忘者。我听说瑟伯切尔北边的道路上发生了事故。如果你能制作一些次级治疗药水，并把它们送给坠毁地点的亡灵卫兵基萨佩尔，我没法为他做更多事的良心会好受些。",
  },
  [27618] = {
    ["T"] = "给基利恩·萨纳森的委托",
    ["O"] = "药剂师伦弗利尔要你使用炼金术技能制作5瓶黑口鱼油，并把订单交给银松森林北流海岸的基利恩·萨纳森。",
    ["D"] = "说到帮忙……还有另一个人一直在寻求炼金师的协助。你可以在粘丝洞外、海岸上方北流海岸的营地找到基利恩·萨纳森。他一直在找人给他做几瓶黑口鱼油，而，呃，我可能把他给我的鱼用在别的地方了。如果你有兴趣，我肯定他会付钱给你。",
  },
  [27667] = {
    ["T"] = "给塞巴斯蒂安·米洛奇的委托",
    ["O"] = "塞巴斯蒂安·米洛奇要你使用锻造技能制作5块粗制砂轮，并把订单交给银松森林瑟伯切尔的塞巴斯蒂安·米洛奇。",
    ["D"] = "向你致意，$C。很高兴镇上有位铁匠。我需要一批新的粗制砂轮，好让我们的武器和护甲不受锈迹和污垢侵扰。如果你能制作并送五块给我，我会很感激。",
  },
  [27668] = {
    ["T"] = "给兰妮·尤瑞克的委托",
    ["O"] = "塞巴斯蒂安·米洛奇要你使用锻造技能制作1件铜质符文胸甲和1副铜质符文护腕，并把订单交给银松森林伊瓦农场的兰妮·尤瑞克。",
    ["D"] = "如果你还想找活干，伊瓦农场那边的兰妮·尤瑞克需要一件铜质符文胸甲和一副铜质符文护腕，用来替换她兄弟损坏的护甲。如果你能制作这些物品，就把它们送到那里交给兰妮。伊瓦农场在瑟伯切尔北边。",
  },
  [28455] = {
    ["T"] = "给萨姆·尤瑞克的委托",
    ["O"] = "纪尧姆·索鲁伊要你使用工程学技能制作2个粗制瞄准镜，并把订单交给银松森林奥森农场的萨姆·尤瑞克。",
    ["D"] = "我有权征用亡灵哨兵所需的物品。你是工程师，对吧？我需要一个给萨姆·尤瑞克用的粗制瞄准镜，他正在奥森农场侦察。那个位置能让他很好地狙击任何从南边袭击瑟伯切尔的东西。如果你能制作几个并送给他，我们会给你报酬。",
  },
  [28456] = {
    ["T"] = "给兰妮·尤瑞克的委托",
    ["O"] = "纪尧姆·索鲁伊要你使用工程学技能制作1副灵巧老虎护目镜，并把订单交给银松森林路上的伊瓦农场兰妮·尤瑞克。",
    ["D"] = "作为亡灵哨兵的征用官，我还想请你给兰妮·尤瑞克制作一副灵巧老虎护目镜。她独自巡逻从瑟伯切尔向北延伸的道路，那副护目镜能保护她的眼睛免受泥污和烈日侵扰。如果你愿意把它们送给她，我会很感激。",
  },
  [28487] = {
    ["T"] = "给兰妮·尤瑞克的委托",
    ["O"] = "高级执行官哈德瑞克要你使用急救技能制作20条厚亚麻绷带，并把订单交给银松森林北部农场的兰妮·尤瑞克。",
    ["D"] = "如果你要出去寻找那些失踪的亡灵哨兵，就该考虑为他们可能需要的东西做准备。\n\n我说的是厚亚麻绷带，$C。你应该赶制一叠，在寻找尤瑞克姐弟时带上。",
  },
  [28513] = {
    ["T"] = "给基利恩·萨纳森的委托",
    ["O"] = "基利恩·萨纳森要你使用钓鱼技能收集20条新鲜的滑皮鲭鱼，并把订单交给银松森林北流海岸的基利恩·萨纳森。",
    ["D"] = "很多人说得像自己很懂钓鱼，其实不过是吹牛。言语对海浪毫无意义。算数的是渔获。\n\n觉得自己有这个本事吗？带给我20条新鲜的滑皮鲭鱼，证明你不只是鱼饵和虚张声势。",
  },
  [28545] = {
    ["T"] = "给雷欧·萨恩的委托",
    ["O"] = "药剂师伦弗利尔要你使用草药学技能采集20株魔皇草，并把订单交给银松森林通往希尔斯布莱德道路南边营地中的雷欧·萨恩。",
    ["D"] = "我从你膝盖上的草渍看得出你是草药师。我不知道人们怎么会把炼金师和草药师混为一谈，更妙的是，他们为什么会以为我有时间处理他们那些微不足道的草药小愿望。幸运的是，你看起来既有本事，也有时间处理这个请求。\n\n把20株魔皇草带给那个附魔师——雷欧·萨恩，我想是这个名字——他在通往希尔斯布莱德的道路南边扎了营。",
  },
  [28589] = {
    ["T"] = "给贤者绿角的委托",
    ["O"] = "贤者绿角要你使用制皮技能制作2双黑皮长靴，并把订单交给银松森林瑟伯切尔的贤者绿角。",
    ["D"] = "你好，$R。我和我的朋友茉拉都不是这一带的人。我想这很明显。\n\n我们没料到银松森林会这么……寒冷。尤其是夜里。如果你有这门手艺，我想请你给我制作几双黑皮长靴。这样我在这里等待学徒时，蹄子就不会冻僵。",
  },
  [28590] = {
    ["T"] = "给茉拉·符文图腾的委托",
    ["O"] = "贤者绿角要你使用制皮技能制作1件优质皮披风，并把订单交给银松森林瑟伯切尔的茉拉·符文图腾。",
    ["D"] = "我站在这里冻得蹄子都快掉了，而从海上吹来的冷风像女妖尖啸一样穿过丘陵谷地，茉拉也被冻得发抖。\n\n你能不能为她制作一件优质皮披风，既挡风又挡雨？",
  },
  [28660] = {
    ["T"] = "给塞巴斯蒂安·米洛奇的委托",
    ["O"] = "约翰·福赫特要你使用采矿技能采集5块银锭，并把订单交给银松森林瑟伯切尔的塞巴斯蒂安·米洛奇。",
    ["D"] = "啊，矿工。我有份活给你。\n\n那边的塞巴斯蒂安和我，嗯，我们合不来。自从跳蚤和蜱虫那件事之后，这座墓穴已经容不下我们两个了，但为了支援亡灵哨兵，我们又必须待在这里。\n\n总之，带5块银锭给塞巴斯蒂安。我有一份委托需要他在瑟伯切尔处理，需要恰到好处的光泽，而银正合适。由你传话，他会更容易接受。",
  },
  [28703] = {
    ["T"] = "给基利恩·萨纳森的委托",
    ["O"] = "安德莉亚·博因顿要你使用裁缝技能制作4件灰色毛纺衬衣，并把订单交给银松森林北流海岸的基利恩·萨纳森。",
    ["D"] = "基利恩已经在北流海岸钓了好几周鱼，每次回来都浑身湿透。他不肯承认，但他那件旧衬衣已经洞比布还多了。\n\n如果你能缝几件灰色毛纺衬衣，就该带给他。我本想自己做，但我怀疑他不会乐意收我的。说来话长。",
  },
  [28704] = {
    ["T"] = "给莉蕾的委托",
    ["O"] = "安德莉亚·博因顿要你使用裁缝技能制作2双毛纺靴，并把订单交给银松森林瑟伯切尔南边营地中的莉蕾。",
    ["D"] = "莉蕾是个怪人，即使在被遗忘者里也算怪。她涉猎附魔，却不穿鞋就在森林里奔跑。\n\n我有很多本事，但做鞋不是其中之一。如果你有这方面的才华，也许可以送她一双毛纺靴。我们被遗忘者必须互相照应。",
  },
  [28705] = {
    ["T"] = "给沙罗萨斯船长的委托",
    ["O"] = "哈莉娅·白行者要你使用裁缝技能制作1件珍珠扣披风，并把订单交给银松森林棘齿城的沙罗萨斯船长。",
    ["D"] = "自从部落建立十字路口以来，我们接到的订单多得一个月都做不完。如果你有裁缝技能，我们可以用你的帮助清理这批积压。\n\n沙罗萨斯船长已经停靠在棘齿城，并要求一件新的珍珠扣披风。这应该是个很适合你练手的活，对吧，$N？",
  },
  [26345] = {
    ["T"] = "好消息",
    ["O"] = "在棘齿城与卡莱塔卡·冬崖会面，讨论诺甘农圆盘。",
    ["D"] = "我有个好消息，$N！探险者协会成功解读了诺甘农圆盘上的一些符文。奇怪的是，它们与古代牛头人语中使用的符文很相似。\n\n我们找到了一位愿意与我们合作解读符文的牛头人联系人，并希望你和她合作。她同意从雷霆崖前往棘齿城与你会面。去那里的旅店见卡莱塔卡·冬崖，我们就离开启奥丹姆更近一步了！",
  },
  [26346] = {
    ["T"] = "激动人心的发现",
    ["O"] = "在棘齿城与卡莱塔卡·冬崖会面，讨论诺甘农圆盘。",
    ["D"] = "不久前，探险者协会得到了一件名为诺甘农圆盘的神器。我们一直试图从圆盘中获取信息，而要继续推进，需要一位精通牛头人语的专家。\n\n我们找到了一位愿意与我们合作的牛头人联系人，需要一名信使去见她。我听说你在镇上颇受推荐，所以想请你去棘齿城的断桅酒馆见卡莱塔卡·冬崖。如果我们的判断没错，这些圆盘可能会引向开启古代设施奥丹姆！",
  },
  [26347] = {
    ["T"] = "好消息",
    ["O"] = "在棘齿城和费伍德森林之间的道路上找到卡莱塔卡·冬崖。",
    ["D"] = "老实说，和一个$R面对面见面有点让人紧张，但我母亲从不是那种会让阵营恩怨妨碍追求知识的人。\n\n不过她来这里的路上很担心，因为她觉得有可疑的人在跟踪我们。她决定不在这里等了，要我告诉你她前往费伍德森林了。既然她是步行，我相信你能追上她。\n\n我很担心她，$R，但我相信我母亲能照顾好自己。",
  },
  [26348] = {
    ["T"] = "坏消息",
    ["O"] = "带着坏消息回到棘齿城的穆林·冬崖那里。",
    ["D"] = "卡莱塔卡·冬崖的尸体上所有值钱物品都被洗劫一空。她似乎遭到了伏击，因为手上没有防御伤。喉咙上整齐的一刀，说明杀手效率极高。\n\n你正要离开时，看见附近泥地里有一个奇怪的蹄印。你记住了那个蹄印的细节，知道自己必须回到棘齿城的穆林·冬崖那里，告诉他，他母亲怀疑自己被跟踪看来是正确的——而这对所有人都是灾难。",
  },
  [26354] = {
    ["T"] = "激动人心的发现",
    ["O"] = "在棘齿城与赫德里格·铁石会面，讨论诺甘农圆盘。",
    ["D"] = "不久前，传承者得到了一件名为诺甘农圆盘的神器。我们一直试图从圆盘中获取信息，而要继续推进，需要一位精通矮人语的专家。\n\n我们找到了一位愿意与我们合作的矮人联系人，需要一名信使去见他。我听说你在镇上颇受推荐，所以想请你去棘齿城的断桅酒馆见赫德里格·铁石。如果我们的判断没错，这些圆盘可能会引向开启古代设施奥丹姆！",
  },
  [26355] = {
    ["T"] = "好消息",
    ["O"] = "在棘齿城和费伍德森林之间的道路上找到赫德里格·铁石。",
    ["D"] = "老实说，和一个$R面对面见面有点让人紧张，但我老爹从不是那种会让阵营恩怨妨碍追求知识的人。\n\n不过他来这里的路上很担心。他觉得有人在监视并跟踪我们，所以独自出发了。他要我告诉你，他前往费伍德森林了。既然他是步行，我相信你能追上他。\n\n我很担心他，$R，但我相信我老爹能照顾好自己。",
  },
  [26356] = {
    ["T"] = "坏消息",
    ["O"] = "带着坏消息回到棘齿城的妮莉·铁石那里。",
    ["D"] = "赫德里格·铁石的尸体上所有值钱物品都被洗劫一空。他似乎遭到了伏击，因为手上没有防御伤。喉咙上整齐的一刀，说明杀手效率极高。\n\n你正要离开时，看见附近泥地里有一个脚印。你记住了那个脚印的细节，知道自己必须回到棘齿城的妮莉·铁石那里，告诉她，她父亲怀疑自己被跟踪看来是正确的——而这对所有人都是灾难。",
  },
  [26467] = {
    ["T"] = "那些未能寻回者",
    ["O"] = "在棘齿城四处打听那位圣骑士的消息。",
    ["D"] = "我以前听说过你，$N。即使在死亡中，你也再次为白银之手骑士团赢得了名声。我们也许被生者排斥，但我们的许多目标与那些从天灾中幸存下来的圣骑士一致。\n\n我的一位老朋友给我写了一封信，询问我对联盟远征卡利姆多一事知道些什么。她告诉我，有一名人类圣骑士正付钱打听狮心公爵的消息，并会前往棘齿城亲自调查。我很遗憾此时无法协助，但如果这位圣骑士正在追查已故的狮心公爵，我相信我们有责任尽力相助。去棘齿城打听这位圣骑士。",
  },
  [26596] = {
    ["T"] = "魔法坠饰",
    ["O"] = "把魔法坠饰带给马尔冯·铆钉搜寻者，在塔纳拉辛？坦克里斯？塔纳拉尼萨尼？差不多那地方！",
    ["D"] = "总有一天我会亲自到野外去发现东西，但现在我只能在棘齿城这里看着马尔冯的工坊。不过他肯定很想看看你手里的这个护符。他喜欢带奇怪刻痕的旧东西。这算是他的专长。\n\n你可以往南找他，远到需要坐飞艇才能到的地方。塔纳拉辛？坦克里斯？塔纳拉尼萨尼？差不多那地方！",
  },
  [27060] = {
    ["T"] = "以太波澜",
    ["O"] = "前往贫瘠之地的甜水绿洲，杀死唤风者莱杰斯和先遣骑米辛。",
    ["D"] = "所以，大酋长反对我的氏族与几个流离失所的术士合作？你没有问我们为什么这么做，但我会告诉你。\n\n你当然知道，牛头人曾经被半人马猎杀。许多代人的知识都在他们的掠食下丧失了。我不会容忍他们共享这片土地。你以为我为什么支持与被遗忘者结盟？他们的瘟疫是一种非常有趣的武器……\n\n如果你想让我的氏族停止与燃刃合作，那就给我一个相当的工具。去贫瘠之地杀死唤风者莱杰斯和先遣骑米辛。他们碍我的事已经太久了。",
  },
  [27127] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "去棘齿城与M.斯宾塞·铜栓谈谈，商议在烟林牧场和黑木村之间开辟贸易路线。",
    ["D"] = "老实说，$N……我能叫你$N吗？老实说，我只是对那家伙客气一下。黑木收集的那些东西，不是我平常会碰的货。\n\n不过既然你在这里，又愿意帮忙，那我告诉你吧。我表亲在南边有份好差事，替烟林牧场干活。他们以各种古怪玩具和小玩意闻名。也许黑木做的那些雕刻图腾会在冬幕节卖得不错？或者他们也有鲜鱼市场？我不知道。\n\n你可以在棘齿城烟林牧场办事处外找到我表亲，他在那里叫卖烟林的货物。名字叫M.斯宾塞·铜栓。",
  },
  [27165] = {
    ["T"] = "燃刃徽记",
    ["O"] = "从燃刃成员身上收集10枚燃刃徽记，然后回到十字路口的索克那里。",
    ["D"] = "你肯定听说过燃刃吧？那是一个自燃烧军团到来后就一直祸害艾泽拉斯的残忍恶魔邪教。他们入侵了贫瘠之地，而且已经洗劫了一个小村庄。\n\n我的首要任务是保护这片土地的安全，所以出去把他们从这里清除掉！带回一些他们的徽记戒指，作为他们覆灭的证据。我的斥候告诉我，燃刃在鬼雾峰扎营，那是一片离这里西北方相当远的山脉。",
  },
  [27166] = {
    ["T"] = "仇恨吞噬",
    ["O"] = "带回10颗科卡尔人头，交给十字路口的曼科里克。",
    ["D"] = "你知道时时刻刻感到不安是什么滋味吗？不知道纳迪娅的命运如何？也许你知道，也许不知道，但有一件事我很确定……我要复仇。我要见血。科卡尔必须死！\n\n我本想亲自去，但逃跑时伤了腿。替我去吧，$r，把他们的头带回来，让我知道事情已经完成。",
  },
  [27168] = {
    ["T"] = "战斗中失踪",
    ["O"] = "查明纳迪娅发生了什么，并把你的发现报告给十字路口的曼科里克。",
    ["D"] = "他们在深夜里来了，一大群冲过来。半人马是邪恶又可怕的生物。我逃离村庄，来到这里寻求庇护。我的妻子纳迪娅就没那么幸运了。\n\n他们把她带到南边某个营地，靠近死水绿洲。我担心最坏的结果，$N，但我必须知道。请去看看能否在他们的帐篷里找到线索，如果可以，就把她带回来。路上遇到的半人马，一个不留。",
  },
  [27170] = {
    ["T"] = "非我所能",
    ["O"] = "在贫瘠之地追踪辛吉尔。",
    ["D"] = "我们已经没有更多办法找到她了，$n，必须寻求外援。我仍相信她还活着，因为你询问的俘虏说她逃脱了。\n\n我听说有一位名叫辛吉尔的萨满曾帮助过这一带的人。他住在这座镇子北边一点，靠近道路岔口。去吧，和他谈谈，看看他能否帮助我们找到纳迪娅。",
  },
  [27171] = {
    ["T"] = "取回宝珠",
    ["O"] = "杀死大法师科加尔，把他的宝珠带给贫瘠之地的辛吉尔。",
    ["D"] = "没错，我能帮你，朋友，但我们需要一些东西来开始仪式，好集中力量找出纳迪娅的位置。唯一强大到足以找到她的东西就在北方城堡。\n\n那里有个强大的法师，名叫大法师科加尔。他的宝珠是他力量的来源，受到严密保护。如果我们要找到纳迪娅，就需要那颗宝珠。\n\n你会在棘齿城南边找到北方城堡，朋友。但你最好小心，那些卫兵可不喜欢陌生人。",
  },
  [27172] = {
    ["T"] = "灌注宝珠",
    ["O"] = "将5份闪电精华吸入科加尔的宝珠，然后回到贫瘠之地的辛吉尔那里。",
    ["D"] = "这就是我们要找的宝珠，朋友。但现在有了宝珠，我们还需要把自然之力灌注进去。远在南边，过了十字路口，有成群看起来像科多兽的雷霆蜥蜴。\n\n我们需要汲取它们的精华，灌注进宝珠……在它们活着的时候力量最强。完成之后回到我这里，我们就能完成仪式。",
  },
  [27173] = {
    ["T"] = "向曼科里克报告",
    ["O"] = "带着纳迪娅位置的消息向十字路口的曼科里克报告。",
    ["D"] = "我们找到她了，朋友！记住，在甜水绿洲西南方有一个钢鬃村。你会在那里找到她。\n\n不要浪费时间，去把消息告诉曼科里克！另外，如果十字路口还有其他人需要帮助，请让他们来找我。",
  },
  [27174] = {
    ["T"] = "寻找纳迪娅",
    ["O"] = "在贫瘠之地的钢鬃村找到纳迪娅。",
    ["D"] = "我们离找到她已经很近了，$n。我熟悉辛吉尔告诉你的那片区域。那里叫阿迦玛戈，住着许多钢鬃野猪人。\n\n你会在甜水绿洲西南方找到它。我指望你了，请把我心爱的纳迪娅带回我身边。",
  },
  [27175] = {
    ["T"] = "打开牢笼",
    ["O"] = "收集戈塔克的钥匙，并在贫瘠之地释放笼中的纳迪娅。",
    ["D"] = "你来了我真高兴！我被困在这里很多天了……迷失……等待。但我想我知道出去的办法！\n\n我不时观察他们的首领，他们叫他戈塔克。他总是从这里西北方的一个钢鬃村过来。我敢打赌他有我笼子的钥匙！但要小心，他看起来比其他人强壮得多……你可能需要几个朋友来对付他。",
  },
  [27176] = {
    ["T"] = "好消息",
    ["O"] = "告诉十字路口的曼科里克，纳迪娅已经逃脱。",
    ["D"] = "感谢你的所有帮助，$N。我欠你一条命。我知道回家的路，但你告诉我那里已经被毁了。我想，在我们建起新家之前，我必须在十字路口避难。\n\n你先走一步，把发生的一切告诉曼科里克。我知道他一定在不知我命运的煎熬中快要死去了。我马上跟上你！",
  },
  [27177] = {
    ["T"] = "行动：北方城堡",
    ["O"] = "从北方城堡偷走杂项护甲箱，并把它带给十字路口的索克。",
    ["D"] = "嘘！你，对，就是你！你看见我们前面的那座城堡了吗？那些塞拉摩卫兵把它当作补给前哨。我观察他们好几天了，担心他们的补给已经足够对十字路口发动攻击！\n\n我要你进去偷走他们的护甲。你大概能在他们的铁匠铺里找到它。把它带回十字路口交给索克，这样我们就能给士兵使用。",
  },
  [27185] = {
    ["T"] = "来自血腥徽记的补给",
    ["O"] = "把5枚血腥徽记带给棘齿城的莫里森·铜栓。",
    ["D"] = "地精贸易财团在部落和联盟的紧张关系中保持中立，但我对你们互相战斗时偶尔获得的血腥徽记很感兴趣。有些账外的“企业家”愿意用稀有材料交换这些血腥徽记。\n\n我可不打算冒着自己的皮去弄一些，但如果你愿意，那会让我刮目相看。",
  },
  [27186] = {
    ["T"] = "来自东瘟疫之地的补给",
    ["O"] = "为棘齿城的莫里森·铜栓占领东瘟疫之地的一座哨塔。",
    ["D"] = "我们才刚开始探索东瘟疫之地那些变异动植物如何才能发挥最大效用。那里很危险，我们在艾泽拉斯任何地方都没有比那里损失更多的探员。\n\n也许你可以通过控制银色黎明在那里建立的一座哨塔，让那里变得更安全些？这样我就能告诉我的探员，如果有需要，那里是个安全港。",
  },
  [27195] = {
    ["T"] = "直取利齿",
    ["O"] = "收集10颗乱齿土狼牙齿，并把它们带回陶拉祖营地的卡莉娅·风剪。",
    ["D"] = "你好，$c，到现在你一定知道艾泽拉斯是个致命的地方。想要无畏前行，就需要一把强韧结实的武器。\n\n我需要本地乱齿土狼的牙齿来给我的部族制作武器。我还不够强大，没法自己去和它们战斗，但我可以和你做个交易。带回一些它们的牙齿，我也会给你打造一件武器。",
  },
  [27196] = {
    ["T"] = "科卡尔报告",
    ["O"] = "把科卡尔报告带给十字路口的索克。",
    ["D"] = "这似乎是一张用科卡尔文字潦草写成的便条，你看不懂。把这份报告带给十字路口的索克应该是个好主意。",
  },
  [27197] = {
    ["T"] = "商人的女儿号",
    ["O"] = "把宝箱带回棘齿城的可怜的维尼克斯那里。",
    ["D"] = "嘿，朋友，你想赚钱吗？这一带日子不好过，但我听到一个传闻，说这座城外海岸底下有一艘沉船，名叫商人的女儿号。\n\n残骸里有些宝藏。谁知道那艘船的船员把什么东西放在里面！我不知道，但我知道前几晚我从一个醉水手手里赢来了宝箱钥匙。把宝藏带回来，我会分你一点。",
  },
  [27199] = {
    ["T"] = "失踪的传承者",
    ["O"] = "带着坏消息回到陶拉祖营地的贤者鹿蹄那里。",
    ["D"] = "你环顾残骸。骨头刚被啃得干干净净。箱子被撬开并洗劫一空。\n\n泥土里有一截断裂的野猪人獠牙。还有几支箭和一把丢弃的匕首，看起来也是野猪人制品。你捡起匕首作为证据，准备在带去坏消息时交给贤者鹿蹄。",
  },
  [27201] = {
    ["T"] = "三城卷轴",
    ["O"] = "潜入剃刀沼泽，从野猪人手中找回三城卷轴。",
    ["D"] = "三城卷轴是一组三卷卷轴，记载了雷霆崖、烈日石居和莫沙彻营地的建立。这是这些传说第一次从最初的口述历史被写下来。我们必须找回它们。\n\n我有个可怕的怀疑：这些卷轴已经被当作战利品送往剃刀沼泽的野猪人据点。你必须进入那里，把它们找回来！",
  },
  [27202] = {
    ["T"] = "黑曜石圣物",
    ["O"] = "把黑曜石圣物带给贫瘠之地的加恩·石塔。",
    ["D"] = "勘探员的随身物品中有一件奇怪的圣物，与巴尔莫丹挖掘场遗迹的风格格格不入。它由一种黑色材料制成，仿佛会吞噬周围的光。\n\n也许加恩·石塔会知道该如何处理这个不祥的发现？",
  },
  [27245] = {
    ["T"] = "恐怖图腾的背叛",
    ["O"] = "在伊索克营地或裂蹄堡杀死8名加拉克唤风者、8名加拉克掠夺者和8名加拉克虐待者。",
    ["D"] = "我知道你看着我时看到了什么，$C。你认为我愿意与萨尔的敌人合作，就是背叛了部落。你的世界非黑即白，而我的世界有许多灰色。\n\n想想萨尔想要向那些诱骗他族人堕落并被奴役的人复仇。好吧，半人马就是我的燃烧军团。我一生的事业，就是确保我们永远不再被那些憎恶之物猎杀。\n\n为此，我希望你前往千针石林，杀死许多半人马。你会在伊索克营地和裂蹄峭壁找到他们。\n\n从贫瘠之地沿路向南前往千针石林。半人马营地依附在峡谷北壁上。",
  },
  [27280] = {
    ["T"] = "必须除掉艾尔哈特",
    ["O"] = "找到尘泥沼泽和贫瘠之地边境上的艾尔哈特要塞，并杀死其中的指挥官艾尔哈特。",
    ["D"] = "我们从陶拉祖营地收到了令人不安的消息。一群联盟逃兵占据了尘泥沼泽和贫瘠之地边境上的一座要塞，正在偷取我们的补给。我在联盟中的……联系人也同意，我们必须在有人误解局势、这些逃兵引发与部落的公开战争之前清除他们。\n\n然而，他们武装精良，并在要塞中深深扎根。他们的首领是一位无畏的指挥官，名叫艾尔哈特。深入要塞找到他并杀死他，终结这场严峻局势。",
  },
  [27281] = {
    ["T"] = "必须除掉艾尔哈特",
    ["O"] = "找到尘泥沼泽和贫瘠之地边境上的艾尔哈特要塞，并杀死其中的指挥官艾尔哈特。",
    ["D"] = "我们从斥候那里收到了令人不安的消息：一群新的逃兵占据了尘泥沼泽和贫瘠之地边境上的一座要塞。我们必须在有人误解局势，以为我们正武装准备与部落全面开战之前清除他们。\n\n这些逃兵武装精良，并在要塞内深深扎根。他们的首领是一位无畏的指挥官，名叫艾尔哈特。深入要塞找到他并杀死他，终结这场严峻局势。",
  },
  [27284] = {
    ["T"] = "逃离艾尔哈特",
    ["O"] = "护送安娜·卡斯皮安逃出艾尔哈特要塞，然后向塞拉摩旅店里她的朋友珍妮报告她已逃脱。",
    ["D"] = "我和丈夫杰拉德带着新鲜补给，从棘齿城前往塞拉摩时，遭到这些恶棍伏击。我从他们胸前的纹章看得出来，他们绝不是塞拉摩的朋友。\n\n我可怜的丈夫试图捍卫普罗德摩尔的荣誉，然后……看看我身后，你就知道结果了……\n\n我的脚踝严重扭伤，需要帮助才能离开这里。你愿意帮我吗，$n？",
  },
  [27285] = {
    ["T"] = "逃离艾尔哈特",
    ["O"] = "护送卡雅·怒图腾逃出艾尔哈特要塞，然后通知陶拉祖营地旅店中她的朋友卡莉娅，卡雅已经逃脱。",
    ["D"] = "我和丈夫通加从乱风岗前往陶拉祖营地时，遭到这些恶棍伏击。\n\n我从他们胸前的纹章看得出来，他们绝不是部落的朋友。\n\n我可怜的丈夫试图保护我们，然后……他们把他铺在那片园地里当肥料……！\n\n我的脚踝严重扭伤，需要帮助才能离开这里。你愿意帮我吗，$n？",
  },
  [27287] = {
    ["T"] = "击倒他们",
    ["O"] = "攻击艾尔哈特要塞，杀死8名逃兵荣誉卫士和8名逃兵医师。",
    ["D"] = "尘泥沼泽和贫瘠之地边境上的一座旧要塞，被一群由艾尔哈特率领的联盟逃兵占据了。如果我们只是斩下他的头，队伍中很快会有新的领袖冒出来。\n\n我们必须全力攻击这些逃兵，不仅打击首脑，也要斩断四肢。除掉他可怕的荣誉卫士和医师，让他们无法从这一击中恢复。",
  },
  [27288] = {
    ["T"] = "击倒他们",
    ["O"] = "攻击艾尔哈特要塞，杀死8名逃兵荣誉卫士和8名逃兵医师。",
    ["D"] = "尘泥沼泽和贫瘠之地边境上的一座旧要塞，被一群由艾尔哈特率领的联盟逃兵占据了。如果我们只是斩下他的头，队伍中很快会有新的领袖冒出来。\n\n我们必须全力攻击这些逃兵，不仅打击首脑，也要斩断四肢。除掉他可怕的荣誉卫士和医师，让他们无法从这一击中恢复。",
  },
  [27289] = {
    ["T"] = "远方的援军",
    ["O"] = "把装饰信件带给蕨墙村的纳泽尔·血矛检查。",
    ["D"] = "你们请求补给和援军的消息已经收到，我们的走私者正竭尽所能，通过热砂港和塞拉摩本身给你们送去援助。\n\n要塞不陷落对我们的事业至关重要。部落的狗和联盟内部的幼崽会为他们所做的一切付出代价。\n\n我们与岛屿主人新近达成的中立关系，已经让我们开始为忠于我们愿望的人建设一座真正的城镇。\n\n不久之后，你们将被派去大举进攻陶拉祖营地，但请等待我们的下一份报告。为了上将！\n\n-- R.D.",
  },
  [27290] = {
    ["T"] = "远方的援军",
    ["O"] = "把装饰信件带给塞拉摩的吉安娜·普罗德摩尔女士检查。",
    ["D"] = "你们请求补给和援军的消息已经收到，我们的走私者正竭尽所能，通过热砂港和塞拉摩本身给你们送去援助。\n\n要塞不陷落对我们的事业至关重要。部落的狗和联盟内部的幼崽会为他们所做的一切付出代价。\n\n我们与岛屿主人新近达成的中立关系，已经让我们开始为忠于我们愿望的人建设一座真正的城镇。\n\n不久之后，你们将被派去大举进攻陶拉祖营地，但请等待我们的下一份报告。为了上将！\n\n-- R.D.",
  },
  [27298] = {
    ["T"] = "嗅探器MK IV",
    ["O"] = "向棘齿城的加兹鲁维打听如何取得希斯的嗅探器MK IV。",
    ["D"] = "这次行动越来越贵了。我的老板不会喜欢的，我也不打算替比吉尔的错误背锅！\n\n我们可以用你找到的斗篷追踪他，但需要一些科技协助。去棘齿城找加兹鲁维谈谈，我把一套嗅探器MK IV套件交给他保管了。\n\n我们要用精良的地精科技找到比吉尔。",
  },
  [27312] = {
    ["T"] = "戈杜尼盗贼",
    ["O"] = "从菲拉斯的戈杜尼食人魔那里收集10箱莫沙彻营地补给。",
    ["D"] = "贫瘠之地的道路骚乱已经让补给很难送到莫沙彻营地，而好不容易运到菲拉斯的有限货箱又被戈杜尼食人魔偷走了。\n\n你能从那些盗贼手中找回一些货箱，好让我们不至于只能靠最低限度维持吗？沿着河向北走，你会找到他们的前哨。",
  },
  [27901] = {
    ["T"] = "大地母亲的赐予",
    ["O"] = "在贫瘠之地大地母亲圣坛的日光下为安舍之心充能，并在石爪山脉大地母亲圣坛的月光下为穆莎之心充能。",
    ["D"] = "当大地母亲看见自己的造物被黑暗低语腐化时，她流下一滴泪，化作蓝孩子——洛舒。当她将自己的身体献给创造时，又流下了两滴泪——也就是你现在握着的石头。\n\n要正确使用它们，必须在对它们母亲神圣的地方，用她孩子们的光为它们充能。\n\n把安舍之心带到淤泥沼泽东南方山顶上的一座圣坛。在白昼灿烂的光芒中把它放在圣坛上，让它吸收安舍的力量。\n\n同样，你必须把穆莎之心带到烈日石居北边山丘上、石爪洞穴附近的一座圣坛。在夜晚把它放在那里，吸收穆莎的力量。\n\n只有完成这些之后，再回到我这里。",
  },
  [28034] = {
    ["T"] = "狩猎仪式",
    ["O"] = "与贫瘠之地哀嚎洞穴附近营地里的宾兹纳库谈谈。",
    ["D"] = "很高兴见到你，$N。我有一条消息要给像你这样技艺高超的制皮师。\n\n一个名叫宾兹纳库的地精在贫瘠之地哀嚎洞穴西边的营地经营着一家偏僻店铺。他正在寻找愿意以委托方式工作的优秀制皮师。我不知道你是否感兴趣，但我觉得应该把消息转达给你。",
  },
  [28035] = {
    ["T"] = "狩猎仪式",
    ["O"] = "宾兹纳库要你使用制皮技能制作5份精炼石中盐和20片毛皮护甲片，然后把它们带到他在贫瘠之地哀嚎洞穴西边的营地。",
    ["D"] = "作为精良皮货的供应商，我总是在寻找拥有独特技艺的供货者。尤其是我的店开在这么偏远的地方……因为我已经不受镇上欢迎了……因为，一些原因。\n\n我很高兴你来了，$N。我听人提起过你的名字，说你是个崭露头角的工匠。我想看看你是否拥有我需要的技艺，所以你为什么不给我制作一些精炼石中盐和一大批毛皮护甲片呢？\n\n如果你不知道该怎么制作盐，嗯，你需要一位工程师的协助。",
  },
  [28039] = {
    ["T"] = "狩猎仪式",
    ["O"] = "与贫瘠之地哀嚎洞穴西边营地里的宾兹纳库谈谈。",
    ["D"] = "哦……我差点忘了！刚才一时陷入了回忆。你工作的那个地精传来消息。他希望你尽快回到他的营地。说是关于“失传已久的制皮图样”，挺有意思。记得告诉我你发现了什么！",
  },
  [28040] = {
    ["T"] = "狩猎仪式",
    ["O"] = "为贫瘠之地的宾兹纳库，从希利苏斯南风村的受折磨德鲁伊身上收集5片古代图样残片。",
    ["D"] = "这是一条热乎线索，刚从一群探索遥远南方沙漠的蠢货报告里来的。显然，他们发现了一个满是暗夜精灵幽灵的村庄，其中一些幽灵携带着古代制皮图样的碎片！想想古董货能加多少价！\n\n所以在别人抢走这条线索之前，亲自去那个叫希利苏斯的地方。没错，你是制皮师，但你也是个$C——该把那些本事用起来了。",
  },
  [27619] = {
    ["T"] = "给菲拉·古风的委托",
    ["O"] = "药剂师赫布瑞姆要你使用炼金术技能制作5瓶智慧药剂，并把订单交给贫瘠之地哀嚎洞穴顶上家中的菲拉·古风。",
    ["D"] = "每隔几个月，就会有朝圣者前去拜访住在哀嚎洞穴顶上的一位隐居牛头人。她的智慧有时很难理解，所以我想储备一些智慧药剂给她。如果你能制作并送过去，她会很乐意用一些有用的补给奖励你。",
  },
  [27620] = {
    ["T"] = "给辛吉尔的委托",
    ["O"] = "药剂师赫布瑞姆要你使用炼金术技能制作5瓶初级坚韧药剂，并把订单交给贫瘠之地十字路口北边家中的辛吉尔。",
    ["D"] = "在这片大陆上所有奇怪的生物中，我觉得巨魔最令人不快。他们有味道，也不欣赏优秀文学……总之，我收到一个名叫辛吉尔的巨魔请求，要一些初级坚韧药剂。如果你能替我处理掉这一单，我不会抱怨。",
  },
  [27621] = {
    ["T"] = "给酿酒师德罗恩的委托",
    ["O"] = "酿酒师德罗恩要你使用炼金术技能制作5瓶水下呼吸药剂，并把订单交给贫瘠之地棘齿城的酿酒师德罗恩。",
    ["D"] = "你好，$C……或者我该说，炼金师$N？你知道，酿酒和炼金并没有那么不同。\n\n我在旅途中和遇到的生物身上学到了许多酿酒知识，但还有一种材料来源我尚未探索：大海。为此，我可以用上一些水下呼吸药剂。这事你能帮我吗？",
  },
  [27622] = {
    ["T"] = "给酿酒师德罗恩的委托",
    ["O"] = "酿酒师德罗恩要你使用炼金术技能制作5瓶速游药水，并把订单交给贫瘠之地棘齿城的酿酒师德罗恩。",
    ["D"] = "我想探索大海，寻找可以用于酿酒的材料，但我并不愚蠢。我知道鲨鱼和其他危险可能潜伏在海浪之下。所以，如果我也能拿到一些速游药水，好在必要时从危险中跑——游——走，我会很感激！",
  },
  [27669] = {
    ["T"] = "给犹塞克的委托",
    ["O"] = "特劳弗要你使用锻造技能制作3块粗制磨刀石和3块粗制平衡石，并把订单交给贫瘠之地东北方前沿哨所的犹塞克。",
    ["D"] = "啊，我隔着一里地都能认出同为铁匠的人！说到一里地外，前沿哨所的犹塞克送来便条，要更多磨刀石和平衡石。我一直没时间处理他的订单，但如果你愿意在镇上练练手艺，我很乐意把这份委托交给你。",
  },
  [27671] = {
    ["T"] = "给布瑞恩的委托",
    ["O"] = "塔特纳克·钢炉要你使用锻造技能制作4把银质万能钥匙，并把订单交给贫瘠之地南部黑棘岭顶上的布瑞恩。",
    ["D"] = "向你致意，冒险者……而且还是位铁匠！我需要你的服务。\n\n一位名叫布瑞恩的隐居萨满要我为你制作一些银质万能钥匙，但我的银已经用完了。如果你能取得材料并完成她的订单，我就能专心处理大酋长要求的这些新武器。",
  },
  [27672] = {
    ["T"] = "给加恩·石塔的委托",
    ["O"] = "塔特纳克·钢炉要你使用锻造技能制作2把厚重战斧，并把订单交给贫瘠之地南黄金之路的加恩·石塔。",
    ["D"] = "自从野猪人袭击那支商队后，有一位牛头人就开始在南黄金之路上往来巡行。我钦佩他的坚韧，但如果武装得更好，他会撑得更久。\n\n我一直没时间给他打造几把厚重战斧，但我建议你去做。完成后，你可以在南边道路上巡逻时找到他。",
  },
  [28071] = {
    ["T"] = "给麦伯克·米希瑞克斯的委托",
    ["O"] = "麦伯克·米希瑞克斯要你使用烹饪技能制作10条长嘴泥鳅，并把订单交给贫瘠之地棘齿城的麦伯克·米希瑞克斯。",
    ["D"] = "搞这些发明可真辛苦，$C！我忙着处理这些创造物，肚子早就饿了。问题是，我不太会做饭。实验通常不太适合用在你真的想吃的食物上。\n\n你擅长烹饪吗？如果擅长，就帮我做些美味又营养的长嘴泥鳅吧。只要有新鲜泥鳅，我厨房里有什么就给你什么！",
  },
  [28080] = {
    ["T"] = "给拉卡的委托",
    ["O"] = "拉卡要你使用烹饪技能制作10份水煮蚌肉，并把订单交给贫瘠之地十字路口的拉卡。",
    ["D"] = "还有什么比照看酒吧更让人饿的吗？那些美味饮品让我的肚子直叫。\n\n附近的大海提供的美味多得数不过来。你吃过水煮蚌肉吗，$N？我现在真想来点。如果你愿意替我做一些，我会让你觉得值得。",
  },
  [28083] = {
    ["T"] = "给基尔格·锐角的委托",
    ["O"] = "基尔格·锐角要你使用烹饪技能制作10份猪肉干，并把订单交给贫瘠之地陶拉祖营地的基尔格·锐角。",
    ["D"] = "啊，$N！今天不是很美好吗？阳光明媚，云层高远，而我真想吃些猪肉干！\n\n什么，你以为我会想吃牛排？那太恶心了！\n\n南边的野猪人在他们的灌木丛里养了不少猪。你能帮帮一个老牛头人吗？",
  },
  [28407] = {
    ["T"] = "给辛吉尔的委托",
    ["O"] = "索克要你使用附魔技能，用附魔披风 - 初级防护为提供的1件绒毛披风附魔，并把订单交给十字路口北边一座塔附近小屋里的辛吉尔。",
    ["D"] = "既然我已经注意到贫瘠之地出现燃刃腐化的迹象，采取预防措施是明智的。辛吉尔在北边道路上有间小屋。给这件绒毛披风附上初级防护后，把它带给他。他住得离鬼雾峰太近，让我不太放心。",
  },
  [28408] = {
    ["T"] = "给索克的委托",
    ["O"] = "索克要你使用附魔技能制作1根符文银棒，并把订单交给贫瘠之地十字路口的索克。",
    ["D"] = "也许这有些迷信，但我听说银能有效抵御腐化，也许它能帮助我们对抗恶魔敌人和他们的盟友。给我制作一根符文银棒。那些附魔铭文肯定会以某种方式派上用场。",
  },
  [28409] = {
    ["T"] = "给贤者鹿蹄的委托",
    ["O"] = "基尔格·锐角要你使用附魔技能制作1根强效魔法杖，并把订单交给贫瘠之地陶拉祖营地的贤者鹿蹄。",
    ["D"] = "你是附魔师？也许你能解决我心头一根刺。贤者鹿蹄是镇上的传承者祭司，需要一根魔杖。给他制作一根强效魔法杖，好让他别再唠叨。告诉他先付你钱，我之后会去还他，否则他又会抱怨这件事。",
  },
  [28410] = {
    ["T"] = "给加恩·石塔的委托",
    ["O"] = "基尔格·锐角要你使用附魔技能，用附魔武器 - 初级攻击为提供的1把猎人斧附魔，并把订单交给贫瘠之地陶拉祖营地南边黄金之路某处的加恩·石塔。",
    ["D"] = "喂，既然你在镇上，我能不能说服你帮帮南贫瘠之地的好人？加恩·石塔独自巡逻南黄金之路，我担心他的安全。给这把猎人斧附上初级攻击，然后带给他，好让他更安全。",
  },
  [28457] = {
    ["T"] = "给瑟格拉·黑棘的委托",
    ["O"] = "加兹鲁维要你使用工程学技能制作5个活动假人，并把订单交给贫瘠之地十字路口的瑟格拉·黑棘。",
    ["D"] = "这些卡利姆多人大多并不了解工程学的威力，但他们知道自己想要我们造出来的一些东西。这意味着我们已经锁定市场，活也多得做不完。就拿十字路口那位队长瑟格拉·黑棘来说吧。她想要活动假人。我手头没有，但如果你有兴趣制作一些，我相信她会让你觉得值得。",
  },
  [28458] = {
    ["T"] = "给维妮·布特巴克的委托",
    ["O"] = "加兹鲁维要你使用工程学技能制作20个银触媒，并把订单交给贫瘠之地北黄金之路家中的维妮·布特巴克。",
    ["D"] = "我库存里没有的另一种东西是银触媒，但有个住在北黄金之路的地精有兴趣买一些。她说可以等送货。我不知道她在做什么，但我知道，如果你能给维妮·布特巴克弄到一些银触媒，就有钱可赚。",
  },
  [28459] = {
    ["T"] = "给塔特纳克·钢炉的委托",
    ["O"] = "塔特纳克·钢炉要你使用工程学技能制作5个铜质调节器，并把订单交给贫瘠之地陶拉祖营地的塔特纳克·钢炉。",
    ["D"] = "向你致意，$C。我知道这有点奇怪，一个铁匠向工程师求助，但我必须让熔炉继续运转。为此，我需要五个铜质调节器。如果你能帮我，我很乐意在你的报酬之外再给你一点小费。",
  },
  [28460] = {
    ["T"] = "给布拉什特的委托",
    ["O"] = "塔特纳克·钢炉要你使用工程学技能制作5把练习锁，并把订单交给贫瘠之地南黄金之路旁一座烧毁哨塔处的布拉什特。",
    ["D"] = "说到帮忙，我收到了一张匿名便条，要求一些练习锁。我不知道谁会对那种东西感兴趣，但这里没人有本事制作。如果你想多赚点钱，便条指示我把它们放在南黄金之路旁、靠近一座被烧毁的部落哨塔的地方。",
  },
  [28489] = {
    ["T"] = "给卡莉娅·风剪的委托",
    ["O"] = "卡莉娅·风剪要你使用急救技能制作20条绒线绷带，并把订单交给贫瘠之地陶拉祖营地的卡莉娅·风剪。",
    ["D"] = "喂，你包里那些是绷带吗？我能用得上你的帮助。我想勇敢踏入荒野，但首先需要一些补给。一把武器、一些食物，还有你能帮上的东西！\n\n我的医疗补给不够了。如果你能带给我20条绒线绷带，我一定会好好使用它们。我能来到这里已经很幸运了——让我们保持这种幸运吧。",
  },
  [28546] = {
    ["T"] = "给麦伯克·米希瑞克斯的委托",
    ["O"] = "胡拉玛希要你使用草药学技能采集20株石南草，并把订单交给贫瘠之地棘齿城的麦伯克·米希瑞克斯。",
    ["D"] = "哦，草药师！一个名叫麦伯克·米希瑞克斯的古怪地精向我索要石南草。我这边已经没有了，也不想再应付他那种“紧急”的语气。\n\n拜托了，朋友，把20株石南草带给棘齿城的他，帮我省掉这个麻烦。",
  },
  [28547] = {
    ["T"] = "给杜安·卡汉的委托",
    ["O"] = "杜安·卡汉要你使用草药学技能采集20株迅捷蓟，并把订单交给贫瘠之地南黄金之路东边营地中的杜安·卡汉。",
    ["D"] = "你好，$R。我正在贫瘠之地执行一项和平研究任务，但当地镇民对把货物卖给我保持警惕，这也可以理解。我的下一阶段实验需要迅捷蓟。既然你似乎有些植物方面的本事，我请求你协助。当然，我会支付你的服务费用。",
  },
  [28591] = {
    ["T"] = "给菲拉·古风的委托",
    ["O"] = "纳尔帕克要你使用制皮技能制作5片中型护甲片，并把订单交给贫瘠之地哀嚎洞穴顶上家中的菲拉·古风。",
    ["D"] = "制皮师？没错，你就是我在幻象中看到的人。我在梦中看见你运用自己的技艺帮助菲拉，她就住在这座山顶上。她需要几片中型护甲片。\n\n你会帮助她的，对吧？",
  },
  [28592] = {
    ["T"] = "给加兹罗格的委托",
    ["O"] = "纳尔帕克要你使用制皮技能制作1件优质皮外套，并把订单交给贫瘠之地十字路口的加兹罗格。",
    ["D"] = "在我的梦中幻象里，我还看见你手里拿着一件优质皮外套。我想那是给十字路口的加兹罗格的。他和几只迅猛龙打斗时撕破了衬衣，一直瞒着同伴。你给他带去一件新的，他会松一口气。",
  },
  [28593] = {
    ["T"] = "给玛伦·星眼的委托",
    ["O"] = "鲁迦·狂暴图腾要你使用制皮技能制作2条轻皮短裤，并把订单交给贫瘠之地提度斯阶梯的玛伦·星眼。",
    ["D"] = "哦，一位受过训练的制皮师。我们这里能用得上你的帮助。克鲁姆已经忙不过来了，但他不肯承认。他试图表现得勇敢，虽然他很紧张——他才刚完成大师训练。\n\n如果你能帮帮他，我借来了几张他的订单单据。玛伦·星眼订了几条轻皮短裤。你可以制作好，然后送到棘齿城外海岸上的她家。",
  },
  [28594] = {
    ["T"] = "给克鲁姆·满月的委托",
    ["O"] = "鲁迦·狂暴图腾要你使用制皮技能制作1条优质皮带，并把订单交给贫瘠之地陶拉祖营地的克鲁姆·满月。",
    ["D"] = "愿意再接一个任务吗？嗯……这张便条上没有名字。只有一行潦草字迹写着“一条优质皮带”。算了。你就制作这条皮带，把它带给克鲁姆。他会处理合适的交付。",
  },
  [28616] = {
    ["T"] = "给宾兹纳库的委托",
    ["O"] = "宾兹纳库要你使用剥皮技能收集5片变异鳞片和1片完美的变异鳞片，并把订单交给贫瘠之地哀嚎洞穴西边店铺里的宾兹纳库。",
    ["D"] = "哦，哈，你是剥皮师？你熟悉变异皮吗？那东西很奇怪。闪闪发亮，坚韧，卖得特别快。\n\n听着，我跟你做个交易。给我带来5片变异鳞片和一片完美的变异鳞片，我就分你一些利润。\n\n不过你得进哀嚎洞穴去弄它们。你觉得自己应付得了吗？",
  },
  [28649] = {
    ["T"] = "给维妮·布特巴克的委托",
    ["O"] = "斯布特瓦夫要你使用采矿技能采集20块粗糙的石头，并把订单交给北贫瘠之地黄金之路家中的维妮·布特巴克。",
    ["D"] = "你是找活干的矿工吗？我有条线索给你。\n\n维妮正在做某个又响、又不稳定、而且绝对不符合街道法规的东西。她说需要20块粗糙的石头来做“结构缓冲”还是什么胡话。能跑得更快时，谁在乎结构？\n\n如果你能采到一些，就带给她——她在黄金之路北边安顿下来了。",
  },
  [28661] = {
    ["T"] = "给特劳弗的委托",
    ["O"] = "加翰·鹰翼要你使用采矿技能采集10块银矿石，并把订单交给贫瘠之地十字路口的特劳弗。",
    ["D"] = "啊，矿工。我有份活给你。\n\n我想在这里的熔炉向特劳弗订制一些东西，但需要镶银。他说银用完了，也不知道什么时候会再进货。你觉得能帮上这个忙吗？",
  },
  [28706] = {
    ["T"] = "给维妮·布特巴克的委托",
    ["O"] = "哈里沙·白蹄要你使用裁缝技能制作2副高级毛纺手套，并把订单交给贫瘠之地北黄金之路家中的维妮·布特巴克。",
    ["D"] = "有人要一些耐用厚实的手套，但我手头没有那样的东西可给那个提出请求的地精。如果你能帮忙，就制作几副高级毛纺手套，并把它们送到黄金之路北边维妮·布特巴克的家。",
  },
  [28707] = {
    ["T"] = "给塔特纳克·钢炉的委托",
    ["O"] = "马哈尼要你使用裁缝技能制作2个毛纺包，并把订单交给贫瘠之地陶拉祖营地的塔特纳克·钢炉。",
    ["D"] = "我可以用得上一位有经验的裁缝，来完成贫瘠之地居民的几份积压订单。你有兴趣吗？\n\n塔特纳克·钢炉对奇怪矿石眼光敏锐，而且更敏锐的是，他会把自己找到的每一点都塞进口袋。问题是，他捡得太多，旧挎包都被撑裂了。\n\n我有一份订单，要给他送两个新的毛纺包。你可以在路对面、熔炉那里找到他。",
  },
  [28708] = {
    ["T"] = "给布瑞恩的委托",
    ["O"] = "马哈尼要你使用裁缝技能制作1条手工亚麻马裤，并把订单交给贫瘠之地南部黑棘岭的布瑞恩。",
    ["D"] = "我的朋友布瑞恩住在黑棘岭下，她传来消息说，附近野猪人营地周围到处生长的巨大荆棘划破了她的裤子。如果你不介意帮我，这会是一份很适合练手的订单。",
  },
  [26125] = {
    ["T"] = "石鱼汤",
    ["O"] = "从石爪山脉收集10条石肤鲦鱼，然后回到艾萨拉黑木村的维弗拉那里。",
    ["D"] = "向你致意，$C。如果你在石爪山脉崎岖山峰和蜿蜒峡谷间寻找片刻宁静，那我正好有个法子。维弗拉有一道新石鱼汤配方一直想试试，我们需要主要材料——石肤鲦鱼，只有石爪山脉才有。它们的鳞片也许比钉子还硬，但和鞭根、舒缓香料一起炖起来正合适。\n\n你愿意去那里，替我们带回一大堆好鱼吗？",
  },
  [26361] = {
    ["T"] = "冲突召唤：石爪山脉",
    ["O"] = "在石爪山脉找到并杀死5名部落成员。",
    ["D"] = "石爪山脉属于联盟，我们必须不断证明这一点。追猎部落成员，并代表军队杀死他们，证明你的价值，在军阶中晋升。",
  },
  [26362] = {
    ["T"] = "冲突召唤：石爪山脉",
    ["O"] = "在石爪山脉找到并杀死5名联盟成员。",
    ["D"] = "石爪山脉属于部落，我们必须不断证明这一点。追猎联盟成员，并代表军队杀死他们，证明你的价值，在军阶中晋升。",
  },
  [27397] = {
    ["T"] = "前往山谷",
    ["O"] = "从焦炭谷收集1块烧焦的木头和1条蜥蜴尾巴，然后回到石爪山脉烈日石居的库尔维娅那里。",
    ["D"] = "我需要一些只有焦炭谷才有的异域贸易材料。那是个危险的地方，只有最勇敢的冒险者才会去。你从这里向北走就能找到它。到达暗色湖后向东走，应该就能找到那条路。\n\n我需要的材料是一条蜥蜴尾巴，以及一块来自谷中游荡古树的烧焦木头。把这些材料带给我，我会让你觉得值得。",
  },
  [27398] = {
    ["T"] = "袭击矿洞",
    ["O"] = "在狂风矿洞杀死5名狂风地占师、5名狂风霸主和10名狂风掘地工，然后回到石爪山脉烈日石居的格劳纳尔那里。",
    ["D"] = "如果你到了狂风峭壁，要留意风险投资公司建造的一座矿洞。我听说他们已经开始作业，但狗头人占领了矿洞，把风险投资公司赶了出去！\n\n风险投资公司掠夺大地资源，从不考虑后果，但狗头人也是害虫，如果放任不管，就会召唤出强大的元素生物。矿洞中的作业必须停止！不惜一切代价，$N，任务完成前不要回来见我。",
  },
  [27399] = {
    ["T"] = "宁静狩猎",
    ["O"] = "从石爪林地周围的鹿身上收集10份驰鹿毛皮，然后回到石爪山脉的猎人基亚娜那里。",
    ["D"] = "你好，$C。你熟悉狩猎的技艺吗？这片林地里的鹿非常难以捉摸，对任何想猎取它们的人来说都是一项艰巨挑战。它们脚步迅捷，感官敏锐，是很好的猎物。\n\n这样吧，如果你给我带些它们的毛皮，我甚至会用它给你做一件漂亮披风！当然，我会给自己留一些，因为这里的冬天很冷！祝你好运，如果你在这里找不到它们，那些鹿有时会往南走一点，靠近通往林地的小径。",
  },
  [27400] = {
    ["T"] = "暗色湖护腕",
    ["O"] = "从暗色湖的水元素身上收集8副暗色湖护腕，然后回到石爪山脉烈日石居的塔姆拉·风田那里。",
    ["D"] = "你好，$N。很高兴在这里见到一位$C，因为有许多事要做。我在烈日石居住了很多年，这些山脉仍总能让我惊叹。最近，附近暗色湖中一处魔法泉苏醒了，我需要你帮忙处理它。\n\n这座湖是森林生物古老的庇护所。由于那处泉水，水元素从湖底涌出，伤害湖边四周的生物。我要你除掉那些水元素，并把它们的护腕带给我，作为完成此事的证明。",
  },
  [27401] = {
    ["T"] = "暗色湖",
    ["O"] = "从暗色湖的水元素身上收集8份暗色湖精华，然后回到石爪山脉石爪林地的森特瑞卡·夜歌那里。",
    ["D"] = "石爪山脉栖息着许多艾露恩珍爱的生灵，$N。我来到这里研究它们，并安静地练习炼金术。\n\n我观察到南边暗色湖有一些水元素。我很想测试它们精华的效果。你觉得能给我带一些回来吗？\n\n只要沿着林地外的道路向南走，就能轻松抵达暗色湖。如果你带来一些可用样本，我很乐意给你一些我的药水！",
  },
  [27402] = {
    ["T"] = "烈日石居的矿石",
    ["O"] = "从狂风矿洞采集8块钯矿石，然后回到烈日石居的格劳纳尔那里。",
    ["D"] = "看起来也许不像，但我们能锻造成守卫武器的金属已经不多了。如果无法自卫，我们就会暴露在联盟攻击之下！\n\n我听说风险投资公司在石爪这里发现了一种新矿石，据说比我们一直使用的铁更坚固。我要你拿上我的矿锄，前往狂风矿洞。进入狂风峭壁后沿山边向右走，就能找到矿洞。如果你发现任何特殊矿石，就用我的矿锄采集，带回来给我检查。",
  },
  [27404] = {
    ["T"] = "大地的震颤",
    ["O"] = "从石爪山脉焦炭谷中的血怒风巫身上收集4个闪电图腾。",
    ["D"] = "我知道了！你会在焦炭谷找到血怒风巫。她们引导的闪电必然有一个来源。杀死她们，把那东西带给我！我能用你带来的尾巴引导她们的闪电，给这台震地仪超级充能。\n\n我想四个鹰身人来源应该足够了。焦炭谷在烈日石居西边。",
  },
  [27405] = {
    ["T"] = "大地的震颤",
    ["O"] = "使用震地仪MK III，定位石爪山脉中震动的来源。",
    ["D"] = "来了。我介绍一下，震地仪MK III。我向来比我兄弟更擅长把东西拼凑起来。你知道该怎么做，我看得出来！\n\n现在把震地仪拍到地上，它会定位这些震动的来源。动手吧！",
  },
  [27406] = {
    ["T"] = "大地的震颤",
    ["O"] = "把矿石样本带给烈日石居的迪兹·弹簧套。",
    ["D"] = "你面前的矿石与你见过的任何东西都不同。你费了很大力气才掰下一块，准备带给迪兹·弹簧套。",
  },
  [27407] = {
    ["T"] = "大地的震颤",
    ["O"] = "把粪化石样本带给奥格瑞玛的萨尔。",
    ["D"] = "自从几年前大酋长进去后，就没人敢再冒险进入石爪洞穴，而他也是我知道的唯一一个活着回来的人。把你收集到的样本带给他，并告诉他你的旅程。\n\n没有人会比他更了解这种金属。",
  },
  [27408] = {
    ["T"] = "谷中修造",
    ["O"] = "从焦炭谷收集10片烧焦的鳞片和1个狂怒核心，然后回到石爪山脉石爪林地的巴珀·图克温克那里。",
    ["D"] = "日安，$gsir:madam;！这片林地真不错，你不觉得吗？我其实是来探索焦炭谷的一些生物，看看它们能不能用在我的下一项创造里。\n\n不幸的是，我太害怕了，根本不敢去那里。你看起来是个强壮的冒险者，能替我去吗？我需要蜥蜴身上的鳞片，还有土元素身上的核心。你会在这里南边找到焦炭谷，要经由暗色湖西边的一条小路过去。",
  },
  [27409] = {
    ["T"] = "暮光尖牙",
    ["O"] = "收集10颗暮光尖牙，然后回到石爪山脉烈日石居的克隆德那里。",
    ["D"] = "如果你到了远在北方的石爪林地，请睁大眼睛，留意潜伏在那里的暮光猎豹。据说它们的尖牙品质极高，但这些猫科野兽难以捉摸又行动迅速，所以很少有人能得到。\n\n如果你给我带来一些它们的尖牙，我很乐意用它们给你制作点东西。有人说暮光尖牙甚至带有魔法属性……！",
  },
  [27410] = {
    ["T"] = "湖中藤蔓",
    ["O"] = "从暗色湖收集8根水藤，然后回到石爪林地的瓦洛雷克·夜歌那里。",
    ["D"] = "很高兴在这里见到一位$c，我一直在寻找有冒险精神的人！我的姐姐森特瑞卡·夜歌需要一些新材料来进行炼金研究。我跟着一起来帮她，但恐怕完全没帮上什么忙！她需要的草药只生长在危险的地方，而我不擅长用剑。\n\n你愿意代我前去吗，$N？她需要只生长在暗色湖的水藤。那座湖很好找，只要沿路向南走，但要小心那里的生物！",
  },
  [27411] = {
    ["T"] = "湖中藤蔓",
    ["O"] = "把水藤箱交给石爪林地的森特瑞卡·夜歌。",
    ["D"] = "非常感谢你的帮助，$N。我已经把水藤放进了箱子里，如果你能把它们交给我姐姐就太好了！你可以在这里的旅店旁找到她。她终于能拿到这些草药，一定会很高兴；我知道她已经试着弄到它们很久了。",
  },
  [27413] = {
    ["T"] = "向凯拉报告",
    ["O"] = "向俯瞰石爪山脉狂风峭壁入口山谷的凯拉·影矛报告。",
    ["D"] = "我们今天给污林熊怪造成了决定性打击，但我收到情报，石爪山脉的威胁需要我们注意。显然，风险投资公司已经开始在狂风峭壁展开作业。必须阻止这件事。\n\n既然你在对付污林熊怪时证明了自己的效率，我希望你向凯拉·影矛报告，她正在监督我们对风险投资公司的攻击。沿着这里南边的石爪小径前往石爪后，你可以在俯瞰狂风峭壁入口的悬崖上找到她。",
  },
  [27414] = {
    ["T"] = "焚烧补给堆",
    ["O"] = "点燃狂风峭壁中的8份风险投资公司补给，然后回到石爪山脉的凯拉·影矛那里。",
    ["D"] = "这个观察点下方就是狂风峭壁，曾经是一片葱郁美丽的森林。然而，它的宁静正受到风险投资公司的威胁，那是一群受利润驱使、毫不留情的地精。他们以摧毁艾泽拉斯壮丽之地、掠夺自然资源而闻名。\n\n为了保护森林，我们必须向风险投资公司发动攻击。我要你拿上这支火把，在我身后的营火中点燃它，然后放火烧掉他们的补给箱。如果你的火把熄灭了，就回来找我再拿一支。森林正指望你，$N。",
  },
  [27415] = {
    ["T"] = "狂风矿洞",
    ["O"] = "在狂风矿洞杀死15名狂风掘地工，然后回到石爪山脉的凯拉·影矛那里。",
    ["D"] = "我预计补给被烧成灰后，风险投资公司会很难继续这里的作业。狂风峭壁的下一个威胁是狗头人。他们开始在一座矿洞里挖掘矿石，还恐吓这一带的居民。\n\n你会在进入狂风峭壁处正东边找到那座矿洞。消灭那里的狗头人，然后回到我这里。为了这片土地的安全，绝不能让那些邪恶生物继续在这里采矿。",
  },
  [27416] = {
    ["T"] = "石爪林地",
    ["O"] = "把凯拉的报告交给石爪山脉石爪林地的迈内拉队长。",
    ["D"] = "$N，感谢你协助处理狂风峭壁的问题。我在石爪林地的上级迈内拉队长要求一份关于狂风峭壁状况的报告。你能把它带给她吗？要到石爪林地，沿路一路向北走。",
  },
  [27922] = {
    ["T"] = "令人不安的传闻",
    ["O"] = "调查石爪山脉暗色湖周围的区域。",
    ["D"] = "感谢你回应我的召唤，$N。有消息传来，说石爪遭到袭击，我担心最坏的情况。你的服务受到高度推荐。\n\n我们历史中一处神圣的部分可能被盗走了——我这么说，但它也是所有德鲁伊的历史，甚至包括暗夜精灵。一个由穆莎，也就是月亮，祝福的生命之泉遭到了袭击。它位于阿赫普瓦尽头的洞穴中，那是湖边的一个营地。这个高地上的长者认为那里由我们最信任的勇士守卫，十分安全。\n\n<阿波尼停顿了一下，瞪向小屋入口，并警惕地打量外面的恐怖图腾。>\n\n我……不，我不会让流言复活。请前往石爪山脉中心、暗色湖东北方的营地。我们必须知道发生了什么，以及为什么！",
  },
  [27626] = {
    ["T"] = "给巫医金吉尔的委托",
    ["O"] = "基达要你使用炼金术技能制作5瓶次级法力药水，并把订单交给石爪山脉玛拉卡金的巫医金吉尔。",
    ["D"] = "我不是炼金师……不算真正的炼金师。不过，我的导师巫医金吉尔似乎以为我能凭空变出药水来。\n\n我需要一些次级法力药水给巫医。也许你能帮帮我？只要制作几瓶，送到玛拉卡金交给金吉尔。也许这样他就会让我安心学习了。",
  },
  [27676] = {
    ["T"] = "给达恩·鹰爪的委托",
    ["O"] = "迪兹·弹簧套要你使用锻造技能制作3副镀银青铜护手，并把订单交给石爪山脉南部玛拉卡金的达恩·鹰爪。",
    ["D"] = "嘿，你是铁匠吗？这个兽人在熔炉上给路过的铁匠留了张字条，说他想要三副镀银青铜护手。如果你有兴趣，就把它们做出来，送到玛拉卡金交给达恩·鹰爪。",
  },
  [28065] = {
    ["T"] = "给迈内拉队长的委托",
    ["O"] = "迈内拉队长要你使用烹饪技能制作10条彩鳍鱼，并把订单交给石爪山脉石爪林地的迈内拉队长。",
    ["D"] = "伊什努阿拉，$C。这个前哨十分偏远，我们人手很少，却有许多任务要做，好让部队随时准备应对风险投资公司……或愿艾露恩禁止，部落的攻击。\n\n我可以用得上一位厨师的帮助。你能为驻扎在这里的哨兵准备一些彩鳍鱼吗？一顿健康鱼肉做成的热饭，会比鹿肉和双足飞龙蛋更换换口味。",
  },
  [28081] = {
    ["T"] = "给马格兰的委托",
    ["O"] = "马格兰要你使用烹饪技能制作10条彩鳍鱼，并把订单交给石爪山脉烈日石居的马格兰。",
    ["D"] = "向你致意，$C。这个前哨十分偏远，我们人手很少，却有许多任务要做，好让部队随时准备应对风险投资公司……或愿大地母亲禁止，联盟的攻击。\n\n我可以用得上一位厨师的帮助。你能为驻扎在这里的步兵准备一些彩鳍鱼吗？一顿健康鱼肉做成的热饭，会比鹿肉和双足飞龙蛋更换换口味。",
  },
  [28414] = {
    ["T"] = "给巫医金吉尔的委托",
    ["O"] = "赫加斯要你使用附魔技能，用附魔胸甲 - 法力为提供的1件梦者长袍附魔，并把订单交给石爪山脉玛拉卡金的巫医金吉尔。",
    ["D"] = "你的附魔技艺进步得不错。想找点东西练习吗？巫医金吉尔想给这件梦者长袍附上法力。完成后把它送到玛拉卡金，沿这条路向南走就到了。",
  },
  [28464] = {
    ["T"] = "给菲兹克斯的委托",
    ["O"] = "迪兹·弹簧套要你使用工程学技能制作20根烈性炸药，并把订单交给石爪山脉狂风峭壁的菲兹克斯。",
    ["D"] = "我自己就是工程师，但现在没空接活。我有自己的项目要做，不过这可阻止不了别人来找我帮忙！\n\n我可以用上一双手，或者更确切地说，菲兹克斯可以用上你的双手。\n\n如果你能制作一些烈性炸药，就把它们送到狂风峭壁下面菲兹克斯的工坊去。",
  },
  [28478] = {
    ["T"] = "给森特瑞卡·夜歌的委托",
    ["O"] = "森特瑞卡·夜歌要你使用急救技能制作20条厚绒线绷带，并把订单交给石爪山脉石爪林地的森特瑞卡·夜歌。",
    ["D"] = "炼金术非常奇妙。有治烧伤的药水、止痛的药剂、增强力量的药剂……但有些伤口，有时我们真正需要的只是一条干净布带和稳定的双手。\n\n这个前哨没有驻扎治疗者，$C。因此，我请求你带给我20条厚绒线绷带。有了手头的补给，我们就能处理小伤，把炼金补给留给严重情况。",
  },
  [28488] = {
    ["T"] = "给马格兰的委托",
    ["O"] = "塔姆拉·风田要你使用急救技能制作3份抗毒药剂，并把订单交给石爪山脉烈日石居的马格兰。",
    ["D"] = "我了解毒素，$C。它们是这片土地的防御之一，而在这些山里？你最好准备好处理蜘蛛咬伤或双足飞龙蛰刺……如果不是两者同时的话！\n\n驻扎在这里的步兵在毒素方面可以用上一些实用资源。把3份抗毒药剂带给马格兰。我们会用毒的源头来治疗毒。",
  },
  [28515] = {
    ["T"] = "给丹尼卡的委托",
    ["O"] = "丹尼卡要你使用钓鱼技能收集20条火鳞鳝鱼，并把订单交给石爪山脉玛拉卡金的丹尼卡。",
    ["D"] = "肉倒是很多——野猪、科多兽，什么都有。但我已经厌倦了嚼肥肉和啃骨头。\n\n我想吃鱼。带给我20条火鳞鳝鱼。要有点辣味，要新鲜。如果渔获不错，我会好好跟你换。",
  },
  [28524] = {
    ["T"] = "给加克希姆·尘链的委托",
    ["O"] = "加克希姆·尘链要你使用草药学技能采集20株野钢花，并把订单交给石爪山脉蛛网小径营地中的加克希姆·尘链。",
    ["D"] = "石爪的蜘蛛咬得很深，毒液会留下挥之不去的残留。\n\n只有用野钢花熬制的合适热饮才能把它拔出来，但我们的补给快用完了。你能帮忙！在更多人病倒之前，带20株野钢花给我。",
  },
  [28549] = {
    ["T"] = "给森吉拉的委托",
    ["O"] = "森吉拉要你使用草药学技能采集20株野钢花，并把订单交给石爪山脉玛拉卡金的森吉拉。",
    ["D"] = "石爪的蜘蛛咬得很深，毒液会留下挥之不去的残留。\n\n只有用野钢花熬制的合适热饮才能把它拔出来，但我们的补给快用完了。你能帮忙！在更多人病倒之前，把20株野钢花带到玛拉卡金。",
  },
  [28570] = {
    ["T"] = "给凯拉·影矛的委托",
    ["O"] = "猎人基亚娜要你使用制皮技能制作5片重型护甲片，并把订单交给石爪山脉蛛网小径沿线营地中的凯拉·影矛。",
    ["D"] = "制皮师，我可以用得上你的协助。你看，我最好的朋友凯拉·影矛驻扎在蛛网小径，那里每天都有伏击、毒素，还有更糟的东西。她的装备已经修补过太多次，快撑不住了。\n\n你能制作几片重型护甲片并送给她吗？我不想占用你的时间，但她非常需要它们。",
  },
  [28598] = {
    ["T"] = "给达恩·鹰爪的委托",
    ["O"] = "马格兰要你使用制皮技能制作1副韧化皮手套，并把订单交给石爪山脉玛拉卡金的达恩·鹰爪。",
    ["D"] = "达恩·鹰爪自战争结束后就驻扎在玛拉卡金。他是个好指挥官，即使在艰难局势中也是如此。我尊重他，胜过大多数兽人。\n\n我想委托你为达恩制作一副非常特别的韧化皮手套。他最近遭遇了一次挫折，开始质疑自己的领导能力。我想提醒他，他受到尊敬，也很有价值。让达恩保持能干，也算是为部落服务。",
  },
  [28641] = {
    ["T"] = "给巴珀·图克温克的委托",
    ["O"] = "巴珀·图克温克要你使用采矿技能采集20块重石，并把订单交给石爪山脉石爪林地的巴珀·图克温克。",
    ["D"] = "哎呀，石爪这里居然有矿工？我看这地方挺适合干这行。而且如果你在找活干，这里正有份活等着你。\n\n我需要石头！具体来说，是那种常与铁矿石伴生的重石。虽然石爪本身铁不多，但周边地区富含这种材料。如果你愿意帮忙，我一定会在你回来时付给你报酬！",
  },
  [28665] = {
    ["T"] = "给马格兰的委托",
    ["O"] = "马格兰要你使用采矿技能采集20块重石，并把订单交给石爪山脉烈日石居的马格兰。",
    ["D"] = "哎呀，石爪这里居然有矿工？这是个适合干这行的地方。如果你在找活干，这里正有份活等着你。\n\n我需要石头！具体来说，是那种常与铁矿石伴生的重石。虽然石爪本身铁不多，但周边地区富含这种材料。只要手头有足够石头，我们就能保持武器锋利，以防联盟攻击。",
  },
  [26121] = {
    ["T"] = "热气腾腾的岸边",
    ["O"] = "在千针石林收集一条银溪鳗鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "你在千针石林可找不到多少水，$C。事实上，我知道的那个地方——恐怖图腾岗哨下方的热泉——我从来没停下来甩过钓线。\n\n我很好奇你会在那里找到什么。我听过一个夸张的传闻，说有条老鳗鱼从我朋友手里溜掉了。多半根本不存在，不过你不想去弄个明白吗？不管你带回来什么，维弗拉都会帮你装裱起来。",
  },
  [26367] = {
    ["T"] = "战斗的召唤：千针石林",
    ["O"] = "在千针石林找到并杀死5名部落成员。",
    ["D"] = "千针石林属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26368] = {
    ["T"] = "战斗的召唤：千针石林",
    ["O"] = "在千针石林找到并杀死5名联盟成员。",
    ["D"] = "千针石林属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26906] = {
    ["T"] = "祖尔达亚石板",
    ["O"] = "把祖尔达亚石板带给藏宝海湾的克兰克·菲兹巴布。",
    ["D"] = "不知道为什么，现在研究巨魔历史成了热门事。这也意味着里面有钱可赚！\n\n祖丹亚废墟北边是血顶巨魔的地下墓穴。那里面某处有一块记载祖尔达亚历史的石板。我有个感兴趣的买家——如果你能把它弄到手，我会把一部分利润分给你。",
  },
  [27200] = {
    ["T"] = "失踪的传承讲述者",
    ["O"] = "从黑棘岭的野猪人营地找回8卷牛头人传说卷轴。",
    ["D"] = "可怜的米娜和塞利姆。他们是和平的研究者，不是战士。他们与野猪人无冤无仇……但现在我有了！\n\n那辆车上装着从乱风岗运来的几箱牛头人传说卷轴。我只能认为它们现在已经落到野猪人手里了。到他们袭击商队地点附近的黑棘岭营地去，找回那些卷轴。任何挡路的野猪人都杀掉。这就是我为倒下的同胞复仇的方式。",
  },
  [27246] = {
    ["T"] = "唤雷者杰辛斯",
    ["O"] = "前往裂蹄堡。杀死唤雷者杰辛斯，并从她身上取回大地母亲石板。",
    ["D"] = "半人马劫掠并毁坏牛头人不懈建造的一切。他们是盗贼和杂种，用蹄子亵渎大地。\n\n塔霍达营地被废弃时，半人马来到那里，抢走了少数无法带走的贵重物品。其中之一就是埋在那里、用于祝圣土地的大地母亲圣石板。\n\n那块石板现在落在唤雷者杰辛斯手中，她就住在千针石林的裂蹄峭壁里。我要让这块神圣石板归还，也要让杰辛斯被埋进泥土。",
  },
  [27251] = {
    ["T"] = "返回玛加萨身边",
    ["O"] = "把幽暗绝壁发生的事告诉玛加萨·野性图腾。",
    ["D"] = "我想在这里停留片刻，向我倒下的族人灵魂告别。在你到来之前，我设法收集了一些死者的骨骸。请把这包骨骸带回给玛加萨，让她为他们举行合适的安葬仪式。告诉她发生了什么，也告诉她我很快就会回城。",
  },
  [27317] = {
    ["T"] = "寻找归宿的孤儿",
    ["O"] = "到千针石林的沙漠赛道与哈桑·重木谈一谈。",
    ["D"] = "哦，你好，$N。真高兴又见到你。你的雷霆崖之行怎么样？\n\n嗯，你会高兴地知道，在你离开的时候我们取得了不少进展。我们甚至救下了一整窝蛋。可惜我们赶到之前，它们的母亲已经死了。\n\n说起来，你想要一只当宠物吗？它们看起来快孵化了，需要一个好$Gfather:mother;。你觉得呢？\n\n如果你真的感兴趣，就把其中一枚蛋带给闪光平原赛道上的哈桑·重木。他会告诉你更多事情。",
  },
  [27318] = {
    ["T"] = "短暂的孵化期",
    ["O"] = "把2瓶坚韧药剂带给千针石林的哈桑·重木。",
    ["D"] = "大地之月夫妇，是吗？真有意思。我希望精龙真的能明白由那两位照看它们意味着什么。他们都很有能力。\n\n所以，他们把这枚蛋作为礼物送给了你。那么在它需要照料的这段时间里，你就应该对它负责。它看起来马上就要孵化了，但我们得确保它健康，没有受到损伤。\n\n我只需要两瓶坚韧药剂，用一个小法术保护这枚蛋。其他材料我这里都有。",
  },
  [27446] = {
    ["T"] = "完美容器",
    ["O"] = "从加基森以西坠毁的侏儒赛车上取得6个侏儒赛车零件。",
    ["D"] = "如果没有可靠的方法把燃料储存在火箭上，再完美的燃料也没用。附近最好的冶金活儿都出自沙漠赛道的侏儒车队，可惜他们不肯分享！好像是因为什么“商业机密”和“别再偷我们的东西”之类的，随便吧。\n\n有传言说，他们的一辆实验赛车一路坠毁到了塔纳利斯这里。我想要那辆车的金属！到加基森外面找到坠毁地点，不管用什么办法，把它的零件带回来！",
  },
  [27471] = {
    ["T"] = "女工的工具",
    ["O"] = "到千针石林闪光平原的沙漠赛道，从拉泽瑞克那里取回凯克斯的电池增压焊枪。",
    ["D"] = "我们本来指望货物里有一台新的强力电弧焊枪，我可以在这里使用。它一碰到水就毁了，所以我甚至没让你去把它捞上来。\n\n我还有一台备用的，借给了我一个好朋友，他在沙漠赛道的地精车队工作。你能去找他要回来吗？我肯定他不会乐意交出来，但我们的需求比一辆赛车更重要。",
  },
  [27486] = {
    ["T"] = "琥珀纪念物",
    ["O"] = "解开琥珀纪念物之谜。",
    ["D"] = "这枚护符取自尘蹄酋长迷失的灵魂，看上去并不显眼。它是一枚磨旧的青铜坠饰，金属已经失去光泽，一小块琥珀被粗糙地嵌在托座里。\n\n你不确定这件饰物有多古老，也不知道它值多少钱。当你端详它时，一阵冷风从身边掠过，像是在召唤你前往闪光平原北缘的方向。\n\n也许你该去调查一下？",
  },
  [27487] = {
    ["T"] = "聚集灵魂",
    ["O"] = "从凄凉之地的海岸收集8捆织叶草。",
    ["D"] = "许多个月亮以前，我们的部族曾在玛珊希的草原上行走，但灾难降临这片地区，使它变得死寂而荒芜。我们的部族在尘蹄酋长的指引下离开了那片如今被称为凄凉之地的荒原。他心中始终怀着希望，相信在南方沙漠之外，在半人马和精灵土地之外，还有一片青翠而未驯服的土地。\n\n我们对这趟旅程准备不足，尘蹄酋长在穿越闪光平原时死去。酋长死后，部族其他人四散而去。许多人倒在酷热和沙漠野兽之下。你也许见过他们的灵魂在这一带徘徊。\n\n我相信我们仍能以灵魂之身完成这趟旅程，至少能让部族再次一同行走在那片土地上。但你必须帮助我们，$c。\n\n你必须回到活人的世界，前往凄凉之地。沿着海岸收集织叶草。收集足够之后，回到这里，用它点燃这座图腾旁的火焰。过去，我们在仪式聚会中用织叶草作熏香；尘蹄和族人的灵魂会认出这股气味。\n\n愿大地母亲指引你的道路，朋友。",
  },
  [27488] = {
    ["T"] = "坏消息长着角",
    ["O"] = "在黑云峰找到并取回三份密信。",
    ["D"] = "除了半人马、牛头人和偶尔经过的地精商队，我们在石林里很少见到旅人。有一个特别的团体让我很担心。\n\n有人看到一些阴影般的人物去拜访恐怖图腾氏族。他们披着兜帽，所以我看不清他们的身份，但我怀疑他们并不是部落成员。\n\n我不知道恐怖图腾在计划什么，但绝不会是好事。我明白这非常危险，但我需要你潜入黑云峰上的氏族村落。看看能不能找到文件、消息——任何能解释那些密探和恐怖图腾之间合作关系的东西。",
  },
  [27491] = {
    ["T"] = "驾驶执照审批",
    ["O"] = "向赛道管理员泽尔林、赛场主管科鲁克莱德、拉泽瑞克和维兹尔·铜栓苦苦哀求，取得沙漠赛道执照。",
    ["D"] = "如果你想参加沙漠赛道的比赛，就需要得到附近几位关键人物的正式签字。赛场主管科鲁克莱德是这里的大头目，但光靠他一个人还不能点头。你需要每支车队负责人的认可；侏儒车队是维兹尔·铜栓，地精车队是拉泽瑞克。最后，赛道管理员泽尔林也很有分量。\n\n这里唯一比赛车更大的就是车手们的自尊心，所以只要你去向他们苦苦哀求，我相信正式请愿书很快就能批下来，你也能上赛道了。",
  },
  [27492] = {
    ["T"] = "清水递送",
    ["O"] = "把10瓶清凉气泡淡水送给沙漠赛道周围瞭望塔上的赛事监督员。",
    ["D"] = "赛道四周有四座塔，里面坐着比赛裁判——也就是监督员。监督员们顶着烈日坐在那里，监视比赛，把作弊和外部干扰控制在可以接受的水平。如果有撞车事故打断比赛，他们会通知我们。\n\n如果你给他们送些清凉气泡淡水，当事情出岔子时，他们也许会变得更……好说话一点。你觉得怎么样？",
  },
  [27493] = {
    ["T"] = "登上领奖台",
    ["O"] = "在一场沙漠赛道赛事中取得第1、第2或第3名。",
    ["D"] = "你出去比赛时代表的是我们地精车队。我对你有最高期待，所以条件是这样：如果你在比赛结束时登上前三名的领奖台，我就给你一份特别礼物。怎么样？现在上场去，把轮胎烧起来！",
  },
  [27494] = {
    ["T"] = "登上领奖台",
    ["O"] = "在一场沙漠赛道赛事中取得第1、第2或第3名。",
    ["D"] = "你出去比赛时代表的是我们侏儒车队。我对你有最高期待，所以条件是这样：如果你在比赛结束时登上前三名的领奖台，我就给你一份特别礼物。怎么样？现在上场去，把轮胎烧起来！",
  },
  [27496] = {
    ["T"] = "缝补物资",
    ["O"] = "把10片尘皮带给千针石林萨兰纳尔的瑞恩多尔。",
    ["D"] = "打扰一下，你有空吗？我修补护甲的材料快用完了，而在半人马最近袭击之后，我不指望还有商队会经过这里。我需要从千针石林周围游荡的野兽身上弄些新鲜皮革。\n\n你从什么动物身上采集、皮革质量如何，我都不是特别挑剔，但如果你能收集十片，我会给你不错的报酬。",
  },
  [27497] = {
    ["T"] = "反击加拉克",
    ["O"] = "找到并杀死督军布利兹，把他的头颅带给乱风岗的峭壁卫兵图林·长角。",
    ["D"] = "那个懦夫……！如果他这么想要我的头……除非他亲自来这里，否则他不会有机会。\n\n督军布利兹在这里北边扎下营地，派他的部队伏击我们的营地和商队。他躲在那里，不亲自来杀我，我一点也不意外。\n\n你知道，我相信乱风岗不会介意你把他毙命的证据带给他们。",
  },
  [27498] = {
    ["T"] = "可汗阿布林",
    ["O"] = "找到并杀死可汗阿布林，把他的头颅带给乱风岗的峭壁卫兵图林·长角。",
    ["D"] = "伊索克营地的督军已经死了，但他们的首领可汗阿布林很快就会任命新的督军。现在正是出击的时候！\n\n那个可汗住在北边的半人马营地里，策划着下一步行动。猎杀他，$c。砍倒他，让营地陷入混乱。",
  },
  [27500] = {
    ["T"] = "神圣之火",
    ["O"] = "侦察半人马神器的位置，从千针石林的裂蹄峭壁开始。如果找到它，就回到萨兰纳尔的法芬德尔·行路者那里。",
    ["D"] = "我听说过这一带半人马的传闻。据说加拉克氏族守护着一件来自半人马诞生时代的神器。\n\n我不知道它究竟是什么，但我相信它能揭示一些半人马起源的线索。遗憾的是，我们不知道那件神器在哪里，而加拉克半人马也不可能轻易透露它的位置。\n\n更下方峡谷里的裂蹄峭壁是最大的加拉克聚落。我建议你先在那里寻找可能的线索，不过我不认为就连半人马也会把如此贵重的东西随意摆在外面。",
  },
  [27502] = {
    ["T"] = "塔霍达营地的悲剧",
    ["O"] = "把风化图腾带给乱风岗的某个人。他们也许更了解那座废弃营地。",
    ["D"] = "你手中的牛头人图腾显然饱经风霜。蜥蜴的咬痕布满图腾，残留的颜料也严重褪色。尽管如此，它仍是那座废弃营地少数留存下来的东西之一，也许对牛头人有价值。\n\n乱风岗也许有人更了解塔霍达废墟及其命运。或许你也能把这座图腾卖掉，换到一点金币。",
  },
  [27503] = {
    ["T"] = "噢，双足飞龙！",
    ["O"] = "从千针石林风巢救出克里斯蒂的猫科迪。",
    ["D"] = "$C，你得帮帮我！\n\n科迪，我那只小恶魔一样的猫……他被猫拐走了！我只是把他的笼门开了一会儿，他就冲进了沙漠！我还没来得及抓住他，一只双足飞龙就俯冲下来，把我亲爱的科迪叼走了！它们一定把他误认为自己的幼崽了！\n\n带上科迪的提篮，前往风巢的双足飞龙筑巢地，但请务必小心！据说那里的双足飞龙非常凶猛，我不想让我的小男孩受伤！\n\n求你了，$c，快点！",
  },
  [27625] = {
    ["T"] = "给埃鲁的委托",
    ["O"] = "埃鲁要你使用炼金术技能制作5瓶强力巨魔之血药水，并把订单交给千针石林乱风岗的埃鲁。",
    ["D"] = "很高兴在这里见到一位炼金师。我正在照料一些受伤的双足飞龙幼崽，需要一批强力巨魔之血药水来轻柔地清洗并治疗它们的伤口。你能帮这个忙吗？",
  },
  [27675] = {
    ["T"] = "给维兹罗的委托",
    ["O"] = "维兹罗要你使用锻造技能制作2把青铜匕首，并把订单交给千针石林白沙岗哨的维兹罗。",
    ["D"] = "啊，铁匠！也许你能帮我——要是商队再遭袭，我可得做好准备。为此，我想要几把漂亮的匕首。要快的，懂吧。闪亮，而且够快。你能办到吗？",
  },
  [27890] = {
    ["T"] = "生死攸关",
    ["O"] = "到雷霆崖长者高地寻找玛加萨·野性图腾。",
    ["D"] = "你好，$N。我带来了玛加萨·野性图腾的消息。她在找人替她办件事——要低调。好像和被遗忘者有关。\n\n我知道你是个值得信赖的$C，所以我觉得你再合适不过了。你可以在雷霆崖的长者高地找到她。还有，$N，如果有人问起，我可没跟你说过这事。",
  },
  [27894] = {
    ["T"] = "生死攸关",
    ["O"] = "带着你了解到的关于被遗忘者的消息，回到雷霆崖长者高地的玛加萨·野性图腾那里。",
    ["D"] = "原来如此，霍尔卡一直在研究被遗忘者本身。\n\n我想你也许以为我会因为这些消息而不悦，但我并没有。即使我们活着，我们存在的许多原因对我们来说仍是谜团。至少我有这种感觉，而我研究天灾本质的时间比大多数人都久。\n\n我可以给你一个结论。正如黑暗女王本人所说，这种存在是一种诅咒。有人也许称它为黑暗的赐福，当然也确有一些好处，但它终究是诅咒。只有最愚蠢的人才会主动寻求加入我们的行列。\n\n话虽如此，我们也观察到，并非所有被复生为亡灵的存在都能成功活下去。成为被遗忘者，就是在生命本身已经抛弃你时，仍拥有生存下去的意志。把这句话带回给你的女主人。",
  },
  [28084] = {
    ["T"] = "给多恩·平原行者的委托",
    ["O"] = "多恩·平原行者要你使用烹饪技能制作10条刺须鲶鱼，并把订单交给千针石林风裂峡谷老屋的多恩·平原行者。",
    ["D"] = "你好，$N。大海离这里太远，而我又太想吃鱼了。可我有责任在身，根本没时间旅行，更别说用我那点粗浅手艺烹饪了。\n\n你愿意帮我一个忙吗？我想要一些热腾腾的刺须鲶鱼。看起来你在营火旁很有手艺。我会乐意为你的服务付钱。",
  },
  [28394] = {
    ["T"] = "给洛娜·石印的委托",
    ["O"] = "洛娜·石印要你使用附魔技能，为提供的1面萨满祭司之盾附魔盾牌 - 精神，并把订单交给菲拉斯与千针石林交界处萨兰纳尔附近的洛娜·石印。",
    ["D"] = "从大地的低语中我能听出你是一名附魔师。你能为我的萨满祭司之盾附上精神吗？我会非常感激！哦，我也会付钱。",
  },
  [28413] = {
    ["T"] = "给哈加尔·雷蹄的委托",
    ["O"] = "卫兵穆赫·月角要你使用附魔技能制作1根亲和法杖，并把订单交给千针石林乱风岗的哈加尔·雷蹄。",
    ["D"] = "你好，你是附魔师吗？乱风岗的哈加尔·雷蹄正在找一根亲和法杖，但镇上没有附魔师。如果你愿意帮忙，我相信他会让你觉得值得。",
  },
  [28463] = {
    ["T"] = "给维兹罗的委托",
    ["O"] = "维兹罗要你使用工程学技能制作2个普通瞄准镜，并把订单交给千针石林白沙岗哨的维兹罗。",
    ["D"] = "嘿，你是工程师吗？太棒了！我正准备让商队重新上路，但我需要几个普通瞄准镜，这样下次那些半人马一露头，我就能把他们打下来。你能帮我吗？",
  },
  [28479] = {
    ["T"] = "给瑞恩多尔的委托",
    ["O"] = "瑞恩多尔要你使用急救技能制作3份强力抗毒药剂，并把订单交给千针石林萨兰纳尔的瑞恩多尔。",
    ["D"] = "双足飞龙在森林边缘的高空盘旋。它们的毒刺发作很快，残酷无情，如果不及时处理就会致命。我们已经失去了两匹驮马，还差点失去一名斥候。\n\n我看得出来，你精通急救。我需要3份强力抗毒药剂。下一只被刺伤的生物也许还没赶回来，毒液就已经发作了，我们必须做好准备。",
  },
  [28491] = {
    ["T"] = "给埃鲁的委托",
    ["O"] = "埃鲁要你使用急救技能制作3份强力抗毒药剂，并把订单交给千针石林乱风岗的埃鲁。",
    ["D"] = "双足飞龙在石林的高空盘旋。虽然我很喜爱它们，但我不得不承认，它们的毒刺发作很快，残酷无情，如果不及时处理就会致命。我们最近失去了两头驮运科多兽，还差点失去一名斥候。\n\n我看得出来，你精通急救。我需要3份强力抗毒药剂。下一只被刺伤的生物也许还没赶回来，毒液就已经发作了，我们必须做好准备。",
  },
  [28526] = {
    ["T"] = "给洛娜·石印的委托",
    ["O"] = "洛娜·石印要你使用草药学技能采集20株皇血草，并把订单交给千针石林萨兰纳尔的洛娜·石印。",
    ["D"] = "手上有草汁的痕迹？你莫非是炼金师？\n\n这一带的元素很不安宁，我想制作一枚护符与它们沟通。为此，我需要大量皇血草。你觉得你能帮忙吗？",
  },
  [28551] = {
    ["T"] = "给哈加尔·雷蹄的委托",
    ["O"] = "卫兵穆赫·月角要你使用草药学技能采集20株皇血草，并把订单交给千针石林乱风岗的哈加尔·雷蹄。",
    ["D"] = "你好，$N。你看起来像是个草药师。我想请你帮个忙。\n\n我在乱风岗的朋友哈加尔需要皇血草。别问我为什么，但听起来很紧急。\n\n采集20株皇血草并把它们带给他。他会知道该怎么处理。",
  },
  [28597] = {
    ["T"] = "给斯塔恩的委托",
    ["O"] = "斯塔恩要你使用制皮技能制作2条黑皮腰带，并把订单交给千针石林乱风岗的斯塔恩。",
    ["D"] = "你好，$N。你会用针线和皮革吗？我想弄几条黑皮腰带，作为父母即将来乱风岗探望我时带回家的礼物，但我们这里没有常驻制皮师。\n\n如果你能接下这份委托，我会很乐意付钱给你，还会附上我上次狩猎留下的一些毛皮。",
  },
  [28611] = {
    ["T"] = "给瑞恩多尔的委托",
    ["O"] = "瑞恩多尔要你使用剥皮技能采集5张中毛皮，并把订单交给千针石林萨兰纳尔的瑞恩多尔。",
    ["D"] = "你好，$N。请原谅我冒昧，但我注意到你的剥皮刀小心地绑在背包上。我一直想收集原料，用来制作护甲，保护那些进入这片荒野的人。你愿意为我收集5张中毛皮吗？",
  },
  [28640] = {
    ["T"] = "给菲兹尔·铜栓的委托",
    ["O"] = "菲兹尔·铜栓要你使用采矿技能采集20块青铜锭，并把订单交给千针石林沙漠赛道的菲兹尔·铜栓。",
    ["D"] = "哇，嘿，你好。看到这条赛道了吗？引擎太多，时间太少！我要焊零件、磨齿轮，可库存里一点青铜都没有。\n\n快给我带来20块青铜锭！我倒是想自己去弄，可我要是一离开，肯定会有什么东西爆炸。大概吧……！",
  },
  [28664] = {
    ["T"] = "给普兹克的委托",
    ["O"] = "普兹克要你使用采矿技能采集20块青铜锭，并把订单交给千针石林沙漠赛道的普兹克。",
    ["D"] = "哇，嘿，你好。看到这条赛道了吗？引擎太多，时间太少！我要焊零件、磨齿轮，可库存里一点青铜都没有。\n\n快给我带来20块青铜锭！我倒是想自己去弄，可我要是一离开，肯定会有什么东西爆炸。大概吧……！",
  },
  [28711] = {
    ["T"] = "给泰瑞斯·晨影的委托",
    ["O"] = "泰瑞斯·晨影要你使用裁缝技能制作1件白色毛绒裙，并把订单交给千针石林沙漠赛道的泰瑞斯·晨影。",
    ["D"] = "我非常需要一名裁缝，而且我能从你手指上的茧看出来，你知道该怎么拿针。\n\n太阳落下后这里会变冷。沙子不像石头那样保温，而我平常的衣服更适合赛道，不适合寒风。你能给我做一件暖和的毛绒裙吗？我会付钱！保证！",
  },
  [28712] = {
    ["T"] = "给大法师提尔斯的委托",
    ["O"] = "大法师提尔斯要你使用裁缝技能制作2件次级巫师袍，并把订单交给千针石林沙漠赛道的大法师提尔斯。",
    ["D"] = "我无意中听到你是裁缝。我的行李本应直接传送到沙漠赛道。结果我相信它现在在现实之间的某处——或者可能在无尽之海海底。\n\n无论如何，我需要两件次级巫师袍。希望你能加快这份订单，免得有人把我误认为廉价把戏的施法者！",
  },
  [26119] = {
    ["T"] = "深水贝壳",
    ["O"] = "在凄凉之地收集10只索拉提亚贝类，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "你知道吗，$N，你有成为一名出色$gfisherman:fisherwoman;的潜质，而且品味也很不错！\n\n如果你想找最好的海鲜，就去凄凉之地的海岸吧，在那里捕贝类就像钓鲈鱼一样容易。那些索拉提亚贝类可真是古怪的生物。要是你也能给维弗拉带些回来，她一定会非常感激。",
  },
  [26299] = {
    ["T"] = "配得上国王",
    ["O"] = "进入玛拉顿并杀死诺克赛恩。收集他的精华，带给菲拉斯的维戈。",
    ["D"] = "好吧，别想着今天能轻松过了。我只听说过一个地方可能有我们需要的东西：半人马的诞生地，玛拉顿。\n\n在橙色洞窟深处，你会找到一个极其强大的水元素，名叫“诺克赛恩”。他的精华会成为更配得上这把强大武器的材料。\n\n你愿意冒着生命和肢体的风险替我取来他的精华吗？我保证，等格鲁克统治厄运之槌之后，这一切都会有回报！",
  },
  [26302] = {
    ["T"] = "腐化之源",
    ["O"] = "在玛拉顿内收集一份瑟莱德丝公主的样本，交给曲线岗哨的塞尔莱·露光。",
    ["D"] = "口述历史说，这片土地曾经郁郁葱葱，但玛拉顿中的瑟莱德丝公主释放了半人马，引发了一场灾难，造就了我们周围如今所见的土地。我的目标是在这里迪比和凯莉的协助下恢复这片土地。\n\n我们需要进一步研究的关键成分之一，是公主本身的样本。杀死她不仅能终止进一步的腐化，而且通过仔细研究她，我们也许能逆转这种腐化。\n\n请替我深入玛拉顿，取回一份样本。我会给你丰厚的报酬。",
  },
  [26371] = {
    ["T"] = "战斗的召唤：凄凉之地",
    ["O"] = "在凄凉之地找到并杀死5名部落成员。",
    ["D"] = "凄凉之地属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26372] = {
    ["T"] = "战斗的召唤：凄凉之地",
    ["O"] = "在凄凉之地找到并杀死5名联盟成员。",
    ["D"] = "凄凉之地属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26528] = {
    ["T"] = "所有迹象都指向凄凉之地",
    ["O"] = "在凄凉之地与菲莉希蒂·佩瑞诺德会合，她会在玛诺洛克集会所附近某个视野良好的地方。",
    ["D"] = "$C，仔细听。在占卜中，我被引向大海彼岸，来到名为卡利姆多的土地。在它西岸有一片荒芜之地，名叫凄凉之地。我看到一群术士正在架设召唤传送门。我们会在那里找到关于阿古斯之醒的答案。\n\n等我从占卜中恢复过来，就能把自己传送到卡利姆多。我现在……很累。但你先出发，占个先机。到那些术士扎根的地方附近找我——我会待在视野不错的地方！",
  },
  [26529] = {
    ["T"] = "凄凉之地的阿古斯之醒",
    ["O"] = "使用变形护符制服扎拉丝莉娅，然后回到凄凉之地的菲莉希蒂·佩瑞诺德那里。",
    ["D"] = "我观察这些术士有一阵子了，他们效忠的是燃刃氏族，不是阿古斯之醒。但燃烧军团内部有许多组织，他们很可能知道自己的姐妹组织在凄凉之地哪里行动。\n\n有个大恶魔装模作样地当首领，但聪明的间谍会看穿表象（至少拉文霍德大人是这么告诉我的）。那个恶魔也许拿着一把大剑，可这个团体背后的真正力量，是一个名叫扎拉丝莉娅的术士。她就在我们下方，那座神庙废墟里。\n\n要接近她，有些人挡在路上，所以我需要你动手清掉他们。我们需要她活着，所以用拉文霍德大人给我的这个小护符。它应该能让她更容易对付。等你完成后，我会去把她带走。\n\n<菲莉希蒂咯咯笑了起来。>",
  },
  [26530] = {
    ["T"] = "凄凉之地的阿古斯之醒",
    ["O"] = "为凄凉之地的菲莉希蒂·佩瑞诺德收集4撮亡灵劫掠者的骨髓、2瓶恐怖飞鸟的血和一袋燃刃术士的血石粉。",
    ["D"] = "要让扎拉丝莉娅说出真相，我们需要一种特殊的吐真血清。我离开庄园前本该拿上一瓶，但我相信我们能在凄凉之地弄到必要材料。\n\n我需要四撮骨髓——附近峡谷里的骷髅身上很容易弄到。还需要两瓶血：秃鹫的就行。最后，从下面那些召唤者手里弄一袋血石粉。\n\n我知道我说过血石会被用来施展强大的邪恶魔法——别担心，不是给我用的。至少不是我个人要用。",
  },
  [26531] = {
    ["T"] = "凄凉之地的阿古斯之醒",
    ["O"] = "审问扎拉丝莉娅。",
    ["D"] = "好了。我会暂时解除变形并给她灌下血清；你来问那些棘手的问题。准备好了吗？\n\n喝下去吧，扎拉丝莉娅！飞艇来啦！张嘴！不然你就永远吃草吧！",
  },
  [26532] = {
    ["T"] = "凄凉之地的阿古斯之醒",
    ["O"] = "找到阿古斯之醒的洞穴藏身处，一路杀到传送法阵。然后使用传送器寻找斯罗金。",
    ["D"] = "我们现在有目标了：斯罗金。干掉他，阿古斯之醒也许就会自行崩溃。或者被燃烧军团其他分裂组织撕成碎片。不管怎样，都能解决我们眼前的问题。\n\n我得先处理扎拉丝莉娅，才能和你会合。杀穿阿古斯之醒的藏身处，找到这个传送法阵。等我处理完她，就能占卜并加入你，不管它通向哪里。如果还有你信得过的人能叫来帮忙，也许你该这么做。只帮我一个忙，别在我赶到之前杀掉斯罗金！",
  },
  [27230] = {
    ["T"] = "需要帮助的侏儒",
    ["O"] = "追踪燃刃信使，把他的信带给凄凉之地的迪比·曲线。",
    ["D"] = "我知道我看起来也许不怎么样，但这座镇子可是我从无到有建起来的！照看我的居民是我的职责，而现在我需要你的帮助！\n\n我的一名工程师温克尔·螺桶出去补给后就再也没回来。我担心燃刃氏族可能抓住了他。\n\n我的情报显示，他们的一名信使正要把一封信送到雷斧堡垒的首领手里。那封信可能包含温克尔下落的信息。你大概能在堡垒周围找到那个信使，所以动作快点，把那封信带给我！",
  },
  [27233] = {
    ["T"] = "需要帮助的侏儒",
    ["O"] = "把5份暗影精华吸入恍惚增强器，然后回到曲线岗哨的伊科克·巧补那里。",
    ["D"] = "好消息是我们有了护目镜，坏消息是它们没电了！看来在海底泡了几年真的会把电池耗光。幸好我知道一个给它们充能的好地方。\n\n把它们带到东北边的萨格隆。你会在那里找到一些能量充沛的暗影元素。把它们的能量吸入护目镜，然后带回来给我。",
  },
  [27234] = {
    ["T"] = "需要帮助的侏儒",
    ["O"] = "使用充能的恍惚增强器催眠一名燃刃氏族成员，让他告诉你温克尔·螺桶的位置。如果成功，就回到曲线岗哨向迪比·曲线报告。",
    ["D"] = "恍惚增强器已经充能完毕，可以用了！把它带到雷斧堡垒，对那里的一个燃刃成员使用。我不能保证催眠能持续多久，所以赶快问问题。\n\n如果你问出了他的位置，立刻告诉迪比，好让我们协调救援行动。祝你好运，$N，把温克尔带回家！",
  },
  [27235] = {
    ["T"] = "需要帮助的侏儒",
    ["O"] = "在凄凉之地的雷斧堡垒找到温克尔·螺桶。",
    ["D"] = "这么说，你催眠的燃刃成员说温克尔被关在雷斧堡垒南侧的一个洞穴里？如果这是真的，我们必须赶在他们把他转移到主牢房前行动。\n\n不过要小心，燃刃氏族不会轻易放人。我希望自己能抽出些守卫，但这件事只能交给你了，$N。把温克尔平安带回家。",
  },
  [27236] = {
    ["T"] = "需要帮助的侏儒",
    ["O"] = "护送温克尔·螺桶离开雷斧堡垒。如果成功，向迪比·曲线报告。",
    ["D"] = "是迪比派你来的吗？我被困在这个洞里好几天了。我想过直接冲出去，但我只是个胆小的侏儒。不过既然你来了，我们就有机会离开这里了！带路吧，$R！",
  },
  [27237] = {
    ["T"] = "终结恐惧",
    ["O"] = "在凄凉之地内为瑟卡布斯库营地的斯特雷克杀死8只恐怖飞鸟。",
    ["D"] = "我们的商队穿越凄凉之地时，经常面临半人马和本地野兽的伏击。不知为什么，凄凉之地的恐怖飞鸟特别喜欢偷我们运送的生肉。几次得手后，它们的袭击越来越大胆。你能帮我削减它们的数量，好让商队安全些吗？",
  },
  [27239] = {
    ["T"] = "小鬼的吩咐",
    ["O"] = "从凄凉之地玛诺洛克集会所的希瑞娜那里取回地狱历书。",
    ["D"] = "下一个任务比上一个难多了。也许你还有时间被烧成灰！\n\n燃刃氏族在玛诺洛克集会所的废墟中有明显据点，就在从葬影村向东延伸的道路旁。我相信这里其他人会给你一些平凡的任务，让你去处理那里的恶魔，但我们只关心其中一个。\n\n魅魔希瑞娜拥有这位面上唯一一本地狱历书。我们需要它。去拿来！",
  },
  [27240] = {
    ["T"] = "小鬼的吩咐",
    ["O"] = "在凄凉之地东南部的破影峡谷寻找一个强大的恶魔。",
    ["D"] = "你也许在想，我怎么知道该让你做什么。那是因为我知道扎卡拉在想什么。这是怎么做到的？我告诉你——这是魔法。\n\n扎卡拉用远超你那可怜$C脑袋理解范围的魔法技巧，确定你要找的恶魔就在凄凉之地东南部一条隐秘的峡谷里。我曾受前任主人之命去过那里。它叫破影峡谷。\n\n所以，出发吧，去找那个大坏恶魔！",
  },
  [27241] = {
    ["T"] = "破影峡谷",
    ["O"] = "回到凄凉之地葬影村的扎卡拉和皮普乔特那里。",
    ["D"] = "你没有找到强大的恶魔，反而发现了一座由燃刃氏族建造的堡垒。入口被严密封锁，你暂时看不到进入的方法。\n\n如果那个恶魔在这里，它一定就在堡垒里面。你得回到扎卡拉和皮普乔特那里，把这个进展告诉他们。",
  },
  [27243] = {
    ["T"] = "发狂的食腐鸟",
    ["O"] = "在科多兽坟场内杀死8只食腐恐魔。",
    ["D"] = "成为后来者的食物，是生命循环中自然的一部分，无论是在泥土中喂养蠕虫，还是让食腐鸟啄食你的骨骸。\n\n我相信科多兽内心深处明白这一点，所以它们才会来到这里的坟场。\n\n然而，以科多兽尸体为食的食腐秃鹫数量太多，也太过凶暴。它们啄咬抓挠那些仍然活着的科多兽，让它们最后的日子饱受痛苦。\n\n削减秃鹫的数量，$N，恢复这片圣地的平衡。",
  },
  [27244] = {
    ["T"] = "硬壳美味",
    ["O"] = "从凄凉之地海岸的干钳龙虾人身上收集巨大的干钳蟹爪，然后回到幽灵岗哨的哈诺尔那里。",
    ["D"] = "幽灵岗哨的气氛常常很沉重，这和下方坟场的性质有关。牛头人见证科多兽生命的终结是很痛苦的，但我们知道这必须发生。\n\n唯一能温暖任何灵魂的，就是一锅美味而朴实的海鲜炖汤。如果我能弄到一些干钳蟹爪，就能为大家做一顿可口的饭。\n\n你愿意去海岸，从那里的干钳龙虾人身上给我收集一些吗？越大越好！",
  },
  [27247] = {
    ["T"] = "幽暗绝壁",
    ["O"] = "把大地石板带给凄凉之地幽暗绝壁的凯莉·野性图腾。",
    ["D"] = "你从塔霍达营地救回的大地母亲石板已经准备好前往它的新家。\n\n我的氏族在凄凉之地建立了一处新的定居点，名叫幽暗绝壁。你可以在灵魂高地西北方的山丘中找到一条蜿蜒而上的小路。它从一根蓝色图腾旁边开始。\n\n把石板带给凯莉·野性图腾。她是那里的常驻萨满，会用它祝福大地。",
  },
  [27248] = {
    ["T"] = "给幽灵岗哨的消息",
    ["O"] = "前往凄凉之地中部的幽灵岗哨，与费古尔·双刃谈一谈。",
    ["D"] = "科卡尔半人马是游牧民族，就像牛头人过去一样。我们刚在幽暗绝壁安顿下来，科卡尔就迁来，在村庄下方山脚下搭起了帐篷。我们没有足够的战士抵抗他们，凯莉把局势的消息送回了雷霆崖。我真想知道它为什么从没送到……\n\n我们已经不再需要大地母亲石板了。我可以把它带回给玛加萨。你能继续前往幽灵岗哨吗？我的朋友费古尔·双刃应该知道这里发生了什么。",
  },
  [27250] = {
    ["T"] = "掠夺掠夺者",
    ["O"] = "为幽暗绝壁的杰文·野性图腾收集8件珍贵的牛头人遗物。",
    ["D"] = "科卡尔不仅杀死了幽暗绝壁的所有人，还洗劫了村庄，把许多我们珍贵的遗物带到了他们的营地。我想把那些东西拿回来！\n\n穿过幽暗绝壁，沿小路下到科卡尔村。你会在他们的棚屋和营地里找到被偷走的牛头人遗物。尽可能多地收集起来，带回来给我。",
  },
  [27253] = {
    ["T"] = "巨大利润",
    ["O"] = "从凄凉之地内最大的科多兽骨架中收集3个化石化胆囊，然后回到凄凉之地科米克小屋的比布利·法兹巴克那里。",
    ["D"] = "西南方科多兽坟场周围到处都有真正巨大的科多兽骨架，它们一定是在凄凉之地变成……现在这样之前，远古时代生活在这里的。我认为它们体型巨大的关键在于吃了什么，而我需要化石化的胆囊样本来证明我的理论。\n\n如果我是对的，而且能培育出那种规模的野兽，谁知道人们会花多少钱来看这些东西！？也许可以建成某种公园……总之，胆囊很难找，所以睁大眼睛。",
  },
  [27254] = {
    ["T"] = "幽暗城的材料",
    ["O"] = "把10只怨怒之爪和10只怨怒之角带给凄凉之地的安妮·格里姆。",
    ["D"] = "我在这里的任务之一，是替幽暗城里一位强大的炼金师萨多雷·格雷夫收集一些材料。马尔温似乎觉得既然我们已经在这里了，这就是轻松入袋的钱。他完全不在乎我们本来就人手不足。\n\n他清单上的前几样东西应该还算好弄，任何帮忙的人都能拿到一大笔钱。\n\n我需要凄凉之地东北远处那些怨怒萨特的角和爪。把它们带回来给我，我们就能开始处理清单的其他部分。",
  },
  [27255] = {
    ["T"] = "幽暗城的材料",
    ["O"] = "把7瓶蝎群毒液和3张老科多兽皮带给凄凉之地的安妮·格里姆。",
    ["D"] = "萨多雷清单上的下一项是……让我看看……嗯。哦，在这里。\n\n很简单，但他的说明相当明确。他需要蝎群的毒液，还需要一些科多兽皮。小字注明他需要特定生物：毒液可以来自任何蝎群，但兽皮必须来自老科多兽，不能是垂死的或远古的。\n\n炼金师啊，我跟你说，他们想要的有些东西……就是古怪。",
  },
  [27256] = {
    ["T"] = "幽暗城的材料",
    ["O"] = "把10个地狱犬脑、10片虚空之翼和10瓶末日守卫之血带给凄凉之地的安妮·格里姆。",
    ["D"] = "这是最后一批物品，我不撒谎，这可不好看。我也预计这会比其他物品多花你一点时间。\n\n坏消息是这样的。萨多雷说他需要：十个脑子，来自法力吞噬者、法师猎手或魔能猎手都行。然后是十片虚空之翼，来自虚空少女、姐妹或女巫。还有……十瓶末日守卫之血，来自末日守卫队长或领主。\n\n很简单，对吧？唉……如果你想跳过这一项，我也能理解。",
  },
  [27257] = {
    ["T"] = "幽暗城的材料",
    ["O"] = "把萨多雷的包裹送到幽暗城炼金房的萨多雷·格雷夫那里。",
    ["D"] = "要拿到报酬，你得回幽暗城亲自和萨多雷谈谈。把这包补给交给他，就足够让你拿到钱了。\n\n别担心，等我回去后，还是会替你美言几句。我应该不会在凄凉之地待太久了。",
  },
  [27258] = {
    ["T"] = "虚空残余",
    ["O"] = "从玛诺洛克集会所内的恶魔身上收集10份虚空残余。",
    ["D"] = "在这里西南方，你会找到玛诺洛克集会所，那是一处危险、被邪能污染的地方，燃刃氏族正在把恶魔召唤到这片土地上。\n\n当恶魔被从它们的本源位面撕扯到艾泽拉斯时，它们会带来奇异的虚空残余，我正在研究这些东西。你能收集一些样本吗？",
  },
  [27259] = {
    ["T"] = "给曲线的补给",
    ["O"] = "把曲线补给箱带到雷斧堡垒西南方的曲线岗哨。",
    ["D"] = "在这些危险的土地上，我们联盟成员必须随时准备帮助盟友。出于这个精神，我需要你把一个包裹送到那座新的侏儒定居点，曲线岗哨。我们收到他们的旅店老板提尼·引线传来的消息，说他的食物和饮料补给快用完了。\n\n曲线岗哨离这里不算太远。你可以在这里西南方、越过雷斧堡垒后找到它。",
  },
  [27260] = {
    ["T"] = "恳求归返",
    ["O"] = "从葬影村东北方的旋风风行者身上收集4份风暴精华。",
    ["D"] = "我的家和我的心都在辛特兰，和恶齿部族在一起，但我因为教一些枯木表亲萨满之道更黑暗的一面而被放逐。我深深后悔这些行为，如今只想再次感受脚下的青草，看见树木摇曳，和家人共度夜晚。\n\n为了做到这一点，我准备向恶齿原始祭司献上一根拥有强大力量的闪电图腾，希望你能帮我完成这件事。\n\n这里东北方有旋风风行者，那些强大的空气元素在这片土地上游荡。它们体内蕴含着一股我能导入图腾的狂怒。请收集它，带回来给我。",
  },
  [27261] = {
    ["T"] = "恳求归返",
    ["O"] = "从凄凉之地各处的老雷霆蜥蜴身上收集10只蓄能角。",
    ["D"] = "我还需要最后一样东西才能制作图腾。凄凉之地周围可以找到老雷霆蜥蜴，它们最年长、最强壮，也有最大的角。多年流经它们身体的能量能让我制作一根强大的闪电图腾，作为献给原始祭司的礼物。你能帮我收集一些吗？",
  },
  [27262] = {
    ["T"] = "最新鲜的油脂",
    ["O"] = "在葬影村沿岸为马尔温·尖愿收集7块逆戟鲸脂肪。",
    ["D"] = "最适合灯油和炸药的油脂，有些来自凄凉之地海岸边的逆戟鲸。牛头人和巨魔都拒绝帮我弄它们的脂肪，说是什么尊重仪式动物之类的。所以我需要像你这样勇敢的冒险者替我弄脏双手！你能进海湾帮我收集脂肪吗？",
  },
  [27263] = {
    ["T"] = "最仁慈的行为",
    ["O"] = "在科多兽坟场内杀死8头垂死的科多兽。",
    ["D"] = "人们并不完全理解，为什么卡利姆多的科多兽在感到漫长生命即将终结时，会如此拼命地想抵达这里的坟场，但它们的旅程就像日出一样可预见。\n\n然而，有些科多兽病得很重，在土地上痛苦徘徊，无法跨入大地母亲的怀抱。\n\n我们能做的最仁慈之事，就是引导它们走向她。你愿意替我做这件事吗？",
  },
  [27264] = {
    ["T"] = "通缉：凯科",
    ["O"] = "在凄凉之地葬影村外的海湾找到并杀死凯科。",
    ["D"] = "捕鱼是维持村庄食物供应的重要部分，但海湾里有一头我们称作凯科的巨大逆戟鲸，它一直掀翻我们的渔船，还让巨魔和牛头人都受了伤。必须杀死这头蛮横的逆戟鲸，我们才能继续养活尽可能多的人。\n\n把凯科死亡的证据带给葬影村的吉纳尔齐伦。",
  },
  [27265] = {
    ["T"] = "通缉：威尔菲兹·银钻",
    ["O"] = "在凄凉之地玛诺洛克集会所以北找到并杀死威尔菲兹·银钻。",
    ["D"] = "我昔日的学徒跑去协助燃烧军团，还带走了关于我们在这里计划的宝贵知识。这种傲慢绝不能容忍！我要他的头颅带到我面前——必要的话就插在长矛上！他最后一次被看见，是在玛诺洛克集会所以北采蘑菇。\n\n——伊穆·铜咒",
  },
  [27504] = {
    ["T"] = "克里斯蒂的递送服务",
    ["O"] = "把科迪带给凄凉之地曲线岗哨的奈莱·天月。",
    ["D"] = "嗯，科迪经历了那场小冒险后看起来没事；有点受惊，但除此之外没有受伤。我只是不知道还能不能继续把科迪留在萨兰纳尔，他总是惹出太多麻烦。\n\n如果你不介意，能不能再帮我照看他一会儿，把他带给我的一位朋友？奈莱·天月住在凄凉之地的曲线岗哨。她对各种猫都特别温柔，我相信她会非常乐意照看我的小科迪。\n\n凄凉之地离这里有点远，但你经历过这些事之后，这对你应该不成问题！",
  },
  [27604] = {
    ["T"] = "给守护者玛兰迪斯的委托",
    ["O"] = "守护者玛兰迪斯要你使用炼金术技能制作5瓶坚韧药剂，并把订单交给凄凉之地尼耶尔前哨站的守护者玛兰迪斯。",
    ["D"] = "我奉塞纳里奥议会之命来到这里执行一项重要任务，但这片土地让我很不舒服。我的关节隐隐作痛，附近恶魔的邪能污染也让我毛皮发麻。\n\n我注意到你是一名熟练的炼金师。如果你能为我制作一批坚韧药剂，它会帮助我在任务完成前抵御这片土地的污秽。你怎么说？",
  },
  [27629] = {
    ["T"] = "给塔卡塔·钢刃的委托",
    ["O"] = "马尔温·尖愿要你使用炼金术技能制作5瓶坚韧药剂，并把订单交给凄凉之地幽灵岗哨的塔卡塔·钢刃。",
    ["D"] = "我奉皇家药剂师协会之命来到这里执行一项重要任务，但随部落来到这里的乌合之众似乎觉得我能处理每一个小请求。\n\n塔卡塔·钢刃是某种兽人战士，声称他的关节疼痛，附近恶魔的邪能污染让他浑身不自在。既然你是个还算熟练的炼金师，我要你为他制作一些坚韧药剂，把这个请求从我手里处理掉。",
  },
  [27654] = {
    ["T"] = "给莫特利·重铜的委托",
    ["O"] = "玛克斯顿·斯坦恩要你使用锻造技能制作2把亮闪闪的钢匕首，并把订单交给凄凉之地曲线岗哨的莫特利·重铜。",
    ["D"] = "欢迎来到荒原，铁匠。我忙得手指都快磨到骨头，只为让这个小小前哨站有足够的护甲和武器，尤其是现在那些恶魔就在我们门口！\n\n曲线岗哨那边的侏儒也开始下订单了，但我实在没时间处理。如果你愿意帮个忙，就打造几把亮闪闪的钢匕首，送给那边的莫特利·重铜。",
  },
  [27679] = {
    ["T"] = "给安妮·格里姆的委托",
    ["O"] = "塔卡塔·钢刃要你使用锻造技能制作2把亮闪闪的钢匕首，并把订单交给凄凉之地葬影村的安妮·格里姆。",
    ["D"] = "欢迎来到荒原，铁匠。我兄弟是个铁匠，真希望他能把手艺带到这里来。幽暗城来的一个药剂师想买几把匕首，但葬影村的巨魔主要做斧头。如果你有本事打造亮闪闪的钢匕首，葬影村的安妮·格里姆会需要你的服务。",
  },
  [28069] = {
    ["T"] = "给麦克·扎普的委托",
    ["O"] = "麦克·扎普要你使用烹饪技能制作10份大块的熊排，并把订单交给凄凉之地艾瑟雷索的麦克·扎普。",
    ["D"] = "我来到凄凉之地，是因为圣光召唤我拜访这处神圣遗迹，但我想家。具体来说，我想念家乡所有最好的食物，比如一份热腾腾、多汁的大块熊排。\n\n我知道凄凉之地没有熊，但如果你能弄来一些熊肉，给我烹制几份熊排，我会真心感激你。",
  },
  [28085] = {
    ["T"] = "给马尔温·尖愿的委托",
    ["O"] = "马尔温·尖愿要你使用烹饪技能制作10份大块的熊排，并把订单交给凄凉之地葬影村的马尔温·尖愿。",
    ["D"] = "我来到凄凉之地，是因为皇家药剂师协会派我执行重要研究，但我想家。具体来说，我想念家乡所有最好的食物，比如一份热腾腾、多汁的大块熊排。\n\n我知道凄凉之地没有熊，但如果你能弄来一些熊肉，给我烹制几份熊排，你就能让这片该死的荒原稍微好忍受一点。",
  },
  [28417] = {
    ["T"] = "给安妮·格里姆的委托",
    ["O"] = "安妮·格里姆要你使用附魔技能制作1根强效秘法杖，并把订单交给凄凉之地葬影村的安妮·格里姆。",
    ["D"] = "真是粗心，我们收拾行装来到这里时，我把魔杖忘在幽暗城了。或者也可能是落在了地精商队上。不管怎样，请替我制作一根强效秘法杖，前提是你确实是附魔师。",
  },
  [28442] = {
    ["T"] = "给霍恩尼兹的委托",
    ["O"] = "迪比·曲线要你使用工程学技能制作20个实心炸弹，并把订单交给凄凉之地科多兽坟场的霍恩尼兹。",
    ["D"] = "欢迎来到曲线岗哨。我从零开始建起了这里，现在还有很多事要做。\n\n说起来，你是工程师，对吧？我能从你手指上那些奥金扳手磨出的茧看出来。愿意接一份开放订单吗？\n\n有个住在科多兽坟场下面的地精想买一些实心炸弹。我对地精工程师有健康的职业敬意，但这家伙是个炼金师……我不知道他到底想拿炸药干什么，所以一直没处理这份订单。如果你想接，它就是你的了！",
  },
  [28467] = {
    ["T"] = "给霍恩尼兹的委托",
    ["O"] = "图克要你使用工程学技能制作20个实心炸弹，并把订单交给凄凉之地科多兽坟场的霍恩尼兹。",
    ["D"] = "欢迎来到葬影村。你是工程师，对吧？我能从你手指上那些奥金扳手磨出的茧看出来。愿意接一份开放订单吗？\n\n有个住在科多兽坟场下面的地精想买一些实心炸弹。我对地精工程师有健康的职业敬意，但这家伙是个炼金师……我不知道他到底想拿炸药干什么。如果你想要这份订单，它就是你的了！",
  },
  [28501] = {
    ["T"] = "给斯米德·瑟卡布斯库的委托",
    ["O"] = "斯米德·瑟卡布斯库要你使用钓鱼技能收集20条黑口鱼，并把订单交给凄凉之地瑟卡布斯库营地的斯米德·瑟卡布斯库。",
    ["D"] = "其他地精在这里挖土、砍树，或者为了利润把什么东西炸上天。业余货色。\n\n你不能忽视陆地尽头和海水开始的地方。利润也是从那里开始的！只要知道该捕什么，海里到处都是金子。比如黑口鱼。炼金师会为它付高价。\n\n给我带来20条黑口鱼，我就让这些踩泥巴的家伙知道，聪明钱来自浪里。",
  },
  [28534] = {
    ["T"] = "给霍恩尼兹的委托",
    ["O"] = "霍恩尼兹要你使用草药学技能采集20株墓地苔，并把订单交给凄凉之地科多兽坟场的霍恩尼兹。",
    ["D"] = "你喜欢谜题吗，$C？我喜欢和幽灵、坟墓有关的谜题。\n\n我已经在研究长骨谷里栖息的半人马幽灵，但我也想更多了解墓地苔。为什么它只在坟墓附近生长？我必须知道！\n\n如果你能给我带来一捆墓地苔，我就能解开这个谜团！",
  },
  [28576] = {
    ["T"] = "给比布利·法兹巴克的委托",
    ["O"] = "詹奈特·霍莫斯要你使用制皮技能制作2副野人护肩，并把订单交给凄凉之地科米克小屋的比布利·法兹巴克。",
    ["D"] = "在尼耶尔前哨站这样的小前哨里，我们每个人都要兼顾不止一份工作。比如我负责接收和传递消息。我这里有一条你可能感兴趣的消息。\n\n有个住在科米克小屋那种破棚里的地精，一直四处打听制皮师。他声称自己因为“商业原因”需要新的护肩。不管那是什么意思。\n\n这也许是个赚点钱的好机会？地精的口袋很深……至少我听说是这样。",
  },
  [28601] = {
    ["T"] = "给比布利·法兹巴克的委托",
    ["O"] = "纳夫要你使用制皮技能制作2副野人护肩，并把订单交给凄凉之地科米克小屋的比布利·法兹巴克。",
    ["D"] = "在幽灵岗哨这样的小前哨里，我们都会出力帮助凄凉之地的其他人。这意味着我手上的订单多到处理不过来，也需要你的帮助。\n\n有个住在科米克小屋那种破棚里的地精，一直四处打听制皮师。他声称自己因为“商业原因”需要新的护肩。不管那是什么意思。\n\n这也许是个赚点钱的好机会？地精的口袋很深……至少我听说是这样。",
  },
  [28617] = {
    ["T"] = "给比布利·法兹巴克的委托",
    ["O"] = "比布利·法兹巴克要你使用剥皮技能采集5张重毛皮，并把订单交给凄凉之地科米克小屋的比布利·法兹巴克。",
    ["D"] = "嘿，剥皮师。我有份活给你。别问这是做什么用的。真的，别问。\n\n你只需要知道我需要重毛皮。又大又厚，很难弄到……对某个正在进行的项目来说完美。\n\n我向你保证，完全无害。大概吧。",
  },
  [28644] = {
    ["T"] = "给迪比·曲线的委托",
    ["O"] = "迪比·曲线要你使用采矿技能采集20块铁锭，并把订单交给凄凉之地曲线岗哨的迪比·曲线。",
    ["D"] = "我的前哨站进展得很顺利……除了……我们的铁锭储备已经危险地偏低了。\n\n你能再给我带一些来吗？不需要太多，只要足够把门把手留在门上，也让墙壁不会被人一靠就倒。",
  },
  [28668] = {
    ["T"] = "给海维拉尼的委托",
    ["O"] = "海维拉尼要你使用采矿技能采集20块铁锭，并把订单交给凄凉之地葬影村的海维拉尼。",
    ["D"] = "我一直靠给这里的巨魔供应斧头谋生，但随着部落到来，我的铁锭储备已经危险地偏低了。\n\n你能再给我带一些来吗？不需要太多，只要足够把斧刃固定在柄上，也让箭头保持锋利。",
  },
  [28690] = {
    ["T"] = "给安东修士的委托",
    ["O"] = "安东修士要你使用裁缝技能制作1件力量法袍，并把订单交给凄凉之地尼耶尔前哨站的安东修士。",
    ["D"] = "$C……你是裁缝，对吧？朋友，我私下问你。在修道院里，某些法袍是……不受鼓励的。他们称之为“虚荣”，“太世俗”。但在这里，在开阔天空与阴影笼罩的太阳下，我以那些修道院长从未教过的方式感受到圣光。\n\n如果你的双手足够灵巧，就为我制作一件力量法袍吧。不是为了骄傲，而是为了证明虔敬与力量并不必然为敌。除了你我，无需让任何人知道！",
  },
  [28717] = {
    ["T"] = "给扎卡拉的委托",
    ["O"] = "皮普乔特要你使用裁缝技能制作1件力量法袍，并把订单交给凄凉之地葬影村的扎卡拉。",
    ["D"] = "$C……你是裁缝，对吧？终于有人能把我的主人打扮成她应有的样子了！没错，扎卡拉需要一件新法袍。不是随便什么法袍。是一件力量法袍！你觉得自己能搞定吗，$R？快动手！\n\n对，别担心，你会拿到报酬的。",
  },
  [8970] = {
    ["T"] = "我看见奥卡兹岛出现在你的未来……",
    ["O"] = "从斯塔莎兹纳迦那里收集20份血藻，然后回到黑石山内的伯德雷那里。",
    ["D"] = "正如我刚才所说，$c，我活着的时候曾经想过当个占卜师。不过，这行并没有你想象中那么有利可图，主要是因为它很危险，而且材料又稀有又昂贵。不过，我懂得足够多，能确定护符最后一块碎片的位置，也能找到我昔日同伴的灵魂。\n\n这就是你该出场的地方，$N。我需要你前往尘泥沼泽海岸外的奥卡兹岛，从住在那里的斯塔莎兹纳迦身上收集血藻。",
  },
  [26117] = {
    ["T"] = "追逐暗影",
    ["O"] = "在尘泥沼泽收集一条珊瑚鲨，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "听着，$C，我觉得你有足够的胆量和韧劲，能接下一名钓鱼人能遇到的最艰难任务之一——钓鲨鱼。\n\n没错，在尘泥沼泽浑浊的深水里，有的是鲨鱼等着被钓上来。它们又大又凶，会给你一场很久都忘不了的搏斗。你觉得自己有本事和深水中的利齿较量吗？",
  },
  [26405] = {
    ["T"] = "战斗的召唤：尘泥沼泽",
    ["O"] = "在尘泥沼泽找到并杀死5名部落成员。",
    ["D"] = "尘泥沼泽属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26406] = {
    ["T"] = "战斗的召唤：尘泥沼泽",
    ["O"] = "在尘泥沼泽找到并杀死5名联盟成员。",
    ["D"] = "尘泥沼泽属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26416] = {
    ["T"] = "通往塞拉摩的门",
    ["O"] = "在诅咒之地的新黑暗之门附近收集3块第一座黑暗之门碎片，然后回到塞拉摩的吉安娜·普罗德摩尔那里。",
    ["D"] = "又见面了，$N。我相信我的城市有时对你来说是个有用的传送地点吧？如果是这样，你想不想改为制造一道传送门？这次我交给你的任务要困难得多，但除了法术之外，我还为你准备了另一份奖励。\n\n首先，我需要你前往诅咒之地的黑暗之门。那座被诅咒的传送门是通往兽人故乡德拉诺的入口，但它实际上是第二座黑暗之门。最初的那座被大法师卡德加摧毁，作为阻止第二次战争中入侵兽人的尝试。你仍能在新传送门附近找到旧门的碎片。给我收集三块小碎片，然后我们再继续。",
  },
  [26417] = {
    ["T"] = "通往塞拉摩的门",
    ["O"] = "从安戈洛环形山周围收集5块绿色能量水晶，然后回到塞拉摩的吉安娜·普罗德摩尔那里。",
    ["D"] = "做得好，这些碎片非常适合你的王——\n\n<吉安娜女士咳嗽了一声。>\n\n差点忘了要保密！接下来，我们需要五块安戈洛环形山的绿色能量水晶。它们散落在那片区域各处。如果你从没去过，可以在塔纳利斯西南部找到下去的路。不过也许直接施放缓落术跳进环形山会更有趣！",
  },
  [26418] = {
    ["T"] = "通往塞拉摩的门",
    ["O"] = "深入黑石深渊，击败七贤以取得塞斯雷尔的典籍，然后回到塞拉摩的吉安娜·普罗德摩尔那里。",
    ["D"] = "好了，该揭示这些旅行的目的了！除了教你如何制造通往塞拉摩的传送门外，我还要赠给你一件头饰，可以说是一顶王冠。好吧，我想这礼物也不算太慷慨，毕竟大部分材料都是你自己收集的，但我手头没有这些东西！我不久前想出了这顶王冠的构想。它使用被虚空触碰过的石头，并用粉碎的能量水晶为其注入力量。我希望成品会不错！\n\n但我们还需要一个组件。像这样把石头结合在一起并不是常识，但我读到一位名叫塞斯雷尔的强大巫师写过一本书，里面有详细说明。他曾住在暗炉城——也就是黑石深渊。如果你能前去取回那本典籍，我们就能完成这顶王冠。",
  },
  [26424] = {
    ["T"] = "塞拉摩之眼",
    ["O"] = "从东部王国悲伤沼泽海岸线上的淤泥蟹身上取得14只淤泥蟹眼，然后回到塞拉摩的吉安娜·普罗德摩尔那里。",
    ["D"] = "啊，你好，$C！我有个提议，你想不想能够传送到塞拉摩？我看得出你是一位学识相当丰富、旅行经验也不少的法师，所以我毫不怀疑教会你会很容易。\n\n首先，我需要你前往遥远的东部王国悲伤沼泽，一直走到它的海岸线。在那里你会找到一些淤泥蟹。收集十四只它们的眼睛，而且要确保没有损坏！等你回来后，我会解释下一步为什么需要这些。",
  },
  [26425] = {
    ["T"] = "奥术聚合体",
    ["O"] = "在塞拉摩塞拉摩堡垒的地下室使用奥术视界药剂，然后击败元素聚合体。之后回到塞拉摩的吉安娜·普罗德摩尔那里。",
    ["D"] = "很好，$N。至于你为什么需要这些眼睛。你听说过元素聚合体吗？我很怀疑你听过！它们是被灌注元素能量的奥术构造体，可以化作元素的形态。它们本身并不是元素，但很难分辨。\n\n嗯，塞拉摩这里，塞拉摩堡垒的地下室里就有一个。我不知道是谁把它放在那里的，但我担心它最终可能会造成麻烦。你收集的这些眼睛应该能显现那个“元素”，让你击败它。虽然我可以亲自击败它，但我觉得与它战斗也许能让你获得一些有用的见解。祝你好运！我完全相信你。",
  },
  [26426] = {
    ["T"] = "偏僻臭水坑",
    ["O"] = "从卡利姆多南部尘泥沼泽的尘泥鳄鱼身上取得14只尘泥鳄鱼眼，然后回到斯通纳德的洛林·跃火那里。",
    ["D"] = "嘿，你，看起来像个有点学识的$c。终于有个不是迟钝兽人的家伙了！你知道元素聚合体是什么吗？不知道？嗯，那也没多有学识……\n\n<洛林停下来，挪了挪桌上的东西。>\n\n这样吧，如果你帮我，而且别问问题，我就教你怎么传送到斯通纳德，成交吗？这里也许是个偏僻臭水坑，但至少位置很有用。\n\n去遥远的尘泥沼泽，收集十四只尘泥利齿鳄鱼眼。必须完好无损！你可以在沼泽南部找到它们。",
  },
  [27282] = {
    ["T"] = "通缉：屠龙者",
    ["O"] = "在尘泥沼泽的布洛格洞穴找到布洛格。",
    ["D"] = "布洛格需要强壮的战士和厉害的魔法人来帮助夺回石槌。那个又胖又懒的霸王什么都不做，但我可以。到沼泽西南角的一处洞穴里找到布洛格。",
  },
  [27283] = {
    ["T"] = "漂流者",
    ["O"] = "安全护送阿盖尔·威尔克斯前往塞拉摩。",
    ["D"] = "我先是因为一点小分歧被自己的船员赶了出去，只带着这条小破艇被扔进暴风雨里。然后一醒来，就到了这片被圣光遗弃的沼泽！\n\n我只想回到海滩上的小屋，一个人待着。抱怨够了！我需要喝一杯！最近的酒馆在哪儿，嗯？",
  },
  [27286] = {
    ["T"] = "用火烧掉",
    ["O"] = "进入黑雾洞穴，点燃8个黑雾卵囊。",
    ["D"] = "自从我们搬来这里，食人魔就开始失踪。走太远，蜘蛛就抓你。我们要活下去，就得赶走坏虫子。拿上我的火把，烧掉它们的蛋。",
  },
  [27291] = {
    ["T"] = "通缉：克鲁尔王",
    ["O"] = "在石槌废墟以南找到克鲁尔王并击败他。",
    ["D"] = "大鳄鱼吃食人魔！家人失踪。不要往石槌南边走，不然克鲁尔王会抓你。你杀鳄鱼，就有亮晶晶。",
  },
  [27292] = {
    ["T"] = "通缉：克鲁尔王",
    ["O"] = "在石槌废墟以南找到克鲁尔王并击败他。",
    ["D"] = "有人在尘泥沼泽的支流中见到一只巨大的鳄鱼，它会把士兵和旅人一并咬走。食人魔很有想象力地给它取名叫“克鲁尔王”。\n\n猎杀这头怪物。它最后一次被看见是在石槌废墟以南。",
  },
  [27293] = {
    ["T"] = "坠落的飞艇",
    ["O"] = "侦察蕨墙村东南方区域，找到斥候加克看到的坠落飞艇。",
    ["D"] = "你看见了吗，$c？一道火光爆开，紧接着我就看到正东南方的地平线上，一艘飞艇从空中翻滚着坠了下来！\n\n我已经请求派一支侦察队去调查发生了什么，但那些繁文缛节全挡在前面。\n\n你能不能去调查坠毁地点，看看有没有幸存者？",
  },
  [27294] = {
    ["T"] = "坠落的飞艇",
    ["O"] = "侦察塞拉摩码头以西区域，找到守望者华莱士看到的坠落飞艇。",
    ["D"] = "你看见了吗，$c？一道火光爆开，紧接着我就看到正西方的地平线上，一艘飞艇从空中翻滚着坠了下来！\n\n我已经请求派一支侦察队去调查发生了什么，但那些繁文缛节全挡在前面。\n\n你能不能去调查坠毁地点，看看有没有幸存者？",
  },
  [27295] = {
    ["T"] = "比兹尔·链扳究竟在哪里？",
    ["O"] = "从尘泥沼泽比兹尔残骸附近的软泥怪身上搜集线索，查明比兹尔·链扳可能发生了什么。",
    ["D"] = "我在飞艇上的工作很简单：飞过沼泽时盯着有没有龙。我才刚到岗位，下一刻就听到一声巨响，一个箱子砸在我头上！瞬间昏了过去。\n\n我也许是船员里唯一恢复意识的人，但我到处都找不到比兹尔·链扳船长！附近的软泥怪一直吞掉任何能裹住的东西，身上也许有能指向他的线索。搜刮它们，把你找到的东西带给我。",
  },
  [27296] = {
    ["T"] = "抢回货物",
    ["O"] = "从比兹尔残骸周围区域收集8箱飞艇货物。",
    ["D"] = "找到船长之后，公司的下一优先事项就是追回我们的资产！任何在坠毁中幸存、还没被该死软泥怪吸收的东西都是我们的，我们必须拿回来。\n\n我们得从这场灾难里至少抢救出一点利润。去收集散落在周围的幸存货物吧，$n。",
  },
  [27297] = {
    ["T"] = "电击复苏",
    ["O"] = "电醒6名船员，获取更多关于飞艇上可能发生了什么的信息。",
    ["D"] = "现在我们得帮助其他船员。看起来，他们的医疗费用会比付给近亲的赔偿还高。不过……我需要他们帮忙把这些箱子运出沼泽。\n\n拿上这个除颤器，把他们叫醒。顺便看看他们有没有关于比兹尔去向的信息。一次强脉冲应该就够了，正中心脏。",
  },
  [27299] = {
    ["T"] = "嗅出他的踪迹",
    ["O"] = "使用嗅探器MK IV控制器召唤嗅探器，它会带你找到比兹尔。",
    ["D"] = "有了这个嗅探器和你找到的披风，我们就能找到比兹尔。放出嗅探器，它会嗅一嗅披风，然后出发，你跟在后面。用你的生命保护这台装置，因为我们手头没有替代品！\n\n找到船长，把他平安带回我这里。",
  },
  [27300] = {
    ["T"] = "比兹尔与燃刃氏族",
    ["O"] = "把关于比兹尔·链扳的消息带回给希斯·充能。",
    ["D"] = "要不是你刚从那个地狱火手里救了我的命，我什么都不会告诉你。但我欠你这么多，而且我有一部分觉得还能挽回这事。\n\n没错，燃刃氏族雇我把一个巨大的地狱火运到热砂港，至于要拿它做什么，谁知道呢。我确信不会是什么好事。幸运的是，他们预付了钱。我得通知他们发生了什么，但别担心，我袖子里还藏着一个小保险计划。\n\n回头见，蠢货！",
  },
  [27301] = {
    ["T"] = "燃刃档案",
    ["O"] = "把希斯·充能的报告带给蕨墙村的斥候加克。",
    ["D"] = "所以比兹尔背着公司和燃刃氏族合作？那个卑鄙的老鼠混蛋！\n\n这个问题已经不只是公司资源管理不当那么简单了。我觉得你最好把我的报告副本带给你的上级。他们会想知道燃刃氏族究竟走到了什么地步。",
  },
  [27302] = {
    ["T"] = "燃刃档案",
    ["O"] = "把希斯·充能的报告带给塞拉摩的守望者华莱士。",
    ["D"] = "所以比兹尔背着公司和燃刃氏族合作？那个卑鄙的老鼠混蛋！我觉得你最好把我的报告副本带给你的上级。他们会想知道燃刃氏族究竟走到了什么地步。",
  },
  [27905] = {
    ["T"] = "鲜血与荣耀的纽带",
    ["O"] = "向尘泥沼泽塞拉摩岛的吉安娜·普罗德摩尔询问关于兽人的信息。",
    ["D"] = "我听说你有兴趣更多了解兽人。我会小心把这种愿望告诉谁——并不是所有人都原谅了战争中发生的事。\n\n如果你真的想获得对兽人不带偏见的看法，我只信任一个人——吉安娜·普罗德摩尔。\n\n她是尘泥沼泽塞拉摩岛的统治者，也是兽人在联盟中最接近朋友的人。",
  },
  [27917] = {
    ["T"] = "鲜血与荣耀的纽带",
    ["O"] = "回到塞拉摩岛的吉安娜·普罗德摩尔那里，告诉她你了解到的事情。",
    ["D"] = "我相信你现在对我的人民有了更深的理解，$R。我们也许还不会称你为朋友，但请记住，当你在战场上面对兽人时，那将是一场荣耀的挑战。值得你竭尽全力。\n\n回到派你来找我的人那里，把你学到的告诉他们。永别了！",
  },
  [28020] = {
    ["T"] = "深水仪式",
    ["O"] = "与尘泥沼泽的纳特·帕格谈一谈。",
    ["D"] = "没有什么比手握鱼竿、在水边放松更好了，对吧，$N？我知道你同意，因为你是我认识的最投入的$gfishermen:fisherwomen;之一！\n\n说起来，这倒提醒了我——我最近收到纳特·帕格的邀请，要去尘泥沼泽和他钓一会儿鱼。听起来他想和有本事的钓鱼人比比技巧。你绝对是任何钓鱼比赛都该邀请的人。你为什么不去尘泥沼泽看看？",
  },
  [28021] = {
    ["T"] = "深水仪式",
    ["O"] = "尘泥沼泽的纳特·帕格要你使用钓鱼技能钓到20条石鳞鳗和10条板鳞鱼。",
    ["D"] = "我最近有点坐不住，$N。很高兴你来了，因为我一直想让自己的水平再提高一点。不太确定具体该怎么做，不过也许我们可以先来一场友好的比赛？\n\n我一直想看看有没有人能打破我钓石鳞鳗和板鳞鱼的纪录。你想自己试试看吗？",
  },
  [28023] = {
    ["T"] = "深水仪式",
    ["O"] = "黑喉村的维弗拉要你从名叫斯纳皮库斯王的龙虾人身上取回黑喉鱼饵。拿到鱼饵后，把它交给尘泥沼泽的纳特·帕格。",
    ["D"] = "你想要黑喉鱼饵？是的，我们的鱼饵很适合钓鱼。但手工做的鱼饵对黑喉来说很私人。不容易送人。\n\n维弗拉觉得，如果你挣得它，你可以拿走黑喉鱼饵。维弗拉最喜欢的鱼饵被一只又大又坏的龙虾人抢走了。地精叫那只龙虾人斯纳皮库斯王。他在艾萨拉到处游。如果你找到斯纳皮库斯，就从他那里拿回鱼饵，然后你可以留下它。",
  },
  [28024] = {
    ["T"] = "深水仪式",
    ["O"] = "在东瘟疫之地斯坦索姆内的月桂旅店寻找约翰·金凯德的钓具箱，并把它带给尘泥沼泽的纳特·帕格。",
    ["D"] = "我有个朋友死在斯坦索姆的悲剧中。约翰是个好伙伴，他拥有你见过的最棒的一套鱼饵。我知道希望渺茫，但我想知道那些鱼饵是不是还在那里。\n\n约翰拥有城北的月桂旅店。我听说镇上很多地方都烧了，但约翰把他的鱼饵放在一个结实的钓具箱里。应该能挺过火灾。\n\n当然，如果这要求太过分，我也理解。那些废墟现在大概仍然很危险。",
  },
  [28025] = {
    ["T"] = "深水仪式",
    ["O"] = "纳特·帕格要你使用钓鱼技能钓到10条新鲜的熔火颅鱼，并把它们带给尘泥沼泽的他。",
    ["D"] = "这个钓具箱勾起了太多回忆，我得花点时间想想。不过在这期间，我有个请求给你。\n\n拿到这个钓具箱说明你不怕火。嗯，火里才能钓到熔火颅鱼。没错——熔岩钓鱼。\n\n如果你的鱼竿经不起高温，就得和黑铁矮人多待一阵，直到给自己弄到升级装备。",
  },
  [28026] = {
    ["T"] = "深水仪式",
    ["O"] = "从希利苏斯的生物身上收集10份异种虫诱饵，然后带给尘泥沼泽的纳特·帕格。",
    ["D"] = "哦，对。诱饵！\n\n如果没有相配的诱饵，世界上最好的鱼饵也没意义。我试过从夜行虫、发光蠕虫到疯狂的工程装置，什么都试过。它们某种程度上都管用，但我想我需要更……异域的东西。来自遥远土地，带着独特味道。谁知道真正不同寻常的诱饵能钓上什么？你有什么想法吗？",
  },
  [28027] = {
    ["T"] = "深水仪式",
    ["O"] = "使用异种虫诱饵与纳特·帕格一起钓鱼，看看你们会钓到什么！",
    ["D"] = "好吧，我等不及要试试这个诱饵了。让我把它装到鱼饵上，准备好了就告诉我。谁知道我们会钓到什么？",
  },
  [27603] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "乌玛·巴图姆要你使用炼金术技能制作5瓶次级隐形药水，并把订单交给尘泥沼泽塔贝萨农场的塔贝萨。",
    ["D"] = "哦——一位有本事的炼金师！我需要你的帮助！\n\n沼泽里住着一位隐居女士，名叫塔贝萨。她派信使告诉我，她急需次级隐形药水，但我这里没有库存，也不知道怎么制作！你能帮我制作一些，并送到她那里吗？",
  },
  [27628] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "德拉兹辛比要你使用炼金术技能制作5瓶次级隐形药水，并把订单交给尘泥沼泽塔贝萨农场的塔贝萨。",
    ["D"] = "哦——一位有本事的炼金师！我需要你的帮助！\n\n沼泽里住着一位隐居女士，名叫塔贝萨。她派信使告诉我们，她急需次级隐形药水，但我们这里没人能制作这种东西！你能帮我制作一些，并送到她那里吗？我可不想招来她的怒火。我们已经受够了。",
  },
  [27653] = {
    ["T"] = "给达利尔上尉的委托",
    ["O"] = "玛蕾·霍斯顿要你使用锻造技能制作1顶绿铁头盔、1副绿铁护腕和1条绿铁护腿，并把订单交给尘泥沼泽北点哨塔的达利尔上尉。",
    ["D"] = "你好，冒险者——或者我该说，铁匠同伴？\n\n我们正为塞拉摩卫兵忙得不可开交，但北点的达利尔上尉又来了份特殊委托。我可不想为了处理这一单，耽误其他订单的进度。你愿意帮我接手吗？他需要一顶绿铁头盔、一条绿铁护腿和一副绿铁护腕。",
  },
  [27678] = {
    ["T"] = "给“沼泽之眼”加尔的委托",
    ["O"] = "祖尔格要你使用锻造技能制作1顶绿铁头盔、1副绿铁护腕和1条绿铁护腿，并把订单交给尘泥沼泽水光庄园的“沼泽之眼”加尔。",
    ["D"] = "你敲金属？\n\n人类要护甲，但我不知道怎么做人类合身的。只会武器。他需要绿铁头盔、绿铁护腿和绿铁护腕。你会敲金属，就带去女巫岭给沼泽之眼。",
  },
  [28076] = {
    ["T"] = "给“沼泽之眼”加尔的委托",
    ["O"] = "“沼泽之眼”加尔要你使用烹饪技能制作10份蜘蛛肉肠，并把订单交给尘泥沼泽水光庄园的“沼泽之眼”加尔。",
    ["D"] = "我很喜欢青蛙腿，但你不能永远只吃青蛙腿。好吧，也许我可以。你行吗？\n\n不管怎样，我想吃点比青蛙更多的东西。我不太喜欢蜘蛛，但它们的肉还挺好吃。给我带些蜘蛛肉肠来，好吗？",
  },
  [28391] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "大法师特沃什要你使用附魔技能制作1根次级秘法魔杖，并把订单交给尘泥沼泽泥潭沼泽某处屋子里的塔贝萨。",
    ["D"] = "一位法师同伴需要一根新魔杖。为沼泽农场里的塔贝萨制作一根次级秘法魔杖。这请求有些出人意料，但我不会拒绝。也许这是给别人的礼物，而她会以某种方式强化它。",
  },
  [28416] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "巴莱·洛克维要你使用附魔技能制作1根次级秘法魔杖，并把订单交给尘泥沼泽泥潭沼泽某处屋子里的塔贝萨。",
    ["D"] = "附近某位法师需要一根新魔杖。为沼泽农场里的塔贝萨制作一根次级秘法魔杖。这请求有些出人意料，但我不会拒绝。也许这是给别人的礼物，而她会以某种方式强化它。",
  },
  [28466] = {
    ["T"] = "给萨尔格的委托",
    ["O"] = "萨尔格要你使用工程学技能制作5个发条式同步协调陀螺仪，并把订单交给尘泥沼泽蕨墙村的萨尔格。",
    ["D"] = "萨尔格不是最聪明的食人魔，但萨尔格会注意东西。影子和光，亮和暗。萨尔格想知道时间。萨尔格不知道怎么看时间，但萨尔格知道发条式同步协调陀螺仪对时间有用。给萨尔格带很多发条式同步协调陀螺仪，这样萨尔格就有很多时间！",
  },
  [28503] = {
    ["T"] = "给“沼泽之眼”加尔的委托",
    ["O"] = "“沼泽之眼”加尔要你使用钓鱼技能收集20条新鲜的刺须鲶鱼，并把订单交给尘泥沼泽水光庄园的“沼泽之眼”加尔。",
    ["D"] = "我住在沼泽里，所以大家都以为我喜欢水。让我说清楚。我不喜欢。它又冷又湿，还到处都是。\n\n但鱼？我确实喜欢鱼。尤其是鲶鱼。\n\n给我带来20条新鲜的刺须鲶鱼，也许我就能忘掉湿漉漉的靴子。",
  },
  [28528] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "查瑞迪·米普斯要你使用草药学技能采集20株卡德加的胡须，并把订单交给尘泥沼泽塔贝萨农场的塔贝萨。",
    ["D"] = "哦，我麻烦大了。住在沼泽里的那位法师——塔贝萨——要卡德加的胡须，但我一点都没有。如果我不快点给她带去，我不知道她会做什么。她也许会把我变成癞蛤蟆！\n\n你能给她带20株卡德加的胡须到塔贝萨农场吗？",
  },
  [28553] = {
    ["T"] = "给塔贝萨的委托",
    ["O"] = "巴莱·洛克维要你使用草药学技能采集20株卡德加的胡须，并把订单交给尘泥沼泽塔贝萨农场的塔贝萨。",
    ["D"] = "喂，沼泽里的女巫——塔贝萨——想要卡德加的胡须，用来做她的一种药剂。如果我不快点给她带去，我不知道她会做什么。她也许会把我变成癞蛤蟆！\n\n你能不能把20株卡德加的胡须带给塔贝萨农场的她……趁我还没呱呱叫之前？",
  },
  [28613] = {
    ["T"] = "给训练员辛格迪的委托",
    ["O"] = "训练员辛格迪要你使用剥皮技能采集20张重皮，并把订单交给尘泥沼泽塞拉摩的训练员辛格迪。",
    ["D"] = "来观看我们的训练兵吗？新兵意味着瘀伤、鲜血和破损装备。如果他们的护甲撑不住，他们自己也撑不住。\n\n如果你想帮助我们的部队，就给我带来20张重皮。我需要它们来加固训练装备。它必须足够坚韧，能承受打击，也要足够便宜，能经得起消耗。",
  },
  [28630] = {
    ["T"] = "给克拉克的委托",
    ["O"] = "克拉克要你使用剥皮技能采集20张重皮，并把订单交给尘泥沼泽蕨墙村的克拉克。",
    ["D"] = "来帮忙？克拉克需要皮做新东西。龙袭击时丢了很多。需要新护腕。新腰布。需要重皮做这些东西。\n\n你去沼泽弄皮？克拉克就高兴！",
  },
  [28643] = {
    ["T"] = "给卡兹·双链的委托",
    ["O"] = "卡兹·双链要你使用采矿技能采集20块铁矿石，并把订单交给尘泥沼泽塞拉摩岛的卡兹·双链。",
    ["D"] = "为这里的库尔提拉斯人干活真是苦差事，我跟你说！每隔一阵子就有某个指挥官冲进来，征用我所有的铁矿石。他们刚刚又这么干了！\n\n说起来，你背上有把矿镐！也许你愿意帮我补满自己的个人储备。我会很乐意拿我自己的补给和你交换，那些东西任何冒险者都会觉得有用！",
  },
  [28667] = {
    ["T"] = "给纳泽尔·血矛的委托",
    ["O"] = "纳泽尔·血矛要你使用采矿技能采集20块铁矿石，并把订单交给尘泥沼泽蕨墙村的纳泽尔·血矛。",
    ["D"] = "你，站住！我看见你带着矿镐。我代表部落征召你执行一项任务。\n\n看到那边的熔炉了吗？我们把它搭起来了，但食人魔一直没用，因为他们没有储备材料。这就是你派上用场的地方。给我带来20块铁矿石，好让我们给这些食人魔看看什么叫冶炼。",
  },
  [26114] = {
    ["T"] = "羽月钓鱼",
    ["O"] = "在菲拉斯收集一条蓝脊枪鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "羽月岛作为钓鱼点是偏远了点，可只要找对地方，那里的鱼咬钩可凶得很。\n\n如果你想试试自己能不能应付大海能给出的最好挑战，就去找一条蓝脊枪鱼吧。把它们卷上来的时候可有得你较劲，不过哪怕只钓上一条，也能切出好些鱼排！奥苏哈会帮你处理那部分。",
  },
  [26293] = {
    ["T"] = "配得上国王",
    ["O"] = "从菲拉斯各处的森林漫游者身上收集树行者枝条。",
    ["D"] = "你看起来不太忙……来点小差事怎么样？我受热砂港派遣，到这里来押一场小赌。这里的格鲁克觉得自己总有一天会成为戈多克之王，就像他父亲以前那样，可现任国王把他打成叛徒，还把他逐出了厄运之槌。我们觉得格鲁克有成为国王的本事……只要有朋友帮忙。\n\n我打算给格鲁克打造一件威力强大的武器，让他在即将到来的战斗中使用，而你要替我弄到我需要的所有部件。成交吗？\n\n我首先需要一种特殊的魔法木材，你可以从附近的森林漫游者身上找到。它很轻，却像任何金属一样坚韧，用来做柄再合适不过。",
  },
  [26294] = {
    ["T"] = "配得上国王",
    ["O"] = "为格鲁克营地的维戈收集8捆湿地麻。",
    ["D"] = "这附近生长着一种特殊的麻，我可以用它做出非常结实的绳索。这样就算国王手一滑，也不会丢掉自己的武器！\n\n食人魔真奇怪。有传言说格鲁克的父亲，也就是上一任国王，抽了一捆这玩意儿，然后就从王座旁晃走了。他刚一离开食人魔的视线，他们就宣布立了新国王，于是格鲁克对王位的宣称就这么没了。\n\n总之，这种麻长在菲拉斯的河流附近，整片森林里都能找到。",
  },
  [26295] = {
    ["T"] = "配得上国王",
    ["O"] = "从菲拉斯虚弱的野兽身上收集20瓶野兽之血。",
    ["D"] = "我计划中的重要部分，需要大量精炼铁，再掺入一种你稍后要替我收集的特殊合金。不过，铁在这片地方很难弄到！\n\n但我有个变通办法：我需要的不多，所以我们可以直接从菲拉斯这里的野兽身上提取。\n\n这是我称作强力采血器的小玩意儿。削弱一头野兽，然后把它们血里的铁直接吸出来！有了足够多的小瓶，我就有足够的铁可用了。可惜每瓶的量都很少，所以是时候来一场老派的野生动物大屠杀了。",
  },
  [26296] = {
    ["T"] = "配得上国王",
    ["O"] = "从菲拉斯的痛苦深渊收集12块异种虫合金。",
    ["D"] = "现在该说说……没那么愉快的东西了。我就是特意等到你觉得已经投入了不少之后，才向你提出这个要求的。从这里往东南走，你会找到痛苦深渊。那里住着一些到处乱爬的野兽，有些人开始把它们叫作异种虫。\n\n众所周知，它们有时候会把矿石误当成食物，还会给矿石裹上一层黏糊糊的软泥。你知道它们把矿石完全吃下去再……排出来之后，会发生什么吗？\n\n好吧，我们得到的是一团混杂矿石，却不知怎么形成了一种新合金。别问我是怎么回事；我从来不想剖开一只来弄明白。我在乎的只是你把那些合金带回来，给格鲁克的新武器使用。",
  },
  [26298] = {
    ["T"] = "配得上国王",
    ["O"] = "从菲拉斯海岸的水元素身上收集盐冷精华。",
    ["D"] = "热量只是这道等式的一半，$c。我们还得能驯服火焰、控制热度，让那些合金慢慢熔化、融合，变成一种全新的东西。你运气不错，我不用把你派得太远去找我们需要的材料。\n\n就在菲拉斯海岸上，你会找到吸收了大海冷却精华的水元素。去尽可能多地收集它，我们会在锻造过程中用它，免得把整座营地都烧成灰！",
  },
  [26328] = {
    ["T"] = "进入炼狱",
    ["O"] = "利用你收集到的情报寻找黑石的藏宝。",
    ["D"] = "所以那三名船员说宝藏在菲拉斯，一个有纳迦出没的洞穴里？\n\n我对卡利姆多一无所知，没法再给你更多建议，但如果你去搜索那片土地的海边洞穴，我毫不怀疑你会找到想找的东西。\n\n还有，再弄一把你用来挖出这里箱子的那种铲子。我相信你会用得上。\n\n永别了，$C。我祈祷我们没有再见面的理由。",
  },
  [26401] = {
    ["T"] = "战斗的召唤：菲拉斯",
    ["O"] = "在菲拉斯找到并杀死5名部落成员。",
    ["D"] = "菲拉斯属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26402] = {
    ["T"] = "战斗的召唤：菲拉斯",
    ["O"] = "在菲拉斯找到并杀死5名联盟成员。",
    ["D"] = "菲拉斯属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26735] = {
    ["T"] = "东威尔德的回忆",
    ["O"] = "在达隆郡找到一件往昔遗物，并把它带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·羽月。",
    ["D"] = "你也感觉到了吗，$C？这片土地的自然和谐被打破时，它正如何痛苦地呼喊？我远道而来回应它的呼唤，可如今抵达这里，我感到自己被这片土地的痛苦淹没了。我需要你的帮助。 \n\n在瘟疫之前，这片土地被称为东威尔德，是一片葱郁的森林和农田，遍布生长之物。若要让它得到治愈，我们必须提醒这片土地，它曾经是什么模样。 \n\n曾经生活在这里的人们，在逃离或倒在瘟疫之下时，留下了许多过往生活的遗物。我们必须收集许多这样的遗物，举行净化仪式，驱散这片土地黑暗的记忆。 \n\n从南边那个名叫达隆郡的小镇开始吧。寻找任何可能被遗留下来的东西。",
  },
  [26736] = {
    ["T"] = "东威尔德的回忆",
    ["O"] = "在考林路口找到两件往昔遗物，并把它们带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·羽月。",
    ["D"] = "沿着达隆郡向北上路的旅人，接下来会抵达考林路口。我听说过那个村庄欢快的节庆，尤其是在丰收时节。红公鸡旅店以醇厚的麦酒闻名，甚至在我的族人中也是如此。我们必须唤回那些丰饶与喜悦的记忆。 \n\n前往考林路口，在那里寻找几件遗物。",
  },
  [27104] = {
    ["T"] = "向斥候杜拉报到",
    ["O"] = "前往艾萨拉瓦罗莫克寻找斥候杜拉。",
    ["D"] = "$C，我很看重你在菲拉斯处理食人魔事务时所做的工作。所以我准备推荐你接受另一项任务，前往一片更加危险的土地。\n\n如果你觉得菲拉斯的精灵废墟令人惊叹，那就等你见到艾萨拉的那些废墟吧。部落已经在瓦罗莫克建立了前线基地，我们需要像你这样的战士去探索荒野，保卫我们的阵地。\n\n我可是拿自己的名声来推荐你，所以别让我失望！",
  },
  [27190] = {
    ["T"] = "恐怖之元素",
    ["O"] = "从菲拉斯恐怖之岛的未滤元素身上取得一枚手工水核。",
    ["D"] = "你喝过我们的咖啡吗？那种深沉的泥炭香气来自我们对咖啡豆的特殊烘焙，而这要靠从自然栖息地的元素身上提取出的手工水来浸泡咖啡豆。\n\n一个水核在我们的工艺里能用很久，但现在该去菲拉斯的特殊来源地补充一个了。你愿意接下这份工作吗？",
  },
  [27315] = {
    ["T"] = "伸张正义",
    ["O"] = "杀死12名恐怖图腾博学者、10名恐怖图腾袭击者和6名恐怖图腾萨满祭司，然后回到菲拉斯的奥多·地月那里。",
    ["D"] = "就像她已经告诉你的那样，卢尤亚和我现在要把战斗带给恐怖图腾。我们两人联手，仍然能在不受太大威胁的情况下解决一些恐怖图腾，但如果你愿意而且有能力，我们很欢迎你的帮助。\n\n你已经见过我们下方的营地了，但东边还有更多。用你自己的战术，尽可能重创那些牛头人。等他们尝到卢尤亚的箭矢和你武器的锋芒之后，我们都可以回到这里会合。",
  },
  [27327] = {
    ["T"] = "牙齿记录",
    ["O"] = "从格鲁克营地北边、双塔山附近的老年怒痕雪人身上收集牙齿。",
    ["D"] = "我想也许老年怒痕在营地北边洞里，他们又大又强。我需要你去拿他们的牙齿，我希望特罗格能认出它们，终于明白。你现在去，带回牙齿，帮特罗格安息。",
  },
  [27607] = {
    ["T"] = "给索尔宾·范达瑟的委托",
    ["O"] = "洛加纳斯要你使用炼金术技能制作5瓶强力水下呼吸药剂，并把订单交给菲拉斯被遗忘的海岸营地里的索尔宾·范达瑟。",
    ["D"] = "我不信任地精，所以当一个在大陆海岸扎营的地精要求一些强力水下呼吸药剂时，我没有理他。\n\n但我确实有点过意不去，$C。我看不出那些药剂能造成什么危害。可我还是没法亲自把它们送过去。如果你有兴趣赚点钱，我邀请你去满足他的请求。",
  },
  [27633] = {
    ["T"] = "给杰拉尔的委托",
    ["O"] = "杰拉尔要你使用炼金术技能制作5瓶侦测亡灵药剂，并把订单交给菲拉斯格鲁克营地的杰拉尔。",
    ["D"] = "啊，炼金师。我的朋友托尔格以为自己没死。我想知道是不是还有别的没死的人在这附近晃，也许这就是为什么托尔格觉得死了还在这里晃也没关系。你能做让我看见死人的药水吗？",
  },
  [27657] = {
    ["T"] = "给珊蒂斯·羽月的委托",
    ["O"] = "珊蒂斯·羽月要你使用锻造技能制作6件钢质胸甲，并把订单交给菲拉斯羽月要塞的珊蒂斯·羽月。",
    ["D"] = "哨兵部队中工匠很少，所以我可以用得上你的服务，铁匠。我想委托你为新的哨兵新兵制作六件钢质胸甲。完成后请把它们带给我。",
  },
  [27682] = {
    ["T"] = "给洛卡·奥赫的委托",
    ["O"] = "洛卡·奥赫要你使用锻造技能制作6件钢质胸甲，并把订单交给菲拉斯莫沙彻营地的洛卡·奥赫。",
    ["D"] = "我们在莫沙彻营地的队伍里工匠很少，所以我可以用得上你的服务，铁匠。我想委托你为新的新兵制作六件钢质胸甲。完成后请把它们带给我。",
  },
  [28036] = {
    ["T"] = "狩猎仪式",
    ["O"] = "宾兹纳库要你使用制皮技能制作4件蛮皮披风，并把它们交给费伍德森林翡翠圣地的伊维·飘叶。",
    ["D"] = "既然我知道你能胜任这活儿，我已经准备好你的第一份合约了。\n\n你知道怎么制作蛮皮披风，对吧？费伍德森林北边有个古怪的客户想要四件。我不知道她为什么要四件，我也不打算问！但我要告诉你，制作那些披风，然后把它们送到翡翠圣地。\n\n如果你不知道怎么做那些披风，就去羽月要塞找普拉特·马克格鲁比，或者去莫沙彻营地找杉多尔·迅蹄。他们都在菲拉斯，如果你从没去过那里的话。",
  },
  [28395] = {
    ["T"] = "给特洛亚斯·月风的委托",
    ["O"] = "特洛亚斯·月风要你使用附魔技能制作1块大块强光碎片，并把订单交给菲拉斯羽月要塞的特洛亚斯·月风。",
    ["D"] = "如今海上的补给船少之又少，既要重建战后的秩序，又有风暴和海盗作乱。我的大块强光碎片用完了，如果你有兴趣给我带来一块，我的研究正好用得上。",
  },
  [28421] = {
    ["T"] = "给杉多尔·迅蹄的委托",
    ["O"] = "杉多尔·迅蹄要你使用附魔技能制作1块魔化皮，并把订单交给菲拉斯莫沙彻营地的杉多尔·迅蹄。",
    ["D"] = "你是附魔师，对吧？能帮我个忙吗？作为制皮供应商，我会寻找愿意为我提供存货的人。附魔师很难遇到，而我的魔化皮已经用完了。你愿意弄一块来吗？",
  },
  [28445] = {
    ["T"] = "给珊蒂斯·羽月的委托",
    ["O"] = "珊蒂斯·羽月要你使用工程学技能制作2个高级假人，并把订单交给菲拉斯羽月要塞的珊蒂斯·羽月。",
    ["D"] = "$N，我有许多哨兵要训练，却没有足够的护甲可用。那些等待铁匠打造护甲的人必须谨慎对练，以免受伤。这就是你派上用场的地方——听说你的工程学技艺早在你抵达前就传开了。我需要一些高级假人给我的哨兵使用。你能帮忙吗？",
  },
  [28471] = {
    ["T"] = "给维戈的委托",
    ["O"] = "希恩德拉·深草要你使用工程学技能制作5个不牢固的扳机，并把订单交给菲拉斯格鲁克营地的维戈。",
    ["D"] = "你是工程师吗？抱歉……你只是看起来像。\n\n不久前有个地精来找我，想要一些不牢固的扳机。我没有这些类型的补给库存，但他提到如果有工程师路过，他会待在格鲁克营地。要是你敢穿过森林到那里去，也许是个赚点钱的好机会！",
  },
  [28481] = {
    ["T"] = "给贝萨·蓝河的委托",
    ["O"] = "贝萨·蓝河要你使用急救技能制作20份魔纹绷带，并把订单交给菲拉斯羽月要塞的贝萨·蓝河。",
    ["D"] = "我奉泰兰德·语风本人之命，前来研究曾在这里安家的古代暗夜精灵。但我发现菲拉斯的废墟古老而危险。坠落的石块、锋利的树根、苔藓下隐藏的东西。如果我要妥善研究它们，就必须准备好处理小伤。\n\n出发前我还有很多东西要查看，也需要你的协助。给我带来20份魔纹绷带。我不会因为擦伤和扭伤就停止考察，但也不会放任它们不治。",
  },
  [28493] = {
    ["T"] = "给布莱斯·蒙特高莫的委托",
    ["O"] = "布莱斯·蒙特高莫要你使用急救技能制作20份魔纹绷带，并把订单交给菲拉斯莫沙彻营地的布莱斯·蒙特高莫。",
    ["D"] = "我受传承者派遣，前来研究曾在这里安家的古代暗夜精灵，但我发现菲拉斯的废墟古老而危险。如果我要妥善研究它们，就必须准备好处理小伤。我一直在这里等额外补给的邮包，可不知为什么它们还没有到。\n\n出发前我还有很多东西要查看，也需要你的协助来加快进度。给我带来20份魔纹绷带。我不会因为擦伤和扭伤就停止考察，但也不会放任它们不治。",
  },
  [28505] = {
    ["T"] = "给梅克内尔的委托",
    ["O"] = "梅克内尔要你使用钓鱼技能收集20条新鲜的斑点黄尾鱼，并把订单交给菲拉斯格鲁克营地的梅克内尔。",
    ["D"] = "格鲁克的执行者喜欢肉！也喜欢鱼！你有鱼竿，你钓鱼好。你给我带很多新鲜的斑点黄尾鱼给格鲁克的朋友。我们到时候也觉得你是朋友。",
  },
  [28531] = {
    ["T"] = "给洛加纳斯的委托",
    ["O"] = "洛加纳斯要你使用草药学技能采集20株阿尔萨斯之泪，并把订单交给菲拉斯羽月要塞的洛加纳斯。",
    ["D"] = "阿尔萨斯之泪……这样悲伤的名字，却属于如此美丽的花。你知道吗，它过去叫斯坦索姆百合。我听说它们在曾经的洛丹伦大地上已经不再大量生长了。\n\n我想研究这种草药。给我带来20株阿尔萨斯之泪，我会给你报酬。",
  },
  [28556] = {
    ["T"] = "给拉乌的委托",
    ["O"] = "拉乌要你使用草药学技能采集20株阿尔萨斯之泪，并把订单交给菲拉斯莫沙彻营地的拉乌。",
    ["D"] = "阿尔萨斯之泪……这样悲伤的名字，却属于如此美丽的花。你知道吗，它过去叫斯坦索姆百合。我听说它们在曾经的洛丹伦大地上已经不再大量生长了。\n\n我想研究这种草药。给我带来20株阿尔萨斯之泪，我会给你报酬。",
  },
  [28580] = {
    ["T"] = "给格雷甘·山酒的委托",
    ["O"] = "普拉特·马克格鲁比要你使用制皮技能制作1个快捷箭袋，并把订单交给菲拉斯双塔山附近营地里的格雷甘·山酒。",
    ["D"] = "那个矮人，格雷甘，待在菲拉斯荒野里的时间比大多数路过这里的德鲁伊都久。他给我寄来一张便条，要求一个新的快捷箭袋。需要那种不会在森林潮气里散架的东西。\n\n你可别想让我踏出羽月半步，$gsir:ma\'am;！但你有制作那东西的本事，对吧？",
  },
  [28605] = {
    ["T"] = "给格雷甘·山酒的委托",
    ["O"] = "杉多尔·迅蹄要你使用制皮技能制作1个快捷箭袋，并把订单交给菲拉斯双塔山附近营地里的格雷甘·山酒。",
    ["D"] = "那个矮人，格雷甘，待在菲拉斯荒野里的时间比大多数路过这里的德鲁伊都久。他给我寄来一张便条，要求一个新的快捷箭袋。需要那种不会在森林潮气里散架的东西。\n\n你可别想让我踏出莫沙彻营地一步！但你有制作那东西的本事，对吧？",
  },
  [28620] = {
    ["T"] = "给维戈的委托",
    ["O"] = "维戈要你使用剥皮技能采集20张厚皮，并把订单交给菲拉斯格鲁克营地的维戈。",
    ["D"] = "喂，你是剥皮师吗？我手头有几个副业项目。安静的活，不算官方事务。不过需要好材料。\n\n给我带20张厚皮来，我就拿些对你在这里冒险有用的补给跟你换。我需要结实的东西，切口干净。别多问。",
  },
  [28653] = {
    ["T"] = "给维戈的委托",
    ["O"] = "维戈要你使用采矿技能采集20块秘银锭，并把订单交给菲拉斯格鲁克营地的维戈。",
    ["D"] = "看见那边那两个蛮子了吗？丁和当说他们随时都能把熔炉准备好，但我可不抱希望。\n\n如果我们有一些秘银锭，也许能稍微加快进度。我想大约20块就够了。没错。当然是为了熔炉。不是为了我个人，不是。但把它们带回来给我。",
  },
  [28719] = {
    ["T"] = "给奥利坎多的委托",
    ["O"] = "奥利坎多要你使用裁缝技能制作2双灰布长靴，并把订单交给菲拉斯莫沙彻营地的奥利坎多。",
    ["D"] = "我不是森林巨魔，$C。这里的土地太潮湿。树太近，也太高。我一直在想着离开，但我必须为目的地做好准备：燃烧平原。\n\n如果你有这手艺，我需要几双灰布长靴。它们应该能承受平原的热度。",
  },
  [27068] = {
    ["T"] = "分一杯羹",
    ["O"] = "为瓦罗莫克的雷尔科从艾萨拉的珊瑚海龟身上收集6根海龟颈肉。",
    ["D"] = "艾萨拉是片古老又奇妙的土地，到处都有财富可拿。你是来瓦罗莫克分一杯羹的吗，伙计？想找最好的制皮材料？\n\n我自己最近刚出手了一批货，这片地方从森林到海岸都盛产完好的野兽毛皮。你要是想入行，我给你个提示。这里的海龟脖子周围有最柔软的皮。我从没见过这样的。所以出去杀些珊瑚海龟，拿它们的——没错——海龟颈肉回来。",
  },
  [27069] = {
    ["T"] = "分一杯羹",
    ["O"] = "从艾萨拉的多头蛇身上收集6片碎浪鳞片，然后回到瓦罗莫克的雷尔科那里。",
    ["D"] = "这里无尽海岸上的咸湿海风，会让沿着海滩巡游的碎浪多头怪鳞片保存得更好，也更有光泽——至少在纳迦没有称王称霸的地方是这样。\n\n如果你想再赚点钱，可以杀掉这里任何一种多头蛇，收集上好的鳞片。我心里那些买家只要最好的货。",
  },
  [27070] = {
    ["T"] = "分一杯羹",
    ["O"] = "杀死莫克拉克，把它坚韧的龙虾人肌腱带给艾萨拉瓦罗莫克的雷尔科。",
    ["D"] = "制皮匠会用线把他们的作品缝在一起。大多数时候，那样就够好了。但我有个买家要做点更大的东西。我们需要更结实的材料。而我知道去哪儿弄。\n\n在风暴海湾中央，有座岛，上面有块大弯石伸过一片沙洲。你常会在那里看到一只大个头老龙虾人在晒太阳。找到这个莫克拉克，杀掉它，取来它又粗又厚的肌腱。它坚韧又有弹性，正好能完成这份订单。\n\n别担心，伙计，如果你能办成，我有特别的东西给你。",
  },
  [27071] = {
    ["T"] = "合约：瓦罗莫克矿井",
    ["O"] = "在艾萨拉的瓦罗莫克矿井开采5处矿脉，然后向矿井前的工头利奥波德报告。",
    ["D"] = "嘿，矿工！我这儿有笔好买卖给你！\n\n看你那鼓起来的二头肌，我就知道你这辈子挥过不少次矿镐。怎么样，要不要来矿井里短期帮把手，让我们的苦工歇一歇？我们正在开采玫瑰石英，一种漂亮又罕见的小玩意儿，我以前从没见过。\n\n当然是有报酬的合约劳工，短期，没有福利，入矿风险自负，下面发生什么我们概不负责。但我们得完成部落的定额，而你能帮上忙！",
  },
  [27072] = {
    ["T"] = "合约：瓦罗莫克矿井",
    ["O"] = "把玫瑰石英样本带给瓦罗莫克的莱安德大师调查。",
    ["D"] = "你确实挖出了好几批玫瑰石英。大多数都是很普通的货。可看这个！这块玫瑰石英跟其他的不一样。看见它发出那种怪光了吗？这要么很糟，要么特别好。\n\n你不如把它带到西南边炼金建筑里的莱安德大师那里，让他仔细看看？\n\n记住，如果它被诅咒了，我可不负责！",
  },
  [27073] = {
    ["T"] = "合约：瓦罗莫克矿井",
    ["O"] = "把莱安德大师的报告带给艾萨拉瓦罗莫克矿井的工头利奥波德。",
    ["D"] = "$N，这真是个发现。我一眼就能看出，这块玫瑰石英碎片里确实有某种魔法精华。工头利奥波德让你把它带来给我，倒是出人意料地有见识。\n\n我会留下这个样本继续研究。回去告诉利奥波德，如果他们挖出更多类似的东西，我很感兴趣——另外，你已经挣到奖金了。",
  },
  [27077] = {
    ["T"] = "蒸馏软泥",
    ["O"] = "从艾萨拉的森林软泥怪身上收集4份森林软泥，然后回到瓦罗莫克的莱安德大师那里。",
    ["D"] = "看到我塔里到处都是的这些学徒了吗，$C？一群废物！\n\n不过这是怎么回事——我是不是从你身上闻到了巨魔之血的气味？石鳞鱼油的精华？如果你确实是一位炼金师同道，我正好有份活给你。\n\n我有四个学徒，但以前有五个，直到我派其中一个去执行收集森林软泥怪软泥这种简单差事。既然我还需要软泥，又没有更多多余学徒，我就需要一位老练炼金师协助收集。你可以在门纳尔湖北边，或者艾萨拉西北部找到森林软泥怪。\n\n如果你看到我那个蠢学徒剩下的东西，别犹豫，朝他吐口唾沫！",
  },
  [27078] = {
    ["T"] = "蒸馏软泥",
    ["O"] = "从艾萨拉南部海岸的风暴海湾智者身上取得一份纯净鱼人精华，并把它带给瓦罗莫克的莱安德大师。",
    ["D"] = "软泥怪的软泥是药水和药剂的强力基底，但我们还需要某种带能量的东西来激活混合物。幸运的是，答案就在东南海岸那些水生居民身上。\n\n风暴海湾智者鱼人会分泌一种灌注闪电的精华，帮助维持它们的魔法能力。完整取回这种精华很少见，但只要杀得够多，你最终会弄到的。你会在拉文凯斯雕像半岛周围的海岸和近海水域找到它们。快去！",
  },
  [27079] = {
    ["T"] = "蒸馏软泥",
    ["O"] = "用门纳尔湖的湖水装满莱安德的瓶子，然后回到艾萨拉瓦罗莫克的莱安德大师那里。",
    ["D"] = "<莱安德大师用下水道语向他的学徒们吼出命令，他们立刻绷紧神经，开始以狂乱的速度混合材料。莱安德大师默默监督，直到一名学徒开始往溶液里加水。>\n\n不！你这个蠢货！这东西不能用没稀释过的奥格瑞玛自来水！你的熟练导师是谁，巨魔吗？\n\n<莱安德大师从学徒手里抢过瓶子，塞向你。>\n\n$C，做个乖$gboy:girl;，去从门纳尔湖纯净的魔法湖水里把它装满。你可以在南边找到那里，靠近蓝龙人栖息的地方。\n\n请别被它们吃掉，我这里备用瓶子也就那么多。",
  },
  [27088] = {
    ["T"] = "掠夺亚考兰神殿",
    ["O"] = "把奇怪的纳迦石板带给瓦罗莫克炼金塔里的莱安德大师。",
    ["D"] = "艾萨拉的上层精灵废墟中有许多石板，但这块看起来完全不一样。它更大，呃……更花哨？更……符文味？\n\n我不知道，我只是个普通士兵。我能告诉你的只有，它看起来很危险。最好把它带给莱安德大师进一步调查。你可以在瓦罗莫克另一侧的炼金塔里找到他和他的学徒。",
  },
  [27089] = {
    ["T"] = "掠夺亚考兰神殿",
    ["O"] = "把奇怪的纳迦石板带给艾萨拉北部法师塔的大法师克希雷姆。到瓦罗莫克附近营地寻找萨纳斯传送过去。",
    ["D"] = "<莱安德大师把石板递还给你。>\n\n千万小心，$R。你手里拿着的东西，似乎是一块完整的上层精灵圣物匣石板——来自艾萨拉女王本人上层精灵图书馆的遗物。\n\n在大分裂摧毁曾经矗立于此的精灵城市之后，那座图书馆和其中所有藏品都被认定已经毁灭。我无法验证这是否真是圣物匣石板，但我知道谁能。\n\n把这块石板带给大法师克希雷姆，他住在附近悬崖上的一座塔里。你得说服他的助手萨纳斯，让他送你上塔。",
  },
  [27091] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "回到艾萨拉瓦罗莫克的莱安德大师那里。",
    ["D"] = "破译你带给我的遗物需要一些时间。你不如先回你的主人那里待一阵？如果我还需要你的服务，我会派人找你。",
  },
  [27092] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "为瓦罗莫克的莱安德大师从玛科尼龙虾人身上收集12只眼睛。",
    ["D"] = "如果大法师的利益能与我们的重合，他会是一个强大的盟友。你做得很好，$N。\n\n我确实还有另一项任务给你。玛科尼这一支龙虾人可以在艾萨拉的北部和南部海岸找到。我需要它们的眼睛，具体来说要十二只。\n\n不要把它们和亚考兰品种弄混。那些被魔法动过手脚，对我没用。",
  },
  [27093] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "与艾萨拉北部法师塔的大法师克希雷姆谈谈。到瓦罗莫克附近营地寻找萨纳斯传送过去。",
    ["D"] = "你外出执行我的小差事时，大法师克希雷姆送来了一条消息。他再次需要你协助处理那块石板。\n\n最好别让他等太久。你现在还有他的好感，别把它搞砸。",
  },
  [27096] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "回到艾萨拉瓦罗莫克的莱安德大师那里。",
    ["D"] = "我们的事务暂时结束了，$C。你可以回到你的主人那里，领取他认为适合你服务的任何报酬。\n\n如果有必要，我会再联系他。我……欠你一份谢意。",
  },
  [27098] = {
    ["T"] = "给斥候杜拉的消息",
    ["O"] = "前往艾萨拉瓦罗莫克寻找斥候杜拉。",
    ["D"] = "如果你在这里待得太久，费伍德森林的腐化会渗入你的血肉，$R。为了你自己好，我觉得你该去艾萨拉瓦罗莫克的新前哨站看看。离开邪能河流一阵，呼吸一下咸湿的海风。\n\n你可以在那里找我的朋友杜拉。她会告诉你这片土地的情况。",
  },
  [27099] = {
    ["T"] = "黑曜钢",
    ["O"] = "为艾萨拉瓦罗莫克的格鲁尔·黑刃收集6面毒蛇守卫盾牌。",
    ["D"] = "啊，一位铁匠同道。我能从你的血脉里闻到熔炉独有的气味。\n\n你也许会感兴趣：守卫附近埃达拉斯废墟的恶鞭毒蛇守卫，已经掌握了使用黑曜钢打造那些惊人盾牌的技术。\n\n你问黑曜钢是什么？这也是我想知道的。\n\n从它们主人手里收集六面毒蛇守卫盾牌带回来，也许我们就能一起弄明白。",
  },
  [27100] = {
    ["T"] = "黑曜钢",
    ["O"] = "把毒蛇守卫盾牌带给奥格瑞玛荣誉谷的克拉索克·火拳。",
    ["D"] = "你看到了吗，$N？这种材料几乎完全不受我熔炉热力的影响！\n\n但我们在瓦罗莫克这里只搭起了最基本的设备。你愿意把它带到奥格瑞玛的熔炉去，看看克拉索克·火拳能不能帮我们把它熔化吗？你可以在荣誉谷后面找到他。",
  },
  [27107] = {
    ["T"] = "来自晃荡谷的补给",
    ["O"] = "把浸水零件箱带给艾萨拉瓦罗莫克的菲兹特。",
    ["D"] = "来，让我把这些给你装进箱子里。希望这能帮上你原本需要它们做的事。等等，你说过你需要它们做什么吗？\n\n<威尔伯脸色发白。>\n\n哦，一个部落前哨站？好吧，呃，希望我们本着工程师之间合作精神提供的帮助，能大大促进我们在艾萨拉这里的和平相处。\n\n现在快走吧！",
  },
  [27108] = {
    ["T"] = "恶鞭巫术",
    ["O"] = "与艾萨拉北部法师塔的乔艾·阿纳雷斯谈谈。你也许得找瓦罗莫克附近营地的萨纳斯送你过去。",
    ["D"] = "你能感觉到这片土地里流动的能量吗，$C？我看得出你很会用附魔魔杖——那些能量几乎从你身上发光。\n\n想给自己加点防护吗？也许还能考验一下你的附魔本事？不远处那座大法师塔里有个高等精灵，几天前在找助手。你得和萨纳斯讨价还价，让他送你上去，但也许值得去看看。",
  },
  [27111] = {
    ["T"] = "编织防护",
    ["O"] = "为瓦罗莫克的朱尔扎从艾萨拉的林木隐匿者身上收集10份林木隐匿者蛛丝。",
    ["D"] = "你能感觉到这片土地里流动的能量吗，$C？对这里的生灵来说，这是黑暗过去和黑暗未来的征兆。上层精灵对这片土地中流淌的魔法犯下了严重罪行。我的巫毒在这样的邪恶面前软弱无力。\n\n想给自己加点防护吗？我们裁缝有办法做到，但需要从当地弄些东西。\n\n如果你想帮忙，就给我带些艾萨拉这里隐匿者的蛛丝。然后我们看看能用它们织出什么。",
  },
  [27112] = {
    ["T"] = "编织防护",
    ["O"] = "为瓦罗莫克的朱尔扎从艾萨拉的血精灵身上收集12份精灵织物。",
    ["D"] = "说到线，东边那些血精灵带着他们那种花哨的日纹丝绸。他们的布料天然排斥祖先的魔法。要是我们能弄到一些，嗯，这活儿会轻松很多。\n\n你会在东边，然后沿着破碎海岸上方的悬崖向南，找到血精灵营地。拿十二份他们的丝绸回来。",
  },
  [27113] = {
    ["T"] = "编织防护",
    ["O"] = "用一卷符文线向艾萨拉黑喉村的商人玛鲁交换秋色染料，然后回到瓦罗莫克的朱尔扎那里。",
    ["D"] = "我们最后需要的是用本地材料制成的染料。我不敢为了这么小的请求打扰莱安德大师，而他的所有学徒都忙得没空帮我们。\n\n我听说北岸很远的地方有个熊怪村，那里的熊怪对外来者很友好，还有个熊怪商人。如果那里有商人，就去看看他们有没有染料可换，好吗？\n\n你得带点东西去交换。也许试试符文线？大概比他们平常用的细致多了。",
  },
  [27120] = {
    ["T"] = "远古土地的战利品",
    ["O"] = "为艾萨拉瓦罗莫克的雷尔科从苔蹄雄鹿身上剥取10张苔蹄毛皮。",
    ["D"] = "$N，艾萨拉这里的剥皮生意富得像地精开出的贸易价一样。你想不想给自己捞点战利品？\n\n建造前哨站需要大量材料，而瓦罗莫克是部落能建出的好基地。我可以替你把这里到处都有的雄鹿毛皮卖个好价钱。杀了它们，剥下皮，拖回来，你就能分到一份财富。",
  },
  [27121] = {
    ["T"] = "远古土地的战利品",
    ["O"] = "从雾翼奇美拉身上剥取10张雾翼毛皮，然后回到艾萨拉瓦罗莫克的雷尔科那里。",
    ["D"] = "艾萨拉到处都是雄鹿，可奇美拉就难找多了。它们的皮更危险，也因此贵得多。\n\n如果你想收集更多战利品，可以在门纳尔湖附近找到一种古怪的奇美拉——不过大多数都在东北部。杀掉它们，剥下皮，拖回这里换取奖赏！",
  },
  [27123] = {
    ["T"] = "供应学生",
    ["O"] = "把20株太阳草带给艾萨拉瓦罗莫克的学徒萨瑞娜。",
    ["D"] = "哦，你好，$C。你有什么需要吗？莱安德大师交给我们的任务太多了，我忙得不可开交。\n\n话说，你该不会碰巧是草药师吧？如果是，我真的能用得上你的帮助。我们的太阳草快用完了，而这种草在艾萨拉生长得很茂盛，可我一直没时间出去采更多。如果你旅途中见到一些，能不能替我们补充库存？\n\n把它们交给学徒萨瑞娜，她正在研究一种新的太阳草油配方。",
  },
  [27124] = {
    ["T"] = "供应学生",
    ["O"] = "杀死5只大型碎浪多头怪并收集它们的消化囊，然后把它们带给艾萨拉瓦罗莫克的学徒贾维斯。",
    ["D"] = "自从我们搭起实验室以来，科林就一直浪费时间派信使给我送花。他应该专心做我们编录艾萨拉植物的工作才对！\n\n如果你真想帮我们，有一项我们这些学徒独自处理不了的任务。栖息在艾萨拉东南海岸的大型碎浪多头怪，会在拉文凯斯雕像下方那些脆弱的潮池里游荡，踩踏那里稀有而脆弱的植物。这些多头蛇太危险了，我们甚至没法好好编录那些潮池中生长的所有物种。\n\n如果你能杀掉一些多头蛇并收集它们的消化囊，我们就能更好地了解那片区域生长着什么。如果你能收集到，请把它们带给二楼的学徒贾维斯——他是生物学专家。",
  },
  [27125] = {
    ["T"] = "供应学生",
    ["O"] = "从南山海滩沿岸的潮池中收集8朵白潮莲，并把它们带给艾萨拉瓦罗莫克的学徒温特。",
    ["D"] = "不可思议，$C！这只碎浪多头怪的胃里有<lotos aestus albos>，也就是白潮莲的残余。\n\n白潮莲极其稀有，需要经验丰富的草药师才能采摘。恐怕这里没有哪个学徒具备这种本事。不过，也许你有？\n\n如果你想帮忙收集这种草药，就去艾萨拉东南部山谷和峭壁间的潮池里寻找。把你找到的任何莲花带给顶楼的学徒温特。",
  },
  [27140] = {
    ["T"] = "魔网罗盘",
    ["O"] = "把奇怪的罗盘带给艾萨拉瓦罗莫克的莱安德大师。",
    ["D"] = "你杀死的魔导师带着一件奇怪的魔法装置。它的形状像罗盘，但里面精巧的银色仪器并不指向真正的北方。相反，它们在玻璃罩下飞快旋转，偶尔停下来指向刻度盘上陌生的标记。\n\n也许瓦罗莫克的莱安德大师会有兴趣检查这件物品？",
  },
  [27142] = {
    ["T"] = "破碎海岸的指挥官",
    ["O"] = "找到并消灭破碎海岸上的潮汐女祭司阿奎拉，然后向艾萨拉瓦罗莫克的哈格鲁姆·血拳报告你的胜利。",
    ["D"] = "这个纳迦带着一套似乎用海藻包裹的命令。虽然你看不懂纳迦难以理解的文字细节，但你认出命令中提到了一名指挥官：潮汐女祭司阿奎拉。\n\n除掉破碎海岸上恶鞭的指挥官，肯定会让哈格鲁姆·血拳高兴，也有助于确保瓦罗莫克的安全。也许你该检查一下附近的小亭？",
  },
  [27148] = {
    ["T"] = "即将到来的寒冬",
    ["O"] = "为艾萨拉瓦罗莫克的猪倌古努格从瓦罗莫克东边的纳迦身上收集10份恶鞭海藻。",
    ["D"] = "杰迪加是最早来到艾萨拉的兽人之一，而她居然爱上了——在所有东西里——海藻！\n\n杰迪加说它能像肉一样用各种方法烹饪。晒干、加香料、嫩煎、炙烤、炖煮，只是举几个例子。\n\n我听说海滩下方的纳迦有很多海藻。如果它能让他们又大又强，也许也能让我们又大又强。你能替我们从纳迦那里储备些海藻吗？",
  },
  [27149] = {
    ["T"] = "即将到来的寒冬",
    ["O"] = "杀死亚考兰龙虾人，收集10只巨大的龙虾人钳子，交给艾萨拉瓦罗莫克的猪倌古努格。",
    ["D"] = "巨魔们说可以在这里的水里抓龙虾。我们在德拉诺也有龙虾。我很喜欢龙虾。\n\n可艾萨拉这里有龙虾人！他们的钳子更大。我敢说味道更好。那里肯定肉更多。\n\n你能给我带些他们又大又多肉的钳子，好让我试着烹饪吗？东边海滩往上，亚考兰神殿旁边，有一大群。",
  },
  [27150] = {
    ["T"] = "即将到来的寒冬",
    ["O"] = "从黑喉村的商人玛鲁那里取得黑喉黄油，并把它带回艾萨拉瓦罗莫克的猪倌古努格那里。",
    ["D"] = "你帮了我这个卑微猪倌这么多忙。我不想再求你一个人情，但我真的想要些黄油来配这些龙虾钳。\n\n北边海岸上有个熊怪营地，比木喉对外来者更友善。他们被称作黑喉，愿意和我们交换补给。你能把这块培根带给他们的商人，看看他愿不愿意换些黄油给你吗？",
  },
  [27155] = {
    ["T"] = "瓦罗莫克的威胁",
    ["O"] = "为瓦罗莫克的哈格鲁姆·血拳杀死10名恶鞭战士和10名恶鞭尖啸者。",
    ["D"] = "向你致意，部落的士兵！\n\n瓦罗莫克是部落在卡利姆多推进得最远的前哨站，我们需要你的帮助来确保阵地安全。\n\n你可以先清理附近废墟里的纳迦。杀死那些战士和尖啸者，直到你的武器被他们的鲜血染红！\n\n等等……纳迦流的是红血吗？\n\n去弄清楚！",
  },
  [27156] = {
    ["T"] = "瓦罗莫克的威胁",
    ["O"] = "为瓦罗莫克的哈格鲁姆·血拳杀死10名恶鞭侍从和10名恶鞭海妖。",
    ["D"] = "瓦罗莫克附近的纳迦软弱，轻易就能击溃。我很抱歉把你派去对付如此低劣的敌人，但在提供更合适的挑战前，我必须考验你的本事。在东边下方的破碎海岸，你会找到更强的对手。\n\n杀死恶鞭侍从和海妖。把海滩上的敌人清除干净，让我们今晚能在床铺上安心睡觉！",
  },
  [27157] = {
    ["T"] = "瓦罗莫克的威胁",
    ["O"] = "为哈格鲁姆·血拳杀死15名风暴海湾战士。",
    ["D"] = "我的上级血卫士格鲁什特别憎恨鱼人。我倒没有那么特别厌恶它们，但它们仍然是威胁。\n\n有大量它们的战士在艾萨拉北部海岸巡逻。削减它们的数量，让它们无法组织起来反抗我们。\n\n然后也许格鲁什就会闭嘴，不再念叨它们那些古怪的声音。",
  },
  [27158] = {
    ["T"] = "瓦罗莫克的威胁",
    ["O"] = "为瓦罗莫克的哈格鲁姆·血拳杀死5名蓝色龙人、5名蓝色刃鳞龙人和5名龙人施法者。",
    ["D"] = "你已经证明自己能对付各种武装敌人，但你怎么看待魔法敌人？\n\n一群蓝龙人栖息在南边，门纳尔湖周围。它们的存在表明那一带很可能有一条魔网，或者某种其他魔法枢纽。我们将来也许需要利用这份资源。\n\n执行一次前进任务，消灭它们的部队，把对部落的恐惧打进它们心里。这样一来，如果我们大军到来，它们就会逃跑。\n\n蓝龙人可不是普通敌人。你最好为这项任务组建一支小队。",
  },
  [27159] = {
    ["T"] = "瓦罗莫克的威胁",
    ["O"] = "为瓦罗莫克的哈格鲁姆·血拳消灭5名峭壁巨人。",
    ["D"] = "$N，我已经向你要求了很多，而到目前为止你没有让我失望。我还有最后一项任务，用来确保我们的安全。\n\n艾萨拉的峭壁巨人看起来没有组织到足以发动入侵，但他们隆隆的脚步震动着大地本身，威胁着我们在这里的所有新建设，尤其是矿井。我希望你削减他们的数量。\n\n如果你手边还有那支小队，最好再带上他们。祝你好运。",
  },
  [27160] = {
    ["T"] = "瓦罗莫克矿井报告",
    ["O"] = "与艾萨拉瓦罗莫克矿井的工头利奥波德、监工加尔德和工头莱昂纳德谈谈，取得采矿状况报告。",
    ["D"] = "欢迎来到瓦罗莫克，$C。我们奉大酋长本人之命来到这里，驯服这片土地，利用它的资源装备并供给部落。\n\n我一直忙着安排前哨站的事务——也许你愿意顺路去镇北的矿井，和管理人员确认一下情况？他们早该提交状态报告了。",
  },
  [27161] = {
    ["T"] = "工作时吹口哨",
    ["O"] = "对5名瓦罗莫克苦工使用/Whistle，然后回到艾萨拉瓦罗莫克的阿格图·血拳那里。",
    ["D"] = "你可以说我激进，但我相信音乐能扭转阴暗的一天。所以把嘴唇凑起来，在矿井里和矿工们一起吹个小口哨。我们可以开开心心地从这里采出矿石。只要有歌声帮你掌握节奏，这不会花太久。\n\n心情高涨时，时间就会飞逝。所以，让他们一边工作一边吹口哨吧。\n\n<阿格图朝你露出一个宽得吓人的笑容。>",
  },
  [27162] = {
    ["T"] = "给奥格瑞玛的瓦罗莫克报告",
    ["O"] = "把瓦罗莫克报告带给奥格瑞玛智慧谷的萨尔。",
    ["D"] = "<阿格图·血拳叹了口气。>\n\n我骗谁呢？一点音乐解决不了所有问题。\n\n以前有联盟或者燃烧军团可以打，事情简单多了。现在全是“士气”、“投入度”，还有“你不能再剥半人马的皮”。\n\n如果有什么东西影响了矿工，也许萨尔知道该怎么办。不管怎样，我应该通知他，矿井已经启用，但生产力还没达到我们的目标。你愿意把这条消息带给奥格瑞玛智慧谷的他吗？",
  },
  [27635] = {
    ["T"] = "给学徒萨瑞娜的委托",
    ["O"] = "学徒萨瑞娜要你使用炼金术技能制作5瓶昏睡药水，并把订单交给艾萨拉瓦罗莫克的学徒萨瑞娜。",
    ["D"] = "莱安德大师是炼金术天才，但他让我们忙到骨头里——这不是亡灵笑话。我觉得自己已经好几个月没睡过一个好觉了。\n\n我不能停下手头工作去做个人项目，但如果你愿意替我制作几瓶昏睡药水，我就能站着睡觉，而且更有效率。你能帮忙吗？",
  },
  [27684] = {
    ["T"] = "给格鲁尔·黑刃的委托",
    ["O"] = "格鲁尔·黑刃要你使用锻造技能制作4把真银万能钥匙，并把订单交给艾萨拉瓦罗莫克的格鲁尔·黑刃。",
    ["D"] = "洛克塔！你是铁匠，对吧？\n\n艾萨拉海岸上会有许多箱子和盒子从各种沉船残骸中被冲上岸，这些水域总是遭受危险风暴的冲击。我想把其中一些打开，而这需要真银万能钥匙。如果你能制作一些并送到这里，就能帮助补给基地——也能让那些财宝落不到联盟手里。",
  },
  [28423] = {
    ["T"] = "给学徒萨瑞娜的委托",
    ["O"] = "学徒萨瑞娜要你使用附魔技能制作1根次级虚空魔杖，并把订单交给艾萨拉瓦罗莫克的学徒萨瑞娜。",
    ["D"] = "等一下，小声点，你能帮我吗？大药剂师莱安德拿走了我的魔杖，因为他说我太依赖魔法，花在炼金术上的时间不够。但我需要我的魔杖！所以你能不能偷偷给我做一根替代品？我会付钱的！",
  },
  [28473] = {
    ["T"] = "给血卫士格鲁什的委托",
    ["O"] = "格鲁尔·黑刃要你使用工程学技能制作20枚高爆炸弹，并把订单交给艾萨拉瓦罗莫克的血卫士格鲁什。",
    ["D"] = "每天到吃饭时间，我听到的全是鱼人的威胁。这个“姆啦啦”，那个“哇啦咕”。血卫士格鲁什简直迷上它们了。\n\n我们镇上的熔炉还没搭好，没法做任何工程活，但如果你愿意在别处制作一些高爆炸弹送给格鲁什，也许他就会觉得自己不再害怕“鱼人威胁”，然后闭嘴不提了！",
  },
  [28557] = {
    ["T"] = "给学徒温特的委托",
    ["O"] = "学徒温特要你使用草药学技能采集20株梦叶草，并把订单交给艾萨拉瓦罗莫克的学徒温特。",
    ["D"] = "梦叶草……对有些人来说是无害草药，但我看到了潜力——某种更大的潜力。\n\n它对心智的影响……很有前景。给我带来20株梦叶草，我们就可以开始配制一种新的瘟……我是说，药水。",
  },
  [28672] = {
    ["T"] = "给菲兹特的委托",
    ["O"] = "菲兹特要你使用采矿技能采集20块瑟银锭，并把订单交给艾萨拉瓦罗莫克的菲兹特。",
    ["D"] = "$N，真是灾难！我们刚把基地熔炉搭起来，纳迦就来袭击，把它炸了！要让它重新运转起来，除非有奇迹。\n\n不过，你也许可以帮我凑到20块瑟银锭。我听说北边荒野里有很多矿石。要是我自己有时间去看看就好了。",
  },
  [28721] = {
    ["T"] = "给杰迪加的委托",
    ["O"] = "杰迪加要你使用裁缝技能制作2件简易的黑裙子，并把订单交给艾萨拉瓦罗莫克的杰迪加。",
    ["D"] = "你是裁缝，对吧？很好。\n\n贝尔格罗姆把我判到这里时，根本没时间带太多东西。至少，如果我还想让脑袋留在肩膀上的话是这样。可女孩子天天穿同一套制服也会腻。我想要几件简易的黑裙子，等我终于办完这里的事，能回奥格瑞玛喝杯麦酒时穿。你能帮忙吗？",
  },
  [8924] = {
    ["T"] = "猎取灵质",
    ["O"] = "在无形亡灵附近使用灵质蒸馏器，收集12份艾萨拉的浸水灵质、12份冬泉谷的冰冻灵质和12份东瘟疫之地的稳定灵质。把它们和灵质蒸馏器一起带回加基森的穆克斯·玛纳斯卡波。",
    ["D"] = "要我自己说，这可是一件精妙的工程学作品！恐怕你得跑上不少路，才能找到我们需要的无形亡灵。\n\n你看，不同气候会让死者的幽魂织体呈现不同的黏稠度。艾萨拉那些早已溺亡的暗夜精灵、冬泉谷的上层精灵之魂，以及东瘟疫之地的鬼魂和女妖，应该能给我们需要的不同类型灵质。收割它们之前，记得把蒸馏器放在附近！",
  },
  [8962] = {
    ["T"] = "重要材料",
    ["O"] = "取得德鲁伊遗骸，并把它们带回黑石山内的伯德雷。",
    ["D"] = "$C，仔细听。既然我们已经有了火盆，也有了点燃它的手段，我们还需要另一种材料来灌注其中；某种能提供足够强大焦点、引来我那已故前战友之灵的东西。\n\n莫尔·灰蹄是我们最杰出的德鲁伊，他在塞纳里奥议会中有许多亲近的朋友。他曾参加一支前往艾萨拉研究那里的石巨人的远征队，但那些石巨人太过凶暴，远征队大多数人都倒下了。我需要你从艾萨拉东北部的那些巨人那里取回一些德鲁伊遗骸。",
  },
  [8986] = {
    ["T"] = "更多重要材料",
    ["O"] = "取得德鲁伊遗骸，并把它们带回黑石山内的伯德雷。",
    ["D"] = "$C，仔细听。既然我们已经知道最后一块护符碎片的位置，我们还需要另一种材料来灌注火盆；某种能提供足够强大焦点、引来我那已故前战友之灵的东西。\n\n莫尔·灰蹄是我们最杰出的德鲁伊，他在塞纳里奥议会中有许多亲近的朋友。他曾参加一支前往艾萨拉研究那里的石巨人的远征队，但那些石巨人太过凶暴，远征队大多数人都倒下了。我需要你从艾萨拉东北部的那些巨人那里取回一些德鲁伊遗骸。",
  },
  [26100] = {
    ["T"] = "城里的鳄鱼",
    ["O"] = "在奥格瑞玛收集一只小鳄鱼，然后回到艾萨拉黑喉村的老人巴尔洛那里。",
    ["D"] = "你好，$C。很高兴你停下来和这个老人说说话——家乡那边出了麻烦。\n\n一个旅行商人最近把一批小鳄鱼卖给了一些容易上当的孩子。鳄鱼是野兽，许多已经逃走，现在潜伏在城市水道里。\n\n拿上你最结实的鱼竿，在任何主城里下钩，把其中一个小恶魔带回来给我。我急着想见一只。",
  },
  [26101] = {
    ["T"] = "月光林地的月鱼",
    ["O"] = "在月光林地收集10条月鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "如果你想找个放松钓鱼的地方，月光林地再合适不过。卡利姆多再也找不到更宁静的水域了。\n\n我打赌输了，欠我朋友维弗拉一些鱼，但一直没时间去月光林地。也许你有兴趣替我把它们钓上来？你会帮这个老人一个大忙。",
  },
  [26102] = {
    ["T"] = "河中的幽灵",
    ["O"] = "在逆风小径收集一条幽灵鬼鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "当年老卡拉赞周围的钓鱼可真是丰盛又美好。后来就有了军团、恶魔，还有麦迪文离去那些不愉快的事。那地方让我的老骨头发抖。\n\n我的朋友奥苏哈很好奇那里现在还能不能钓鱼。我太不好意思承认自己害怕，就答应去试试。可我实在没法让自己往那边走——大多数钓鱼人都迷信嘛。\n\n也许你愿意去看看，把咬钩的东西带回来给他？",
  },
  [26103] = {
    ["T"] = "冰冻补给",
    ["O"] = "在冬泉谷收集10块冰冻球体，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "你知道吗，钓鱼的用处可远不止抓下一顿饭。它还能在炎热夏日帮你一把。\n\n拿冬泉谷的水来说吧——你能钓起大块大块的冰，冻得结结实实，能保存好几天。用来储存运输中的鱼很好，或者在有人奇怪地看你时丢过去也不错。\n\n事实上，我快用完了。愿意替我们补充补给吗？完成后把它们带给维弗拉。",
  },
  [26104] = {
    ["T"] = "钓起美术品",
    ["O"] = "在东瘟疫之地收集一幅精美风景画，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "你知道吗，世上有很多东西最后都会流进河流、湖泊和海洋里。其中有些甚至值点钱！\n\n比如说，现在东瘟疫之地那边布洛米尔出产的工艺品和艺术品。当年那里有些非常可爱的作品，漂亮的风景画和精致的木雕，奥苏哈一定会喜欢。也许其中一些被冲进了那里残存的湖水里。值得一看，不是吗？",
  },
  [26105] = {
    ["T"] = "顽强的墩鱼",
    ["O"] = "在西瘟疫之地收集10条墩鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "如今西瘟疫之地里流入达隆米尔湖的索瑞达尔河，一直都是个难钓鱼的地方。现在对这把老骨头来说肯定太难了。\n\n如果你想找点挑战，可以从那片水域钓上一批墩鱼。我相信维弗拉一定会非常佩服。只是，小心湖里的那些长颈龙。我听说它们现在全都染上瘟疫了。",
  },
  [26106] = {
    ["T"] = "防熔岩龙虾",
    ["O"] = "在燃烧平原收集10只防熔岩龙虾，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "啊，燃烧平原……硫磺和啤酒的味道。让人心情大好，想抓起鱼竿和绕线轮出发。那里只有熔岩，但你仍然能钓上一顿盛宴。我说的是著名的防熔岩龙虾。外壳硬得像钉子，还耐火，但一旦把壳剥掉，哦！里面辛辣又烟熏的味道无可匹敌。\n\n奥苏哈有剥壳的钳子，所以等你弄到足够多可以分享的时候，就把它们带给他。",
  },
  [26107] = {
    ["T"] = "香鱼之水",
    ["O"] = "在费伍德森林收集一条芳香邪鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "$N，我永远搞不懂时尚。尤其是熊怪的时尚。维弗拉告诉我，黑喉会用他们过去从如今费伍德森林那地方弄来的鱼制作古龙水。臭死了！\n\n不过，如果这对我们这里毛茸茸的朋友很重要，那对我也重要。我想看看，即使水道已经被邪能魔法腐化，我们是否还能弄到这种芳香野兽。愿意试试看吗？",
  },
  [26108] = {
    ["T"] = "狂野安戈洛",
    ["O"] = "在安戈洛环形山收集10条脊齿火鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "世界上我没钓过鱼的地方不多，安戈洛环形山的荒野就是其中之一。如果这把老骨头还能爬下去，我很乐意在环形山未驯服的水域里甩竿。唉，我只好依靠你这样的年轻人了。\n\n奥苏哈很会处理异域鱼类。也许你能给我们带十条回来，让我们都能借你之口饱餐一顿？",
  },
  [26109] = {
    ["T"] = "兽人与过度捕捞",
    ["O"] = "在诅咒之地收集10条橙色粗皮鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "盘踞在诅咒之地邪石要塞、效忠军团的兽人，正在把附近海岸的鱼捕个干净，好喂饱他们贪得无厌的恶魔军队。我们必须行动起来，保护那些栖息在海岸上的可爱橙色粗皮鱼！\n\n钓上十条，然后把它们带回给维弗拉。她会确保它们在这里平安生活，这样等那些兽人被消灭后，我们最终还能再放归更多。",
  },
  [26110] = {
    ["T"] = "万中无一",
    ["O"] = "在艾萨拉收集一条蓝宝石镖鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "啊，艾萨拉。对我来说是家外之家，对我的朋友们来说则是真正的家。这里有太多可以钓鱼的地方，你总能找到新的最爱。\n\n我在艾萨拉钓鱼的时间比任何地方都多，但仍有一种渔获让我始终求而不得：蓝宝石镖鱼。熊怪如果钓到一条，会把它挂上战利品墙，而不是丢进炖锅！也许你可以亲手试试。它可能在任何地方……！",
  },
  [26111] = {
    ["T"] = "钓起怀表",
    ["O"] = "在灼热峡谷收集巴尔洛的怀表，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "哦天哪，$C，我现在可慌了。我刚从灼热峡谷的熔岩池旅行回来，却找不到我的幸运怀表了！\n\n这把老骨头再次上路前得歇一阵，可如果我等太久，等魔法消退，熔岩就会把我的表熔成液态糊糊。也许你能跳过去，替我把它钓上来？如果你能把它带回来，维弗拉会把它清理干净。",
  },
  [26112] = {
    ["T"] = "巨魔鳟鱼",
    ["O"] = "在塔纳利斯收集10条长鳟鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "安杰瓦萨的巨魔一直把淡水鳟鱼和咸水鲈鱼杂交，培育出一种新鱼，在他们那儿叫作“兰瓜”，用通用语说就是“长鳟鱼”。我们已经有一阵子没尝过它了。你为什么不去塔纳利斯看看能钓上什么？",
  },
  [26113] = {
    ["T"] = "童话钓鱼",
    ["O"] = "在辛特兰收集10条金鳞鲈鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "坐下，$C，我给你讲个故事。\n\n很久很久以前，辛特兰住着一些不会钓鱼的高等精灵。后来我和那里的枯木巨魔发生了一点麻烦，细节我就不说了，但作为救我的回报，我教会了他们钓鱼，他们可喜欢了！至少他们是这么告诉我的。\n\n后来才发现他们只是在哄我。从那以后我就有点不去那个地方了，不过如果你不介意过去一趟，维弗拉一直很想吃一堆金鳞鲈鱼。",
  },
  [26115] = {
    ["T"] = "卷起泥水",
    ["O"] = "在悲伤沼泽收集10条泥吻比目鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "你好啊，$C！我这把老骨头里嘎吱响着许多往日钓鱼故事，而且我有个提议给你。悲伤沼泽浑浊的水域里到处都是维弗拉喜欢的滑溜小家伙，我想是时候让我们下钩，看看能卷上什么了。不过小心，那片沼泽里可不只有鱼。那些浑水深处潜伏着危险，所以保持机灵。",
  },
  [26116] = {
    ["T"] = "筛沙",
    ["O"] = "在荒芜之地收集10条筛沙鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "我敢打赌你以为荒芜之地的意思就是那里不适合钓鱼。要是在那些地精到泉轴镇开张之前，你还真没错。结果沙漠下面有水，水里还有鱼！\n\n如果你还没去过那地方，那可错过了一些绝佳钓鱼点！所以，怎么样？准备好抛下鱼线，看看什么会上钩了吗？",
  },
  [26118] = {
    ["T"] = "荆棘谷条纹鱼",
    ["O"] = "在荆棘谷收集10条条纹倒立鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "你好啊，$R！听说过条纹倒立鱼吗？那鱼漂亮得会让别的鱼嫉妒它的鱼鳍。如今我可不像从前那么灵活了，我的钓具箱也需要休息，所以我把火炬传给你。去荆棘谷钓上十条这种滑溜的小恶魔吧。它们就像丛林自己的水下时装秀！\n\n不过重点在这里：等你钓到它们，就去找维弗拉。把这些漂亮鱼给她看，告诉她它们是艾泽拉斯水族圈里的极品。谁知道呢，也许我们还能教熊怪一点钓鱼知识，还能玩得很开心！现在出发吧，愿条纹倒立鱼像糖果店里的侏儒一样配合你！",
  },
  [26120] = {
    ["T"] = "利齿出没的水域",
    ["O"] = "在阿拉希高地收集一条利齿激流鱼，然后回到艾萨拉黑喉村的奥苏哈那里。",
    ["D"] = "向你致意，$C。如果你想找点宁静，也许可以去阿拉希高地看看，那里是少数几个相隔不远就能在两片海域钓鱼的地方之一！\n\n别被平静的景色骗了，这里的鱼可是会反咬一口——字面意义上的！小心利齿激流鱼。如果你站在它们聚集的水里，它们会咬掉你的腿。好在它们通常独来独往，所以这种机会很少。你能给奥苏哈带一个样本来吗？",
  },
  [26123] = {
    ["T"] = "鱼人泥跃鱼",
    ["O"] = "在希尔斯布莱德丘陵收集10条泥跃撕咬鱼，然后回到艾萨拉黑喉村的维弗拉那里。",
    ["D"] = "希尔斯布莱德丘陵有很多鱼人，沿着南部海岸到处都是。我在南海镇钓鱼时注意到，有一种特别的小泥跃鱼喜欢在那些鱼人周围出没，盼着从它们剩下的残渣里偷点肉。那些泥跃鱼很好吃，而我们这里的补给看起来相当低了。\n\n当然，你在希尔斯布莱德哪里都能找到泥跃鱼，但这就是我所知道的。怎么样，愿意挥动鱼竿和绕线轮，给我们带回一顿盛宴吗？",
  },
  [26130] = {
    ["T"] = "艾萨拉阿戈洛特币",
    ["O"] = "把艾萨拉阿戈洛特币带给藏宝海湾的阿塔迪娜。",
    ["D"] = "你找到了一枚艾萨拉阿戈洛特币。\n\n奇迹中的奇迹，你找到了一枚来自艾萨拉卡多雷王国的古代钱币。虽然这些钱币的许多破损版本散落在世界各地，但很少能见到一枚像这样保存完好的。\n\n稀有钱币收藏家会对这件物品感兴趣。",
  },
  [26131] = {
    ["T"] = "艾萨拉舍客勒币",
    ["O"] = "把艾萨拉舍客勒币带给藏宝海湾的阿塔迪娜。",
    ["D"] = "你找到了一枚艾萨拉舍客勒币。\n\n奇迹中的奇迹，你找到了一枚来自艾萨拉卡多雷王国的古代钱币。虽然这些钱币的许多破损版本散落在世界各地，但很少能见到一枚像这样保存完好的。\n\n稀有钱币收藏家会对这件物品感兴趣。",
  },
  [26278] = {
    ["T"] = "炎魔之王的副官",
    ["O"] = "杀死黑石深渊中的洛考尔领主和弗莱拉斯大使，然后回到艾萨拉的海达克西斯公爵那里。",
    ["D"] = "你已经向我证明，你能击败我们的敌人，并执行推进水元素领主事业的任务。但直到现在，你面对的还只是较弱的敌人……现在是时候让你承担需要更高技巧和更大危险的任务了。 \n\n在黑石山深处，黑铁矮人与炎魔之王的仆从勾结。杀死他的两名主要使者：洛考尔领主和弗莱拉斯大使。 \n\n做到这一点，向我证明你对我们事业的奉献。",
  },
  [26303] = {
    ["T"] = "熔火之心的协调",
    ["O"] = "前往艾萨拉海岸外的一座岛上寻找海达克西斯公爵。",
    ["D"] = "哦看啊，是$N。我以前见过你从我身旁走过，却完全没注意到这个地方的独特之处。离我站的地方不到两步，就有一道稳定的现实裂隙，通向黑石山深处，一个名叫熔火之心的地方。那里充满巨大邪恶，但对像你这样有冒险精神的人来说，也充满巨大荣耀。你想看看吗？ \n\n你当然想，但凡人若没有帮助就冒险前往那里，实在太危险了。幸运的是，我在这里，可以把你往正确方向推一把。 \n\n去寻找居住在艾萨拉海岸沿线的海达希亚水元素。他们与你的成功有切身利益。",
  },
  [26304] = {
    ["T"] = "熔火之心的协调",
    ["O"] = "把5朵火焰花、5株冬刺草、1份元素火焰和1份元素之水带给艾萨拉海岸外一座岛上的海达克西斯公爵。",
    ["D"] = "熔火之心是我们死敌火元素的巢穴。如果任由它们发展，它们会不断壮大，直到把整个艾泽拉斯点燃。 \n\n山脉狂暴的中心炽热无比，就连炎魔之王的黑铁盟友也难以承受。但如果你照我的吩咐去做，我会赐予你一项恩惠，让你能抵御火山核心的强烈高温。 \n\n首先，我需要在仪式中消耗一些元素材料。收集一份元素火焰、一份元素之水、一些火焰花和一些冬刺草。如果你无法自己在世界上找到这些东西，我相信凡人会在某种贸易集散地出售它们。",
  },
  [26305] = {
    ["T"] = "熔火之心的协调",
    ["O"] = "把托里德的炽热核心和基尼斯的冰冻核心带给艾萨拉海岸外一座岛上的海达克西斯公爵。",
    ["D"] = "接下来，我们需要与火焰和冰霜相契合的强大存在所灌注的精华。 \n\n在燃烧平原风暴祭坛附近，你会在一道熔岩瀑布中找到托里德。杀死他并取回他的炽热核心，对世界是一项恩惠。 \n\n至于冰霜，你需要杀死我在冬泉谷的表亲基尼斯。他栖息在凯斯利尔湖南边的冰冻瀑布沿线。 \n\n这很不幸，但也是必要的牺牲。",
  },
  [26387] = {
    ["T"] = "战斗的召唤：艾萨拉",
    ["O"] = "在艾萨拉找到并杀死5名部落成员。",
    ["D"] = "艾萨拉属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26388] = {
    ["T"] = "战斗的召唤：艾萨拉",
    ["O"] = "在艾萨拉找到并杀死5名联盟成员。",
    ["D"] = "艾萨拉属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26955] = {
    ["T"] = "制弓师的要求",
    ["O"] = "从角鹰兽或秃鹫身上收集20根制箭羽毛，然后回到寒风营地的玛瑞尔·杜蒙那里。",
    ["D"] = "根据这些笔记，游侠玛瑞斯曾用奎尔萨拉斯找到的材料制作自己的弩和弩矢，他一生中有很长时间都在那里度过。既然奎尔萨拉斯已经遭到毁灭，我们就得去别处寻找类似的东西。\n\n我们首先需要的是制箭用的羽毛。我相信我们可以从几个来源取得类似羽毛——强壮的角鹰兽或秃鹫，比如西瘟疫之地这里、艾萨拉，甚至更远的地方能找到的那些。",
  },
  [27074] = {
    ["T"] = "恶魔入侵者",
    ["O"] = "为艾萨拉黑喉村的大酋长昂加尔杀死10名雷加斯萨特、10名雷加斯潜行者和8名雷加斯唤魔者。",
    ["D"] = "许多季节以前，强大恶魔来到这片土地。我们部族帮助联盟赶走恶魔。大酋长乌恩·阿克选择这地方定居，远离他人，寻求和平。\n\n然后恶魔回来了。腐化夺走许多朋友。\n\n和平时间结束。隔绝时间结束。访客想和黑喉做朋友？杀死南边附近许多恶魔，证明朋友。然后我们谈。",
  },
  [27075] = {
    ["T"] = "恶魔入侵者",
    ["O"] = "杀死巴克萨兰，然后带着他的头颅回到艾萨拉黑喉村的大酋长昂加尔那里。",
    ["D"] = "你向黑喉展示友谊，但黑喉也要求你展示力量。\n\n南边恶魔中有一个叫巴克萨兰。他带头，恶魔跟随。\n\n你必须杀死巴克萨兰来展示力量。带头颅作为证明。然后我们才是真正朋友。",
  },
  [27076] = {
    ["T"] = "流亡者的后裔",
    ["O"] = "塔伦迪斯营地的阿希拉上尉要你杀死艾萨拉萨拉斯营地的10名血精灵开拓者和10名血精灵勘测员。",
    ["D"] = "来艾萨拉观光吗，$C？对那些不从历史中学习的人来说，这里没什么值得看的。这片土地本身和它的同名者，都证明了魔法会带来的危险。\n\n辛多雷原本是奎尔多雷的一部分，因鲁莽使用魔法而被逐出卡利姆多。然而，他们最近带着雇来的兽人护卫回到了艾萨拉。更令人担忧的是，报告说他们杀死了那些兽人，如今正在这里东北方为自己的目的勘测这片区域。\n\n他们肯定没安好心，我要阻止他们。替我消灭那些入侵者，你会得到报酬。",
  },
  [27080] = {
    ["T"] = "邪恶塑像",
    ["O"] = "为艾萨拉黑喉村的大酋长昂加尔偷取雷加斯萨特营地里的3根邪恶塑像图腾。",
    ["D"] = "南边恶魔制造邪恶塑像来行黑暗法术——一根燃烧骷髅的柱子。黑烟、坏魔法和更多恶魔都从塑像出来。\n\n我们拿走他们邪恶图腾，然后净化它们。偷走三个恶魔营地的图腾，证明你是黑喉朋友。打断他们的魔法。然后，我们谈。",
  },
  [27081] = {
    ["T"] = "如何与熊怪交朋友",
    ["O"] = "为艾萨拉黑喉村的诺尔格收集10根雷首角鹰兽羽毛。",
    ["D"] = "你好，外来者。你想学习熊怪之道？我帮助。\n\n仪式需要羽毛。来自黑喉村外的大角鹰兽。但不要杀。它们落在地上，我们带着感谢拾起，当作礼物。朋友帮助朋友需要的东西，所以你收集羽毛帮助诺尔格？然后我们是朋友。",
  },
  [27083] = {
    ["T"] = "晃荡谷的威胁",
    ["O"] = "为艾萨拉晃荡谷的温迪·晃轮杀死10名恶鞭尖啸者和10名恶鞭战士。",
    ["D"] = "我的家人是用艰难方式来到艾萨拉的——我们的飞机燃料耗尽，坠进了海里。抵达过程不算平稳，但我们被冲到下面的海滩上，等把自己拖上这座悬崖后，我们决定就在这里开张。这也许不是我们原本的打算，但晃荡谷现在就是我们的家，我要保护它免受艾萨拉荒野中那些威胁的侵扰。\n\n如果你愿意帮忙，我很乐意为你的服务付一笔费用。恶鞭纳迦部族住在门纳尔湖北边的精灵废墟里。专门干掉战士和尖啸者。他们看起来像纳迦的炮灰，所以你应该不会遇到太多麻烦。",
  },
  [27084] = {
    ["T"] = "晃荡谷的威胁",
    ["O"] = "为艾萨拉晃荡谷的温迪·晃轮杀死10名恶鞭海妖和10名恶鞭侍从。",
    ["D"] = "看来我让你解决那些低阶纳迦，导致破碎海岸那边聚集了更多熟练纳迦。我说的是那些在整片海滩上巡逻的恶鞭侍从和海妖。如果他们的巡逻增多，也许会发现我们在海岸这里的存在，而我不能让那种事发生。\n\n我还能指望你再帮我们一次吗？",
  },
  [27085] = {
    ["T"] = "晃荡谷的威胁",
    ["O"] = "为艾萨拉晃荡谷的温迪·晃轮杀死艾萨拉南部海岸沿线的8名风暴海湾智者。",
    ["D"] = "你反击纳迦时，我发现了另一个必须处理的威胁。这里东边海岸上的风暴海湾智者，威胁要通过黑暗仪式释放强大的风暴。如果放任不管，通往艾萨拉的海路和空路都可能受到破坏！\n\n我需要你沿着海岸前进，终结他们的阴谋。小心，这些鱼人掌握强大的自然魔法，对元素的驾驭也很可怕。如果你成功，我会很乐意再次奖赏你的努力。",
  },
  [27086] = {
    ["T"] = "恶鞭的首领",
    ["O"] = "为晃荡谷的温迪·晃轮杀死艾萨拉拉文凯斯雕像附近名叫女巫雅莉娜的恶鞭首领。",
    ["D"] = "嘿，$N，如果你有兴趣，我还有一份保护工作给你。\n\n恶鞭纳迦是我们在艾萨拉这里的敌人，而一名新的首领已经从海上抵达，准备接管他们。我们的远程传感器记录到了她的到来。\n\n有了本地首领坐镇，只要纳迦愿意，就没有什么能阻止他们聚集起来入侵晃荡谷。没有首领，他们会陷入混乱，足够让我们在这里准备好防御。\n\n你可以在远东边的悬崖顶上，拉文凯斯雕像周围找到女巫雅莉娜。解决她，给我们争取点时间！",
  },
  [27087] = {
    ["T"] = "掠夺亚考兰神殿",
    ["O"] = "从艾萨拉西北部的亚考兰神殿收集任何可能有价值的遗物。",
    ["D"] = "如果你愿意调查艾萨拉遥远西北部的亚考兰神殿，就留意任何不寻常、可能对我们有价值的东西。\n\n我不知道具体会包括什么——卷轴、书籍、药水……纳迦似乎特别喜欢石板和雕像……？\n\n总之，如果你找到任何有趣且小到能带走的东西，我想看看。",
  },
  [27090] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "从风暴海湾的精灵废墟中收集8件浸水的上层精灵遗物。",
    ["D"] = "$C，你和你的主人把这个带给我，做得很好，但这块石板只是艾萨拉上层精灵圣物匣中曾经存在的知识的一小部分。\n\n也许可以用这块完整石板作为解码器，解读散落在风暴海湾中那些破碎无用的遗物。潜入水中，为我取回一些，好让我进行比较。",
  },
  [27094] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "搜索艾萨拉东南角的潮池，寻找纳迦流亡者的位置。",
    ["D"] = "你从风暴海湾取回的遗物，只与圣物匣石板上的符文部分匹配。这道谜题还缺一块，而我想我知道从哪里取得。\n\n根据我的占卜，有一名纳迦女巫隐居在艾萨拉东南角、拉文凯斯雕像下方潮池中隐藏的洞穴里。我希望你找到她，请她协助破译石板。\n\n我有理由相信她会愿意帮助我们。",
  },
  [27095] = {
    ["T"] = "艾萨拉的遗产",
    ["O"] = "杀死一名亚考罗克之子，并把它的深渊徽记带给艾萨拉的大法师克希雷姆。",
    ["D"] = "你的“大学者”朋友以为占卜到我很聪明，却没有意识到他能做到，只是因为我愿意被找到。自从你从亚考兰神殿拿走石板起，我就一直看着你的旅程。你如今走上的道路威胁着所有生活在艾萨拉的人，如果我袖手旁观，那就太不负责任了。\n\n所以我只对你说一次：你们凡人插手这种规模的魔法是愚蠢的。它来自深海的力量，并不属于你们。你们无法控制它。\n\n我知道你不太可能听从我的话，所以我还告诉你另一件事。亚考罗克之子能找到那块石板，是因为他们深入海洋时携带着一种特殊的防护徽记。杀死其中一个，拿走它的徽记。它也许能给你足够保护，让你在自己的错误中活下来。",
  },
  [27105] = {
    ["T"] = "来自晃荡谷的补给",
    ["O"] = "和艾萨拉晃荡谷的威尔伯·晃轮谈谈，请他帮忙提供备用工程零件。",
    ["D"] = "能在这片荒野里遇见一位工程师同道，真是巧啊。我一直在努力让这个前哨站的一切运转起来，我跟你说，这可不容易！\n\n听着，能不能帮我个忙，工程师对工程师？我的原始部件快用完了，你知道，就是齿轮什么的。门纳尔湖南边悬崖边上有一群侏儒扎了营。跑下去看看他们有没有什么闲置备用零件能便宜弄到，我会让你觉得值得。\n\n是，我知道他们是联盟的一部分，但他们还挺友好的。",
  },
  [27106] = {
    ["T"] = "来自晃荡谷的补给",
    ["O"] = "从艾萨拉南部的海洋和海岸收集10份沉船零件，然后使用有限传送提示器返回艾萨拉的晃荡谷。",
    ["D"] = "如果说工程师需要很多什么东西，那就是备用零件。不幸的是，我们没有多少额外补给摆着。我们自己一直也在搜刮零件。不过好消息是，我们的来源也可以成为你的来源。\n\n<威尔伯指向南方开阔的大海。>\n\n那里有很多沉船，也有很多零碎东西可以搜刮，只要你愿意做点深海潜水。来，我会给你这个传送信标，你会在我们这里的传送器旁冒出来。你得有效率点——电池只能维持那么久。祝你好运！",
  },
  [27109] = {
    ["T"] = "恶鞭巫术",
    ["O"] = "从恶鞭海妖或恶鞭法师身上取得10份编码海卷轴，然后回到艾萨拉法师塔的乔艾·阿纳雷斯那里。",
    ["D"] = "虽然我看得出你是个有些本事的附魔师，但只要你愿意替我做几件微不足道的小事，我还能教你很多。\n\n当永恒之井的爆炸撕裂大地时，强大的上层精灵法师变成了纳迦。他们仍掌握着许多旧日秘密，而我打算收集它们。\n\n杀死纳迦海妖或法师，取得她们携带的十份卷轴。你可以在南边破碎海岸的海滩上，或艾萨拉遥远东南角拉文凯斯雕像周围的山丘上找到她们。\n\n现在去吧！",
  },
  [27110] = {
    ["T"] = "恶鞭巫术",
    ["O"] = "从艾萨拉东南部拉文凯斯雕像的女巫雅莉娜身上取得一枚恶鞭法术贝壳，然后回到艾萨拉法师塔的乔艾·阿纳雷斯那里。",
    ["D"] = "这些卷轴似乎被一种魔法密码编码了，没有正确钥匙解开密码的人完全无法使用。幸运的是，大法师克希雷姆本周早些时候通过占卜找到了可能的解决办法。\n\n在他对这片区域的例行占卜中，他注意到一名新指挥官已经驻扎在艾萨拉遥远东南角的拉文凯斯雕像处。这个女巫雅莉娜一定拥有用来解读这些卷轴的钥匙或信物。杀了她，把那个信物带回来给我！",
  },
  [27115] = {
    ["T"] = "打捞海岸",
    ["O"] = "为艾萨拉晃荡谷的威尔伯·晃轮从艾萨拉海滩收集10份沉船补给。",
    ["D"] = "$C，如果你不介意，我还有更多活给你。风暴海湾南部沿岸的潮池和海岸被称为南山海滩。在我们的飞机坠毁到这里之前，我对那片区域做过几次空中勘察。我注意到那里有很多残骸被冲上岸的地方。我想让你去南山看看那些箱子。如果你找到任何对我们在晃荡谷行动有用的东西，我会付钱给你。怎么样？",
  },
  [27116] = {
    ["T"] = "打捞打捞者",
    ["O"] = "杀死亚考兰鱼人，取回闪亮打捞品箱，交给艾萨拉晃荡谷的威尔伯·晃轮。",
    ["D"] = "我的空中勘察还发现了另一个值得注意的区域：遥远西北方、风暴海湾另一侧的亚考兰神殿。在海湾巡逻的海巨人会捡起各种东西，把它们留在那里让鱼人翻找。我相信那些鱼人剥走各种货物并囤积起来。鱼人似乎喜欢亮闪闪的东西。\n\n总之，这意味着他们的囤货正适合我们收集。鱼人是讨厌的生物，消灭它们是公益。额外好处是，你还能从它们身上搜到对晃荡谷极其宝贵的材料！你对这份工作有兴趣吗？",
  },
  [27117] = {
    ["T"] = "打捞恶鞭",
    ["O"] = "杀死恶鞭军官和恶鞭法师，为艾萨拉晃荡谷的威尔逊·晃轮收集打捞卷轴。",
    ["D"] = "我能勘察到的最后一个地方是在拉文凯斯雕像附近，艾萨拉最东南端。我注意到那里住着恶鞭纳迦，其中还有法师——换句话说，强大的施法者。我们侏儒是技术专家，但有时候魔法也能补充技术不容易做到的事。\n\n这些纳迦经常带着施过普通法术的卷轴。我希望你替我们把一些卷轴从她们手里拿走，这样我们就能用她们的魔法补充晃荡谷的技术——顺便还能清除我们家园附近的一个纳迦威胁！",
  },
  [27118] = {
    ["T"] = "侦察亚考兰神殿",
    ["O"] = "前往艾萨拉西北部的亚考兰神殿，杀死8名亚考兰泥浆鱼人和8名亚考兰智者。",
    ["D"] = "欢迎来到边疆，$C。你和我一样感觉到这片土地的狂野能量了吗？\n\n哈格鲁姆和阿格图关心的是我们周围看得见的威胁，他们这样做是对的。但我看得更远，我看见他们称作亚考兰的伟大神殿，以及……<颤抖>……潜伏其中、在地平线上逼近的鱼人。\n\n我奉命留在这里观察麻烦，但也许你愿意替我去清除它们，免得以后我们遭遇鱼人入侵的噩梦？",
  },
  [27126] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和艾萨拉的基姆加尔谈谈，在热砂港和黑喉村之间开辟贸易路线。",
    ["D"] = "你好，新朋友。我叫玛鲁，黑喉商人。\n\n现在我们向外来者开放村子，我从贸易中收集到许多新小玩意。一个新朋友是名叫基姆加尔的绿色小人。绿色小人说他能帮助和许多其他绿色小人贸易，离黑喉村很远。\n\n玛鲁必须待在村里和外来者交易，但也许你能找到绿色小人，告诉他玛鲁现在想交易。他住得不远，在精灵营地上方的山上。",
  },
  [27128] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和热砂港的贾比谈谈，在热砂港和黑喉村之间开辟贸易路线。",
    ["D"] = "听着，$N……我能叫你$N吗？烟林牧场经营的是高端优质商品。这听起来简直就是“手工精品”的定义。艾萨拉森林里的熊做的手工艺品？哈！不过这也许能让我们打入麻烦的暗夜精灵市场……嗯……\n\n<M.斯宾塞·铜栓思考了一会儿。>\n\n不，不，那绝对行不通。抱歉，$N，我不需要你提的东西，基姆加尔大概只是把你打发到我这里，好让你别再缠着他。不过我告诉你——既然我是个正派企业家，我可以把你介绍给一个可能对熊怪卖的东西感兴趣的人。我的老室友贾比在塔纳利斯的热砂港卖货。也许来自遥远北方的东西对他的顾客来说会很新奇？",
  },
  [27129] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和商队老板拉兹戈特谈谈，在热砂港和黑喉村之间开辟贸易路线。",
    ["D"] = "你知道吗，$N……我能叫你$N吗？你知道，不是每天都有像你这么新鲜的冤大头走进我的店，编出什么森林里的熊会做玩具的故事。这笑话不错！\n\n等等，你是认真的？\n\n嗯。好吧，自从石油开始流动、水泵开始抽水后，热砂港这里热闹多了。而这意味着游客！不管你是想给藏宝海湾孩子带点东西回去的海盗，还是需要消遣的口渴商队老板，我都能卖给你。所以好吧，行，我们试试看！\n\n我们首先需要的是基础设施。得有人能在艾萨拉靠岸，拿上货物，再把它们运到这里来。你为什么不去藏宝海湾和商队老板拉兹戈特谈谈，看看他是否已经在北方海域建立了什么关系？",
  },
  [27130] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和泉轴镇的约阿基姆·火根谈谈，在热砂港和黑喉村之间开辟贸易路线。",
    ["D"] = "我的一个前打手，在热砂港搬进荒芜之地的泉轴镇时，开了自己的商队公司。我估计他能多接点活，毕竟那地方是片荒地。他叫约阿基姆·火根，你应该能在他休息日时在镇上附近找到他。\n\n告诉他是拉兹戈特派你来的，他甚至可能会降低服务费！",
  },
  [27131] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和永望镇的乌玛隆·斯特拉加榆谈谈，在热砂港和黑喉村之间开辟贸易路线。",
    ["D"] = "拉兹戈特的想法没错，但我不是干这活的地精。我一想到离开荒芜之地就受不了。这里有大量生意可做，我不会为了几只熊错过这些机会，不管它们听起来多有意思。\n\n不过嘿，这趟不算完全白跑。我以前有个雇员讨厌炎热，所以他去了离沙漠尽可能远的地方——冬泉谷。去永望镇找乌玛隆·斯特拉加榆。他没工作，而且有做这活的经验。\n\n祝你好运，$N……我能叫你$N吗？",
  },
  [27132] = {
    ["T"] = "熊怪——地精贸易网络",
    ["O"] = "和黑喉村的商人玛鲁谈谈你开辟的贸易网络。",
    ["D"] = "你说这个黑喉村在海岸上？而我要把货物送到塔纳利斯的热砂港？听起来够简单。我会借我姐姐的蒸汽船。她嫁给了一个侏儒……不知道怎么做到的。\n\n我下个月就能开始跑这条线。只要告诉你在村里的联系人，准备好要发运的物品。篮子、箱子，怎么都行。只是别散着放，否则损坏我不负责。\n\n他寄了合同吗？没有？好吧，他是只熊。不知为什么，我觉得他们不太碰很多文书。\n\n总之，你可以告诉他，说定了就是定了。谢谢这份活。",
  },
  [27133] = {
    ["T"] = "小偷！",
    ["O"] = "从雷瑟斯圣所找回亚历山德拉的文本，然后把它还给艾萨拉废墟海岸的她。",
    ["D"] = "这不是我们第一次遭到纳迦的袭击——用手、爪子、鱼鳍，随便怎么说！我们刚到时，就在海滩上扎营。还没反应过来，鱼人和纳迦就一起伏击我们，迫使我们撤退到这里。\n\n我只回头看过一次，但我看到其中一个鱼人把它那鱼腥手指全都弄到我花费多年心血写成的文本上。拜托，如果你能替我取回它，我会很乐意付钱。他们看起来像是从东边雷瑟斯圣所的方向来的。",
  },
  [27134] = {
    ["T"] = "以防万一",
    ["O"] = "杀死雷瑟斯圣所的10名恶鞭袭击者和5名恶鞭女巫，然后回到艾萨拉废墟海岸的帕特里克·米尔斯那里。",
    ["D"] = "自从纳迦把我们逼回这里，我们就一直处于防御状态。眼下我们能喘口气，但必须做点什么，让他们在医生照料伤员时别再来纠缠我们。\n\n亚历山德拉说她看到纳迦是从雷瑟斯圣所那边靠近的。如果你愿意帮忙，那里就是打击他们的地方。运气好的话，他们会在派出更多袭击前再三考虑。",
  },
  [27135] = {
    ["T"] = "濒临崩溃",
    ["O"] = "为艾萨拉废墟海岸的特尔丁医生收集3箱医疗补给。",
    ["D"] = "这简直是噩梦。先是船沉了，然后我们被围攻，现在补给也快用完了。\n\n帮我个忙好吗？我们的一些医疗补给可能从南边地平线斥候号的残骸里漂了上来。我还看到西边好像有一座侏儒房子。他们也许会卖补给。\n\n如果你能从任一处给我带来医疗补给，你就能让我们在艾萨拉接下来丢给我们的任何灾难中活下去。",
  },
  [27136] = {
    ["T"] = "地平线斥候号",
    ["O"] = "在艾萨拉地平线斥候号附近找到大副杉德里尔。",
    ["D"] = "我和我的船员很幸运你路过。事情开始对我们有起色了。\n\n我知道我们已经向你要求很多，但我们刚被困在这里时，我的大副杉德里尔出发去地平线斥候号附近查看是否还有其他幸存者。你能在我守住这里时去看看她吗？她应该就在我们位置南边。",
  },
  [27139] = {
    ["T"] = "地平线斥候号",
    ["O"] = "回到艾萨拉废墟海岸的瓦妮莎·贝蒂斯船长那里。",
    ["D"] = "你现在能做的差不多都做了。我会留在这里，看看还能打捞些什么，然后再回去。\n\n你应该去向船长报到。",
  },
  [27141] = {
    ["T"] = "破碎海岸的指挥官",
    ["O"] = "找到并消灭破碎海岸上的潮汐女祭司阿奎拉，然后向艾萨拉晃荡谷的温迪·晃轮报告你的胜利。",
    ["D"] = "这个纳迦带着一套似乎用海藻包裹的命令。虽然你看不懂纳迦难以理解的文字细节，但你认出命令中提到了一名指挥官：潮汐女祭司阿奎拉。\n\n除掉破碎海岸上恶鞭的指挥官，肯定会让温迪·晃轮高兴，也有助于确保晃荡谷的安全。也许你该检查一下附近的小亭？",
  },
  [27143] = {
    ["T"] = "木喉盟约",
    ["O"] = "和守门人拉格罗尔谈谈，并解释黑喉熊怪没有被腐化。你必须至少与木喉保持中立，他们才会和你说话。",
    ["D"] = "既然你是黑喉朋友，你可以做黑喉做不了的事。\n\n木喉熊怪是兄弟，但不信任任何其他熊怪。有好理由。许多被腐化。但木喉像黑喉。你可以成为木喉朋友。如果你同时是木喉和黑喉朋友，你可以替黑喉把消息带给守门人拉格罗尔。\n\n拉格罗尔守着木喉要塞入口。但你必须是木喉朋友才能靠近。告诉他们黑喉没有被腐化。告诉他们我们也是朋友。",
  },
  [27144] = {
    ["T"] = "木喉盟约",
    ["O"] = "和艾萨拉木喉要塞的斥候加勒斯谈谈。",
    ["D"] = "$C，我信任你，因为你是木喉朋友，也说你是黑喉朋友。但信任有时需要证明。\n\n<守门人拉格罗尔思考着。>\n\n我派斥候加勒斯和你一起去黑喉。你保护。他会看见真相并报告。带上他，好好上路。",
  },
  [27145] = {
    ["T"] = "木喉盟约",
    ["O"] = "护送斥候加勒斯前往黑喉村，帮助证明黑喉没有被腐化。",
    ["D"] = "我从没和黑喉说过话。恶魔来之前，他们就住得很远。听过他们酋长的吓人故事。有人说他会变成狼。你见过吗？没有？那也许不是真的。\n\n你准备好时我也准备好了。如果我们遇到恶魔，保护我，这样我才能见到黑喉。",
  },
  [27146] = {
    ["T"] = "木喉盟约",
    ["O"] = "把守门人拉格罗尔的友谊提议带回艾萨拉黑喉村的大酋长昂加尔那里。",
    ["D"] = "作为木喉朋友，你把这条消息带给黑喉。我们看见你们。我们闻见你们。我们一起对抗恶魔。\n\n我们注视黑喉，黑喉注视木喉。如果腐化到来，我们做必须做的事。\n\n现在，带着友谊去吧，$N。",
  },
  [27147] = {
    ["T"] = "即将到来的寒冬",
    ["O"] = "为猪倌古努格从艾萨拉的苔蹄麋鹿身上收集10份鹿肉排。",
    ["D"] = "$N，猪是我的热爱，但只靠猪没法让我们撑过冬天——尤其是它们自己也得吃东西！\n\n我见过森林里有些大块头有肉的野兽四处游荡，头上长着巨大的角。我听一个牛头人叫它们“麋鹿”或者“雄鹿”之类的。它们看起来很好吃，而我们需要为即将到来的冬天做准备。你能给我带些它们的肉来储备吗？",
  },
  [27151] = {
    ["T"] = "饥饿的侏儒",
    ["O"] = "从艾萨拉的苔蹄麋鹿身上收集10份鹿肉排，并把它们带给晃荡谷的威廉明娜·晃轮。",
    ["D"] = "嘿，$R！欢迎来到晃荡谷。\n\n我本想请你吃点东西，但说实话，我们除了鱼之外没什么可嚼的。天天都是。\n\n虽然大海能让我们不至于挨饿，但我就是想吃一块多汁的肉排。我见过森林里有些威风的雄鹿，可我不是猎人。如果你有兴趣，给我带回一堆鹿肉，我会让你觉得值得。",
  },
  [27152] = {
    ["T"] = "饥饿的侏儒",
    ["O"] = "从埃达拉斯废墟和破碎海岸的恶鞭纳迦身上收集10份搜刮来的补给，然后回到艾萨拉晃荡谷的威廉明娜·晃轮那里。",
    ["D"] = "我很想现在就把这些做熟，可天哪，要是有点香料该多好。一点擦料，一点盐……等等，这让我有了个主意！\n\n风暴海湾是个危险的地方，船只经常在那里失事并被冲上岸。这些残骸会被破碎海岸上的恶鞭纳迦洗劫。我敢说他们那里有大量补给，而且我几乎可以保证里面会有香料！\n\n我不知道你会发现它们散落在地，还是得用武力从纳迦手里拿走补给，但如果你能搜刮到我想要的东西，我会给你丰厚报酬。",
  },
  [27153] = {
    ["T"] = "饥饿的侏儒",
    ["O"] = "杀死亚考兰龙虾人，收集10只巨大的龙虾人钳子，交给艾萨拉晃荡谷的威廉明娜·晃轮。",
    ["D"] = "太好了！挖到宝了，$N！这些箱子里有一大堆舒缓又辛辣的香料。但现在，我有了个更好的主意……\n\n有什么比肉排更好？配上龙虾的时候！\n\n我知道我说过自己受够海了，但现在既然我想吃海陆大餐，就再也甩不掉这个念头。\n\n所以我们还需要龙虾的来源。你见过那些在艾萨拉游荡、长着巨大肥美钳子的龙虾人吗？在艾萨拉遥远西北角的亚考兰神殿附近，有一大群它们晃来晃去。杀死响钳龙虾人和巨钳龙虾人，把那肉带给我！你能想象那会是什么味道吗？",
  },
  [27154] = {
    ["T"] = "饥饿的侏儒",
    ["O"] = "从黑喉村的商人玛鲁那里取得黑喉黄油，并把它带回艾萨拉晃荡谷的威廉明娜·晃轮那里。",
    ["D"] = "好了，$N！我们有海鲜了！有肉了！有擦料了！有……哦不……哦不！我们没有黄油。没有黄油，怎么能做出又多汁又有黄油香的肉排和龙虾？\n\n我不能让这个梦想死掉，$N。我们也许还有一点机会从艾萨拉某处弄到黄油。\n\n北部海岸沿线有个熊怪营地，对外来者很友好。我听说他们交易各种货物。如果你拿这块培根和他们交换，也许他们能提供黄油？",
  },
  [27163] = {
    ["T"] = "通缉：蓝龙",
    ["O"] = "为晃荡谷的温迪·晃轮杀死5名蓝色龙人、5名蓝色刃鳞龙人和5名龙人施法者。",
    ["D"] = "冒险者注意：晃荡谷北边门纳尔湖附近栖息着一群蓝龙。这些敌人威胁着我们在这里的工作。现向任何能削减其数量的人提供奖励。 \n\n警告：这些敌人非常强大。\n\n完成这项任务后，和晃荡谷的温迪·晃轮谈谈。",
  },
  [27164] = {
    ["T"] = "通缉：峭壁巨人",
    ["O"] = "杀死5名峭壁巨人，然后和艾萨拉晃荡谷的温迪·晃轮谈谈。",
    ["D"] = "冒险者注意：峭壁巨人在艾萨拉远方游荡。这些可怕生物的践踏正在影响我们在晃荡谷使用的精密设备。任何能消灭一些巨人、恢复安宁的小队都将获得奖励。\n\n警告：这些敌人非常强大。",
  },
  [27507] = {
    ["T"] = "以力换力",
    ["O"] = "用5块红色能量水晶、5块黄色能量水晶、5块蓝色能量水晶和5块绿色能量水晶，向艾萨拉黑喉村的商人玛鲁交换一根黑喉仪式图腾。把图腾带给安戈洛环形山的莫尔维克。",
    ["D"] = "我想试试从托尔瓦·寻路者那里听说的一种新训练技巧。他告诉我，艾萨拉那边有一支名叫黑喉熊怪的生物部族。他们会制作能让野兽信任训练师的安抚图腾，我希望你替我取来一根。\n\n照托尔瓦的说法，单纯的钱币不足以换取这样的物品。必须交易。既然图腾代表力量，也许等价交换力量会有用？\n\n收集安戈洛各处生长的每种颜色能量水晶各五块，把它们带到艾萨拉北部的村子，看看他们是否愿意接受这笔交易。",
  },
  [27522] = {
    ["T"] = "阿鲁-塔利斯的传说",
    ["O"] = "沿着安戈洛环形山边缘寻找阿鲁-塔利斯的废墟，并把你找到的任何东西带回给杰尔莎·石歌。",
    ["D"] = "你好，$R。请原谅我现在如此虚弱。我是杰尔莎·石歌，艾露恩的姐妹。我来到安戈洛环形山寻找一个传说：传说中的精灵城市阿鲁-塔利斯。\n\n据说我族的祖先曾躲进这座环形山，以避开狂暴的巨魔战帮。他们建起一座可与艾萨拉任何城市比肩的城市，并将其称为阿鲁-塔利斯。后来它走向毁灭，甚至在艾泽拉斯大分裂之前许多年就已如此。\n\n环形山是个危险的地方，我被这一带的生物重创。我会恢复，但你愿意继续搜索吗？我穿过了环形山中央，却还没有搜索它的边缘。拜托，在我们周围的山丘和高地中寻找任何我祖先留下的痕迹。",
  },
  [27584] = {
    ["T"] = "魂精交换",
    ["O"] = "用5份枭兽魂精和5份冰草魂精，向艾萨拉黑喉村的商人玛鲁交换一根黑喉仪式图腾。把图腾带给冬泉谷的雷沃·霜翼。",
    ["D"] = "在堕入腐化之前，冬泉熊怪常常协助训练冬泉霜刃豹。他们会制作安抚图腾，帮助野兽信任我。我听说艾萨拉的黑喉熊怪部族也制作类似图腾，我希望你替我取来一根。\n\n如果他们和冬泉熊怪相似，单纯的钱币不足以换取这样的物品。必须交易。永望镇的巫医玛艾里已经找到了从冬泉谷居民身上抽取魔力的方法。也许一些这种“魂精”会让黑喉部族感兴趣？\n\n如果你不确定如何取得魂精，就去和永望镇的巫医谈谈。否则，试试枭兽和雪人的精华——它们与熊怪相似，但灌注了冰霜和奥术之力。",
  },
  [27609] = {
    ["T"] = "给威尔伯·晃轮的委托",
    ["O"] = "威尔伯·晃轮要你使用炼金术技能制作5瓶强效敏捷药剂，并把订单交给艾萨拉晃荡谷的威尔伯·晃轮。",
    ["D"] = "哦，一位炼金师。我不懂那种特定门类的科学，但我尊重它！\n\n说起来，我能请你帮个忙吗？有时我会把一两件，甚至三件工具弄掉到这座悬崖边下面。我可以用这里的传送器跳下去再回来，但驱动它的能量很宝贵。如果我有一些强效敏捷药剂，就能直接攀上悬崖，把电池留到真正需要的时候。愿意帮忙吗？",
  },
  [27659] = {
    ["T"] = "给大酋长昂加尔的委托",
    ["O"] = "温迪·晃轮要你使用锻造技能制作4把真银万能钥匙，并把订单交给艾萨拉北部黑喉村的大酋长昂加尔。",
    ["D"] = "嘿！你是铁匠，对吧？\n\n我一直在想，有什么象征性的好礼物可以送给那些黑喉熊怪，向他们表明我们不是威胁。我觉得我找到了正合适的东西：一些真银万能钥匙。你懂的，友谊的钥匙之类的？我需要一名铁匠帮我们制作并送出这些钥匙。有兴趣吗？",
  },
  [27954] = {
    ["T"] = "隐形之物",
    ["O"] = "夜间，在艾萨拉门纳尔湖从门纳尔湖之灵身上收集灵魂残渣。",
    ["D"] = "当你听到“隐形”时会想到什么？盗贼？也许是某种……荒唐的法师法术？！\n\n我告诉你我会想到什么。鬼魂！你知道鬼魂只在自己想现身时才会现身吗？呃，大多数是这样。\n\n我读到过艾萨拉那边有一个这样的鬼魂——故事很悲伤……也许下次再讲！你可以在门纳尔湖上方找到它，但只有太阳不照耀时才行！非常重要——你只能在夜间找到它！\n\n击败它，把它留下的灵魂残渣带回来给我。我确信那正是我们需要的东西！",
  },
  [28006] = {
    ["T"] = "火焰仪式",
    ["O"] = "从艾萨拉拉文凯斯雕像附近的纳迦那里收集烛台、餐巾、餐垫和银餐具，并把它们带给塔纳利斯热砂港的卡雷姆。",
    ["D"] = "一万多年里，我从没听说过如此奇怪的请求，但我承认，这很有趣。作为文明民族，我们当然有你寻找的物品。\n\n没有纳迦会轻易交出他们辛苦得来的餐桌布品，所以必须使用武力。也许你应该去艾萨拉的拉文凯斯雕像。那些不是我的族人，而且他们与世隔绝太久了。你的出现会搅动他们，让血液流动起来。我想，是字面意义上的。",
  },
  [28022] = {
    ["T"] = "深渊仪式",
    ["O"] = "和艾萨拉黑喉村的维弗拉谈谈。",
    ["D"] = "作为一名热心钓手，我相信你以前去过黑喉村。如果没有，那你可真错过了！那是艾萨拉北部海岸上的一个熊怪村，他们痴迷钓鱼。\n\n总之，我觉得我需要一些新鱼饵来添点花样。我一直很欣赏黑喉的手艺。你愿意上那里去，给我弄一个他们的鱼饵吗？",
  },
  [28397] = {
    ["T"] = "给威廉明娜·晃轮的委托",
    ["O"] = "威廉明娜·晃轮要你使用附魔技能制作1块魔化瑟银锭，并把订单交给艾萨拉晃荡谷的威廉明娜·晃轮。",
    ["D"] = "我们还需要很多补给，才能让晃荡谷真正运转起来。具体来说，我需要一些魔化瑟银锭，用来打造一个能烹饪我们在这里找到的任何东西的厨房。你有兴趣提供吗？",
  },
  [28447] = {
    ["T"] = "给基姆加尔的委托",
    ["O"] = "威尔逊·晃轮要你使用工程学技能制作2个致命瞄准镜，并把订单交给艾萨拉雷加什营地的基姆加尔。",
    ["D"] = "哦！一位工程师同道！我到哪儿都认得出你指甲底下的油污！\n\n听着，你接活吗？晃荡谷周围有一大堆任务需要处理，所以我抽不出时间去帮别人。北边恶魔那边住着一个地精，正在找人给他制作几个致命瞄准镜。如果你有兴趣赚点钱，他大概会为你的服务付不少！",
  },
  [28483] = {
    ["T"] = "给大酋长昂加尔的委托",
    ["O"] = "大酋长昂加尔要你使用急救技能制作20份厚魔纹绷带，并把订单交给艾萨拉黑喉村的大酋长昂加尔。",
    ["D"] = "恶魔用火焰和暗影打击。我们战斗，但伤口很多。\n\n我听说你的药和布，不用草药或魔法也能治疗。我想试试。给我带20份厚魔纹绷带，我看看你们的办法能否帮助我的人民。",
  },
  [28510] = {
    ["T"] = "给基姆加尔的委托",
    ["O"] = "基姆加尔要你使用钓鱼技能收集20只黑爪龙虾，并把订单交给艾萨拉雷加什营地的基姆加尔。",
    ["D"] = "我在逃离那些该死的血精灵时失去了一切——笔记、工具、零食——甚至到现在还没找到我最喜欢的叉子。\n\n我现在真正需要的是一顿像样的饭。如果你能给我带20只黑爪龙虾，至少在我想清楚下一步该怎么办时，肚子里能有点热乎东西。",
  },
  [28532] = {
    ["T"] = "给布利莫·机簧的委托",
    ["O"] = "布利莫·机簧要你使用草药学技能采集20株梦叶草，并把订单交给艾萨拉晃荡谷的布利莫·机簧。",
    ["D"] = "第三次战争中，我是少数随联盟军队来到卡利姆多的侏儒之一。我的部队回家时，我留了下来。自从见到那些恶魔后，困扰我的念头就始终挥之不去。\n\n我很感激能在晃荡谷找到一处容身之地和一个目标，但我仍然需要些东西来对付梦境。我听说梦叶草可能是有效疗法。梦……叶草……名字里就写着呢。",
  },
  [28622] = {
    ["T"] = "给德蕾吉的委托",
    ["O"] = "德蕾吉要你使用剥皮技能采集5张硬甲毛皮，并把订单交给艾萨拉黑喉村的德蕾吉。",
    ["D"] = "冬天悄悄逼近，不是每个人都有庇护。艾萨拉的风咬得很深，尤其在夜里。\n\n我需要5张硬甲毛皮做温暖毯子。保护我们的幼崽。简单的活，但意味着许多人能活下去。",
  },
  [28648] = {
    ["T"] = "给威尔逊·晃轮的委托",
    ["O"] = "威尔逊·晃轮要你使用采矿技能采集20块瑟银锭，并把订单交给艾萨拉晃荡谷的威尔逊·晃轮。",
    ["D"] = "$N，真是灾难！我们起飞时有四架飞机，现在只打捞回一架，要让它重新运转起来，除非有奇迹。\n\n不过，你也许可以帮我凑到20块瑟银锭。我听说北边荒野里有很多矿石。要是我自己有时间去看看就好了。",
  },
  [28696] = {
    ["T"] = "给威廉明娜·晃轮的委托",
    ["O"] = "阿希拉上尉要你使用裁缝技能制作2件简易的黑裙子，并把订单交给艾萨拉晃荡谷的威廉明娜·晃轮。",
    ["D"] = "你是裁缝，对吧？很好。\n\n晃荡谷下面的侏儒在坠毁到这里时失去了一切。我们已经设法给了他们食物，他们也在搭建自己的庇护所，但除了身上的衣服，他们什么都没得穿。\n\n如果你能制作两件简易的黑裙子，就把它们带给威廉明娜·晃轮。这只是小小善意，但他们迫切需要。",
  },
  [26385] = {
    ["T"] = "战斗的召唤：费伍德森林",
    ["O"] = "在费伍德森林找到并杀死5名部落成员。",
    ["D"] = "费伍德森林属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26386] = {
    ["T"] = "战斗的召唤：费伍德森林",
    ["O"] = "在费伍德森林找到并杀死5名联盟成员。",
    ["D"] = "费伍德森林属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [27304] = {
    ["T"] = "遏制污染",
    ["O"] = "从费伍德森林碎痕谷的地狱火保镖身上取得一枚燃烧元素核心，并把它带给翡翠圣地的伊维·飘叶。",
    ["D"] = "$N，我有个主意。你需要找点东西引诱这只巨大的软泥怪离开湖泊，这样我们才能摧毁它。\n\n软泥怪诞生于恶魔腐化，并以它为食来变得更大。我怀疑如果你能取得一个强大的恶魔能量源，就可以用它把软泥怪从湖边引开。\n\n这是一项危险的任务。我唯一能想到能取得这种强大能量源的地方，就是在碎痕谷附近游荡的地狱火保镖核心。你不会想独自尝试的。\n\n祝你好运，愿艾露恩与你同在。",
  },
  [27305] = {
    ["T"] = "遏制污染",
    ["O"] = "把邪恶的软泥母体从血毒瀑布引出来并摧毁它。",
    ["D"] = "给你，$N，我已经把核心做成了可供你使用的诱饵。注意，一旦你激活它，软泥母体一定会直冲你而来！\n\n我敢打赌，一旦它被摧毁，我们就会看到血毒河中的腐化开始下降。以防万一，我会着手修理净化器——但如果你的努力成功，也许我们就不需要它了！",
  },
  [27306] = {
    ["T"] = "碧火谷的花园",
    ["O"] = "杀死碧火萨特和碧火魔仆，直到找回科雷克·望天的园艺工具，然后把它们带回费伍德森林翡翠圣地的他那里。",
    ["D"] = "军团到来之前，我把许多时间花在碧火谷，在那里创造了一座发光的花园。可悲的是，多年来为建造那片宁静圣地所付出的栽培与努力，如今什么都没剩下。\n\n如今占据我旧花园的碧火恶魔以囤积杂物出名，凡是落到他们肮脏手里的碎片都会被藏起来。我希望这意味着他们拿着我的工具，而我愿意付出任何代价把它们找回来。\n我不是战士，但如果你把我的工具带回来，我会给你丰厚的报酬——尤其是如果这意味着杀光那地方的每一个恶魔！",
  },
  [27307] = {
    ["T"] = "欺诈者神龛",
    ["O"] = "找回保存在欺诈者神龛中的萨格拉斯、提克迪奥斯、基尔加丹和阿克蒙德纪念物，并把它们带给费伍德森林翡翠圣地的守望者钢歌。",
    ["D"] = "向你致意，$C。我叫维拉·钢歌，是一名守望者。或者至少，我希望成为一名守望者。事实上我还在训练中。\n\n我被派到这里调查占据加德纳尔的恶魔势力。我已经确认，这些邪教徒收集了燃烧军团穿过费伍德森林时留下的纪念物，并把它们保存在加德纳尔内的欺诈者神龛中。\n\n从他们手中夺走这些纪念物，会移除一个象征他们效忠军团的强大标志。\n\n我不该直接与他们交战，也不想在第一次任务中违抗命令——但如果你能作为我的代理人取回这些遗物，我会非常感激。",
  },
  [27310] = {
    ["T"] = "通缉：卡拉拉什",
    ["O"] = "在铁木森林找到卡拉拉什，结束他的痛苦。",
    ["D"] = "$N，这片森林痛苦地提醒着我们第三次战争之后失去了什么。军团没有屠杀掉的野生生物，也被费伍德森林中的恶魔腐化逼疯了。\n\n伟大的奇美拉卡拉拉什和他的子嗣，是军团进攻时第一批保护费伍德森林的生灵。可悲的是，他的整窝后代都在对抗恶魔的战斗中倒下，只留下他孤身一人，被邪恶的邪能魔法污染。伟大奇美拉残存下来的东西如今在铁木森林游荡，满身大战留下的伤痕，也被悲痛折磨。 \n\n我不建议你独自踏入那些被诅咒的树林，但如果你遇到卡拉拉什本人……请结束他的痛苦。这就是我唯一的请求。",
  },
  [27311] = {
    ["T"] = "通缉：卡拉拉什",
    ["O"] = "进入铁木森林，杀死邪恶的奇美拉卡拉拉什。",
    ["D"] = "$C，你也许以为第三次战争后这片森林里的奇美拉已经被消灭殆尽，但仍有一只在铁木森林游荡。精灵们叫它“卡拉拉什”。 \n\n我和我的狩猎伙伴曾试图捕获它，却遭遇了一头被邪能逼疯的有翼恐怖，双口喷吐邪火和毒液。我勉强逃得性命，但我的伙伴……就没那么幸运了。 \n\n我不敢再和那头野兽纠缠，但任何能放倒它的人，我都会给予奖励。",
  },
  [27517] = {
    ["T"] = "风暴、大地、风与火",
    ["O"] = "削弱六个焦油元素，然后将大地之力吸收到雅卢尼·观焰的图腾中。",
    ["D"] = "我代表大地之环向你致意，$R。我正在研究原初元素，想知道你是否愿意协助我。\n\n我本想把安戈洛各类元素力量的精华都捕捉进这根图腾中，但在费伍德森林多年之后，我担心自己会以残留邪能污染它们。我需要有人替我收集这些精华。只要削弱元素，然后用图腾捕捉它们的原初精华。\n\n你可以从大地的原初力量开始——拉卡利油沼周围的焦油元素。",
  },
  [27521] = {
    ["T"] = "风暴、大地、风与火",
    ["O"] = "对一名石头守护者使用雅卢尼的元素强化图腾，然后击败它。",
    ["D"] = "安戈洛有一种比焦油领主更强的大地之力，而那正是吸引我来到这里的原因。\n\n伟大的石头守护者会沿着河流和环形山岩壁等孤独路线游荡。通常来说，它们会是强大的对手，对我们任何一人单独来说都过于强大。但我相信，我们收集到的原初力量可以把一个结实的敌人压到合适的尺寸。\n\n拿着这根图腾。它已经充满你收集到的所有元素力量。对一名石头守护者释放图腾的力量，并击败它。\n\n这些守护者目前是和平的，但如果它们有朝一日像费伍德森林的元素一样被腐化，我们必须准备好防御手段。",
  },
  [27610] = {
    ["T"] = "给艾瑞丹·蓝风的委托",
    ["O"] = "艾瑞丹·蓝风要你使用炼金术技能制作5瓶昏睡药水，并把订单交给费伍德森林翡翠圣地的艾瑞丹·蓝风。",
    ["D"] = "$C，过一段时间后，这片森林的污秽会渗进你的心智。我真正需要的是一两个不被打断的夜晚，好好睡上一觉。\n\n不过，哦……你是炼金师，对吧？也许你愿意替我制作一些昏睡药水？如果我不尽快睡个好觉，我担心自己会屈服于邪能疯狂的诱惑！",
  },
  [27634] = {
    ["T"] = "给特鲁尔·法贝恩的委托",
    ["O"] = "特鲁尔·法贝恩要你使用炼金术技能制作5瓶强效敏捷药剂，并把订单交给费伍德森林血毒岗哨的特鲁尔·法贝恩。",
    ["D"] = "啊，一位炼金师。我不懂那种特定门类的科学，但我尊重它。\n\n实际上，我能用得上一些强效敏捷药剂。弥漫在这片森林里的邪能魔法钻进我的骨头，让我浑身僵硬。那些药剂能让我的关节重新活动起来。你能帮忙吗？",
  },
  [27660] = {
    ["T"] = "给麦琳妮·霜月的委托",
    ["O"] = "麦琳妮·霜月要你使用锻造技能制作1顶秘银罩帽和1条秘银鳞片短裤，并把订单交给费伍德森林刺枝林地的麦琳妮·霜月。",
    ["D"] = "向你致意，$C。我感觉你也是一名老练的铁匠。费伍德森林的邪能蒸汽把我上一套护甲腐蚀穿了。我需要一条新的秘银鳞片短裤和一顶新的秘银罩帽。如果你能制作这些，我愿意用我的一些补给交换你的工作。",
  },
  [27685] = {
    ["T"] = "给德雷卡苏的委托",
    ["O"] = "德雷卡苏要你使用锻造技能制作1顶秘银罩帽和1条秘银鳞片短裤，并把订单交给费伍德森林血毒岗哨的德雷卡苏。",
    ["D"] = "铁匠？我能用得上你的才能。\n\n既然我已经得知丈夫的死讯，我受到鼓舞，要追随他的脚步，斩杀恶魔，努力让这片土地更安全。哪怕只完成他所做的一半，我也需要护甲。给我带来一顶秘银罩帽和一条秘银鳞片短裤，我会奖赏你。",
  },
  [28013] = {
    ["T"] = "奥术仪式",
    ["O"] = "从费伍德森林铁木森林的树人身上收集4份铁木树皮，并从诅咒之地邪石要塞的术士身上收集一枚暗影雕文，交给奥特兰克山脉拉文霍德庄园的菲莉希蒂。",
    ["D"] = "要安全驱散这种雕文，我们需要的不只是魔法材料。我们需要用代表雕文所调谐两极的魔法成分来校准它。\n\n这枚雕文被设计成让庄园看起来像自然的奥特兰克地貌，并抵御暗影议会的魔法。我们可以使用费伍德森林的铁木树皮作为大地成分——它被暗影议会的魔法触碰过，所以应该能与我们需要用来代表军团的暗影雕文更和谐地配合。我听说军团残余正在诅咒之地重建一座堡垒。你应该能从那里的术士身上取得一枚暗影雕文。",
  },
  [28028] = {
    ["T"] = "田野仪式",
    ["O"] = "与月光林地永夜港的德迪利特·星焰谈谈。",
    ["D"] = "哎呀，你的草药学技艺真的磨练得很不错了，对吧？像你这样有天赋的人可不常来。\n\n实际上，我想请你帮个忙。我在月光林地有个朋友，正在研究腐化对植物的影响。他已经厌倦了在费伍德森林和瘟疫之地之间来回奔波，可以用得上一名助手。如果你有兴趣，就前往永夜港，与德迪利特·星焰谈谈。\n\n如果你从没去过月光林地，嗯，你得穿过费伍德森林里木喉熊怪的领地才能抵达。熊怪对陌生人不怎么友善，但我相信你能想办法通过。",
  },
  [28037] = {
    ["T"] = "狩猎仪式",
    ["O"] = "为费伍德森林翡翠圣地的伊维·飘叶从冬泉谷的冬泉熊怪身上收集6件冬泉皮货。",
    ["D"] = "$N，我算是独特皮革制品的收藏者。尤其是那些对历史或我的人民有某种意义的物品。\n\n卡多雷曾经与冬泉谷的熊怪部族关系友好，但自战争以来，熊怪已经堕入腐化。他们不再制作那些曾经闻名的美丽皮革工艺品，而他们仍然拥有的许多作品也被糟蹋了。\n\n我想保存其中一些物品，希望有朝一日，当我们净化这片土地的腐化后，熊怪可以把它们作为重新学习的范例。作为一名有经验的制皮师，你会知道该找什么。你愿意为我取得半打吗？",
  },
  [28038] = {
    ["T"] = "狩猎仪式",
    ["O"] = "为费伍德森林翡翠圣地的伊维·飘叶从黑石塔上层的狂爪龙人身上收集4面龙皮鼓。",
    ["D"] = "曾经，在几千年前，黑龙军团的成员在与他们的首领奈萨里奥一同腐化之前，是建造者、工匠和编织者。我已经很久没有想起那些日子，以及随之而来的痛苦了。\n\n来自东部王国的报告显示，黑龙军团已经与黑石山附近旧部落的残余结盟。我想知道他们是否仍在实践他们的制皮工艺。如果是，我也想取得一些样本。你觉得自己能前往那里并替我打听吗？",
  },
  [28398] = {
    ["T"] = "给索罗斯·暗弦月的委托",
    ["O"] = "索罗斯·暗弦月要你使用附魔技能制作1根次级虚空魔杖，并把订单交给费伍德森林刺枝林地的索罗斯·暗弦月。",
    ["D"] = "丢了我的……魔杖……和恶魔战斗时。需要……替代品……等我恢复……我要找他们算账。",
  },
  [28422] = {
    ["T"] = "给奥索巴·狂怒图腾的委托",
    ["O"] = "奥索巴·狂怒图腾要你使用附魔技能制作1块魔化瑟银锭，并把订单交给费伍德森林血毒岗哨的奥索巴·狂怒图腾。",
    ["D"] = "等一下，附魔师。我们仍需要大量补给，才能让血毒岗哨运转起来。具体来说，我可以用一些魔化瑟银锭来继续打造武器。你能给我制作一块吗？当然会给你报酬。",
  },
  [28448] = {
    ["T"] = "给索罗斯·暗弦月的委托",
    ["O"] = "索罗斯·暗弦月要你使用工程学技能制作20枚高爆炸弹，并把订单交给费伍德森林刺枝林地的索罗斯·暗弦月。",
    ["D"] = "<索罗斯看起来虚弱，但神志清醒。>\n\n恶魔……把我害成这样。必须……复仇！需要……炸弹。高爆……炸弹。帮我……复仇！",
  },
  [28472] = {
    ["T"] = "给杰希尔·月弓的委托",
    ["O"] = "奥索巴·狂怒图腾要你使用工程学技能制作2个致命瞄准镜，并把订单交给费伍德森林翡翠圣地的杰希尔·月弓。",
    ["D"] = "哦！一位工程师！我到哪儿都认得出你指甲底下的油污！\n\n听着，你接活吗？我在翡翠圣地时，有个暗夜精灵想买几个致命瞄准镜。我凭良心没法卖给暗夜精灵，但她是塞纳里奥议会的一员。如果你对这份工作有兴趣，沿路往南就能找到她。",
  },
  [28537] = {
    ["T"] = "给塔诺恩·红羽的委托",
    ["O"] = "塔诺恩·红羽要你使用草药学技能采集20株格罗姆之血，并把订单交给费伍德森林翡翠圣地的塔诺恩·红羽。",
    ["D"] = "我能验证费伍德森林腐化程度的另一种方法，是观察一些本地植物。\n\n有一种名叫格罗姆之血的草药，据说只在军团和部落穿过这片森林之后才开始生长。我想要一捆来研究。",
  },
  [28606] = {
    ["T"] = "给塔诺恩·红羽的委托",
    ["O"] = "塔诺恩·红羽要你使用制皮技能制作1张熟化毛皮，并把订单交给费伍德森林翡翠圣地的塔诺恩·红羽。",
    ["D"] = "一位有才华的制皮师！那种皮革和深石之盐的气味，我到哪儿都认得出来。\n\n说起来……我需要你的技艺。这片树林里的邪能腐化已经开始在我帐篷的结构皮革上蚀出一个洞，我需要一张熟化毛皮来修补，否则整座帐篷都会塌到我们头上！\n\n如果你能提供那张皮，我会很感激。",
  },
  [28621] = {
    ["T"] = "给塔诺恩·红羽的委托",
    ["O"] = "塔诺恩·红羽要你使用剥皮技能采集5张厚毛皮，并把订单交给费伍德森林翡翠圣地的塔诺恩·红羽。",
    ["D"] = "我能验证腐化渗透森林有多深的另一种方法，是研究这里的野兽。它们已经扭曲了，但它们的皮革呢？腐化深入骨髓，但究竟有多深？\n\n我需要5张来自费伍德森林生物的厚毛皮。我想测试它们，研究污秽。如果皮肤记住了毒素，我们也许还能学会如何对抗它。",
  },
  [28654] = {
    ["T"] = "给科雷克·望天的委托",
    ["O"] = "科雷克·望天要你使用采矿技能采集20块瑟银矿石，并把订单交给费伍德森林翡翠圣地的科雷克·望天。",
    ["D"] = "即使我找回旧园艺工具，也不确定它们还能有多大用处。这里的腐化深入地下，照料这片土地也许需要由更坚硬材料制成的泥铲。\n\n如果你能给我带来20块瑟银矿石，我就能打造一些新工具。我听说瑟银坚韧无比。如果有什么材料能承受费伍德森林的腐化，那一定是它。",
  },
  [8905] = {
    ["T"] = "热心的建议",
    ["O"] = "将15份冬泉谷血样、20枚金币以及一副野性之心护腕交给铁炉堡的德莉亚娜。",
    ["D"] = "你好，$c。我这里有一些你可能会很感兴趣的东西。\n\n它跟你们这个职业的人平常穿着的那些护甲有点类似，但质量上远远好于你们现在所拥有的。要是你能帮我一个小忙的话，我愿意拿它来从你手里换一件普通的护腕。\n\n栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。给我带来足够的样本，还有那副护腕和一些金币。你会发现这其实是笔很划算的交易。",
  },
