    ["D"] = "嗨，$c！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。\n\n帮我一个小忙，我就愿意拿它来从你手里换一副普通护腕。\n\n栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。把样本和几枚金币带给我，我就完成这笔交换。",
  },
  [8920] = {
    ["T"] = "热心的建议",
    ["O"] = "将15份冬泉谷血样、20枚金币以及一副勇气护腕交给奥格瑞玛的莫克瓦尔。\n",
    ["D"] = "嗨，$c！从你的言行举止就能看出你是个历经沧桑、见多识广的家伙。但是我打赌你没有见过这么一件护甲。\n\n帮我一个小忙，我就愿意拿它来从你手里换一副普通护腕。\n\n栖息在冬泉谷的霜刃豹和熊身上的血液有着某种我目前很需要的特性。把样本和几枚金币带给我，我就完成这笔交换。",
  },
  [8928] = {
    ["T"] = "狡猾的商人",
    ["O"] = "在冬泉谷南部暗语峡谷入口的一处洞穴里寻找一个小鬼，购买一根恶魔元素之杖，然后返回加基森的穆克斯·玛纳斯卡波那里。",
    ["D"] = "那个核心可以提供足够的能量来驱动我们的装置；现在我们只需要制造一根不会熔化、还能引导能量的棒子。\n\n我曾在冬泉谷见过一个贩卖各类奇特货物的小鬼。他有一根元素之杖，应该正合适。我现在真想敲自己的脑袋，当初为什么没把它买下来。\n\n他住在暗语峡谷入口的一处洞穴里。潜进去，试着找到他。\n\n记住，只付四十金币，那是他当时报给我的价！",
  },
  [8963] = {
    ["T"] = "重要的材料",
    ["O"] = "取得星风村遗物，再回到黑石山找伯德雷。",
    ["D"] = "$C，仔细听好了。既然我们有了火盆和点燃它的方法，还需要另一个注入火盆的材料；某种足够强大的焦点，才能诱使我已故前战友的灵魂现身。\n\n伊萨利恩，我们的女祭司，成长于冬泉谷的星风村。我要你从冬泉谷南部霜语峡谷的霜槌巨人身上取得一件星风村遗物，那些巨人时常向北劫掠。",
  },
  [8985] = {
    ["T"] = "更多重要的材料",
    ["O"] = "取得星风村遗物，再回到黑石山找伯德雷。",
    ["D"] = "$C，仔细听好了。既然我们已经知道最后一块护符的位置，还需要另一个注入火盆的材料；某种足够强大的焦点，才能诱使我已故前战友的灵魂现身。\n\n伊萨利恩，我们的女祭司，成长于冬泉谷的星风村。我要你从冬泉谷南部霜语峡谷的霜槌巨人身上取得一件星风村遗物，那些巨人时常向北劫掠。",
  },
  [26272] = {
    ["T"] = "我们需要修理！",
    ["O"] = "把上层精灵工匠工具包送到永望镇的菲诺克那里。",
    ["D"] = "嗯……这个工具包真的很古老……我还不太放心直接使用。\n\n<艾莉诺一边挠着眉头，一边用出人意料的敏锐眼光检查工匠工具包。>\n\n哦，我知道了！我在永望镇认识一个地精，还借给过他一些补给。他是个工程师，欠我一个人情！你要去那边吗？介意顺路把这个交给他吗？告诉他是我让你来的，说我会很感激他帮忙修复它。",
  },
  [26273] = {
    ["T"] = "坠落的星辰",
    ["O"] = "坠星村的艾莉诺·月辉要你在冬泉谷周围收集10块坠星水晶。",
    ["D"] = "这太令人兴奋了，$N！我等不及要开始制作珠宝了。我相信菲诺克是个好工程师，但修复那么古老的遗物，对任何人来说都是挑战。\n\n与此同时，我们为什么不尽可能多收集些水晶呢？等一切结束后，我会给你做一件珠宝！这样公平吧？",
  },
  [26274] = {
    ["T"] = "菲诺克的巧手",
    ["O"] = "从永望镇的菲诺克那里取回修复好的工匠工具包，然后返回冬泉谷坠星村的艾莉诺·月辉那里。",
    ["D"] = "好了，$N。我本想和你一起去取工具包，但我不放心把这些珠宝单独留在这里……万一有人偷走了呢？\n\n很抱歉总是麻烦你。我保证会补偿你的！不，我不是懒！",
  },
  [26351] = {
    ["T"] = "又一个好消息",
    ["O"] = "在冬泉谷的暗语峡谷寻找奥丹姆石板所在地的线索。",
    ["D"] = "探险者协会解读出几段信息，显示奥丹姆石板被保存在某个烟雾经久不散的地方。此外，“峡谷”和“洞穴”这两个词似乎频繁出现。\n\n灼热峡谷看起来显然会被提到，但别忘了，这些圆盘是在拉格纳罗斯被召唤前很久制造的。那时灼热峡谷还不存在。\n\n但冬泉谷的暗语峡谷已经存在。\n\n我们希望你凭借你出众的本领，前往暗语峡谷搜寻任何奥丹姆石板的迹象。找到任何线索都回来报告。",
  },
  [26359] = {
    ["T"] = "又一个好消息",
    ["O"] = "在冬泉谷的暗语峡谷寻找奥丹姆石板所在地的线索。",
    ["D"] = "传承者解读出几段信息，显示奥丹姆石板被保存在某个烟雾经久不散的地方。此外，“峡谷”和“洞穴”这两个词似乎频繁出现。\n\n灼热峡谷看起来显然会被提到，但别忘了，这些圆盘是在拉格纳罗斯被召唤前很久制造的。那时灼热峡谷还不存在。\n\n但冬泉谷的暗语峡谷已经存在。\n\n我们希望你凭借你出众的本领，前往暗语峡谷搜寻任何奥丹姆石板的迹象。找到任何线索都回来报告。",
  },
  [26403] = {
    ["T"] = "战斗的召唤：冬泉谷",
    ["O"] = "在冬泉谷找到并杀死5名部落成员。",
    ["D"] = "冬泉谷属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26404] = {
    ["T"] = "战斗的召唤：冬泉谷",
    ["O"] = "在冬泉谷找到并杀死5名联盟成员。",
    ["D"] = "冬泉谷属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26515] = {
    ["T"] = "匹瑞诺德的遗产",
    ["O"] = "把哈斯将军的玺戒带到冰风岗附近的墓地，与艾登·匹瑞诺德一同埋葬。",
    ["D"] = "这么说，奥里登·匹瑞诺德死了，还希望哈斯将军知道？我想知道为什么。\n\n我就是你要找的人，$C。\n\n我和匹瑞诺德家族不欢而散，而那种感觉从未消失。我只想平静地度过余生。正如托尔贝恩曾经说过的，背叛永远不可饶恕。\n\n既然你似乎很喜欢替别人跑腿，我还有最后一件事要你做。拿着这枚玺戒，这是我对那段岁月最后的遗物，把它埋在奥特兰克边境那边冰风岗墓地里的艾登国王坟前。然后，我们再也不要谈起匹瑞诺德家族。",
  },
  [26952] = {
    ["T"] = "时间流分岔？",
    ["O"] = "把克罗米的时空置换器带到你在冬泉谷发现的异常点，并探测它，看看会出现什么。",
    ["D"] = "这些异常都出现在军团曾在艾泽拉斯保持强大存在的地区，这不可能只是巧合……还是说有可能？他们会在自己的力量之地留下改变时间流的证据，这感觉几乎太显而易见了。\n\n我还不能确定，$N。拿着这个时空置换器，像你探测安多哈尔的粮仓那样，去探测冬泉谷的异常点。看看会出现什么。这样我们就能知道真正的幕后黑手是谁，或者这件事是否确实与军团有关。",
  },
  [26954] = {
    ["T"] = "弓匠的请求",
    ["O"] = "取回玛瑞斯农场的游侠玛瑞斯笔记，并把它们带给冰风岗的玛瑞尔·杜邦。",
    ["D"] = "$C，谢谢你愿意和我说话。我只是个卑微的猎人，恳求你的帮助。著名游侠纳萨诺斯·玛瑞斯曾在如今的东瘟疫之地拥有一座家园。在天灾到来之前，他是我的英雄，我曾想去那里看看是否还留下了他的笔记。\n\n恐怕瘟疫之地的野兽对我来说太危险了。你愿意替我搜索他庄园的废墟吗？我想知道如何制作一把像他所持那样的弩。如果你找到任何他的笔记，请带给我。",
  },
  [27189] = {
    ["T"] = "冰凉的材料",
    ["O"] = "从冬泉谷的猫头鹰身上收集10根冰凉的猫头鹰羽毛。",
    ["D"] = "为了睡个好觉，你愿意付多少钱？不用回答——我知道它值很多金币。所以烟林牧场正在开发一种实验性枕头，采用最上等的清凉技术。\n\n我们的原型还需要更多羽毛，而且只有一种来源合适——冬泉谷的猫头鹰。它们的羽毛天生冰凉，即使你睡在黑石山旁边，也能带来舒适睡眠。你愿意接下这份工作吗？",
  },
  [27193] = {
    ["T"] = "冬泉谷上空的星辰",
    ["O"] = "使用奇妙枭兽获取神经仪，从冬泉谷的枭兽身上抽取5份星光精华。",
    ["D"] = "我希望你已经注意到，烟林牧场生产的商品总有那么一点额外的特别之处。那不是花招——我们做的每样东西里都注入了微量星光。\n\n我们的星光储备快用完了，不过我最近弄到一件新工具，可以从特别契合星光的生物身上汲取星光，比如冬泉谷的枭兽。只要削弱它们再抽取，轻轻松松。对这份工作有兴趣吗？",
  },
  [27545] = {
    ["T"] = "通往过去的门",
    ["O"] = "为观灵者尼谢尔从永望镇北边的野兽身上取得一根完好的熊股骨、一只完好的枭兽眼睛和一个完好的奇美拉毒囊。",
    ["D"] = "欢迎来到凯斯利尔湖，$N。你是否和我一样被这里吸引？我把每一个清醒的时刻都用来研究这些废墟。\n\n很久以前，甚至在大分裂撕裂大地之前，一场可怕的悲剧降临在这座神殿。悲剧的原因仍是谜团，但只要我们能与灵魂交谈，灵魂本身就能为我们揭开它。玛艾里的水晶是我设计的一场特殊仪式的关键材料，它应该能让我们召唤出一个可以交谈的灵魂。\n\n我需要你帮忙从本地野兽身上收集仪式所需的材料。给我带来一根熊股骨、一只枭兽眼睛和一个奇美拉毒囊。这些生物在永望镇北边都能找到——但记住，我们需要完好的部件，仪式才能奏效。",
  },
  [27548] = {
    ["T"] = "通往过去的门",
    ["O"] = "在冬泉谷东部找到灵语者安布兰斯，请他帮助翻译古代日记。",
    ["D"] = "唉，我完全看不懂这本日记。我担心它穿过帷幕时内容已经扭曲了。而且仪式水晶也受损了。真是一场灾难！不过附近有个人也许能帮我们。\n\n灵语者安布兰斯曾是尼谢尔的——也就是——我的导师。你可以在永望镇东北方他偏僻的小屋里找到他。把这本书和水晶带给他，问他能不能替我们翻译。我本想亲自去，但我们……闹翻了。我想如果由像你这样的中立第三方提出请求，会更好些。",
  },
  [27550] = {
    ["T"] = "通往过去的门",
    ["O"] = "返回冬泉谷东部的灵语者安布兰斯那里。",
    ["D"] = "安布兰斯说得对，辛玛洛水晶太危险了，不能再被找到和使用。许多日子里，我忍受着那个灵魂寄居在我体内，而这只是水晶可能造成的诸多祸害中最轻微的一种。\n\n拜托，$N，你愿意回到安布兰斯那里，告诉他我又是我自己了吗？我已经不在乎日记的翻译了。他想怎么处理那本书都可以。我会在有机会反思这段经历后尽快回到镇上。愿灵魂保佑你，$C。",
  },
  [27551] = {
    ["T"] = "一磅肉",
    ["O"] = "艾伦·霍桑要你从冬泉谷的熊怪身上收集4个皱缩的熊怪大脑、20块熊怪肉和15根大块熊怪骨。",
    ["D"] = "向你问好，$C。\n\n我需要一名屠夫……一个眼光挑剔、道德感又没那么强的人。感兴趣吗？\n\n这里的熊怪都是强壮的生物——可以说是一座座肌肉山。他们饮用一种“火酒”，我已经把那东西用于自己的用途，不过这不是重点。\n\n我有计划。一个艺术品的计划。我需要熊怪的大脑、血肉，还有骨头。",
  },
  [27552] = {
    ["T"] = "邪恶补给",
    ["O"] = "从永望镇的商人那里购买20个铅瓶、10块煤和5张空白羊皮纸，然后返回冬泉谷的艾伦·霍桑那里。",
    ["D"] = "现在该为眼前这些血肉绘制设计图了。这需要一些时间。\n\n我猜你正在四处旅行？如果你到了那个叫永望镇的罪恶蜂巢，顺便买些这些补给。你当然会得到丰厚报酬……！",
  },
  [27554] = {
    ["T"] = "承受痛苦者的痛苦",
    ["O"] = "从凯斯利尔湖的幽灵身上收集10份不安的灵质，然后返回冬泉谷的艾伦·霍桑那里。",
    ["D"] = "不，那绝对不是我原本的打算。至少你处理得……呃，很出色。\n\n嗯……苦难总爱找伴。我想我们的野兽醒来时也不会太高兴，而我看到东边那座湖边游荡着一些极其痛苦的幽灵。\n\n你为什么不去拜访一下那些幽魂呢，$C？一大堆他们的灵质就足够了。",
  },
  [27556] = {
    ["T"] = "被盗的书",
    ["O"] = "为冬泉谷的雷沃·霜翼从壁炉谷取回《冬泉霜刃豹训练论》。",
    ["D"] = "不久前，银色黎明派了一名信使去见灵语者安布兰斯，那是个隐居在山谷另一边的人类。那名银色使者离开前在冬泉谷转了一圈，似乎对霜刃豹训练的过程非常感兴趣。\n\n太感兴趣了。\n\n那个人是个小偷。他偷走了我尚未完成的著作《冬泉霜刃豹训练论》，然后消失了。我和安布兰斯谈过后得知，灵语者也遭遇了盗窃。我们认为那个小偷其实是血色十字军的一员，如今躲在他们的堡垒壁炉谷中。住在那里的血色魔导师据说是如饥似渴的文学学生——也许我的书就在他们的图书馆某处？",
  },
  [27558] = {
    ["T"] = "气泡生意",
    ["O"] = "与永望镇南边道路旁营地里的塔努姆谈谈。",
    ["D"] = "嘿，能人！找活干吗？我在炼金界做生意，酿造一流品质的饮料。\n\n至少，我本来是这么想的！我的搭档塔努姆已经失踪一个多星期了，我开始担心了。我需要我的货，而他是卡利姆多这边唯一一个我信得过、能做出那东西的化学师！我还花了大价钱把他弄到这里来！\n\n我忙疯了，所以你能不能去看看是什么拖住他了？从永望镇往南走，他就在主路旁再往下一点。他最好不是在干我想的那种事！",
  },
  [27561] = {
    ["T"] = "气泡",
    ["O"] = "塔努姆要你用冰风奇美拉的闪电吐息为电击瓶装回收装置充能8次。",
    ["D"] = "好吧，$C。我们有了手指，也有了安静，现在还需要气泡……你问气泡是啥？\n\n<塔努姆停顿了一下，用空洞的眼神看着你。>\n\n当然是闪电吐息！从那些奇美拉身上来……但只要会电你的那种！这是干活用的工具。\n\n<塔努姆递给你一个危险的装置，上面布满按钮、开关和灯。>\n\n要是觉得有点刺痛，别担心……哦，还有，尽量别死！",
  },
  [27562] = {
    ["T"] = "一件好……产品？",
    ["O"] = "把药水箱送到冬泉谷永望镇的罗克希·嘶哨那里。",
    ["D"] = "好吧，$N……呃……！\n\n<塔努姆大声叹气，伸手拿起各种颜色和质地的药水，然后全都扔进一个箱子里。>\n\n把这些拿给那个小爆竹！啊，她要毁了我！没、没时间管这个了……！\n\n<塔努姆的话开始含糊起来，他一边自言自语，一边用饥渴的眼神转向炼金台上刚酿好的药水。>",
  },
  [27563] = {
    ["T"] = "通用语言",
    ["O"] = "教训塔努姆一顿，然后返回冬泉谷永望镇的罗克希·嘶哨那里。",
    ["D"] = "<罗克希检查着凌乱的药水箱。听你讲完经过后，她脸上露出厌恶的神情。>\n\n不，不！不！！他又在偷喝产品了！还把这种垃圾寄给我……我甚至不想知道这些瓶子里装的是什么——我只知道这不是我的产品！\n\n那个蠢货运气好，酿得还算不错！哦……可要是老板知道了会怎么办！？\n\n够了，$N！给那个矮子一点教训！别杀了他，只要……稍微揍他一顿。告诉他“财阀向他问好”。这会让他清醒过来！",
  },
  [27565] = {
    ["T"] = "试剂之杖",
    ["O"] = "德莱文·霜凝要你从隐秘林地附近的树根中收集8份冰汁，从岩石中收集6块寒霜水晶，并从空中的猫头鹰身上收集5根血羽。",
    ["D"] = "我相信罗克希已经说明了我的目标？没有？\n\n某种东西正在搅动北边枭兽的心灵。原因很难解释，但我相信我们可以减轻它们的动荡。\n\n第一步是用本地试剂处理一根法杖，并为它附魔，增强效力。我本想自己去收集……只是担心回来时营地已经被毁。你愿意代我前往吗？\n\n附近树根里的冰汁可以作为封剂，使心智迟缓；岩石上的寒霜水晶在寒意中嗡鸣，可以安抚心智；最后，冬泉谷空中飞翔的睿智猫头鹰意志坚定，也许它们的血羽能把同样的品质赋予它们更大的亲族。请给它们一个有尊严的结局。\n\n如果你愿意收集这些材料，我会欠你一个人情。请多加小心，冬泉谷并不仁慈。",
  },
  [27567] = {
    ["T"] = "通往泰雷萨兰之路",
    ["O"] = "沿永望镇北边的道路前进，在过了坠星村后的岔路口右转，找到扎卡加在冬泉谷的雇主。",
    ["D"] = "你，过来。扎卡加的雇主需要一个强壮、有勇气的战士……扎卡加觉得你够格。\n\n从永望镇北边的路出发，过了坠星村后的岔路口向右转。她在那里等你。",
  },
  [27568] = {
    ["T"] = "石中之语",
    ["O"] = "莱琳女士要你搜索冬泉谷的泰雷萨兰，并收集8块奎尔多雷石板。",
    ["D"] = "我看你有备而来。想不想让口袋鼓起来，$C？\n\n我收集一切古代奎尔多雷的东西——是上层精灵，不是卡利姆多的那些流亡者——我正在北边的废墟里寻找某些东西。任何你能找到的文献我都需要，但你大概只会找到石板。\n\n不需要阅读。我们成交吗？",
  },
  [27569] = {
    ["T"] = "抄写员的工作",
    ["O"] = "把奎尔多雷石板带给冬泉谷永望镇旅店里的马里乌斯·赫德林。",
    ["D"] = "我的护卫们正在永望镇闲逛。他们两个不像我这样热情，不过他们来这里也不是为了这个。\n\n找到抄写员马里乌斯·赫德林。让他把这块石板上的这部分内容蚀刻到一张法术卷轴上。\n\n<莱琳女士用手指框住石板文字的一段。>\n\n告诉他卷轴必须足够强力——只有他最强的手艺才够用。",
  },
  [27570] = {
    ["T"] = "幻象之钥",
    ["O"] = "冬泉谷永望镇的马里乌斯·赫德林需要7份幻影之尘来制作奎尔多雷法术卷轴。幻影之尘是附魔专业的产物。",
    ["D"] = "哇，多漂亮的书法！我看不懂，但我猜那位女士想要抄录？\n\n法术卷轴？嗯，最强大的卷轴要用幻影之尘作墨水……啊，可我上周就用完了！\n\n呃……你能提供试剂吗？幻影之尘归附魔师管，如果别处找不到，也许可以在永望镇观测台的拍卖行买到。",
  },
  [27574] = {
    ["T"] = "迷失的灵魂",
    ["O"] = "伊斯米尔·晨落要你让冬泉谷泰雷萨兰的任意20名幽灵居民安息。",
    ["D"] = "你愿意和我说话？已经过去多久了……？大多数旅人都不理我……要么就是转身逃跑。\n\n<伊斯米尔停顿了一下，仿佛预料你会离开；他锐利的眼中透出深深的悲伤。>\n\n我失败了，$C……泰雷萨兰是我父亲的祖居，我多年前来到这里，是为了让他受苦的族人安息。我生前是一名游侠，对自己的能力充满信心。可结果，如你所见……！\n\n<伊斯米尔挥动虚幻的手穿过胸口，身体的幽灵光晕随之扭曲。>\n\n你看起来像是正要前往废墟。我没有什么能给你，但请把你的善意借给这地方的灵魂。解除他们的痛苦。可悲的是，他们甚至没有意识到自己如今的状态。",
  },
  [27576] = {
    ["T"] = "玛沃尔的指引",
    ["O"] = "根语者阿哈鲁要你把梦魇种子袋送给月光林地的玛沃尔。",
    ["D"] = "你把这些带给我是明智的，$N。现在我感觉到了，树根和魔法盘绕进大地；砍倒它并不能阻止它扩散。\n\n我的魔法可以照料伤口、培育植物……但这种事远远超出我一个人的能力。不过我知道有个人处理过类似的情况。\n\n$N，请去找月光林地的玛沃尔，他是一位博学的草药师。他住在永夜港西南区，靠近飞行管理员。\n\n把种子送去，并说明我们的困境，他会知道该怎么做。我会留在冬泉谷，并咨询我的一位同僚。",
  },
  [27578] = {
    ["T"] = "返回阿哈鲁处",
    ["O"] = "把梦境种子瓶送给冬泉谷泰雷萨兰附近的根语者阿哈鲁。",
    ["D"] = "好了。看见种子已经不再蠕动了吗？假以时日，它们一定会成为积极变化的媒介。\n\n月亮井水赋予了强大的反制魔法。如果把这些种子种在被诅咒的树附近，它的生长和恶性也许就能被遏制。\n\n我保留了一些种子供进一步研究，也会把这些进展告知议会。赶快去找阿哈鲁吧；他会补偿你的开销。谢谢你，$C。",
  },
  [27579] = {
    ["T"] = "种下梦境",
    ["O"] = "在冬泉谷泰雷萨兰内的5处梦魇生长物附近种下梦境种子。",
    ["D"] = "玛沃尔救了我们！很遗憾我们不能立刻终结这棵邪恶之树，但任何能减轻其影响的行动都是胜利。我的同僚德莱文怀疑野生动物正在受到扰动，所以时间紧迫！\n\n让我们希望这能奏效。种下种子的荣誉属于你，$N。完成后回来找我。",
  },
  [27580] = {
    ["T"] = "邪角之影",
    ["O"] = "根语者阿哈鲁要你杀死北边泰雷萨兰内的15名邪角萨特。",
    ["D"] = "向你致意，$C，虽然我希望我们是在更好的情况下相遇。\n\n即使身在月光林地，我也感觉到冬泉谷出了问题。我与树木沟通，它们向我展示了大地上一处受污染的伤口，正在越长越大、越发凶残——被恶毒魔法诱导成形。\n\n<根语者阿哈鲁沮丧地摇了摇头。>\n\n你闻到空气中的恶臭了吗？硫磺烟气顺风飘到这么远，只能说明一件事：萨特。循着他们的气味向北，除掉他们——终结他们的黑暗行径！",
  },
  [27581] = {
    ["T"] = "雪樱小食",
    ["O"] = "为冬泉谷的雷沃·霜翼收集12颗雪樱。",
    ["D"] = "训练冬泉霜刃豹是一件很费时间的事，$N。我有时甚至顾不上吃东西，尽管我最喜欢的小食在我们周围到处都长着。\n\n也许你愿意帮我一个忙？雪樱遍布冬泉谷，常常生长在点缀大地的大树和岩石庇护之处。趁我继续训练时，替我采几把回来，我会非常感激。",
  },
  [27582] = {
    ["T"] = "柔韧的蝙蝠皮",
    ["O"] = "为冬泉谷的雷沃·霜翼从东瘟疫之地的瘟疫蝙蝠身上收集10张柔韧的蝙蝠皮。",
    ["D"] = "骑乘冬泉霜刃豹的一个必要部件，是合适的鞍具。虽然冬泉谷并不缺皮革，但我发现有一个更异域的地方，是这种装置最好的皮革来源。\n\n横渡海洋前往东瘟疫之地，猎杀那里的瘟疫蝙蝠。蝙蝠皮既坚韧又细腻，不像有些皮革那样磨人。收集十张柔韧的蝙蝠皮，用来制作鞍具，然后带回冬泉谷给我。",
  },
  [27583] = {
    ["T"] = "麦索瑞尔的幼龙",
    ["O"] = "前往冬泉谷的麦索瑞尔，杀死12只深蓝雏龙。",
    ["D"] = "霜刃豹是危险的掠食者，但它也会成为某种特定强大生物的猎物——栖息在麦索瑞尔的蓝龙。\n\n成年霜刃豹可以在战斗中与较弱的龙类周旋，但那些邪恶的生物有时会捕捉幼崽，喂给它们自己的幼龙。这就是生命的循环。然而，我最近注意到这片区域的雏龙数量有所增长。如果数量太多，我担心会对霜刃豹种群造成影响。必须采取行动！\n\n我请你去削减一些盘踞麦索瑞尔的蓝龙雏龙。虽然它们个体并不强大，但可能受到成年守卫保护。我建议你组建一支队伍，以确保自身安全。",
  },
  [27585] = {
    ["T"] = "冬泉谷鞍具",
    ["O"] = "前往藏宝海湾，从崔斯里克那里取回冬泉霜刃豹鞍具货物，然后带回冬泉谷的雷沃·霜翼那里。",
    ["D"] = "我委托剥你的皮制皮店的崔斯里克为我训练的冬泉霜刃豹制作鞍具。下一件现在应该可以领取了。你能跑一趟把它取回来吗？那家店在藏宝海湾的上层。\n\n有一件事，$N——我不记得自己是否已经付过鞍具的钱了。如果还没付，你愿意替我先付款吗？等你回来时我会报销。",
  },
  [27608] = {
    ["T"] = "给化学家阿尔比顿的委托",
    ["O"] = "化学家阿尔比顿要你使用炼金术技能制作5瓶侦测亡灵药剂，并把订单交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    ["D"] = "啊，一位炼金师同道。我大部分时间都在这里研究天灾瘟疫的影响，如果我能分辨哪些区域有亡灵游荡、哪些没有，效率就会高得多。唉，我似乎把侦测亡灵药剂的配方笔记弄丢了。如果你愿意替我调制五瓶药剂，除了酬金之外，我还乐意给你一些研究补给。",
  },
  [27658] = {
    ["T"] = "给指挥官阿什拉姆·瓦罗菲斯特的委托",
    ["O"] = "指挥官阿什拉姆·瓦罗菲斯特要你使用锻造技能制作2把巨型黑色锤，并把订单交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",
    ["D"] = "啊，一位铁匠。我需要你的技艺。\n\n虽然天灾已经被击退，但我们需要新武器来继续战斗。我听说有一种巨型黑色锤，对付亡灵很有效。如果你能制作一对带来让我试试，我们就能看看传言是否属实。",
  },
  [27934] = {
    ["T"] = "保持冰爽",
    ["O"] = "在冬泉谷北部收集5块寒霜水晶。",
    ["D"] = "你去过另一个大陆上的冬泉谷吗，$N？那里的寒冷和卡兹莫丹不一样，我跟你说……\n\n越往北走，就越冷。寒霜水晶会从冬泉谷北部的岩石上冒出来，我在想，那么冷的东西放进我们的饮料里会怎样，嗯？\n\n我的想法是：冰饮能帮你放慢流血速度，而最冰的饮料能让流血完全停止！不管怎么说，光是去一趟那里，就能提升你自己的冰霜抗性。\n\n怎么样，$N？把那些水晶带回来，我们做完气泡饮料时就把它们放进去。",
  },
  [27963] = {
    ["T"] = "狂暴入门",
    ["O"] = "收集巫毒材料，并把它们带给碎矛节庆上的巫医哈尔德。",
    ["D"] = "啊，孩子，我看你也是布鲁比赛的受害者之一。哈尔德能给你击败布鲁所需的优势——那小子该被从枝头上打下来一截又一截了。\n\n布鲁夺冠的秘密，是他与驱动所有英雄的内在怒火有着深厚联系。巨魔从出生起就学习这种联系，但即使像你这样的外人，只要练习得当，也能触及它。\n\n为了让你更容易掌握，我需要你收集几样东西——一瓶来自丛林巨魔的魔精，一些来自冬泉谷熊的牙齿，用来代表冰霜巨魔，还有我们森林巨魔敌人的骨头。东瘟疫之地废墟里的烂苔巨魔就可以。\n\n你可以和乌娜·吉罗以及你主城里的使者交谈，在你的家乡和我们这里之间往返。",
  },
  [27998] = {
    ["T"] = "铸炉仪式",
    ["O"] = "从东瘟疫之地或冬泉谷的女妖身上收集6份幽灵等离子体，并把它们带给荆棘谷藏宝海湾的麦加文。",
    ["D"] = "我对我们需要的这种幽灵等离子体一无所知，但只要拿到手，我就知道该怎么把它注入金属里。所以，我来准备熔炉，你去弄等离子体。\n\n布莱恩的笔记显示，女妖幽灵可能最合适。我想冬泉谷那些古老的暗夜精灵废墟里应该有女妖。或者东瘟疫之地也有，那里曾经住着高等精灵？我不在乎你从哪里弄来，只要弄到就行！",
  },
  [28051] = {
    ["T"] = "荒野仪式",
    ["O"] = "赫米特·奈辛瓦里要你使用剥皮技能，从冬泉谷的霜刃豹身上收集6张超厚霜刃豹皮，并把它们带到他位于荆棘谷的营地。",
    ["D"] = "我有个客户在购买几样高级野兽制品时希望保持匿名。我猜是担心身份公开后引来竞争。\n\n他们要求我收集的第一样东西，是冬泉谷的高级霜刃豹皮。不是随便什么皮都行。买家只要最厚、最暖和的货。你觉得自己能应付这个吗？这是最简单的一项。",
  },
  [28446] = {
    ["T"] = "给阿特伍德医生的委托",
    ["O"] = "玛瑞尔·杜蒙要你使用工程学技能制作5个不牢固的扳机，并把订单交给西瘟疫之地凯尔达隆的阿特伍德医生。",
    ["D"] = "你是工程师吗？抱歉……你只是看起来有点像。我哥哥是工程师。\n\n总之，我只是想告诉你，一个叫阿特伍德医生的人不久前到过冰风岗，想找一些不牢固的扳机。银色黎明的人有点把他赶走了……不太确定为什么。不过他说，如果有工程师路过，他就在凯尔达隆。要是你敢穿过亡灵到那儿去，也许是个赚点钱的好机会！",
  },
  [28624] = {
    ["T"] = "给扎卡加的委托",
    ["O"] = "扎卡加要你使用剥皮技能采集5张战熊皮，并把订单交给冬泉谷永望镇的扎卡加。",
    ["D"] = "这里太冷了，朋友。扎卡加想念丛林，想念温暖。不过，扎卡加听说有种东西能帮忙。\n\n这里的熊皮很结实，为了过冬格外厚。带5张战熊皮来，这样只要扎卡加的雇主需要，我就能忍受这里的寒冷。",
  },
  [28646] = {
    ["T"] = "给阿莱克希亚·铁刀的委托",
    ["O"] = "阿莱克希亚·铁刀要你使用采矿技能采集10块真银矿石，并把订单交给西瘟疫之地冰风岗的阿莱克希亚·铁刀。",
    ["D"] = "你有没有注意到，真银靠近亡灵时会产生奇怪的共鸣？我有个理论，它也许会对亡灵能量产生反应，但我需要样本来测试。\n\n我不是矿工……但你是！你愿意带给我10块真银矿石吗？如果我是对的，我们也许就找到了一种既优雅又有效的武器。",
  },
  [28656] = {
    ["T"] = "给维尔的委托",
    ["O"] = "维尔要你使用采矿技能采集20块厚重的石头，并把订单交给冬泉谷暗语峡谷的维尔。",
    ["D"] = "我很少向凡人索取东西，也不会解释。但我有自己的需要，而你可以协助。\n\n带给我20块厚重的石头。把问题留在峡谷门外，之后也许会有答案。",
  },
  [28695] = {
    ["T"] = "给高阶牧师玛多妮尔的委托",
    ["O"] = "高阶牧师玛多妮尔要你使用裁缝技能制作1件暗纹护肩，并把订单交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",
    ["D"] = "自从驻守冰风岗以来，我亲眼看见暗影如何移动，又如何低语。它可以毁灭，没错……但也能保护。而且它会聆听，以圣光从未有过的方式。\n\n我必须更深入地理解它。如果你能制作一件暗纹护肩，就把它带到冰风岗给我。我相信它们也许不仅仅是衣物——它们可能是通往长久被拒绝的力量之钥。",
  },
  [31001] = {
    ["T"] = "向阵亡者致敬",
    ["O"] = "奥格瑞玛的督军伦萨克要你向一名在东部冬泉谷阵亡的部落老兵致敬。",
    ["D"] = "",
  },
  [31006] = {
    ["T"] = "觐见酋长",
    ["O"] = "与奥格瑞玛的萨尔谈谈冬泉谷传来的不安报告。",
    ["D"] = "向你致意，冒险者。我最近获准觐见酋长。你与瓦萨拉克领主作战的英雄事迹给他留下了深刻印象。\n\n有人告诉我，部落此时可以用得上像你这样有能力的人。冬泉谷发生了奇怪的事。去吧，和酋长谈谈，别让他等。",
  },
  [31008] = {
    ["T"] = "不安的报告",
    ["O"] = "聆听酋长的命令。",
    ["D"] = "你会响应酋长的召唤吗？坐下，听着。\n\n<一名卫兵给你带来一叠报告。>\n\n灵魂不得安宁，$N，冬泉谷的冻土上正发生着邪恶之事。部落法师感觉到它东部传来巨大的奥术扰动，我们的斥候还报告说出现了尖石食人魔，他们从未在黑石山之外现身过。\n\n各方都如此骚动，我担心一定发生了严重的事。冒险者，我能指望你去调查吗？",
  },
  [31010] = {
    ["T"] = "冬境跋涉",
    ["O"] = "调查东部冬泉谷的部落斥候报告。",
    ["D"] = "<你得到一叠斥候报告。通读之后，似乎食人魔活动和奥术异常都出现在冬泉谷东部。你看到其中提到一条狭窄的山口和巨大的龙骸。最好前往那里，看看能发现什么。>",
  },
  [31011] = {
    ["T"] = "冬境跋涉",
    ["O"] = "调查东部冬泉谷的联盟斥候报告。",
    ["D"] = "",
  },
  [31014] = {
    ["T"] = "可怕的指引",
    ["O"] = "寻求蓝龙军团的建议。麦索瑞尔洞穴是他们在卡利姆多的家园。守卫肯定会见入侵者就攻击，但也许他们隐居的守护者族母愿意帮助我们？",
    ["D"] = "我知道那条龙属于蓝龙军团。只要触摸那些骨头，你就能确定。我不懂魔法，也怀疑你没有压制这场疫害所需的力量，$c。\n\n<塔尔鲁克思索片刻。>\n\n冬泉谷有一处蓝龙军团巢穴。他们很可能会见面就攻击，但也许，只是也许，那里有人可以交谈？一位领袖，一位守护者？这不确定，但值得一试。",
  },
  [31015] = {
    ["T"] = "必要的黑暗代价",
    ["O"] = "麦索瑞尔的哈尔琳要你杀死通灵学院的维克图斯，并夺回他的权杖。",
    ["D"] = "我怎么会漏掉这个？我怎么会感觉不到？我的同族，就在离我这么近的地方安息……还有那块水晶？\n\n我没有答案给你，$r。而且我不能离开麦索瑞尔的职责，但必须有人采取行动。\n\n<她朝安息地深深凝望了许久。>\n\n你也能感觉到，对吗？它正在成长，正在进食。那些愚蠢的食人魔究竟做了什么……你来找我是对的，如果这股魔法源头不被遏制，我无法想象会发生什么。\n\n我们需要答案，而且要快。前往位于西瘟疫之地的通灵学院。那里有个邪恶的死灵法师，正在试验制造染疫巨龙。给他最残酷的死亡，把他的权杖带给我。",
  },
  [31019] = {
    ["T"] = "回程",
    ["O"] = "权杖已经净化，我们可以返回冬泉谷。蔚蓝安息地的塔尔鲁克会等着我们。",
    ["D"] = "<玛克斯韦尔·泰罗索斯男爵明显喘不过气来。>\n\n仪式比我预想的更耗费力量。\n\n我尽力了……但我不知道你的计划能否成功。返回蔚蓝安息地的龙骸处。如果你现在把权杖的力量导入它们的头骨，就应该能引出那条龙的灵魂，让你们交谈。\n\n再会，$c，祝你好运。等一切结束后摧毁那根权杖。这种魔法不该被允许存在。",
  },
  [31027] = {
    ["T"] = "奥术疫害",
    ["O"] = "开始净化冬泉谷的蔚蓝安息地。把四枚抑制结界分别放在受奥术疫害影响的每片土地上。",
    ["D"] = "结界已经准备好了。把它们放在受影响土地的中央附近。\n\n小心那些食人魔，他们似乎仍在追着我们。"
  },
  [31029] = {
    ["T"] = "奥术疫害",
    ["O"] = "与维利戈斯交谈，摧毁维克图斯的权杖并释放他的灵魂。之后，我们应该把发生的一切告诉塔尔鲁克。他可以在冬泉谷的蔚蓝安息地找到。",
    ["D"] = "随着水晶平静下来，我赖以维持自身的能量正在减少。\n\n$N，很抱歉，我许多年前辜负了所有人。我的好奇心几乎带来无数死亡。请把这件纪念物带给我的族群，让他们知道我的故事，让他们警示年轻一代。\n\n剩下的，就是折断那个死灵法师的权杖。\n\n<维利戈斯短暂地悬浮在上方，久久望向下方的海洋。>\n\n我的职责已经完成，是时候离开了。我准备好了。"
  },
  [31030] = {
    ["T"] = "奥术疫害",
    ["O"] = "把维利戈斯的纪念物带给守护者族母哈尔琳。她可以在冬泉谷麦索瑞尔上方找到。",
    ["D"] = "你做得很好，$N。你应该尊重那条龙的请求，把他的纪念物带给麦索瑞尔的族母。这是个悲剧故事，必须被知晓。\n\n每当你感到迷失，就回到这个地方。它曾是巨大悲伤的源头，但终有一天，宁静会回到这里。\n\n再会，$r。"
