  [27329] = {
    ["T"] = "牙齿记录",
    ["O"] = "从双塔山附近格鲁克营地北边的格罗多克雷鸣者身上收集牙齿。",
    ["D"] = "俺、杰拉尔和特罗格，很久以前一起去打猎。俺们找到大坏格罗多克。它们有大牙，很坏的大牙。俺们跑得飞快，但杰拉尔记得那些牙。现在俺觉得那些牙就是害死特罗格的东西。俺需要你去从格罗多克那里取回那些牙。你带回来，俺们给特罗格看，也许他会想起来。",
  },
  [27332] = {
