    ["O"] = "向双塔山的格罗多克雷鸣者投掷泰拉比姆香蕉，以找到特罗格的尸体。",
    ["D"] = "俺们之前为了牙齿杀了格罗多克……俺希望这些香蕉能让它们的心变甜，也许它们会带俺们去平常存放食物的地方。去试试！",
