  [26357] = {
    ["T"] = "坏消息",
    ["O"] = "把海德里格的加密信件带给雷霆崖的圣者图希克。",
    ["D"] = "<奈莉努力让自己平静下来时，你描述了在泥地里看到的脚印。>\n\n我希望能帮上你，但那种奇怪的鞋底纹路我并不熟悉。不过有一样东西，$R。\n\n我老爹告诉我，如果他真出了什么事，就把这封信交给你。我希望它能帮上你找我老爹要办的事。\n\n请原谅我这么说，我再也不想见到另一个$R了。",
