    ["O"] = "与雷霆崖灵魂高地上的圣者纳莎谈谈。",
    ["D"] = "我会继续解读海德里格的信件，但你离开期间，其他几位传承者认为他们在破译奥丹姆石板所在地方面取得了突破。\n\n如果你想了解更多，就去灵魂高地找圣者纳莎谈谈。",
  },
  [26360] = {
    ["T"] = "又一个坏消息",
    ["O"] = "带着唤地者的讯息返回雷霆崖的圣者纳莎那里。",
    ["D"] = "我知道你在寻找什么，也见过你追寻它时展现出的勇气。请放心，我不是轻率地说这些话，因为我见过凡人为了追求知识会牺牲多少。\n\n警告你：你还没有准备好面对奥丹姆石板。你还没有准备好面对那些门后等待的东西。连泰坦都没有准备好面对他们发现的事物，因此石板和圆盘才被分开，散落四方。\n\n如果你继续沿着这条线索追查，将会释放难以言说的灾祸。现在走吧，$R。这个任务已经结束了。我敦促你另寻新的道路。",
  },
  [26429] = {
    ["T"] = "重在牺牲",
    ["O"] = "前往雷霆崖，在元素高地从穆恩·地怒那里取得一根灵魂图腾。这需要捐献150枚金币。",
    ["D"] = "我知道你在寻找什么，$C $N，我会尽力帮助你。这件事不能用传统方式完成，因此我们必须寻求一位非传统盟友的协助。\n\n为了让你为这项任务做好准备，你必须先做出牺牲。\n\n接下来我们需要一根灵魂图腾。即使它的用途是善良而正义的，让一名萨满交出它也必须给予应有补偿。\n\n前往雷霆崖，到城市西侧的元素高地与穆恩·地怒谈谈。带上足够的钱币，以弥补失去图腾的代价，这会显示你愿意为了追求正义牺牲世俗财富。",
  },
  [26443] = {
    ["T"] = "神圣卷轴",
    ["O"] = "与雷霆崖的希西卡·地角谈谈。",
    ["D"] = "向你致意，$Gbrother:sister;。希西卡·地角是我们最有影响力的烈日行者之一，她最近谈起过你。我听见她说，是时候让你接受一些考验了……还说了不少称赞你至今表现的话。\n\n如果我是你，有空时就会前往雷霆崖找她谈谈。我肯定她在灵魂高地——她大部分时间都在那里。",
  },
  [26445] = {
    ["T"] = "神圣卷轴",
    ["O"] = "与雷霆崖的希西卡·地角谈谈。",
    ["D"] = "在一切行动中，烈日行者都必须映照出补充我们力量的温暖。对我们族人而言，追求神圣并不意味着追求神格——我们追求的是在一切行动中行善。\n\n虽然你会被召唤去从这艰难时代中惩击黑暗，但你必须永远记住，真正让你有别于艾泽拉斯众生的，是帮助他人。怜悯、耐心、勇气——这些对烈日行者来说，与战斗中的力量同等重要。\n\n牢牢记住这一点，永远不要忘记。",
  },
  [26446] = {
    ["T"] = "神圣卷轴",
    ["O"] = "在雷霆崖主高地寻找特娅·迅图腾。",
    ["D"] = "那么你的任务，$n，就是在雷霆崖找到一位需要帮助的人。一个心灵和动机都纯洁的人。也许是正在帮助别人的人。也许是需要指引的人。无论如何，这个人必须怀有高尚意图，并依靠你的善意。\n\n完成这件事，然后回来找我。之后，我们会进一步讨论你的道路，以及行走于太阳之下意味着什么。",
  },
  [26447] = {
    ["T"] = "神圣卷轴",
    ["O"] = "把10块亚麻布带给雷霆崖的特娅·迅图腾。",
    ["D"] = "愿那些小心灵受到祝福，他们大多因为半人马的袭击，以及我们的族人在部落各地分散开来而失去了家人。\n\n我平常还能设法找到布料和皮革来制作东西，但现在越来越困难了，而我满脑子只想着让他们保暖、安全，并有个遮风避雨的屋顶。\n\n如果你能给我带些亚麻布，好让我给孩子们缝衣服，那会帮我很大的忙。",
  },
  [26448] = {
    ["T"] = "神圣卷轴",
    ["O"] = "与雷霆崖的希西卡·地角谈谈。",
    ["D"] = "我会确保孩子们在今天结束前拿到这些。请注意安全，善良的$c。像你这样品格的$men:women;并不常出现在城里，但你已经证明，在雷霆崖追随太阳的人，永远不会把他人带入黑暗。\n\n再会。",
  },
  [26452] = {
