  [27316] = {
    ["T"] = "伸张正义",
    ["O"] = "把奥多的玺戒带给雷霆崖的大德鲁伊哈缪尔·符文图腾。",
    ["D"] = "在这片荒野里，卢尤娅和我没有多少东西能回报你的帮助，但我们不希望你觉得自己不受感激。拿着我的玺戒。如果你有一天来到雷霆崖的峰顶，就去长者高地。在那里你会找到大德鲁伊哈缪尔·符文图腾。这枚戒指会让他知道我们平安无事，也会证明你的故事。\n\n我们两人都感谢你，$N。",
