    ["D"] = "我想你目前已经尽力帮助我了。等我恢复之后，就能自己继续这项工作。\n\n请再帮我最后一个忙。把核心样本、石板拓片和我的报告带回雷霆崖交给哈缪尔·符文图腾。他曾表示有兴趣知道这个传说是否属实，而既然是一位部落成员帮助了我，这是我至少该做的事。",
