    ["D"] = "$N，阿波尼·亮鬃向你提出了一项请求。\n\n她代表雷霆崖的长者德鲁伊请求援助。关于此事，我没有太多可说的，但其中提到了暗夜精灵等事情。\n\n我要转告你，你的谨慎至关重要。去雷霆崖的长者高地找她吧。",
