  [27925] = {
    ["T"] = "返回阿波尼处",
    ["O"] = "带着你的发现返回雷霆崖长者高地的阿波尼·亮鬃那里。",
    ["D"] = "<那名暗夜精灵缓缓眨眼，努力弄清周围情况。他的目光四处游移，却总是回到你身上。>\n\n我们……我们是受邀来到这里的——与牛头人一起研究这座泉水。起初我们有所迟疑……但既然我们同样遵循塞纳留斯的教诲，便怀着强烈好奇前来。看到这样一根橄榄枝浸透鲜血，令人悲伤，虽然并不意外。\n\n我的话分量不大，但并不存在针对你们部落的阴谋。我不会干涉你们的政治；我只希望返回北方。\n\n<他短暂地瞥了一眼你的武器，然后闭上眼睛片刻。>\n\n感谢你饶我一命。愿我们和平分别？",
  },
  [27926] = {
    ["T"] = "月之恩典",
    ["O"] = "与雷霆崖的勇士赛克谈谈。",
    ["D"] = "<那名精灵端详着你的脸，轻轻清了清喉咙。>\n\n那泉水。你……你被赐予了一份礼物，$R……！\n\n<精灵停顿下来，神情既不安又困惑。>\n\n……而你并不是第一个收到它的人。另一个人在这座泉水中被治愈，是一名牛头人，包裹在同样的光环中。我们逐渐把它称为女神的眷顾……作为追随她意志的人，我们把自己的教诲传授给了那名牛头人。\n\n毫无疑问，这是一条艰难的掌握之路。然而，女神对你似乎怀有某种信任。我不能再作进一步解读。\n\n去雷霆崖找勇士赛克，也许你会学会驾驭它。",
  },
  [26755] = {
    ["T"] = "太阳之水",
    ["O"] = "从安戈洛环形山葛拉卡温泉的活水和飞溅元素身上收集8颗纯净泉水珠，然后返回东瘟疫之地奎尔林斯小屋的塞莱斯特·科瑞莉丝那里。",
    ["D"] = "你在找日触特酿？口味可真昂贵！这年头那可是很难弄到的饮料。\n\n幸运的是，我这里正好有几瓶日触特酿正在发酵，但我已经用完了一种制造更多特酿所需的关键材料。帮我把材料取来，一瓶酒就是你的！\n\n我需要纯净泉水，就像曾经流经永歌森林的那种。既然永歌森林已经被天灾摧毁，你就得去别处寻找另一个来源。也许某个原始之地，有温泉的地方？至于那在哪里，就交给你自己琢磨了。",
  },
  [27468] = {
    ["T"] = "火焰箭头",
    ["O"] = "使用梅尔乔·血奔提供的物品，从安戈洛环形山的焦油兽身上虹吸焦油。焦油兽必须处于虚弱状态。",
    ["D"] = "既然我们已经有了毒刺，就必须专注于让火焰箭尽可能强大。我设计了一种特殊容器，可以直接从焦油兽核心吸收焦油，但必须让它们虚弱且活着。这是个痛苦的过程，但有时科学需要牺牲。你可以在附近安戈洛环形山的拉卡利油沼找到焦油兽。",
  },
  [27506] = {
    ["T"] = "饥肠辘辘的幼崽",
    ["O"] = "从安戈洛环形山恐惧小道附近的剑龙身上收集10块新鲜恐龙肉。",
    ["D"] = "虽然我会为照料中的暴掠龙幼崽维持均衡饮食，但要让它们保持强壮，没有什么能取代新鲜肉类。\n\n在环形山西南角，你会找到一种叫剑龙的强大恐龙。它们的肉特别厚实多汁，正适合满足年轻暴掠龙的胃口！\n\n你愿意替我从它们身上收集10块肉吗？",
  },
  [27516] = {
    ["T"] = "洗得干干净净",
    ["O"] = "使用莫维克的清洁桶从葛拉卡温泉取水，然后趁水冷却前，用水清洗他附近的年轻毒皮暴掠龙。",
    ["D"] = "你看到我旁边那只年轻的毒皮暴掠龙了吗？\n\n这家伙喜欢在安戈洛泥泞的河流里跺来跺去，而且杀戮之后还没学会把爪子上的血洗干净。该给这位年轻女士洗个澡了！\n\n带着这只桶去环形山另一边的葛拉卡温泉，装满热水。回来后，在水冷掉之前把她刷洗干净。",
  },
  [27519] = {
    ["T"] = "风暴、大地、风与火",
    ["O"] = "削弱六个火元素，然后将火焰之力吸收到雅卢尼·观焰的图腾中。",
    ["D"] = "空气轻快、轻盈，容易被更明亮的能量推开——比如火焰。\n\n火焰在安戈洛很容易找到。环形山中央的火羽山上，到处都是灼热的元素。\n\n在开阔的熔岩池和它们的首领火焰使者附近要小心。他不是我们的研究对象。\n\n其他元素你可以削弱，并吸收到图腾中。",
  },
  [27520] = {
    ["T"] = "风暴、大地、风与火",
    ["O"] = "削弱六个水元素，然后将水之力吸收到雅卢尼·观焰的图腾中。",
    ["D"] = "最后，我需要你前往西边。葛拉卡温泉里有水元素栖息——坚韧、顽强的存在。\n\n<雅卢尼·观焰打量着你。>\n\n不过我相信你能应付它们。\n\n流程相同，先削弱它们，然后用图腾捕捉它们的精华。我们快完成了。",
  },
  [27524] = {
    ["T"] = "阿鲁-塔利斯的传说",
    ["O"] = "使用利基的岩芯钻机，从马绍尔营地的水晶洞深处、火羽山顶、铁石高原和葛拉卡温泉提取样本，然后把样本带回安戈洛环形山的利基·卡斯帕克那里。",
    ["D"] = "杰尔莎有没有提到，传说中是一场巨大的奥术爆炸摧毁了阿鲁-塔利斯？你找到的遗物也许能支持这个理论。如果这是真的，我们应该能在环形山长期沉积的沉积物样本中看到一层奥术残留。\n\n我需要照看杰尔莎，但如果你不介意帮忙，就拿着这台岩芯钻机，在安戈洛各处提取一些沉积岩芯。我会给你一份地点清单。",
  },
  [27529] = {
    ["T"] = "格格不入的东西",
    ["O"] = "在安戈洛环形山西南部某处找到利基·卡斯帕克。",
    ["D"] = "传闻安戈洛环形山里的水晶塔极其古老，而且没人知道它们来自哪里。我想知道那座水晶塔已经损坏多久了？\n\n我有个朋友是判定古物年代的专家——利基·卡斯帕克。她和她的搭档正在环形山西南角的恐惧小道附近进行考古研究。你能去看看她，问问她是否知道如何判断那座水晶塔是什么时候受损的吗？",
  },
  [28484] = {
    ["T"] = "给利基·卡斯帕克的委托",
    ["O"] = "利基·卡斯帕克要你使用急救技能制作20条符文布绷带，并把订单交给安戈洛环形山恐惧小道的利基·卡斯帕克。",
    ["D"] = "很高兴在这里见到有你这种技能的人，$C。杰尔莎还没恢复到能站稳的程度。外面袭击她的东西不只是牙齿和爪子。它背后带着狂怒，而她的恢复会很漫长。\n\n为了让她保持稳定，我已经用掉了大部分绷带储备。我们还需要更多。如果你能带给我20条符文布绷带，那会大大帮助她恢复。",
  },
  [28507] = {
    ["T"] = "给利基·卡斯帕克的委托",
    ["O"] = "利基·卡斯帕克要你使用钓鱼技能收集20条新鲜的红腮鱼，并把订单交给安戈洛环形山恐惧小道的利基·卡斯帕克。",
    ["D"] = "嘿，你背包上绑着的是鱼竿吗？我在想你能不能帮我们一个忙？\n\n杰尔莎的伤让我们在荒野里待得比计划更久，而我们的新鲜食物已经吃完了。虽然我们不至于挨饿，但天天吃同样的口粮有点……嗯，无聊！\n\n我们可以用点新鲜东西。不用太讲究！只要一些新鲜的红腮鱼，如果你愿意钓些给我们的话。",
  },
  [28582] = {
    ["T"] = "给利基·卡斯帕克的委托",
    ["O"] = "威利德·马绍尔要你使用制皮技能制作2双夜色长靴，并把订单交给安戈洛环形山恐惧小道的利基·卡斯帕克。",
    ["D"] = "哦！嘿，你不是制皮师……对吧？\n\n真走运！你看，我们刚收到利基·卡斯帕克的消息，她是个正在研究安戈洛古代精灵遗迹的侏儒。她的搭档杰尔莎受伤了，靴子也毁了。好像和焦油、毒液有关。总之，她们可以用得上几双新的夜色长靴。你能帮上忙吗？",
  },
  [26892] = {
    ["T"] = "野兽盟友",
    ["O"] = "在薄雾谷找到并消灭8名薄雾谷偷猎者。",
    ["D"] = "我在月光林地长大时，母亲曾给我读过薄雾谷猩猩的故事。她去世后，我觉得自己被吸引着来看看它们。而我所发现的一切，震惊得让我无法用语言形容。\n\n这些曾经数量众多的野兽，已经被偷猎到几近灭绝！不是为了肉，不是为了取暖——只是为了取乐！\n\n追捕下面山谷里的偷猎者，帮我揭开幕后黑手。\n\n这些巨猿需要你，$N。",
  },
  [27336] = {
    ["T"] = "梦魇精华",
    ["O"] = "从怒风兽穴的先祖梦魇身上收集10份梦魇精华样本，并把它们带给月光林地的希拉·月卫。",
    ["D"] = "月光林地看起来也许很宁静，$c，但我感觉在它平静的表象下潜伏着某种东西。\n\n风暴行者队长希望你消灭兽穴中不安的灵魂，但我更关心最初究竟是什么在折磨它们。一旦你杀死第一个，我想你就会明白我的意思……梦魇化为实体。\n\n收集这些梦魇的精华并带给我，好让我进一步调查。",
  },
  [27337] = {
    ["T"] = "在艾露恩之光中",
    ["O"] = "进入怒风兽穴中间的传送门，让10名卡多雷灵魂安息。这些灵魂只在夜间可见。完成任务后，返回月光林地怒风兽穴外的赛娜·风暴行者队长那里。",
    ["D"] = "$C，听好警告！怒风兽穴是宁静与和平之地，我们绝不容忍愚人玷污我们的圣地。\n\n通常外来者会被挡在外面，但我需要你的协助。当艾露恩的光芒照耀月光林地时，我们祖先的灵魂已经开始显现。虽然它们看起来平静，内心却因压抑的怒火而翻涌。\n\n我无法忍受每夜一遍又一遍地消灭我的族人。如果你愿意协助这些灵魂重归大地，我会感激不尽。",
  },
  [27338] = {
    ["T"] = "怒风兽穴",
    ["O"] = "与月光林地怒风兽穴的赛娜·风暴行者队长谈谈。",
    ["D"] = "你看起来是个能干的$c。赛娜·风暴行者队长是我们兽穴守望者的领袖，目前驻守在艾露恩湖东南侧的怒风兽穴。她正在寻找帮手，处理一件紧急事务。\n\n只要沿着永夜港外的道路绕湖一路前行，你就能找到她。",
  },
  [27577] = {
    ["T"] = "如月纯净",
    ["O"] = "在月光林地玛沃尔屋外，用月亮井的水装满水晶瓶。",
    ["D"] = "这非常令人不安，$C。幸好袋子还撑得住——如果这些种子中有一颗接触到土壤，我怀疑你就再也取不回来了。\n\n这些种子污秽不堪，但受月亮祝福的水可以净化万物。如果我没错，我们可以让这些种子反过来对抗它们邪恶的目的。把我的瓶子带到外面的月亮井装满，然后回来找我。",
  },
  [28029] = {
    ["T"] = "田野仪式",
    ["O"] = "德迪利特·星焰要你使用草药学技能采集20株山鼠草和20株冰盖草，并把它们带给月光林地永夜港的他。",
    ["D"] = "你有兴趣协助我的研究？非常好。我有许多事要做，而我已经不再拥有世界上所有的时间来完成它们。\n\n我感谢你的意愿，但我必须评估你的技艺。采集山鼠草和冰盖草，向我展示你的草药学能力。这样我就会知道，你拥有完成后续任务所需的天赋。",
  },
  [28030] = {
    ["T"] = "田野仪式",
    ["O"] = "前往辛特兰的辛萨罗，从邪枝草药师身上收集一把邪恶镰刀。把它带给月光林地永夜港的德迪利特·星焰。",
    ["D"] = "要采集我希望研究的样本，你需要一种特殊工具。我听说祖尔格拉布的古拉巴什巨魔有专门采集危险植物的镰刀，但既然祖尔格拉布对我们关闭了，我们就得寻找次优选择。\n\n据说辛萨罗的邪枝巨魔中有一名技艺高超的草药师。作为古拉巴什的近亲，也许这名草药师会有类似的工具？",
  },
  [28031] = {
    ["T"] = "田野仪式",
    ["O"] = "在希利苏斯的虫巢和洞穴中采集10朵菌花，测试邪恶镰刀，并把它们带给月光林地永夜港的德迪利特·星焰。",
    ["D"] = "既然我们已经取得邪恶镰刀，就必须用一些腐化植物来测试它。我想确认它确实有效，再派你去完成最终目标。\n\n在南方遥远的希利苏斯，有一支由塞纳里奥议会支持的研究远征队。他们报告说，那片土地的洞穴和虫巢中长出了奇怪的变异蘑菇。带上邪恶镰刀，采集这种真菌。远征队把它们命名为菌花。确保这把镰刀能让你采集它们，同时不扩散腐化。",
  },
  [28032] = {
    ["T"] = "田野仪式",
    ["O"] = "德迪利特·星焰要你使用草药学技能采集20株野葡萄藤、20株盲目草和1朵黑莲花，并把它们带给月光林地永夜港的他。",
    ["D"] = "让你毫无准备地进入危险并不合适。因此，我们还必须做最后一件事——为你准备一种可能的解毒剂，以备紧急情况。\n\n我在永夜港这里已经有了大部分所需材料，而且酿制还需要一些时间。我只需要一些野葡萄藤、盲目草和一朵黑莲花来完成混合剂。既然你是熟练的草药师，取得这些材料对你来说应该不成问题，对吧？",
  },
  [28033] = {
    ["T"] = "田野仪式",
    ["O"] = "前往西瘟疫之地的通灵学院，为月光林地永夜港的德迪利特·星焰收集一份瘟疫之地捕蝇草样本。",
    ["D"] = "既然解毒剂正在酿制，我可以揭示我们的最终目标了。\n\n诅咒教派正在西瘟疫之地做着污秽之事。我曾在那里花时间研究那片土地。它可以被治愈，但如果诅咒教派继续从他们在通灵学院的设施里释放腐化植物，就绝无可能。\n\n我必须取得他们腐化植物的样本，才能弄清如何阻止它们扎根和扩散。进入通灵学院，把这个样本带给我，并一举从诅咒教派手中移除那株植物！",
  },
  [28504] = {
    ["T"] = "给莫伦·河弯的委托",
    ["O"] = "莫伦·河弯要你使用钓鱼技能收集20条新鲜的银头鲑鱼，并把订单交给月光林地永夜港的莫伦·河弯。",
    ["D"] = "艾露恩湖里到处都是银头鲑鱼。它们挤占了其他鱼群，弄脏了芦苇，还破坏了湖泊的平衡。\n\n我们需要减少它们的数量。如果你会钓鱼，就带给我20条新鲜的银头鲑鱼。你会同时帮助生态系统和我们的餐桌。",
  },
  [8921] = {
    ["T"] = "灵质提纯器",
    ["O"] = "将1个精密奥金转换器、4份强效不灭精华、10瓶石鳞鱼油、25份火山灰和40枚金币交给加基森的穆克斯·玛纳斯卡波。",
    ["D"] = "啊，你需要我最新的项目……超维度幽灵显形器！遗憾的是，我已经没有资金和人手了。\n\n你愿意帮忙？太好了！我们的第一项任务，是制造一台能够收割死亡本质的装置！制造灵质提纯器可不是件容易的事，$N。\n\n我需要你给我带来一个奥金转换器、一些强效不灭精华和石鳞鱼油。我还需要一些来自燃烧平原熔岩池的火山灰，用来制造过滤器。",
  },
  [8922] = {
    ["T"] = "超自然的设备",
    ["O"] = "把封起来的血液容器带给塔纳利斯加基森内的穆克斯·玛纳斯卡波。",
    ["D"] = "我必须想办法和安泰恩·哈尔蒙谈谈……更确切地说，和他的鬼魂谈谈！\n\n我知道有个工程师对超自然之事有种古怪的兴趣。他声称自己能制造一台让他与死者交谈的机器！\n\n你收集的血液原本就是给他的；前往加基森，把它带给他，作为支付服务的报酬！ ",
  },
  [8923] = {
    ["T"] = "超自然的设备",
    ["O"] = "把封起来的血液容器带给塔纳利斯加基森内的穆克斯·玛纳斯卡波。",
    ["D"] = "经历那些之后你还留在这里，看来你相当勇敢。要么就是我给你的那件护甲激起了你的兴趣。如果你仍有兴趣帮助我，这类东西还有更多。\n\n你收集的血液样本是给我的一位熟人准备的，穆克斯·玛纳斯卡波，一个对超自然现象感兴趣的工程师。他最新的项目是一台能让你与死者沟通的装置！我最后的希望就是联系安泰恩，弄清更多关于我处境的事。",
  },
  [8925] = {
    ["T"] = "便携的能量源",
    ["O"] = "在燃烧平原找到熔岩领主博奥克，取得他的岩浆核心，并把它带给加基森的穆克斯·玛纳斯卡波。",
    ["D"] = "接下来，我们需要找到一种稳定且便于携带的能量源，用来维持灵质活性。我听说有个强大的元素生物叫熔岩领主博奥克，它的心脏是一枚强大的岩浆核心——无尽的热量来源！\n\n据说他可以在黑石山南边的燃烧平原找到。把岩浆核心带给我，我们就有足够的能量来驱动超维度幽灵显形器了！",
  },
  [26288] = {
    ["T"] = "收回工具",
    ["O"] = "从亮泥矿洞内的风险投资公司手中取回20件工具。",
    ["D"] = "事情是这样的，$N——几个月前，有人委托我为荆棘谷某个行动打造一批高品质工具。工头把那地方叫作闪……什么来着。亮泥！\n\n我不知道他们在挖什么，但他们往矿洞里投入了人手，也花大价钱给矿工配工具。\n\n从那以后，我在塔纳利斯这里接到了一份利润高得多的委托，而我需要尽可能把所有工具都拿回来，才能完成订单。\n\n如果这事只在你我之间，我想你可以去从亮泥矿工那里“取回”我做的工具，然后大家都开心。嗯，除了那些亮泥蠢货，哈哈。你怎么说？",
  },
  [26333] = {
    ["T"] = "拿王国换一条船",
    ["O"] = "取得维克要求的造船补给，并把它们带到她位于塔纳利斯的岛上。",
    ["D"] = "我不会游泳，而且现在也绝不会浪费时间去学！我需要的是造一条自己的船所需的部件——只是个小东西，所以我要求不多。\n\n这里是一份部件清单；穿着你那套防水护甲快去吧，把这些东西带给我。你越早出发，就越早回来，也就越早解除诅咒，而我也能睡上一张像样的床。\n\n哦——去哪儿弄这些东西？嗯，我听说西瘟疫之地有座伐木场，也许你可以在那里弄到一些。符文布不就是到处都有、谁都能拿的吗？线由贸易商人出售，沥青罐则得从其他海盗那里弄来。",
  },
  [26383] = {
    ["T"] = "战斗的召唤：塔纳利斯",
    ["O"] = "在塔纳利斯找到并杀死5名部落成员。",
    ["D"] = "塔纳利斯属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26384] = {
    ["T"] = "战斗的召唤：塔纳利斯",
    ["O"] = "在塔纳利斯找到并杀死5名联盟成员。",
    ["D"] = "塔纳利斯属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26420] = {
    ["T"] = "通往斯通纳德的门径",
    ["O"] = "从安戈洛环形山各处收集5块绿色能量水晶，然后返回斯通纳德的洛林·狐火那里。",
    ["D"] = "你的下一项任务在更远的地方，在遥远的卡利姆多。前往安戈洛环形山，收集5块绿色能量水晶。你在哪里都能找到它们，整个环形山里散布着能量水晶。人们对它们了解不多，这正是我让你去做这件事的主要原因。如果你从未去过，可以在塔纳利斯西南部找到通往环形山下方的道路。或者，如果你足够鲁莽，也可以直接施放缓落术跳进环形山。\n\n尽量别被吃掉。",
  },
  [27359] = {
    ["T"] = "让低语沉寂",
    ["O"] = "为希利苏斯勇士之墓的萨希娅·林冠杀死琥珀月之影，把她从疯狂中解放出来。",
    ["D"] = "前些时候，一个名叫布莱恩的流浪矮人经过这里，往返于塔纳利斯和希利苏斯之间，原因他没有透露。他最后一次经过勇士之墓时，报告说看见了南风村一名指挥官的阴影，琥珀月女士。他说自己听见她在和只有她能听见的低语交谈。\n\n我担心她受折磨的心智真的已经崩溃了——或者更糟，有某种邪恶之物正在亡灵状态中影响她。你愿意把她的灵魂从掌控它的黑暗力量中释放出来吗？",
  },
  [27417] = {
    ["T"] = "洛阿的敬意",
    ["O"] = "从塔纳利斯西南部的炎鹏和晶鳞石化蜥蜴身上收集肉，作为献给海之洛阿格拉尔的供品。",
    ["D"] = "嘿，朋友。我是阿基哈，强大的萨满，也是海之洛阿格拉尔的仆人。我带着一项至关重要的任务来找你。\n\n在安杰瓦萨西边，有炎鹏和晶鳞石化蜥蜴。那些野兽以鲜美的肉闻名，我需要大量肉来赢得格拉尔的青睐。\n\n我需要格拉尔的祝福，来维持那些在沙漠中为我们供水的元素流动。没有他的青睐，它们会枯萎并消散。\n\n尽你所能给我带来更多肉。",
  },
  [27419] = {
    ["T"] = "轰！轰！轰！",
    ["O"] = "从塔纳利斯深沙平原的火鹏身上收集8个火焰囊。它们通常出现在骨骸周围。",
    ["D"] = "轰！轰！轰！我正在做一枚超——大手雷！为什么？为什么不呢！？轰！轰！轰！\n\n我需要一点额外的助力，而那只能来自一样东西：火鹏。你能去收集一些它们的火焰囊吗？",
  },
  [27422] = {
    ["T"] = "没人能白喝水",
    ["O"] = "和热砂港那些没有支付水费的住户严肃谈谈。完成任务后，返回塔纳利斯热砂港的安全主管吉罗姆·比格维兹那里。",
    ["D"] = "嗯，你看起来像个会走路、会说话、还很凶狠的家伙……想接点外快吗？在这里，如果你想要最好的清洁用水，就必须通过我们。我们把水直接用管道输送到镇上所有住户家里，并收取费用。\n\n有些人似乎不明白我们已经多么慷慨，还“忘了”付账。我需要有人去说服他们。你能做到，对吧？\n\n第一个是米基·小弹簧小姐。她在旅店后面出售食物和饮料。第二个是伊纳比特·楔足，我们这里痴迷爆炸的住户。你很容易找到他，因为他是镇上唯一的侏儒。第三个你得找到斯特尔克斯。她最近开店出售和修理护甲。最后，是那个满身鱼腥味的蠢货吉科希斯。",
  },
  [27425] = {
    ["T"] = "工蝎叛乱",
    ["O"] = "为塔纳利斯的斥候影舞者在腐化之巢杀死10只森提帕尔工蝎。",
    ["D"] = "仔细听着，$n。在你从森提帕尔巨蜂身上收集毒刺时，我看见森提帕尔工蝎把昏迷的斥候队成员拖进虫巢，原因不明。我需要你杀死这些工蝎，防止它们把更多我的斥候带进虫巢。",
  },
  [27427] = {
    ["T"] = "其拉虫群清剿",
    ["O"] = "深入虫巢侦察，并消灭6只森提帕尔掘洞蝎和6只森提帕尔沙行者。",
    ["D"] = "谢谢你帮助复苏斥候，$n。现在是时候为森提帕尔对我的斥候队所做的一切复仇了。我需要你深入虫巢侦察，消灭那些负责在塔纳利斯沙地下挖掘隧道的森提帕尔掘洞蝎和森提帕尔沙行者。\n\n虫巢是危险之地，里面充满各种致命昆虫。你必须小心，$n，并准备好面对一场艰难而危险的战斗。杀死掘洞蝎和沙行者后，回到我这里。",
  },
  [27428] = {
    ["T"] = "虫群焚尽",
    ["O"] = "在腐化之巢最深处焚烧6具森提帕尔毒刺蝎或森提帕尔群居蝎的尸体。",
    ["D"] = "我有一项特殊任务给你，$n。腐化之巢最深处充满最强韧的森提帕尔，包括森提帕尔毒刺蝎和森提帕尔群居蝎。我需要你抵达那里并杀死这些昆虫。\n\n不过，有个条件。杀死毒刺蝎和群居蝎后，你必须使用一支涂有碾碎毒刺膏的火把点燃它们。毒刺膏极易燃。\n\n你看，$n，森提帕尔毒刺蝎和森提帕尔群居蝎是森提帕尔最强的繁殖者。杀死它们并点燃尸体，就能重创它们的族群，阻止它们重建虫巢。这计划有风险，但这是确保塔纳利斯居民安全的唯一办法。我能相信你会做到吗，$n？",
  },
  [27430] = {
    ["T"] = "补给安杰瓦萨",
    ["O"] = "把补给带给塔纳利斯东南角安杰瓦萨的乌鲁尔格。",
    ["D"] = "向你致意，冒险者。如果你愿意接受挑战，我有一项任务交给你。我们收到消息，东南方的安杰瓦萨前哨补给不足。我需要有人把一批补给送到他们那里。你会在大裂口附近找到那座前哨——只要从加基森向东南走，应该就能找到。你有兴趣吗？",
  },
  [27431] = {
    ["T"] = "寻找沃提",
    ["O"] = "在塔纳利斯的天涯海滩找到沃提·跃日，并确认她安全无恙。",
    ["D"] = "向你致意，冒险者。我需要你的帮助。我亲爱的朋友沃提·跃日已经失踪好几天了。她是一名熟练的渔妇，也是我们社区中宝贵的一员。我担心她遭遇了可怕的事。\n\n你能去天涯海滩寻找沃提吗？她的家就在那里，那也是她最后一次被看见的地方。我会永远感激你。",
  },
  [27435] = {
    ["T"] = "技术进步",
    ["O"] = "前往热砂港，向旅店老板菲兹脑索要一台给海象人使用的冷却器。",
    ["D"] = "我还没有联系热砂港，但我听说他们有一台机械冷却器，可以用来拯救这名海象人。不过我担心，如果没有充分理由，他们可能不愿意借给我们。\n\n你能前往热砂港，说服旅店老板菲兹脑把冷却器借给我们吗？我知道这可能很困难，但我相信你的技能和能力。\n\n海象人的性命就靠它了。",
  },
  [27439] = {
    ["T"] = "大脑大劫案",
    ["O"] = "从塔纳利斯两处虫巢的异种虫身上收集大脑。",
    ["D"] = "啊，所以你就是那个要帮我研究的英雄，对吗？好吧，我得告诉你，这可不是件容易的事。我需要塔纳利斯两处虫巢中异种虫的大脑。你觉得自己能应付，还是我该另找别人？\n\n我没时间解释细节，但简单说，我正在研究异种虫，需要那些小东西的大脑。塔纳利斯的虫巢里到处都是它们，所以赶快过去，尽可能多收集大脑。我会在你回来时等着你。",
  },
  [27440] = {
    ["T"] = "虫巢思维",
    ["O"] = "从塔纳利斯热砂港的伊纳比特·楔足那里取得杜蒙特的秘密补给。",
    ["D"] = "我们注意到异种虫大脑里有些东西。一种……心灵链接。它们并不只是受本能驱动——沙丘某处有一个强大的哈扎里首领，控制着这里和腐化之巢的异种虫。\n\n异种虫的大脑非常简单，所以我们要制作一顶特殊的心灵控制帽，还要装上炸药。我觉得这会非常适合这里的丹尼斯……\n\n我已经委托热砂港一个古怪的侏儒伊纳比特·楔足制作这顶帽子，还有一些别的东西。你能替我取回来吗？",
  },
  [27443] = {
    ["T"] = "艾泽拉斯太空协会",
    ["O"] = "在热砂港找到艾泽拉斯太空协会的戈达德。",
    ["D"] = "我们的首席火箭科学家戈达德已经在热砂港搭起了他的实验火箭开发平台。好像是因为朝海上发射更安全——但安全什么时候重要过？\n\n他最近抱怨说，需要有人帮忙寻找关键材料。\n\n你能去找他，看看他想要什么吗？",
  },
  [27445] = {
    ["T"] = "完美燃料",
    ["O"] = "从热砂港东北方钻油平台底部收集原油。",
    ["D"] = "在这里东北方的钻油平台底部，你可以找到一个阀门，他们用它在炼油前后测试纯度。我需要能找到的最粗糙、最未经精炼的油，所以这意味着我们得从水下偷一些。去那座平台，带上这个容器。在阀门那里装满它，再带回来给我，这样我们就能继续。",
  },
  [27447] = {
    ["T"] = "更好的燃料",
    ["O"] = "为热砂港的普尔收集一枚变异石化蜥蜴腺体和6枚晶鳞腺体。",
    ["D"] = "嘘……到这边来……小声点。\n\n听着，就你我之间说，我觉得这里的戈达德就是个傻瓜。总是使唤我，还吹嘘自己有多聪明。我受够了！首席火箭科学家只能有一个；预算不允许更多。所以……帮我除掉他，我会比他对你更好。你怎么说？\n\n我要往混合物里加点额外成分，点燃时会造成灾难性结果。如果你愿意帮忙，我需要沙丘里的晶鳞石化蜥蜴腺体。那是燃料里相对正常的成分。额外火花来自我在附近见过的一只变异个体。我觉得是油让它变得不太正常！有人看见它在这里南边的海滩巡逻。去给我取它的腺体，加入混合物。\n\n这事只在我们之间，否则我们两个都会在加基森外面被拧断脖子。",
  },
  [27448] = {
    ["T"] = "危险混合物",
    ["O"] = "在纳瑞安家中混合火箭燃料材料，然后把实验火箭燃料带回热砂港的戈达德那里。",
    ["D"] = "现在我们终于要实际混合所有东西了。我那个讨厌的助手已经替你把所有材料打包好了，拿着。\n\n唯一的问题是，这个流程如果做错了，可能会……爆炸。港口明确禁止我在城墙内尝试，所以你不如到最近的合适地点混合它。让我想想……我知道了！镇外北边那个蠢货纳瑞安的房子。他总是在抱怨我们这里的工作，而这样会有两种可能结果。\n\n如果混合正确，就什么也不会发生。如果不正确，嗯，炸飞的也只有你和他。双赢。",
  },
  [27450] = {
    ["T"] = "艾泽拉斯太空协会整顿",
    ["O"] = "把普尔的报告带给加基森的艾泽拉斯太空协会创始人克兰兹。",
    ["D"] = "嘿，嘿，嘿，真是完美！我敢说他们从安戈洛都能看见火箭烟。现在我唯一要做的，就是在我们老板心里播下怀疑的种子，我很快就能拿到戈达德的工作。\n\n这是我整理的事件报告。把它带给我们组织的创始人克兰兹，你在这里的工作就完成了。",
  },
  [27451] = {
    ["T"] = "传承者万扎",
    ["O"] = "在塔纳利斯的安杰瓦萨找到传承者万扎。",
    ["D"] = "如果你有兴趣，我可以用得上一个去沙漠的信使。\n\n在塔纳利斯南部，你会找到巨魔定居点安杰瓦萨。传承者万扎几周前去了那里，到现在还没有寄回进度报告。如果你在那一带，能给我带回点消息，我会感谢你的。",
  },
  [27452] = {
    ["T"] = "死去的讯息",
    ["O"] = "搜索塔纳利斯海岸，寻找传承者万扎失踪的信使。",
    ["D"] = "如果传承者贾尼没有收到我的报告，那信使们一定出了什么事。我担心他们的性命，朋友。\n\n我告诉他们两个都走沿海路线——避开异种虫和沙尘暴。你愿意搜索海岸，看看能否找到他们的任何踪迹吗？还要小心，$C。",
  },
  [27454] = {
    ["T"] = "寻找陵墓",
    ["O"] = "从祖尔法拉克附近的沙怒巨魔身上收集6枚图尔玛瑞信物。",
    ["D"] = "我来到塔纳利斯，是为了寻找图尔玛瑞的陵墓，她是大分裂之前时代的一位古老巨魔英雄。我相信陵墓就在塔纳利斯，但沙怒巨魔也声称图尔玛瑞是他们的祖先。他们知道陵墓在哪里，却不想让我找到。我试过谈判，但失败了。\n\n你在尸体上看到的黑皮肤，是沙怒毒药。如果他们杀了我的信使，那我就要请你去杀他们！沙怒巨魔带着一些小信物，上面写着图尔玛瑞的话。既然他们不愿和平交出我需要的东西，我就用武力从他们手里夺来。",
  },
  [27456] = {
    ["T"] = "寻找陵墓",
    ["O"] = "杀死祖尔法拉克的巫医祖穆拉恩，取得他的符咒书，交给奥格瑞玛的传承者基辛。",
    ["D"] = "我会替万扎做这份翻译，不过在我忙活时，你得帮我一个小忙。既然你反正要在塔纳利斯办事，我想让你去拜访我那位老朋友，祖尔法拉克的巫医祖穆拉恩。\n\n很久以前，他偷走了一份我想拿回来的古老符咒配方。既然他不会主动交出来，就杀了他，把他的符咒书带给我。\n\n然后我就把翻译给你。",
  },
  [27457] = {
    ["T"] = "寻找陵墓",
    ["O"] = "把译文带给塔纳利斯安杰瓦萨的传承者万扎。",
    ["D"] = "这是传承者万扎要求的译文。我想它意味着你还有更多活要做。你看，它说他寻找的陵墓在大分裂期间沉入了海浪之下。而万扎，他害怕大海。\n\n<传承者基辛咯咯笑了起来。>\n\n幸运的是，上面说有一道魔法屏障保护陵墓，让海水无法进入，所以如果你找到了它，就能在那里呼吸。祝你好运，$C。",
  },
  [27458] = {
    ["T"] = "寻找陵墓",
    ["O"] = "找到图尔玛瑞陵墓，并取回德雷克之锤。",
    ["D"] = "图尔玛瑞是德雷克的勇士，他死后她继承了他的锤子。根据传说，那把锤子与她一同下葬。那就是我要找的东西。\n\n但这份译文说，陵墓沉在塔纳利斯南部海岸外的浪涛之下。我不会游泳，$C，而且我讨厌大海。\n\n请替我搜索南部近海水域，找到那座陵墓，我求你了。",
  },
  [27460] = {
    ["T"] = "它们大多在夜里出现……大多如此",
    ["O"] = "在夜间从塔纳利斯的夜行者身上收集10副夜行者下颚。",
    ["D"] = "该死的异种虫又在制造麻烦了。有人看见它们派出夜行者守卫塔纳利斯的领地。这些野兽只在夜间出现，所以如果你想追踪它们，就得小心。\n\n你可以在腐化之巢和大裂口找到夜行者。腐化之巢在遥远的西北方，大裂口就在安杰瓦萨外面。\n\n用你的力量和狡诈击败它们，并收集它们的下颚作为胜利证明。",
  },
  [27461] = {
    ["T"] = "想想那些动物",
    ["O"] = "清洗塔纳利斯海岸沿线8只沾满油污的小动物。",
    ["D"] = "自从地精建起那座钻井平台后，我就在海岸上下发现许多动物因为泄漏而沾满油污。野生动物正在受苦，看到它们这样让我心碎。\n\n你能做点什么吗？我救不了它们全部。拿着这些清洁用品，帮助你遇到的任何沾满油污的野兽。",
