  [27463] = {
    ["T"] = "孤注一掷",
    ["O"] = "从加基森的巴兹克·布拉斯温那里取得玛莱的“补给”。",
    ["D"] = "我受够了！我已经能看见新的小动物在受苦，新的油桶被倒进海里。水务公司不会帮我，因为他们有那套花哨的过滤废话。如果我们想让污染停止，就必须去真正的源头……那座钻井平台必须消失……永久地。\n\n我联系了加基森一位名叫巴兹克的工程大师，他已经为我准备了一些“补给”。你能替我取回来吗？它们对接下来要做的事很重要。",
  },
  [27464] = {
    ["T"] = "痛打石油大亨",
    ["O"] = "在热砂港北边的钻井平台杀死8名钻井平台工人和他们的首领鲁尼监工。",
    ["D"] = "拆掉那座钻井平台的第一步，是清除平台工人。他们的首领名叫鲁尼监工，就在平台顶部的控制室里。\n\n其余工人只是喽啰，但他们为了自己的经济利益，根本不在乎让小动物受苦，所以这对我来说已经足够了。什么样的怪物才会这么做？",
