  [27466] = {
    ["T"] = "火焰箭头",
    ["O"] = "在塔纳利斯的安杰瓦萨找到梅尔乔·血奔。",
    ["D"] = "我知道你最近发现异种虫毒刺可以碾成糊状，并作为可燃武器使用。在我们同时对抗联盟和异种虫的持续战争中，这个情报对我们的事业可能很有价值。我请求你帮助把这项情报交给一名被遗忘者，梅尔乔·血奔。他就在附近，安杰瓦萨内的一处洞穴里。",
  },
  [27467] = {
    ["T"] = "火焰箭头",
