    ["O"] = "从热砂港周围的海床上收集8个过滤器零件。",
    ["D"] = "热砂港是水务公司帝国的核心，但现在我们完全靠储备运转，因为过滤系统遭到了严重损坏。\n\n我们本来在等一批零件运来，但那些操作起重机的笨重蠢货在船靠岸时，把大多数箱子都撞下了船！现在真是找不到好人才！\n\n你能沿着海岸潜下去，在那些零件锈到不能用之前把它们找回来吗？",
  },
  [27472] = {
    ["T"] = "女工的工具",
    ["O"] = "使用塔纳利斯沙丘各处被削弱的狂怒风暴，为基克斯的电池充能。",
    ["D"] = "这台焊机唯一的问题，是拉泽瑞克显然没有给它保持充电。真像他的作风。\n\n塔纳利斯沙丘里有一种稀有元素，我们把它叫作狂怒风暴。它们体内充满极其强大的电力！如果我们从它们身上虹吸能量，就能迅速给焊机电池充电。\n\n你必须先削弱那些风暴，然后用充能器轰它们。用不了多久，我们就能让高品质的水再次流过这里了。",
  },
  [27474] = {
