    ["O"] = "询问热砂港的打手，查明那个阴影身影是谁以及去了哪里。",
    ["D"] = "破坏者！现在一切都说得通了……他们一定是故意把我们的零件撞进海里的！一开始破坏过滤器的也是他们！但会是谁呢？\n\n我没看清他们逃向哪里，不过打手们就是拿钱干这个的。去问问他们看见了什么。",
