  [27475] = {
    ["T"] = "明确指控",
    ["O"] = "把你怀疑是谁破坏了水过滤系统告诉热砂港的安全主管吉罗姆·比格维兹。",
    ["D"] = "所以他们都反复提到同一个人，多兹德。为什么这个名字听起来这么耳熟？一个打手！他是守卫之一。这是内鬼干的！必须把这件事告诉安全主管。现在就去找他！",
  },
  [27476] = {
    ["T"] = "通缉：多兹德",
    ["O"] = "找到并杀死前打手多兹德。据报告，他最近出现在加基森外面。",
    ["D"] = "我们的探员告诉我们，叛徒多兹德被人看见从加基森取得补给后走出了城门。无论他在哪里，都应该离那里不远。找到他，以水务公司的名义杀死他。事情办完后向安全主管报告。",
  },
  [27535] = {
    ["T"] = "风暴汇聚",
    ["O"] = "调查塔纳利斯入口和希利苏斯入口处的奇怪水晶塔。",
    ["D"] = "如果这些水晶塔确实阻止了异种虫扩散，也许还有其他线索能说明它们最初为何被创造出来。\n\n在安戈洛环形山入口处，东南和西北两侧都有深紫色水晶塔。你愿意去调查那些水晶塔，看看它们是否与环形山内部的水晶塔有关吗？\n\n我对此有种不好的预感……",
  },
  [27536] = {
    ["T"] = "风暴汇聚",
    ["O"] = "在希利苏斯的勇士之墓询问其拉水晶塔雕文中的讯息。",
    ["D"] = "在马绍尔远征队于加基森准备期间，一群名叫勇士远征军的人已经出发前往希利苏斯。他们中的一些研究者自称是这些异种虫方面的专家。如果那些黑暗水晶塔是由它们创造的，也许你观察到的刻痕对他们来说会有意义。\n\n我不知道他们现在在哪里，但如果你沿路进入希利苏斯，也许能找到他们的营地？",
  },
  [27632] = {
    ["T"] = "给阿基哈的委托",
    ["O"] = "杜蒙特·空哭要你使用炼金术技能制作5瓶强力水下呼吸药剂，并把订单交给塔纳利斯安杰瓦萨的阿基哈。",
    ["D"] = "我觉得巨魔和他们那些愚蠢的洛阿灵魂都荒唐极了！看看阿基哈就是个例子。一个“鲨鱼神”？多荒谬的想法！\n\n如果这个格拉尔真的存在，为什么不制作一些强力水下呼吸药剂，然后去打个招呼呢？事实上，既然你是炼金师，你为什么不就去做这件事？",
  },
  [27683] = {
    ["T"] = "给努恩特格·双弯的委托",
    ["O"] = "努恩特格·双弯要你使用锻造技能制作2把巨型黑色锤，并把订单交给塔纳利斯安杰瓦萨的努恩特格·双弯。",
    ["D"] = "啊，一位铁匠。我需要你的技艺。\n\n虽然异种虫已经被击退，但我们需要新武器继续战斗。我听说有一种巨型黑色锤，对付那些生物非常有效。如果你能打造一对带来让我试试，我们就能看看传言是否属实。",
  },
  [27941] = {
    ["T"] = "取材于爬行者",
    ["O"] = "与塔纳利斯安杰瓦萨西南方天涯海滩的扎昆科谈谈。",
    ["D"] = "向你致意，$C。一位名叫扎昆科的巨魔萨满正在寻找像你这样经验丰富的冒险者，帮助设计一种模仿矮人能力的方法。\n\n这关系到他们清除自身病痛的能力。这名萨满正在研究塔纳利斯南部一种独特的石化蜥蜴，地点在安杰瓦萨西南方的天涯海滩。\n\n通常我会避开这种奇怪的请求……但扎昆科是部落中声誉良好的一员。",
  },
  [27943] = {
    ["T"] = "冷却它",
    ["O"] = "从北边洞穴中库扎加爬行者附近的冰冻猎物身上收集15块冻结碎块。",
    ["D"] = "塔纳利斯太热了，朋友！对扎昆科来说太热……但你可不想让石化蜥蜴来帮你。\n\n所有被石化蜥蜴吐息害死的灵魂，都被陈列在洞穴里……你很快就会亲眼看见。冻得结结实实！在这种地方！\n\n我们需要你找到的任何遗骸。把它们敲碎，收集冻结碎块——要尊重些。",
  },
  [27945] = {
    ["T"] = "不灭信念",
    ["O"] = "告诉扎昆科你准备好后，使用扎昆科的魔符，撑过他用刀划出的一道伤口。",
    ["D"] = "好，朋友，最后的考验……！\n\n你知道矮人吧？抗寒、止血、抗毒、抗病……皮也真的很厚，但只有他们化为石头时才这样。\n\n扎昆科这里有把刀……锯齿刃，涂着扎昆科能找到的最致命毒药：塔纳利斯周围尸体里的染病血液。\n\n朋友，如果你不用魔符，这会杀了你。最后会成功的，灵魂已经说过。准备好挨这一刀时，就和扎昆科谈谈。",
  },
  [27975] = {
    ["T"] = "工坊仪式",
    ["O"] = "在希利苏斯任意虫巢杀死掘洞者、雄蜂、掘洞蝎和工虫，直到找到一个奇怪的古代物件，然后把它带给荒芜之地弹簧座的豪伊·车链。",
    ["D"] = "这个球体里的装置……\n\n<科琳咳嗽着，又从物件里抖出更多沙子。>\n\n在我看来绝对像泰坦科技。可这些沙子！根本不是安戈洛的！而且我也不觉得它像塔纳利斯的沙子。\n\n不过……不久前有一支前往希利苏斯沙漠的研究远征队经过这里。他们回报说，发现一群虫子正在沙漠里挖掘。也许那些会挖洞的虫子会有更多这种东西，如果它们是从那里来的话？\n\n远征队在西北方向的山上找到了一条路。值得一试。如果你真的找到什么，不妨把它带回给豪伊。我可不知道该怎么处理它。\n\n祝你好运！",
  },
  [27976] = {
    ["T"] = "工坊仪式",
    ["O"] = "豪伊·车链要你使用工程学技能为他制作1台修理机器人74A型、3个高级活动假人、1枚强力爆盐炸弹和20枚瑟银手榴弹。把它们带给荒芜之地弹簧座的他。",
    ["D"] = "奥丹姆是一座古老的泰坦研究设施。这些节点有点像参考书，而读取它们的装置应该存在于那座设施中。但它被锁得死死的。\n\n也许这个节点能帮助我们研究如何开启奥丹姆。我一完成弹簧座的工作，就必须尽快前往那里。\n\n离开前，我必须为真正的沙漠露营做好准备——而且我听说塔纳利斯甚至比荒芜之地还要偏远！不过这就是为什么你是我的助手！我需要一些补给：一台修理机器人74A型和一枚强力爆盐炸弹用于挖掘工作，一些高级活动假人用来应对陷阱，还有一堆瑟银手榴弹，用来赶走本地野生动物！",
  },
  [28000] = {
    ["T"] = "烈火仪式",
    ["O"] = "与塔纳利斯热砂港的卡雷姆谈谈。",
    ["D"] = "我的朋友卡雷姆也许被称为艾泽拉斯最好的厨师……但如果她不能在下一位美食评论家品尝她的菜单时保住她的米什伦星，她就有可能把这个头衔输给伊莎贝尔·皮克曼。她联系我，想找一位有才能的副厨，而你是曾经走进这间厨房的最优秀者之一。这意味着你有机会和传奇的卡雷姆一起烹饪！\n\n你会在热砂港的新餐厅找到她。如果你不知道，那地方在塔纳利斯。",
  },
  [28001] = {
    ["T"] = "烈火仪式",
    ["O"] = "塔纳利斯热砂港的卡雷姆要你使用烹饪技能制作10杯蛋白饮，并把它们带给她。",
    ["D"] = "副厨？哦！很高兴我的消息传到了。\n\n是的，是的，伟大的卡雷姆需要一位副厨。但你必须足够熟练，才能帮助我对抗我的老朋友伊莎贝尔·皮克曼。\n\n伊莎贝尔已经被食物的黑暗面腐化了，但我不能否认她有天赋，还有……就叫创造力吧。烹饪她的招牌蛋白饮，向我证明你在我的厨房里会有用。\n\n如果你还不知道怎么制作，也许得先去她脚下学习。她如今位于西瘟疫之地凯尔达隆岛上。",
  },
  [28002] = {
    ["T"] = "烈火仪式",
    ["O"] = "进入西瘟疫之地的通灵学院，找到伊莎贝尔·皮克曼的食谱。把它带给塔纳利斯热砂港的卡雷姆。",
    ["D"] = "伊莎贝尔·皮克曼现在是通灵学院那所不知做什么的学校的主厨，就在瘟疫荒地上。她在偷走我许多实验食谱并冒充成自己的作品之后，获得了这个显赫职位！\n\n好吧，在烹饪界，以牙还牙天经地义。我要你替我们进行一次间谍行动。她在那所学校里一定有本食谱。去那里偷回来！我需要知道她正在研究什么，这样我才能超越那些计划。",
  },
  [28003] = {
    ["T"] = "烈火仪式",
    ["O"] = "为塔纳利斯热砂港的卡雷姆从希利苏斯亚什虫巢的生物身上收集10块柔软肉块。",
    ["D"] = "神圣之树啊！这本书里的食谱太骇人了！大多数都用了人肉……恶心。人类没什么味道，还带野味……而且不管怎样，现在也不是季节。\n\n不过看，她这里有些关于混合陆地肉和海鲜的笔记。我们也可以这么做。海就在这里，但去哪儿找和人类足够相似、又不至于那么糟糕的陆地肉呢？\n\n我知道了！希利苏斯有些虫状生物，是塔纳利斯这里那些的放大版。我烹饪过本地的，味道差不了太多。大的那些能给我们真正的肉排。去希利苏斯给我弄一些回来，就算按市价也行。",
  },
  [28004] = {
    ["T"] = "烈火仪式",
    ["O"] = "塔纳利斯热砂港的卡雷姆要你使用烹饪技能制作10份龙虾卷、10瓶斯坦索姆白葡萄酒和10杯海员烈饮，并把它们带给她。",
    ["D"] = "这些异种虫肉排会解决陆地那部分，所以现在该处理海味了。就用经典的——龙虾卷。你做过吗？如果需要配方，海盗们可喜欢这东西了。\n\n我们也不能忘了饮品。菜单上加些海员烈饮，增添一点俏皮，再加斯坦索姆白葡萄酒，给讲究的味蕾。\n\n这些配方你也不知道？嗯，海员烈饮和龙虾卷来自同一个地方，而斯坦索姆白葡萄酒显然来自……斯坦索姆！",
  },
  [28005] = {
    ["T"] = "烈火仪式",
    ["O"] = "与塔纳利斯洞穴中的扎拉什吉谈谈。",
    ["D"] = "如果你想到大海和住在那里的人，最终总会想到纳迦。纳迦是我的古老亲族，所以按理说他们一定也像我一样，有精致的晚宴。\n\n不远处住着一名纳迦流亡者，就在沿海岸下去一点的地方。去问问他，纳迦会怎样布置餐具。也许我们可以借鉴一些他们的点子？",
  },
  [28055] = {
    ["T"] = "织机仪式",
    ["O"] = "与塔纳利斯热砂港的傲慢的店主谈谈。",
    ["D"] = "哦，$N！很高兴你顺路过来。我最近听说艾泽拉斯首屈一指的设计师之一，傲慢的店主，正在寻找一名熟练的裁缝助手。我看过你的一些作品，觉得你会对这个机会感兴趣。\n\n如果你想去看看，店主女士目前就在塔纳利斯南边的热砂港。",
  },
  [28056] = {
    ["T"] = "织机仪式",
    ["O"] = "傲慢的店主要你使用裁缝技能制作4个符文布背包，并把它们带给塔纳利斯热砂港的她。",
    ["D"] = "你就是助手？好吧，我想乞丐不能挑肥拣瘦。\n\n我讨厌承认自己需要帮助，但我的确需要。你看，我为了开店向血帆海盗借了一些本钱，现在还款日来得比我赚额外现金还快。我必须把利润花在保持时尚前沿上——而这就是你出场的地方。\n\n免费替我处理一些任务，你就能在履历上写自己曾和传奇的傲慢的店主共事！你可以先完成这批符文布背包订单。",
  },
  [28057] = {
    ["T"] = "织机仪式",
    ["O"] = "为塔纳利斯热砂港的傲慢的店主，从瘟疫之地的蜘蛛身上收集5份铁网蛛丝和5份死灵蛛丝。",
    ["D"] = "这单很简单！我要完成的下一份订单来自一些痴迷蜘蛛的巨魔。他们想在设计里加入蛛丝，但我已经用完了。所以你去瘟疫之地再弄些来吧。我听说那里的蜘蛛非常大，因此丝也非常好。我要一些强韧的丝和一些异域的丝。你觉得能办到吗？",
  },
  [28058] = {
    ["T"] = "织机仪式",
    ["O"] = "进入托尔巴拉德岛上的巴拉丁监狱，杀死格拉古特，然后回到塔纳利斯热砂港的傲慢的店主那里。",
    ["D"] = "所以，这笔交易……需要你的帮助和你的$C本事。\n\n血帆愿意免掉我一半债务，只要我能替他们解决一个麻烦。那个麻烦？一个叫格拉古特的叛徒食人魔，他以前是血帆的一员，后来离开去加入了另一支舰队。我猜海盗不喜欢叛徒？\n\n总之，据说格拉古特的新舰队正在阿拉希高地海岸外的托尔巴拉德岛周围航行。这种冒险活不是我的专长，所以我把它交给你。",
  },
  [28059] = {
    ["T"] = "织机仪式",
    ["O"] = "傲慢的店主要你使用裁缝技能制作2个灵魂袋和2块月布，并把它们带给塔纳利斯热砂港的她。",
    ["D"] = "下这份订单的情侣太可爱了！完全是异性相吸……那个暗夜精灵肯定是牧师，想要一些月布。可他的女朋友？完全是术士气质。订了几个灵魂袋。\n\n我相信你能处理这单。我的债快还清了，如果你坚持到最后，我一定会告诉别人你帮过我。",
  },
  [28060] = {
    ["T"] = "织机仪式",
    ["O"] = "为塔纳利斯热砂港的傲慢的店主，从希利苏斯的暮光信徒身上拾取8块微光暮布。",
    ["D"] = "我不知道希利苏斯沙漠具体在哪里。血帆说在西边，塔纳利斯以西很远。显然那些海盗和住在那里的那群信徒有点过节。好像是什么召唤深处的狂野元素，在迷雾之海吞掉一艘船……如果话题不是时尚，我有时会跟丢。\n\n引起我注意的是，据说这些信徒会自己织布。血帆称它为微光暮布。他们想让我杀一些信徒来清算旧怨，而我想要这种布。所以，杀信徒，直到你拿到八块微光暮布，那应该就足以还清我的债了！",
  },
  [28061] = {
    ["T"] = "织机仪式",
    ["O"] = "傲慢的店主要你使用裁缝技能制作一顶将军之帽，并把它带给塔纳利斯热砂港的她。",
    ["D"] = "所以……血帆说，只要我再做一件小小小事，他们就会认为我的债全部还清。那就是，给他们的头号老兄制作一顶将军之帽。\n\n不幸的是，我完全不知道这顶帽子该长什么样！我猜荆棘谷某个海盗裁缝有它的图样，但我从没去过东部王国，而且听说狂野元素会吞船之后，我绝对不上船。\n\n所以就靠你了，$N。给我制作这顶将军之帽。我会自由，而你会稍微更有名一点。",
  },
  [28074] = {
    ["T"] = "给纳瑞安的委托",
    ["O"] = "纳瑞安要你使用烹饪技能制作10条银头鲑鱼，并把订单送到塔纳利斯热砂港附近他的家中。",
    ["D"] = "啊，有访客！你觉得地精在海岸上建的这座漂亮城市怎么样，嗯？热砂港真的发展起来了！我还记得它只是码头旁几间小屋的时候。感觉像上辈子的事……总之，你不是来听我回忆过去的。你是来给我烹制美味的银头鲑鱼的，对吧？我总是知道每个人接下来要做什么！",
  },
  [28420] = {
    ["T"] = "给梅尔乔·血奔的委托",
    ["O"] = "梅尔乔·血奔要你使用附魔技能制作1块大块强光碎片，并把订单交给塔纳利斯安杰瓦萨的梅尔乔·血奔。",
    ["D"] = "这些日子补给商队少得可怜，毕竟有海盗、废土强盗、食人魔……还有虫子……好吧，这地方确实危险。我的大块强光碎片用完了，研究需要一块，你能替我弄一块吗？我会为你的努力付钱。",
  },
  [28470] = {
    ["T"] = "给蕾米·冷眼的委托",
    ["O"] = "蕾米·冷眼要你使用工程学技能制作2个高级假人，并把订单交给塔纳利斯安杰瓦萨的蕾米·冷眼。",
    ["D"] = "我有许多步兵要训练，$N，却没有足够的护甲可发。那些还在等盔甲锻好的士兵必须小心对练，避免受伤。这就轮到你了——你工程学技艺的名声先你一步传到这里。我需要一些高级假人给新兵使用。你能帮忙吗？",
  },
  [28508] = {
    ["T"] = "给尤尔巴·斯库比格特的委托",
    ["O"] = "尤尔巴·斯库比格特要你使用钓鱼技能收集20条新鲜的光滑大鱼，并把订单交给塔纳利斯热砂港的尤尔巴·斯库比格特。",
    ["D"] = "科赞的财阀头子们说：“别只是坐着等你的船进港。”\n\n好吧，我的船迟到了，而我确实只能坐在这里。所以我想——不如吃点东西。\n\n给我带20条新鲜的光滑大鱼来。它们又大又好吃，还能让我有东西嚼，而不是只嚼自己的紧张。",
  },
  [28536] = {
    ["T"] = "给炼金师匹斯特苏格的委托",
    ["O"] = "炼金师匹斯特苏格要你使用草药学技能采集20株黄金参，并把订单交给塔纳利斯加基森的炼金师匹斯特苏格。",
    ["D"] = "我正在做一些精细又重要的工作，$C。这些异种虫是威胁，如有必要，我会把它们拆到分子层面。但要为我的工作调配合适的药剂，我需要黄金参。这就轮到你了！",
  },
  [28540] = {
    ["T"] = "给派提亚·格罗森的委托",
    ["O"] = "派提亚·格罗森要你使用草药学技能采集20株太阳草，并把订单交给安戈洛环形山马绍尔营地的派提亚·格罗森。",
    ["D"] = "达丹加真是一头勤劳的科多兽，把我们的补给一路从加基森拖来，甚至还吓跑了一些饥饿的迅猛龙。我想奖赏她的付出。\n\n达丹加喜欢太阳草，但我不是草药师。也许你愿意帮我？",
  },
  [28579] = {
    ["T"] = "给安全主管吉罗姆·比格维兹的委托",
    ["O"] = "安全主管吉罗姆·比格维兹要你使用制皮技能制作2条龟壳护腿，并把订单交给塔纳利斯热砂港的安全主管吉罗姆·比格维兹。",
    ["D"] = "你是制皮师？手上的老茧说明了一切。\n\n听着，让我抱怨一下——普通裤子在这里根本不顶用。海盗打得重，太阳晒得更狠。我想要用海龟壳做的裤子。那东西硬得像食人魔的额头。\n\n如果你的制皮技艺够好，就给我做几条龟壳护腿。我需要耐用、灵活，而且能抗海盗的东西。最好按这个顺序。",
  },
  [28604] = {
    ["T"] = "给安全主管吉罗姆·比格维兹的委托",
    ["O"] = "安全主管吉罗姆·比格维兹要你使用制皮技能制作2条龟壳护腿，并把订单交给塔纳利斯热砂港的安全主管吉罗姆·比格维兹。",
    ["D"] = "你是制皮师？手上的老茧说明了一切。\n\n听着，让我抱怨一下——普通裤子在这里根本不顶用。海盗打得重，太阳晒得更狠。我想要用海龟壳做的裤子。那东西硬得像食人魔的额头。\n\n如果你的制皮技艺够好，就给我做几条龟壳护腿。我需要耐用、灵活，而且能抗海盗的东西。最好按这个顺序。",
  },
  [28619] = {
    ["T"] = "给奎因的委托",
    ["O"] = "奎因要你使用剥皮技能收集10块蝎壳，并把订单交给塔纳利斯加基森的奎因。",
    ["D"] = "沙漠不会轻易交出财富。你得流血、灼伤、烤干，才能找到它们。\n\n但蝎壳？那是一种根本不藏起来的珍品。给我带10块蝎壳来，我会告诉你怎样把那些沙漠害虫变成利润。",
  },
  [28652] = {
    ["T"] = "给特伦顿·轻锤的委托",
    ["O"] = "特伦顿·轻锤要你使用采矿技能采集20块秘银矿石，并把订单交给塔纳利斯加基森的特伦顿·轻锤。",
    ["D"] = "精灵挥舞铁匠锤并不常见，而能因此受人尊敬的就更少了。但当我见到鞭笞者苏萨斯时，我知道自己若不学会它的秘密，就永远无法安宁。\n\n为了继续研究，我需要秘银矿石。沙漠中资源丰富，但它绝不是唯一能找到这种矿石的地方。去吧，带着我渴求之物回来。",
  },
  [28693] = {
    ["T"] = "给傲慢的店主的委托",
    ["O"] = "傲慢的店主要你使用裁缝技能制作10卷符文布卷，并把订单交给塔纳利斯热砂港的傲慢的店主。",
    ["D"] = "哦，裁缝！我知道你懂，我根本无法在这种条件下工作。丝绸已经过时，毛料简直悲剧，魔纹布？别逗我笑了。\n\n如果我要在这片被太阳晒白的荒地里做出任何勉强算时髦的东西，就需要像样的材料。给我带十卷符文布来。不要碎布，不要线头，而是完整的布卷，完美无瑕。风格要求牺牲，而我要求符文布。",
  },
  [28718] = {
    ["T"] = "给傲慢的店主的委托",
    ["O"] = "傲慢的店主要你使用裁缝技能制作10卷符文布卷，并把订单交给塔纳利斯热砂港的傲慢的店主。",
    ["D"] = "哦，裁缝！我知道你懂，我根本无法在这种条件下工作。丝绸已经过时，毛料简直悲剧，魔纹布？别逗我笑了。\n\n如果我要在这片被太阳晒白的荒地里做出任何勉强算时髦的东西，就需要像样的材料。给我带十卷符文布来。不要碎布，不要线头，而是完整的布卷，完美无瑕。风格要求牺牲，而我要求符文布。",
  },
  [31003] = {
    ["T"] = "灵魂食粮",
    ["O"] = "请教一位烹饪专家，也许加基森的迪尔格·奎克里弗能帮忙？",
    ["D"] = "",
  },
  [31004] = {
    ["T"] = "灵魂食粮",
    ["O"] = "迪尔格·奎克里弗在加基森怀疑我们没有能力收集蜂蜜黄油面包的材料。\n\n-艾泽拉斯的许多商人出售刚出炉的面包，那是最容易取得的。\n\n-蜂蜜可以在安戈洛的一些黄蜂身上找到。\n\n-黄油可以在希尔斯布莱德丘陵买到。塔伦米尔或南海镇都可以。",
    ["D"] = "",
  },
  [26265] = {
    ["T"] = "奥术清凉",
    ["O"] = "向巴拉丁监狱中的某人学习如何制造魔法晶水，然后把20份魔法晶水带给希利苏斯勇士之墓的纳莱斯·月枝。",
    ["D"] = "你好，$C！我正需要你的帮助。\n\n沙漠干热的天气让人和野兽都口干舌燥。我听说托尔巴拉德的肯瑞托或许有一种特殊方法，可以制造最清爽的晶水。你愿意前往那里，看看能否学会这种做法，好补充我们的储备吗？",
  },
  [26399] = {
    ["T"] = "战斗的召唤：希利苏斯",
    ["O"] = "在希利苏斯找到并杀死5名部落成员。",
    ["D"] = "希利苏斯属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26400] = {
    ["T"] = "战斗的召唤：希利苏斯",
    ["O"] = "在希利苏斯找到并杀死5名联盟成员。",
    ["D"] = "希利苏斯属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [27355] = {
    ["T"] = "受诅者的武备",
    ["O"] = "从南风村内被折磨的哨兵身上收集8件虚灵武备。",
    ["D"] = "南风村曾是卡多雷与异种虫之间一场大战的战场。虽然我们不确定南风村的灵魂为何徘徊不去，但我们知道，他们随身携带着生前使用的武器。这些武器是专为对抗异种虫而铸造的，如果能回收一些，对我们的部队将大有裨益。去南风村，让一些灵魂安息，但把他们的武器带回来。",
  },
  [27356] = {
    ["T"] = "脱离痛苦",
    ["O"] = "杀死南风村废墟内6名被折磨的德鲁伊。",
    ["D"] = "许多年前，在流沙之战期间，我和同伴被派驻在南边一个小村庄里，那里位于安戈洛东部边境。\n\n我们的防线被突破了……村庄失守，许多曾与我并肩作战的人如今仍在痛苦和折磨中游荡。解放他们的灵魂，让他们摆脱这份折磨，继续前行吧。",
  },
  [27357] = {
    ["T"] = "来自过去的报告",
    ["O"] = "从南风村收集3份古代报告。",
    ["D"] = "很久以前，异种虫席卷南风村时，许多无法逃离的人都死在战斗中。但卡多雷军队留下了关键情报，以报告的形式记录了我们如何对抗异种虫。\n\n你愿意替我去南风村，尽可能多地收集它们吗？情报是胜利的关键，而我担心其中也许有些秘密连我们暗夜精灵都已经遗忘。",
  },
  [27358] = {
    ["T"] = "屠灭幽影",
    ["O"] = "杀死塞兰迪尔之影，并把他的精华带给希利苏斯勇士之墓的福里安·贤风。",
    ["D"] = "南风村正深陷不安，$n。有人目击到一位曾经强大的德鲁伊塞兰迪尔的幽影在那里喃喃自语、尖叫不止。据说他一遍又一遍地念着“眼睛来了”。\n\n我的父亲曾与塞兰迪尔并肩作战，为了纪念他，我必须让这位德鲁伊摆脱痛苦。你愿意替我完成这件事吗？",
  },
  [27360] = {
    ["T"] = "水晶调查",
    ["O"] = "佩塔·风痕要你在希利苏斯东北端的5堆水晶上使用精华聚焦器。",
    ["D"] = "就在这里西南方，有一些水晶堆，与更西边的水晶相比明显不同。我需要了解这些水晶的用途，并看看其中是否有能为我们所用的东西。\n\n带上这个聚焦器，试着让它与东北方的水晶堆调谐，然后把它带回来给我。",
  },
  [27361] = {
    ["T"] = "清剿野生动物",
    ["O"] = "扎诺克要你杀死8只掠沙蜘蛛。",
    ["D"] = "当你穿过希利苏斯时，一定遭到过那些把这片土地当家的凶恶蜘蛛袭击。勇士之墓同样不能幸免。\n\n守卫们尽力保护我们的安全，但我们需要有人主动出击，给远征队争取喘息的机会。你愿意帮我们这个忙吗？",
  },
  [27362] = {
    ["T"] = "收集蝎毒",
    ["O"] = "纳塔·鹰歌要你从希利苏斯任意蝎子身上收集8瓶蝎毒。",
    ["D"] = "我们的远征队在希利苏斯面临的挑战之一，就是蝎子的螫刺。它们的毒液强烈而致命，而我们没有足够的样本来制作抗毒剂。\n\n我们人手紧张。如果你愿意帮助我们，从本地蝎子身上收集毒液瓶，那会给我们极大的帮助。",
  },
  [27363] = {
    ["T"] = "虫群",
    ["O"] = "为希利苏斯勇士之墓的阿姆拉斯·月剑捕获6群异种蜂群。",
    ["D"] = "塞纳里奥议会在希利苏斯的工作，给了我一个近距离研究亚基虫族的独特机会。\n\n异种虫有成群的幼年黄蜂，就在这里西边能找到。我本想亲自收集，但目前研究让我无法离开。你愿意替我把它们收集来吗？",
  },
  [27364] = {
    ["T"] = "那些东西……",
    ["O"] = "扎诺克要你杀死10只掘泥打击者。",
    ["D"] = "掘泥虫把希利苏斯当作家园，也是这里可怕生物的又一个例子。它们异常凶暴，会毫不犹豫地发动攻击。\n\n它们尚未逼近勇士之墓，但我不愿冒这个险。我能说服你去削减它们的数量吗？",
  },
  [27365] = {
    ["T"] = "桑德兰的勇士",
    ["O"] = "从灰尘风暴身上收集5份桑德兰精华，然后用它们召唤并杀死桑德兰的勇士。成功后，回到希利苏斯勇士之墓的加鲁德·坚蹄那里。",
    ["D"] = "你听说过驭风者桑德兰吗？他在希利苏斯的重要性不容低估，因为他的许多仆从都在西北方的水晶谷游荡。被称为灰尘风暴的元素生物携带着他的精华，将自身与主人相连。如果有人想削弱这位王子对希利苏斯的掌控，就必须杀死他的仆从，并把这些精华收集起来。等你收集够了，就用它们召唤桑德兰的勇士并杀死它。",
  },
  [27366] = {
    ["T"] = "禁忌，还是遗失？",
    ["O"] = "为希利苏斯勇士之墓的阿姆拉斯·月剑收集一块暮光石板。",
    ["D"] = "暮光之锤曾在希利苏斯西北端有一处营地，前些时候被摧毁了。原因和经过可以以后再说，但现在最有意思的是，我们可能有机会收集他们当时在营地里掌握的情报。我希望他们对亚基虫族、其拉虫人和异种虫有更深的了解。\n\n如果你到了那片被毁的营地附近，愿意四处看看，找找能发现什么吗？当心可能潜伏在阴影中的信徒。",
  },
  [27367] = {
    ["T"] = "风中的尘埃",
    ["O"] = "为希利苏斯勇士之墓的萨希亚·林冠杀死8个灰尘风暴。",
    ["D"] = "这片土地上到处都有被称为灰尘风暴的空气元素，不过它们似乎在遥远西方、水晶谷以南最为集中。它们是狂怒的元素，会制造影响整个希利苏斯的危险沙暴。\n\n减少它们的数量非常重要。如果你打算代表我们去对付它们，请务必小心，并带上盟友。",
  },
  [27368] = {
    ["T"] = "隆隆作响的奔行者",
    ["O"] = "为希利苏斯勇士之墓的萨希亚·林冠杀死6个沙漠奔行者。",
    ["D"] = "众所周知，暮光之锤教派会召唤土元素，为他们的黑暗勾当效力。水晶谷内就有几个被召唤出来后留在那里肆虐大地的元素。\n\n勇士远征队人手紧张，所以只能依靠你这样的英雄来处理这些横冲直撞的元素威胁。拜托了，$n，召集你的冒险者同伴，削减它们的数量。",
  },
  [27369] = {
    ["T"] = "小到能带走",
    ["O"] = "为希利苏斯勇士之墓的佩塔·风痕，从水晶谷收集8块希利苏斯水晶碎片。",
    ["D"] = "希利苏斯西北部有个地方叫水晶谷，离这里很远。那里的水晶比别处更多。我们的斥候报告说，水晶正在生长，而且在那些大得多的水晶附近，可以找到“幼年”水晶。\n\n你能替我取回一些幼年水晶样本吗？",
  },
  [27370] = {
    ["T"] = "到底在复仇什么？",
    ["O"] = "为希利苏斯勇士之墓的萨希亚·林冠杀死8名暮光复仇者。",
    ["D"] = "异种虫不是这片土地上唯一的危险。我们的工作还受到暮光之锤教派的干扰，他们派出了那些所谓的“复仇者”，不过我并不知道他们到底在复仇什么。\n\n我请求你召集同伴，袭击他们，削减他们的数量。不过一定要小心。他们绝不可轻视。",
  },
  [27371] = {
    ["T"] = "教派计划",
    ["O"] = "从希利苏斯任意暮光之锤营地找回3套教派计划。",
    ["D"] = "盯紧敌人的行动只是我在远征队任务中的一项，但我最近受伤后无法履行职责。我的任务原本是潜入暮光之锤的营地，尽可能了解他们的计划。\n\n你愿意替我承担这项任务吗？找到他们的任意营地，把他们的计划带给我。",
  },
  [27373] = {
    ["T"] = "好读物",
    ["O"] = "从希利苏斯任意暮光之锤信徒身上取得5份暮光文稿。",
    ["D"] = "今天似乎人人都忙着思考暮光之锤教派，但没人知道他们那些该死行径的动机。想了解一个教派，只需要读读他们无聊的文献。我打赌教派成员身上有些情报，能帮助我们更好地理解这个组织的结构，以及该如何对付它。\n\n如果你近期要和信徒作战，记得花点时间查看他们身上有没有能帮助我们理解情况的文字。萨希亚也许能从中得到有用的东西。",
  },
  [27374] = {
    ["T"] = "不要旧神，也不要暮光主宰",
    ["O"] = "为希利苏斯勇士之墓的米莱斯·雾刃杀死6名暮光主宰。",
    ["D"] = "希利苏斯正在举行黑暗仪式，折磨逝者的灵魂，也侵扰我们这些活人。负责这些亵渎行径的，正是暮光之锤那些所谓的“主宰”。\n\n曾经我会亲自承担责任，追猎并杀死他们，但我必须留在这里维持防御。你愿意代我行动，打击那些自称暮光之锤主宰的人吗？",
  },
  [27376] = {
    ["T"] = "饿死它们",
    ["O"] = "在佐拉虫巢焚烧10堆肉，然后回到希利苏斯勇士之墓的扎诺克那里。",
    ["D"] = "异种虫依靠它们猎杀野生动物后堆成的巨大肉堆生存。我曾建议萨希亚让守卫找到并烧毁虫群的食物补给，但她认为风险太大。我并非不同意，可我们不能任由虫群无止境地壮大。\n\n如果我把火炬给你，你愿意去佐拉虫巢点燃它们的食物补给吗？",
  },
  [27377] = {
    ["T"] = "蜂巢",
    ["O"] = "在佐拉虫巢杀死8只佐拉巨蜂，然后回到希利苏斯勇士之墓的扎诺克那里。",
    ["D"] = "有人在佐拉虫巢目击到数量惊人地庞大的异种蜂群。这些不是普通黄蜂，出现这种规模，说明我们可能很快就会遭到攻击。\n\n我相信异种虫在集结力量时，不会预料到先发制人的反击。我们在这里维持防御，而你和你的同伴可以袭击佐拉虫巢的巨蜂，削减它们的数量。",
  },
  [27378] = {
    ["T"] = "道路守望者",
    ["O"] = "在佐拉虫巢杀死6名佐拉守卫，然后回到希利苏斯勇士之墓的萨希亚·林冠那里。",
    ["D"] = "远征队正处于高度戒备，而且理由充分。异种虫太危险了，我们不能让它们取得任何立足点。为此，如果你有意帮忙，可以把战斗带到佐拉虫巢的守卫那里。削减它们的数量后，虫群的协调能力会受到影响，让我们能加强对通往希利苏斯道路的控制。\n\n也许到那时萨希亚就能喘口气，我们也能重新投入工作。",
  },
  [27379] = {
    ["T"] = "达莱的报告",
    ["O"] = "在佐拉虫巢找到达莱·月枝，为希利苏斯勇士之墓的萨希亚·林冠取得她的报告。",
    ["D"] = "达莱出发去侦察佐拉虫巢了。这里的局势很微妙，我们需要尽早取得她的报告，才能抢在异种虫威胁前面行动。考虑到虫巢可能在我们不知情时动员起来，我必须让远征队守卫留在附近。\n\n你能在虫巢里找到达莱，并从她那里取得报告吗？",
  },
  [27380] = {
    ["T"] = "主宰啊！",
    ["O"] = "从雷戈虫巢的雷戈主宰身上取得3个脑子，然后回到希利苏斯勇士之墓的阿姆拉斯·月剑那里。",
    ["D"] = "雷戈虫巢由一种被称为主宰的异种虫控制。它们位于阶级顶端，尽管仍然服从其拉虫人主人。我一直在研究各种不同异种虫的脑子，通过比较来更好地理解它们如何运作。\n\n远征队守望者没能取回主宰脑子的样本。你愿意帮我弄一些来，协助我的研究吗？",
  },
  [27381] = {
    ["T"] = "碾碎虫子",
    ["O"] = "在雷戈虫巢杀死6只雷戈掘洞者，然后回到希利苏斯勇士之墓的萨希亚·林冠那里。",
    ["D"] = "雷戈虫巢里有一种异种虫会在地下挖掘并打通隧道，为其他异种虫开辟路径。无论我们在这里准备什么防御，都可能被这些生物从下方破坏！\n\n我们的守望者仍在密切看守勇士之墓，否则他们早就出去处理这些东西了。我能把这项任务托付给你吗？",
  },
  [27382] = {
    ["T"] = "迫在眉睫的解放",
    ["O"] = "在雷戈虫巢杀死5只雷戈制奴者，然后回到希利苏斯勇士之墓的玛斯卡·驭烬那里。",
    ["D"] = "你见过为异种虫效力的奴隶吗，$n？我没有。不过，有报告称雷戈虫巢的一些异种虫能控制粗心士兵的心智。这些生物被称为“制奴者”。至于这些制奴者把它们“制造”的奴隶带到哪里，我永远不会知道。我只知道，为了我们自己，我们必须消灭这些异种虫。如果你是来帮我们的，就杀死你发现的任何制奴者，并小心别让自己也被奴役。",
  },
  [27383] = {
    ["T"] = "更像是酸液",
    ["O"] = "从雷戈虫巢的雷戈喷火者身上取得5份酸性唾液样本，然后回到希利苏斯勇士之墓的纳塔·鹰歌那里。",
    ["D"] = "这一次，我关注的不是制作抗毒剂。无论我怎么做，似乎都无法有效抵消雷戈虫巢某些异种虫用来溶解敌人护甲的酸性唾液。如果你到了雷戈虫巢附近，愿意从那里的“喷火者”身上收集唾液样本吗？",
  },
  [27384] = {
    ["T"] = "直击核心",
    ["O"] = "把发光的种子放在雷戈虫巢的核心，然后回到希利苏斯勇士之墓的莱耶·星击那里。",
    ["D"] = "行动的时刻到了，$n。趁异种虫试图重新集结，我们需要对它们的一处虫巢采取行动，扰乱它。在我手中有一粒蕴含不稳定力量的种子，一旦种下，就会迅速且不受控制地生长。你愿意帮助我们，找到雷戈虫巢的核心，并把种子种在它的中心吗？",
  },
  [27385] = {
    ["T"] = "镇压工蝎",
    ["O"] = "在亚什虫巢消灭6只亚什工蝎，然后回到希利苏斯勇士之墓的萨希亚·林冠那里。",
    ["D"] = "亚什虫巢由雄蝎或者说工蝎运转，它们负责虫巢周围的日常杂务。虽然它们不像其他异种虫那样好战，却能确保虫巢继续产出更危险的异种虫。我派出的远征队守望者原本要尽可能消灭这些雄蝎，但遗憾的是，有几人在虫巢中丧生。我不能再派更多人去完成他们的任务。\n\n你愿意冒险进入亚什虫巢，击倒相当数量的工蝎，完成那些倒下守望者未竟的任务吗？",
  },
  [27386] = {
    ["T"] = "砸碎虫卵！",
    ["O"] = "在亚什虫巢砸碎10枚异种蝎卵，然后回到希利苏斯勇士之墓的加鲁德·坚蹄那里。",
    ["D"] = "如果我们要遏制虫群的增长，就应该追溯源头。我们不太可能找到唯一的育母，但我知道亚什虫巢到处都是虫卵。假设有一队冒险者前往那里，把它们砸成糊状，将来就会有更少异种虫来补充它们的数量。",
  },
  [27387] = {
    ["T"] = "从毒蝎取毒刺",
    ["O"] = "在亚什虫巢从亚什毒蝎身上取得5根亚什毒刺，然后回到希利苏斯勇士之墓的纳塔·鹰歌那里。",
    ["D"] = "亚什虫巢的毒蝎拥有强效毒液，与其他异种虫注入的毒液相比尤其致命。守望者失败之后，我担心如果不先研制出解毒剂，我们还没有准备好对付它们。\n\n如果你下到那里，能不能从那些……毒蝎身上收集一些毒刺？从亚什毒蝎身上取亚什毒刺。这样说合理吗？",
  },
  [27388] = {
    ["T"] = "找回遗失物资",
    ["O"] = "从亚什虫巢找回3份勇士之墓补给，然后回到希利苏斯勇士之墓的米莱斯·雾刃那里。",
    ["D"] = "随着虫群攻击勇士之墓的大部分威胁减弱，萨希亚趁机袭击亚什虫巢，试图削弱它们，为远征队争取更多时间。许多守望者在虫巢中作战，但被迫撤回这里。我们在战斗中失去了大量补给和武备。你愿意去虫巢看看能找回什么吗？",
  },
  [27389] = {
    ["T"] = "就一个？",
    ["O"] = "杀死亚什虫巢的亚什虫巢主宰，然后回到希利苏斯勇士之墓的达莱·月枝那里。",
    ["D"] = "每个异种虫巢的运作方式都不相同。以亚什虫巢为例，它们的领导权集中在一个直接统治虫巢的主宰身上。萨希亚派远征队守望者去消灭它，但我担心他们没有成功。\n\n虫巢动员的威胁仍然非常真实，而且不太可能再派出另一支远征队。拜托了，$n，召集其他冒险者，消灭亚什虫巢的主宰。",
  },
  [27515] = {
    ["T"] = "希利苏斯小吃",
    ["O"] = "把5块从希利苏斯沙虫身上取得的沙虫的肉带给安戈洛环形山沼泽地的莫维克。",
    ["D"] = "我训练的暴掠龙最终会和它们的主人一起环游世界。为了帮助它们适应，我会确保它们接触各种各样的肉类。\n\n西边是一片名叫希利苏斯的危险土地。栖息在那片贫瘠荒地上的巨大沙虫有一种辛辣、干燥的肉质，与毒皮幼崽习惯吃的东西很不一样。我想在它们成长时，把这种肉加入它们的食谱。\n\n从这些沙虫身上收集五块肉，但要小心，它们是强大的敌人，可能需要一支队伍才能击倒。",
  },
  [27990] = {
    ["T"] = "实验室仪式",
    ["O"] = "从希利苏斯的空气元素身上取得10块精炼玻璃碎片。把玻璃和一块奥金锭带给逆风小径的埃瑞丁·埃利斯。",
    ["D"] = "杜安的主要难题，是为这些药剂混合后产生的强效混合物寻找合适容器。普通水晶瓶会开裂，甚至爆炸！真惊人！\n\n不过，我有个想法。我读到过一片名叫希利苏斯的遥远土地。空气元素在那片土地上游荡，并卷起细密的远古沙砾。古代暗夜精灵记录显示，这些元素会在自身汹涌的内部，将这些沙砾旋成极其坚固的玻璃碎片。\n\n什么？我读书很多。\n\n我知道前往卡利姆多远端是一段漫长旅程，但这是我们最好的选择。杀死这些元素，直到我们有足够的玻璃制作自己的大师级药瓶——哦，我们还需要一块奥金锭来加固玻璃，不过对你这种技艺的人来说应该不成问题。",
  },
  [27995] = {
    ["T"] = "熔炉仪式",
    ["O"] = "与希利苏斯铜须营地的布莱恩·铜须谈谈。",
    ["D"] = "我最初得知这种材料，是因为一次偶然遇见探险家布莱恩·铜须。他答应调查我提出的几个问题，但我上一封信一直没有收到回复。\n\n你看起来能应付危险局面。我研究死灵之刃的时候，希望你前往卡利姆多远端的希利苏斯。铜须写信说，他会在那里扎营，研究某个矮人历史发现。去取得我那些问题的答案，然后回到这里找我。",
  },
  [27996] = {
    ["T"] = "熔炉仪式",
    ["O"] = "在希利苏斯杀死石行蜘蛛，直到找回布莱恩上锁的箱子。把箱子和一把奥金万能钥匙带给荆棘谷藏宝海湾的马克迦文。",
    ["D"] = "我们扎营后有一阵子，蜘蛛爬进我们东西里，真是个大麻烦。我们会把它们吓跑，但其中几只用黏糊糊的蛛网带走了我们的一些私人物品！\n\n布莱恩把他关于那种金属的所有笔记都放在一个上锁的盒子里。最后一次看见那个盒子时，它挂在一只石行蜘蛛背上，正从营地匆匆逃走。我估摸着，只要你杀够多，就能找到盒子和笔记。\n\n当然，布莱恩不在这里，没法打开盒子，所以你需要一把奥金万能钥匙来办这事。不过既然你是铁匠，我估摸着这对你应该不成问题。",
  },
  [28014] = {
    ["T"] = "奥术仪式",
    ["O"] = "为奥特兰克山脉拉文霍德庄园的费莉希蒂，从希利苏斯的暮光信徒身上收集一副暮光信徒手套。",
    ["D"] = "虽然你拥有大师级附魔技能，但不能赤手空拳解除这个雕文。不，你需要一副特殊手套，否则你可能会失去手上所有皮肤……嗯，我就不展开讲细节了。\n\n不过别怕，我已经找到了适合这项任务的手套。你只需要去取得一副。从暮光信徒那里。在希利苏斯。我听说那里每年这个时候很宜人！等你完成这件事，我有百分之九十三的把握，我们就差不多准备好移除雕文了。",
  },
  [28047] = {
    ["T"] = "山脉仪式",
    ["O"] = "为安戈洛环形山马绍尔营地的雅卢妮·炎望，从希利苏斯采集10块嗡鸣矿石。",
    ["D"] = "马绍尔远征队并不是唯一一群进入卡利姆多这一带的探险者。还有一支塞纳里奥议会队伍从这里继续前进，进入了一片名叫希利苏斯的沙漠。我们从他们那里听到的消息稀少而零散，但他们送来的一条消息提到，那里到处都是愤怒的亡灵和嗡鸣的虫巢。\n\n我很好奇，那里远离诅咒之地的大地，是否也显露出同样的愤怒？我能感觉到有东西从那个方向散发出来，但我与火焰的联系远强于大地。如果你能从希利苏斯给我带回一些样本，也许我能占卜出更多。",
  },
  [28052] = {
    ["T"] = "荒野仪式",
    ["O"] = "赫米特·奈辛瓦里要你使用剥皮技能，从希利苏斯的掘泥虫身上收集6张掘泥虫皮，并把它们带给荆棘谷营地中的他。",
    ["D"] = "说到这下一个任务，我还有点嫉妒你。遥远西方发现了一片新土地，叫希利苏斯。显然，我们的买家得到消息，说那里有些生物身上能找到异域皮革。他把它们描述成“像虫子一样”。\n\n我很感兴趣，甚至想亲自去，但在能动身之前，我还有谷地里的工作要完成。更别提这个希利苏斯地方显然极其危险。不过，如果猎人不时不时考验自己，那还算什么猎人？",
  },
  [26297] = {
    ["T"] = "配得上国王",
    ["O"] = "从灼热峡谷内的土元素和火元素身上收集旋熔岩石和灼热火焰精华。",
    ["D"] = "我们离最终打造这把王者之武已经不远了。现在的瓶颈很简单：制造并维持足够的热量。这里的熔炉很适合生产食人魔通常喜欢用的低劣货色，但温度还不足以熔炼这些合金并把它们与铁结合。\n\n不幸的是，这意味着热量必须送到我们这里来。在遥远东方，东部王国中，你会找到灼热峡谷。\n\n那地方熔岩流淌，岩石熔化，元素横行。我需要你收集它们的炽热精华，并把它们带给我。\n\n有了这些精华，我就能强化这座熔炉，让它满足我们的需求。",
  },
  [26391] = {
    ["T"] = "战斗的召唤：灼热峡谷",
    ["O"] = "在灼热峡谷找到并杀死5名部落成员。",
    ["D"] = "灼热峡谷属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26392] = {
    ["T"] = "战斗的召唤：灼热峡谷",
    ["O"] = "在灼热峡谷找到并杀死5名联盟成员。",
    ["D"] = "灼热峡谷属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26852] = {
    ["T"] = "卡加斯被盗的补给",
    ["O"] = "从灼热峡谷大熔炉和熔渣之池的黑铁矮人那里找回8箱被盗的部落补给。",
    ["D"] = "我接到消息，灼热峡谷的黑铁矮人一直在偷拿我们空投的部分补给。我们需要这些补给来维持在荒芜之地的立足点。\n\n从卡加斯南边的隘口向西走，你会在灼热峡谷中央找到大熔炉和熔渣之池里的黑铁矿井。尽可能多地找回那些补给箱。",
  },
  [26854] = {
    ["T"] = "暮光战术",
    ["O"] = "在灼热峡谷西北部的暮光营地杀死8名暮光火焰卫士和8名暮光地占师。",
    ["D"] = "瑟银兄弟会听说暮光之锤派使者去黑石山影铸城找我们的兄弟。这些拉格纳罗斯的仆人想为早已沉睡的古老力量寻找盟友，瑟银兄弟会绝不允许他们在灼热峡谷站稳脚跟！\n\n杀掉这些信徒，终结他们肮脏的仪……*嗝*……仪……*嗝*……仪式。",
  },
  [26855] = {
    ["T"] = "暮光战术",
    ["O"] = "搜索灼热峡谷西北部的暮光信徒洞穴，找到一座仪式祭坛，并取回从影铸城偷走的索瑞森遗物。",
    ["D"] = "很久以前，我们皇帝索瑞森的祖先通过可怕的魔法把拉格纳罗斯带到了这里。*嗝* 我担心暮光之锤可能想再次唤醒他。\n\n他们在影铸城的使者偷运出了一件曾属于巫王索瑞森的遗物。我不知道他们打算拿它做什么……*嗝*……但我相信它被存放在洞穴里的仪式地点。我需要你潜……*嗝*……调……*嗝*……取回这件遗物。",
  },
  [26856] = {
    ["T"] = "暮光战术",
    ["O"] = "打断暮光使者莫加利和监工韦夫特之间的会面，并取回他们可能携带的任何文件。",
    ["D"] = "我的情报显示，暮光之锤的一名使者会在附近和大熔炉的一名监工会面。我们必须打断这场会面，并取回那些叛徒身上的任何文件。\n\n根据我的情报，会面地点在黑炭谷附近，就在这里东南方，靠近黑石山入口。没时间浪费了，$C！*嗝*",
  },
  [26859] = {
    ["T"] = "腐化的元素",
    ["O"] = "在灼热峡谷，从泥浆元素身上收集腐化水之核心，从地狱元素身上收集腐化火焰核心，从熔岩元素身上收集腐化大地核心，从烟雾元素身上收集腐化空气核心。",
    ["D"] = "小心，$R。这是一片愤怒的土地。两百年前创造黑石山的剧变，或许已经把这里的元素力量腐化得面目全非。\n\n我担心拉格纳罗斯现身造成的创伤，正渗入峡谷本地的元素之中。我需要有人从每一种元素身上收集核心，并把它们带回这里给我，同时我会准备研究用品。那个人会是你吗？",
  },
  [26864] = {
    ["T"] = "奴隶贩子会留记录吗？",
    ["O"] = "取得奴隶贩子记录，然后回到灼热峡谷的布林德·烈酒炉那里。",
    ["D"] = "我们来到这里，是因为一个对我家族非常重要的人被奴隶贩子带走了，我们想把她救回来。你知道大熔炉那些奴隶贩子吧？我打赌他们有某种文件，记录着他们把一些奴隶怎么处理了。\n\n看看能不能从他们尸体上找到什么给我。",
  },
  [26865] = {
    ["T"] = "老爹的推测",
    ["O"] = "找到灼热峡谷西北部的会面地点。杀死使者，把任何奴隶贩子记录带回给老爹·烈酒炉。",
    ["D"] = "<老爹透过皱起的浓眉看着你。>\n\n暮光之锤。以前见过他们在西北边和奴隶贩子会面。俺打赌他们很快又要见面。杀了他们，看看他们给我们留下些什么。\n\n<老矮人若有所思地抚摸着胡须。>",
  },
  [26866] = {
    ["T"] = "蕾莎",
    ["O"] = "在观火岭救出蕾莎，然后回到灼热峡谷的布林德·烈酒炉那里。",
    ["D"] = "西北边的观火岭有个洞，里面到处都是暮光之锤。我敢打赌那些混蛋把蕾莎囚禁在那里，等着献祭她！或者更糟……！\n\n去那边的洞穴放她自由！等我确定我一离开奴隶贩子不会抓走老爹，就会赶上你。",
  },
  [26867] = {
    ["T"] = "高级审讯官",
    ["O"] = "在黑石深渊杀死审讯官格斯塔恩，然后回到灼热峡谷的老爹·烈酒炉那里。",
    ["D"] = "<老爹看着你，露出你只能理解为满意的表情。>\n\n你干得不错。蕾莎正在恢复。她回城前，把一整本书那么多的事告诉了我和我儿子。简单说，黑石深渊的拘禁区里有个怪物。她想除掉那家伙，但以她现在的状态做不到。她似乎很相信你能办到。名字叫格斯塔恩，是个人类。\n\n你怎么说？完成蕾莎的工作，然后拿报酬。",
  },
  [26868] = {
    ["T"] = "老爹·烈酒炉",
    ["O"] = "在灼热峡谷西南部的营地找到老爹·烈酒炉。",
    ["D"] = "老爹·烈酒炉很老了，即使以矮人的标准也是如此。他是一名铸造大师，加入瑟银兄弟会的时间比我们所有人能记得的都久。\n\n最近他和儿子布林德一起往南去了。他不肯告诉我们原因，但举止怪得很。你为什么不去看看，他做的事需不需要帮忙？",
  },
  [27932] = {
    ["T"] = "品尝佳酿",
    ["O"] = "与吉温娜·火酒、特鲁克·蛮鬃和侦查队长洛洛尔谈谈，品尝他们的佳酿。",
    ["D"] = "好吧，$C。如果我听起来有点自以为是，请原谅，但我敢打赌你还没培养出品味上等矮人酿酒的舌头。要想真正品尝我计划中的佳酿，你得先润润喉咙！\n\n众所周知，我们矮人给小崽子断奶靠的就是好烈酒！其他种族练出来的那点酒量根本比不上我们。我可不想用自己的酒把你灌死，所以把这当成必要步骤吧！\n\n我列了几位朋友，他们会让你尝尝他们最好的酒。首先，和我这边旅店里的美丽山花吉温娜谈谈……她会用我自己的拉格啤酒招待好你。\n\n接下来去哪由你决定，但去辛特兰鹰巢山找特鲁克·蛮鬃，再去灼热峡谷瑟银哨塔找侦查队长洛洛尔。这两位酿的酒劲头可不小，我跟你说！\n\n干杯，$N！",
  },
  [28539] = {
    ["T"] = "给监工斯克兰格的委托",
    ["O"] = "监工斯克兰格要你使用草药学技能采集20株火焰花，并把订单交给灼热峡谷瑟银哨塔的监工斯克兰格。",
    ["D"] = "工作就是工作，$C。不是享乐。而我给你准备了一份完美的枯燥差事。\n\n我需要火焰花。一大堆。出去给我弄些火焰花来，别敢享受这个过程！",
  },
  [28623] = {
    ["T"] = "给大铁匠博恩奈特的委托",
    ["O"] = "大铁匠博恩奈特要你使用剥皮技能收集20块硬甲皮，并把订单交给灼热峡谷瑟银哨塔的大铁匠博恩奈特。",
    ["D"] = "我们撤出影铸城时，留下了一半储备：工具、装备，还有好皮革。结果证明，靠回忆可没法制作东西。\n\n如果你想在这里帮忙，就给我带20块硬甲皮来。我会处理那些丢失物资的替代品。抱怨没用。干活吧。",
  },
  [28655] = {
    ["T"] = "给大铁匠博恩奈特的委托",
    ["O"] = "大铁匠博恩奈特要你使用采矿技能采集10块黑铁矿石，并把订单交给灼热峡谷瑟银哨塔的大铁匠博恩奈特。",
    ["D"] = "我们放弃影铸城时，不得不把熔炉、工具……还有所有补给都留在那里。\n\n现在我们正在这里重建，我需要一名熟练矿工的帮助。给我带10块黑铁矿石来。如果我们要重拾力量，一切都要从火与金属开始。",
  },
  [8965] = {
    ["T"] = "重要的材料",
    ["O"] = "取得放逐者的灵魂灰烬，并把它们带回黑石山内的伯德雷。",
    ["D"] = "$C，仔细听。既然我们已经有了火盆，也有了点燃它的手段，我们还需要另一种材料来灌注其中；某种能提供足够强大焦点、引来我那已故前战友之灵的东西。\n\n一名曾与我们同行的食人魔通灵师库尔莫克，过去很喜欢召唤希尔斯布莱德丘陵南部海岸外赎罪岛上那些被放逐死者的灵魂。去那里，从他们的遗骸中取回一些放逐者的灵魂灰烬。",
  },
  [8984] = {
    ["T"] = "真相大白",
    ["O"] = "在希尔斯布莱德丘陵，越过拉文霍德庄园，找到药剂师斯塔弗隆·雷伦特。",
    ["D"] = "听着，一个叛逃药剂师的行为不是我关心的事。如果他在破坏我们的努力，那就让我第一个给你指明方向。\n\n如果他是清白的，那他就没什么可隐瞒，对吧？\n\n这些货物是我从药剂师斯塔弗隆·雷伦特那里买来的。他在拉文霍德庄园后方、希尔斯布莱德上方山中的一处隐蔽地点工作。老实说，我觉得他有点古怪。",
  },
  [8988] = {
    ["T"] = "更多重要的材料",
    ["O"] = "取得放逐者的灵魂灰烬，并把它们带回黑石山内的伯德雷。",
    ["D"] = "$C，仔细听。既然我们已经知道了最后一块护符碎片的位置，我们还需要另一种材料来灌注火盆；某种能提供足够强大焦点、引来我那已故前战友之灵的东西。\n\n一名曾与我们同行的食人魔通灵师库尔莫克，过去很喜欢召唤希尔斯布莱德丘陵南部海岸外赎罪岛上那些被放逐死者的灵魂。去那里，从他们的遗骸中取回一些放逐者的灵魂灰烬。",
  },
  [26327] = {
    ["T"] = "进入炼狱",
    ["O"] = "找到布莱克斯通船长过去的船员，了解他们对帕雷斯之眼来源的说法。",
    ["D"] = "$C，你现在被一只帕雷斯之眼束缚着，它所受的诅咒比把这座岛上的居民困在炼狱中的魔法更强——而我们则因在南海镇拘留营中虐待他人所扮演的角色，被圣光束缚在此。\n\n布莱克斯通船长选择这座岛来藏匿他的宝藏，并非偶然。他在被招募进南海镇私掠舰队前，受了许多年苦。作为赎罪的一部分，由我们看守他的宝藏倒也合适。这个故事本不该与你有任何关系，但你现在已经深陷其中。如果你不想让他的错误支配你的人生，就必须解开布莱克斯通未能解开的诅咒。\n\n我不知道这只眼睛如何落入布莱克斯通手中的细节，但我相信，你必须追溯它的源头，才能打破把它与你相连的诅咒。布莱克斯通带着三名船员来到这座岛。如果你不想像布莱克斯通那样屈服于疯狂，就去找他们吧。",
  },
  [26335] = {
    ["T"] = "斯图尔的复仇",
    ["O"] = "查明洛林·雷姆卡是生是死。",
    ["D"] = "正如我告诉你的，我父亲牺牲了自己的生命，让布莱克斯通和其余兽人船员免于囚禁。在我父亲麾下航行的兽人来自拘留营征召，南海镇私掠舰队被凿沉后，他们又被送回那些营地。我父亲请求释放他们，却遭到审判者塞尔格拉姆和监工洛林·雷姆卡拒绝。\n\n塞尔格拉姆已经死了有一段时间，但我相信雷姆卡还活着。如果她当初肯听理性之言，我父亲就不会觉得必须把兽人从营地里劫出来，也不会因此丧命。我的良心无法安宁，除非她为他的死付出代价，但我不知道她如今在哪里。\n\n雷姆卡曾把一名女性兽人当作私人奴隶。她的名字叫格里基克。雷姆卡在营地里还有一名随员，名叫瓦里克。我也不知道这两人是否还活着，但如果你能找到其中任何一人，也许就能追查到雷姆卡的下落。",
  },
  [26476] = {
    ["T"] = "暗影斗篷",
    ["O"] = "向拉文霍德庄园的卡尔鲁·奥瑞留斯报到。",
    ["D"] = "$C，是时候让你踏上旅程的下一步，学习一门曾拯救许多$C免于死亡的技艺了。我收到了来自希尔斯布莱德丘陵拉文霍德庄园的消息。\n\n这相当罕见，因为庄园里的居民是一个非常隐秘的组织。你是否已经给某些阴影中的人物留下了印象？在明火上阅读那封送来的信，然后按指示出发。",
  },
  [26506] = {
    ["T"] = "斯坦恩布莱德信使",
    ["O"] = "找到并拦截往返于敦霍尔德城堡和斯坦恩布莱德之间的辛迪加信使。",
    ["D"] = "<拉文霍德领主叹了口气。>\n\n所以辛迪加已经扩张到希尔斯布莱德了。我原本希望在他们继续伸手之前，完成自己对其起源的调查，但我的资源已经捉襟见肘。如果你能协助这项工作，那对我和你在南海镇的主人都有好处。\n\n我收到的最后一份实地报告说，有一名信使定期从敦霍尔德城堡前往斯坦恩布莱德。这名信使沿河而行，而不是走大路。\n\n拦截信使，把他们的消息带给我。",
  },
  [26512] = {
    ["T"] = "匹瑞诺德遗产",
    ["O"] = "前往南海镇，询问镇史学家昆迪瑞克·赞德恩是否知道一名叫哈斯的人，以寻找哈斯将军。",
    ["D"] = "哈斯将军曾是奥特兰克军队的领袖。他从一开始就反对艾登国王与部落勾结。他是个好人，也是更好的军人。\n\n如果他还活着，我想他已经找到了融入当地居民的方法。试试南海镇吧——我想他们那里有位镇史学家也许能帮忙。",
  },
  [26521] = {
    ["T"] = "阿古斯之醒",
    ["O"] = "杀死4名阿古斯暗影大法师，然后把阿古斯之醒的情报带回塔伦米尔的克鲁斯克那里。",
    ["D"] = "奥里登·匹瑞诺德和我谈话时提到，辛迪加已经招募了强大的盟友来支持他们的事业。一个我从未听说过、名叫阿古斯之醒的组织派来了暗影法师，还有一名叫纳伽兹的兽人协助他。我不知道纳伽兹在哪里，但那些暗影法师在斯坦恩布莱德和高地一带游荡。杀掉他们中的一些，然后把这个情报带回给克鲁斯克。",
  },
  [26522] = {
    ["T"] = "阿古斯之醒",
    ["O"] = "在奥特兰克山脉的达伦德农场杀死纳伽兹，并把他的头颅带给希尔斯布莱德丘陵塔伦米尔的克鲁斯克。",
    ["D"] = "如果辛迪加与燃烧军团结盟，局势就比我怀疑的更加严重。大酋长会希望我们采取行动。\n\n这个纳伽兹一定离奥里登·匹瑞诺德领主很近。我们的情报显示，匹瑞诺德在湖边一座庄园里的达伦德农场。去那里找到纳伽兹，把他的头带给我。",
  },
  [26523] = {
    ["T"] = "附有魔法的羊皮纸",
    ["O"] = "把附有魔法的羊皮纸带给希尔斯布莱德丘陵塔伦米尔的克鲁斯克。",
    ["D"] = "在纳伽兹的尸体上，你找到一张羊皮纸，表面闪烁着奥术符文，扭曲文字使其无法阅读。塔伦米尔的克鲁斯克会想知道这件事。",
  },
  [28009] = {
    ["T"] = "奥术仪式",
    ["O"] = "与希尔斯布莱德丘陵塔伦米尔的大法师沃迪恩·伍德格莱尔谈谈。",
    ["D"] = "啊，$N！自你初学这门手艺以来，你的附魔技能已经成长了许多。我很欣赏！事实上，我非常欣赏，所以想推荐你去做一份工作。\n\n大法师沃迪恩·伍德格莱尔派人到幽暗城寻找一名大师级附魔师。我不想离开城市，但你拥有更……冒险的精神。绝不是鲁莽，别混淆了！\n\n搭蝙蝠去塔伦米尔会直接把你带到大法师那里。我很好奇他想要什么。大法师很少请求帮助。",
  },
  [28443] = {
    ["T"] = "给西蒙尼·坎提瑞尔的委托",
    ["O"] = "西蒙尼·坎提瑞尔要你使用工程学技能制作1副超聚焦护目镜，并把订单交给希尔斯布莱德丘陵拉文霍德庄园的西蒙尼·坎提瑞尔。",
    ["D"] = "我很惊讶，像拉文霍德领主这样的人类竟然会有园艺眼光，但他这里的花园确实有成为杰作的基础。真正能帮上我的，是一副超聚焦护目镜，好让我专注观察枝叶的细节。你碰巧知道我在哪里能弄到一副吗？",
  },
  [26126] = {
    ["T"] = "弹簧座鳗鱼",
    ["O"] = "把10条新鲜的弹簧座鳗鱼带给弹簧座的齐莫。",
    ["D"] = "信不信由你，弹簧座的钓鱼活动相当活跃！虽然真正参与这项运动的只有我一个，但我毫不怀疑其他人迟早会加入。不管怎样，如果你愿意接受，我这里有个挑战给你。\n\n这片池塘的水来自地下深处的天然洞穴系统。下面的鱼都是瞎的，偶尔会向上游，来到地表。我零零散散只钓到过几条，但它们绝对是我吃过最美味的鱼！\n\n你应该试试钓鱼，看看能不能钓到几条。如果你运气不错，就把它们带给我，我会教你怎么烹饪。",
  },
  [26282] = {
    ["T"] = "旧债",
    ["O"] = "在微光泥沼矿井内找到并杀死监工格里姆加什。",
    ["D"] = "你看起来像是那种有进取心、愿意接活又不问太多问题的人。正是我一直在找的类型。\n\n我定居弹簧座以前，曾经有自己的生意，把货物从一个地方运到另一个地方。那时候我有个“搭档”，帮忙……打点海关和文书上的麻烦。后来风险投资公司跑来把他们从我手底下挖走，整个营生就垮了。我被困在这片沙漠里！\n\n虽然后来事情也算过得去，但地精可不会忘记这种仇。我得留在这里照看自己的事业，不过如果你愿意去微光泥沼矿井拜访一下监工格里姆加什，我会很乐意奖赏你。",
  },
  [26377] = {
    ["T"] = "战斗的召唤：荒芜之地",
    ["O"] = "在荒芜之地找到并杀死5名部落成员。",
    ["D"] = "荒芜之地属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26378] = {
    ["T"] = "战斗的召唤：荒芜之地",
    ["O"] = "在荒芜之地找到并杀死5名联盟成员。",
    ["D"] = "荒芜之地属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26577] = {
    ["T"] = "上好的药水",
    ["O"] = "把10个烈焰核心带给弹簧座的德里兹。",
    ["D"] = "身为地精，我当然会试验和摆弄各种东西。此刻我正在弹簧座这里酿造艾泽拉斯有史以来最伟大的药水！不过我还缺几样关键材料，如果我要完成这瓶药水，就需要你的帮助。\n\n我需要的第一种材料，是远在西边、越过卡加斯后山脊上那些元素的炽热核心。那些火元素噼啪作响，它们的核心里蕴含着极其强大的材料。给我带一些回来，我就离完成药水更近一步。",
  },
  [26579] = {
    ["T"] = "上好的药水",
    ["O"] = "把1份研磨岩石带给弹簧座的德里兹。",
    ["D"] = "我们需要的最后一种材料可以在苦痛堡垒找到。那些矮人唤醒了巨大的石傀儡，而我清单上的最后一样东西是研磨岩石。我毫不怀疑，那些傀儡会产出最好的样本。\n\n你可以在这里西北方找到苦痛堡垒。不过小心，矮人可不喜欢外来者。",
  },
  [26580] = {
    ["T"] = "遗失的宝藏",
    ["O"] = "前往铁趾挖掘场，寻找可能发现宝藏的任何线索。如果发现了什么，就回到弹簧座的努格尔那里。",
    ["D"] = "我听说暗炉矮人已经在这里西北边的铁趾挖掘场开始挖掘了！谁知道他们会发现什么？最近流传的传言说，那里埋着一批宝藏……装满财富和贵重金属！\n\n如果你帮我弄到那批宝藏，我会很乐意和你分享利润。你找到挖掘场后，留意一个叫安多·暗影的人。我的消息来源告诉我，他负责监督这次挖掘，所以他很可能知道宝藏在哪里。",
  },
  [26581] = {
    ["T"] = "遗失的宝藏",
    ["O"] = "前往苦痛堡垒，找到暗炉宝藏。完成后回到弹簧座的努格尔那里。",
    ["D"] = "你在安多尸体上找到的信件显示，宝藏位于苦痛堡垒。不过它不会在那里待太久！矮人们正计划很快把它运往影铸城。\n\n如果我们想要这批宝藏，你就得抓紧了，$N。你可以在这里西北方找到苦痛堡垒，但要小心……那里是暗炉的坚固据点！祝你好运，因为你肯定需要它。",
  },
  [26582] = {
    ["T"] = "敲来护符",
    ["O"] = "把10枚尘怒护符带给弹簧座的约阿基姆·火根。",
    ["D"] = "地精活着图什么，不就是赚钱吗？我也没什么不同，我敢说如果你是地精，也会有同样感觉！总之，我弄到些高价值产品的消息，也许值得你跑一趟。\n\n很远的西南方有火山洞穴，那是你在这里看见的那些食人魔的老巢。有传言说，他们身上带着护符，用来标记自己的部族。那些护符的材料可能相当值钱！去给我弄一些来，$N，如果它们真有价值，也许我们能赚点钱。",
  },
  [26583] = {
    ["T"] = "挖掘调查",
    ["O"] = "调查挖掘场，然后回到弹簧座的加普尔那里。",
    ["D"] = "嘿，你有空吗？\n\n我在旅店里听到几个家伙谈起东北边一处挖掘场。这附近挖掘场倒是不少见，但据我听说，这次规模相当大。那些家伙没说清楚背后是谁，只说其中一人想靠近看看时被赶跑了。\n\n不过你看起来挺强壮，愿不愿意替我调查一下？如果你的调查带来什么好东西，我可以分你一份利润。",
  },
  [26584] = {
    ["T"] = "宾克尔的正义",
    ["O"] = "在暗炉挖掘场杀死10名暗炉矿工和10名暗炉监工，然后回到弹簧座的宾克尔·剪钉那里。",
    ["D"] = "我从加普尔那里听说，暗炉已经在附近开始挖掘。这意味着我寻求正义的时候到了。暗炉残忍无情，而我有一笔私人恩怨必须了结。\n\n多年前，我的妻子拉赫塔被暗炉杀害。那天我失去了一半自我，从此再也不是原来的我。我被困在这里，为弹簧座制造更多武器，但我要你去那个挖掘场，尽可能多地杀死暗炉。给我带来平静，$N。",
  },
  [26585] = {
    ["T"] = "给加普尔的矿石",
    ["O"] = "从暗炉挖掘场收集8箱秘银，并回到弹簧座的加普尔那里。",
    ["D"] = "那座矿井肯定塞满了矿脉！想想看，如果我们掌握它，能赚多少钱！\n\n话说……你看起来很有本事，为什么不试试呢？给我带几箱他们正在那里开采的矿石来。我能找到买家，也会分你一小份！",
  },
  [26586] = {
    ["T"] = "原始遗物",
    ["O"] = "把原始遗物带给弹簧座的加普尔。",
    ["D"] = "你杀死了一个似乎被暗炉挖掘惊扰的土灵之灵。那个灵魂掉下了这件遗物。也许弹簧座的加普尔会对它感兴趣？",
  },
  [26587] = {
    ["T"] = "原始遗物",
    ["O"] = "如果你是联盟，就把原始遗物带给铁趾挖掘场附近的矮人；如果你是部落，就带去卡加斯。",
    ["D"] = "嘿，别误会。我很感谢你把这东西带给我。但现在到处都是探险者，博物馆玩意儿不值钱。\n\n如果你想找真正关心它的人，也许铁趾挖掘场那边的矮人是合适人选？或者卡加斯的某个人——我想他们派过一支远征队到荒芜之地，正在找这类东西。",
  },
  [26588] = {
    ["T"] = "被困的矿工",
    ["O"] = "救出被困在铁泉矿洞中的矿工。",
    ["D"] = "所以你有点胆量，是吗？那我还有另一项任务给你。部落建立卡加斯时，我们也在城镇东边不远处开凿了铁泉矿洞。显然，挖掘激怒了本地土元素，因为它们已经占领了矿井！\n\n元素开始肆虐时，大多数工人都逃走了，但矿井里仍有一些人被困。进去确保他们安全离开。",
  },
  [26590] = {
    ["T"] = "被困的矿工",
    ["O"] = "把奇怪的矿石带给卡加斯的尼卡·血痕。",
    ["D"] = "好吧。既然你已经清理了矿井，我会尽量回收能用的工具，然后把这些矿工召集起来带回城里。现在铁泉已经完了，也许我该回卡利姆多。\n\n不过现在，你把那块矿石带回卡加斯，解释发生了什么。",
  },
  [26591] = {
    ["T"] = "奇怪的矿石",
    ["O"] = "把奇怪的矿石带给卡加斯的历史学家丽贝卡·凯勒。",
    ["D"] = "我不是冶金师，而卡加斯现在也没有专精金属的人，不过最近有一名来自幽暗城的博学者到了这里。他们像是某种研究组织——也许她会知道这是什么，或者该找谁谈。\n\n她名叫丽贝卡·凯勒，就在火堆旁那些被遗忘者那里。",
  },
  [26592] = {
    ["T"] = "奇怪的矿石",
    ["O"] = "从荒芜之地的苦痛堡垒收集8箱精铁矿石。",
    ["D"] = "你说这是从铁泉矿洞弄来的？真令人兴奋！但还不如发现纯净的精铁矿石令人兴奋。据我们所知，那东西只来自奥达曼。而奥达曼周围的矿井已经被暗炉占据。\n\n不过……暗炉在东边的苦痛堡垒有个基地。那或许比攻打奥达曼本身更容易。如果你想帮忙，$C，就去苦痛堡垒，把他们储藏的精铁偷出来！",
  },
  [26594] = {
    ["T"] = "通缉：灼喉",
    ["O"] = "杀死灼喉，并把他的头带给弹簧座的德克·风响。",
    ["D"] = "一头名叫灼喉的危险幼龙在弹簧座东边的莱瑟罗峡谷游荡。灼喉造成了数十人死亡，所到之处皆遭破坏。\n\n一名关心此事的弹簧座市民悬赏这头野兽的头。建议冒险者带上朋友，因为灼喉绝不会对攻击者手下留情。如果你成功了，就把他的头带给弹簧座旅店里的德克·风响。",
  },
  [26862] = {
    ["T"] = "暗炉图书管理员",
    ["O"] = "杀死暗炉图书管理员宾德罗尔，取回《索瑞森历史》，交给荒芜之地卡加斯的暗法师薇薇安·拉格雷。",
    ["D"] = "一个难得的机会出现了，$c，而我需要有人利用它。\n\n暗炉图书管理员宾德罗尔是一位才华横溢的作者，也是臭名昭著的隐士。不知为何，他前往熔渣之池，并住在那里的黑铁营房里。这可能是我们唯一能取得他的《索瑞森历史》手稿的机会。\n\n我要那本书。不管用什么办法，拿到它！",
  },
  [27049] = {
    ["T"] = "大地的震动",
    ["O"] = "在奥格瑞玛找到伊兹·速火箭，并收取工头弹簧座的补给。",
    ["D"] = "这就是我想偷工减料，用真正的植物和沾满黏液的玻璃便宜解决问题的下场。好吧，至少值得一试。\n\n看来唯一的解决办法就是动用我的金库了。拿着这袋齿轮当报酬，到奥格瑞玛的飞艇区域找到我的老同事伊兹·速火箭。请她提供我需要的高质量零件。",
  },
  [27630] = {
    ["T"] = "给桑德哈特的委托",
    ["O"] = "加卡尔要你使用炼金术技能制作5瓶猫眼药剂，并把订单交给荒芜之地卡加斯的桑德哈特。",
    ["D"] = "荒芜之地的大型猫科野兽很大胆，$C。我们已经不止一次失去侦察兵，死在它们的捕猎之下。问题在于它们的潜行。我们需要某种能让我们提前看见它们的东西。\n\n我自己也是炼金师，但我是自学的，不知道猫眼药剂的配方。如果你懂，制作几瓶会极大地帮助这里的步兵。",
  },
  [27680] = {
    ["T"] = "给高恩的委托",
    ["O"] = "尼卡·血痕要你使用锻造技能制作1件绿铁锁甲，并把订单交给荒芜之地卡加斯的高恩。",
    ["D"] = "我们这里没有铁匠，所以新护甲很难弄，但我更同情像高恩这样的斥候。他还在凑合用从德拉诺带来的护甲和武器！\n\n你是铁匠？好吧，如果你有兴趣帮忙，高恩可以用上一件新的绿铁锁甲。他自己绝不会开口，但我们得让他护甲完好。如果失去斥候，我不知道我们要怎样抵挡下一次联盟进攻！",
  },
  [27969] = {
    ["T"] = "工坊仪式",
    ["O"] = "与荒芜之地弹簧座的豪伊·车链谈谈。",
    ["D"] = "从最初制作铜管和扳手的日子起，你已经走了很远。我想你已经准备好接受工程学技能的考验了。\n\n我收到一位熟人的消息，他是我在工匠联盟会议上认识的。他更像是这门手艺的爱好者——豪伊真正热爱的其实是历史。不管怎样，他说自己急需一名熟练工程师的帮助，不管对方是部落、联盟，还是两者都不是！看来他真的很绝望。\n\n以我对豪伊的了解，这份工作报酬不会太高，但一定会很有意思。你觉得怎么样？",
  },
  [27970] = {
    ["T"] = "工坊仪式",
    ["O"] = "豪伊·车链要你前往托尔巴拉德岛上的巴拉丁监狱，从巴拉丁监狱守卫那里取回他的故障保护笔记本，然后把书带给荒芜之地弹簧座的他。你可以从阿拉希高地的法迪尔海湾搭乘航班前往托尔巴拉德。",
    ["D"] = "探险者协会成立的目的是研究泰坦历史，但我想更多了解他们的科技！具体来说，是关于一种名为“互联地脉稳定奥术通量引擎基础组件”，简称“故障保护装置”的传闻。故障保护装置被设计用来避免行星级灾难，但如果缺乏维护，它可能造成很多麻烦。\n\n我关于故障保护的所有研究笔记都在一本笔记本里，被一位熟人偷走了，而他目前正在巴拉丁监狱服刑。我写信给那里的守卫，他们告诉我欢迎我去取回那本书。我还没时间去做这件事，但有了助手，我就能同时出现在两个地方。所以拜托你，前往托尔巴拉德，把我的笔记本取回来！",
  },
  [27971] = {
    ["T"] = "工坊仪式",
    ["O"] = "从巴拉丁监狱的一名囚犯那里找回豪伊·车链的笔记本，并把它交还给荒芜之地弹簧座的豪伊·车链。",
    ["D"] = "既然没有巴拉丁守望者能协助你取回豪伊的笔记本，你就得亲自处理这件事。\n\n其中一名囚犯一定就是偷走笔记本的人。如果你盘问他们，或者调查他们的牢房，也许能找到你要找的东西。",
  },
  [28077] = {
    ["T"] = "给德克·风响的委托",
    ["O"] = "德克·风响要你使用烹饪技能制作10份龙息红椒，并把订单交给荒芜之地弹簧座的德克·风响。",
    ["D"] = "嘿，你是厨师吗？我看见你外衣上的油火污渍，就这么猜了。\n\n东边有一大群龙，而那些龙有时会喷火。我很羡慕！但这事也不是没办法。\n\n龙息红椒。听说过吗？给我做一些，好让我也能像龙一样喷火，我就会是个快乐的地精。",
  },
  [28418] = {
    ["T"] = "给军官高图斯的委托",
    ["O"] = "加卡尔要你使用附魔技能，用附魔武器 - 攻击为提供的1把少校之刃附魔，并把订单交给荒芜之地卡加斯的军官高图斯。",
    ["D"] = "哦，你好，附魔师，请稍等片刻。大家都没意识到我是炼金术学徒，不是附魔师。尼卡·血痕要我为军官高图斯给这把少校之刃附魔，但我做不到。你能帮忙，并把它送到附近塔楼里的他那里吗？",
  },
  [28468] = {
    ["T"] = "给神射手贾拉玛弗的委托",
    ["O"] = "尼卡·血痕要你使用工程学技能制作1副超聚焦护目镜，并把订单交给荒芜之地卡加斯的神射手贾拉玛弗。",
    ["D"] = "我很惊讶，贾拉玛弗竟然没有使用任何装备来辅助射击。我想他只是不了解工程学能怎样帮助他——比如一副超聚焦护目镜！你碰巧知道我在哪里能弄到一副吗？",
  },
  [28535] = {
    ["T"] = "给约阿基姆·火根的委托",
    ["O"] = "约阿基姆·火根要你使用草药学技能采集20朵紫莲花，并把订单交给荒芜之地弹簧座的约阿基姆·火根。",
    ["D"] = "弹簧座这里对紫莲花的兴趣突然上升。我不知道为什么，但我想分一杯羹。\n\n你是个有空闲时间的草药师，否则你也不会出现在弹簧座。所以出去采些莲花回来，我们都能获利。",
  },
  [28618] = {
    ["T"] = "给约阿基姆·火根的委托",
    ["O"] = "约阿基姆·火根要你使用剥皮技能收集5片龙鳞，并把订单交给荒芜之地弹簧座的约阿基姆·火根。",
    ["D"] = "龙。巨大、愤怒、危险。东边住着一大群，我告诉你——它们很值钱。只要你知道卖到哪里，每片鳞都值一堆金币。而这正是你买不起的情报。\n\n所以，我们做个交易吧。给我带5片龙鳞来。它们现在也许看起来不怎么样，但稍加打磨和涂层，我们就能把野兽变成赏金。",
  },
  [28651] = {
    ["T"] = "给加普尔的委托",
    ["O"] = "加普尔要你使用采矿技能采集20块坚固的石头，并把订单交给荒芜之地弹簧座的加普尔。",
    ["D"] = "荒芜之地这里人人都在争矿石。精铁？瑟银？算了，我要石头。坚固、未经塑形的石头。\n\n听着，你有技术，我有人脉，所以你对交易感兴趣吗？给我带20块坚固的石头来，我可以确保你在这片贫瘠荒地上多活一天。",
  },
  [28715] = {
    ["T"] = "给暗法师薇薇安·拉格雷的委托",
    ["O"] = "暗法师薇薇安·拉格雷要你使用裁缝技能制作1件丝质长披风，并把订单交给荒芜之地卡加斯的暗法师薇薇安·拉格雷。",
    ["D"] = "这一个完全没用！\n\n<薇薇安用干瘦的拇指朝斯兰达一指。>\n\n我说我需要的是长披风。不是披肩。不是帷布。是一件完整尺寸的披风。\n\n如果你不是个彻头彻尾的废物，就给我带一件丝质长披风来。要够长，能挡住沙漠的风，也要有足够的格调，让我忘记自己现在身边都是些什么货色。",
  },
  [26266] = {
    ["T"] = "黑暗文献",
    ["O"] = "从诅咒之地荒野中的教派成员身上收集8本魔誓秘典。",
    ["D"] = "你是部落的人，对吧？我想加入一个阵营，综合考虑下来，我觉得这显然是正确选择……\n\n莫格莉亚和她的商队在我的营地这里遇到了我。我们各自解释自己为什么来到这里之后，嗯……这简直是扭曲虚空促成的绝配——你能相信我们的目标完全一致吗？所以，我们暂时达成协议：我提供关于邪石堡垒的情报，以及解决这场正在蔓延的诅咒的办法，换取部落公民身份。\n\n至于诅咒，我有个计划，不一定能成功。这不是永久解决办法，但我可以试着给部落争取一点喘息。也就是说——只要我能得到只有$C才能提供的一些帮助。\n\n我需要附近那些信徒的书，特别是那些施法或举行仪式的人。暴徒和执行者不行。书越厚越好。等我拿到它们，会解释更多。",
  },
  [26407] = {
    ["T"] = "战斗的召唤：诅咒之地",
    ["O"] = "在诅咒之地找到并杀死5名部落成员。",
    ["D"] = "诅咒之地属于联盟，我们必须不断证明这一点。猎杀部落成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26408] = {
    ["T"] = "战斗的召唤：诅咒之地",
    ["O"] = "在诅咒之地找到并杀死5名联盟成员。",
    ["D"] = "诅咒之地属于部落，我们必须不断证明这一点。猎杀联盟成员，以军队的名义杀死他们，证明你的价值并提升军阶。",
  },
  [26419] = {
    ["T"] = "通往斯通纳德的门径",
    ["O"] = "在诅咒之地新的黑暗之门附近收集3块第一座黑暗之门碎片，然后回到斯通纳德的洛林·狐火那里。",
    ["D"] = "啊，$C！很高兴见到你，我有个提议。与其只是传送到斯通纳德，为什么不为你的盟友创造一扇传送门呢？我只需要你帮我制作一样东西。如果一切如我推测的那样，我甚至会让你保留它。\n\n如果这听起来值得，就从这里向南进入诅咒之地，在如今的黑暗之门附近收集散落在地上的原始黑暗之门碎片。不要离传送门太近，除非你想死。",
  },
  [26599] = {
    ["T"] = "喂饱部队",
    ["O"] = "从灰鬃野猪身上收集10块硫磺肉。",
    ["D"] = "在这种地方保持积极很重要，但我想这里很多人都对你冷淡吧？尽量别怪他们。荒凉的地貌、不断的闪电、黑暗之门苏醒的威胁——这些会把驻扎在这里的多数人慢慢磨垮。\n\n这里不仅压力巨大，饥饿也会对人造成可怕影响。我们正在动用应急食物储备，直到下一批大补给到来……可谁知道那是什么时候！\n\n这里的动物不适合食用，但我有个计划。愿意帮忙吗？\n\n我需要附近灰鬃野猪的肉。请尽量多带，但避开那些特别硬的部位。",
  },
  [26601] = {
    ["T"] = "黏土净化",
    ["O"] = "从诅咒之地海岸附近的矿点收集7份红土。",
    ["D"] = "所以……计划是用炼金术，把这种恶魔肉变成能吃的东西？嗯……我不知道，不过试试大概也没坏处。\n\n<妮娜托着下巴沉思了很久。>\n\n好吧，这听起来可能很荒唐，但我们骑到这里的马在穿过沼泽后很容易生病。我们抵达时，我总会注意到它们在吃地上的黏土块。第二天，它们就像什么事都没发生过一样。\n\n也许……也许黏土有某种净化特性？到处都能找到少量，但我想你在海岸边运气会更好，毕竟有潮汐之类的。",
  },
  [26602] = {
    ["T"] = "准备分发",
    ["O"] = "把消息带给守望堡内的军需官朗格尔斯。",
    ["D"] = "好，来测试一下。我把水煮沸，加入一些压碎的木炭、跌打草、格罗姆之血……现在加黏土。\n\n<妮娜把黏土混入气味刺鼻的溶液中，使它变得黏稠。>\n\n豁出去了……\n\n<混合物接触肉块，剧烈嘶嘶作响。等一切平静下来，显然有些事成功了。>\n\n哦，哇……气味没了！不再渗液，颜色更明亮，而且似乎也煮熟了！\n\n<妮娜警惕地看着你，然后尝了一口。>\n\n嗯……不错！看来我们运气不错，$N。你为什么不去把好消息告诉朗格尔斯？我会把剩下的都煮完，之后带给他。太谢谢了！",
  },
  [26603] = {
    ["T"] = "斥候莫格莉亚",
    ["O"] = "在诅咒之地海岸某处找到斥候莫格莉亚。",
    ["D"] = "正是我在找的$R，$N。\n\n你可能还没见过，但我们一些斥候和步兵从诅咒之地回来时染上了诅咒。它不会消退，我们的术士也从未见过类似情况。\n\n我们剩下的一名斥候被派往南方执行侦察任务，查明更多情况，我想你能和她配合得很好。她有点急性子，所以试着平衡她一下。也别低估南边那片荒野的危险。\n\n我读到的最后一份报告显示，她和她的商队在诅咒之地海岸。力量与荣耀，$N。",
  },
  [26604] = {
    ["T"] = "杀掉弱者",
    ["O"] = "杀死诅咒之地的魔誓教派成员。",
    ["D"] = "派遣指挥官派我来这里收集情报。我已经收集到需要的一切！这个教派是我们侧腹的一道溃烂伤口，从远处传播诅咒、恐吓我们。\n\n<莫格莉亚严厉地瞪了附近的亡灵一眼。那亡灵不情愿地迎上她的目光。>\n\n杀光他们，$N。先从这里西南方堡垒外沿游荡的杂兵开始。我们要用他们的血把这片土地涂得更红。为了部落！",
  },
  [26605] = {
    ["T"] = "杀戮联盟",
    ["O"] = "从守望堡周围的联盟士兵身上收集16枚守望堡徽记。",
    ["D"] = "信徒是一回事，但没有什么比看见联盟更让我血液沸腾。我们是这个营地的客人，所以必须注意礼节……可每当我看见那些渣滓经过，我就几乎控制不住自己！要是由我决定，我们早就对守望堡发动全面进攻了！\n\n我的上级说，我们需要他们缓冲任何朝沼泽进发的恶魔……我说全是胡扯！你不受我那些命令约束，所以去吧，$N。从要塞周围那些士兵身上给我带些联盟徽记回来，你会得到丰厚奖赏。",
  },
  [26613] = {
    ["T"] = "援助守望堡",
    ["O"] = "把援助请愿书交还给守望堡内的看守者马哈尔巴。",
    ["D"] = "<这具尸体相当新鲜。矮人胸口一道破烂伤口流出的血在地上积成一滩。>\n\n<矮人的装备看起来没有被动过，你在他们磨旧的背包里找到一封信，似乎是来自守望堡的正式通讯。>",
  },
  [26614] = {
    ["T"] = "收集情报",
    ["O"] = "从诅咒之地各处的魔誓教派成员身上收集12捆信徒文稿。",
    ["D"] = "魔誓者一直妨碍我们监视黑暗之门。我们通常只在孤立事件和冲突中遇到他们，但他们变得更加大胆，也更有组织。我们无法监控他们的发展，因为我们派出去的大多数斥候从未回来。更糟的是，敌人正在使用一种我们无法治愈的奇异新魔法诅咒。\n\n我很好奇这里到底发生了什么。你愿意作为我们的代理人行动吗？低阶魔誓成员不是最好的情报来源，但他们是我们唯一常能看到的人。先从这里南边山谷里的他们开始，把他们可能携带的任何笔记或信件带回来。\n\n外出小心，$C。",
  },
  [26617] = {
    ["T"] = "邪石矿井",
    ["O"] = "从邪石堡垒内的矿井收集30块邪石金矿。",
    ["D"] = "你好吗，$C。听说你就是帮了老看守者的人。谢谢……代表我们这里所有人。\n\n还听说南边那座堡垒里有些矿井。你知道这片土地的历史吗？在兽人把它榨干之前，这一带曾经有很多金子。如果他们正在开矿，也许还有些剩下！\n\n你要去邪石吗？愿意把他们在下面开采的东西带一些回来给我吗？守望堡需要它能得到的所有资源！",
  },
  [26620] = {
    ["T"] = "给疲惫者的水",
    ["O"] = "把水桶交给守望堡的希尔达·雷酒，并告诉她消息。",
    ["D"] = "给。\n\n<格罗克斯尖锐地吹了一声口哨。一名水手迅速拖来一只桶，放在你面前。>\n\n就像我说的——你能找到的最新鲜的水！告诉那个希尔达姑娘，我很快会去守望堡送剩下的货，并谈谈未来的运输。别担心怎么送，交给我们就好。和你做生意很愉快。",
  },
  [26622] = {
    ["T"] = "沉没的宝藏",
    ["O"] = "在诅咒之地海岸外的一艘沉船中找到沉没的宝藏。",
    ["D"] = "嘿！你看起来水性不错，而我需要一个水性不错的人。\n\n看见那边的沉船了吗？我们进港时我总会看见它们，然后冒出一个想法：沉没的宝藏！\n\n我会付钱让你替我去看看。我数过，下面有四艘沉船。如果你找到什么，就带回来，我们可以分赃……\n\n哦，我想我还看到一些讨厌的骷髅人在下面游来游去。小心，$R！",
  },
  [26624] = {
    ["T"] = "通缉：剥魂者格鲁佐克",
    ["O"] = "进入邪石堡垒内的格罗姆波拉，取下剥魂者格鲁佐克的头。",
    ["D"] = "需要一群勇敢的人深入魔誓者领地，找到并杀死那个被称为剥魂者格鲁佐克的家伙。\n\n他被认为是极度危险的人物。可靠情报显示，他位于守望堡以南、邪石堡垒深处一个被白骨环绕的洞穴内。\n\n要完成悬赏，把格鲁佐克的头带给军需官朗格尔斯。",
  },
  [26626] = {
    ["T"] = "意外盟友",
    ["O"] = "在诅咒之地海岸某处找到伊扎尔尼尔并与他交谈。",
    ["D"] = "我们多数人不愿承认，但我们处境危急。守望堡已经有一段时间没有收到增援，人们正遭受我们从未见过的诅咒，而我们周围的土地每天都变得更危险。\n\n两周前收集一些材料时，我遇到一个从南边那座堡垒废墟中逃出来的亡灵。我做好了战斗准备，但他举起双手解释了自己的处境。\n\n他曾是那个教派的高阶成员，试图逃离时差点送命。现在他想在部落或联盟寻求庇护，但既然他是亡灵……嗯，他在我们这里也没有多少容身之处，对吧？\n\n看守者认为这可能是某种陷阱，但说实话，我们需要一点转机。这样的人一定掌握有用情报。\n\n你愿意去找找他吗，$C？我最后一次看见他时，他正朝海岸走去。",
  },
  [27192] = {
    ["T"] = "黑暗之门的哨兵",
    ["O"] = "在诅咒之地黑暗之门附近杀死5名地狱卫士斥候。",
    ["D"] = "你知道诅咒之地的黑暗之门吗？大多数人因为那整场军团战争的事都避开它，但烟林牧场可不会让恶魔入侵这种小事挡住生意！\n\n我们有一名代理人定期虹吸传送门辐射出的能量，但巡逻该区域的地狱卫士斥候最近造成了一些麻烦。如果你能削减它们的数量，让我们的代理人继续完成任务，那就太好了！",
  },
  [27916] = {
    ["T"] = "鲜血与荣耀的束缚",
    ["O"] = "在诅咒之地用/challenge向玛兹罗尔发起玛克戈拉，并在荣耀决斗中击败他。你必须在这场挑战中存活。",
    ["D"] = "我可以用一生谈论荣耀之战，但为了让你有基本理解，我会说得简单些。\n\n我的族人抛弃荣耀加入了军团，沦为它力量的奴隶。在堕落之前，我们用一种名为玛克戈拉的荣耀决斗解决领导权争端，或挑战他人的权威。在诅咒之地，一座俯瞰黑暗之门的山丘上，有个名叫玛兹罗尔的恶魔。他是艾泽拉斯上军团仆从中的一个小领主，但应该受到挑战并被击败。\n\n向玛兹罗尔发起玛克戈拉，堂堂正正面对他——不要耍花招。如果你输了，就公正地输。如果你赢了，就靠自己的力量取胜。祝你好运，冒险者。",
  },
  [28042] = {
    ["T"] = "山脉仪式",
    ["O"] = "与诅咒之地的凯尔娜·寒石谈谈。",
    ["D"] = "$N！我刚收到一位朋友的紧急消息，她是一名对大地召唤有特殊兴趣的萨满。你是经验丰富的矿工，对吧？她正需要咨询这样的人。\n\n如果你愿意帮忙，就去诅咒之地守望堡找凯尔娜·寒石。",
  },
  [26267] = {
    ["T"] = "逆转诅咒",
    ["O"] = "从邪石堡垒内的术士身上取得一枚苦难雕文。",
    ["D"] = "<伊扎尔尼尔佝偻着身子，用浑浊的双眼在魔典书页上扫视了很久。最后，他抬头看向你。>\n\n你有没有见过类似这样的东西？写在卷轴上的，或者甚至刻在石头上的？\n\n<伊扎尔尼尔给你看了一页，上面满是混乱的字迹，环绕着一枚邪恶的符文。>\n\n那些术士正用这些东西摆弄那种诅咒——邪焰——手段之多，连我都没想到。哈，那些蠢货甚至还把它用于炼金术。\n\n如果要继续下去，我需要一枚这样的雕文，而且除了邪石的术士，我想不出还有谁会有这种东西。那座堡垒一个人去太危险，带上朋友吧。你回来之前，我会继续读下去。",
  },
  [26268] = {
    ["T"] = "重写诅咒",
    ["O"] = "从邪石堡垒周围收集5瓶库兹希尔暗墨。",
    ["D"] = "看见这枚雕文上的铭文了吗？它是用库兹希尔暗墨写成的：效力很强，也很难弄到，哪怕对术士来说也是如此。恶魔之血是这种墨水的主要成分，使它泛着吞噬光线的黑色光泽。\n\n嗯……他们使用的词典源自海外的阿古斯之醒圈子。我能读懂到足以自行修改的程度，但我自己没有暗墨。\n\n<伊扎尔尼尔带着期待的笑容看向你。>\n\n能请你弄一些来吗？术士和他们的侍僧身上有。我敢打赌，你会在堡垒周围的术士帐篷里找到它。那些小屋里也可能有一些。",
  },
  [26269] = {
    ["T"] = "灵魂燃料",
    ["O"] = "在邪石堡垒内的教徒尸体上为伊扎尔尼尔找到1块格罗姆波拉灵魂石。",
    ["D"] = "你握住这枚雕文时感觉到了什么？恶心？一种怎么也抓不着的瘙痒？\n\n<伊扎尔尼尔把一只手按在符文上，闭上眼睛。>\n\n对我来说，那是脑袋里的砰砰声。像是……有人在摇晃自己的牢笼。我听说有些强大的灵魂石是从邪石后方某个洞穴里走私出来的……不难推断，我们这枚雕文就是这样被充能的。\n\n那个洞窟里的兽人层次完全不同，根本不屑于和其他人往来。话虽如此，盗窃、交易，或者一个简单的错误，有时都会让他们垂涎的石头落到不该去的地方。\n\n也许你已经见过一些了？我的计划要开花结果，至少需要一块。邪石周围的术士大概会有。\n\n如果你觉得自己够鲁莽，也可以试试那个洞穴。它在邪石中心以西，入口被巨大的白骨环绕。我从没进去过，但听过一些故事……",
  },
  [26598] = {
    ["T"] = "讨债",
    ["O"] = "从邪石堡垒内的约翰·泰勒、乔尔·泰勒和约书亚·泰勒身上取回格罗克斯的货物。",
    ["D"] = "我有个需要动点肌肉的问题。\n\n堡垒里有几个赖账的欠我一大笔——三个亡灵兄弟。上上次我们靠港时，他们各自看中了我卖的东西，却没带够钱。我同意先把货给他们，只要他们在我下次停靠时付钱就行。\n\n结果你猜怎么着？我还在等他们付款！地精绝不会忘账，$R，你也别忘了！\n\n一个拿着我的法杖，另一个拿着怀表，最后一个拿着一面魔法鼓。只要能把我的东西拿回来，就算你得敲断几根骨头，我也不在乎——你懂我的意思吧。",
  },
  [26608] = {
    ["T"] = "攻陷邪石",
    ["O"] = "从邪石堡垒居民身上收集50只破烂的耳朵。",
    ["D"] = "那座堡垒即使在这片土地上也是一块毒疮。我们越是“等待并监视”，它就变得越危险。\n\n我离开斯通纳德之前，我们已经向奥格瑞玛求援。你能忍受坐在这里无所事事，等一封信一路送到世界另一端……最后只被某个软骨头扔进一堆同样的信里吗？！\n\n我受够了！去找一支战队！带回战利品，$N。耳朵。我要看见你制造屠杀的证据！冲进那座堡垒，砸碎几颗脑袋。为部落做事不需要任何人的许可！",
  },
  [26609] = {
    ["T"] = "邪石矿井",
    ["O"] = "从邪石堡垒内的矿井收集30块邪石金矿。",
    ["D"] = "那边那个亡灵告诉我邪石下面有矿井。他说据他最后所知，那条矿脉仍然很旺，而且是这一带最大的。\n\n咱们也分一杯羹吧，$C。照现在的形势，那座堡垒里不会剩下多少活人。趁着有老鼠带着矿石跳船之前，最好现在就拿一些。",
  },
  [26611] = {
    ["T"] = "恶人安息",
    ["O"] = "护送夜行者罗斯离开邪石堡垒。",
    ["D"] = "<你轻轻推了推那个亡灵，他唇间逸出一声微弱的嘶气，随后睁开了眼睛。>\n\n你不是教徒？帮帮我，$C！他们一直在我身上施展军团魔法。我再也撑不住了……\n\n我们得离开这里……现在就得走！你处、处理掉那个拷问者了吗？\n\n如果我们能、能逃出去，就去幽暗城的盗、盗贼区找格雷戈·查尔斯。",
  },
  [26616] = {
    ["T"] = "我们的眼睛",
    ["O"] = "在邪石堡垒内对12只诅咒之眼使用看守者的虹膜。",
    ["D"] = "这些文稿里有几处提到，术士在堡垒内几乎无所不知。显然，他们召唤了离体的眼睛，让它们漂浮在道路周围，时刻监视人群……\n\n这听起来不像什么复杂魔法，而且如果我们能接入这些眼睛，从这里监视它们所见之物，我看得出其中有很大潜力。也许我们能进一步了解正在蔓延的诅咒。\n\n我准备了一件饰品，你可以带去堡垒。遇到这些眼睛时，透过虹膜看它，魔法就会生效。眼睛越多越好，所以尽可能多用它。",
  },
  [26618] = {
    ["T"] = "干渴与包裹",
    ["O"] = "查明邪石堡垒如何取得清洁的水。",
    ["D"] = "那邪石可真是坏买卖。这些被诅咒的土地也是坏买卖……而且你知道吗，这整片地方以前也没好看到哪去。\n\n说起来，那些邪石家伙的水是从哪来的？我们可是懂饮品的……\n\n<希尔达朝她姐妹旁边那辆装满酒的大车点了点头。>\n\n……我也知道这一带每口井都干了。这里又不下雨。他们总不会只喝召唤出来的东西吧？那可对身体不好，听我的！\n\n每个人都需要水，$N。你要是往那边去，为什么不调查一下呢？我敢说我们会了解到比预想更多的东西……也许甚至能知道怎么给自己弄到干净水！我听说我们也快见底了。",
  },
  [26625] = {
    ["T"] = "通缉：剥魂者格鲁佐克",
    ["O"] = "进入邪石堡垒内的格罗姆波拉，取下剥魂者格鲁佐克的头。",
    ["D"] = "部落成员们，这是战斗号召！古尔丹的旧日追随者在邪石堡垒内筑巢，唤起死者，并复兴了通灵术的黑暗技艺。\n\n这个团伙的首领被称为剥魂者格鲁佐克，需要一支老练的队伍将他铲除。在南方邪石堡垒内一处被白骨环绕的洞穴里找到他。\n\n把他的头带给斥候莫格莉亚以完成悬赏。",
  },
  [26628] = {
    ["T"] = "根基崩塌",
    ["O"] = "在邪石堡垒内杀死15名邪石商人、15名邪石矿工和15名邪石建造者。",
    ["D"] = "邪石的社会根基由工人组成。没有他们参与，什么都无法运转。纳罗克督军花了极多时间，通过恐惧和痛苦收紧对他们的控制。\n\n那座堡垒坐落在这一带最大的金矿脉之一上，而工人开采它。邪石的老建筑已经成了废墟，但工人正在修复它们。码头上还有需要运输的货物——用开采出的金子买来的货物，如此等等……\n\n你知道该怎么做，$N。",
  },
  [26629] = {
    ["T"] = "真正的信徒",
    ["O"] = "在邪石堡垒内杀死兽王金拉、厨师德文和码头管理员利亚姆。",
    ["D"] = "邪石的队伍中，有几个不可或缺的人立刻浮现在我脑海里。杀掉他们会在等级体系中播下深深的不和。\n\n兽王金拉是个粗犷的女人，负责牧养群狼，监管堡垒内的骑乘巡逻和重要交付。那些野兽只听她一个人的。她住在最西侧高地、马厩附近的一间大棚屋里。\n\n厨师德文可真是个难缠货——白天当厨师，夜里当拷问者，而且没人敢问熟肉是从哪里来的。他让恐惧在堡垒中鲜活不散，盘踞在南侧中层台地上一处有墙围住的院落里。\n\n最后，码头管理员利亚姆是邪石后勤和海上贸易背后的天才。他是个独来独往的人……很可能埋头待在港口办公室的账本里。",
  },
  [26630] = {
    ["T"] = "背叛之刺",
    ["O"] = "在邪石堡垒内找到伊扎尔尼尔的物品，并从埃塞尔德林身上取得伊扎尔尼尔的雕文。",
    ["D"] = "在邪石，我有过一个活人也许会称为朋友的人，信不信由你。\n\n那个名叫“埃塞尔德林”的高等精灵和我有许多共同兴趣。那感觉令人沉醉。随着我们合作，我放松了戒心……他的行动很隐蔽，我没有注意到他对我周围人的影响像杂草一样蔓延。当我逃离时，他继承了我拥有的一切。\n\n我想拿回其中一些东西。我以前的帐篷就在码头旁边的高地上，里面有个包，装着我的物品。埃塞尔德林拿着我的雕文：那是诅咒的某种“钥匙”，也是我们要阻止诅咒所必需的东西。",
  },
  [26631] = {
    ["T"] = "眼中刺",
    ["O"] = "从邪石堡垒内的塞安娜·亮谷身上取得塞安娜的雕文。",
    ["D"] = "我的对手是塞安娜·亮谷，一名造诣不浅的术士，却有着不幸的完美癖。每一个细微缺陷都会招来她尖刻的嘲讽，而我至今仍会在梦中看见我失势后她露出的那副恶毒笑容。\n\n我承认，正在四处蔓延的这个诅咒……邪焰，是我们两个人思维的产物。她负责它有害的一面，而我负责它的强度和持久力。\n\n<伊扎尔尼尔举起双手，低头作出半心半意的道歉。>\n\n别指望这会是一场轻松战斗。她持有另一枚雕文，我们需要它来对抗诅咒。从邪石中心向西走，你会在主路右侧的高地上找到她。",
  },
  [26632] = {
    ["T"] = "督军的雕文",
    ["O"] = "从邪石堡垒内的纳罗克督军身上取得纳罗克的雕文。",
    ["D"] = "终于到时候了，$N。现在你要去斩蛇头了。我们已经如此接近……\n\n为了表示效忠并加强安全，塞安娜和我被迫给纳罗克督军各自制作了一枚雕文。把三枚雕文合在一起，可以让人对诅咒拥有少量控制权。不足以将它从世界上清除……但这是个开始。我只能逐个案例地把它从你身上驱散。\n\n纳罗克住在最南方最高台地的塔楼里。经历了其他那些死亡之后，他会知道你正冲着他而来。把他的雕文带给我，我就能开始收束这个由我协助释放的诅咒。",
  },
  [26918] = {
    ["T"] = "够劲的一脚",
    ["O"] = "从悲伤沼泽周围收集8个火爆辣椒。",
    ["D"] = "如果我想让这锅炖菜够劲，好让守卫们保持警觉，那就需要些强烈的味道。我们穿过黑暗之门时，我带着一袋火爆辣椒种子。袋子破了个洞，有些种子沿着去避难营的路掉了出来。从那以后，那些植株已经发芽成熟。植株上长出来的辣椒辣得非同寻常。你能给我弄一些来吗？",
  },
  [27907] = {
    ["T"] = "鲜血与荣耀的束缚",
    ["O"] = "前往悲伤沼泽，看看能否找到一个愿意与你交谈的兽人。",
    ["D"] = "我最大的愿望之一，就是让联盟与部落之间的仇恨冷却下来。你愿意主动去理解兽人，这是时代正在改变的可喜迹象。\n\n不幸的是，与真正的兽人相比，我会是个糟糕的老师。事情发展成现在这样，我心中的苦涩还太新。但悲伤沼泽中有一个兽人营地，靠近守望堡。我听说他们对联盟稍微友好些。去那里看看，找找附近有没有人愿意向你讲述兽人的荣耀观念。那就是个不错的起点。",
