    ["D"] = "像我的族人那样思考和战斗，并不只是以某种方式挥动斧头。你必须在一切事情中拥抱荣耀。我相信我知道教授这些观念的最佳老师。\n\n在悲伤沼泽，你会找到一位生前死后都秉持荣耀之人的灵魂。在通往诅咒之地的道路上寻找他，并在那里开始你的学习。",
  },
  [28043] = {
    ["T"] = "山脉仪式",
    ["O"] = "在诅咒之地的断层中开采沸腾矿石，交给诅咒之地守望堡的凯尔娜·寒石。",
    ["D"] = "为了大地的疼痛而寻求矿工帮助，我知道这很奇怪。通常，我们萨满会认为采矿正是那种疼痛的来源。但这一次，我能感觉到你的采矿技艺正是所需之物。\n\n我听见诅咒之地的石头在哭喊。有某种古老之物正在深处翻腾。大地的裂缝开始渗出东西。去诅咒之地看看从地下冒出了什么。",
  },
  [28044] = {
    ["T"] = "山脉仪式",
    ["O"] = "把1块奥术水晶、1颗艾泽拉斯钻石、1颗巨型蛋白石和10块黑铁锭带给诅咒之地守望堡的凯尔娜·寒石。",
    ["D"] = "正如我所说，这种矿石和我遇到过的任何东西都不同，但它与黑石山深处发现的黑铁有些相似之处。更相关的是流经那座山的熔岩。它同样拥有一种黑暗的灵魂。我想比较一份样本，但我们首先需要打造一只能够盛放它的坩埚。\n\n为此，我需要一些你特别有资格取得的补给：一块奥术水晶作为焦点，一颗艾泽拉斯钻石和一颗巨型蛋白石用于内衬，还有一些黑铁锭用于框架。",
  },
  [28045] = {
    ["T"] = "山脉仪式",
    ["O"] = "进入黑石山的黑石深渊，使用黑铁坩埚从黑熔炉附近的熔岩中收集一份样本，然后把它带给诅咒之地守望堡的凯尔娜·寒石。",
    ["D"] = "现在你已经准备好从黑石山采集一份熔岩样本了。我听说黑铁矮人在接近山心的深处拥有自己的熔炉——黑熔炉。样本越靠近这座熔炉越好。\n\n还有，小心点，$N。我听说暗炉城如今充满了背叛、暴徒、盗贼和教徒。",
  },
  [28048] = {
    ["T"] = "山脉仪式",
    ["O"] = "安戈洛环形山马绍尔营地的亚露妮·观焰者要你把嗡鸣的矿石样本带给诅咒之地守望堡的凯尔娜·寒石。",
    ["D"] = "你必须把这份样本带回给凯尔娜，让她亲自比较。她与大地的联系比我深得多。\n\n感谢你把这个谜团带给我，$N。大地之环会讨论现在是否应该做些什么，如果需要的话。",
  },
  [28396] = {
    ["T"] = "看守者马哈尔巴的委托",
    ["O"] = "看守者马哈尔巴要你使用附魔技能制作1块魔化皮，并把订单带给诅咒之地守望堡的看守者马哈尔巴。",
    ["D"] = "我们一直在研制能够承受黑暗之门邪能污染的护甲和武器，这片土地已经被它破坏。其中有一样东西特别有用，那就是魔化皮。我相信你是个附魔师，对吧？如果你给我带一些来，我会付钱给你。",
  },
  [28647] = {
    ["T"] = "斯塔诺尔·火踵的委托",
    ["O"] = "斯塔诺尔·火踵要你使用采矿技能收集5块真银锭，并把订单带给诅咒之地守望堡的斯塔诺尔·火踵。",
    ["D"] = "他们说恶魔不喜欢真银。我可不能怪它们。这东西闪闪发亮，打磨起来很锋利，还在不止一种意义上受过祝福。\n\n那些恶魔在传送门遗迹附近游荡，我们正需要储备一批真银武器。给我带来5块真银锭，你就是为联盟效了一份力。",
  },
  [28694] = {
    ["T"] = "军需官朗格尔斯的委托",
    ["O"] = "看守者马哈尔巴要你使用裁缝技能制作2双灰布长靴，并把订单带给诅咒之地守望堡的军需官朗格尔斯。",
    ["D"] = "这里的大地在燃烧。邪能污染附着在石头、沙土，甚至钢铁上。朗格尔斯不到六周就磨坏了三双靴子——没有什么撑得住。听说灰布能抵御高温、火焰和腐蚀。所以守望堡愿意为我们的军需官付钱买几双灰布长靴。\n\n希望这话是真的，否则月底前他就要光脚了。",
  },
  [26270] = {
    ["T"] = "远程扰乱",
    ["O"] = "在邪石最南方最高台地的高坛仪式法阵上使用改造过的苦难雕文。",
    ["D"] = "到了最后一幕了。你的小队现在已经熟悉邪石的危险，希望这不会太困难。\n\n计划是这样的：把修订过的雕文带到邪石南部最高台地的祭坛，在仪式法阵上使用它。那是一枚散发着黑暗魔法的紫色符文。理论上，这枚雕文会把诅咒从目标身上撕下来，并送回仪式法阵——正如我说过的，这不是永久的解决办法。\n\n我不知道这样做会带来什么后果，所以准备好面对任何情况。祝你好运，$N。",
  },
  [26421] = {
    ["T"] = "通往斯通纳德的门径",
    ["O"] = "深入黑石深渊，击败七贤以取得希斯雷尔的典籍，然后返回斯通纳德的劳林·狐火那里。",
    ["D"] = "利用这些承受过巨大虚空能量的石头，再加上碾碎的能量水晶，我希望能为你制作出某种可佩戴的头冠。如果成功，我之所以会把它交给你，是因为我根本用不上它。我只是想知道我的理论是否正确。像你这样的冒险者会有很多用处。你甚至可以想扔就扔，我不在乎。\n\n但我们还需要最后一种组件。我会很多本事，可惜束缚石头不在其中。我知道有个名叫希斯雷尔的矮人巫师，曾经住在暗炉城。如果你不知道，那地方就在黑石深渊。希斯雷尔拥有一本典籍，里面记载着我所需的信息。如果你能去那里取回那本典籍，我们就能完成这顶头冠。",
  },
  [26427] = {
    ["T"] = "奥术融合体",
    ["O"] = "在斯通纳德外南部的兽人洞穴中使用奥术视野药剂，然后击败元素融合体。之后返回斯通纳德的劳林·狐火那里。",
    ["D"] = "我用你收集来的眼睛调制出了一瓶奥术视野药剂。在这里西边南部的兽人洞穴里使用它。它会召唤出一个名为元素融合体的奥术造物。你的任务就是击败它。\n\n如果你活着回来，我想我可以解释那东西是什么；但如果你想问是不是我把它放在那里的，不是。我不知道是谁干的。",
  },
  [26610] = {
    ["T"] = "向斯通纳德报告",
    ["O"] = "向悲伤沼泽斯通纳德的派遣指挥官鲁阿格报告。",
    ["D"] = "<莫格莉亚向你敬礼，递给你一卷破损的卷轴，上面有光亮的红色封印。>\n\n我会说这次任务很成功，全靠你。我对你只有称赞，$N。我想你会想把这个地方远远抛在身后，所以把这份报告带回斯通纳德的派遣指挥官那里吧。\n\n如果斩杀部落敌人的荣耀还不够，他会确保你得到奖赏。\n\n胜利或死亡！",
  },
  [26623] = {
    ["T"] = "砸骨头",
    ["O"] = "为洛克和泰迪从格罗姆波拉内带回30根结实的骨头。",
    ["D"] = "<洛克哼了一声，变得躁动不安。它嘴里叼着一只袜子。你注意到围栏里散落着许多骨头，每根都快被啃得一干二净。>",
  },
  [26627] = {
    ["T"] = "烂中选优",
    ["O"] = "在莫格莉亚营地西南方的邪石前哨杀死莉迪娅·卡特莱特。",
    ["D"] = "我就直说吧——我还没有加入任何阵营，但我对以前的同僚也没有半点好感。我愿意和任何人合作，给那些蠢货上一堂他们永远忘不了的课！\n\n我在堡垒里待的时间不长，但我知道它所有的秘密……更重要的是，我知道怎么让它彻底停摆。至少能停一阵子……\n\n我需要确认你足以胜任。在附近的一处前哨，有个隐秘行事的家伙在指挥教派乌合之众，一个叫“莉迪娅·卡特莱特”的人。\n\n带上朋友……确保她走向毁灭，然后我们再继续。",
  },
  [26912] = {
    ["T"] = "致命刺击解药",
    ["O"] = "收集8瓶致命刺击毒液，并返回斯通纳德的苏塔佐尔那里。",
    ["D"] = "我一定是惹恼了头儿，他才把我派到这个兽人称作斯通纳德的臭水沟！显然他们需要一名炼金师，帮忙处理这一带那些该死的野生动物。这就是你出场的地方。\n\n最近，这里东南方孵出了一座巨大的蜘蛛巢。我们已经发生过几起严重中毒事件，我想取一些蜘蛛毒液研究，好研制治疗它们咬伤的解药。我可不是战士，$N。你愿意把我需要的毒液带来吗？",
  },
  [26915] = {
    ["T"] = "沼泽恐魔",
    ["O"] = "杀死10个纠缠恐魔和3个沼泽行者长老，然后返回斯通纳德的祖恩达萨那里。",
    ["D"] = "西北方是迷雾谷，那里曾经是一片郁郁葱葱、美丽的森林生命之地。最近，一场元素恐魔的灾祸占据了山谷。\n\n联盟可能会把那座山谷当作攻击斯通纳德的集结地，所以控制它符合我们的最大利益。去迷雾谷，清除那里的元素，$N。为了斯通纳德！",
  },
  [26922] = {
    ["T"] = "沼泽芦苇",
    ["O"] = "收集8根沼泽芦苇，并返回斯通纳德的苏塔佐尔那里。",
    ["D"] = "这片沼泽有许多奇异的草药和野生生物。我的工作就是检验它们是否能为斯通纳德提供药用价值。\n\n特别是有一种名为沼泽芦苇的草药，生长在西北方的迷雾谷。我希望你从那里带回一些样本，好让我测试它们可能的用途。",
  },
  [26924] = {
    ["T"] = "通缉：塔穆拉",
    ["O"] = "杀死塔穆拉，并把她的头带给斯通纳德的祖恩达萨。",
    ["D"] = "小心北部沼泽，一头名为塔穆拉的致命狮子在那里游荡。这头凶残的野兽迫使斯通纳德发布了击杀命令——不惜一切手段。强烈建议追捕这项悬赏的冒险者不要独自面对她。如果你成功了，就把塔穆拉的头带给斯通纳德的祖恩达萨领取奖赏。",
  },
  [26965] = {
    ["T"] = "遵守着装规范",
    ["O"] = "杀死夏洛特，并把她的吐丝器带给伊莎贝尔·皮克曼。",
    ["D"] = "你出去为制服收集材料的时候，我织机上的梭子坏了。如果我们必须从诺森德寄来替换品，那会花很长时间，但幸运的是，我知道本地有个解决办法。\n\n本地蜘蛛群的主母是一只巨大的野兽，当地人称她为夏洛特。她的吐丝器应该和我织机所需的尺寸很接近。你可以在邪石农场西北方的一个洞穴里找到她。把这当成你的第一次额外学分机会吧。",
  },
  [28492] = {
    ["T"] = "本戈尔的委托",
    ["O"] = "本戈尔要你使用急救技能制作20条厚丝质绷带，并把订单带给悲伤沼泽斯通纳德的本戈尔。",
    ["D"] = "我的身体疼痛，$C，但别想着用治疗魔法碰我。我不想沾上任何这种“圣光”。\n\n常规医药能治我的伤，要么我就接受死亡。如果你能拿出20条厚丝质绷带，我也许还能重新站起来。",
  },
  [28552] = {
    ["T"] = "罗格瓦尔的委托",
    ["O"] = "罗格瓦尔要你使用草药学技能收集20株枯叶草，并把订单带给悲伤沼泽斯通纳德的罗格瓦尔。",
    ["D"] = "沼泽隐藏着许多危险，我们的斥候已经以惨痛方式发现了这一点。我想制作一些药剂，让他们像本地的美洲虎一样消失在迷雾中。\n\n我看得出你擅长采药。给我带来20株枯叶草，我会把这事办成。",
  },
  [28629] = {
    ["T"] = "步兵祖尔的委托",
    ["O"] = "步兵祖尔要你使用剥皮技能收集5片绿色幼龙鳞片，并把订单带给悲伤沼泽斯通纳德的步兵祖尔。",
    ["D"] = "那边那个，拿剥皮刀的。我需要你的协助！\n\n这个人类坚持说沼泽让他做噩梦。他声称自己需要一条用绿色幼龙鳞片制成的毯子，才能睡得好些。\n\n我们接到命令要保住他的命，而我也想别再听他抱怨了。所以，你能弄来他想要的鳞片吗？",
  },
  [28666] = {
    ["T"] = "格瑞姆纳尔的委托",
    ["O"] = "格瑞姆纳尔要你使用采矿技能收集5块金锭，并把订单带给悲伤沼泽斯通纳德的格瑞姆纳尔。",
    ["D"] = "金子！战争中联盟的护甲闪着金光。我永远忘不了那种明亮的光泽。\n\n不过，自从我们返回斯通纳德以来，我一直没有机会再摆弄它。也许你可以带些金锭来弥补这一点？",
  },
  [28714] = {
    ["T"] = "费泽鲁尔的委托",
    ["O"] = "费泽鲁尔要你使用裁缝技能制作4条深红丝质马裤，并把订单带给悲伤沼泽斯通纳德的费泽鲁尔。",
    ["D"] = "$C……你是裁缝，对吧？朋友，我是私下问你的。我当时出去，呃……方便一下……结果一只鳄鱼从沼泽里蹿出来扑向我。在我那种……没穿好的状态下，它除了我的裤子什么也没咬到。但现在我需要几条替换的。\n\n我愿意为你的服务付钱。别担心，长袍暂时还能遮住……",
  },
  [28720] = {
    ["T"] = "费泽鲁尔的委托",
    ["O"] = "费泽鲁尔要你使用裁缝技能制作1件暗纹护肩，并把订单带给悲伤沼泽斯通纳德的费泽鲁尔。",
    ["D"] = "既然你把我的裤子做得这么好，我还有另一件工作交给你！这次我需要一副新护肩，暗纹套装里的那种。你觉得自己能帮我搞定吗？",
  },
  [26317] = {
    ["T"] = "阿塔莱石板",
    ["O"] = "从阿塔哈卡神庙收集阿拉尼石板和加卡里石板。",
    ["D"] = "据说住在悲伤沼泽沉没的阿塔哈卡神庙里的阿塔莱巨魔，保有两块我想研究的古老石板。\n\n考虑到他们会在我开口询问前就杀了我，我需要一个冒险者下去把它们取回来。对这活儿感兴趣吗？",
  },
  [26375] = {
    ["T"] = "冲突号召：悲伤沼泽",
    ["O"] = "在悲伤沼泽内找到并杀死5名部落成员。",
    ["D"] = "悲伤沼泽属于联盟，我们必须不断证明这一点。追猎部落成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26376] = {
    ["T"] = "冲突号召：悲伤沼泽",
    ["O"] = "在悲伤沼泽内找到并杀死5名联盟成员。",
    ["D"] = "悲伤沼泽属于部落，我们必须不断证明这一点。追猎联盟成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26837] = {
    ["T"] = "巨魔魔法",
    ["O"] = "从沉没的神庙收集琥珀、蓝色和绿色巫毒羽毛。",
    ["D"] = "啊！还不够强！我早该知道这样行不通。只有巨魔自己被诅咒的巫毒，才能抵消他们的灵魂魔法。\n\n在遥远的南方，悲伤沼泽里，有个地方叫沉没的神庙。那些名叫米杉、祖罗、祖罗尔、洛若尔、加什尔和胡库的巨魔携带着灌注了可怕巫毒的羽毛。杀掉这些害虫，把他们的羽毛带给我。",
  },
  [26916] = {
    ["T"] = "卡拉波炖菜",
    ["O"] = "从悲伤沼泽东部海岸沿线的淤泥蟹身上收集10只巨型蟹爪。",
    ["D"] = "这里要喂的嘴太多了，我几乎没法让一锅卡拉波炖菜一直煮着。如果我能做出足够大的一锅，就能让大家好几天都吃得高高兴兴。你愿意帮我弄些食材吗？在遥远的东方，沿着海岸，你会找到淤泥蟹。我要它们最大、最多汁的蟹爪。",
  },
  [26921] = {
    ["T"] = "沼泽皮料",
    ["O"] = "从悲伤沼泽的锯齿钳嘴龟身上收集8张结实的鳄鱼皮，并从暗影黑豹身上收集8张坚韧的黑豹皮。",
    ["D"] = "嘘，嘿，你。对，就是你！\n\n早些时候我看见你给玛萨特带去一捆皮，我在想你能不能帮我做个小项目。玛萨特是镇上产量最高的制皮匠，但他的手艺很粗糙。我觉得如果我能做出足够高质量的东西，就能接手为卫兵配备装备。你愿意也给我弄些皮来吗？它们必须比玛萨特要的那些垃圾质量高得多。\n\n往遥远的东方去，你会找到锯齿钳嘴龟和暗影黑豹。把它们的皮带给我。",
  },
  [27937] = {
    ["T"] = "安全之忧",
    ["O"] = "在悲伤沼泽东北边缘维吉·玛格利泽隐蔽实验室附近与她交谈。",
    ["D"] = "一位著名地精科学家需要你的协助，$C。她一直在努力抵挡闯入悲伤沼泽实验室的窃贼，想找人测试几项新的反制措施。\n\n这听起来有点夸张，但据说如果你参与其中，就能磨炼心智，并获得逃离任何处境的能力——很像侏儒那样。\n\n上面说只招募认真的冒险者。你有兴趣吗？",
  },
  [28041] = {
    ["T"] = "鳞甲工匠",
    ["O"] = "卡拉娜要你从世界各地收集各种鳞片。作为专家，你认为合适的鳞片是5片黑龙鳞片、5片厚蝎鳞、5片厚重石化蜥蜴鳞片和5片龟壳。收集这些东西，把它们带回悲伤沼泽避难营的卡拉娜那里。",
    ["D"] = "阿卡尔赫克塔，流浪者。你是某种制皮匠，对吧？那我想我们可以达成一项互利的协议。在德拉诺——如今被称作……外域的地方，我会用无数生物的鳞片制作美丽的鳞甲锁甲，其中大多数生物很可能已经不复存在了。不过这个世界有许多新的鳞片可供我制作。\n\n我希望你为我带来你们世界各地的各种鳞片。我知道这个请求很重，但作为回报，我会给你一张我珍藏的图样。",
  },
  [28462] = {
    ["T"] = "托克卡尔的委托",
    ["O"] = "加拉什要你使用工程学技能制作10个水下诱鱼器，并把订单带给悲伤沼泽迷雾芦苇岗哨的托克卡尔。",
    ["D"] = "嘿，$C。我们派了一名先遣斥候去东边的海边，负责保障我们的食物供应。我听说有一种叫水下诱鱼器的鱼饵，能帮助他们在海里捕鱼。我可真想吃些新鲜捕来的鱼！你不会认识能做那东西的人吧？",
  },
  [28480] = {
    ["T"] = "旅店老板芬米尔的委托",
    ["O"] = "旅店老板芬米尔要你使用急救技能制作20条厚丝质绷带，并把订单带给悲伤沼泽避难营的旅店老板芬米尔。",
    ["D"] = "避难营里的流亡者承受了太多。疾病、伤口，再加上从破碎世界跋涉而来的漫长旅程，他们几乎没有什么可用于治疗的东西了。\n\n如果你能拿出20条厚丝质绷带，我会确保它们送到最需要的德莱尼手中。这不算多，但即使是一块简单柔软的布，也能带来希望。",
  },
  [28527] = {
    ["T"] = "玛格图尔的委托",
    ["O"] = "玛格图尔要你使用草药学技能收集20株枯叶草，并把订单带给悲伤沼泽避难营的玛格图尔。",
    ["D"] = "沼泽隐藏着许多危险，我们的斥候已经以惨痛方式发现了这一点。我想制作一些药剂，让他们像本地的美洲虎一样消失在迷雾中。\n\n我看得出你擅长采药。给我带来20株枯叶草，我会把这事办成。",
  },
  [28575] = {
    ["T"] = "看守者玛纳尔的委托",
    ["O"] = "旅店老板芬米尔要你使用制皮技能制作6副绿色皮护腕，并把订单带给悲伤沼泽避难营的看守者玛纳尔。",
    ["D"] = "我们的看守者要抵御美洲虎和鳄鱼、元素和狂乱的鱼。他们在制服这些生物时，需要护腕保护手腕。你看起来很擅长处理皮革和针线。能帮帮他们吗？",
  },
  [28600] = {
    ["T"] = "托克卡尔的委托",
    ["O"] = "祖恩达萨要你使用制皮技能制作6副绿色皮护腕，并把订单带给悲伤沼泽迷雾芦苇岗哨的托克卡尔。",
    ["D"] = "我们的斥候要抵御美洲虎和鳄鱼、元素和狂乱的鱼。他们在制服这些生物时，需要护腕保护手腕。你看起来很擅长处理皮革和针线。能帮帮他们吗？",
  },
  [28612] = {
    ["T"] = "莫鲁尔的委托",
    ["O"] = "莫鲁尔要你使用剥皮技能收集5片绿色幼龙鳞片，并把订单带给悲伤沼泽避难营的莫鲁尔。",
    ["D"] = "啊。一个本世界人。一个带着剥皮工具的人。\n\n这个世界很奇怪——它的野兽、天空、气味。但皮革仍然是皮革，而我仍然了解自己的手艺。\n\n我对南方那些小龙很感兴趣。给我带来5片绿色幼龙鳞片。有了它们，我就能制作适合这个地方的护甲。",
  },
  [28642] = {
    ["T"] = "莫鲁尔的委托",
    ["O"] = "莫鲁尔要你使用采矿技能收集5块金锭，并把订单带给悲伤沼泽避难营的莫鲁尔。",
    ["D"] = "在我的世界，护甲由纤维和芦苇、水晶和光编织而成。但在这里，你们用金属塑造它。\n\n我听说金子很柔软，易于弯曲和塑形。给我带来10块金锭，好让我学习你们的方法，制作一些美丽的东西。",
  },
  [26318] = {
    ["T"] = "血神祈求",
    ["O"] = "从阿塔哈卡神庙内的阿塔莱巫医和阿塔莱高阶祭司身上收集4份阿塔莱卷轴。",
    ["D"] = "在找活儿吗，伙计？我需要一个勇敢的灵魂前往南方的沼泽。\n\n在沉没的神庙里，你会找到高阶祭司和巫医。这些巨魔带着一些卷轴，上面写着血神哈卡本人疯狂的预言。我一直在盯着他的追随者，而这些卷轴能帮上忙。你怎么说？",
  },
  [26466] = {
    ["T"] = "正义试炼",
    ["O"] = "把巫毒羽毛带给亡灵壁垒的乔纳森·贝雷斯福德。",
    ["D"] = "有了这些惰性天灾石，我们就能打造一件武器，将它们的力量反过来用于对付天灾军团。不过，要按我们所需的方式让邪恶之力反噬自身，还需要强大的魔法。\n\n正巧，有个名为沉没的神庙的地方，拥有完成这项任务所需的那种魔法。在你试炼的最后阶段，你必须前往那座神庙，消灭那些持有这种魔法的巨魔。他们的名字是加什尔、胡库、洛若尔、米杉、祖罗和祖罗尔。",
  },
  [26913] = {
    ["T"] = "欧克尼尔心爱的鱼竿",
    ["O"] = "从避难营南方的渔船上收集欧克尼尔遗弃的鱼竿。",
    ["D"] = "一段时间以前，一位非常友好的人类路过这里，教我建造理论上比我们的小皮艇更稳定的渔船。我们花了好几天辛苦劳作后，那个人类和我终于把它开出去试了试。你敢信吗——一只鳄鱼咬了那该死的船，然后它就开始下沉！我们差点没能活着回来！\n\n我们把船遗弃在这里南边，接着我才知道，那个人类没回去帮我取回那些特别抛光过的鱼竿，就直接离开了镇子。你能替我找到那艘船，把我的鱼竿找回来吗？",
  },
  [26914] = {
    ["T"] = "欧克尼尔心爱的鱼竿",
    ["O"] = "从避难营东边的失落者渔夫身上收集一根完好的抛光鱼竿。",
    ["D"] = "听着，这里是沼泽。这一带没多少人在钓鱼，所以我只能想到一个拿走我鱼竿的群体：东边的失落者。他们之中有些粗陋的渔夫，我敢打赌其中一个拿着它。搜查那些失落者，替我把它取回来好吗？",
  },
  [26917] = {
    ["T"] = "八足肉排",
    ["O"] = "从避难营东南方的致命刺击狼蛛身上收集10块肥美蜘蛛肉排。",
    ["D"] = "如果我想做出一锅出色的炖菜，我们就需要尽可能多的肉。只有最好的品质才能恢复卫兵所需的精力。在这里东南方，你会找到致命刺击狼蛛。它们的肉多汁又美味。越大越好！去替我踩扁几只蜘蛛，切下它们的肉排。",
  },
  [26919] = {
    ["T"] = "卡拉波火焰炖菜",
    ["O"] = "把卡拉波火焰炖菜送给避难营的居民。",
    ["D"] = "我觉得这是我这段时间以来做出的最好炖菜。它的味道和热辣会为我的人民带来对故乡的温暖回忆。\n\n你愿意把它分发给我的德莱尼同胞吗？既然你为准备它帮了这么多忙，由你来接受他们的感谢才合适。",
  },
  [26920] = {
    ["T"] = "沼泽皮料",
    ["O"] = "为玛萨特·坦德尔收集8张厚鳄鱼皮和8张结实的美洲虎皮。",
    ["D"] = "有时我会怀念家乡的野兽……它们的皮……它们的毛……全都精美无比。这个星球看起来也许正适合我继续做我的生意。\n\n不过，我的补给已经非常短缺了。你能从这片沼泽的野兽身上给我弄些皮来吗？最好是沼泽美洲虎和幼年锯齿鳄鱼的皮，因为它们很适合鞣制。",
  },
  [26923] = {
    ["T"] = "通缉：斯宾纳瑞特",
    ["O"] = "找到避难营东边的斯宾纳瑞特并消灭它。",
    ["D"] = "夜里，我们的人民会无声无息地失踪。由于现场留下了大量黏稠残留物，我怀疑罪魁祸首是一只生活在沼泽里的巨大蛛形生物。任何成功消灭这场噩梦的冒险者都将得到奖赏！\n\n\n——看守者玛纳尔",
  },
  [27938] = {
    ["T"] = "挑战路线",
    ["O"] = "穿过北方崖边小路上的维吉·玛格利泽挑战路线，然后在她的实验室与她交谈。",
    ["D"] = "我搬到这里，就是为了不让窃贼找到我。“没人会跑到这个阴沉沉的烂泥桶来！”我当时这么说。我才安顿下来几个月，他们就像蝗虫一样涌来了！\n\n我已经停下所有研究，只为了先设计出保护它的办法！我想测试一下我的新防御。\n\n觉得自己能胜任吗？我会紧盯着你，做笔记……希望你不是那种被观察就崩溃的人，小子。\n\n我会付钱给你，而且你说不定还能顺便学点新东西。准备好后，就沿北边的小路上去——但你最好快点！我会计时的。祝你好运，要是死了可别回来缠着我。",
  },
  [26127] = {
    ["T"] = "奥特兰克先令",
    ["O"] = "把奥特兰克先令带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚奥特兰克先令。\n\n这枚硬币大约在二十年前铸造，正值艾登·匹瑞诺德国王统治的末日。一面有国王侧脸磨损的轮廓，另一面则是一只群星环绕的俯冲雄鹰；那是奥特兰克旧王国的象征。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26128] = {
    ["T"] = "亚基尤努西",
    ["O"] = "把亚基尤努西带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚亚基尤努西。\n\n这是古神那些较近似人形的仆从所使用货币的罕见样本。它的表面似乎在吸收光线，而不是反射光线。尽管躺在沙漠烈日下，它的表面不知为何仍摸起来油腻。握在手里时，你感到有些不安。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26129] = {
