    ["O"] = "把阿塔莱里亚尔带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚阿塔莱里亚尔。\n\n这是短命的古拉巴什帝国的一枚硬币。传说它们是在献给血神哈卡的敌人鲜血中铸成的。硬币确实泛着红色。\n\n稀有硬币收藏家会对这件物品感兴趣。",
