    ["D"] = "你找到了一枚黑铁斯塔特。\n\n这些硬币正逐渐退出流通，取而代之的是一批新铸币，其图案用于纪念与暮光之锤的结盟。\n\n稀有硬币收藏家会对这件物品感兴趣。",
