  [26146] = {
    ["T"] = "库尔提拉斯克朗",
    ["O"] = "把库尔提拉斯克朗带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚库尔提拉斯克朗。\n\n这枚沉重的金币是库尔提拉斯财富与权力的标志，只在最有影响力的商人与船长之间流通。尽管边缘已被多年海上贸易磨损，它仍是一件引人注目的航海史遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26147] = {
    ["T"] = "库尔提拉斯法辛",
    ["O"] = "把库尔提拉斯法辛带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚库尔提拉斯法辛。\n\n这枚朴素的铜币曾在库尔提拉斯繁忙港口中无数水手和码头工人手里流转。虽然它没有多少物质价值，但它在海员日常生活中的角色，使它成了一件具有文化意义的遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26148] = {
    ["T"] = "军团派萨",
    ["O"] = "把军团派萨带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚军团派萨。\n\n这枚诡异、染着邪能的硬币带有燃烧军团鲜明的影响。虽然大多数人都明智地避免接触与恶魔力量有关的物品，但研究者和地狱遗物收藏家也许会把它视为无价发现。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26149] = {
    ["T"] = "军团卢比",
    ["O"] = "把军团卢比带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚军团卢比。\n\n这枚不祥、宝石般的硬币微微发出邪能光芒，是军团扭曲经济的残余。它曾在他们的黑暗领域中用于交易，来历或许邪恶，但其稀有性让它成为一件引人注目的遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26150] = {
    ["T"] = "洛丹伦克朗",
    ["O"] = "把洛丹伦克朗带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚洛丹伦克朗。\n\n这枚王室风格的金币曾在洛丹伦的贵族和商人间流通，上面刻着一个曾经伟大王国的徽记。尽管洛丹伦早已沦为废墟，它的遗产仍在这样的遗物中延续。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26151] = {
    ["T"] = "洛丹伦法辛",
    ["O"] = "把洛丹伦法辛带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚洛丹伦法辛。\n\n这枚小铜币曾是洛丹伦日常生活的一部分，在市场和酒馆中经过无数人的手。如今，它成了一个被历史和悲剧吞没的王国的遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26152] = {
    ["T"] = "洛丹伦便士",
    ["O"] = "把洛丹伦便士带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚洛丹伦便士。\n\n这枚朴素的硬币曾常见于洛丹伦市民的口袋。尽管设计简单，它如今作为一个陨落王国最后残余之一，拥有了感情与历史价值。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26153] = {
    ["T"] = "达拉然先令",
    ["O"] = "把达拉然先令带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚达拉然先令。\n\n这枚硬币微微嗡鸣着奥术能量，是达拉然这座魔法城市曾经繁荣魔法经济的产物。尽管不再流通，它仍是肯瑞托金融体系中一件迷人的遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26154] = {
    ["T"] = "吉尔尼斯克朗",
    ["O"] = "把吉尔尼斯克朗带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚吉尔尼斯克朗。\n\n这枚沉甸甸的银币曾是吉尔尼斯的常用货币，直到那个王国与世界隔绝。它精细的设计体现了一个独立于世的民族的工艺与骄傲。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26155] = {
    ["T"] = "纳迦大贝币",
    ["O"] = "把纳迦大贝币带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚纳迦大贝币。\n\n这种奇异货币由巨大的抛光贝壳制成，用于纳迦的易货体系。它虹彩般的表面微微发光，这是纳迦宝物中常嵌有奥术附魔的迹象。\n\n稀有硬币收藏家会对这件物品感兴趣。",
