  [26156] = {
    ["T"] = "纳迦小贝币",
    ["O"] = "把纳迦小贝币带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚纳迦小贝币。\n\n这种较小的贝壳币常用于纳迦交易，表面光滑，几乎半透明。它对地表居民没什么用处，却仍是来自深海的罕见而引人入胜的遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
