    ["O"] = "把熊猫人圆币带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚熊猫人圆币。\n\n这枚圆形、精巧铸造的硬币带有潘达利亚优雅的文字和图像。它曾在商人与茶商之间流通，其艺术性与历史使它成为珍贵发现。\n\n稀有硬币收藏家会对这件物品感兴趣。",
