    ["O"] = "把来历不明的硬币带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚来历不明的硬币。\n\n这枚神秘硬币上有着不同于任何已知文明的符号和标记。它究竟属于被遗忘的王国、失落的种族，还是某种更加邪恶的东西，谁也说不准。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26164] = {
    ["T"] = "风险投资公司欠条",
    ["O"] = "把风险投资公司欠条带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一张风险投资公司欠条。\n\n这张匆忙写下、盖着风险投资公司标志的纸条，承诺会偿付已提供的服务。考虑到这家公司的名声，它的实际价值充其量也很可疑——但对合适的收藏家来说，连坏账也有价值。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26165] = {
    ["T"] = "风险投资公司凭券",
    ["O"] = "把风险投资公司凭券带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一张风险投资公司凭券。\n\n这份看似正式的文件赋予持有人从风险投资公司获得货物或服务的权利——至少理论上是这样。虽然它是否有效很可疑，但其稀有性让它成了一件有趣且可能有价值的发现。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26166] = {
    ["T"] = "蛮锤弗罗林",
    ["O"] = "把蛮锤弗罗林带给藏宝海湾的阿尔塔德娜。",
    ["D"] = "你找到了一枚蛮锤弗罗林。\n\n这枚由蛮锤矮人铸造、被风磨蚀的硬币带有风暴与天空的象征。虽然它很少用于贸易，但其稀有性以及与高地氏族的联系，使它成为一件独特的历史遗物。\n\n稀有硬币收藏家会对这件物品感兴趣。",
  },
  [26180] = {
    ["T"] = "钳嘴龟零食",
    ["O"] = "收集8块石斑鱼排和12根王咬芦苇茎，用来制成钳嘴龟零食。",
    ["D"] = "如果有一整个洛阿化身成海龟，那它们一定是非常特别的生灵。我不是赞达拉人，我妈也不是，但我一直爱听她讲所有巨魔崇拜哪些洛阿的故事。\n\n恶齿部族消耗了大量龟肉，有时甚至只是为了取乐而杀它们。这让我恶心。\n\n我想给这些海龟献上一份连托加都会满意的供品。我见过它们吃一种特殊的芦苇，还有一种鱼，有时会从上游河里被冲到这里的海岸。你能替我收集一些，再从那种鱼身上取些鱼排来吗？这样我就能给它们做一份美味点心。",
  },
  [26285] = {
    ["T"] = "迪格丢失的烟斗",
    ["O"] = "从闪泥矿井内的墨潜身上找回迪格丢失的烟斗，并把它带给藏宝海湾的迪格。",
    ["D"] = "没有点小毛病的人生还有什么意思，对吧，$C？\n\n可惜，自从我在镇东边的海滩上把最爱的烟斗弄丢以后，就一直没法抽它了。我当时有点，呃，喝得东倒西歪，你懂我的意思吧；等我清醒过来，就看见一个大鱼人带着它跑了！\n\n看起来那个鱼人已经在闪泥矿井里安了家。如果你正好去那边，又有机会拿到我的烟斗，我会非常感激。",
  },
  [26287] = {
    ["T"] = "棱彩鳞片",
    ["O"] = "从闪泥矿井内的一只石化蜥蜴身上收集棱彩鳞片，并把它们带给藏宝海湾的崔斯里克。",
    ["D"] = "既然你在完成我那批精制靴子的订单时这么帮忙，我想你也该帮帮我的实验性新设计。\n\n我要从鳄鱼皮扩展到石化蜥蜴——但不是随便哪只石化蜥蜴。我要最好的。我听说风险投资公司在闪泥矿井里发现了一只又大、又亮、又特别的石化蜥蜴。那就是我需要的。去那里，把它的鳞片带给我！",
  },
  [26292] = {
    ["T"] = "隧道怪物",
    ["O"] = "搜索闪泥矿井，找到艾莉丝·寻潮描述的怪物并摧毁它。",
    ["D"] = "我知道这对一个精灵来说不寻常，但我热爱大海。我曾花许多时间漂浮在藏宝海湾东边的浅水里，与鱼和鸟交朋友。我从未感到害怕……直到最近。\n\n我漂得比平常更靠北时，某种巨大而神秘的触须从海底伸上来抓住了我的腿！那生物试图把我拖进一条水下隧道，但我奋力反抗。最后，它松开了我，消失进隧道里……而隧道在它身后坍塌了。\n\n我想那生物也许就住在风险投资公司在镇北山里开设的那处挖掘场。我试着警告他们，但他们不理我。拜托，如果你进入那些矿井，留心那个怪物！我害怕还有别人毫无防备地遇到它。",
  },
  [26344] = {
    ["T"] = "你帮我，我帮你……",
    ["O"] = "在荆棘谷找到头目奥格索普并消灭她。",
    ["D"] = "我猜你在找那颗宝珠所属的其余宝藏，我有个好消息——它们整批埋在我们俘获那艘船的地方附近。坏消息是，我只知道位置的一部分。布莱克斯通把坐标分给了我、温克斯和小子。所以你得去找他们，拿到剩下的信息。\n\n不过首先——我和一个敌对财阀成员有点小麻烦。自从离开布莱克斯通船员后，我一直给黑水海盗打零工，也不止一次和风险投资公司的头目奥格索普交火。我已经厌倦了每次踏出藏宝海湾都要提防背后。替我除掉她，我就告诉你想知道的事。\n\n她在荆棘谷某处有个小基地，但我不知道在哪。",
  },
  [26381] = {
    ["T"] = "冲突号召：荆棘谷",
    ["O"] = "在荆棘谷内找到并杀死5名部落成员。",
    ["D"] = "荆棘谷属于联盟，我们必须不断证明这一点。追猎部落成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26382] = {
    ["T"] = "冲突号召：荆棘谷",
    ["O"] = "在荆棘谷内找到并杀死5名联盟成员。",
    ["D"] = "荆棘谷属于部落，我们必须不断证明这一点。追猎联盟成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26758] = {
    ["T"] = "野兽的本性",
    ["O"] = "杀死名为暮翼的邪恶生物，然后回到东瘟疫之地皇冠哨塔附近的帕特里斯·厄尔加丁女士那里。",
    ["D"] = "向你致意，冒险者！能在这片荒凉之地遇见一张友善的面孔，我感到很宽慰。\n\n我的丈夫作为猎人在荆棘谷成名。我想通过猎杀瘟疫之地的怪物来超越他的名声，但我发现自己被这片熟悉土地的毁灭所带来的悲伤压倒了。比如这所房子，曾经属于亲爱的朋友。\n\n我们不该追逐战利品，而必须帮助摧毁天灾军团创造出的可怕生物。一只名为暮翼的巨大白化恶魔蝙蝠在玛瑞斯农场北方的乡野间出没。如果你能协助摧毁这个邪恶生物，我将不胜感激。",
  },
  [26880] = {
    ["T"] = "给萨曼莎的药膏",
    ["O"] = "从荆棘谷东北部库尔森营地的库尔森驯兽师身上收集4份振奋丛林药膏。",
    ["D"] = "萨曼莎有高贵的灵魂，但没有速度保护她远离危险，她就缺乏信心。如果我们恢复她的信心，也许她会继续寻找自己的治愈之法。\n\n在丛林遥远的东北部，一群人类建立了营地。那里的库尔森驯兽师携带一种药膏，用来振奋他们训练的战豹。杀掉这些入侵的人类，取回一些药膏。",
  },
  [26881] = {
    ["T"] = "给萨曼莎的药膏",
    ["O"] = "从荆棘谷北部的薄雾谷猩猩身上收集6瓶温热的血液。",
    ["D"] = "沿道路向北前往库尔森营地时，你也许穿过了薄雾谷猩猩的领地。这些凶暴野兽的血将构成我们药膏的另一部分。\n\n杀掉它们，给我带回半打温热血液！你回来得越快，我们就能越早帮助萨曼莎。",
  },
  [26884] = {
    ["T"] = "洗劫掠夺者",
    ["O"] = "从血顶墓穴找回4件达尔特里的财物。",
    ["D"] = "看见我们周围这些废墟了吗，$C？这就是我爷爷试图在丛林里建个家的全部遗迹。我来到这里，是想看看还能找回什么。\n\n几十年前，血顶巨魔袭击了农场，屠杀了家族的大多数人。他们还抢走了所有贵重物品。问题是，我听说巨魔会把一些战利品和死者一起埋葬。祖丹亚废墟北边有一座血顶的大墓穴。我只是个穷农民，但如果你愿意去那座墓穴里找找我家被抢走的财物，我会很乐意奖赏你。",
  },
  [26885] = {
    ["T"] = "我的朋友，劈颅巨魔",
    ["O"] = "在荆棘谷西北部的血顶巨魔中找到传说讲述者伊兹利的朋友图特克。",
    ["D"] = "嘿，伙计，我非常需要帮助。\n\n我一直想联系其他丛林氏族，帮忙记录我们共同的历史，最后终于和一个劈颅巨魔成了朋友。他本该在格罗姆高外的路上见我，但他一直没出现。\n\n与此同时，我们收到报告，说一支劈颅战队突袭了血顶巨魔，却被击败。金维利说我朋友的灵魂不在灵魂领域，所以他一定是血顶巨魔的俘虏。\n\n请找到他，$C，看看他需要什么帮助。他的名字叫图特克。",
  },
  [26887] = {
    ["T"] = "我的朋友，劈颅巨魔",
    ["O"] = "为荆棘谷格罗姆高的传说讲述者伊兹利收集6根野葡萄藤、4颗大牙齿和一份血顶萨满精华。",
    ["D"] = "血神已经死了，$C。图特克不能白白死去。但有一种古老的方法，能帮助他挽救自己部族的荣耀，也让他继续帮我。\n\n首先，我们必须收集一些材料。我们需要一些野葡萄藤——它在谷地各处自然生长。然后是大牙齿——试试迅猛龙或老虎。最后，还要一份血顶萨满的精华。你可以在这里北边海滩上的巴拉尔废墟找到一些。",
  },
  [26888] = {
    ["T"] = "我的朋友，劈颅巨魔",
    ["O"] = "搜索巴拉尔、特卡希、祖丹亚和卡莱废墟，找到一只血火盆，并把它带给格罗姆高的传说讲述者伊兹利。",
    ["D"] = "既然我们有了这些材料，我还需要你从血顶废墟里取另一件东西——一只血火盆。\n\n我们巨魔已经存在了数万年，废弃的古老方法不止一种。甚至在哈卡被击败之前，丛林巨魔就已经停止使用他们的血火盆了。但我知道他们一直留着那些东西。\n\n前往这里北边海滩和丛林中的巴拉尔、特卡希、祖丹亚和卡莱这些血顶废墟，找到一只血火盆。它可能在其中任何一处。",
  },
  [26889] = {
    ["T"] = "我的朋友，劈颅巨魔",
    ["O"] = "把传说讲述者伊兹利的补给带到祖玛维废墟的墓穴。",
    ["D"] = "西北海岸祖丹亚废墟北边，是血顶巨魔安葬受尊敬死者的墓穴。我用你带给我的材料制作了一种特殊熏香。你需要把这只火盆、图特克的护符和精华带到墓穴。在中央墓室点燃精华。\n\n图特克的灵魂会出现，而他的身体仍留在血顶巨魔那里。\n\n什么？有一个灵魂朋友，总比没有朋友强吧？",
  },
  [26893] = {
    ["T"] = "野兽盟友",
    ["O"] = "在荆棘谷东部海岸找到偷猎者首领，并发现更多有关买家的证据。",
    ["D"] = "一座岛？一个肥猫买家？一个首领？这也太多了！我又需要你的帮助了，$N。沿东边海岸追踪这个营地，自己再进行一些狩猎。看看这个W.P.有什么可说的，并进一步查明他们的买家。我们必须从根部烧掉这棵树。",
  },
  [26894] = {
    ["T"] = "野兽盟友",
    ["O"] = "在藏宝海湾伏击西迪斯·暗狙。",
    ["D"] = "我们终于知道头目的名字和所在地了：藏宝海湾。我一点也不惊讶。拿着这只哨子，去找他。一旦找到，就吹响哨子，我的朋友们会来给那个贪婪的毛皮商一点报应。",
  },
  [26902] = {
    ["T"] = "停止缩头",
    ["O"] = "从祖昆达废墟的血顶巨魔手中释放8名联盟冒险者。",
    ["D"] = "这里西南方是祖昆达的血顶巨魔，他们以制作皱缩头颅的技艺闻名整个荆棘谷。但似乎没人谈论的是：到底是谁的头被缩小了！\n\n他们一直在整个荆棘谷各处抓捕冒险者，带给他们的巫医。请在那些人最后被绑到某个血顶巨魔脖子上之前，把他们从囚禁之处释放出来。",
  },
  [26903] = {
    ["T"] = "停止缩头",
    ["O"] = "从祖昆达废墟的血顶巨魔手中释放8名部落冒险者。",
    ["D"] = "这里西北方是祖昆达的血顶巨魔，他们以制作皱缩头颅的技艺闻名整个荆棘谷。但似乎没人谈论的是：到底是谁的头被缩小了！\n\n他们一直在整个荆棘谷各处抓捕冒险者，带给他们的巫医。请在那些人最后被绑到某个血顶巨魔脖子上之前，把他们从囚禁之处释放出来。",
  },
  [26904] = {
    ["T"] = "粗制头盔",
    ["O"] = "把实验性心灵控制头盔带给藏宝海湾里也许懂它的人。",
    ["D"] = "你手里找到了一堆粗糙拼凑在一起的电线、天线，以及不知为何固定在一顶旧金属头盔上的弹簧。\n\n也许如果你把它拿给藏宝海湾某个有才华的工程师看看，他们会知道该怎么处理？",
  },
  [26905] = {
    ["T"] = "粗制头盔",
    ["O"] = "在藏宝海湾北方的8只老年薄雾谷猩猩身上测试实验性心灵控制头盔。",
    ["D"] = "哎呀呀……这可真是独特的样本。很明显，这是风险投资公司试图制造心灵控制头盔的成果。但它既是我见过最糟糕的尝试，又不知为何同时很天才。\n\n我可不打算试，也怀疑你不会愿意让我对着你轰它，所以把它带去藏宝海湾北方的老年猩猩那里试试看。\n\n把它表现如何的报告带回来给我。",
  },
  [27183] = {
    ["T"] = "契约#1025：圣化布匹",
    ["O"] = "从斯坦索姆的血色领区内收集一卷圣化布匹。",
    ["D"] = "我有些工作可以给愿意组队的承包人。这里有一份来自我们想在藏宝海湾设立的免下车婚礼产业综合体的需求。\n\n契约#1025：从斯坦索姆内取得圣化布匹\n\n数量：一卷",
  },
  [27543] = {
    ["T"] = "毒皮鞍座",
    ["O"] = "前往藏宝海湾，从崔斯里克那里取回毒皮鞍座货物，然后把它带回安戈洛环形山的莫维克那里。",
    ["D"] = "我委托“鞣皮制皮店”的崔斯里克为我训练的毒皮暴掠龙制作鞍座。下一只现在应该可以取货了。你能跑一趟把它取回来吗？那家店在藏宝海湾的上层。\n\n有一点，$N——我不记得自己有没有付过鞍座的钱。如果还没有，你能替我付款吗？你回来后我会报销。",
  },
  [27602] = {
    ["T"] = "尤瓦中士的委托",
    ["O"] = "尤瓦中士要你使用炼金术技能制作5瓶精准药剂，并把订单带给荆棘谷反抗军营地的尤瓦中士。",
    ["D"] = "只要库尔森上校还拥有他的巫医制作的药剂和药水，我们就在打一场败仗。虽然我已经有任务去中断那些补给的流动，但我们自己也需要一点优势。\n\n我想委托你制作一些精准药剂并交给我。有了它们，我们就能压过库尔森的丛林战士一头。",
  },
  [27627] = {
    ["T"] = "尼姆布亚的委托",
    ["O"] = "尼姆布亚要你使用炼金术技能制作5瓶精准药剂，并把订单带给荆棘谷格罗姆高的尼姆布亚。",
    ["D"] = "只要其他森林和丛林巨魔还有他们的巫医，我们就在打一场败仗。我们自己也需要一点优势。\n\n我想委托你制作一些精准药剂并交给我。有了它们，我们就能压过其他巨魔一头。",
  },
  [27652] = {
    ["T"] = "多伦中尉的委托",
    ["O"] = "多伦中尉要你使用锻造技能制作1把青铜战斧、1把青铜巨剑和1把青铜战锤，并把订单带给荆棘谷北部反抗军营地的多伦中尉。",
    ["D"] = "很高兴在这里见到一名铁匠。正如你所见，我们还没有建立起像样的补给线，也没有自己的铁匠铺来持续生产武器。如果我能委托你为我制作一把青铜战斧、一把青铜巨剑和一把青铜战锤，我会很乐意为你今后的锻造工作提供一些补给。",
  },
  [27677] = {
    ["T"] = "赫米特·奈辛瓦里的委托",
    ["O"] = "瓦尔要你使用锻造技能制作1把青铜战斧、1把青铜巨剑和1把青铜战锤，并把订单带给荆棘谷北部奈辛瓦里远征队的赫米特·奈辛瓦里。",
    ["D"] = "很高兴在这里又见到一名铁匠。我收到那位矮人猎人赫米特·奈辛瓦里的制作请求。我猜联盟还没有建立补给线，所以没法帮他解决武器需求。\n\n我自己不太想冒险靠近联盟领地，所以如果我能委托你代替我制作一把青铜战斧、一把青铜巨剑和一把青铜战锤，并把它们送到赫米特的营地，我会很感激。",
  },
  [27956] = {
    ["T"] = "元素模拟",
    ["O"] = "取回纳胡文和伊拉格纳的元素核心。",
    ["D"] = "根据我的研究，我了解到暗夜精灵会依照太阳和月亮的循环获得祝福。\n\n我还读到，火元素和水元素也遵循类似的相对循环！它们的核心不仅能作为强大且可再生的组件，还能调节装置的效果。\n\n我知道燃烧平原有一个强大的火元素……而且也很凶。你可以在黑石山山脚下一个熔岩池里找到它。让我想想……我很确定还有一个强大的水元素，在荆棘谷野人海岸外的一座岛周围徘徊。那座岛上全是水元素，所以你不会错过！我是怎么知道这些存在的？我读到的！\n\n把它们的核心带回来给我，我们就能开始鼓捣了。",
  },
  [27992] = {
    ["T"] = "熔炉仪式",
    ["O"] = "与荆棘谷藏宝海湾的马克迦文交谈。",
    ["D"] = "你看起来很眼熟。经常待在熔炉旁吗？是的，你拥有我们需要的技能。\n\n我在藏宝海湾有个朋友，名叫马克迦文。你也许以前见过他，但如果没有，只要知道他和秘银会的所有成员都对解开金属与魔法的奥秘感兴趣。如果你也感兴趣，就去马克迦文的铁匠铺吧。他正在做一些超越这个世界的研究……",
  },
  [27993] = {
    ["T"] = "熔炉仪式",
    ["O"] = "荆棘谷藏宝海湾的马克迦文要你使用锻造技能制作2把乌木刀并带给他。",
    ["D"] = "所以我的朋友认为你拥有我解开冶金之谜所需的技能？那就来检验一下。\n\n我想让你为我制作一对乌木刀。如果你没有这些设计图，嗯，那得和死亡打个照面才能学会。正好这就是我们要研究的东西，所以这是一场完美的测试。\n\n还是困惑？去西瘟疫之地的通灵学院转转。你也许得在那里做些杂务，才能购买设计图，但那只会让你更有能力面对接下来的一切。",
  },
  [27994] = {
    ["T"] = "熔炉仪式",
    ["O"] = "进入东瘟疫之地的斯坦索姆，杀死黑衣守卫铸剑师。取回他的坏死之刃，并把它带给荆棘谷藏宝海湾的马克迦文。",
    ["D"] = "你曾经处理过坏死金属吗？你甚至听说过坏死金属吗？没有，对吧？嗯，它们确实存在，而我打算弄清它们如何运作。\n\n金属不是活物，所以它本来就不该会死，更不用说变成亡灵了。我听说天灾军团使用这种东西制成的刀刃，所以第一步就是弄到其中一把。\n\n斯坦索姆过去有一片宏伟的铸造区，而天灾军团不知用什么办法为他们无脑的战士打造刀刃，所以它一定在那里。前往东瘟疫之地，看看能从废墟里找回什么。你最好带上一些朋友。",
  },
  [27997] = {
    ["T"] = "熔炉仪式",
    ["O"] = "荆棘谷藏宝海湾的马克迦文要你使用锻造技能制作一对黑铁护肩和一把火山战锤。",
    ["D"] = "你离开期间，我已经把坏死之刃分解成了它的组成部分。但布莱恩的笔记表明，这也许并不是必要的。他推测坏死金属是普通金属在坏死能量作用下转化而成的！\n\n我们必须验证这个理论。布莱恩推荐了几件也许适合作为基底的物品。从这张清单里，不如你给我制作……一些黑铁护肩和一把火山战锤。\n\n如果你不知道这些设计图，嗯，黑铁护肩来自黑石山深处，而火山战锤的设计图可以从与瑟银兄弟会有关的人那里购买。",
  },
  [28049] = {
    ["T"] = "荒野仪式",
    ["O"] = "与荆棘谷奈辛瓦里远征队的赫米特·奈辛瓦里交谈。",
    ["D"] = "你听说消息了吗，$N？传奇猎人赫米特·奈辛瓦里正在寻找一名精英剥皮师，帮他处理一些战利品！\n\n这可是一份能写进履历的工作！如果你有兴趣，可以亲自去荆棘谷奈辛瓦里的营地申请。",
  },
  [28050] = {
    ["T"] = "荒野仪式",
    ["O"] = "把1片黑龙鳞片、1片蓝龙鳞片、1片绿龙鳞片和1片红龙鳞片带给荆棘谷奈辛瓦里远征队的赫米特·奈辛瓦里。",
    ["D"] = "我不能把这活交给随便哪个老剥皮师，$N，所以我需要你证明自己的资格。\n\n我猎杀过艾泽拉斯最危险的野兽，而其中最狡猾的就是龙。你不需要猎龙，但你确实需要剥几条龙，把它们的龙鳞带给我，证明你懂得如何使用剥皮刀。黑龙、蓝龙、绿龙和红龙的鳞片我各要一片。",
  },
  [28053] = {
    ["T"] = "荒野仪式",
    ["O"] = "赫米特·奈辛瓦里要你使用剥皮技能，从黑石塔下层收集哈雷肯的皮，并把它带给荆棘谷营地中的他。",
    ["D"] = "我不知道那位买家是从哪里弄到这些线索的，但显然黑石塔里的兽人有一对巨狼，为他们的狼骑兵提供坐骑。而我们的买家想要它们的皮。更具体地说，是一头名叫哈雷肯的狼的皮。\n\n现在我不知道你到底要怎么进入黑石塔，找到这头狼并剥下它的皮，但如果你能做到，对我们俩都有一份很不错的奖赏。",
  },
  [28054] = {
    ["T"] = "荒野仪式",
    ["O"] = "把一捆毛皮交给荆棘谷藏宝海湾的大财主里维加兹。",
    ["D"] = "你离开时，我给客户送了口信，告诉他你干得很好。嗯，他想见见你，亲自向你道谢。\n\n你也许已经猜到了，是个地精。他就在南边的藏宝海湾，名叫大财主里维加兹。我估计他是热砂财阀里的某个大人物。既然你要往那边去，不妨顺路把你收集的这些毛皮交给他。",
  },
  [28073] = {
    ["T"] = "海克拜瑞·斯莫特船长的委托",
    ["O"] = "海克拜瑞·斯莫特船长要你使用烹饪技能制作10份烧烤巨蚌，并把订单带给荆棘谷藏宝海湾的海克拜瑞·斯莫特船长。",
    ["D"] = "我现在有麻烦了，$C。我不仅把船长弯刀输给了那个怪物奈古拉什，还答应船员一进藏宝海湾就给他们一顿特别大餐。我一直没能兑现承诺，船员们开始不安分了。\n\n如果你愿意帮我，我正需要一大堆烧烤巨蚌。海盗重新出海前，就该用这种东西吊起胃口！",
  },
  [28390] = {
    ["T"] = "尤瓦中士的委托",
    ["O"] = "马克迦文要你使用附魔技能，为提供的1把高冲击钉锤附上附魔双手武器 - 次级冲击，并把订单带给荆棘谷反抗军营地的尤瓦中士。",
    ["D"] = "反抗军营地那边的尤瓦中士订了这把高冲击钉锤，但她想给它附魔，而我平常找的人出城了。你认识能帮忙的人吗？我会付给他们丰厚报酬。",
  },
  [28415] = {
    ["T"] = "指挥官阿格罗戈什的委托",
    ["O"] = "马克迦文要你使用附魔技能，为提供的1把高冲击钉锤附上附魔双手武器 - 次级冲击，并把订单带给荆棘谷格罗姆高营地的指挥官阿格罗戈什。",
    ["D"] = "格罗姆高营地那边的指挥官阿格罗戈什订了这把高冲击钉锤，但他想给它附魔，而我平常找的人出城了。你认识能帮忙的人吗？他们会得到丰厚报酬。",
  },
  [28440] = {
    ["T"] = "尤瓦中士的委托",
    ["O"] = "尤瓦中士要你使用工程学技能制作20个重磅青铜炸弹，并把订单带给荆棘谷反抗军营地的尤瓦中士。",
    ["D"] = "库尔森上校的部队龟缩在荆棘谷远处山丘的一处洞穴里。如果我们能用战术打击解决他和他的手下，那当然更好，但我们必须为攻势失败做好准备。\n\n这项准备包括一名有才华的工程师，比如你。\n\n我需要炸弹，$N。大的。具体来说，是一堆重磅青铜炸弹。如果最糟糕的情况发生，我们可以炸塌那座洞穴的入口，把库尔森困在里面。",
  },
  [28465] = {
    ["T"] = "指挥官阿格罗戈什的委托",
    ["O"] = "奥格索普·奥布诺提斯要你使用工程学技能制作20个重磅青铜炸弹，并把订单带给荆棘谷格罗姆高的指挥官阿格罗戈什。",
    ["D"] = "你好，$N！见到同为工程师的人总是件好事，哪怕你也是部落的一员。\n\n说到这个……格罗姆高的指挥官阿格罗戈什送来一张便条，要求一些重磅青铜炸弹。虽然我表面上在阵营冲突中保持中立，但我宁愿这份订单由一名部落工程师完成。也就是说，就是你！",
  },
  [28482] = {
    ["T"] = "加维克·污帆的委托",
    ["O"] = "加维克·污帆要你使用急救技能制作20条丝质绷带，并把订单带给荆棘谷藏宝海湾的加维克·污帆。",
    ["D"] = "我已经不像以前那么灵活了，$N，而大海可不会在乎。海上一个小划伤很快就会恶化。船长要我等他处理完港口里的事就准备出航。至于我？我想在再次爬上索具前休息一下。\n\n我知道了！给我带20条丝质绷带，好吗？我还挥得动弯刀，但这些天要把自己缝补好，需要更多帮助。",
  },
  [28500] = {
    ["T"] = "老人海明威的委托",
    ["O"] = "老人海明威要你使用钓鱼技能收集20条新鲜的石鳞鳕鱼，并把订单带给荆棘谷藏宝海湾的老人海明威。",
    ["D"] = "你有没有只是坐在水边听过？乐趣就在那儿。不在金币里，也不在收获里。只有平静，还有抛竿。\n\n不过……如果你正好弄到一些新鲜的石鳞鳕鱼，我也不会拒绝。它们会提醒我，当初为什么开始钓鱼。",
  },
  [28533] = {
    ["T"] = "格里克斯·布鲁维特的委托",
    ["O"] = "格里克斯·布鲁维特要你使用草药学技能收集20根荆棘藻，并把订单带给荆棘谷藏宝海湾的格里克斯·布鲁维特。",
    ["D"] = "嘿，$C。你可以想象，在一个满是海盗的港口城镇，水上行走和水下呼吸药剂卖得像热蛋糕一样快。不幸的是，我已经完全没有荆棘藻可用来继续制作了！\n\n从你指甲缝里的泥土我看得出来，你很懂草药，所以如果你愿意给我带更多来，我愿意让你分到一些利润和我手头还有的药剂。",
  },
  [28650] = {
    ["T"] = "马克迦文的委托",
    ["O"] = "马克迦文要你使用采矿技能收集10块金矿石，并把订单带给荆棘谷藏宝海湾的马克迦文。",
    ["D"] = "金子会说话，$C。在藏宝海湾这里，它是在大喊。\n\n秘银会以品质闻名，我也已经排好了买家，可手里没有产品可交。因为现在人人都想要闪亮的镶边，而我的金矿石全用完了。\n\n想加入这门生意吗？给我带10块金矿石。确实是稀有东西，但如果你知道谁在付钱，每挥一下矿镐都值得。",
  },
  [28713] = {
    ["T"] = "先知摩克萨尔丁的委托",
    ["O"] = "赫拉格兰要你使用裁缝技能制作2副冥想手套，并把订单带给荆棘谷格罗姆高营地的先知摩克萨尔丁。",
    ["D"] = "先知摩克萨尔丁会进入深度恍惚来指引我们。他能看穿丛林、海洋，有时甚至能透过灵魂世界的帷幕。但最近，压力越来越大。他的幻象开始动摇，双手也会颤抖。\n\n如果你能制作冥想手套，就把它们带给这里格罗姆高营地的他。它们也许能帮助他稳住专注……并稳定他伸向无形之界的触及。",
  },
  [8929] = {
    ["T"] = "寻找安泰恩",
    ["O"] = "在斯坦索姆入口处使用超维度幽灵显形器，并与安泰恩·哈尔蒙的灵魂交谈。",
    ["D"] = "好吧，我们现在只剩下试试那个地精发明这件事了。有传言说，安泰恩试图进入斯坦索姆大门时，被城中的亡灵军团砍倒了。\n\n在那里试着使用这个装置，弄清安泰恩知道些什么。",
  },
  [8930] = {
    ["T"] = "寻找安泰恩",
    ["O"] = "在斯坦索姆入口处使用超维度幽灵显形器，并与安泰恩·哈尔蒙的灵魂交谈。",
    ["D"] = "很好，$N。剩下的就是把地精的发明拿来测试了。有传言说，安泰恩试图进入斯坦索姆大门时，被城中的亡灵军团杀死了。\n\n在那里试着使用这个装置，看看你是否真的能与死者交谈！",
  },
  [8945] = {
    ["T"] = "死人的请求",
    ["O"] = "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达·哈尔蒙。",
    ["D"] = "我会把你要的信息告诉你，$N。但眼下有更紧迫的事。\n\n我挚爱的妻子被瑞文戴尔的亡灵渣滓俘虏了。\n\n我曾强烈反对她加入银色黎明那场愚蠢的远征，但那现在已经不重要了。你必须完成我试图完成的事，你必须把伊思达从男爵的魔爪中救出来！",
  },
  [8946] = {
    ["T"] = "生命的证明",
    ["O"] = "把伊思达的项链带给东瘟疫之地的安泰恩·哈尔蒙。",
    ["D"] = "我挚爱的人为了救我而死，这是最残酷的命运。可是，你声称自己拥有与他交谈的能力。\n\n把这条项链带给他，证明我安然无恙。他不能继续徘徊在这个世界上；我的心无法承受。\n\n永别了，$N。我将永远欠你一份情。",
  },
  [8947] = {
    ["T"] = "安泰恩的奇怪请求",
    ["O"] = "把3块黑铁锭、20张魔化皮、3块月布和4块熟化毛皮带给东瘟疫之地的安泰恩·哈尔蒙。",
    ["D"] = "我们竟没有意识到瓦塔拉克勋章的重要性，所以它和其他战利品一起被分了出去。第一块碎片被一个名叫塞尔德林的矮人拿走了。我曾试图从他那里取回它，却被他打得只剩半条命。你恐怕得用武力夺取那块碎片。\n\n我最后听说他的消息时，他已经成了黑铁矮人的角斗士。不过，要让他与你交手，恐怕会有点挑战。\n\n替我收集以下材料。你会用到它们。",
  },
  [8964] = {
    ["T"] = "重要的材料",
    ["O"] = "取回一把狂热光芒之剑，并把它交给黑石山内的伯德雷。",
    ["D"] = "$C，仔细听好。既然我们有了火盆，也有了点燃它的办法，还需要另一种注入其中的材料；某种足够强大的焦点，用来召唤我已故旧友的残余。\n\n贾林和索索斯这对兄弟是血色十字军信徒。他们渴望在那个邪恶组织中成为骑士。前往东瘟疫之地的提尔之手，从那里的血色禁卫队身上取回一把狂热光芒之剑。",
  },
  [8987] = {
    ["T"] = "更多重要的材料",
    ["O"] = "取回一把狂热光芒之剑，并把它交给黑石山内的伯德雷。",
    ["D"] = "$C，仔细听好。既然我们知道了最后一块护符碎片的位置，还需要另一种注入火盆的材料；某种足够强大的焦点，用来召唤我已故旧友的残余。\n\n贾林和索索斯这对兄弟是血色十字军信徒。他们渴望在那个邪恶组织中成为骑士。前往东瘟疫之地的提尔之手，从那里的血色禁卫队身上取回一把狂热光芒之剑。\n",
  },
  [26316] = {
    ["T"] = "洛丹伦的法律遗产",
    ["O"] = "为幽暗城的传说讲述者埃伯洛克，在通灵学院和斯坦索姆中寻找关于洛丹伦法律实践的书籍。",
    ["D"] = "生前我是法律学者，死后我也想继续这些研究，即使我同时在探索更广泛的主题。我没有时间亲自去洛丹伦废墟中搜集书籍，但我敢说你有。\n\n把斯坦索姆废墟和通灵学院中这些特定典籍带给我，我就能在传说讲述者职责与个人兴趣之间取得平衡。",
  },
  [26397] = {
    ["T"] = "冲突号召：东瘟疫之地",
    ["O"] = "在东瘟疫之地内找到并杀死5名部落成员。",
    ["D"] = "东瘟疫之地属于联盟，我们必须不断证明这一点。追猎部落成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26398] = {
    ["T"] = "冲突号召：东瘟疫之地",
    ["O"] = "在东瘟疫之地内找到并杀死5名联盟成员。",
    ["D"] = "东瘟疫之地属于部落，我们必须不断证明这一点。追猎联盟成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26432] = {
    ["T"] = "大师之作",
    ["O"] = "询问堕落骑士，部落中谁有足够技艺为你制作马饰。",
    ["D"] = "你想召唤一匹战马骑入战场？那是每个圣骑士在赢得资格后的梦想。\n\n我无法理解你们这些生物怎么可能配得上同样的东西，但如果你执意尝试，就需要一套马饰。\n\n我的马饰由斯坦索姆最优秀的铁匠制作。我怀疑你无法进入他们的作坊，但亡者行列中一定有人具备技艺。",
  },
  [26433] = {
    ["T"] = "赤红图纸",
    ["O"] = "进入斯坦索姆，杀死赤红锤匠以取回赤红马饰图纸。把它们带给圣光之愿礼拜堂的军需官米兰达·布利奇洛克。",
    ["D"] = "所以血色十字军的铁匠正在斯坦索姆制作他们的马饰？血色堡垒内有一名颇有名望的锤匠。我大胆猜测，就是他处理这种需求。至少，这是我们寻找图纸的最佳选择。\n\n如果你成功取得图纸，就需要把它们带到圣光之愿礼拜堂。我敢肯定它们是用人类语言写的——没有帮助的话，阿图克读不懂。",
  },
  [26435] = {
    ["T"] = "货物收集",
    ["O"] = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币带给奥格瑞玛荣誉谷的铁砧阿图克。",
    ["D"] = "根据图纸，这套马饰有四种组成材料：做内衬的符文布、做护板的奥金锭、用于灵魂调和的阿尔萨斯之泪，以及用于灵魂灌注的斯坦索姆圣水。\n\n算上第五样吧——我需要得到这份工作的报酬。你的费用包括人工，以及手工制作的马鞍和马镫。\n\n一旦你把货物交来，我就能完成马饰。我会立刻开始制作马鞍。",
  },
  [26475] = {
    ["T"] = "大规模净化",
    ["O"] = "进入斯坦索姆的血色领区，杀死赤红审判官，看看他们是否掌握大规模净化的秘密。",
    ["D"] = "每天都有更多尸体要丢进坑里。死者仍可能携带疾病，$C。我担心把他们全都扔进坑里，可能会让圣光之愿礼拜堂的其他人生病。\n\n要是有办法用一个大型法术把他们全部净化就好了。\n\n血色十字军一定会遇到这个问题。我想知道他们在血色领区的牧师中，是否有人掌握大规模净化的秘密？",
  },
  [26725] = {
    ["T"] = "黑魔法",
    ["O"] = "从东瘟疫之地的黑暗助祭和暗影法师身上收集3本黑魔法典籍，然后返回奥格瑞玛暗影裂口的库尔古尔那里。",
    ["D"] = "诅咒教派训练巫师掌握各种禁忌魔法和形形色色的黑暗技艺。虽然他们专精通灵术，但我们术士也能从他们的研究中学到一两样东西。\n\n前往东瘟疫之地，杀死教派的黑暗助祭和暗影法师。你会在他们的据点——剧毒林地和蘑菇谷——找到他们。收集三本他们的法术书，好让我研究他们的技艺。",
  },
  [26726] = {
    ["T"] = "奉献的回响",
    ["O"] = "在病木林中寻找迷失者艾利德林，并让他安息。",
    ["D"] = "你能看见我？你能听见我？我能感觉到你的灵魂属于生者。也许你就是我祈祷的答案。\n\n我是塞拉芬，曾经来自奎尔萨拉斯，如今只是这片荒芜土地上被遗忘的回响。我的灵魂徘徊不去，被未竟的职责困住。被诅咒者仍不得安宁……而生者遗忘得太快。\n\n我挚爱的人——艾利德林——在天灾军团的第一波冲击中倒下。他的灵魂和我一样仍受束缚，但他被愤怒与悲伤所缚。如果你愿意赐我安宁，就必须先解放他。他在我们最后抵抗之地的废墟附近游荡，被自己的失败折磨。你会在附近的病木林找到他。",
  },
  [26728] = {
    ["T"] = "实地考察",
    ["O"] = "杀死拉斯穆森教授，并从优等生身上收集4份项目笔记。",
    ["D"] = "请不要因为我与通灵学院有关就受骗，$C。我的心效忠银色黎明。我在诅咒教派中潜伏了许多天，一直在寻找挫败他们计划的机会。你的到来给了我一个机会，让我既能保住伪装，又能干涉他们的事务。\n\n通灵学院的一群优等生被派到东瘟疫之地进行某种研究实地考察。他们的老师拉斯穆森教授怀疑我，不愿告诉我他们在这里做什么。\n\n杀了他和那些邪恶学生，取回他们的笔记。也许我们能拼凑出他们来到这里的目的。",
  },
  [26730] = {
    ["T"] = "一封可疑的信",
    ["O"] = "把可疑的信带给东瘟疫之地的斯塔林教授。",
    ["D"] = "在寒骨的随身物中，你找到一封写给莱斯·霜语、尚未完成的信。上面写着：\n\n“莱斯，我已收到会面地点的通知，并派出信使携带那件物品。你确定在如此靠近洛丹伦、且穿过辛迪加控制土地之后会面是明智的吗？黑暗的掩护对被遗忘者来说意义不大。如果护命匣落入错误之手，后果……”\n\n斯塔林教授会对这件物品感兴趣。",
  },
  [26733] = {
    ["T"] = "实地考察",
    ["O"] = "把寒骨的护命匣带到黑石山，并尝试在山内熔岩中摧毁它。然后带着结果返回东瘟疫之地废弃礼拜堂附近的斯塔林教授那里。",
    ["D"] = "净化一个巫妖的护命匣绝非小事，但有一种简单方法——把它投入黑石山炽热的熔岩中。如果那座山的灼热都无法熔化困住寒骨灵魂的框架，那就没有什么能做到了。\n\n沿着弗兰克罗恩·铸铁之墓中的锁链前进，你很容易就能到达熔火之桥底部的熔岩池。",
  },
  [26734] = {
    ["T"] = "实地考察",
    ["O"] = "把紧急报告带给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫爵士。",
    ["D"] = "你赶路的时候，我有时间解读寒骨的日记。我了解到的内容让我作呕。我不知道现在能和你分享多少，所以我会把这件事交给我的上级。请立刻把我准备好的这份报告送到圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵那里！",
  },
  [26737] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "在布洛米尔找到一件往昔遗物，并把它带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽。",
    ["D"] = "就在我们现在所站之处的北边，曾经是布洛米尔。过去它会锯开从祖阿曼和永歌森林沿河漂下来的木材。虽然我个人厌恶这种做法，但我相信那里的工人留下了他们服务的回响，而我们应该捕捉它。\n\n在磨坊寻找一件遗物，把它带给我。",
  },
  [26738] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "在干涸的绿奔河附近农场找到两件往昔遗物，并把它们带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽。",
    ["D"] = "绿奔河曾经从山间流下，穿过东威尔德，把木材和生机带给下游农场。其中一些农场的废墟仍然存在。\n\n黑木农场在与其同名的湖泊附近，绿奔农场则在河对岸、它的北边。搜索那些农场，看看能否在那里找到更幸福时代的遗物。",
  },
  [26739] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "在灰烬村废墟中找到两件往昔遗物，然后返回东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽那里。",
    ["D"] = "旅行者接近斯坦索姆时，会穿过一道仪式拱门。我不知道这对人类意味着什么，但那道门旁曾坐落着灰烬村。这个曾经逐渐壮大的社区如今所剩无几，但我们可以捕捉他们的遗产。\n\n沿道路向西北前往斯坦索姆，搜索穿过拱门后、如今病木林内的废墟。把你找到的任何东西带回来。",
  },
  [26740] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "在恐惧谷找到一件往昔遗物，并把它带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽。",
    ["D"] = "病木林另一侧有一座小村，曾名为西谷，如今则恰如其分地被称作恐惧谷。阿尔萨斯袭击斯坦索姆时，许多城中居民逃到这里，也把瘟疫带了过来。\n\n我知道它很快就陷落了。\n\n我们快完成了，$C。为我们的收藏带回一件西谷历史的遗物。",
  },
  [26741] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "从斯坦索姆居民身上收集10件往昔遗物，并把它们带给东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽。",
    ["D"] = "只剩最后一个地点了，我害怕代表自己请求你面对这种危险，但如果你成功取回我们需要的最后遗物，我就必须准备必要的仪式。\n\n那些斯坦索姆居民的遗物。\n\n曾经是北方璀璨明珠的地方，如今成了闹鬼、永燃的废墟。亡灵和诅咒教派行走在它的街道上。\n\n这些新居民中，肯定有许多从死者身上搜刮过东西。让他们交出这些不义之财，把那些遗物带给我。\n\n我们就快完成了。",
  },
  [26743] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "在瑟拉丹的祭坛上净化遗物包裹中沉重的记忆，然后返回东瘟疫之地圣光之愿礼拜堂的艾拉娜·月羽那里。",
    ["D"] = "我感觉到了你见到我时的惊讶，$C。是的，我也是东威尔德的记忆。我在那里，你明白吗，当天灾瘟疫开始的时候。而令我永远羞愧的是，我逃走了，没有做任何事去阻止它。\n\n现在摆在你面前的是一项危险任务，但你将释放的不只是东威尔德记忆的重负，也包括我。\n\n我们谈完之后，我会唤起那些记忆并开始仪式。确保你和你的队伍已经准备好……",
  },
  [26744] = {
    ["T"] = "开门营业",
    ["O"] = "在病木林中斯坦索姆与恐惧谷之间十字路口的旅店废墟里，寻找马文·卡什的任何踪迹。",
    ["D"] = "现在我准备好做生意了！你想要什么？\n\n哦等等……看来我的库存不太多。没有库存，我怎么卖东西？\n\n马文·卡什过去会给我带货来卖。既然他不在这里，他一定是在路线上。他会在斯坦索姆和通往这里的道路之间那个十字路口旁的旅店停留。去看看他有没有把我的库存留在旅店。把它带给我，你就会看到我的价格有多疯狂！",
  },
  [26745] = {
    ["T"] = "开门营业",
    ["O"] = "沿着马文的踪迹前往东瘟疫之地黑木湖附近的农场。",
    ["D"] = "你打开信，读到其中内容：\n\n“亲爱的阿加莎，\n\n我只能祈祷你能找到这封信并跟上我。一支亡灵大军正在穿越洛丹伦。我打算和古德曼一家一起躲到黑木农场。愿你平安。愿圣光保护你。\n\n马文”\n\n也许这就是奥古斯图斯提到的同一个人？",
  },
  [26746] = {
    ["T"] = "开门营业",
    ["O"] = "跟随马文的踪迹，前往东瘟疫之地考林路口的旅店。",
    ["D"] = "这里的信因潮气而发霉潮湿。你小心地打开信，发现字迹几乎难以辨认：\n\n“亲爱的阿加……\n\n我们已经……两天……饥饿的食尸鬼……在附近山丘游荡……前往考林路口……在旅店订了房间，并……有消息留给你。\n\n马文”\n\n也许你该调查考林路口的旅店？",
  },
  [26747] = {
    ["T"] = "开门营业",
    ["O"] = "在东瘟疫之地米雷达尔湖岸边寻找马文·卡什的任何踪迹。",
    ["D"] = "你打开信，读到其中内容：\n\n“亲爱的阿加莎，\n\n我们听说达隆郡发生了一场战斗，通往首都的道路已被封锁。古德曼一家找到一个有船的人，他会渡过米雷达尔湖，我们可以在对岸尝试逃生。愿圣光在这黑暗时刻庇佑我们所有人。\n\n马文”\n\n也许你该去湖边的码头看看？",
  },
  [26748] = {
    ["T"] = "开门营业",
    ["O"] = "把打捞来的货物箱交给东瘟疫之地恐惧谷的被感动的奥古斯图斯。",
    ["D"] = "这辆货车里堆放着干草药、神圣奉献印章和奥术蜡烛，虽然布满灰尘，但似乎还能使用。也许这就是马文·卡什本该带给奥古斯图斯的那批货？\n\n不管怎样，关于这名商人和他的朋友们究竟遭遇了什么，这里已经没有其他线索了。如果他们够幸运，也许已经逃过了天灾军团的行军。",
  },
  [26750] = {
    ["T"] = "清除竞争",
    ["O"] = "为被感动的奥古斯图斯收集8只石像鬼之翼和4根恐兽缝线。",
    ["D"] = "哦不，$N！出问题了——我没有购物袋来装顾客们想买的所有货物！\n\n你能不能顺路去一趟斯坦索姆，从古德曼家的杂货店里再拿些袋子来？\n\n着火了？那就是不行了。好吧。\n\n我见过一些像蝙蝠的生物在周围尖叫。不是蝙蝠！是像蝙蝠的那些。它们的翅膀很适合做袋子。我还需要一些线。也许可以从那些在病木林里蹒跚行走的缝合怪物身上弄到。对！就是这样！",
  },
  [26752] = {
    ["T"] = "有所作为",
    ["O"] = "为东瘟疫之地的阿多恩杀死8只幽灵狼蛛。",
    ["D"] = "你好，很高兴见到你，冒险者！我已经很久没有在这片荒芜之地见到新面孔了。\n\n我被派到这里监视奎尔萨拉斯可能到来的危险，哪怕继续执行那些早已死去或失踪的上级留下的命令显得十分荒唐，我也不会逃避职责。但在守望期间，我发现这片土地上有些问题，只要有人愿意拿起武器，就能把它们纠正过来。\n\n如果你正是这样的$R，我要请你注意病木林南边那座遍布蜘蛛的洞穴。削减它们的数量，向我展示你的战斗本领。",
  },
  [26753] = {
    ["T"] = "森林之外的土地",
    ["O"] = "从幽灵狼蛛卵囊中收集6缕奎尔多雷丝线，并把它们带给东瘟疫之地的阿多恩。",
    ["D"] = "奎尔萨拉斯陷落后，我成了自己同胞中的流亡者。奎尔林斯小屋的精灵回避与外人接触，回银月城的路也被阻断。我孤身一人。\n\n也许你愿意帮助我？住在病木林南部的幽灵狼蛛卵囊里，含有银月城用来制作精美披风的细丝。给我带一些那样的丝线来，让我回想起曾经在那里生活的感觉。",
  },
  [26754] = {
    ["T"] = "森林之外的土地",
    ["O"] = "把一瓶日触特酿珍藏带给东瘟疫之地的阿多恩。",
    ["D"] = "在更快乐的日子里，我会用一瓶日触特酿珍藏来为你的胜利举杯，那是一种以日光酿成的美酒。我多想再尝一口。\n\n奎尔林斯小屋的精灵也许还有一些，但他们是从旧日奎尔萨拉斯流放出来的。我上次试着和他们交谈时，他们把我赶了出来，还警告我不得再进入他们的领地。我不想招致他们的恶意。也许你可以替我去那里，看看能不能为我弄到一些？",
  },
  [26756] = {
    ["T"] = "森林之外的土地",
    ["O"] = "在东瘟疫之地剧毒林地的屠宰场找到游侠拉莉娅并杀死她，然后返回东瘟疫之地的阿多恩那里。",
    ["D"] = "还有一件事我要请求你，$R。\n\n当天灾军团穿过我族的土地时，我们失去了许多最优秀的游侠。幸运者死去了，其他人则被亡灵诅咒唤起，被迫服役。其中一人曾与我十分亲近。\n\n剧毒林地是天灾军团在这片土地上进行邪恶谋划的行动基地之一。那片林地的指挥官是游侠拉莉娅，曾经来自银月城。请赐予她早该得到的死亡。知道她终于安息，会让我心中轻松许多。",
  },
  [26757] = {
    ["T"] = "暗影不至之处",
    ["O"] = "把拉莉娅的信带给东瘟疫之地的阿多恩。",
    ["D"] = "游侠拉莉娅身上的这封信看起来已经很旧，写得也很仓促——甚至没有封口。阿多恩一定会对它感兴趣。",
  },
  [26759] = {
    ["T"] = "野兽的本性",
    ["O"] = "杀死名为淤血虫的污秽生物，然后返回东瘟疫之地皇冠哨塔附近的帕崔斯·埃尔加丁夫人那里。",
    ["D"] = "随着暗翼蝠死去，你已经证明自己能够应付强大的生物。还有另一个憎恶之物，我希望你去杀死它。\n\n向北沿着通往斯坦索姆的道路前进，你会找到那个名为淤血虫的臃肿软泥怪。请在它繁殖出一群无法遏制的污秽蠕虫之前杀死它。",
  },
  [26760] = {
    ["T"] = "病木林的大锅",
    ["O"] = "把通用中和剂加入病木林中的天灾大锅，然后返回药剂师迪瑟斯那里。",
    ["D"] = "你在西瘟疫之地处理大锅的工作做得非常出色。现在该把注意力转向东瘟疫之地类似的天灾活动了。\n\n我们的情报显示，病木林里有三口瘟疫大锅正在运作。这些大锅没有大锅领主看守，我相信我们可以用一种通用中和剂污染它们的内容物，让它们至少暂时无法使用。带上这瓶药剂去处理那些大锅，但要当心。病木林是瘟疫之地天灾力量的核心，遍布他们各式各样的士兵。",
  },
  [26761] = {
    ["T"] = "最后的大锅",
    ["O"] = "把通用中和剂加入蘑菇谷和剧毒林地中的天灾大锅，然后返回药剂师迪瑟斯那里。",
    ["D"] = "有报告传来，说最后还有两口大锅，一口在东瘟疫之地的剧毒林地，另一口在蘑菇谷。等你把中和剂加入这两口大锅后，瘟疫的蔓延就应该能得到控制——至少暂时如此。\n\n快去吧，英雄，好让我们把这件事了结。",
  },
  [26762] = {
    ["T"] = "病木林的大锅",
    ["O"] = "把通用中和剂加入病木林中的天灾大锅，然后返回化学家阿尔比顿那里。",
    ["D"] = "你在西瘟疫之地处理大锅的工作做得非常出色。现在该把注意力转向东瘟疫之地类似的天灾活动了。\n\n我们的情报显示，病木林里有三口瘟疫大锅正在运作。这些大锅没有大锅领主看守，我相信我们可以用一种通用中和剂污染它们的内容物，让它们至少暂时无法使用。带上这瓶药剂去处理那些大锅，但要当心。病木林是瘟疫之地天灾力量的核心，遍布他们各式各样的士兵。",
  },
  [26763] = {
    ["T"] = "最后的大锅",
    ["O"] = "把通用中和剂加入蘑菇谷和剧毒林地中的天灾大锅，然后返回化学家阿尔比顿那里。",
    ["D"] = "有报告传来，说最后还有两口大锅，一口在东瘟疫之地的剧毒林地，另一口在蘑菇谷。等你把中和剂加入这两口大锅后，瘟疫的蔓延就应该能得到控制——至少暂时如此。\n\n快去吧，英雄，好让我们把这件事了结。",
  },
  [26764] = {
    ["T"] = "我们有技术",
    ["O"] = "击败天灾工程师腐扳手并拿走天灾投石车图纸。在东瘟疫之地通往提尔之手的道路附近找到他。",
    ["D"] = "嘿，$C。很高兴见到一张友善——而且还活着——的面孔。\n\n尽管亡灵遍地，但这里对有进取心的年轻$R来说也有机会……比如你！天灾军团穿过瘟疫之地时留下了许多投石车，而他们已经开始回收其中一些。我想知道它们是怎么运作的！\n\n离这里不远，沿着通往提尔之手的路，有些天灾技工正在修理一台倒下的伐木机。杀掉他们的头儿，把他们用来修理车辆的图纸带给我，我会让你觉得这趟很值。",
  },
  [26766] = {
    ["T"] = "我们有技术",
    ["O"] = "在东瘟疫之地北谷附近回收瘟疫收割机，取得30个天灾备用零件。",
    ["D"] = "现在我们有了合适的工具，还需要合适的零件。\n\n看起来这些投石车有个设计缺陷，就在机件通量齿轮带和旋转螺母矩阵接合的地方。我见过的所有坏掉车辆，那部分都损坏了。不过，现在该加入一点地精创意了！我们应该能从北谷周围的机械收割机上弄到替换零件。没人照看后，它们已经失控发狂了，所以小心点！",
  },
  [26958] = {
    ["T"] = "英雄崇拜",
    ["O"] = "与东瘟疫之地玛瑞斯农场的纳萨诺斯·凋零者谈一谈。",
    ["D"] = "$C，谢谢你愿意和我说话。我只是个卑微的猎人，来请求你的帮助。我听说那位著名游侠纳萨诺斯·玛瑞斯，如今在亡灵形态下成了我们的盟友。在天灾到来之前，他就是我的英雄，我本打算前往他的家宅，当面与他交谈。\n\n恐怕瘟疫之地的野兽对我来说太难应付了。你能替我去和游侠玛瑞斯谈谈吗？我想知道怎样制作一把像他手中那样的弩。",
  },
  [26959] = {
    ["T"] = "英雄崇拜",
    ["O"] = "从角鹰兽或秃鹫身上收集20根制箭羽毛，然后返回东瘟疫之地玛瑞斯农场的纳萨诺斯·凋零者那里。",
    ["D"] = "<纳萨诺斯叹了口气。>\n\n亡灵的日子有时相当无聊。我想我现在也没什么更好的事可做。如果你去找来材料，我就教你一些基础。\n\n我们首先需要做箭羽的羽毛。你可以从强壮的角鹰兽或秃鹫身上取得，就像这里西瘟疫之地，甚至更远地方能找到的那些一样。",
  },
  [26983] = {
    ["T"] = "给提里奥·弗丁的邀请",
    ["O"] = "把汉隆医生的邀请转达给提里奥·弗丁，他就在东瘟疫之地边界的河边。",
    ["D"] = "等等，$N，在你走之前我有话要说。很抱歉，历史课我没法让你及格。不过你运气不错。只要替我跑个小差事，你仍然可以重新赢得我的好感。\n\n既然你已经证明自己很会与人交谈，我希望你去找一个我刚得知在天灾中幸存下来的恶名人物谈谈。他名叫提里奥·弗丁，曾经是洛丹伦社会中的显赫人物。我想采访他，了解背叛自己的骑士团究竟是什么感觉。\n\n请把这份采访请求带给他。他住在东瘟疫之地索多里尔河北端。",
  },
  [26984] = {
    ["T"] = "实地考察",
    ["O"] = "在东瘟疫之地达隆米尔湖岸边找到斯塔林教授。",
    ["D"] = "在达隆米尔湖北岸，你会找到我们的实践课导师斯塔林教授。她会为你介绍补习课程。如果你觉得入门课程已经很难，那么……这门课程可真是致命。再见，$N。",
  },
  [27180] = {
    ["T"] = "合同 #1031：死灵染料",
    ["O"] = "从斯坦索姆的诅咒教派成员身上收集4份死灵染料。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。你喜欢礼物吗？谁不喜欢呢！？这是礼品包装部门送来的一份。\n\n合同 #1031：从斯坦索姆内取得死灵染料\n\n数量：四瓶",
  },
  [27191] = {
    ["T"] = "蘑菇谷的蘑菇",
    ["O"] = "从东瘟疫之地的蘑菇谷收集5个尼克提亚·科拉布鲁斯蘑菇。",
    ["D"] = "你试过我们的肉馅水果蛋糕或肉馅饼吗？肉很容易弄到，但香料——那才是风味的来源！\n\n我们在馅饼里会用各种蘑菇，不过有一种稀有品种我想试试。它们叫尼克提亚·科拉布鲁斯，只生长在东瘟疫之地的蘑菇谷。你愿意替我采一些回来吗？",
  },
  [27194] = {
    ["T"] = "恶蛛试炼",
    ["O"] = "从东瘟疫之地恶蛛隧道取回烟林牧场的投递箱。",
    ["D"] = "烟林牧场的代理人一直在东瘟疫之地收集各种蛛丝，并安排在我们一个安全投递箱地点交货，位置就在恶蛛隧道。问题是——风险投资公司一直尾随我们的代理人，我想他们已经知道了投递箱的位置。我需要你不择手段确保那批货物安全！",
  },
  [27886] = {
    ["T"] = "求生意志",
    ["O"] = "在东瘟疫之地的破碎尖啸者、憎恨吟唱者和死亡歌手身上测试莉达的精神隔绝水晶。",
    ["D"] = "被遗忘者说他们已经摆脱了巫妖王的精神支配。如果真是如此，我们应该能通过隔绝目标心智免受精神侵入，强行切断这种支配。理论上，亡灵之后应该会变得不再具有攻击性，甚至变得友善。\n\n拿着这颗我亲自设计的宝石，在东瘟疫之地的女妖身上测试它。你需要抽取不止一个样本作为对照。我已经准备好一份你该尝试的名单。把结果带回来给我。",
  },
  [27891] = {
    ["T"] = "生死攸关",
    ["O"] = "把30个腐烂器官从东瘟疫之地的食尸鬼和憎恶身上带给幽暗城炼金房的霍尔卡·灰角。",
    ["D"] = "我们的盟友被遗忘者，对我们其他人来说仍是一个谜。我觉得他们既可疑又有趣，也想更了解他们。你难道不想吗？\n\n先从屠宰他们在东瘟疫之地的同类开始，特别是食尸鬼和憎恶。收集它们那些脆弱的部件，并带给我的使者霍尔卡·灰角。你可以在幽暗城的炼金房找到她。",
  },
  [27892] = {
    ["T"] = "生死攸关",
    ["O"] = "在东瘟疫之地的破碎尖啸者、憎恨吟唱者或死亡歌手身上测试霍尔卡的精神隔绝水晶。",
    ["D"] = "被遗忘者说他们已经摆脱了巫妖王的精神支配。如果真是如此，我们应该能通过隔绝目标心智免受精神侵入，强行切断这种支配。理论上，亡灵之后应该会变得不再具有攻击性，甚至变得友善。\n\n拿着这颗我亲自设计的宝石，在东瘟疫之地的女妖身上测试它。你需要取相当多样本作为对照。把结果带回来给我。",
  },
  [28541] = {
    ["T"] = "给贾斯·法拉恩的委托",
    ["O"] = "贾斯·法拉恩要你使用草药学技能收集20朵瘟疫花，并把订单带给东瘟疫之地圣光之愿礼拜堂的贾斯·法拉恩。",
    ["D"] = "我听说天灾灾难之后，瘟疫之地这里长出了一种新草药。它的名字很贴切，叫瘟疫花。\n\n我想研究这种变异草药。你能替我采一些来吗？我不敢离圣光之愿礼拜堂太远，但你看起来足够强壮。",
  },
  [31017] = {
    ["T"] = "仪式所需材料",
    ["O"] = "圣光之愿礼拜堂的玛克斯韦尔·泰罗索斯男爵需要几种材料来净化权杖：\n- 一瓶来自斯坦索姆的圣水。\n- 一块来自熟练炼金师或矿工的奥金锭。\n- 三支神圣蜡烛，可从施法材料商处购买。\n- 三堆来自附魔师的灵魂之尘。\n- 一个神圣符印，也可从施法材料商处购买。",
    ["D"] = "我看到了你的危机，$r。用死灵法师魔法玷污一条龙的灵魂，是黑暗之举。如果我能以任何方式相助，我会的。\n\n<玛克斯韦尔花了片刻规划仪式。>\n\n我需要几种成分和材料：\n\n首先，我们需要承载权杖的基底。奥金是最合适的材料，所以我们至少需要一块锭。在仪式法阵外侧，我们需要把三支神圣蜡烛放在三堆灵魂之尘上。最重要的部分是一枚作为魔法增幅器的神圣符印，以及一瓶用来浇洒权杖的斯坦索姆圣水。\n\n当你取得一切后回来找我。礼拜堂没有施法材料商真是遗憾……我会等你。",
  },
  [26167] = {
    ["T"] = "粘手的麻烦",
    ["O"] = "从隐匿石废弃部落基地周围的箱子里找回10瓶辛特兰蜜糖。",
    ["D"] = "我有点打捞活要交给你，如果你和我一样是精品果酒的行家，那你一定会喜欢这个任务。\n\n果酒！那是一种饮料，笨蛋。\n\n不管我们这里有什么选择，小伙子和姑娘们就是想要一点……不一样的东西。有点品味的东西。一处废弃的部落前哨里，还藏着他们营业时留下的辛特兰蜜糖。现在可弄不到那样的好果酒了！你可以从隐匿石附近的箱子里把果酒打捞出来。\n\n这会是一项艰苦的任务，因为废墟里会有恶臭的软泥怪和泥浆怪；传言说它们由某种软泥怪首领率领。无论如何，把果酒弄到手，然后回到这里来见我。",
  },
  [26168] = {
    ["T"] = "不打蛋就做不成煎蛋卷",
    ["O"] = "从沙德拉洛收集12枚沙德拉幼蛛卵，然后返回鹰巢山的科尔·铁眼那里。",
    ["D"] = "东南方的枯木巨魔在照料沙德拉子嗣的卵。即使我们杀掉枯木巨魔，那些卵也还会留在那里，等着孵化，把那些可怕的生物释放到荒野里。\n\n我们必须妥善处理这个威胁。把你看到的所有卵都从卵囊里扯出来，带给我。别试着自己摧毁它们；你可能会把小东西放出来。\n\n等你把它们带回来，我会确保它们得到妥善处置！",
  },
  [26169] = {
    ["T"] = "不打蛋就做不成煎蛋卷",
    ["O"] = "从沙德拉洛收集12枚沙德拉幼蛛卵，然后返回恶齿村的断齿族长那里。",
    ["D"] = "西边的枯木巨魔在照料沙德拉子嗣的卵。即使我们杀掉枯木巨魔，那些卵也还会留在那里，等着孵化，把可怕的生物释放到荒野里。\n\n我们必须妥善处理这件事。把你看到的所有卵都从卵囊里扯出来，带给我。别试着自己摧毁它们；你可能会把小东西放出来。等你把它们带回来，我会确保它们得到妥善处置！",
  },
  [26170] = {
    ["T"] = "清理海岸",
    ["O"] = "在辛特兰海岸杀死10只咸岸游泳者。",
    ["D"] = "哎，老兄，村子周围的渔场越来越荒了，我知道原因：就是那些该死的咸岸游泳者。我需要一个勇敢的冒险者替我做一件简单的事……能杀多少就杀多少。你办得到吗？",
  },
  [26171] = {
    ["T"] = "坠向恩惠",
    ["O"] = "从沙德拉洛内的枯木巨魔身上收集8块枯木披肩碎片和8份完美巢穴守卫蛛丝。",
    ["D"] = "我受大工匠本人派遣来到这里，帮助加强联盟和蛮锤氏族之间的关系。我的职责很简单：让他们骑乘狮鹫时更安全。\n\n我计划制作一些降落伞，能感应到骑手正在坠落并自动展开。听起来很棒，对吧？\n\n不过，要制作它们，我需要一些蛮锤这里没有的材料。首先要解决的就是降落伞本体。附近的枯木巨魔有很高明的裁缝经验，而他们的蜘蛛虽然恶心，却能产出绝妙的线。去给我弄一些来，我就能开始制作这些降落伞。",
  },
  [26172] = {
    ["T"] = "坠向恩惠",
    ["O"] = "在辛特兰群山中找到鲁普·火油。",
    ["D"] = "这个计划的下一部分就是测高仪！简单来说，东西掉下去？测高仪做事。很简单。\n\n不幸的是，我身边没有带一个。我们侏儒在辛特兰这里有个较小的前哨，我的一位同事也许有货。你能去和他说说吗？\n\n你会在这里东边的山里找到他们，就在奎尔丹尼小屋北边一处秘密前哨。",
  },
  [26174] = {
    ["T"] = "坠向恩惠",
    ["O"] = "把完好的测高仪带回鹰巢山的蒂兹·火艺那里。",
    ["D"] = "好了，给火艺小姐的完好测高仪。她到底要用这些做什么？自动展开的降落伞……真迷人……我得安排一次最终装置的正式演示。",
  },
  [26176] = {
    ["T"] = "坠向恩惠",
    ["O"] = "把自动降落伞套件交给弗斯塔德·蛮锤。",
    ["D"] = "如果这都不能让我们赢得蛮锤的好感，我就不知道还有什么能做到了。你愿意替我把它交给弗斯塔德吗？",
  },
  [26177] = {
    ["T"] = "锋喙之友",
    ["O"] = "收集8份石斑鱼排和12根王咬芦苇茎，用来制作狮鹫零食。",
    ["D"] = "我们氏族敬奉狮鹫为神圣动物。它们是天空中的雄伟生灵，不只是愚笨的野兽；它们聪明而狡黠。有人说我们把它们当马养，但这更像是一种友谊。\n\n如果你想和这里的蛮锤交朋友，就先和我们的狮鹫交朋友！它们最喜欢的零食很少见：脆芦苇和新鲜鱼排混合而成。那些家伙会为它发疯。\n\n如果我们要给它们做些零食，你就得收集材料。从这里往东，你会找到一条大溪流，它从亚戈瓦萨附近开始，沿海岸流入一条河。你可以在那里找到厚肉石斑鱼和王咬芦苇。去把它们带给我，我们就能做出一批新鲜的。",
  },
  [26178] = {
    ["T"] = "锋喙之友",
    ["O"] = "把狮鹫零食喂给鹰巢山东南方的训练有素的锋喙狮鹫。",
    ["D"] = "拿着这袋食物。新鲜得很。我们训练有素的锋喙狮鹫会在鸟舍东南方的森林里游荡。去替我喂几只，好吗？",
  },
  [26179] = {
    ["T"] = "辛特兰隐士",
    ["O"] = "找到隐士乌博，他曾是恶齿村的卫兵，因为受不了村里把龟肉当食物而离开。",
    ["D"] = "我们有麻烦，需要像你这样强壮的人来解决。\n\n我们有个卫兵，隐士乌博，离开村子，因为他不喜欢龟肉。现在他一个人住在北边。\n\n我们想念乌博，也想念他的守卫本事。我们想让他回村。你找到他，把他带回来，我们好好奖励你。你愿意替我们做这事吗，老兄？",
  },
  [26181] = {
    ["T"] = "分发零食",
    ["O"] = "把零食喂给辛特兰海岸上的钳嘴龟。",
    ["D"] = "用你带来的东西，我给这些钳嘴龟做了点特别零食。帮我个忙，把它们沿海岸分给那些钳嘴龟。",
  },
  [26182] = {
    ["T"] = "和平的赠礼",
    ["O"] = "在辛特兰海岸收集8块龟“团子”。",
    ["D"] = "现在你明白我为什么这么喜欢这些乌龟，为什么不回村了吧？我厌倦了他们派你这样的冒险者来劝我回去。我有个完美的消息要送给他们，我想这能让事情结束。\n\n你分发的零食有第二个好处，会很快穿过乌龟的肚子，这就意味着我们有很多“团子”可以包好送给恶齿巨魔。\n\n去替我收集一些，趁它们还新鲜时尽快回来。",
  },
  [26184] = {
    ["T"] = "和平的赠礼",
    ["O"] = "把乌博的和平赠礼带给辛特兰恶齿村的警戒者欧维。",
    ["D"] = "把这份“和平赠礼”带给村里的警戒者欧维，我想他终于会停止派你这样的冒险者来找我谈话了。\n\n去吧——你最好是最后一个。",
  },
  [26185] = {
    ["T"] = "拉尔德丢失的珠串",
    ["O"] = "从鲨鱼碎颚身上取回拉尔德的珠串，它经常沿着辛特兰海岸巡游。",
    ["D"] = "有时候拉尔德喜欢走到码头，把石头扔进海里。拉尔德甚至有一次打了三个水漂！\n\n拉尔德太兴奋，把珠串扔进水里了……接下来拉尔德就看到大坏鲨鱼碎颚游过来，把珠串吞进肚子里！你能从碎颚肚子里替拉尔德把它们拿回来吗？",
  },
  [26188] = {
    ["T"] = "追猎潜伏者",
    ["O"] = "辛特兰鹰巢山的狮鹫管理员沙拉克·鹰斧要你杀死15只银鬃捕猎者和15只银鬃嗥狼。任务完成后回到他那里。沙拉克·鹰斧提到，这些狼藏身于辛特兰的荒野中。",
    ["D"] = "许多勇敢的矮人都葬身在辛特兰严酷的荒野中，$r。银鬃狼是我们猎人面临的最大威胁之一。它们潜伏等待，藏在灌木和地形之间，一有机会就发动袭击。\n\n这种凶残绝不能放任不管！\n\n要找到银鬃狼，你就必须像银鬃狼一样思考。追猎那些捕猎者和嗥狼！把它们全杀了！",
  },
  [26189] = {
    ["T"] = "顶级软泥",
    ["O"] = "从软泥巨球身上收集一份软泥巨球样本。",
    ["D"] = "没几个矮人知道，但为了让我的酒真正够劲，我会加一点这里的软泥怪。没错，就是那些巨大的绿色吃矮人软泥怪。\n\n不过这次酿的酒需要特别特别够劲，所以我们需要一只巨大的软泥怪！隐匿石下面潜伏着一个所有软泥怪的老母，绝对巨大……我们叫它软泥巨球。\n\n如果你有本事，就下去从软泥巨球身上给我砍下一块来！",
  },
  [26190] = {
    ["T"] = "顶级软泥",
    ["O"] = "从软泥巨球身上收集一份软泥巨球样本。",
    ["D"] = "有兴趣研究一些黏糊糊的软泥怪吗？隐匿石的软泥怪可不是闹着玩的。不管我们清理多少次，它们似乎总会回来，像巨魔一样再生……或者差不多吧。\n\n你知道我怎么想吗？我觉得下面有什么源头，一直在制造软泥怪。我想查清那是什么！所以去吧，冒险者，深入隐匿石，把制造这些软泥怪的东西带一份样本回来。研究它对我来说会是件乐事！",
  },
  [26191] = {
    ["T"] = "凶恶行当",
    ["O"] = "杀死鹰巢山东边的10只邪恶的枭兽。",
    ["D"] = "我们和这一带巨魔之间持续不断的争斗，有时会渐渐变成和平僵持——但和平从不会持久。\n\n辛特兰野外的枭兽正在搅局。它们时不时会击倒一队巨魔，或洗劫一辆蛮锤补给车，随后互相指责便升级成战斗。\n\n如果我们想朝某种和平努力，就必须扰乱那些枭兽。向东去，替我削减它们的数量，双方的火气应该就会平息。",
  },
  [26192] = {
    ["T"] = "原始重击",
    ["O"] = "在辛特兰中部地区找到并清除10只远古枭兽。",
    ["D"] = "你越往东走，枭兽就越原始，也越强悍。从这里开始，削减它们数量的挑战只会越来越大，但为了蛮锤，我们必须这么做。\n\n前往辛特兰中部，减少枭兽的数量。你每杀死一只野兽，辛特兰就会变得更和平。",
  },
  [26193] = {
    ["T"] = "野蛮猛击",
    ["O"] = "在遥远东方望海崖附近找到野蛮的枭兽，并杀死10只。",
    ["D"] = "最靠近海岸上恶齿村的枭兽造成了最大的伤害。我听说它们最近杀死了一支恶齿巡逻队，但巨魔找到死去的同伴时，却把责任推到了我们头上。要你去做这件事让我极其心痛，但不能允许那些枭兽让矮人和巨魔之间的紧张关系成倍增长。\n\n野蛮的枭兽更强，也似乎更暴躁，所以要小心——但我们必须把它们解决掉。",
  },
  [26196] = {
    ["T"] = "乌龟力量",
    ["O"] = "从辛特兰东部海岸、望海崖一带的乌龟身上收集10块瘦龟腹肉。",
    ["D"] = "一个坚韧的蛮锤在漫长一天后最先要的，就是一杯好麦酒和一点吃的。这里最好吃的就是美味的海龟汤。\n\n可惜，鹰巢山在辛特兰里几乎离那些巨龟最远。前往望海崖替我猎一些，好让我开始下厨——把它们的瘦腹肉带给我！",
  },
  [26198] = {
    ["T"] = "通缉：污冠",
    ["O"] = "找到在瓦罗温湖周围巡游的污冠，并结束它的痛苦。",
    ["D"] = "几个月前，一名勇敢的蛮锤在例行空中巡逻时，被一阵巨魔长矛从天上击落。他忠诚的狮鹫伙伴污冠对此承受得很糟。自那以后，污冠通过杀死它遇到的一切来宣泄怒火：野生动物、巨魔和矮人无一幸免。必须让这可怜的野兽安乐死。把污冠死亡的证据带给鹰巢山的狮鹫管理员。",
  },
  [26199] = {
    ["T"] = "通缉：污冠",
    ["O"] = "找到在瓦罗温湖周围巡游的污冠，并杀死它。",
    ["D"] = "几个月前，有个蛮锤被我们一阵长矛从天上打了下来。他的狮鹫污冠对此承受得很糟。自那以后，它就陷入血怒，杀害野生动物、巨魔和矮人无一例外。把它死亡的证据带给恶齿村的警戒者欧维。",
  },
  [26209] = {
    ["T"] = "蛮锤遗骨",
    ["O"] = "从辛萨罗找回10块蛮锤遗骨。任务完成后返回鹰巢山的弗斯塔德·蛮锤那里。",
    ["D"] = "辛萨罗的邪枝巨魔长期以来一直用从我们墓地偷来的矮人遗骨进行邪恶仪式。他们按邪恶祭司海克斯的要求偷走那些遗骨。\n\n前往辛萨罗，找回我们受尊敬祖先的遗骨。你会在城中巨魔的力量之地找到它们。",
  },
  [26210] = {
    ["T"] = "招聘：鹰巢山卫队长",
    ["O"] = "前往辛萨罗，杀死20名邪枝标枪手、20名邪枝暗影法师、20名邪枝剥皮者和20名邪枝精英卫兵。如果你完成了这项任务，就去辛特兰鹰巢山找卡拉·锤翔谈谈。",
    ["D"] = "蛮锤氏族正在招募强大战士，带队前往巨魔城市辛萨罗。有意申请者应完成以下任务：\n\n消灭邪枝标枪手\n\n消灭邪枝暗影法师\n\n消灭邪枝剥皮者\n\n消灭邪枝精英卫兵",
  },
  [26211] = {
    ["T"] = "战术打击",
    ["O"] = "进入辛萨罗，杀死邪恶祭司海克斯和守护者希坦亚。",
    ["D"] = "蛮锤在辛特兰生活已久，我们也与邪枝巨魔冲突已久。巨魔在这里东南方建起了一座巨大的城市，名叫辛萨罗。我们无法指望把他们从这个力量堡垒中彻底铲除，但可以发动一次打击，让他们混乱到无力进攻我们。\n\n潜入辛萨罗，杀死他们的首领：邪恶祭司海克斯和守护者希坦亚！我猜他们会在城市最顶端。",
  },
  [26212] = {
    ["T"] = "他们的巫毒把戏",
    ["O"] = "为辛特兰鹰巢山的卡拉·锤翔，从辛萨罗的巨魔身上收集8份巫毒助熔剂。",
    ["D"] = "和村里的许多人一样，我曾与邪枝巨魔交战，也很佩服他们武器的品质。我相信邪枝巨魔用魔法强化木料和钢铁，但那种魔法是他们锻造和制作武器时使用的一种特殊助熔剂。\n\n如果你愿意前往辛萨罗取回一些，我可以用上几份这种助熔剂样本。",
  },
  [26213] = {
    ["T"] = "霍文最爱的钓鱼点",
    ["O"] = "从鹰巢山远东方望海崖瀑布顶端他最爱的钓鱼点，找回霍文最爱的鱼饵。",
    ["D"] = "$R，你看起来很能干。我能请你帮个忙吗？\n\n我在遥远东方望海瀑布顶端最爱的钓鱼点钓鱼时，遭到一群游荡的邪枝巨魔袭击。我拼命逃走，把所有钓鱼用品都丢在了那里。\n\n你愿意回到望海瀑布，替我把它们收回来吗？如果找不全也没关系——我其实只想要回我最爱的鱼饵。",
  },
  [26216] = {
    ["T"] = "霍文最爱的钓鱼点",
    ["O"] = "带着霍文最爱的鱼饵返回鹰巢山。",
    ["D"] = "这真是个小奇迹！这里有一个鱼饵挂在一块漂木上。你小心地把它取下，希望自己找到了霍文要找的鱼饵。",
  },
  [26379] = {
    ["T"] = "冲突号召：辛特兰",
    ["O"] = "在辛特兰内找到并杀死5名部落成员。",
    ["D"] = "辛特兰属于联盟，我们必须不断证明这一点。追猎部落成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26380] = {
    ["T"] = "冲突号召：辛特兰",
    ["O"] = "在辛特兰内找到并杀死5名联盟成员。",
    ["D"] = "辛特兰属于部落，我们必须不断证明这一点。追猎联盟成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26479] = {
    ["T"] = "空气的召唤",
    ["O"] = "在阿拉希高地找到坦林·双锤。",
    ["D"] = "卡利姆多的风正奔向你，你也将被列入我们最强大的$G brothers:sisters;之中。看到你走到这一步，并拥有如此光明的未来，我感到自豪。\n\n空气元素很难控制，但我相信你的技艺能够克服摆在你面前的任何障碍。\n\n前往阿拉希高地最北端、避难谷地以西，寻找坦林·蛮锤。她会教导你。",
  },
  [26561] = {
    ["T"] = "寻找火羽",
    ["O"] = "找到在燃烧丘陵上空翱翔的火羽。",
    ["D"] = "你已经向我的家人证明了自己既能干又善良。你愿意帮我完成一项对我个人极其重要的任务吗？\n\n身为蛮锤，我和我的狮鹫火羽之间的羁绊无边无际。火羽一直与元素有着独特联系。这也是我选择它、它选择我的部分原因。\n\n当元素从地底迸发时，火羽逃走了，飞上燃烧丘陵上空。我非常担心它的安全。你能追踪到它，告诉我它还好吗？我只需要亲眼确认。",
  },
  [26565] = {
    ["T"] = "紧急恳求",
    ["O"] = "在火羽的栖木召唤火羽，并把阿曼达·艾尔斯通的消息带给鹰巢山的弗斯塔德。",
    ["D"] = "我相信你已经注意到，这座庄园不再安全了。我能感觉到元素在痛苦中呼喊，情况只会越来越糟。我的家人的固执让我们拖延太久，安全转移家眷的时机已经过去，道路也不再可行。\n\n我需要你前往鹰巢山，请求弗斯塔德援助，好让我们离开。与此同时，我会说服我的家人，我们必须走。\n\n拿着这只哨子。火羽现在信任你，只要你在它的栖木处呼唤，它就会来。让它带你去鹰巢山与弗斯塔德交谈。",
  },
  [26566] = {
    ["T"] = "紧急恳求",
    ["O"] = "在鹰巢山内召唤火羽，并骑着它返回艾尔斯通庄园。",
    ["D"] = "如果你告诉我的是真的，艾尔斯通一家必须尽快撤离！回到阿曼达那里，告诉她蛮锤从不会抛弃自己人。我们会在日落前赶到，所以他们最好准备好。谢谢你把这份恳求带给我们，$N。",
  },
  [26567] = {
    ["T"] = "离弃庄园",
    ["O"] = "通知宝拉·艾尔斯通，蛮锤的人正在赶来。",
    ["D"] = "拜托，你能告诉宝拉我们要离开了吗？我需要收拾一些最后的东西，再去叫上我的丈夫。我们会紧跟在你后面逃离庄园。谢谢你为我的家人所做的一切，$N。",
  },
  [26742] = {
    ["T"] = "东威尔德的记忆",
    ["O"] = "前往辛特兰瑟拉丹的神庙废墟，找到仪式祭坛。为了安全起见，你可能需要带上一些同伴。",
    ["D"] = "我担心自己因这片土地的痛苦而太过虚弱，无法在这里举行仪式。你必须前往一个自然之力更强的地方。\n\n辛特兰的瑟拉丹离这里不算太远。如果你避开敌对的绿色龙人，就能找到一座神庙废墟，那会是举行净化仪式的理想地点。把遗物包裹带到祭坛上并放置其上。那些曾参与毁灭这片土地的强大存在的记忆，会被引诱出来。你必须击败它们。\n\n我已经向你索求了许多，$N，如果你做不到，我也理解。你需要召集盟友协助你，而你将面对的是我无法描述的噩梦。我只能说，除非我们净化这片土地的灵魂本身，否则它不可能开始愈合。",
  },
  [26835] = {
    ["T"] = "元素掌握",
    ["O"] = "为戈尔伦德·雪须收集一份空气、火焰、大地和流水的样本。",
    ["D"] = "蛮锤氏族的戈尔伦德·白须向拥有你这般能力的萨满发出了召唤。他要求你带来每种元素的样本，以证明你已经准备就绪。\n\n你可以在鹰巢山找到他。",
  },
  [26836] = {
    ["T"] = "护卫灵魂",
    ["O"] = "为戈尔伦德·雪须收集厚实的黑爪和充血的蜘蛛眼。",
    ["D"] = "辛特兰那些邪恶巨魔用卑劣的灵魂魔法袭击鹰巢。我知道需要什么来制作一根图腾，驱散他们的灵魂，但我已经不再年轻了。\n\n如果你从这里沿路向东前往拉普索迪营地，再向北走，就会进入如今称为西瘟疫之地的地方。你需要弄到黑熊爪和一些蜘蛛眼，用来制作护卫图腾。仔细想想，你也许还能从食腐生物身上弄到它们。",
  },
  [27319] = {
    ["T"] = "家庭新成员",
    ["O"] = "把你的脆弱的小精龙卵带到辛特兰，并与猎户马克霍尔谈谈，但要快，你只有1小时找到他，否则蛋里的幼崽就会死去。",
    ["D"] = "真是个华丽的标本，$N。如果这个生物能顺利孕育，那它一定会成为一只健康的宠物！\n\n如果你打算把这件事做到底，我建议最后再做一件事——前往辛特兰的恶齿村。和那里一名叫猎户马克霍尔的巨魔谈谈。他是驯兽大师，应该能引导你完成孵化的最后步骤。\n\n但要快，$N，这枚蛋很脆弱，得不到适当照料的话撑不了多久。",
  },
  [27320] = {
    ["T"] = "小宝宝的食物",
    ["O"] = "把5块银鬃捕猎者的肉带给辛特兰的猎户马克霍尔。",
    ["D"] = "小精龙是杂食动物——也就是说，它们既吃肉也吃植物。如果你的蛋要孵化，我们最好做好准备。给这些小家伙吃的好东西，就是生鲜多汁的肉块，信不信由你。我一直没弄明白为什么，但这和艾露恩为精灵安排的计划有关……也许它们本该是守护者之类的东西，我也说不准。\n\n这枚蛋暂时由我照看，你不如去给我弄些上好的银鬃捕猎者肉，等它孵出来就能吃。",
  },
  [27321] = {
    ["T"] = "成为父母",
    ["O"] = "与辛特兰的猎户马克霍尔谈谈。",
    ["D"] = "哇，它比我想的准备得充分多了……！",
  },
  [27896] = {
    ["T"] = "星辰中的征兆",
    ["O"] = "与辛特兰鹰巢山的弗斯塔德·蛮锤谈谈。",
    ["D"] = "你好，$N！你对天文学有兴趣吗？我听说不久后将出现一次非常特别的天象——而鹰巢山的蛮锤矮人一直在寻找一名大胆的冒险者，帮助他们完成某种与此有关的重要仪式。\n\n但我得警告你——蛮锤崇拜大地母亲，和那些野牛一样的牛头人一样。我怀疑如果你接下这项任务，就得和那些牛打交道。\n\n我不知道你怎么想，但我更喜欢不会回嘴的牛排。\n\n如果你仍有兴趣，就去鹰巢山找弗斯塔德。",
  },
  [28444] = {
    ["T"] = "给霍文·鹰羽的委托",
    ["O"] = "霍文·鹰羽要你使用工程学技能制作5根秘银管，并把订单带给辛特兰鹰巢山的霍文·鹰羽。",
    ["D"] = "你钓过鱼吗，$N？我喜欢钓鱼，但有些邪枝巨魔把我从最爱的钓鱼点赶走时，我弄丢了自己最爱的鱼竿。\n\n镇上没有工程师，所以我也不确定什么时候才能弄到新的。如果你碰巧弄到一些秘银管，也许会想起你的朋友霍文，嗯？我可以用它们做一根新鱼竿。",
  },
  [28469] = {
    ["T"] = "给钓鱼者卡图姆的委托",
    ["O"] = "钓鱼者卡图姆要你使用工程学技能制作5根秘银管，并把订单带给辛特兰恶齿村的钓鱼者卡图姆。",
    ["D"] = "你钓鱼吗，$N？我喜欢钓鱼，可有些邪枝巨魔把我从最爱的钓鱼点赶走时，我弄丢了自己最爱的鱼竿。\n\n镇上没有工程师，所以我也不确定什么时候才能弄到新的。如果你碰巧弄到一些秘银管，也许会想起你的朋友卡图姆，嗯？我可以用它们做一根新鱼竿。",
  },
  [28506] = {
    ["T"] = "给阿塔莱流放者的委托",
    ["O"] = "阿塔莱流放者要你使用钓鱼技能收集20条新鲜的阳鳞鲑鱼，并把订单带给辛特兰沙德拉洛的阿塔莱流放者。",
    ["D"] = "流放者心中苦涩。冰冷的石头、古老的幽魂，锅里没有一丝温暖。\n\n但我还记得阳鳞鲑鱼的味道。浓郁，金黄，充满早已被遗忘河流中的暖意。给我带20条新鲜的阳鳞鲑鱼来，我就能想起比暗影更好的东西……哪怕只有一餐。",
  },
  [28530] = {
    ["T"] = "给印东·攀崖的委托",
    ["O"] = "印东·攀崖要你使用草药学技能收集20棵金棘草，并把订单带给阿拉希高地避难谷地的印东·攀崖。",
    ["D"] = "我从辛特兰下来采集一些金棘草，但逃离那些似乎巡游整片田野的迅猛龙时扭伤了脚踝。你能不能帮我完成任务，好让我回家？",
  },
  [28578] = {
    ["T"] = "给首席工程师乌鲁尔的委托",
    ["O"] = "首席工程师乌鲁尔要你使用制皮技能制作2条暗色皮带，并把订单带给辛特兰鹰巢山的首席工程师乌鲁尔。",
    ["D"] = "我口袋里有工具，袖子里也有工具，还有一把扳手昨天差点滚进下水道格栅。我的侄女尼奥玛说我需要一条像样的皮带——准确地说，是几条暗色皮带。\n\n如果你受过制皮训练，就做几条带到这里来。我不在乎它们长什么样，只要能挂住我的装备，而且不会在压力下爆炸就行。爆炸是我的工作。",
  },
  [28615] = {
    ["T"] = "给尼奥玛的委托",
    ["O"] = "尼奥玛要你使用剥皮技能收集10块龟壳，并把订单带给辛特兰鹰巢山的尼奥玛。",
    ["D"] = "住在遥远东方海岸上的乌龟也许动作迟缓，但它们的皮可是好东西。结实、柔韧，而且出人意料地容易加工。\n\n这些日子到处都是巡逻的巨魔，我一直没法出去补充库存。如果你路过那边，就给我带10块龟壳来。只要手艺到位，我能把它们做成能用一辈子的精良护甲部件。",
  },
  [28632] = {
    ["T"] = "给铁匠斯拉提的委托",
    ["O"] = "铁匠斯拉提要你使用剥皮技能收集10块龟壳，并把订单带给辛特兰恶齿村的铁匠斯拉提。",
    ["D"] = "住在这里海岸上的乌龟也许动作迟缓，但它们的皮可是好东西。结实、柔韧，而且出人意料地容易加工。\n\n这些日子到处都是巡逻的蛮锤和巨魔，我一直没法出去补充库存。如果你要出门，就给我带10块龟壳来。只要手艺到位，我能把它们做成能用一辈子的精良护甲部件。",
  },
  [28671] = {
    ["T"] = "给铁匠斯拉提的委托",
    ["O"] = "铁匠斯拉提要你使用采矿技能收集5块真银锭，并把订单带给辛特兰恶齿村的铁匠斯拉提。",
    ["D"] = "我想给这些森林巨魔看看，除了他们通常用来做武器的木头和石头之外，还有别的东西。我说的是真银，$N。\n\n我需要几块真银锭。如果你碰巧弄到一些，我很乐意从你手里收下。",
  },
  [28692] = {
    ["T"] = "给穆尔杜格·醉肚的委托",
    ["O"] = "特鲁克·蛮鬃要你使用裁缝技能制作2条碧蓝丝质腰带，并把订单带给辛特兰鹰巢山的穆尔杜格·醉肚。",
    ["D"] = "你是裁缝？感谢诸神！我需要你的帮助。\n\n现在，我通常不会在老板背后说闲话，但……情况越来越严重了。穆尔杜格的裤子一天比一天往下滑，要是他再在食堂里弯一次腰，我们全都要走人。\n\n如果你有本事，就给他做几条碧蓝丝质腰带，让他明白意思。别告诉他是我派你来的——就说这是一位“有眼睛的忧心下属”送的礼物。",
  },
  [28716] = {
    ["T"] = "给拉尔德的委托",
    ["O"] = "断齿族长要你使用裁缝技能制作2条碧蓝丝质腰带，并把订单带给辛特兰恶齿村的拉尔德。",
    ["D"] = "你是裁缝？感谢洛阿！我需要你的帮助。\n\n现在，我通常不会把自己的獠牙插进别人的事里，但……情况越来越严重了。拉尔德的裤子一天比一天往下滑，要是他再弯一次腰，我手上恐怕就要爆发骚乱了。\n\n如果你能给他做几条碧蓝丝质腰带，让他明白意思……只是别告诉他是我派你来的——就说这是一位“忧心的旅店客人”送的礼物。",
  },
  [8960] = {
    ["T"] = "伯德雷的不幸",
    ["O"] = "前往黑石山，使用超维度幽灵显形器在黑石塔附近找到伯德雷。",
    ["D"] = "那么也就是说我们需要找回勋章的其他部分？要找伯德雷可有点麻烦。他去了黑石山，想尝试重新进入黑石塔，结果就再也没有回来。\n\n我建议你带上地精的幽灵显形装置，因为我担心最坏的情况可能已经发生了。",
  },
  [8961] = {
    ["T"] = "两位烈焰之王",
    ["O"] = "收集伊森迪奥斯的余炭和艾博希尔的灰烬，再带上一只神圣火盆，把它们交给黑石山内的伯德雷。",
    ["D"] = "要召唤瓦塔拉克公爵，我们首先需要收集饰品剩下的三分之二。为此，我们需要一只火盆，以及一些能在其中燃烧的特殊炭块。\n\n有两位火焰贵族：黑石深渊的伊森迪奥斯公爵，以及黑石塔的烈焰卫士艾博希尔。他们拥有我们需要的东西。从他们两人身上各收集一块残骸，然后带着一只神圣火盆回到我这里。如果你在银色黎明中的声望达到尊敬，就能从他们那里买到神圣火盆。",
  },
  [8966] = {
    ["T"] = "瓦塔拉克公爵饰品的左瓣",
    ["O"] = "使用召唤火盆召唤莫尔·灰蹄的灵魂并杀死他。带着瓦塔拉克公爵饰品的左瓣和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "我的朋友莫尔·灰蹄，是第一个因为拥有瓦塔拉克公爵饰品的一块碎片，以及其中蕴含的腐化灵魂碎片而受害的人。偷走瓦塔拉克的法术书和饰品后，我们从黑石塔上层逃命。途中，莫尔跌进了塔的下层。\n\n后来，我们发现他在坠落中活了下来，却被指挥官沃恩俘虏并折磨。几个鬼魂刺客溜进去，当着沃恩的面杀死了他。",
  },
  [8967] = {
    ["T"] = "瓦塔拉克公爵饰品的左瓣",
    ["O"] = "使用召唤火盆召唤伊萨莉恩的灵魂并杀死她。带着瓦塔拉克公爵饰品的左瓣和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "后来，在我们竭尽所能求生时，我们得知队伍中的暗夜精灵牧师伊萨莉恩，去了人类监狱托尔巴拉德，探望她被囚禁的朋友法尔林·树影。\n\n但她没能到达。消息传回来说，她在一间候见室里遭到了鬼魂刺客的伏击，毫无疑问是瓦塔拉克公爵派去的。那间候见室如今用来关押一名强大的法师。",
  },
  [8968] = {
    ["T"] = "瓦塔拉克公爵饰品的左瓣",
    ["O"] = "使用召唤火盆召唤亚雷恩和索托斯并杀死他们。带着瓦塔拉克公爵饰品的左瓣和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "佣兵团解散后，亚雷恩和索托斯这对兄妹决定加入血色十字军。他们带走了瓦塔拉克公爵饰品的左瓣。我倒觉得他们走了也好，但我们需要把那一瓣拿回来。\n\n根据我们能收集到的消息，他们其实是在血色堡垒中达索汉大十字军的房间里，因为未能通过入会仪式，被达索汉亲手杀死。\n\n无论如何，我们……也就是你，仍然需要取回那块饰品。",
  },
  [8969] = {
    ["T"] = "瓦塔拉克公爵饰品的左瓣",
    ["O"] = "使用召唤火盆召唤库尔莫克的灵魂并杀死他。带着瓦塔拉克公爵饰品的左瓣和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "现在我们有了所需之物，该谈谈你要召唤的是谁了。\n\n库尔莫克作为食人魔还算可以，直到他转向通灵术为止。那之后，队伍里的每个人都觉得事情变得毛骨悚然。因此，他带着自己的饰品碎片回到新家通灵学院，并不让人意外。\n\n但即便在那里，或者说尤其是在那里，他也没能逃过鬼魂刺客的毒手。它们当着他主人莱斯·霜语的面杀死了他。",
  },
  [8989] = {
    ["T"] = "瓦塔拉克公爵饰品的右瓣",
    ["O"] = "使用召唤火盆召唤莫尔·灰蹄的灵魂并杀死他。带着重新组合的瓦塔拉克公爵饰品和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "我的朋友莫尔·灰蹄，是第一个因为拥有瓦塔拉克公爵饰品的一块碎片，以及其中蕴含的腐化灵魂碎片而受害的人。偷走瓦塔拉克的法术书和饰品后，我们从黑石塔上层逃命。途中，莫尔跌进了塔的下层。\n\n后来，我们发现他在坠落中活了下来，却被指挥官沃恩俘虏并折磨。几个鬼魂刺客溜进去，当着沃恩的面杀死了他。",
  },
  [8990] = {
    ["T"] = "瓦塔拉克公爵饰品的右瓣",
    ["O"] = "使用召唤火盆召唤伊萨莉恩的灵魂并杀死她。带着重新组合的瓦塔拉克公爵饰品和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "后来，在我们竭尽所能求生时，我们得知队伍中的暗夜精灵牧师伊萨莉恩，去了人类监狱托尔巴拉德，探望她被囚禁的朋友法尔林·树影。\n\n但她没能到达。消息传回来说，她在一间候见室里遭到了鬼魂刺客的伏击，毫无疑问是瓦塔拉克公爵派去的。那间候见室如今用来关押一名强大的法师。",
  },
  [8991] = {
    ["T"] = "瓦塔拉克公爵饰品的右瓣",
    ["O"] = "使用召唤火盆召唤亚雷恩和索托斯并杀死他们。带着重新组合的瓦塔拉克公爵饰品和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "佣兵团解散后，亚雷恩和索托斯这对兄妹决定加入血色十字军。他们带走了瓦塔拉克公爵饰品的右瓣。我倒觉得他们走了也好，但我们需要把那一瓣拿回来。\n\n根据我们能收集到的消息，他们其实是在血色堡垒中达索汉大十字军的房间里，因为未能通过入会仪式，被达索汉亲手杀死。\n\n无论如何，我们……也就是你，仍然需要取回那块饰品。",
  },
  [8992] = {
    ["T"] = "瓦塔拉克公爵饰品的右瓣",
    ["O"] = "使用召唤火盆召唤库尔莫克的灵魂并杀死他。带着重新组合的瓦塔拉克公爵饰品和召唤火盆回到黑石山内的伯德雷那里。",
    ["D"] = "现在我们有了所需之物，该谈谈你接下来要召唤的是谁了。\n\n库尔莫克作为食人魔还算可以，直到他转向通灵术为止。那之后，队伍里的每个人都觉得事情变得毛骨悚然。因此，他带着自己的饰品碎片回到新家通灵学院，并不让人意外。\n\n但即便在那里，或者说尤其是在那里，他也没能逃过鬼魂刺客的毒手。它们当着他主人莱斯·霜语的面杀死了他。",
  },
  [8994] = {
    ["T"] = "最后的准备",
    ["O"] = "收集40副黑石护腕，并取得一瓶超级能量合剂。把它们交给黑石山内的伯德雷。",
    ["D"] = "就快好了，$c。剩下的只是取回几样材料，好让我调谐火盆，使它能够召唤瓦塔拉克公爵。\n\n首先，我必须请你进入黑石塔，杀死里面的兽人。他们佩戴的护腕里含有我需要的微量金属，所以我需要不止几副，才能从中提取出合适的数量。然后，为了完成灌注过程，你还需要带给我一瓶超级能量合剂。\n\n祝你好运，$N！",
  },
  [8995] = {
    ["T"] = "认罪吧，瓦塔拉克公爵",
    ["O"] = "使用召唤火盆召唤瓦塔拉克公爵。解决他，并对尸体使用瓦塔拉克公爵的饰品。然后，把瓦塔拉克公爵的饰品还给瓦塔拉克公爵之魂。",
    ["D"] = "一切都已准备就绪，$N。\n\n瓦塔拉克公爵生前曾居住在如今比斯巨兽的房间。到那里去，使用召唤火盆召唤瓦塔拉克公爵。火盆会让他重新凝聚实体，所以你还得再杀他一次。我会先处理掉比斯巨兽，并确保带上足够多的朋友，才能在黑石塔上层活下来。\n\n一旦你解决了瓦塔拉克，就对他的尸体使用饰品。随着他的灵魂重新合一，他很可能也会想要回自己的饰品。\n\n祝你好运！",
  },
  [8996] = {
    ["T"] = "返回伯德雷那里",
    ["O"] = "返回黑石山内的伯德雷那里，把召唤火盆交给他。",
    ["D"] = "这一次我会无视你的无礼，$c，因为你今天做了一件高贵的事：把我被偷走的灵魂其余部分还给了我。尽管你的本性显然很软弱，$r，你仍展现出那些偷我东西的人没有、也许永远不会有的勇气！\n\n在我改变主意并当场杀死你之前，回到他们那里去。回去告诉他们，他们安全了……至少现在是。",
