    ["D"] = "我想，这就是道别了，我的朋友。不过，如果你偶尔想回来和我谈谈，我会一直在这里。大概就在你闲晃着等朋友加入你去突袭黑石塔的时候。\n\n走吧，趁我还没开始哭。回奥格瑞玛找莫克瓦，告诉他发生了什么。",
