  [26243] = {
    ["T"] = "炽热宝石",
    ["O"] = "找人鉴定炽热宝石。",
    ["D"] = "这颗宝石看起来几乎和燃烧平原上随处可见的黑曜石碎片一样，只是带着一道独特的红色光泽。在强光前观察时，碎片内部有一团旋转的烟雾在舞动，而握住水晶太久，就会感受到它散发出的惊人热量。\n\n燃烧平原上的某个人也许会对这件东西感兴趣。",
  },
  [26244] = {
    ["T"] = "取得黑曜石",
    ["O"] = "从燃烧平原周围的黑曜石元素和战争掠夺者身上收集24块黑曜石碎片。",
    ["D"] = "听说暗炉城有些家伙用这些玩意儿制造黑曜石合金，把它们做成魔法武器之类的东西。我一直想亲自试试……\n\n怎么样？我保证会给你做件好东西。开头只需要从山谷周围的元素和战争掠夺者身上弄些黑曜石，然后我们再处理更有意思的试剂……",
