  [26245] = {
    ["T"] = "恶魔之火",
    ["O"] = "从燃烧平原周围的火焰小鬼身上收集8颗闷燃之心。",
    ["D"] = "好吧，见过这里那些在熔岩里跳舞的小鬼吧？讨厌的家伙……\n\n你杀过一只，见过它肚子里是什么样吗？心脏本该在的地方，是一块燃烧的岩石。\n\n如果你不怕给武器沾上一点恶魔味儿，就能把它用进合金里！",
  },
  [26246] = {
    ["T"] = "巨龙之火",
    ["O"] = "从燃烧平原周围的巨龙、龙人或雏龙身上收集12个闪火腺体。",
    ["D"] = "你有没有想过巨龙是怎么喷火的？大多数人说那是魔法……但巨龙的内脏可是炼金师的美梦。\n\n各种化学物质混在一起，然后巨龙把它们从嘴里喷出来，混合物接触空气就会点燃。我这话是有目的的……\n\n其中一种基础化学物质，正好能作为我们武器的优良助熔剂，让黑曜石合金结合得更牢。\n\n你要找的腺体是红色的，色泽很深，几乎会发光……哦，而且它在心脏附近。不是肺旁边那些……\n\n这里大多数喷火的家伙都很危险，所以你可能需要一点帮助。目标越成熟，你弄到腺体的机会就越大。",
  },
  [26247] = {
    ["T"] = "灼热武装",
    ["O"] = "进入黑石深渊，在暗炉城中心的黑铁砧上锻造你武器的基底。",
    ["D"] = "好吧……我可能漏掉了一个小小、小小、非常小的小细节……\n\n合金做好了，但我其实没法在这里锻造你的武器！它得在黑石深渊里暗炉城中心的那座黑铁砧上成形。\n\n我知道，我知道！我只是觉得等我们把所有材料都弄齐后，你会更有动力一点。\n\n所以……你有吗？我会给你带上几张结构图——简单到连婴儿都能看懂！只要在路上决定你想要什么，尽力把它塑形，然后带回这里，我就能完成最后的工序。也带上几个朋友吧。",
  },
  [26277] = {
    ["T"] = "烈焰萨满",
    ["O"] = "杀死黑石深渊中的控火师罗格雷恩，然后返回安戈洛环形山马绍尔营地的雅鲁尼·观焰者那里。",
    ["D"] = "我在大地之环的职责包括监视萨满对火焰能量的使用——以及滥用。最近，我从遥远的黑石山方向感到了一股刺耳而强烈的火焰牵引。\n\n我相信一名前大地之环成员投靠了居住在山脉深处的黑铁矮人，并正在试验将萨满使用的火元素能量，与法师使用的奥术火焰魔法混合。\n\n这种对元素的亵渎必须被阻止。我需要留在这里继续研究原始魔法——但也许你和几位同伴能处理掉这个叛逃的萨满。\n\n他的名字叫托纳卡·罗格雷恩。",
  },
  [26279] = {
    ["T"] = "更好的东西",
    ["O"] = "杀死黑石深渊深处的玛格姆斯，然后返回燃烧平原摩根的岗哨的奥拉留斯那里。",
    ["D"] = "温基船长输不起。输！不！起！\n\n温基说黑铁矮人有好东西，但我说不！一定有更好的。\n\n然后我听说真的有。\n\n它叫玛。玛。\n\n玛。格。\n\n玛。格姆斯。玛格姆斯！杀了它！不过也许别用火。",
  },
  [26306] = {
    ["T"] = "熔火之心的传送门",
    ["O"] = "用隔热瓶装取黑石深渊中熔火之心入口附近流淌的熔岩，并从附近墙上收集一块熔核碎片。",
    ["D"] = "现在你必须收集试剂，以与这座山的热量调谐。我们需要来自熔火之心本身的热量与共鸣样本——或者尽你安全所能接近它。\n\n进入被称为黑石深渊的黑铁矮人要塞。一路前往最底层，你会找到他们的熔炼站。用这只隔热瓶装取附近灼热的熔岩。\n\n然后穿过通往熔火之心的桥，从附近墙上收集一块碎片。\n\n不要误会，凡人，这是一项危险任务，你绝不会想独自完成。之后回到我这里来，如果你活下来的话。",
  },
  [26307] = {
    ["T"] = "熔火之心的传送门",
    ["O"] = "站着别动，让海达克西斯公爵用保护咒符为你灌注，使你能安全进入熔火之心。",
    ["D"] = "我将用你收集的材料，以我的祝福强化你。它只会在熔火之心中保护你，因为它调谐的是这座山独有的共鸣。\n\n坚持住，凡人！这可能会有点灼痛，但如果你要深入黑石山真正的核心，这是必要之恶。",
