  [26395] = {
    ["T"] = "冲突号召：燃烧平原",
    ["O"] = "在燃烧平原内找到并杀死5名部落成员。",
    ["D"] = "燃烧平原属于联盟，我们必须不断证明这一点。追猎部落成员，代表军队杀死他们，以证明你的价值并提升军阶。",
