  [26396] = {
    ["T"] = "冲突号召：燃烧平原",
    ["O"] = "在燃烧平原内找到并杀死5名联盟成员。",
    ["D"] = "燃烧平原属于部落，我们必须不断证明这一点。追猎联盟成员，代表军队杀死他们，以证明你的价值并提升军阶。",
  },
  [26496] = {
    ["T"] = "仪式知识",
    ["O"] = "进入黑石塔下层，从裂盾术士、火印恐法师和血斧召唤师身上收集因库拉的笔记。把笔记带给燃烧平原的朱纳里。",
    ["D"] = "那些强闯进黑石塔下层的兽人氏族，队伍里有好几种术士。裂盾氏族吹嘘自己样样都行，火印专精恐惧，血斧则专精他们的恶魔。\n\n他们共同点是，所有术士都向因库拉女主人汇报。或者说曾经如此，直到她遇见我。\n\n因库拉是个聪明的兽人，她设计出一种仪式，让术士可以创造治疗石之泉。为了防止任何人挑战她的力量，她把自己的知识分散给三个氏族。\n\n这样的仪式会很有用，不是吗，$N？等你从黑石塔取回那些笔记后，就需要我帮你解读。",
  },
  [26595] = {
    ["T"] = "魔法勋章",
    ["O"] = "找一个能告诉你更多魔法勋章信息的人。",
    ["D"] = "你找到了一枚必定被强大魔法灌注过的勋章，因为它似乎完全能抵御黑石山中流淌熔岩的高温。勋章上刻着一个简单图案——一圈分段的圆环。\n\n你不熟悉这个符号，但世上肯定有人会知道……",
  },
  [26597] = {
    ["T"] = "魔法勋章",
    ["O"] = "把魔法勋章带给安戈洛环形山的雅鲁尼·观焰者。",
    ["D"] = "不是？你说它漂在黑石山的熔岩里？嗯，至少这是个好故事。也许这样能避免惹恼大地之环。\n\n没错，这枚饰物上有大地之环的标志。你知道，就是那群神秘、古老的萨满类型人物。大概掌握着他们秘而不宣的疯狂力量之类的。\n\n如果你是那种想把这小发现归还的老好人，我想我听说他们有个成员在安戈洛附近，研究原始元素。不过，来……\n<玛尔冯调整了勋章。>\n如果你想留着，它应该就和新的一样了。无论它以前属于谁，那人肯定已经不需要它了……",
  },
  [26633] = {
    ["T"] = "武装灰落岗哨",
    ["O"] = "从索瑞森废墟中的索瑞森间谍和索瑞森密探身上取回10把黑铁匕首和5支黑铁枪。",
    ["D"] = "有空吗？你看起来不像是怕打架的人。\n\n以前在暗炉城，我是个军官……某种程度上……也就是说手下有很多矮人。我干别的事都没用，所以我打算对兄弟会变得不可或缺。能用上你的帮助。\n\n你可能觉得这个小村子很安全，但每隔几个月就会有一支兽人突袭队路过。那个叫莫根的小伙子尽力把大家的武器维护好，但袭击来得太频繁了。\n\n在索瑞森剩下的废墟那边，有些讨厌的间谍和密探全副武装。想替这里的卫兵征用一些他们的武器吗？我会付钱。",
  },
  [26634] = {
    ["T"] = "受够那些兽人了！",
    ["O"] = "杀死灰落岗哨西边的30名黑石兽人。",
    ["D"] = "就在这里西边，我们得对付黑暗部落那些小喽啰。我不指望你去挑战一整支军队，但你每杀掉一个兽人，都可能救下这里的一条命。\n\n你想去削减一下这支部落吗？我盯上了带领他们的头头，但我还得再侦察一阵。",
  },
  [26636] = {
    ["T"] = "打在痛处",
    ["O"] = "杀死灰落岗哨西北方黑石要塞内的纳戈什·怒刃。",
    ["D"] = "好吧，所以……我查到了这一带的兽人头领，或者你想怎么叫都行……据我看，他有点像个新上位的家伙——最近才坐上这个位置。\n\n名字叫纳戈什·怒刃。黑石山以东那座大堡垒就是你能找到他的地方……也就是这里西北方。他身上肌肉可不少，所以当心点……大概配得上那个荒唐名字。\n\n狩猎顺利，$C。",
  },
  [26638] = {
    ["T"] = "束缚护腕",
    ["O"] = "从燃烧平原各处的敌人身上拾取30块黑铁碎片。",
    ["D"] = "嗯……护腕？这设计还挺有意思。比我这圆滚滚的老肚子还粗！那个大家伙真有这么粗的手腕吗？！\n\n<莫根听你解释用护腕束缚火元素并摧毁它，从而平息土地的计划。>\n\n哈，这才是我能支持的计划！很乐意帮忙，不过别以为我手头有足够金属做这种工程。倒是可以用黑铁碎片来做……\n\n很多人都用黑铁做护甲、武器、小玩意儿——什么都有！给我带些碎片回来，我就免费开始做那些护腕——我也想狠狠教训那个讨厌的火焰领主！",
  },
  [26640] = {
    ["T"] = "地狱符文",
    ["O"] = "从燃烧平原周围的人形施法者身上收集15枚地狱符文。",
    ["D"] = "我已经收集到了我们需要的所有材料……只差一样。\n\n年长的矮人说，当巫士领主统治时，巨槌石顶端的祭坛曾是早期尝试召唤火焰的地点。那个时代遗留下来的符文，也许能用于我们的仪式。\n\n这些符文蕴含力量，就像飞蛾扑火一样，平原各地的施法者都会寻找它们。\n\n<格鲁尔给你看他胸口一处新鲜的灼伤。>\n\n我已经过了巅峰期——身体不再像过去那样灵活，战斗中差点倒下。请你代替我前去，把你找到的所有符文带回来。",
  },
  [26641] = {
    ["T"] = "被召唤而出",
    ["O"] = "在巨槌石顶峰的祭坛召唤并击败火焰显现。",
    ["D"] = "<格鲁尔低声念诵，并用手在符文上方挥过，每一枚符文都随之颤动发光。>\n\n嗯……就是这一枚。声音在呼喊时，这枚符文也在向我低语。让我准备好它，用来进行束缚。\n\n<几分钟过去，格鲁尔用收集来的所有材料完成了工作。>\n\n好了。仪式很简单——在巨槌石顶端的祭坛使用这枚符文。这片土地翻腾的能量会迸发进护腕，被束缚成一个元素形态。击败它，就会熄灭束缚中消耗的所有能量。\n\n正如我之前所说，火焰是狂暴的元素。接下来的战斗中，你可能需要招募一些盟友。",
  },
  [26643] = {
    ["T"] = "是食人魔吗？",
    ["O"] = "在巨槌石北侧某处寻找米兰的踪迹。",
    ["D"] = "<搏斗痕迹和被遗弃的袋子表明，米兰是在这里被带走，而不是被杀。>\n\n<巨大的脚印以及靠近巨槌石的位置暗示，袭击者是食人魔。脚印朝北延伸了一段距离。米兰也许还活着。>",
  },
  [26645] = {
    ["T"] = "米兰的逃脱",
    ["O"] = "护送米兰离开巨槌石。",
    ["D"] = "呃啊！退后，你这蛮子！你——\n\n<米兰发现你不是食人魔。>\n\n你、你是谁？！你是……友善的？是我妻子派你来的吗？哦，米尔蒂斯……\n\n我可以……我可以跟你一起走吗，如果不太麻烦的话？那些食人魔把我当玩偶一样对待……已经弄断了我几根骨头，如果你把我留在这里，我撑不了多久。",
  },
  [26646] = {
    ["T"] = "我们之中的间谍",
    ["O"] = "从游荡在索瑞森废墟的矮人身上寻找追踪的证据。",
    ["D"] = "$C。我有个提议。暗炉城里的事对我和我兄弟来说变得有点太火热了，所以我们一路来到这里，想和瑟银兄弟会开始新生活。\n\n<佩林靠近了一些，压低声音耳语。>\n\n说实话，我觉得我们被跟踪了。议会还没放过我们——他们想把我们拖回律法之环，清算过去的恩怨……\n\n间谍像老鼠一样潜伏在更北边的废墟里。杀几个……看看其余的怎么逃回深渊。最重要的是，看看你能不能找到任何关于我和我兄弟的重要东西。",
  },
  [26648] = {
    ["T"] = "问题根源",
    ["O"] = "进入黑石深渊内的居住区，杀死伊格维尔·马利斯特并夺取他的项链。",
    ["D"] = "其实我有两个亲族。卡鲁姆在这里，另一个伊格维尔在暗炉城里——鼻子拍马屁拍得那么棕，你都看不出他是黑铁矮人。他是个打点人，许多议员都会利用他的服务干些邪恶勾当。\n\n当我们谈起逃离时，他鄙视我们，怒气冲冲地离开，结果带着卫兵回来。卡鲁姆处理了他们，伊格维尔逃走了，我们就到了现在这地步。那小子派毒师来对付我们，已经显露了本性。\n\n我听说有些劫掠队进入城里制造混乱。加入他们的队伍，杀了他，把他戴的项链带给我。你肯定能在居住区找到他在那里攀谈套近乎。",
  },
  [26649] = {
    ["T"] = "抢夺傀儡",
    ["O"] = "在索瑞森废墟北方山脚找到傀儡师卢加尔，并夺取他的控制魔棒。",
    ["D"] = "我一直在找你们这种冒险者！能帮我个忙吗？\n\n我想要一个傀儡来帮助这里的卫兵。我为年轻时学到的傀儡术感到自豪，但这地方可不是什么制造厂。要从头做一台那种掠夺者，可是件苦差事。\n\n我听说北边废墟外的山脚有个名叫卢加尔的傀儡师，在修理这一带的旧战争掠夺者——他正在做一个我很感兴趣的宠物项目……\n\n他有某种魔棒，能让他控制自己的私人傀儡。看看你能不能弄到那根魔棒，我们的事就成了！",
  },
  [26650] = {
    ["T"] = "立足于巨人之上",
    ["O"] = "从燃烧平原的战争掠夺者身上收集一块完好的共振水晶，并使用赫尔加的符文瓶从附近熔岩池中虹吸一些熔岩。",
    ["D"] = "<赫尔加过了片刻睁开眼睛。>\n\n嗯……我能看出他还没完成，但至少基础部分都处理好了。\n\n我会想办法把傀儡弄到这里来。对于可以做的改进，我有几个点子！\n\n共振水晶裂开了，用控制魔棒时很难看清。试着从这一带的战争掠夺者身上找一块看起来像样的。\n\n哦，还有符文有点磨损——需要用一些熔岩把它们整理好，你会需要这个。\n\n<赫尔加递给你一个刻着符文、像玻璃一样的瓶子。>\n\n西边路旁应该有个熔岩池……但小心别掉进去！那只瓶子多年来一直很可靠，所以不用担心拿着它。",
  },
  [26651] = {
    ["T"] = "充能核心",
    ["O"] = "把惰性傀儡核心带到黑石山西边的风暴祭坛，并为它充能。",
    ["D"] = "卢加尔没有完全给他的傀儡核心充能，但反正我想用一个自己从黑石带来的定制核心。我的容量更大，所以我有个想法……\n\n山西边有个地方叫风暴祭坛。据说那是兽人魔法的场所……\n\n如果这座风暴祭坛名副其实，我敢说它就是给这宝贝充能的完美地点！\n\n怎么样，$N？应该不会太麻烦。呃，我觉得……总之……",
  },
  [26652] = {
    ["T"] = "正合适的油",
    ["O"] = "从燃烧平原周围的毒尖蝎、死鞭蝎和火尾蝎尸体上收集16瓶蝎子黏液。",
    ["D"] = "人人都知道，好傀儡的秘诀在于它身上的润滑脂。你以为石头不会裂开，只是因为我们在用魔法吗？不，先生！\n\n就在前几天，我看见一个商人带着一车死蝎子进来。那些东西身上流下来的黏液——简直像一条滑腻的河！我觉得那东西对我们的新傀儡很有潜力。\n\n你愿意替我们收集一些吗？你会在平原各处找到那些蝎子。这里有些空瓶——把它们全都装满就行！",
  },
  [26653] = {
    ["T"] = "傀儡术的艺术",
    ["O"] = "在不失去控制且不让斯图尔特死亡的情况下，控制斯图尔特杀死燃烧平原中的20名敌人。",
    ["D"] = "好吧，$N。我想要的东西都齐了，也给它修整了一下。它已经启动并能运作了……\n\n想找点乐子吗？！\n\n带它出去转一圈！去和任何你喜欢的东西打一架，不过我想确保这次测试是真正有效的——也就是说，你的专注不能被打断！等你准备好就告诉我。\n\n哦……它的名字叫斯图尔特。",
  },
  [26654] = {
    ["T"] = "火腹",
    ["O"] = "从巨槌石的火腹食人魔身上收集30副火腹。",
    ["D"] = "嘿……你懂魔法吗？\n\n我要做一些雾石——孩子们喜欢那玩意儿。不过先需要从东边那些食人魔身上弄些试剂。\n\n我已经很久没见过他们了，但我怀疑食人魔的内脏不会有太大变化。需要他们的肚肠，如果这还不够明显的话。",
  },
  [26656] = {
    ["T"] = "抵御寒意",
    ["O"] = "在燃烧平原收集8张灰烬座狼毛皮。",
    ["D"] = "我知道你在想什么……\"这家伙接下来八成要我去给他弄些该死的石头\"，对吧？\n\n嘿嘿……石头我已经有了，所以别担心。这些肚肠还得晾干，然后我会把它们磨碎。\n\n<杰森·廷林打了个寒颤。>\n\n老天……你感觉到空气里的寒意了吗？冻得我骨头疼……\n\n这样吧：给我带些在这片土地上游荡的座狼毛皮回来，我就给你一些雾石。",
  },
  [26957] = {
    ["T"] = "制弓师的委托",
    ["O"] = "从黑石塔的巨魔身上收集一根绷紧的弩弦。",
    ["D"] = "最后这一步会非常棘手，$N。游侠玛瑞斯做弓弦时，用的是只有奎尔萨拉斯才制造的附魔精灵丝线。\n\n<玛瑞尔叹了口气。>\n\n我们不可能再找到更多了，但我听到一个传言，说与黑石兽人结盟的巨魔是远程武器大师。也许他们使用的弓弦可以作为不错的替代品。你得深入黑石塔的深处去查个明白。",
  },
  [26961] = {
    ["T"] = "英雄崇拜",
    ["O"] = "从黑石塔的巨魔身上收集一根绷紧的弩弦。",
    ["D"] = "粗活都已经完成了，$C。你现在只需要弓弦。过去我用的是只有奎尔萨拉斯才制造的附魔精灵丝线。显然，你得找个替代品。\n\n我听到一个传言，说与黑石兽人结盟的巨魔是远程武器大师。也许他们使用的弓弦可以作为不错的替代品。不过你得深入黑石塔的深处去查个明白……我可不会等着你回来。",
  },
  [27178] = {
    ["T"] = "合同 #1001：熔火恶犬粪便",
    ["O"] = "在黑石塔比斯巨兽的房间里，用箱子装满熔火恶犬粪便。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。我们都喜欢食物，对吧？那么这份合同就能让农产品部门受益。\n\n合同 #1001：从黑石塔内部取得熔火恶犬粪便\n\n数量：一箱",
  },
  [27179] = {
    ["T"] = "合同 #1024：黑铁炉渣",
    ["O"] = "从黑石深渊中的重要矮人身上收集4把黑铁炉渣。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。这一份能让我们的玩具部门受益。\n\n合同 #1024：从黑石深渊内部取得黑铁炉渣\n\n数量：四把",
  },
  [27181] = {
    ["T"] = "合同 #1063：食人魔麝香",
    ["O"] = "从黑石塔收集4品脱食人魔麝香。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。这一份来自香水、古龙水和香薰蜡烛部门。\n\n合同 #1063：从黑石塔下层取得食人魔麝香\n\n数量：四品脱",
  },
  [27928] = {
    ["T"] = "荣誉与鲜血的回忆",
    ["O"] = "前往燃烧平原，杀死附近的黑石士兵、黑石杀戮者和黑石巫师，以纪念洛萨。",
    ["D"] = "我曾在第一次和第二次战争中与人类交战，$C。他们是强大的对手。我亲眼见证奥格瑞姆·毁灭之锤杀死安度因·洛萨，也见证联盟在领袖死后重新集结。那份荣耀出乎意料。\n\n联盟在燃烧平原为洛萨建了一座雕像，但仍忠于军团的黑石兽人盘踞在那一带。削减他们的数量，以此向洛萨的勇气致敬，也为我们自己的防御着想。",
  },
  [28011] = {
    ["T"] = "奥术仪式",
    ["O"] = "在黑石塔下层，从裂盾侍僧、裂盾缚法师和裂盾术士身上收集8份共振灰烬，交给奥特兰克山脉拉文霍德庄园的菲莉希蒂。",
    ["D"] = "我就直说了——我们遇到麻烦了，$N。二十年前，肯瑞托的法师们在拉文霍德庄园施放了一个防窥雕文，用来隐藏洛丹伦联盟训练间谍和潜行者的中心。这个早已失效的盟约遗物如今变得不稳定，我们必须在它爆炸、打开通往虚空的传送门，或引发别的可怕奥术事故之前移除它。\n\n我咨询了肯瑞托剩下的人，确定可以用共振灰烬削弱这个雕文。那是黑石山的裂盾兽人使用的一种物质。只有附魔师才能安全处理这种灰烬——落到其他人手里，它只会闪烁着消散成虚无。\n\n那么……我能指望你帮忙吗？",
  },
  [28368] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "密探梅里根要你使用急救技能制作一份强力抗毒药剂，并把它带到燃烧平原他的洞穴里。",
    ["D"] = "我马上会告诉你任务内容，但我们必须先处理一个紧急情况。\n\n我的伪装还算成功，但我对霍尔登的感情很难掩饰。他中毒了，很可能是黑石兽人在试探我的决心。我已经设法减缓毒性发作，但我需要一份强力抗毒药剂，否则他会死。\n\n帮我救霍尔登，我就把你想知道的一切都告诉你。",
  },
  [28369] = {
    ["T"] = "疗愈者仪式",
    ["O"] = "在黑石要塞杀死乌斯莫格·断脊，并把他持有的任何文件带给燃烧平原的密探梅里根。",
    ["D"] = "我是个守信的人，$C。既然霍尔登正在恢复，我就告诉你发生了什么。\n\n黑石兽人没有质疑我们的存在。我们很容易混进了他们的值勤名单，但坏处是，我和格鲁玛尔下士被分到不同巡逻队时失散了。这让我更难维持伪装。我看起来也许和兽人一模一样，但我并不了解所有细枝末节。所以我不得不撤出来。\n\n格鲁玛尔融入得很顺利，但我已经好几天没见过他了。我不知道他被分派到哪里。唯一知道这情报的人，是黑石要塞的指挥官乌斯莫格·断脊。他保管着唯一一份他们部队分配的书面文件。这要求很高，但你必须除掉他，才能拿到我们需要的情报。",
  },
  [31022] = {
    ["T"] = "奥术疫病",
    ["O"] = "维利戈斯要我们一路杀进碧蓝栖地洞穴深处，杀死正在为水晶灌注能量的食人魔。",
    ["D"] = "那些黑石蠢货一定找到了我的宝珠，并把它重新拼了起来……或者不知怎么模仿了它的魔法。毫无疑问，他们是想汲取水晶的力量。\n\n做出这种事的人必定非常强大，而且掌握着最阴险的魔法。我在附近感觉不到这样的存在，但确实有什么东西在这里。\n\n山边那座洞穴里正在举行仪式。杀掉引导那些法术的人，这应该能拖慢水晶的变化，为我们争取一些时间。",
  },
  [31024] = {
    ["T"] = "奥术疫病",
    ["O"] = "碧蓝栖地的维利戈斯要我们深入黑石塔下层，召唤并杀死尖石氏族真正的首领乌洛克，取回他控制宝珠的第二部分。",
    ["D"] = "我们已经取回了宝珠的一部分，现在需要追踪另一部分。\n\n<维利戈斯把他的魔法注入碎片，它似乎与某个东西产生了共鸣。>\n\n召集你的盟友，$r，前往黑石山，杀死乌洛克。我感觉到他正躲在一道魔法帷幕之后。击溃他的追随者，把他从阴影中拖出来，挑战他的统治，让这个世界摆脱他的黑暗影响。\n\n把我控制宝珠的最后一部分带给我，我现在要集中精力，为将要到来的事积蓄力量。",
  },
  [26853] = {
    ["T"] = "灼热之魂",
    ["O"] = "寻找被煤渣挖掘场惊扰的灵魂，并让它们安息。",
    ["D"] = "煤渣挖掘场似乎惊扰了早已死去的生物灵魂。有人向我报告说，灼热之魂如今正在挖掘场南边的丘陵和平原上游荡。我想让你把这些灵魂送回大地，让它们再次安息。这是我能为我兄弟惹出的麻烦做的最起码的事。",
  },
  [26861] = {
    ["T"] = "灼热之魂",
    ["O"] = "寻找被煤渣挖掘行动惊扰的灵魂，并带回6份灼热精华。",
    ["D"] = "煤渣挖掘场似乎惊扰了早已死去的生物灵魂。它们的灵魂如今正在挖掘场南边的丘陵和平原上游荡。我想为我的研究收集这些存在的精华。\n\n别担心，你应该能活着完成这件事。",
  },
  [30000] = {
    ["T"] = "黑铁镐",
    ["O"] = "找到箱子，并用一份山脉之血解锁它，谁知道你会得到什么呢？",
    ["D"] = "<检查你买来的矿镐时，你注意到镐柄内部有个空腔。你扭动镐柄底部，它掉了下来，一张纸也从空腔里飘落出来。>\n\n\"我留下这封信，是希望某位自豪而技艺精湛的矿工能发现藏着它的空间，或许也可能是你下手太重，把镐柄砸断了！这把镐坚固可靠，但还不足以应对那些你或许尚未见过的最坚硬矿物，因此我花了许多年研究一份传奇矿镐的配方。我没能完全成功，如今也太老了，没法亲手打造它，但我不想随随便便把这份知识交出去。\"\n\n\"找一份山脉之血，这东西可以从黑铁矿脉里不知疲倦地挖出来，不过就算你从别人手里买一份，我在九泉之下也不会评判你。把这份血带到我旧居里的箱子那里，那是我们的皇帝召唤炎魔之王之前我住过的地方。如果你觉得这个方向太模糊，那你一定不是黑铁矮人！\"",
  },
  [26658] = {
    ["T"] = "看守者的请求",
    ["O"] = "在卡拉赞礼拜堂寻找隐藏的看守者钥匙，然后把钥匙带给逆风小径埃瑞丁营地的埃瑞丁·埃利斯。",
    ["D"] = "如果那地方对食人魔来说安全到足以进去搜刮，我想卡拉赞周围对你这样勇敢的冒险者来说，也足够安全，可以去调查一下。\n\n食人魔的战利品里没有庄园中的物品，这说明那地方依然锁得严严实实——希望魔法封印也还在。\n\n幸运的是，我过去总会在卡拉赞礼拜堂藏一把钥匙。沿着道路向南走到庄园，然后继续向西越过它，就能找到礼拜堂。看看你能不能找到那把钥匙！",
  },
  [26659] = {
    ["T"] = "看守者的请求",
    ["O"] = "使用看守者钥匙打开卡拉赞正门，然后回到逆风小径埃瑞丁营地的埃瑞丁·埃利斯那里。",
    ["D"] = "我不是法师，但我很会评估物品中的魔法强度——当你必须给麦迪文收集的各种小玩意儿掸灰时，这本事非常有用。\n\n这把钥匙里还残留着一些魔力，足以绕过通常设置在卡拉赞正门周围的魔法结界。我不能保证你使用钥匙时毫无危险，但如果你成功了，我们就能看看这座庄园如今究竟是什么状况。",
  },
  [26660] = {
    ["T"] = "看守者的请求",
    ["O"] = "使用看守者钥匙打开卡拉赞后门，然后回到逆风小径埃瑞丁营地的埃瑞丁·埃利斯那里。",
    ["D"] = "正门当然有强大的结界防范入侵者。但还有一扇后门，你可以从河岸滑下去，爬上庄园东北方向河对岸的高塔抵达。\n\n后门也有自己的防护，但我认为这把钥匙残留的魔力刚好足以绕过它们。再说一次，我也可能判断错了。但如果你愿意一试，就拿上钥匙去打开后门吧。希望你很快带着好消息回来。",
  },
  [27985] = {
    ["T"] = "实验室仪式",
    ["O"] = "与逆风小径营地里的埃瑞丁·埃利斯谈一谈。",
    ["D"] = "你知道吗，我见你来过这里很多次，必须称赞你对炼金术的掌握。事实上，我印象非常深刻，想推荐你接一份工作。\n\n一位旧识给我发来消息，说他需要有人帮助解开一个谜团，而这需要炼金大师的本领。你既有冒险精神，又有完成此事所需的才华，所以你是我第一个想到的人。\n\n如果你有兴趣，就前往逆风小径。你会在那条荒凉峡谷的某处找到埃瑞丁的营地。",
  },
  [27986] = {
    ["T"] = "实验室仪式",
    ["O"] = "埃瑞丁·埃利斯要你使用炼金术制作5瓶强效治疗药水、5瓶强效法力药水、5瓶石鳞鱼油和5瓶活力行动药水。把它们带给逆风小径的他。",
    ["D"] = "我曾多年担任卡拉赞的看守者。我自己也许不是才华横溢的炼金师，但我熟悉各种药水和药剂。取回卡拉赞炼金师们掌握的知识，是我的职责，但我需要一位技艺高超的人协助我。\n\n所以首先，我需要你证明自己具备那些本领。这里列着一些颇具挑战性的药水。为我酿制它们，证明你的技艺，然后我就会告诉你我们在这里究竟要做什么。",
  },
  [27987] = {
    ["T"] = "实验室仪式",
    ["O"] = "在南边的卡拉赞废墟中寻找炼金术书籍，把你找到的任何书带给逆风小径的埃瑞丁·埃利斯。",
    ["D"] = "你没能亲眼见到卡拉赞炼金实验室完整运作时的样子，真是遗憾。我过去常从图书馆借书，阅读炼金术的种种奇迹。灾难发生时我不在这里，身边还带着一本珍贵的典籍。正是那本典籍激励我回来，寻找更多。\n\n我相信你也许能在废墟的某处找到其他典籍。或许还在那些游荡于此的受困灵魂手中。请仔细搜遍废墟，把你找到的任何炼金典籍带回来。",
  },
  [27988] = {
    ["T"] = "实验室仪式",
    ["O"] = "从西瘟疫之地凯尔达隆岛通灵学院实验室的鬼灵教师身上收集解封油膏，并把它们带给逆风小径的埃瑞丁·埃利斯。",
    ["D"] = "真不敢相信你找回了杜安关于炼金术的私人笔记！我听说他战后发了疯，加入了血色十字军，但很久以前，他曾是卡拉赞的一名肯瑞托学徒。杜安在炼金术上很有天赋，也很有创造力，尽管他真正热爱的还是纯粹的奥术魔法。\n\n这本典籍里记载着我想重现实验的精确步骤，但我相信你也注意到了，它被一道结界保护着。肯瑞托的结界很强，但只要有合适的材料，就能将其破除。让我想想……\n\n我怀疑盘踞通灵学院的邪恶通灵师会有我们需要的东西。我听说他们有自己的炼金实验室，虽然我想象不出它能比得上卡拉赞的。诅咒教派是我们所有人的祸害。去那里，从他们手中夺取一些解封油膏。",
  },
  [27989] = {
    ["T"] = "实验室仪式",
    ["O"] = "埃瑞丁·埃利斯要你使用炼金术制作5瓶耀光药剂、5瓶先知药剂、5瓶强效防御药剂和5瓶猫鼬药剂。把它们带到逆风小径他的营地。",
    ["D"] = "是的，这本典籍现在可以阅读了。我们取得了极好的进展，$N。\n\n据我所知，杜安的研究是尝试把多种药剂合成为某种强大的大师药剂。这些尝试后来证明相当危险，于是有人要求他停止——也就是那时，他对炼金术失去了兴趣。现在没人阻止我们，所以我们可以从他停下的地方继续。\n\n杜安在这里列出了一份推荐药剂清单：耀光、先知、强效防御和猫鼬。你为什么不每种制作五瓶，然后我们试试看？\n\n如果成功，我们也许能创造出某种药剂，让我们进入卡拉赞内部，甚至清除我认为仍残留在里面的恶魔污染。",
  },
  [27991] = {
    ["T"] = "实验室仪式",
    ["O"] = "与逆风小径的埃瑞丁·埃利斯一同查看实验结果。",
    ["D"] = "我扯远了。请原谅一个怀旧老人的絮叨。\n\n我们应该已经具备进行这项实验所需的一切。我现在会按照杜安笔记中的指示组合材料。请和我一起见证这个谜团的结局。",
  },
  [28509] = {
    ["T"] = "给埃瑞丁·埃利斯的委托",
    ["O"] = "埃瑞丁·埃利斯要你使用钓鱼技能收集20条新鲜的白鳞鲑鱼，并把订单带给逆风小径埃瑞丁营地的埃瑞丁·埃利斯。",
    ["D"] = "我承认，当我动身返回卡拉赞时，并没有完全考虑到可能需要多少“野外补给”。我带了不少腌制食品，可是……和我在城里吃的东西相比，更不用说庄园里的饮食了，实在差得太远。\n\n我并不适合钓鱼——太潮湿，虫子也太多。但如果你能给我带来20条新鲜的白鳞鲑鱼，我会很感激能吃上一顿不是从罐子里来的饭。",
  },
  [31025] = {
    ["T"] = "奥术疫病",
    ["O"] = "碧蓝栖地的维利戈斯需要几种材料来召唤能压制疫病的魔法结界：\n\n- 流明石，一种抗魔金属，可在逆风小径卡拉赞之塔附近找到。\n- 四块来自安戈洛环形山石头守护者的守护之石。\n- 两块由熟练制皮师提供的硬甲皮。\n- 两块由裁缝提供的月布。\n- 两瓶由炼金师提供的抗魔药水。",
    ["D"] = "<水晶中传来清晰可闻的声响，并散发出可怕的热量。你感觉自己的本质仿佛正被拖入其中。>\n\n我们时间不多了，$n。我思考过无数种可能的解决办法，也许有一条路……宝珠已经无法修复，艾泽拉斯没有任何工匠技艺高超到足以修补它。但这并不意味着它毫无用处。我或许知道那些食人魔是怎样唤醒水晶的，这办法远谈不上优雅，但会有效。\n\n在我准备这些的时候，你需要再次踏上旅途。我们必须制作抗魔结界，阻止由水晶引起的奥术疫病继续扩散。等它稳定下来后，这些结界将确保封锁永久维持。\n\n前往逆风小径，在麦迪文之塔的地窖中，你会找到流明石，那是一种具有抵消魔法效果的稀有金属。不过要小心，地道和洞穴危险重重，到处都是受折磨的幽魂与亡灵。 \n\n接下来，前往安戈洛环形山。那里的土地守护者是强大的符文傀儡，在当地游荡。收集它们的守护之石，那些石头将作为结界的核心。\n\n为了保护结界免受元素侵蚀，去寻求熟练工匠的帮助。取得两块硬甲皮，以及两匹灌注了月亮井能量的布料。它们必须浸泡在抗魔混合物中。",
  },
  [31033] = {
    ["T"] = "不幸的阻碍",
    ["O"] = "在逆风小径寻找可能了解恶魔的人。",
    ["D"] = "到处都找不到流明石，但你在其中一个恶魔身上发现了一块石板。仔细查看后，它看起来是用难以理解的恶魔语写成的：\n\n瑞克 阿拉尔 伊尔 希 泽恩拉坎 洛克 基拉萨斯 拉卡 鲁克 阿什 希 维尼 帕恩 卡尔 洛克 雷沃拉 鲁卡达雷 伊尔 卡拉赞。洛克 卡米尔 布拉斯 纳兹瑟罗斯 阿拉卡拉达 希 达兹 维尼。瑞克 洛克 帕恩 伊尔 阿什 希 兹 古拉尔 玛拉达斯 洛克 布拉斯 卡恩雷萨德 伊尔 洛克 卡米尔。基尔 阿什雷苏尔 安特 布拉斯 古尔 雷沃斯。\n伊尔 基拉萨斯 沃拉凯姆 泽库尔拉卡斯 阿奇姆 伊尔 阿曼 维尼 卡扎克。\n\n我们需要有人帮助破译这段信息的含义。根据几处环境痕迹来看，最近来访麦迪文地窖的人并不只有我们。如果运气好，他们也许仍在逆风小径的某处。\n\n如今灵魂、食人魔和恶魔都围绕着高塔，他们会躲在哪里？",
  },
  [31034] = {
    ["T"] = "先助人，再求助",
    ["O"] = "逆风小径的陌生人大概是我们找回恶魔夺走的流明石的最佳选择。我们需要带给他能增强法力恢复的食物和一些酒。",
    ["D"] = "我的确能帮你，但你知道这种事通常怎么发展……我得先从你这里得到点东西。\n\n正如你所见，我现在状态并不好。从地窖逃出来时，我不得不把身体逼到远超稳定极限的程度。\n\n帮我恢复魔力，我就会协助你。能长期提升法力恢复的东西，再加上一点可以送服的酒，对我会大有帮助。你离开时，我会开始翻译那块石板。",
  },
  [31035] = {
    ["T"] = "关键信息",
    ["O"] = "与逆风小径的卡兰斯·阿登提斯谈一谈。",
    ["D"] = "我已经感觉好多了，谢谢你，$c。请允许我自我介绍，我是肯瑞托的卡兰斯·阿登提斯。\n\n我们来谈谈这件事。",
  },
  [31037] = {
    ["T"] = "偿还债务",
    ["O"] = "我们在逆风小径遇到的肯瑞托法师邀请我们去他的营地见他。他说他能用强大的附魔帮助我们。这应该是件好事。",
    ["D"] = "向你致意，$N！\n\n很高兴告诉你，我感觉好多了。你的任务顺利吗？\n\n我很快就会离开逆风小径。你有空时来我这里一趟吧。我想我已经有足够的力量，回报你提供的所有帮助。我的附魔十分强大，毫无疑问会在接下来的战斗中帮助你。\n\n卡兰斯敬上。",
  },
  [26593] = {
    ["T"] = "精铁矩阵",
    ["O"] = "在奥达曼内部找到一个精铁矩阵，并把它带回给历史学家丽贝卡·凯勒。",
    ["D"] = "泰坦是一个古老种族，在无数纪元之前曾行走于艾泽拉斯。多年来，他们位于奥达曼的设施被许多人发掘并占据。它的许多秘密已经遭到洗劫，但在深处仍有一些房间，由古老的泰坦防御设施守护着。\n\n到目前为止，你都表现得很能干。也许你足以应付那些防御？如果你有兴趣测试它们，我这里有份工作给你。在奥达曼最深处的房间里，应该有一台名为精铁矩阵的泰坦机器。如果你能取回一个并带给我，你会得到丰厚的报酬。",
  },
  [8950] = {
    ["T"] = "煽动者的附魔",
    ["O"] = "把以下物品带给托尔巴拉德巴拉丁监狱中的法尔林·树影：1份嘲弄鬼灵的精华、4个黑暗符文和8个大块魔光碎片。",
    ["D"] = "正如我刚才所说……不幸的是，我手头没有所需的材料，因为很少有人会要求这种护符。\n\n我需要一个被人类囚禁于此的亡灵精华，一把通灵学院的黑暗符文，以及一些大块魔光碎片。把这些材料带给我，我就会为你完成这件事。",
  },
  [26314] = {
    ["T"] = "造餐仪式",
    ["O"] = "杀死通灵学院中的詹迪斯·巴罗夫，并取回大法师安多玛斯的奥术造餐笔记。",
    ["D"] = "你好，$N。我能请你帮个私人忙吗？\n\n早在第三次战争之前，我曾与詹迪斯·巴罗夫有过一段亲密的私人关系，她是一位颇有才华的咒术师。当天灾军团席卷洛丹伦时，我的一些私人物品留在了詹迪斯手中。考虑到我们分别时的情形，我不想再次面对她的怒火。\n\n但你对奥术技艺的掌握足以与我媲美，我相信你能与她正面对抗。如果你愿意从她那里取回我的奥术造餐笔记，我很乐意与你分享其中内容。我想你会发现造餐仪式相当节省时间！\n\n你和你的同伴可以在西瘟疫之地通灵学院的地下室找到詹迪斯·巴罗夫。",
  },
  [26393] = {
    ["T"] = "冲突号召：西瘟疫之地",
    ["O"] = "在西瘟疫之地找到并杀死5名部落成员。",
    ["D"] = "西瘟疫之地属于联盟，我们必须不断证明这一点。追猎部落成员，并代表军队杀死他们，以证明你的价值并晋升军阶。",
  },
  [26394] = {
    ["T"] = "冲突号召：西瘟疫之地",
    ["O"] = "在西瘟疫之地找到并杀死5名联盟成员。",
    ["D"] = "西瘟疫之地属于部落，我们必须不断证明这一点。追猎联盟成员，并代表军队杀死他们，以证明你的价值并晋升军阶。",
  },
  [26422] = {
    ["T"] = "造餐仪式",
    ["O"] = "杀死通灵学院中的詹迪斯·巴罗夫，并取回贝索尔·冰片的奥术造餐笔记。",
    ["D"] = "你好，$N。我能请你帮个私人忙吗？\n 很久以前，在第三次战争之前，我曾与詹迪斯·巴罗夫有过一段亲密的私人关系，她是一位颇有才华的咒术师。当天灾军团席卷洛丹伦时，我的一些私人物品留在了詹迪斯手中。考虑到我们分别时的情形，我不想再次面对她的怒火。\n 但你对奥术技艺的掌握足以与我媲美，我相信你能与她正面对抗。如果你愿意从她那里取回我的奥术造餐笔记，我很乐意与你分享其中内容。我想你会发现造餐仪式相当节省时间！\n 你和你的同伴可以在西瘟疫之地通灵学院的地下室找到詹迪斯·巴罗夫。",
  },
  [26439] = {
    ["T"] = "审判和救赎",
    ["O"] = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。这样会召出你必须审判的灵魂。击败这些灵魂会召出死亡骑士达克雷尔。击败他，夺回堕落战马失落的灵魂。\n\n把赎罪的战马之魂和被祝福的附魔马铠交给达克雷尔的堕落战马。",
    ["D"] = "拿着这个背包——里面装着你完成任务所需的物品。\n\n在尸骨储藏所地下室的中心使用预言水晶球，召出必须接受审判的被诅咒灵魂。在这场试炼中明智地使用你的审判——它们会比你意识到的更加强大。灵魂之后，死亡骑士会现身；击败他，夺回战马失落的灵魂。只有那时，$N，你才能救赎它，并把你的马铠披在这匹新坐骑身上！",
  },
  [26471] = {
    ["T"] = "未能寻回之人",
    ["O"] = "前往西瘟疫之地的凯尔达隆岛。在要塞二楼的主厅放置包好的圣契，引出狮心公爵并让他安息。\n\n如果你成功了，就回到幽暗城的洛琳·哈尔福德那里。",
    ["D"] = "如果狮心公爵已被复生为亡灵，他会是一个强大的敌人。如果他在被遗忘者之中，那倒还好说，但我只能想象他作为天灾军团奴仆时，被迫做过多少可怕的事。我必须前往凯尔达隆。\n\n<帕特里克抓起自己的圣契，用公爵的斗篷仔细包好，然后递给你。>\n\n拜托，如果你愿意和我一起完成这项任务，就招募盟友前往凯尔达隆。在巴罗夫领主废弃大厅中，把用公爵斗篷包好的我的圣契放下。如果一切按计划进行，他应该会被自己的斗篷和我的圣契吸引而来。我们可以一起终结他。",
  },
  [26953] = {
    ["T"] = "破旧的录取信",
    ["O"] = "把破旧的录取信带到西瘟疫之地达隆米尔湖中央的凯尔达隆岛。",
    ["D"] = "你发现了一个破旧的信封，里面装着一封信。\n\n它似乎是一份邀请函，写在精美羊皮纸上，邀请收信人前往凯尔达隆岛上的某所学术机构。信中提到了魔法和战斗武艺，但没有具体细节。收信人的名字不见了，信的下半部分也缺失了。\n\n也许你应该调查一下这个受教育的机会？",
  },
  [26963] = {
    ["T"] = "开学第一天",
    ["O"] = "与通灵学院教职员工交谈，了解可选课程，并签署相应文件。",
    ["D"] = "首先——这里不是普通学术机构。我们相信实践学习，以及一种松散引导、自主导向、注重实用的方法。某个特别讨厌的食尸鬼，也就是所谓的\"律师\"，通知我说，我需要你签署一些表格，以保护学校和学生免受\"赔偿责任\"和\"太多人到处乱戳\"的影响。哼。\n\n魔法和武艺本来就有危险，尤其是由新手施展时。你可以把这项要求当作认识入门教职员工的机会：阿特伍德博士、汉隆博士、皮克曼大厨和菲利普斯监考官。",
  },
  [26964] = {
    ["T"] = "遵守着装规范",
    ["O"] = "把8份腐臭蛛丝带给凯尔达隆的伊莎贝尔·皮克曼。",
    ["D"] = "你的第一门课程是家政。学校预算紧张，学生需要自行提供制服原料。幸运的是，这项任务很简单。\n\n生活在瘟疫之地的蜘蛛会吐出异常坚韧而腐臭的丝。杀掉它们，直到你有足够的制服原料，然后把蛛丝带给我们的家政老师伊莎贝尔·皮克曼。你可以在安多哈尔废墟北边、瘟疫锅附近，甚至伐木场一带找到这些蜘蛛。去吧！",
  },
  [26966] = {
    ["T"] = "开学第二天",
    ["O"] = "装备通灵学院院服。",
    ["D"] = "你好，$N。很高兴看到你熬过了第一天。百分之十二的准学生没能做到。\n\n既然你已经取得制服，就可以自豪地穿上它。你现在正式接受学院指导了。鬼魂队加油！",
  },
  [26970] = {
    ["T"] = "用腐肉烹饪",
    ["O"] = "从腐肉秃鹫身上收集4枚特别大的蛋，并把它们带给伊莎贝尔·皮克曼。",
    ["D"] = "身为你的家政老师，我的职责是确保你在通灵学院的学术生涯中能照顾好自己。课业负担沉重，并不适合胆小之人。我调制了一种混合物，可以帮助你强壮到足以承受前方的试炼。先给我从安多哈尔废墟北边，或湖泊南岸一带的秃鹫身上带些特别大的蛋来。不要鸟巢里的！那些都被瘟疫污染了。我们需要活鸟身上的。",
  },
  [26976] = {
    ["T"] = "历史通识",
    ["O"] = "抄录巴罗夫陵寝地下室中牌匾上的文字。",
    ["D"] = "该上历史课了。看看你周围，$N。如果这些石头会说话，它们或许能告诉我们许多关于强大的巴罗夫家族的故事，正是他们把这片土地捐给了我们的学院。\n\n我希望趁巴罗夫家族还新鲜地躺在坟墓里时，记录他们的历史。我们尊敬的教职员埋在学校里，但他们的祖先躺在别处。向西越过湖面，就是悔恨岭的墓地。巴罗夫家族的祖传陵寝就在那里。深入其中，把所有安葬于内者的名字带回来。",
  },
  [26977] = {
    ["T"] = "历史通识",
    ["O"] = "与阿莱克斯·巴罗夫的鬼魂交谈。",
    ["D"] = "当你匆忙抄下名单时，身后传来一阵奇怪的声响。\n\n一个之前并不存在的虚幻身影出现了。那鬼魂招手示意你靠近。也许你该和它谈谈？",
  },
  [26978] = {
    ["T"] = "历史通识",
    ["O"] = "带着这条信息回到凯尔达隆的汉隆教授那里。",
    ["D"] = "既然你已经知道了我的故事，请纠正历史记录。也许有一天，黑暗院长加丁对我的控制会解除，我的灵魂也能得到安宁。在那之前，至少还有一个人知道真相，我就心满意足了。愿圣光祝福你，$C。我知道它已经抛弃了我。",
  },
  [26979] = {
    ["T"] = "高年级恶作剧",
    ["O"] = "从通往壁炉谷北方道路旁的血色厕所里弄些粪便。",
    ["D"] = "嘿！新生！到这边来！\n\n学期快结束了，我必须轰轰烈烈地收尾。也就是说，要来一场配得上通灵学院的高年级恶作剧。但我还得学习，才能真正毕业。博学者普克尔特对日期可是一点都不含糊。\n\n这就轮到你了。给我弄来史上最棒高年级恶作剧所需的材料，我会让你觉得值得！首先，我需要某种臭烘烘的东西。血色十字军在达尔松之泪东北方、通往壁炉谷的路上，靠近他们防线的地方有个厕所。给我从那里弄些粪便来！",
  },
  [26985] = {
    ["T"] = "学院注册",
    ["O"] = "与西瘟疫之地凯尔达隆岛上的布莱克伍德院长谈一谈。",
    ["D"] = "你好。我代表一所专精武艺与魔法的精英学院，而且我注意到你似乎很懂法术和武器。我想正式邀请你完成我们的入门课程，看看你是否适合本校。把这封介绍信带给西瘟疫之地凯尔达隆岛上的布莱克伍德院长，开始办理吧。\n\n接受这封信即表示你同意遵守旁听学生政策和保密协议。我们可能会进行背景调查、利益冲突评估，或 附身评估。\n\n期待在通灵学院见到你。鬼魂队加油！",
  },
  [26986] = {
    ["T"] = "学院注册",
    ["O"] = "与西瘟疫之地凯尔达隆岛上的布莱克伍德院长谈一谈。",
    ["D"] = "你好。我代表一所专精武艺与魔法的精英学院，而且我注意到你似乎很懂法术和武器。我想正式邀请你完成我们的入门课程，看看你是否适合本校。把这封介绍信带给西瘟疫之地凯尔达隆的布莱克伍德院长，开始办理吧。\n\n接受这封信即表示你同意遵守旁听学生政策和保密协议。我们可能会进行背景调查、利益冲突评估，或 附身评估。\n\n期待在通灵学院见到你。鬼魂队加油！",
  },
  [27182] = {
    ["T"] = "合同 #1088：超大股骨",
    ["O"] = "从通灵学院的复活构造体身上收集一根超大股骨。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。你喜欢音乐吗？谁不喜欢！？这一份来自音乐部门。\n\n合同 #1088：从通灵学院内部取得一根股骨\n\n数量：一根（超大）",
  },
  [27505] = {
    ["T"] = "高蛋白饮食",
    ["O"] = "从西瘟疫之地的腐肉秃鹫巢中收集12枚腐肉蛋，并把它们带给安戈洛环形山沼泽地的莫维克。",
    ["D"] = "通常来说，年轻的暴掠龙会从父母带回巢穴的尸体上觅食，并很快学会自己狩猎——否则就会饿死。既然我是在训练这些恐龙成为坐骑，它们就能吃到更均衡的早餐。\n\n蛋是很好的蛋白质来源，但我不想从本地取用。安戈洛的恐龙数量太脆弱，不能再额外采集蛋。我听说自从天灾军团席卷之后，西瘟疫之地的秃鹫数量已经失控。传闻那些蛋很大——正适合贪婪的胃口。\n\n你能去西瘟疫之地收集一打蛋吗？你应该能在腐肉秃鹫出没的地方附近找到它们。",
  },
  [27540] = {
    ["T"] = "被偷走的手册",
    ["O"] = "为安戈洛环形山的莫维克从壁炉谷取回《如何训练你的恐龙》。",
    ["D"] = "前段时间，我发现一个人类在我的暴掠龙用品周围鬼鬼祟祟。虽然我把他吓跑了，但后来我发现，他偷走了我关于训练毒皮暴掠龙的心得笔记。经过一些调查，我了解到那个小偷是一个名叫血色十字军的组织成员。 \n\n这些狂热分子在北方瘟疫之地有一座力量堡垒，名叫壁炉谷。住在那里的血色魔法师据说是贪婪的文学研究者——也许那本书就在他们的图书馆某处？\n\n把它取回来给我，好让我继续训练这些暴掠龙幼崽！",
  },
  [27933] = {
    ["T"] = "地下城中的炼金术",
    ["O"] = "从西瘟疫之地的农田中采集30株瘟疫杂草。在瘟疫之地任意天灾瘟疫锅中装满火酒的瓶子。",
    ["D"] = "现在，我们要酿的这酒可不只是为了享受。它对联盟里的盟友有实际用途。你看，我算是个爱国者。\n\n想让我们的朋友远离毒药、疾病，还有乱七八糟的东西……酿酒这门艺术和炼金术也没什么不同。\n\n这话你可别外传。我需要艾泽拉斯最污秽的一些材料，还有哪里比瘟疫之地更适合找它们？没错。最好祈祷我们别酿出什么新瘟疫来！\n\n味道我肯定会处理好！你只需要采集那边田地里长的那些植物。哦，带上这个水晶瓶——我听说这片土地到处散落着装满某种东西的瘟疫锅……噢，里面肯定都是些恶心得不得了的玩意儿，对吧？！\n\n拿到那些植物，再用天灾军团自己的酿液装满瓶子，然后我们就能开始酿我们的酒了。",
  },
  [28485] = {
    ["T"] = "给穆格雷斯·深水的委托",
    ["O"] = "穆格雷斯·深水要你使用急救技能制作20条厚符文布绷带，并把订单带给西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",
    ["D"] = "不要怜悯我，$C。我的生命快要走到尽头……伤口太多，圣光太少。但还有一丝希望，虽然微弱。\n\n如果你能给我带来20条厚符文布绷带，也许我还能撑下去……撑到再看一眼林地上的日出。",
  },
  [28511] = {
    ["T"] = "给伊莎贝尔·皮克曼的委托",
    ["O"] = "伊莎贝尔·皮克曼要你使用钓鱼技能收集20条新鲜的夜鳞鲷鱼，并把订单带给西瘟疫之地凯尔达隆的伊莎贝尔·皮克曼。",
    ["D"] = "学生们变得……焦躁了。他们的胃口和野心一样永无止境——如果我还要再处理一次仪式大厅里的晕厥事件，我可能会献祭其中一个。可他们还远远不够肥。\n\n给我带20条新鲜的夜鳞鲷鱼。它营养丰富，容易料理，还能让他们的头脑足够清醒，这样我就不用一次片开太多学生。",
  },
  [28538] = {
    ["T"] = "给伊莎贝尔·皮克曼的委托",
    ["O"] = "伊莎贝尔·皮克曼要你使用草药学技能收集20朵幽灵菇，并把订单带给西瘟疫之地凯尔达隆的伊莎贝尔·皮克曼。",
    ["D"] = "你听说过幽灵菇吗？我最近把配料范围扩展到了草药，而这种东西听起来非常适合我们通灵学院的学生。\n\n我不知道它长在哪里，但我愿意花钱买一大批来试试看。",
  },
  [28581] = {
    ["T"] = "给克罗米的委托",
    ["O"] = "伦纳德·波特要你使用制皮技能制作1张熟化毛皮，并把订单带给西瘟疫之地安多哈尔的克罗米。",
    ["D"] = "嘿——真正的制皮师！皮革和深石之盐的气味，我到哪儿都认得出来。\n\n说起来……我现在可真是进退两难。你看，我答应了一个叫克罗米的小侏儒，要给她腌制一张熟化毛皮，可我的筛盐器不见了，而且方圆几里内也没有别的制皮师。\n\n也许你能做？你看，另一个问题是，她在那边……安多哈尔废墟里。而我可不是擅长打架的类型。但你看起来是。",
  },
  [26477] = {
    ["T"] = "暗影斗篷",
    ["O"] = "为拉文霍德庄园的卡洛·奥雷留斯收集12块丝绸、4颗暗影石和4份暗影蛛丝。",
    ["D"] = "如我承诺的那样，我很乐意教你一项多年来开发出的宝贵能力。这项能力可以让你移除自身受到的有害效果，比如毒药和诅咒，在你今后的冒险中会非常有用。\n\n不过，在我教你这项能力之前，我需要你帮个忙。我需要一些稀有材料，来制作一件品质纯净的斗篷，以增强我的潜行能力。我相信你有足够的本事和门路弄到这些材料，而我愿意用这项能力的知识来换取你的协助。\n\n我需要的材料是丝绸、暗影石，最后还有暗影蛛丝。等你取得这些材料后，把它们带给我，我就会教你这项宝贵能力。我向你保证，这绝对值得你花费时间和精力。",
  },
  [26507] = {
    ["T"] = "高地的可疑活动",
    ["O"] = "找到高地和达伦德农场附近山丘上的情报投递点。",
    ["D"] = "我一直怀疑辛迪加，于是派了一名特工去侦察他们在高地的营地。他一直没有回报，我怀疑他永远也不会回来了。\n\n我曾指示他在高地山麓一处小标记旁，以及达伦德农场附近留下情报投递点。你能找到那些标记，并取回可能已经收集到的情报吗？如果你沿着斯坦恩布莱德以北、破碎岭城堡以东、屠杀谷以北的山麓前进，应该会发现那些标记。尽快带着你的发现回来复命。我还得为那名特工的家人做些……安排。",
  },
  [26508] = {
    ["T"] = "高地的可疑活动",
    ["O"] = "聆听拉文霍德公爵的故事。",
    ["D"] = "在继续之前，我觉得必须告诉你，我怀疑我们在辛迪加中面对的是谁、是什么。这是一个关于背叛与阴谋的漫长故事。请坐舒服些。",
  },
  [26510] = {
    ["T"] = "奥里登·匹瑞诺德领主",
    ["O"] = "在达伦德农场找到奥里登·匹瑞诺德领主并杀死他。",
    ["D"] = "<拉文霍德公爵摇了摇头。>\n\n曾经强大的匹瑞诺德家族竟然堕落至此。沦为普通的盗贼和刺客！\n\n当然，盗窃和刺杀本身并没有什么不对。关键是必须出于正确的理由。这里面有艺术，也有手艺。不过我扯远了。\n\n辛迪加必须被摧毁。既然我无意宣称奥特兰克的王位，为了政治局势着想，最好不要让拉文霍德家族直接卷入他的死亡。因此我请求你——找到奥里登·匹瑞诺德，杀了他。",
  },
  [26511] = {
    ["T"] = "匹瑞诺德的遗产",
    ["O"] = "把奥里登·匹瑞诺德的死讯，以及伊莱莎请求寻找哈斯将军的事，报告给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "感谢你把我从匹瑞诺德领主的宅邸中解救出来。别担心我，我能自己回家。\n\n不过你能帮我一个忙吗？奥里登总是告诉我，如果他出了什么事，我应该想办法让一个名叫哈斯将军的人知道。我完全不知道该去哪里找这位“哈斯将军”，但我想让自己的良心安宁，完成这个小小的遗愿。你能查出他是谁，并告诉他奥里登已经死了吗？",
  },
  [26516] = {
    ["T"] = "黑暗议会",
    ["O"] = "把阿古斯法术书带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "我相信这个阿古斯复苏是一个秘密组织，可能与比我先前怀疑的更加危险的黑暗力量结盟。把这本法术书带给乔拉齐·拉文霍德公爵。你可以在敦霍尔德城堡北边山麓的庄园里找到他。\n\n也许他听说过这个组织。",
  },
  [26518] = {
    ["T"] = "附有魔法的羊皮纸",
    ["O"] = "把附有魔法的羊皮纸带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "这张羊皮纸被某种法术附魔，无法辨读。但纸张顶端有一个词还能看清：阿古斯。拉文霍德公爵会对此感兴趣。",
  },
  [26520] = {
    ["T"] = "血石装置",
    ["O"] = "从奥特兰克山脉达拉然附近洛丹米尔收容所中被关押的被遗忘者囚犯身上收集4件血石装置。",
    ["D"] = "这个阿古斯复苏组织对血魔法很感兴趣，尤其是那种可以借助血石施展的血魔法。看起来，辛迪加贿赂了一些被遗忘者，让他们从幽暗城的宝库中偷走血石装置，然后前往达拉然寻求庇护。本月晚些时候，囚犯转移时应该会进行一次血石交易。\n\n我怀疑达拉然卫兵也被收买了。\n\n那就以其人之道还治其人之身！我们会用金币打点他们，让他们睁一只眼闭一只眼，好让你解决那些被遗忘者窃贼，取回血石装置。",
  },
  [26524] = {
    ["T"] = "前往拉文霍德庄园",
    ["O"] = "把附有魔法的羊皮纸带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "呃！这是什么？奥术魔法！我对这东西毫无办法。\n\n如果纳伽兹拥有这张羊皮纸，我们就必须弄懂它写了什么。离这里不远就是拉文霍德庄园。虽然拉文霍德公爵并不算我们的盟友，但他以公正闻名——对一个人类来说。看看他能不能破解这张羊皮纸上的密码。\n\n拉文霍德庄园就在敦霍尔德城堡后方的山麓中。",
  },
  [26525] = {
    ["T"] = "费莉希蒂的解读",
    ["O"] = "等待费莉希蒂·佩瑞诺德解读附有魔法的羊皮纸。",
    ["D"] = "请允许我介绍费莉希蒂·佩瑞诺德，前国王艾登·匹瑞诺德的侄女，伊西登·佩瑞诺德的妹妹。她的家族曾经统治奥特兰克山脉，而她也真心希望保护这片土地，不让任何试图腐化和篡夺它的人得逞。\n\n她也是一位极有天赋的法师。给她一点时间研究这张羊皮纸，你就会得到答案。",
  },
  [26526] = {
    ["T"] = "血石装置",
    ["O"] = "从斯坦恩布莱德和高地的辛迪加成员身上收集4条血石项链。",
    ["D"] = "我们最近得知了阿古斯复苏的存在，这是燃烧军团的一个分支组织。他们听命于暗影议会，就像灼热之刃、火刃、灼热项圈，诸如此类。至少他们想出了个更有创意的名字。\n\n血魔法会使用血石作为媒介，而这张羊皮纸显示，他们一直在把血石项链分发给奥特兰克山脉的辛迪加成员。回到高地去，杀掉辛迪加，直到你拿到四条那样的项链。我会在你离开时为它们准备一个仪式。",
  },
  [26527] = {
    ["T"] = "血石装置",
    ["O"] = "保护费莉希蒂·佩瑞诺德在拉文霍德庄园进行血石占卜仪式。",
    ["D"] = "血石是一种污秽的矿物，主要被燃烧军团的术士和暗影法师使用。它会留下魔法灵光，只要你拥有足够强大的血石，就能借此进行占卜。\n\n既然我们可以假定阿古斯复苏正在使用血石，而血石又相对稀有，我们就有希望占卜出血石力量最强的地方。\n\n我可以进行这个仪式，但它需要我全神贯注。占卜期间，被暗影魔法吸引来的污秽生物可能会从虚空中出现。保护我，否则仪式就会失败！",
  },
  [26533] = {
    ["T"] = "阿古斯复苏的终结",
    ["O"] = "杀死斯罗金，然后找到费莉希蒂·佩瑞诺德逃离！",
    ["D"] = "我们在上面！我们已经准备好终结那个大坏蛋了！现在拿出真本事——我已经占卜了附近区域，斯罗金离这里不远，就藏在一些旧废墟里。\n\n只有一个小小的问题。完成任务后，我们需要迅速撤离，而要把我们两个人传送回拉文霍德庄园，会消耗我大量的魔法能量。所以我需要你单独解决他。完成后就来找我——我会在营地另一边不远处等你。",
  },
  [26534] = {
    ["T"] = "阿古斯复苏的终结",
    ["O"] = "向奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵报告任务成功。",
    ["D"] = "如果你准备好了，我们现在就走。抵达后我会非常虚弱，所以你可以向拉文霍德公爵报告任务成功。后会有期。抓稳你的屁股！",
  },
  [26537] = {
    ["T"] = "摩迪斯钥匙",
    ["O"] = "找到摩迪斯钥匙的用途。",
    ["D"] = "这把钥匙是在瓦利玛尔·摩迪斯男爵的尸体上找到的。它会是开什么的？\n\n你记得那位男爵在奥特兰克废墟东北方有一座庄园。也许你该去那里看看？",
  },
  [26509] = {
    ["T"] = "高地的可疑活动",
    ["O"] = "杀死高地的辛迪加成员，寻找奥里登·匹瑞诺德领主仍然活着的证据。",
    ["D"] = "我们必须确认奥里登·匹瑞诺德是否真的是辛迪加背后的主使。\n\n你已经证明了自己的能力——前往高地，杀死辛迪加成员。寻找任何能证明他们首领身份的证据。也许是信上的蜡封、带有王室纹章的玺戒，或是文件上的签名。\n\n无论你找到什么，都尽快带回这里。",
  },
  [26517] = {
    ["T"] = "黑暗议会",
    ["O"] = "杀死纳伽兹，并搜查他身上任何与阿古斯复苏有关的情报。",
    ["D"] = "根据我对辛迪加的调查，我有理由相信，你在阿古斯复苏信件中提到的那个纳伽兹，就在奥里登·匹瑞诺德领主所在的同一处地方。\n\n袭击达伦德农场，杀死纳伽兹。搜查纳伽兹的尸体和房间，寻找任何关于阿古斯复苏听命于谁的文件。祝你好运，$C。",
  },
  [26538] = {
    ["T"] = "摩迪斯男爵领",
    ["O"] = "找到瓦利玛尔·摩迪斯男爵，确认他是否已成亡灵。如果是，就杀了他。",
    ["D"] = "奥特兰克的一个贵族家族曾由瓦利玛尔·摩迪斯男爵领导。摩迪斯家族在奥特兰克城东北方有一座庄园，在这片土地上颇受尊敬。\n\n据说摩迪斯男爵在天灾军团穿过奥特兰克王国前往达拉然时被杀，但近年来，有人看到这位昔日的男爵在家族领地上巡逻。传闻他已经成了天灾军团的傀儡。\n\n搜索他最后一次被报告出现的地点，看看传闻是否属实，$N。如果他已经堕入天灾军团，你就必须摧毁他。",
  },
  [26539] = {
    ["T"] = "摩迪斯男爵领",
    ["O"] = "找到瓦利玛尔·摩迪斯男爵，确认他是否是天灾军团成员。如果是，就杀了他。",
    ["D"] = "奥特兰克的一个贵族家族曾由瓦利玛尔·摩迪斯男爵领导。摩迪斯家族在奥特兰克城东北方有一座庄园，而且一直与我的主人赫尔库拉竞争。\n\n据说摩迪斯男爵在天灾军团穿过奥特兰克王国前往达拉然时被杀，但近年来，有人看到这位昔日的男爵出现在家族领地附近。传闻他已经成了天灾军团的傀儡。\n\n搜索他最后一次被报告出现的地点，看看传闻是否属实，$N。如果他已经堕入天灾军团，你就必须摧毁他。",
  },
  [26731] = {
    ["T"] = "实地考察",
    ["O"] = "在夜间找到交接会面的地点，并找个地方观察会面。",
    ["D"] = "在取得并净化护命匣之前，巫妖从未真正被击败。寒骨的护命匣不在他身上，而这封信显示它已经被带到了别处。\n\n看——日记最后一条写着，即将与皇家药剂师协会的一名成员会面，地点就在洛丹伦废墟本身阴影中一处偏僻区域！信上的路线显示，你要穿过奥特兰克山脉，经过达伦德农场，再沿着洛丹米尔湖东岸前进。\n\n这场会面当然应该被打断——而且它应该会在夜间发生。我会留在这里，破解日记其余内容所用的密码。",
  },
  [27184] = {
    ["T"] = "奥特兰克山谷的补给",
    ["O"] = "赢得一场奥特兰克山谷战斗，以取得奥特兰克补给箱。",
    ["D"] = "烟林牧场在艾泽拉斯各地都有生意，包括一些最危险的地方。我们甚至和部分战场阵营达成协议，只要我们为他们的战事贡献战斗人员，就能获得补给箱。\n\n我需要奥特兰克山脉的补给。从奥特兰克山谷凯旋而归，你就能取得一个奥特兰克补给箱，里面装着我们的冬幕欢乐制造器会用到的纯净雪和冬刺草。你愿意参战吗？",
  },
  [27929] = {
    ["T"] = "荣耀与鲜血的记忆",
    ["O"] = "前往敦霍尔德城堡并找到绞刑架。使用挑战号角召唤埃德拉斯·布莱克摩尔的鬼魂，并杀死他。",
    ["D"] = "部落被联盟击败后，我在荒野中流浪，直到被俘。我只被人类关押了很短一段时间，但萨尔和许多其他人却在敦霍尔德城堡中被囚禁了多年。\n\n埃德拉斯·布莱克摩尔管理的营地对兽人的待遇十分残酷。它体现了人性中最丑恶的一面，也体现了他们对自身堕落的盲目。即便临死之时，萨尔的囚禁者也看不见自己的罪行。\n\n布莱克摩尔很久以前就被杀死，尸体埋在城堡废墟之中。后来，一座新营地建在了上面。拿着这支挑战号角，在重建的绞刑架附近吹响它。布莱克摩尔的鬼魂会出现，而你可以一同执行正义。",
  },
  [28010] = {
    ["T"] = "奥术仪式",
    ["O"] = "在敦霍尔德城堡后方奥特兰克山脉的山麓中找到拉文霍德庄园，抵达后与费莉希蒂谈谈。",
    ["D"] = "我用虚假的借口把你叫到这里，$N。需要帮助的不是我，而是拉文霍德庄园。虽然拉文霍德公爵是个人类，但他已经证明自己是部落的朋友。\n\n据说拉文霍德公爵豢养的法师在庄园里遇到了一些她无法处理的问题，于是他们请求一名附魔师帮忙。我掌握着太多被遗忘者的秘密，不能冒险亲自前往。如果这是陷阱，后果可能会很灾难。但你！你只是个步兵，一个价值平平的$C。不会有太多人想念你的。\n\n所以去代表部落吧，$N。不要相信你在那座庄园里遇到的任何人。那里充满秘密、间谍，还有香菜。香菜尝起来像肥皂。恶心！",
  },
  [28012] = {
    ["T"] = "奥术仪式",
    ["O"] = "奥特兰克山脉拉文霍德庄园的费莉希蒂要你使用附魔技能，为她带来4块大块魔光碎片、6份强效不灭精华和20份幻影之尘。",
    ["D"] = "共鸣灰烬会像海绵一样吸收反占卜雕文的力量，但我们还必须收集其他材料，才能制作……姑且称之为雕文肥皂吧。具体来说，我们需要一些附魔材料，让灰烬与雕文所用的魔法类型协调起来。\n\n既然你是大师级附魔师，我相信你要取得这些材料不会太难：一些大块魔光碎片、强效不灭精华，还有一大堆幻影之尘。",
  },
  [28015] = {
    ["T"] = "奥术仪式",
    ["O"] = "奥特兰克山脉拉文霍德庄园的费莉希蒂要你使用附魔技能，为暮光信徒手套附上附魔手套：初级急速，然后与她交谈。",
    ["D"] = "最后一件事！我保证！\n\n我觉得你应该给这些手套附上一点急速。要移除雕文，你的手指必须足够快。虽然我相信你能完成这项任务，但给自己多一点优势总没有坏处。",
  },
  [28016] = {
    ["T"] = "奥术仪式",
    ["O"] = "进入拉文霍德庄园地下室，戴着附魔过的暮光信徒手套移除反占卜雕文。",
    ["D"] = "我们已经准备好了。时机到了。戴上那些附魔过的暮光信徒手套，从我右边的楼梯下去。你会在地板中央看到那个雕文。现在你应该能毫无问题地移除它了！\n\n去吧！我相信你不会把庄园烧掉！",
  },
  [28017] = {
    ["T"] = "奥术仪式",
    ["O"] = "返回奥特兰克山脉拉文霍德庄园的费莉希蒂那里，报告你的成功。",
    ["D"] = "雕文消失后，拉文霍德庄园就不再有成为奥术事故现场的危险了。\n\n费莉希蒂会为你的成功欣喜若狂。",
  },
  [28019] = {
    ["T"] = "奥术仪式",
    ["O"] = "在敦霍尔德城堡后方奥特兰克山脉的山麓中找到拉文霍德庄园，抵达后与费莉希蒂谈谈。",
    ["D"] = "我把你叫到这里，是为了交给你一项重要任务，$N。需要帮助的不是我，而是拉文霍德庄园。虽然拉文霍德公爵并不完全属于联盟，但他仍然是朋友。\n\n拉文霍德公爵的监护对象是一位才华横溢的法师，但她遇到了一个需要附魔师技艺才能解决的问题。我已经在为塞欧克瑞图斯工作，所以想到了你！希望你有时间抽身？\n\n请代表联盟前往拉文霍德，$N。不过，当心你在那里发现的东西。那里充满秘密、间谍，还有香菜。香菜尝起来像肥皂。恶心！",
  },
  [28529] = {
    ["T"] = "给大法师安斯雷姆·鲁因维沃尔的委托",
    ["O"] = "大法师安斯雷姆·鲁因维沃尔要你使用草药学技能收集20株冬刺草，并把订单带给奥特兰克山脉达拉然的大法师安斯雷姆·鲁因维沃尔。",
    ["D"] = "如果你要探索达拉然废墟，可要小心，$C。\n\n我无法保证这些建筑的安全……哦！你是草药师。\n\n我正在进行一些重建城市的工作，需要冬刺草。如果你想帮助联盟，请给我带一些来。",
  },
  [28554] = {
    ["T"] = "给布罗金的委托",
    ["O"] = "布罗金要你使用草药学技能收集20株冬刺草，并把订单带给奥特兰克山脉奥特兰克废墟的布罗金。",
    ["D"] = "嘿，$N。你有空吗？\n\n没有冬刺草，我就做不出我那著名的冰霜之油，可本地食人魔最近有点过于活跃。我需要一个有冒险精神的人给我带来20株冬刺草。那个冒险者是你吗？",
  },
  [28577] = {
    ["T"] = "给乔拉齐·拉文霍德公爵的委托",
    ["O"] = "乔拉齐·拉文霍德公爵要你使用制皮技能制作1件冰霜皮质披风，并把订单带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "我很擅长评估别人，$C，而我的猜测是……你的制皮手艺相当不差。\n\n费莉希蒂的生日快到了，虽然她绝不会期待这件事，但我想送她点东西。我希望这份礼物既实用又优雅，还要稍微有些出人意料。\n\n一件冰霜皮质披风正合适。你有兴趣接这份工作吗？",
  },
  [28602] = {
    ["T"] = "给乔拉齐·拉文霍德公爵的委托",
    ["O"] = "乔拉齐·拉文霍德公爵要你使用制皮技能制作1件冰霜皮质披风，并把订单带给奥特兰克山脉拉文霍德庄园的乔拉齐·拉文霍德公爵。",
    ["D"] = "我很擅长评估别人，$C，而我的猜测是……你的制皮手艺相当不差。\n\n费莉希蒂的生日快到了，虽然她绝不会期待这件事，但我想送她点东西。我希望这份礼物既实用又优雅，还要稍微有些出人意料。\n\n一件冰霜皮质披风正合适。你有兴趣接这份工作吗？",
  },
  [8926] = {
    ["T"] = "公平的补偿",
    ["O"] = "把野性之心腰带带给铁炉堡的德莉亚娜。",
    ["D"] = "你信守承诺，带来了穆克斯制造的装置。我相信，如果要让你继续有兴趣救我一命，一份奖励是应该的。把你想升级的腰带和一副手套带给我。我们先从腰带开始。我保证我给你的东西会远远更好。",
  },
  [8931] = {
    ["T"] = "公平的补偿",
    ["O"] = "把野兽追猎者腰带和一副野兽追猎者手套带给铁炉堡的德莉亚娜。",
    ["D"] = "你信守承诺，带来了穆克斯制造的装置。我相信，如果要让你继续有兴趣救我一命，一份奖励是应该的。把你想升级的普通腰带和一副手套带给我。",
  },
  [8932] = {
    ["T"] = "公平的补偿",
    ["O"] = "把博学者腰带和一副博学者手套带给铁炉堡的德莉亚娜。\n",
    ["D"] = "你信守承诺，带来了穆克斯制造的装置。我相信，如果要让你继续有兴趣救我一命，一份奖励是应该的。把你想升级的普通腰带和一副手套带给我。",
  },
  [8933] = {
    ["T"] = "公平的补偿",
    ["O"] = "把光铸腰带带给铁炉堡的德莉亚娜。",
    ["D"] = "你信守承诺，带来了穆克斯制造的装置。我相信，如果要让你继续有兴趣救我一命，一份奖励是应该的。把你想升级的腰带和一副手套带给我。我们先从腰带开始。我保证我给你的东西会远远更好。",
  },
  [8934] = {
