    ["T"] = "死灵法师与后裔",
    ["O"] = "进入托尔巴拉德岛上的巴拉丁监狱，杀死空洞者阿斯提洛斯和纳兹拉萨什。",
    ["D"] = "你好，$C。如果你是来找秘密差事的，我可以向你保证，你来对地方了。\n\n我听说巴拉丁监狱那座岛上监狱发生了一次小规模越狱。那里关着几个囚犯，我真的不希望他们逃出来。两人都是强大的施法者，足以对幽暗城造成毁灭性破坏。尤其是，我们可不想再有更多死灵法师到处乱跑。\n\n如果你不介意去阿拉希高地的法迪尔海湾跑一趟，再搭航班前往托尔巴拉德，我会让你觉得这趟值得——只要你确保阿斯提洛斯和纳兹拉萨什永远离不开那座岛。",
  },
  [26339] = {
    ["T"] = "巴拉丁监狱可能陷落",
    ["O"] = "调查托尔巴拉德岛上巴拉丁监狱的状况，确认海盗袭击的传闻是否属实。",
    ["D"] = "托尔巴拉德岛上坐落着巴拉丁监狱——但巴拉丁可不是普通监狱。世界上一些最糟糕的生物都被关押在那里。甚至还有一个连科赞都关不住的家伙！\n\n所以，是的，我们必须弄清海盗是否已经占领了监狱——但如果他们真的占了，我们也必须有所行动。等你落地之后，我会让你自行判断最佳做法。\n\n说到这个，如果你不知道怎么去，就得去一趟阿拉希高地的法迪尔海湾。那里的飞行管理员会很乐意帮你安排。",
  },
  [26341] = {
    ["T"] = "巴拉丁监狱可能陷落",
    ["O"] = "调查托尔巴拉德岛上巴拉丁监狱的状况，确认海盗袭击的传闻是否属实。",
    ["D"] = "部落的英雄，你的酋长们需要你的帮助！\n\n托尔巴拉德岛上坐落着巴拉丁监狱——世界上一些最糟糕的怪物就被关在那里。甚至还有一个连科赞都关不住的家伙！\n\n有传闻说海盗已经占领了监狱。我们需要调查。等你落地之后，我会让你自行判断最佳做法。\n\n说到这个，如果你不知道怎么去，就得去一趟阿拉希高地的法迪尔海湾。那里的飞行管理员会很乐意帮你安排。",
  },
  [26373] = {
    ["T"] = "战斗号召：阿拉希高地",
    ["O"] = "在阿拉希高地找到并杀死5名部落成员。",
    ["D"] = "阿拉希高地属于联盟，我们必须不断证明这一点。追猎部落成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26374] = {
    ["T"] = "战斗号召：阿拉希高地",
    ["O"] = "在阿拉希高地找到并杀死5名联盟成员。",
    ["D"] = "阿拉希高地属于部落，我们必须不断证明这一点。追猎联盟成员，并代表军队杀死他们，以证明你的价值，在军中晋升。",
  },
  [26535] = {
    ["T"] = "致激流堡的信",
    ["O"] = "向落锤镇的杜拉姆法尔警告激流堡中出现的辛迪加特工。",
    ["D"] = "这封来自斯罗金的信写给玛雷兹·考尔，收信地址是阿拉希高地的激流堡。阿古斯复苏也许也在与阿拉希高地的辛迪加合作。落锤镇有人可能会对这份情报感兴趣。",
  },
  [26536] = {
    ["T"] = "致激流堡的信",
    ["O"] = "向避难谷地的尼艾丝队长警告激流堡中出现的辛迪加特工。",
    ["D"] = "这封来自斯罗金的信写给玛雷兹·考尔，收信地址是阿拉希高地的激流堡。阿古斯复苏也许也在与阿拉希高地的辛迪加合作。避难谷地有人可能会对这份情报感兴趣。",
  },
  [26546] = {
    ["T"] = "前往丘陵",
    ["O"] = "侦察炽燃丘陵，查明烟雾的来源。",
    ["D"] = "俺看见落锤镇东边的炽燃丘陵冒出了很浓的烟。俺很担心，因为住在那地方的元素通常都很平静。\n\n俺要你去那边看看，到底是什么惹出了这么大动静。危险就在前头，所以一定要保持警惕，脑子放清醒点。",
  },
  [26547] = {
    ["T"] = "前往丘陵",
    ["O"] = "侦察炽燃丘陵，查明烟雾的来源。",
    ["D"] = "我看见落锤镇东边的炽燃丘陵冒出了很浓的烟，$glad:lass;。这让我非常担心，因为住在那片区域的元素通常都很平静。我派你去那边调查是什么造成了这么大动静。前方有危险，所以一定要保持头脑清醒，时刻警惕。",
  },
  [26568] = {
    ["T"] = "暗影莓派",
    ["O"] = "从落锤镇东南方的炽燃丘陵收集8筐巨型暗影莓。",
    ["D"] = "炽燃丘陵上有一种特别的浆果，我们称它为暗影莓——一种美味的深紫色水果。\n\n我知道因为它很稀有，在黑市上能卖个好价钱，但我们还有部队要喂，没时间想着赚钱。如果你能给我弄些来，我就能给士兵们做上热乎乎的派。",
  },
  [26569] = {
    ["T"] = "不同寻常的口粮",
    ["O"] = "从炽燃丘陵中的炽燃爬行者身上收集10块爬行者肉块。",
    ["D"] = "在阿拉希很难找到好肉，味道不错的就更少了。我一直偷偷往我们的“肉”饺子里加一种秘密配料……爬行者肉。\n\n是，是，我看见你的表情了。等你在落锤镇驻扎六个月后再来评判我吧。\n\n我的库存快见底了，如果没有足够的伙食，我们手上就要爆发哗变。我需要的肉在这里东南方炽燃丘陵中的炽燃爬行者身上。给我带些来，我会给你丰厚报酬。",
  },
  [26570] = {
    ["T"] = "浸水的日记",
    ["O"] = "在阿拉希高地炽燃丘陵的海岸上找到浸水日记的主人。",
    ["D"] = "你手中这本厚厚的日记贴着“宝拉·艾尔斯通所有”的标签。有人显然对里面写下的内容非常自豪。也许你可以读一读最近几篇记录，找出主人在哪里，并把日记还给她？",
  },
  [26571] = {
    ["T"] = "南部丘陵",
    ["O"] = "前往南部炽燃丘陵，调查土元素的命运。",
    ["D"] = "这片土地的南部属于大地及其首领吉奥玛尔。他没有来到议会，让我十分担忧。我希望你前往他的领地，把你发现的情况转告给我。\n\n很久以前，枯木巨魔崇拜元素，把我们视为神明。他们古老的祭坛至今仍散布在这片土地上。在南部丘陵中，你会找到这样一座祭坛，我可以通过它与你沟通。任务完成后，用它向我发出信号。",
  },
  [26572] = {
    ["T"] = "狂怒剥皮",
    ["O"] = "在炽燃丘陵中杀死8名枯木剥皮者，然后回到沉没的萨满祭坛与阿特拉希斯交谈。",
    ["D"] = "枯木部族的剥皮者是其中最残忍的一群。关于他们活剥敌人的传闻已经传遍整个阿拉希，甚至传到了元素议会这里。我不知道他们在这里做什么，也不知道他们为什么选择终结我们和平共处的关系，但他们的恐怖统治必须结束。用火焰无拘无束的愤怒杀光他们！",
  },
  [26573] = {
    ["T"] = "炽燃丘陵狂战士",
    ["O"] = "在炽燃丘陵中杀死8名枯木狂战士，然后回到沉没的萨满祭坛与阿特拉希斯交谈。",
    ["D"] = "狂战士是高大而可怕的巨魔，也是枯木部族战斗的主力。面对他们时你必须小心，但我坚持认为，为了元素的安全，必须把他们从这些丘陵中清除出去。",
  },
  [26574] = {
    ["T"] = "我同胞的束缚",
    ["O"] = "在炽燃丘陵中杀死枯木控火者，收集腐化束缚，然后回到沉没的萨满祭坛与阿特拉希斯交谈。",
    ["D"] = "我透过你感受到了同胞的痛苦。枯木的萨满变了……他们不再请求，而是掠夺。杀光他们，把他们持有的束缚带回这里，让我检查。",
  },
  [26575] = {
    ["T"] = "黑暗萨满",
    ["O"] = "把奴役报告带到沉没的萨满祭坛，与远方的阿特拉希斯交谈。",
    ["D"] = "你在一具枯木巨魔的尸体上发现了一封皱巴巴的讯息，看起来是在他们的首领之间传递的。阅读里面的内容，也许能揭示炽燃丘陵正在发生什么。阿特拉希斯会对此感兴趣。",
  },
  [27606] = {
    ["T"] = "给基恩洛的委托",
    ["O"] = "德罗夫纳·烈酒要你使用炼金术技能制作5瓶强效治疗药水，并把订单带给阿拉希高地格沙克农场的基恩洛。",
    ["D"] = "不久前，两名联盟斥候前往格沙克农场观察那里的部落活动。他们一直没有回来，我担心他们可能遇上了麻烦。\n\n我的库存里没有多余的强效治疗药水，但我看得出你很熟悉炼金实验室。如果你能制作一些并送给基恩洛，我就能安心了。",
  },
  [27631] = {
    ["T"] = "给杜拉姆法尔的委托",
    ["O"] = "托尔甘要你使用炼金术技能制作5瓶强效治疗药水，并把订单带给阿拉希高地落锤镇的杜拉姆法尔。",
    ["D"] = "这个营地里的兽人被曾在这里降临到他们兄弟姐妹身上的可怕记忆压垮了。我可以用元素的力量振作其中一些人的精神，但另一些人会受益于一些老派的炼金术。\n\n拿杜拉姆法尔来说。他把自己在人类手中遭受的伤痛藏了起来。为他制作一些强效治疗药水，你会看到一种新的领导气魄显现出来。",
  },
  [27656] = {
    ["T"] = "给管理员奥拉瑞克的委托",
    ["O"] = "斯奎尔图要你使用锻造技能制作1枚敏捷黄水晶护符，并把订单带给阿拉希高地激流堡墓穴中的管理员奥拉瑞克。",
    ["D"] = "你也许注意到我们有熔炉，却没有铁匠使用它。如果你愿意改变这一点，管理员奥拉瑞克送来了一份新敏捷黄水晶护符的委托。制作完成后，你可以把它送到激流堡墓穴里的奥拉瑞克那里。小心附近潜伏的部落！",
  },
  [27681] = {
    ["T"] = "给斯迪加特船长的委托",
    ["O"] = "戈尔穆尔要你使用锻造技能制作1枚敏捷黄水晶护符，并把订单带给阿拉希高地南部法迪尔海湾的斯迪加特船长。",
    ["D"] = "我本行是铁匠，但这些日子我实在没什么心情打铁。\n\n斯迪加特船长给落锤镇送来一张便条，问有没有人能做一枚敏捷黄水晶护符，作为送给妻子的礼物——算是为自己离开太久而道歉吧。我不想无视他的请求，所以如果你能替我完成，你会在法迪尔海湾找到他停泊的船。",
  },
  [28072] = {
    ["T"] = "给斯迪加特船长的委托",
    ["O"] = "斯迪加特船长要你使用烹饪技能制作10份美味煎蛋卷，并把订单带给阿拉希高地法迪尔海湾的斯迪加特船长。",
    ["D"] = "我们驶进这个小海湾，只是想短暂上岸休整，$N，但现在我的船员在确认黑石的舰队没有在这片海域游弋之前，都不想再出海。与此同时，补给有点吃紧，我需要你的帮助。\n\n我听说高地上到处都是迅猛龙，而迅猛龙会下蛋。现在，我们是水手，不是猎人，所以我需要你去弄到那些蛋，再给我们做好。但如果你能给我的船员送来一大批美味煎蛋卷，我们就欠你一个人情。",
  },
  [28419] = {
    ["T"] = "给戈尔穆尔的委托",
    ["O"] = "托尔甘要你使用附魔技能，为提供的1面萨满之盾附上附魔盾牌 - 精神，并把订单带给阿拉希高地落锤镇的戈尔穆尔。",
    ["D"] = "你好，附魔师。戈尔穆尔最近十分低落，所以我想振作他的精神。那就字面意义上来吧。每个优秀的战士都会带盾牌，所以我希望你把我拿到的这面萨满之盾附上精神，好振作他的精神。这就是它的作用，对吧？",
  },
  [28555] = {
    ["T"] = "给托尔甘的委托",
    ["O"] = "托尔甘要你使用草药学技能收集20株金棘草，并把订单带给阿拉希高地落锤镇的托尔甘。",
    ["D"] = "要振作占据这座旧监狱之人的精神，还有许多事要做。我的萨满仪式需要许多东西——有时是鲜血和牙齿，有时是适合燃作熏香的草药。\n\n下一场仪式我需要20株金棘草。有了它，我就能引起栖居在这一带的躁动大地与火焰之灵的注意。",
  },
  [28603] = {
    ["T"] = "给哨兵洛洛的委托",
    ["O"] = "吞克要你使用制皮技能制作2条暗色皮带，并把订单带给阿拉希高地法迪尔海湾的哨兵洛洛。",
    ["D"] = "我有一大堆制皮材料，可自己一点手艺也没有。这就麻烦了，因为几次倒霉的掷骰之后，我欠法迪尔海湾下面的洛洛几条新腰带。\n\n别问我为什么……他就是想让我用这种方式还债。\n\n总之，没有这些东西，我没脸再去那边露面，所以你能帮帮我吗？",
  },
  [28614] = {
    ["T"] = "给斯奎尔图的委托",
    ["O"] = "斯奎尔图要你使用剥皮技能收集5张迅猛龙的外皮，并把订单带给阿拉希高地避难谷地的斯奎尔图。",
    ["D"] = "高地上到处都是迅猛龙。它们有爪、有鳞，还很凶猛。我们经常和它们交战……那不如也利用一下它们。\n\n给我带来5张迅猛龙的外皮。那东西结实，很适合做装备。没道理让那些皮革全烂在草地里。",
  },
  [28631] = {
    ["T"] = "给吞克的委托",
    ["O"] = "吞克要你使用剥皮技能收集5张迅猛龙的外皮，并把订单带给阿拉希高地落锤镇的吞克。",
    ["D"] = "高地上到处都是迅猛龙。它们有爪、有鳞，还很凶猛。我们经常和它们交战……那不如也利用一下它们。\n\n给我带来5张迅猛龙的外皮。那东西结实，很适合做装备。没道理让那些皮革全烂在草地里。",
  },
  [28669] = {
    ["T"] = "给戈尔穆尔的委托",
    ["O"] = "戈尔穆尔要你使用采矿技能收集10块钢锭，并把订单带给阿拉希高地落锤镇的戈尔穆尔。",
    ["D"] = "看看那双臂！你要么是矿工，要么就是铁匠最可怕的噩梦。不管是哪种，我都需要你的力量。\n\n我看见了那场陷落，$C。我已经失去了对这个世界的希望。钢锭的秘密仍然对我紧锁。但你，以你高超的技艺，如果能给我带些样品来，也许就能帮上我。",
  },
  [8948] = {
    ["T"] = "安希恩的老朋友",
    ["O"] = "把未完成的挑衅之旗带给托尔巴拉德监狱里的法尔林·树影。",
    ["D"] = "塞尔德林可不是会主动参加公平战斗的人。我已经把这面旗帜做成了他家族的纹色。\n\n再加上一些额外的法术，这面旗帜就会以一种他无法抗拒的方式激怒他。\n\n我一位名叫法尔林的老相识知道所需的确切步骤。他有一种特别的……惹怒别人的办法。我最后听说他被关在托尔巴拉德，希望这不成问题。",
  },
  [8949] = {
    ["T"] = "煽动者的附魔 <NYI>",
    ["O"] = "保护法尔林·树影，抵挡托尔巴拉德的海盗伏击，然后再与他交谈。",
    ["D"] = "没错，我确实熟悉你需要的附魔，$c。遗憾的是，我需要一些手头没有的材料，毕竟我现在被关在牢房里。如果你能带来——\n\n小心，海盗！",
  },
  [26264] = {
    ["T"] = "合同 #1010：魔法残渣",
    ["O"] = "从巴拉丁监狱收集4瓶魔法残渣。",
    ["D"] = "我这里有些工作，适合愿意组队的承包人。是时候创造节日魔法了！这一份来自节日装饰部门。\n\n合同 #1010：从巴拉丁监狱内部取得魔法残渣\n\n数量：四份样品",
  },
  [26319] = {
    ["T"] = "知识的遗产",
    ["O"] = "前往托尔巴拉德岛上的巴拉丁监狱，寻找卡雷德拉·晨风有意找回的书籍。",
    ["D"] = "旅者，请原谅我打扰你，但你的名字已经在贵族议院传开，而我一直在等一位声名卓著的英雄来到要塞。\n\n随着奎尔萨拉斯和达拉然相继陷落，我族许多知识都已遗失。然而，肯瑞托曾在托尔巴拉德岛上的监狱要塞巴拉丁监狱中维护着一座图书馆。那里可能保存着一些典籍，我非常希望能将它们保护下来。\n\n我能恳请你协助我完成这项事业吗？你会得到丰厚的报酬。",
  },
  [26320] = {
    ["T"] = "知识的遗产",
    ["O"] = "前往托尔巴拉德岛上的巴拉丁监狱，寻找博学者灰鬃有意找回的书籍。",
    ["D"] = "旅者，请原谅我打扰你，但你的名字已经在长者们之间传开，而我一直在等一位声名卓著的英雄来到灵魂高地。\n\n随着奎尔萨拉斯和达拉然相继陷落，高等精灵人民的许多知识都已遗失。然而，肯瑞托曾在托尔巴拉德岛上的监狱要塞巴拉丁监狱中维护着一座图书馆。那里可能保存着一些典籍，我非常希望能将它们保护下来。\n\n我能恳请你协助我完成这项事业吗？你会得到丰厚的报酬。",
  },
  [26323] = {
    ["T"] = "未竟之事",
    ["O"] = "从托尔巴拉德岛上找回乔治安娜·马丁遗失的传家宝。",
    ["D"] = "你——对，就是你！冒险者！也许你会听我说！\n\n我已经在幽暗城向各路有权势的人请愿了好几个星期，可他们根本不理会我的请求。第二次战争以前，我的家人曾住在托尔巴拉德岛上。他们大多死在那里，但我的一个叔叔逃了出来。他临终前告诉我，家里一件珍贵的传家宝藏在岛上一个安全的地方。可现在有传言说海盗出现在托尔巴拉德了！他们就是冲着那宝物去的，我敢肯定。\n\n听着，$C，我急需有人去岛上把那件宝物找回来。拿着这把钥匙！它能打开藏有宝物的暗格。求你了，把我家族的遗产还给我吧！",
  },
  [26331] = {
    ["T"] = "劫掠的海盗",
    ["O"] = "搭乘栖木管理员霍金斯的狮鹫，调查托尔巴拉德遭受的海盗袭击。",
    ["D"] = "三个月亮以前，我们的瞭望手在地平线上发现了帆影和船只。他声称以前见过他们的旗帜，但他似乎太害怕了，不敢说出是在何处、和谁一起见过。不久之后，炮火声便隔着海水传来。\n\n那个方向只有一座岛：托尔巴拉德，旧肯瑞托监狱的所在地。会有人想在那里找什么？这是突袭？还是越狱？\n\n我很好奇，而我迷信的船员们很害怕。你能帮忙！和栖木管理员霍金斯谈谈，请他载你去托尔巴拉德。我需要一名斥候去看看那座岛，告诉我到底发生了什么。",
  },
  [26340] = {
    ["T"] = "巴拉丁监狱可能陷落",
    ["O"] = "杀死袭击巴拉丁监狱的海盗主谋：格拉古特、卡吕普索和海盗领主黑石。",
    ["D"] = "雷尼克指示你，如果发现传闻属实，就亲手处理此事。\n\n解决局势最简单的办法，就是除掉目前控制巴拉丁监狱的海盗。\n\n你需要一路杀进监狱，确保秩序恢复。",
  },
  [26342] = {
    ["T"] = "巴拉丁监狱可能陷落",
    ["O"] = "杀死袭击巴拉丁监狱的海盗主谋：格鲁克、卡吕普索和海盗领主黑石。",
    ["D"] = "沃金指示你，如果发现传闻属实，就亲手处理此事。\n\n解决局势最简单的办法，就是除掉目前控制巴拉丁监狱的海盗。\n\n你需要一路杀进监狱，确保秩序恢复。",
  },
  [26548] = {
    ["T"] = "冷却之水",
    ["O"] = "从炽燃丘陵中的水流喷射者身上收集8份冷却的水流精华。",
    ["D"] = "我相信你知道，平衡是自然和谐的关键。一想到我必须伤害自己的同胞来恢复这种平衡，我就痛苦不已。\n\n凡人，这是我最深的悲伤：我必须请求你杀死附近的水元素。它们体内含有冷却的水流精华，我们可以用它来平息影响我同胞的怒火。你会在我的山北边，也就是水流汇聚之处找到它们。",
  },
  [26549] = {
    ["T"] = "痛苦的浇熄",
    ["O"] = "对虚弱的狂怒余烬使用舒缓之水瓶，以便收集它们的狂怒束缚。",
    ["D"] = "用你带来的冷却水流精华，我制成了一瓶舒缓之水。这能帮助你削弱炽燃丘陵中的狂怒余烬火元素，让它们冷却到足以让你收集其腕部束缚。\n\n把这些束缚带回给我，我们将用它们为这些丘陵迎来新的和平时代。",
  },
  [26550] = {
    ["T"] = "与水会面",
    ["O"] = "在炽燃丘陵中找到亚奎门塔斯。",
    ["D"] = "亚奎门塔斯是本地水元素的领袖，也是其中最强大者。他睿智而强大，其影响力延伸到炽燃丘陵的边界之外。\n\n虽然我们经常意见不合，但我非常尊敬亚奎门塔斯。他理解这片土地上平衡与和谐的重要性，并努力维持它。\n\n最近，水元素变得躁动不安，我担心这种不安可能与炽燃丘陵这里的动荡有关。我们必须以尊重和谦卑接近亚奎门塔斯，请求他协助恢复我们家园的平衡。\n\n他可以在北方水流自由奔涌之处找到。去求见他吧。",
  },
  [26551] = {
    ["T"] = "封闭喷口",
    ["O"] = "为亚奎门塔斯在炽燃丘陵中封闭8处蒸汽喷口。",
    ["D"] = "我相信我已经找到了我水域动荡的源头。地面上裂开了热力喷口，把水蒸发成蒸汽，扰乱了我们辛苦维系的平衡。\n\n我会将奔流之水的力量灌注给你，有了它，你就能摧毁那些喷口，永远封闭它们。请尽快行动；我担心我的同胞会伤害自己或他人。",
  },
  [26552] = {
    ["T"] = "羽毛供品",
    ["O"] = "为亚奎门塔斯在炽燃丘陵中收集6根完好的陆行鸟羽毛。",
    ["D"] = "封闭喷口并不能熄灭我同胞全部的怒火。单凭我们做不到。我们需要一位必须先安抚其自尊才愿意相助者的协助。\n\n空气是平衡的关键，既能让森林大火狂暴肆虐，也能冷却凡人额头上的汗水。但它是一种傲慢的元素，满是自吹自擂。\n\n我的计划会在合适的时候解释更多，但现在你只需要知道，我需要这些丘陵中最轻盈羽毛作为供品。它们可以从这一带的陆行鸟身上找到。去完成这项任务吧，凡人。",
  },
  [26555] = {
    ["T"] = "冷却怒火",
    ["O"] = "使用艾洛米尔赐予的平静之风，削弱并安抚炽燃丘陵中的沸腾游荡者。",
    ["D"] = "虽然我毫不怀疑阿特拉希斯会让你屠杀他的同胞来让他们服从，但我拒绝那样做。水不像火那样鲁莽；沸腾可以被抚平。\n\n用艾洛米尔赐予你的平静之风，让我的子嗣从怒火中解脱出来。你需要先削弱它们，理智才会回归。",
  },
  [26556] = {
    ["T"] = "回归火焰",
    ["O"] = "返回炽燃丘陵中的阿特拉希斯那里。",
    ["D"] = "虽然你已经安抚了我的同胞，但炽燃丘陵中的问题根源很深。是时候让我们与阿特拉希斯会面了。你可以回到他那里，告诉他我们同意见面。",
  },
  [26557] = {
    ["T"] = "召开议会",
    ["O"] = "与阿特拉希斯交谈，见证元素议会。",
    ["D"] = "是时候彻底弄清炽燃丘陵到底发生了什么了。过去数千年里，我们这些元素领袖很少召开会议，但如今形势严峻。我召集议会：艾洛米尔、亚奎门塔斯、吉奥玛尔，还有我自己。空气、水、大地与火焰。我们将共同经受所有敌人。再次与我交谈，见证这场会议。",
  },
  [26562] = {
    ["T"] = "一点甜头",
    ["O"] = "从炽燃丘陵收集8筐巨型暗影莓。",
    ["D"] = "火羽最喜欢的点心之一就是暗影莓，但它只喜欢最大的浆果。我丈夫觉得他种出来的是最好的，不过……就说那不是真的吧。炽燃丘陵上，元素的存在帮助造就了最肥沃的土壤。最好的暗影莓就在那里。\n\n你能去收集一些，让我做成诱饵，把火羽引回来吗？",
  },
  [26563] = {
    ["T"] = "一点肉香",
    ["O"] = "从炽燃丘陵中的炽燃爬行者身上收集10块爬行者肉块。",
    ["D"] = "火羽另一个最喜欢的点心是烤爬行者肉块。最好的肉块来自腿与身体相连的关节处。\n\n炽燃爬行者可以在炽燃丘陵中找到。如果你能给我收集一些它们的肉，我就会把它和暗影莓混在一起，做成火羽无法拒绝的美味。",
  },
  [26576] = {
    ["T"] = "黑暗萨满",
    ["O"] = "在南部炽燃丘陵中找到并杀死黑暗萨满德雷兹科和黑暗萨满恩维。",
    ["D"] = "德雷兹科和恩维就是我们真正敌人的名字。我没有什么伟大的演说要给你，$N。只要杀了他们，碾碎他们，然后亲自把他们的头颅带给我。我会尽我所能重重奖赏你。",
  },
  [8927] = {
