  [26263] = {
    ["T"] = "安希恩的离别感言",
    ["O"] = "把一条勇气腿铠带给奥格瑞玛的莫克瓦尔。",
    ["D"] = "瓦塔拉克的灵魂被存封在这个护符里。因为我们的贪婪，我们愚蠢地把它分成三部分，却不知道等待我们的会是什么诅咒。\n\n阻止瓦塔拉克法术的唯一方法就是把护符重新组合起来。回到莫克瓦尔那里，告诉他伯德雷是他找到剩余碎片的唯一希望。跟他谈谈你们安排好的任何奖励。\n\n这一次，我终于可以安息了。祝你好运；你会需要每一点好运的！",
