  [26290] = {
    ["T"] = "巨魔圣物",
    ["O"] = "在奥格瑞玛寻找一位博学的传说讲述者。",
    ["D"] = "摆在你面前的是一尊古老而风化的神像，形状隐约像一个不可思议的远古人类。这也许会引起一位博学的巨魔传说讲述者的兴趣——其中最有名的可以在奥格瑞玛的精神谷找到。",
  },
  [26312] = {
    ["T"] = "圣光的材料",
    ["O"] = "使用阿图尔克的材料清单，找到一些祝福锭、泽勒玛尔之锤、一枚白银之手勋章和一颗科尔宝石。把它们带给奥格瑞玛的铁砧阿图尔克。",
    ["D"] = "我把时间花在磨炼技艺，以及研究可以摆弄的材料上。在旅途中，我得知了一些对你的锤子有用的资源。 \n\n<阿图尔克猛地转向奥克斯，叫他把自己的要求写下来。>\n\n拿着这封信，去取东西！",
  },
  [26434] = {
    ["T"] = "翻译好的结构图",
    ["O"] = "把翻译好的结构图带给奥格瑞玛荣誉谷的铁砧阿图尔克。",
    ["D"] = "我已经为你完成了笔记。这张结构图似乎是圣骑士用的马甲。我祝贺你达成这个里程碑，$C。祝你今后好运。我希望能在这里见到你，向游荡在这片土地上的邪恶狠狠一击。",
  },
  [26457] = {
    ["T"] = "被遗忘的身躯",
    ["O"] = "把10块亚麻布带给幽暗城军事区的奥里萨·布雷尔。",
    ["D"] = "我想那位骑士告诉过你，我过去曾是这里的孤儿院长。当天灾军团袭来时，我……\n\n<奥里萨一时哽咽，随后恢复了镇定。>\n\n现在这不重要了，重要的是终结天灾军团，让这种事不再发生。\n\n不过也许……如果你能给我带些亚麻布，我可以为奥格瑞玛的孤儿做些衣服。至少在战斗训练间隙，我还能再次运用生前的手艺。",
  },
  [27056] = {
    ["T"] = "返回萨尔那里",
    ["O"] = "与奥格瑞玛智慧谷的萨尔交谈。",
    ["D"] = "啊，$C。我相信这里有给你的消息。\n\n我们的大酋长萨尔命你回到奥格瑞玛与他交谈。他有关于火刃氏族的消息。",
  },
  [27066] = {
    ["T"] = "新的恶魔之种",
    ["O"] = "把封印的妖牙匣带给奥格瑞玛的萨尔。",
    ["D"] = "妖牙匣现在已经被魔法封印了，$N。你可以乘双足飞龙把它带到奥格瑞玛，交给萨尔。他会确保它被放在安全的地方监视起来。\n\n你做得很好，年轻的$C。我期待再次见到你。",
  },
  [27122] = {
    ["T"] = "远古土地的战利品",
    ["O"] = "把毛皮包裹带给奥格瑞玛的卡玛莉。",
    ["D"] = "还有最后一件事想请你帮忙，朋友。俺在奥格瑞玛有个熟人，她会很乐意处理这些皮子，但出于……某些原因……俺暂时不进城。把这包毛皮带给暗巷区制皮店的卡玛莉，她会好好报答你的辛苦。\n\n不过如果她问起来，不，你没见过俺，也不知道俺在哪里，支票已经寄出去了。",
  },
  [27242] = {
    ["T"] = "破影峡谷",
    ["O"] = "返回奥格瑞玛的萨尔那里。",
    ["D"] = "唉，扎卡拉不知道接下来该怎么办。我们必须找到办法突破那座堡垒的大门，但在不了解里面有什么的情况下贸然冲进去太愚蠢了。至少她是这么说的。我倒是很想看你试试。\n\n<皮普乔特露出满口牙齿，朝你笑了笑。>\n\n所以，去告诉萨尔吧。现在这是他的问题了。",
  },
  [27271] = {
    ["T"] = "熟练狼骑术",
    ["O"] = "向基尔达学习熟练骑术，然后与奥格瑞玛的奥古纳罗谈谈，领取你的骑乘狼。",
    ["D"] = "欢迎回来。你是来学习熟练骑术的，对吧？和之前一样，你的狼的费用已经有人支付，但训练费用仍需你自己承担。很遗憾，迅捷骑术很昂贵。\n\n获得训练后，和我旁边的奥古纳罗谈谈。他负责出售我们的狼。如果你现在资金不足，随时可以回来。",
  },
  [27272] = {
    ["T"] = "狼骑术",
    ["O"] = "向基尔达学习初级骑术，然后与奥格瑞玛的奥古纳罗谈谈，领取你的骑乘狼。",
    ["D"] = "所以你是来要一头狼的，是吗？巧了，我正等着你！一位神秘资助人给我们留下了骑乘狼的费用，而且是以你的名字指定的，$N。不过他们没有支付你的训练费，所以恐怕你仍得自己购买训练。\n\n获得训练后，和我旁边的奥古纳罗谈谈。他负责出售我们的狼。如果你现在资金不足，可以稍后再回来。",
  },
  [27309] = {
    ["T"] = "第三次战争的遗物",
    ["O"] = "把这箱可怖的遗物带给奥格瑞玛智慧谷的萨尔。",
    ["D"] = "幸好你来了，$N。我查看这些物品时才发现，它们比我原先想的还要骇人——这些头骨属于军团进军海加尔山途中杀害的一部分受害者。\n\n那些邪教徒还在上面刻下了他们的名字。虽然我并不认识这些死者，但他们既然曾为保卫世界之树而战，就理应以英雄之礼得到安葬。\n\n请把这些战利品交给部落大酋长萨尔，也就是那场冲突的胜利者之一。我相信，在决定下一步该怎么做这件事上，他的判断值得信任。",
  },
  [27455] = {
    ["T"] = "寻找陵墓",
    ["O"] = "请奥格瑞玛的传说讲述者基欣翻译图尔玛瑞信物。",
    ["D"] = "<传说讲述者万扎叹了口气。>\n\n俺早该想到的。这些信物是用古代沙怒巨魔语言写的，俺读不懂。\n\n奥格瑞玛的传说讲述者基欣能读懂。请把信物带给他，问问上面写了什么。\n\n你会在精神谷和其他传说讲述者一起找到他。",
  },
  [27538] = {
    ["T"] = "风暴汇聚",
    ["O"] = "把杰迪·科琳的报告带给奥格瑞玛暗巷区的齐尔兹宾·德拉姆洛尔。",
    ["D"] = "我们不能把这个进展秘而不宣，$N！我正好知道该找谁——炼金师匹斯特苏格提过，他正在为奥格瑞玛的一位顾问齐尔兹宾·德拉姆洛尔研究异种虫。拿上这份报告，亲自送过去！他会知道该怎么做！",
  },
  [27906] = {
    ["T"] = "鲜血与荣耀的纽带",
    ["O"] = "在奥格瑞玛萨尔的大厅中与纳兹格雷尔交谈，表达你想了解兽人的兴趣。",
    ["D"] = "我听说你有兴趣进一步了解我们的盟友——兽人。如果这是真的，你应该去找纳兹格雷尔谈谈。你会在奥格瑞玛萨尔的大厅中找到他。",
  },
  [27919] = {
    ["T"] = "鲜血与荣耀的纽带",
    ["O"] = "回到奥格瑞玛萨尔的大厅，去见纳兹格雷尔。",
    ["D"] = "我相信你现在已经更了解我的人民了，$R。我们本就是盟友，但现在你知道了，当你在战场上与兽人并肩作战时，那会是一场荣耀之战。一场值得你全力以赴的战斗。\n\n回到派你来的人那里，把你学到的告诉他们。再会！",
  },
  [27920] = {
    ["T"] = "鲜血与荣耀的纽带",
    ["O"] = "在奥格瑞玛勇气竞技场找到统帅佐克。",
    ["D"] = "既然你已经更了解兽人的荣誉，就能在战斗中用这些原则指引自己。如果你想更彻底地拥抱它们，就去奥格瑞玛寻找统帅佐克。祝你好运，$C。",
  },
  [27927] = {
    ["T"] = "荣耀与鲜血的记忆",
    ["O"] = "与伊崔格谈谈你想进一步了解人类的愿望。",
    ["D"] = "我听说你有兴趣进一步了解我们的主要敌人——人类。我们两族之间仍然关系紧张，这似乎是个明智的选择——知己知彼，诸如此类。\n\n许多部落成员曾在战争中与人类交战，但没有谁像萨尔和伊崔格那样了解他们的心思。萨尔最近很忙，不过你也许能得到伊崔格接见。去奥格瑞玛萨尔的大厅中找他。",
  },
  [27930] = {
    ["T"] = "荣耀与鲜血的记忆",
    ["O"] = "在奥格瑞玛勇气竞技场找到统帅佐克。",
    ["D"] = "我希望你的旅程让你更清楚地看见了人类的本质，无论是好的一面，还是坏的一面。如果你想与他们更加接近，就去奥格瑞玛找统帅佐克谈谈。",
  },
  [27946] = {
    ["T"] = "行巫毒",
    ["O"] = "与奥格瑞玛勇气竞技场的统帅佐克交谈。",
    ["D"] = "和你合作挺愉快，$N。\n\n那双眼睛也会给你看见宝藏……\n\n去奥格瑞玛找统帅佐克吧，扎昆科跟你的事已经办完了。",
  },
  [27967] = {
    ["T"] = "返回奥格瑞玛",
    ["O"] = "与奥格瑞玛勇气竞技场的统帅佐克交谈。",
    ["D"] = "好吧朋友，做巨魔可不只是引导怒火，但如果你想多了解一些，我想奥格瑞玛里有人能给你更多指点。\n\n$E使者瓦尔克隆提过，有个叫佐克的牛头人很想了解我们的历史。很久以前，世界各地的人都来向巨魔学习。但那已经是很久以前的事了，久到大多数生灵都不记得。\n\n<巫医哈尔德赫朝你眨了眨眼。>\n\n祝你好运，冒险者。",
  },
  [28007] = {
    ["T"] = "火焰仪式",
    ["O"] = "与奥格瑞玛暗巷区的扎姆沙谈谈，报告你的成功。",
    ["D"] = "我现在准备好了。美食评论家尽管来吧。我会保住我的米什伦星，而伊莎贝尔可以继续默默无闻地打滚。\n\n你现在必须赶紧走了。我可不能让评论家以为你才是我成功的关键！派你来的朋友扎姆沙大概会想知道发生了什么。\n\n你可以告诉她，我认可你。",
  },
  [28366] = {
    ["T"] = "医护仪式",
    ["O"] = "与奥格瑞玛智慧谷的伊崔格交谈。",
    ["D"] = "我看你已经完成了急救学习。干得好，$N。\n\n你现在来得正是时候。部落需要一位经验丰富的医护人员。大酋长亲自命令他的首席副官伊崔格寻找合适的人选，而我想不到比你更合适的人了。\n\n如果你愿意响应召唤，可以在智慧谷找到伊崔格。",
  },
  [31031] = {
    ["T"] = "奥术疫害",
    ["O"] = "返回奥格瑞玛，告知萨尔你的成功。",
    ["D"] = "再次感谢你，冒险者。今天你为艾泽拉斯立下了伟大的功绩。 \n\n毫无疑问，你的领袖会想听听你的英雄事迹。",
  },
  [31043] = {
    ["T"] = "吉利吉姆之岛之战",
    ["O"] = "在吉利吉姆之岛取得3次胜利，然后回到奥格瑞玛风之谷的韦尔查那里。（该任务每周可以完成一次）",
    ["D"] = "",
  },
  [8979] = {
    ["T"] = "芬斯塔的预感",
    ["O"] = "将1瓶古龙水和1瓶香水交给幽暗城炼金房的药剂师金格。",
    ["D"] = "我想我知道最近这种行为的原因了。你有没有闻到风中飘来的新香味，甚至盖过了运河的臭味？那些新流行起来的古龙水和香水？\n\n我们的思绪被某种邪恶炼金术蒙蔽了。\n\n只有一个办法能确定——带一瓶古龙水和一瓶香水给我的朋友药剂师金格。皇家药剂师协会会找出真相。\n\n你回来的时候，我会报销购买它们的费用。",
