    ["D"] = "幸会，$C $N。我最近去了幽暗城，并有机会和陨落骑士谈了谈。\n\n<这名圣骑士轻声笑了笑。>\n\n我真希望有一天能知道她的真名，总觉得这样称呼她很不专业。尽管如此，她对你的潜力评价很高，并希望我派你去她那里接受几项试炼。前往幽暗城，找到她。",
