    ["O"] = "如果你愿意接受试炼，就与幽暗城的陨落骑士交谈。",
    ["D"] = "我已不再是从前的自己了，$C $N。曾经的我是白银之手的骑士，一名品德高尚的圣骑士，真理与正义的守护者。如今我却躺在幽暗城的深处，在这片污泥里钓着病恹恹的生物。\n\n而你，即使黑暗也栖息在你自己的灵魂中，仍愿意与黑暗战斗。如果你接受，我愿意考验你。",
