    ["D"] = "时机到了，$N，你该了解自己需要付出什么，才能获得旅途中无疑已经想过的东西……你的战马。\n\n去和幽暗城的陨落骑士谈谈。她会指引你完成必要的任务。\n\n我祝你在这场试炼中一切顺利。为了圣光，高贵的$gbrother:sister;！",
