    ["O"] = "与幽暗城的陨落骑士交谈。",
    ["D"] = "再次向你致意，$N。我比以往任何时候都更自豪能称你为$g brother:sister;——你的奉献是我们所有人的荣耀。\n\n现在，我将赐予你一份伟大的礼物。但你要知道，如今我会无偿赐予你它；而日后，当时机允许时，这对所有选择接受我任务的圣骑士来说，都将成为一场更大的挑战。\n\n再次与我交谈，我会赐予你一份伟大的恩赐。",
