    ["O"] = "前往幽暗城，与军事区的陨落骑士交谈。",
    ["D"] = "幸会，$g brother:sister;。你见过陨落骑士了吗？她是一位强大的圣骑士，只是对生前的身份讳莫如深，所以我们才这样称呼她。我相信你已经准备好向她学习了，因为有些课程我无法教你。\n\n你会在幽暗城的军事区找到她，她正在那片我真希望自己一无所知的可怕污泥里钓鱼。愿圣光与你同在。",
  },
  [26456] = {
    ["T"] = "被遗忘的身躯",
    ["O"] = "在幽暗城军事区找到阿莉莎·布莱。",
    ["D"] = "现在我们可以开始了，$N。通常我会希望派你去寻找一个心灵与动机都纯洁的人，但我必须承认，当我们的心脏都不再跳动时，这个要求实在太高了。所以我会把你引向正确的方向。\n\n去找正在运河对面训练的阿莉莎·布莱——其实你从这里就能看见她。天灾降临之前，她曾是洛丹伦王城的孤儿院长。如今她把所有时间都用在训练上，帮助防止那样的悲剧再次发生。\n\n别问她孩子们的事，$N。",
