    ["D"] = "你站在兰斯·哈特斯托伦的尸体旁，想起了陨落骑士的话。\n\n“不过要注意，并不是每个人都能像你一样忍受圣光在我们尸僵身躯上造成的痛苦。”\n\n也许已经没什么可做的了，是时候回去了……不过在那之前，这个世界上的血色十字军或许还能再少一些。",
