    ["D"] = "我实在不明白我们眼前看到的现象，除非被遗忘者的本质——介于生与死之间的存在——有些超出了科学能够把握的范围。这里缺少了一块拼图，而我觉得自己别无选择，只能让一位被遗忘者参与研究。把数据拿给大药剂师法拉尼尔，看看他怎么想。",
