    ["D"] = "这只图腾能让你看见那些被困在生者与死者世界之间的灵魂——鬼魂。其中一个灵魂会帮助你，但首先你必须因它生前所做的事对它施以审判。\n\n在血色修道院后方被称为安息露台的花园里，将灵魂图腾插入地面。它能让你看见凡人双眼无法看见的东西。寻找一名陨落圣骑士的灵魂。与这个灵魂战斗，它就会欠你一份武人的荣誉债。当你的任务完成后，那个灵魂会与你交谈。",
