    ["D"] = "你已经准备好接受第一堂真正的课程了，$C $N。不过，我没有一本圣洁之书供你阅读，所以这会和活着的圣骑士所做的事大不相同。\n\n“怜悯、耐心、勇气——这些东西对圣骑士而言，与战斗中的力量同样重要。”这是那本书中的许多语句之一，也是你必须学习的东西。我们已经死去，是不洁的存在，而我不明白圣光为何还会回应我们。我们的灵魂本身就在抗拒我们理应追求的理想。\n\n准备好接受一场言语的冲击，然后再和我交谈。",
