    ["O"] = "从安戈洛河岸收集4份细河沙，并从安戈洛环形山的软泥怪身上取得一份软泥化合物。",
    ["D"] = "我的伙伴杰尔莎和我来到安戈洛研究暗夜精灵历史。我还没有近距离研究过这些水晶塔，但我相信它们比暗夜精灵还要古老许多。\n\n我们可以依靠某些研究原则来判断水晶塔是在什么时候受损的。\n\n我需要一些材料，为你组装一套调查用工具。我得照看杰尔莎，不过如果你能从河岸弄些细沙，再从当地软泥怪身上弄些黏性化合物，那就能帮上忙。",
