    ["D"] = "好，计划是这样的。你需要回到南部水晶塔，涂上这种化学萃取物。如果水晶塔的碎片已经在地上躺了一年以上，那么厚重丛林环境中积累的泥土和苔藓会吸收这种化合物，什么都不会发生。但如果是近期断裂，就不会有足够的沉积物吸收全部萃取物，你就会看到反应。\n\n我不能确切说那会是什么，但我很确定你不会错过！",
