  [27532] = {
    ["T"] = "其中有一样不一样",
    ["O"] = "把关于南部水晶塔的情报带回安戈洛环形山马绍尔营地的科琳那里。",
    ["D"] = "真是迷人的进展！你观察到的反应说明，过去一年内有人对水晶塔使用过某种爆炸物。你明白这意味着什么吗？\n\n水晶塔不太可能是因为年代久远或天气影响而受损的。有人破坏了它。但为什么？\n\n虽然我很想知道你会发现什么，但我得留在这里陪着杰尔莎。不过科琳必须听到这件事；你应该立刻告诉她。",
  },
  [27533] = {
    ["T"] = "其中有一样不一样",
    ["O"] = "询问霍尔安妮·马绍尔是否能判断安戈洛的异种虫巢有多古老。",
    ["D"] = "所以有人故意摧毁了其中一座水晶塔——但为什么？我有一个令人担忧的理论。那些水晶塔也许与这些虫类生物及其虫巢的扩张有关。\n\n我们可以尝试用一种方法确认这个理论。我记得霍尔安妮有兴趣检查异种虫巢。也许她的研究能告诉我们这个虫巢存在了多久。如果它只是在过去一年里出现的，那我们就该非常担心了。",
