    ["D"] = "我们的小队在安戈洛入口处停下来，并注意到了那些水晶塔，所以我知道你在问什么。它们是其拉造物——一种类人生物种族，与异种虫有亲缘关系。它们算是一种警告，表示环形山禁止进入，或是很危险，但这只是粗略翻译。他们的语言和概念与你我交流的方式相当不同。\n\n我们对这个地方的历史了解不多，只知道很久以前这里爆发过一场大战，异种虫和其拉都被击败了。很抱歉我现在还不能告诉你更多——不过如果你以后回来，欢迎你帮助我们的研究。也许到那时，你会找到想要的答案。",
