    ["D"] = "霍伊让你大老远亲自跑到这里来询问泰坦科技？嗯，我能告诉他的并不多！我一直在研究散布在环形山各处的水晶塔，但我并不真正知道它们是否像泰坦那样古老。\n\n如果要我猜，这里的元素非常古老。而且这里到处都是焦油坑。也许他们的某些科技被焦油元素吸进去了？如果你解剖足够多的焦油元素，也许能找到一些古老的泰坦物件！",
