    ["D"] = "我们必须更多地了解阿鲁-塔利斯发生了什么。要在这里进行完整的考古发掘，需要数月，甚至数年。但遗物往往会留在地表，甚至被当地生物捡走。\n\n你描述的那些空气元素也许吸入了遗物，只要杀死它们，我们就能轻松取回。请你收集几件来做比较，好吗？",
