  [27525] = {
    ["T"] = "阿鲁-塔利斯的传说",
    ["O"] = "造访阿鲁-塔利斯的四处废墟并寻找石板。拓印你找到的任何石板，并把拓片带给安戈洛环形山的杰尔莎·石歌。",
    ["D"] = "又见面了，$N。我查看了你带回来的遗物，它们提到了一种叫做“基石石板”的东西。这只是粗略翻译，所以我不确定它到底是什么意思，但我认为这暗示着一个整体的不同部分被分散在阿鲁-塔利斯各处。 \n\n我确信整件东西已经不完整了，但如果我们能收集到足够多的部分，也许就能通过上下文理解其余内容。 \n\n你愿意前往先前找到的各处废墟，寻找一块写有文字的石板吗？也许是环形文字。请带上这些拓印用品，为我拓印那些石板。",
  },
  [27534] = {
    ["T"] = "其中有一样不一样",
    ["O"] = "把你了解到的情况报告给马绍尔营地的科琳。",
    ["D"] = "根据你带来的虫巢壁样本，这些隧道看起来相当新。事实上，我们见过的所有异种虫巢都比较新。这些生物成长很快，扩张也很迅速。\n\n我估计这个虫巢存在了一年或更短时间。希望这能帮上忙！",
  },
  [27972] = {
    ["T"] = "工坊仪式",
    ["O"] = "与安戈洛环形山马绍尔营地的科琳交谈。",
    ["D"] = "现在我有了笔记本，就能重新想起自己之前发现了什么。哦，对了！我收到过一封磨损得很厉害的信，来自一位前往未知之地安戈洛环形山探险的同事。她怀疑环形山中可能能找到泰坦科技的残余，而且也许与故障保险装置有关。\n\n你知道吗，我得花些时间重新阅读所有笔记。你为什么不去找她呢？可以说，直接从那位侏儒口中获得最新消息。那里路途遥远，等你回来时，我应该已经准备好从停下的地方继续了。",
  },
  [27974] = {
    ["T"] = "工坊仪式",
    ["O"] = "安戈洛环形山马绍尔营地的科琳要你制作一个精密奥金转换器并带给她。",
    ["D"] = "这东西肯定能打开！只是被机械方式封住了。要是我们有一个精密奥金转换器就好了。\n\n等等！你说过自己是工程师，对吧？你能做一个吗？如果你能制作一个并带给我，我想我就能把这东西打开！",
  },
  [27542] = {
    ["T"] = "阿鲁-塔利斯的玩具",
    ["O"] = "从栖息在安戈洛环形山阿鲁-塔利斯废墟中的空气元素身上收集8件“玩具”。",
    ["D"] = "毒皮暴掠龙不是宠物，但在饲养和训练它们时，激发它们爱玩的天性很有好处。 \n\n能经得起暴掠龙当玩具折腾的东西不多，但石制物品最有机会撑过一天。我见过环形山周围山丘上的精灵废墟。有时，如今居住在那里的空气元素会吸入古老的精灵石制神器，而这些东西正好可以给年幼的毒皮当玩具。\n\n你能帮我收集几件吗？你可以在安戈洛的东北和西南边缘找到它们。",
  },
  [27541] = {
    ["T"] = "毒性耐受",
    ["O"] = "攻击安戈洛环形山的毒皮暴掠龙，直到你被毒皮的血液溅到20次。",
    ["D"] = "你想骑毒皮？那我可有坏消息告诉你。\n\n毒皮暴掠龙全身都是毒：毒血、毒唾液、毒皮。你爬到一只身上，几个小时后就会摔下来死掉。\n\n在我把它卖给你之前，你得先建立对它们毒素的抗性，而那需要很久，很久……如果你真的有兴趣，毒皮更喜欢这里西北方沼泽地的北部区域。去和它们战斗，让它们的血多溅你几次。",
  },
  [27955] = {
    ["T"] = "快速反射！",
    ["O"] = "从安戈洛环形山沼泽地的恐爪暴掠龙身上取回12根粗韧心弦。",
    ["D"] = "我做了一个机械护套，可以套在身体的各个关节上，增强佩戴者的反射能力。我知道你在想什么……这安全吗？\n\n我还不知道，不过我们会弄清楚的！别担心，任何断掉的骨头或关节我都能修好。\n\n<韦林在你面前扭动着他那扭曲的手指。尽管已经畸形，它们看起来却出奇地灵巧。>\n\n我现在需要恐爪暴掠龙的心弦。那是一种稀有的迅猛龙，只出没在安戈洛环形山沼泽地的一处洞穴里。这些野兽以瞬间反应能力闻名，你也能想象，像那样的生物一定有一颗坚韧而反应灵敏的心脏！",
  },
  [26330] = {
    ["T"] = "另一个人生的梦",
    ["O"] = "保护帕拉·恐怖图腾，让她带你前往藏宝处。",
    ["D"] = "这座农场曾是我们的梦想。我想我一直都知道，他其实永远不会真正回到这里。做私掠者是危险的行当，后来他又彻底转向了海盗生涯……\n\n我不知道黑石是怎么把宝藏运到这里来的，但他把它藏在了附近的洞穴里。我想那是他留给我的最后一份礼物，可我一直没法进去。那里被帷幕彼端的灵魂占据。它们会试图击退我们。但如果你强到足以在战斗中击败我的爱人，并从诅咒中活下来来到这里，也许你也足以击败它们。\n\n准备好出发时就告诉我。",
  },
  [27314] = {
    ["T"] = "所有生灵的自由",
    ["O"] = "使用竹笼钥匙，从恐怖图腾营地的围栏中释放小精龙。至少6只小精龙和卢尤娅·地月必须存活。\n\n在卢尤娅决定该撤退并导致你任务失败之前，你有6分钟时间。",
    ["D"] = "肮脏的恐怖图腾氏族正在捕捉精灵龙，$N。奥尔多和我不知道他们打算拿这些精灵龙做什么，但他们显然没安好心。\n\n我们还不够强大，无法一路杀进营地并释放被俘的龙，不过也许有你的帮助……我们能做点什么。\n\n如果你愿意，而且有几位强大的朋友，就用这把钥匙把那些生灵从笼中放出来，并确保它们活着逃出去。我会一直在你身边。奥尔多会留在这里。",
  },
  [27923] = {
    ["T"] = "恐怖图腾的背叛",
    ["O"] = "杀死8名恐怖图腾掠夺者，并杀死萨娜·暗云。",
    ["D"] = "<看来传言是真的。这个定居点正在被恐怖图腾部族翻得一片狼藉。>\n\n<这些叛徒必须为他们的罪行付出代价。也许你能找到幸存者，并查明他们为何洗劫了这个地方。>",
  },
  [26326] = {
    ["T"] = "步入炼狱",
    ["O"] = "找一个能告诉你更多关于不祥白色宝珠的人谈谈。",
    ["D"] = "在黑石船长箱中的宝物里，有一颗奇怪的乳白色宝珠，正闪动着不祥的红光。当你抚过它光滑的表面时，这颗宝珠给人一种异样的安心感。弄清楚这件物品到底是什么，也许是个明智的选择。",
  },
  [26329] = {
    ["T"] = "另一个人生的梦",
    ["O"] = "找到黑石和他的爱人的共同朋友。也许黑石的日志里有他朋友所在位置的线索？",
    ["D"] = "你没有找到宝藏和“缚幕者”诅咒的源头，而是找到了一张便条，上面说明黑石把宝藏藏在了别处，以保护他的船员。这一高尚举动却注定让你继续携带被诅咒的帕雷斯之眼。\n\n只有黑石的爱人才知道宝藏的真正位置。找到她，是你摆脱诅咒的唯一希望。",
  },
