  [26481] = {
    ["T"] = "大地的召唤",
    ["O"] = "找到公羊石并喝下大地灵契。",
    ["D"] = "灵契是一种用来把我们的灵魂与元素相连的饮品。融入魔法后，这种药水能让敞开心灵者看见前所未见的元素。你的灵魂将永远与灵契所对应的元素相连，而只有我们族人中少数被选中的人知道它的制作秘密。\n\n灵契总是在神圣之地饮下，绝不能在其他地方饮用。\n\n去寻找西边的萨满祭坛，并喝下灵契。",
  },
  [27372] = {
    ["T"] = "元素束缚",
    ["O"] = "从暮光地王和暮光唤石者身上取回6只元素束缚护腕。",
    ["D"] = "暮光之锤无休止地行动着，召唤元素并将它们束缚在这个位面。我们的斥候报告说，该教派在东部和东南部最为集中，而他们的大多数束缚仪式也在那里进行。\n\n如果你是来协助英勇远征队的，我请求你找到并破坏他们的行动。把他们用来束缚元素的护腕带回来给我。",
  },
  [26214] = {
