    ["D"] = "你仔细搜索了钓鱼椅周围的区域，却没有发现霍文的鱼饵，也没有任何其他钓鱼用品。你怀疑那些东西可能已经被冲下了瀑布。如果你运气好，它们也许就在瀑布底部的泥里。",
