  [26215] = {
    ["T"] = "霍文最爱的钓鱼点",
    ["O"] = "从禁忌之海找回霍文最爱的鱼饵。",
    ["D"] = "一股强劲的水流从瀑布流出，向东汇入禁忌之海。\n\n如果霍文钓具箱里的东西被卷入水流，它们可能已经被冲到了这里东边的海架上。\n\n在回去告诉霍文鱼饵丢失之前，值得先搜寻一番。",
