  [26289] = {
    ["T"] = "叛逆的纳迦",
    ["O"] = "在闪泥矿洞中杀死5名潮水先知、5名潮水战士和格纳什。",
    ["D"] = "作为女王多年的仆从，我憎恶不忠。然而，误入歧途的纳迦会在深海腐化仆从的带领下迷失方向。\n\n你喜欢跑腿小差事，对吧，凡人？这个如何：渡海前往那些地精挖掘的地方。那是内陆深处，对我们来说太干燥，无法亲自前往。地精偶然闯入了一处离群纳迦的巢穴，而他们由一个叫格纳什的家伙领导。杀掉格纳什的仆从，然后终结他的存在。\n\n因为我们不能容忍任何违抗女王者继续活着。",
  },
  [26519] = {
    ["T"] = "菲莉希蒂的破译",
    ["O"] = "等待菲莉希蒂·匹瑞诺德破译附魔羊皮纸。",
    ["D"] = "你会在楼下找到菲莉希蒂·匹瑞诺德，她是前国王艾登·匹瑞诺德的侄女，也是伊西登·匹瑞诺德的妹妹。她做我的被监护人已经将近二十年，我能教她的所有本事她都学会了，甚至还不止如此。 \n\n你的行动让她得以离开庄园。既然她的堂兄已经被处理掉，她就可以公开生活，不必害怕辛迪加刺客突然袭击。 \n\n菲莉希蒂是一位精通法术的专家，尤其擅长奥术学派。让她来试着破解这份文件吧。",
  },
  [26564] = {
    ["T"] = "引诱火羽",
    ["O"] = "把强烈气味的诱饵放在麦酒石码头上，靠近它的巢穴。",
    ["D"] = "有了你带来的爬行者肉块和暗影莓，我就有了火羽最喜欢的两种美味。把它们合在一起，它肯定无法拒绝，会飞回我们这里。这味道有点太冲了，所以我毫不怀疑它能传得很远。你能把它放到码头上的巢穴里吗？",
  },
  [26635] = {
    ["T"] = "炽燃多头蛇",
    ["O"] = "杀死灰落岗哨西边的格鲁玛队长、巫师玛尔塔格和铸造大师特拉拉克。",
    ["D"] = "我盯着外头那些发号施令的兽人有一阵子了，也找出几个你若愿意就该除掉的家伙。\n\n格鲁玛队长在这儿西边那座大塔附近，对部队吼着巡逻命令。巫师玛尔塔格就在塔西南边不远处搞什么仪式……肯定没安好心。铸造大师特拉拉克，正如你猜的那样——就在熔炉边……这些家伙也没什么别的好说。\n\n小心背后，$C。你离开时我会继续侦察。",
  },
  [26647] = {
    ["T"] = "无法者之法",
    ["O"] = "翻找索瑞森之渴楼下房间里的客人物品。",
    ["D"] = "我一直讨厌城里那种无休止的疑神疑鬼。就算卡鲁姆是铁怒军官，我们也得小心，不能踩到太多人的脚趾。到了外面，我们倒是多了点回旋余地……\n\n如果你愿意，不妨去楼下一些客房里翻找一下，看看能找到谁或什么东西。据我所知，我们在这里住得最久，所以那个密探可能是任何人。\n\n杀掉那个密探。当然，你会得到报酬。没有东西是免费的。",
  },
  [26882] = {
    ["T"] = "给萨曼莎的药膏",
    ["O"] = "从格罗姆高北边的黑腮强盗和黑腮猎人身上收集一株疾行蓟。",
    ["D"] = "等等，$N！我无意中听到了肯维雷给你的关于这药膏的指示。我不是真正的炼金师，但我懂试剂，而且我相信你做出来的东西会在无意中毒死萨曼莎，而不是救她！\n\n你还需要另一种材料才能让这份药膏成功。在镇子北边，你会找到一处黑腮鱼人的巢穴。他们的强盗会被一种名叫疾行蓟的稀有草药吸引。如果你真的想帮萨曼莎，就杀掉他们，收集一些疾行蓟。",
  },
  [26890] = {
    ["T"] = "我的朋友，劈颅者",
    ["O"] = "完成仪式，然后回到格罗姆高的传说讲述者伊兹利那里。",
    ["D"] = "你点燃了熏香，却不知道接下来会发生什么。血顶氏族肯定不会喜欢这个仪式。",
  },
  [26899] = {
    ["T"] = "力量之环：德克德",
    ["O"] = "击败擂台冠军。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "他们不得不把冠军从祖阿曼的角斗坑里运过来。他一直在拿山岭巨人训练——一次三个。\n\n如果你赢了，你就会成为新的冠军。你觉得自己的胜算如何，孩子？有机会吗？只要你一句话，我就把全部家当押在你身上。\n\n现在进去，赢下来！",
  },
  [26911] = {
    ["T"] = "野生郁金香",
    ["O"] = "见证切尔·月林的仪式。",
    ["D"] = "感谢你为我所做的一切，但无论接下来发生什么，你都绝不能干涉。\n\n我还能尝试最后一个仪式，但它被艾露恩禁止了。因为……因为很少有人能承受那种痛苦。可就算我活不下来……图莉普？嗯……她也会为我做同样的事。",
  },
  [26972] = {
    ["T"] = "额外学分",
    ["O"] = "从血色伐木工身上收集4本抗暗影笔记本，并带给布莱克伍德院长。",
    ["D"] = "$N，我知道你一定担心自己能否通过这里的课程，所以我给你一个特别提议。血色十字军会给他们的伐木工发放特殊笔记本，很难被暗影魔法损坏。据说是为了让他们能写信给家乡的亲人，而纸张不会携带天灾的污秽。真是胡说八道——但这些笔记本对我们粗心的死灵法术学生来说正合适。\n\n当然，那些伐木工就在北边的血色伐木场。替我们的收藏补货，我就给你的成绩单加分。",
  },
  [27082] = {
    ["T"] = "如何和熊怪交朋友",
    ["O"] = "按照诺尔格的指示参加熊怪友谊仪式，从 /bow 开始。",
    ["D"] = "舞蹈是熊怪手势的说法，因为它是仪式。你照我做。仔细听话。等你照我做完，我们就是朋友。\n\n也许你也能和你的朋友们这样做。教他们像熊怪一样交朋友。先对诺尔格做 /bow。",
  },
  [27403] = {
    ["T"] = "大地的隆隆声",
    ["O"] = "从巨翼捕猎者、雄性巨翼双足飞龙或巨翼雄兽身上收集3根金属尾刺。",
    ["D"] = "好吧，我不能否认我兄弟帮我造这个小玩意省了些时间，但它还需要一样东西：更多动力！我可以用一块临时电池给它超强充能，但我需要几样东西。首先是你能找到的最强巨翼双足飞龙的金属尾巴，它们就在这里西北边。\n\n我只要其中最大、最凶、最强壮的！你可以从捕猎者、雄兽或族长身上取得不错的成熟尾巴。",
  },
  [27436] = {
    ["T"] = "继续冰凉",
    ["O"] = "把冷藏箱带给安杰瓦萨的阿基哈，并请他指点如何为它注入力量。",
    ["D"] = "我必须承认，我很喜欢乌提·跃日，也想帮她。我会把冷藏箱借给你，但必须提醒你，它本身还不够强大，无法复制诺森德的严寒。\n\n要为冷藏箱注入力量，让它强到足以拯救一名海象人，你需要水元素的帮助。最近的水元素可以在安杰瓦萨找到，那是南边的一处前哨，我相信你并不陌生。去向那里一位名叫阿基哈的强大萨满请教。",
  },
  [27444] = {
    ["T"] = "完美燃料",
    ["O"] = "收集8块古代电池和6个从沙漠猎食蝎身上取出的蝎毒囊。",
    ["D"] = "我正在为你身后那件得意作品调配完美的火箭燃料。燃料是一切的关键，没有它，这东西就只是个过大的，呃……象征。我可不能让它这样！\n\n西边热影废墟里的古代巨魔曾制造过一种简陋的太阳能电池。它们在沙漠阳光下暴晒了几十年，电量只会更强。你能去收集一些吗，$n？\n\n顺便，我还需要你从附近的蝎子身上弄到最大的毒囊。",
  },
  [27508] = {
    ["T"] = "拯救研究资料",
    ["O"] = "从任意暴掠龙身上收集10份研究笔记，交给安戈洛环形山马绍尔营地的威利德·马绍尔。",
    ["D"] = "哦不，$N！我们和设备放在一起的研究笔记全都不见了。 \n\n从容器受损的情况来看，安戈洛的迅猛龙似乎在你之前就找到了它。那些笔记现在可能散落在任何地方。 \n\n如果你在环形山探索、靠近迅猛龙时碰巧找到我们的笔记，能不能好心把它们带回来？我不知道——你也许得杀几只看看它们身上有没有。",
  },
  [27509] = {
    ["T"] = "安戈洛狩猎",
    ["O"] = "杀死脊鳞，并把它的头带回安戈洛环形山马绍尔营地的小埃尔加丁。",
    ["D"] = "我搭着马绍尔探险队的顺风车来到了安戈洛环形山，但恐怕我有点应付不来了。也许你能帮我？ \n\n我的父母都是厉害的猎人，所以我决定来到安戈洛，向他们证明我已经准备好狩猎了。 \n\n坦白说，这里太可怕了，我想回家。但如果我空手离开，他们肯定会没完没了地念叨。你能替我猎取几只值得炫耀的野兽，好让我树立自己的传奇吗？ \n\n我听说一只名叫脊鳞的巨大双帆龙住在环形山北缘一块巨石附近。把它的头带给我当战利品。我会付钱的！",
  },
  [27546] = {
    ["T"] = "通往过去的大门",
    ["O"] = "在凯斯利尔湖周围，用未调谐的水晶与上层精灵灵魂调谐，然后回到凯斯利尔湖附近的灵魂先知尼谢尔那里。",
    ["D"] = "在我们开始仪式之前，必须先让水晶与我们想召唤的那种灵魂能量调谐。凯斯利尔湖的废墟里居住着那些目睹这场悲剧的精灵痛苦受难的灵魂。你需要对这些灵魂使用水晶，使它与我族人所在的灵界调谐。我是说，他们的族人。原谅我，我在这里待得太久，感觉自己仿佛已经成了这个地方的一部分。 \n\n摧毁这些灵魂让我痛苦，但如果我们要拯救其余的人，就必须作出牺牲。完成任务后回来找我。你离开时，我会组装你带来的仪式组件。",
  },
  [27547] = {
    ["T"] = "通往过去的大门",
    ["O"] = "帮助灵魂先知尼谢尔完成仪式。",
    ["D"] = "我感觉到虚灵的刺麻感在我的皮肤上游走，$C。我们已经非常接近了！我现在会把你带来的物品、来自玛艾里的调谐水晶，以及我自己调制的灵魂之尘结合起来。这需要一点时间，但等我完成后，一个灵魂就会现身。\n\n从这一刻起就没有回头路了，$N。一旦你触及凡世之外的世界，彼岸的灵魂就会永远知道该到哪里找到你。如果你现在选择离开，我不会责怪你。如果你选择留下，就保持警惕。我不知道这个灵魂会以什么形态出现。",
  },
  [27549] = {
    ["T"] = "通往过去的大门",
    ["O"] = "使用修复的水晶驱逐灵魂先知尼谢尔体内的恶意灵魂，并摧毁它。",
    ["D"] = "我可以翻译那本日记，但眼前还有一件更紧急的事。尼谢尔的研究让她被一个恶意灵魂附身了。让我解释一下。 \n\n凯斯利尔湖的上层精灵滥用了一件名为辛玛洛水晶的强大魔法神器。这块水晶太危险了，不能修复。你亲眼见过它给神殿居民带来的毁灭。我曾警告尼谢尔，有些谜团最好不要碰。 \n\n尼谢尔相信，如果她能理解灵魂如何使用这块水晶，就能控制它。她的研究让自己暴露在湖中灵魂的附身之下，如今一股恶意力量驱使着她行动。你尝试的仪式本意是打开一扇门，让更多灵魂进入我们的世界。幸运的是，你破坏了这道门。 \n\n既然这个实体信任你，我会修复这块水晶，让你能用它把灵魂从她体内驱逐出来并摧毁。也许那之后她会清醒过来，放弃这愚蠢的追求。",
  },
  [27888] = {
    ["T"] = "求生意志",
    ["O"] = "在奈尔斯·伯曼身上测试莱达的精神隔绝水晶，然后带着结果回到克罗雷修士那里。",
    ["D"] = "我可以让你在我们的囚犯身上测试你的理论，但有一个条件——在向其他任何人报告之前，先把结果告诉我。我们的特工费了很大力气才完好无损地抓住这个人。至少你该确保我不会被排除在研究之外。\n\n成交吗？",
  },
  [27909] = {
    ["T"] = "血脉与荣誉相连",
    ["O"] = "前往矿道地铁的工人纪念碑，使用仪式熏香向你的祖先致敬。",
    ["D"] = "你想更多地了解我的族人？我想我和任何人一样适合当老师，而且比大多数人更愿意。毕竟，我哪儿也去不了。\n\n如果你真想理解我的族人，就必须先明白，荣誉是你的言语、行为和行动的根基。我们的氏族由悠久的荣耀事迹维系。我们明白，自己的行动所体现的不只是自己。\n\n让我看看你如何尊敬他人。在你祖先安息之地使用这支仪式熏香，然后回到我这里。",
  },
  [27913] = {
