    ["O"] = "前往森金村附近的墓地，使用仪式熏香向你的祖先致敬。",
    ["D"] = "你想更多地了解我的族人？我想我和任何人一样适合当老师，而且比大多数人更愿意。毕竟，我哪儿也去不了。\n\n如果你真想理解我的族人，就必须先明白，荣誉是你的言语、行为和行动的根基。我们的氏族由悠久的荣耀事迹维系。我们明白，自己的行动所体现的不只是自己。\n\n让我看看你如何尊敬他人。在你祖先安息之地使用这支仪式熏香，然后回到我这里。",
  },
  [27935] = {
    ["T"] = "鉴赏家的味觉",
    ["O"] = "饮用石火旅店中旅店老板洛雷·火酒旁边酒桶里的酒，直到你感受到它的效果。",
    ["D"] = "你还真是个寻宝猎人，不是吗？到处跑，收集这些东西……就像你以前做过似的！\n\n大部分酒现在都准备好了。看这儿？这是一个侏儒朋友给的“快速发酵催化剂”……让我们看看它有没有用。\n\n<旅店老板洛雷·火酒把一份冒泡的液体倒进酒桶里，用力摇晃。酒桶呻吟着咕噜作响，最后终于安静下来。>\n\n好了，现在唯一要做的就是试喝！干杯，$C！我是说，给你喝。",
  },
  [27999] = {
