    ["D"] = "感谢你努力收集这份样本，但我对大地痛苦的来源仍然同样困惑。我必须征求第二意见。\n\n我有一位同事随一支研究探险队去了安戈洛环形山。我不知道雅鲁尼现在具体在哪里，但他是我认识的人里最适合评估这份样本的。\n\n请带上这块沸腾矿石，找到他。",
  },
  [31012] = {
    ["T"] = "眼前的问题",
    ["O"] = "碧蓝栖地的熊怪希望我们除掉尖石蛮兵和尖石引导者，让这一带少些敌意。",
    ["D"] = "<熊怪紧紧盯着水晶。>\n\n你看见吗？食人魔碰它，碰魔法，危险。必须在他们的愚蠢害死我们所有人之前阻止他们。击败保护法师的蛮兵，再除掉那些引导者。之后我们再谈。",
  },
  [31016] = {
    ["T"] = "光明任务",
    ["O"] = "我们的任务是找到一名强大的圣骑士，最好的选择大概是圣光之愿礼拜堂。也许我们可以向银色黎明的领袖玛克斯韦尔·泰罗索斯男爵求助。",
    ["D"] = "让我们先说清楚一件事——我不会允许你用这种被污染的魔法亵渎遗骸。我们要做的事已经够令人厌恶了。\n\n去寻求一位强大圣骑士的帮助。说服他们净化这柄权杖，并为它灌注神圣魔法，以减轻它将对灵魂造成的伤害。\n\n只有在那之后，你才可以回到碧蓝栖地并使用它，牛头人。你明白吗？我多希望还有别的办法……原谅我，同胞。",
  },
  [31018] = {
    ["T"] = "神圣专注",
    ["O"] = "等待净化仪式完成。",
