  },
  [26642] = {
    ["T"] = "米兰失踪了",
    ["O"] = "调查灰落岗哨外不远处的区域，寻找米兰下落的线索。",
    ["D"] = "哦，是冒险者！你看见我贴在旅店入口旁的告示了吗？\n\n我亲爱的丈夫米兰……他已经失踪好几天了！他是个草药师——他告诉我说要到城墙外去采些看到的草药，好卖点钱。\n\n<米尔迪丝开始掉泪。>\n\n从、从那以后我就再也没见过他！我们……我们根本没准备好应付这样的地方！\n\n求你了……你愿意去找找他吗？！你一定能做些什么！",
  },
  [26886] = {
    ["T"] = "我的朋友，劈颅者",
    ["O"] = "带着图泰克的灵魂护符回到格罗姆高的传说讲述者伊兹利那里。",
    ["D"] = "我的部族，劈颅氏族，是公平战败的。我没有死在战斗中，而是被俘了。我会被献祭给血神。这和如果他们战败，我们会做的事没有什么不同。\n\n我会为了部族的荣誉而死。我不需要你的任何帮助，$R。但你可以把这枚护符带给伊兹利，作为我友谊的信物。",
