  [26982] = {
    ["T"] = "上学的最后一天",
    ["O"] = "和布莱克伍德院长一起查看你的成绩单。",
    ["D"] = "好吧，$N，看起来你已经完成了所有入门课程。你还活着，而且四肢完整，这就是个好兆头。把成绩单交出来，我们看看你表现如何。",
