  [27518] = {
    ["T"] = "风暴、大地、风与火",
    ["O"] = "削弱六个空气元素，将空气之力吸收到雅鲁尼·观火者的图腾中。",
    ["D"] = "大地沉重、黏滞、厚密。我们将转向它的对立面——空气。\n\n空气的精华隐藏在安戈洛周围的群山中。你需要沿着环形山边缘寻找它们，前往东北和西南方向的山坡与山谷。\n\n重复同样的过程：削弱它们，然后用图腾夺取它们的精华。",
  },
  [27544] = {
    ["T"] = "给灵魂先知的礼物",
    ["O"] = "把奇异切面的水晶带给凯斯利尔湖附近的灵魂先知尼谢尔。",
    ["D"] = "冒险在召唤你——玛艾里知道！我正好有件事能考验你这样的年轻$C。\n\n我亲爱的朋友尼谢尔特别受灵魂触动。把这块水晶焦点带给凯斯利尔湖边的她，你会发现许多冒险随之而来。但要小心——这片土地上的鬼魂愤怒而不安。如果你无法安抚他们，他们也许会永远纠缠你！",
  },
  [31013] = {
    ["T"] = "片刻喘息",
    ["O"] = "与碧蓝栖地的熊怪交谈，听听他的故事。",
    ["D"] = "你问，我就回答。\n\n<他的目光很快又聚焦到水晶上。你也瞥了它一眼。水晶中散发出越来越强、如波浪般辐射开的深重不安感，仿佛周围所有能量都正在被它吸收。>",
  },
  [31020] = {
    ["T"] = "奥术疫害",
    ["O"] = "在碧蓝栖地对颅骨使用权杖，并与巨龙的灵魂交谈。",
    ["D"] = "玛克斯韦尔大人说，我们应该把权杖的魔法引导进巨龙的颅骨里。如果一切按计划进行，我们就能引出那条陨落蓝龙的灵魂。希望他们能给出我们迫切需要的答案和解决办法。",
  },
  [31021] = {
    ["T"] = "奥术疫害",
    ["O"] = "与碧蓝栖地的维利戈斯交谈。了解他的故事，并商议下一步。",
    ["D"] = "<这个灵魂似乎正慢慢稳定下来，并逐渐恢复意识。>\n\n我是维利戈斯，奥术大师，魔法的守护者。\n\n<维利戈斯把注意力集中到水晶上。>\n\n这个被诅咒的东西为什么会被激活？是谁愚蠢到解除了我的法术？ \n\n\n\n说话，$r，是你造成了这场迫在眉睫的灾难吗？",
  },
  [31023] = {
    ["T"] = "奥术疫害",
    ["O"] = "准备好开始召唤时与维利戈斯交谈。他要我们在碧蓝栖地的水晶旁杀死尖石魔导师领主。",
    ["D"] = "以这种形态存在时，我的能力大大削弱，但我一直试图观察水晶内部的魔法流动。我找到了我的宝珠能量痕迹，也找到了那个很可能曾经挥舞它的人。 \n\n<你感觉维利戈斯周围的能量猛然涌动。>\n\n我应该能通过一道传送门把他拖到这里来。准备好时告诉我，$N。",
  },
  [31028] = {
    ["T"] = "奥术疫害",
    ["O"] = "是时候结束这一切了。拿着维利戈斯的宝珠站在碧蓝栖地的水晶旁，开始压制。",
    ["D"] = "我已经尽力暂时融合了宝珠，但我太虚弱，无法操作它。 \n\n把宝珠拿到水晶旁，我会把所剩力量灌入两者，试着让它们调和。 \n\n在这件事上，水晶的巨大能量将成为压制它自身的关键。我会让魔法流动坍缩回自身之中，我们将把艾泽拉斯从这场灾祸中解救出来。 \n\n<维利戈斯停顿了一下。>\n\n我多希望自己能研究它啊，如果多年前我成功了就好了……也许在另一个人生里吧……",
  },
  [26644] = {
