  [26183] = {
    ["T"] = "和平的赠礼",
    ["O"] = "从乌博小屋北边的岛上收集乌博的华丽箱子。",
    ["D"] = "我们下一步得找个漂亮箱子，好让他们以为这真是份好礼物。现在想想，我也许该先让你去拿箱子，免得你的手沾上那些团子……算了！\n\n这里北边有座小岛，我母亲过世后，我把她的骨灰安放在一个漂亮箱子里，让她在那里安息。那是件精美的手工制品，正好适合这个计划；更重要的是，我母亲一定会觉得这整件事很可笑。",
  },
  [26286] = {
    ["T"] = "杀死工头",
    ["O"] = "杀死闪泥矿井内的风险投资公司工头。",
    ["D"] = "风险投资公司在那上面建了个该死的大型采矿场！难怪我很难弄到歌唱水晶。这种规模的作业很可能会让丛林的根基都崩塌。事情失控之前，总得有人处理它！\n\n帮我个忙，去干掉竞争对手，把闪泥矿井工头的脑袋带回来。他一死，我不仅能在这附近赚点漂亮利润，丛林也不会在这过程中被毁掉！",
  },
  [26300] = {
