    ["O"] = "在迪伊和达姆为格鲁克锻造新武器时给他们降温。",
    ["D"] = "我身后这两个笨重的蠢货是迪伊和达姆。他们远谈不上聪明，但很会拿着大锤敲铁砧，所以在我看来，他们已经和普通铁匠一样聪明了。\n\n他们锻造武器、承受高热时，我需要你用诺克赛恩的精华平息火焰，给他们降温。别让食人魔过热，否则这一切就全白费了。",
  },
  [26637] = {
    ["T"] = "缺席的对话",
    ["O"] = "把格鲁尔·石溪的设计交给莫格恩·黑眼。",
    ["D"] = "幸会，$C。大地之环派我来到这里，评估这片土地的状态。\n\n我在这里唯一能听见说话的元素就是火。它是暴力的化身，从元素的姿态到它们所说的方言都是如此。我听见一个声音凌驾于其他一切之上——嘶哑地命令大地震颤……而我希望让它沉默。你愿意帮我吗？\n\n我们可以把这个声音背后的力量束缚进一个元素体内，使它变得脆弱。不过，必须先做好准备。请把这张蚀刻图带给那边那个矮人……我想他叫莫格恩。\n\n看看他能不能打造出我画的东西。与此同时，我会为我们的目标收集材料，并在时机临近时来找你。",
  },
  [26669] = {
