    ["D"] = "你的下一个无聊任务，是去弄清楚为什么跑道上停着一架飞机。我看到工程师科巴尔特和它在一起，所以我猜出了点问题。他大概需要帮助，而我自己抽不出时间；我更担心这架别人付钱让我修的飞机。去看看他，问问他能不能用上你的帮忙。\n\n也许你会玩得开心，也许不会；我不在乎。",
