    ["O"] = "使用魔法罗盘追踪图莉普和丹尼尔。",
    ["D"] = "好了……这只罗盘会指引你找到图莉普和丹尼尔，无论他们身在何处。拜托，无论付出什么代价，都要把他们安全带回家，让他们终于能迎来自己的婚礼日！\n\n图莉普的记忆最强烈，所以它应该会先带你找到她，然后再找到丹尼尔。把他们安全带回来，$n！",
