  [26971] = {
    ["T"] = "腐肉烹饪",
    ["O"] = "从腐烂湖长颈龙身上取得一份长颈龙唾液腺，并回到伊莎贝尔·皮克曼那里。",
    ["D"] = "达隆米尔湖的水里过去满是无聊的普通鱼，偶尔还有湖长颈龙。天灾瘟疫杀死了鱼，但长颈龙还在。不仅如此，它们还变成了比从前更具攻击性、更有毒的版本。它们的唾液腺如今含有一种强效化合物，能够帮助增长肌肉并恢复活力。这就是我们的秘密原料！\n\n杀死那些长颈龙，直到你取回一枚完整的唾液腺。然后我们就可以开始搅拌了！",
  },
  [26973] = {
