    ["O"] = "使用采集注射器从哭泣洞穴取得三份软泥样本。",
    ["D"] = "哭泣洞穴是观察变异软泥怪自然栖息状态的迷人地点。我曾试着收养一只当宠物，但要找到合适性格的太费时间了。温顺、黏滑但又不能太黏、恶心……哦，我刚才说到哪儿了？对，炼金课。\n\n我们必须进行研究，看看能否在圈养条件下培育出完美的软泥宠物。拿上这支注射器，从死去的软泥怪身上抽取样本。三份左右就够了。",
