    ["O"] = "与菲利普斯监考官交谈，开始实验。",
    ["D"] = "既然我们已经有了样本，我会让我的助手菲利普斯监考官主持下一项测试。如果物质像我预期的那样发生反应，他需要有人保护他。在庭院墙外东边、通往码头的道路旁找到菲利普斯监考官。\n\n还有，$N，不必多说，这将是你这门课程的考试。",
