    ["O"] = "杀死维克托和莉迪娅，取下他们的头颅，结束他们的实验，然后回到工头巴兰那里。",
    ["D"] = "唐纳利想要一个能给他那个小炼金邪教保全面子的解决方案？他会得到他的解决方案！\n\n去找维克托和莉迪娅。把他们的头带给我，来“结束”他们的项目！如果唐纳利以任何方式帮助他们，也把他的头砍下来！部落绝不容忍我们的“盟友”做出这种行为。\n\n解散！",
