  [27114] = {
    ["T"] = "打捞海洋",
    ["O"] = "从晃荡谷附近的海中收集威尔伯、温迪、威尔森和威廉明娜遗失的补给，然后使用有限传送触发器回到晃荡谷的威尔伯·晃匠那里。",
    ["D"] = "嘿，$C！我知道晃荡谷现在还是个粗陋地方，但给我们一点时间，我们会把它变成艾泽拉斯偏远角落里的一项工程奇迹。\n\n为此，我需要有人帮忙找回我家人带来的补给。\n\n我们最初乘三架飞机出发，结果它们坠进了这里南边的海里。后来我们试图回收货箱，可船又沉了，我们差点没能游回岸上。\n\n既然我们没人会游泳，就需要你帮忙潜进水里，把你能从那些残骸中找到的东西带回来。\n\n别担心！科技来救场！完成后只要使用这个有限传送触发器，就能直接传送回这里！你得动作利索——电池撑不了太久。",
  },
  [27137] = {
