    ["O"] = "在地平线斥候号残骸附近寻找失踪船员，然后回到二副杉德里尔那里。",
    ["D"] = "船沉的时候，我们大多数人都保住了性命，但我注意到还有三名船员失踪。我游到残骸下方，想看看能不能找到他们，但我受了伤，没法继续寻找。\n\n我还在养伤。帮姑娘一个忙，看看能不能找到我们的大副、厨师和工程师。如果运气好，他们已经逃出来了，但我有种不祥的预感。",
  },
  [27231] = {
