    ["D"] = "既然燃刃抓走了温克尔，我们就需要一些特殊工具才能把他救回来！我的首席工程师伊科克·巧补也许能给你弄到点能帮上忙的东西。你可以在我身后那栋建筑里找到他。",
  },
  [27232] = {
