    ["D"] = "我也许有办法逼燃刃交出温克尔的位置！唯一的问题是……我们没有合适的工具。几年前，一艘载着一群工程师的船停靠在这里西北方的萨瑟里斯海岸外。纳迦袭击了他们，船也沉了。\n\n我听说船员携带的一些工具相当先进。甚至还有一种能催眠敌人的护目镜！从残骸中找回那副护目镜，我们也许就能用它找到温克尔。",
  },
  [27513] = {
    ["T"] = "希兹尔的飞行器升级版",
    ["O"] = "为安戈洛环形山马绍尔营地的希兹尔收集3块剑龙板甲。",
    ["D"] = "我忍不住听见你和那个埃尔加丁小孩说话。我一直在想，还有一样东西能给这架飞行器增添点亮眼效果——厚实坚硬的板材，用在飞行器中央。你洒出烈性朗姆时，它还正好能当滴液盘。 \n\n如果你要出去追那些剑龙，能不能顺手给我弄几块来试试？三块就够！",
  },
  [27514] = {
    ["T"] = "希兹尔的豪华飞行器",
    ["O"] = "为安戈洛环形山马绍尔营地的希兹尔收集1张魔暴龙皮。",
    ["D"] = "所以那孩子想让你干掉一头魔暴龙？好吧，如果你要去对付那种东西，我正好能用一套漂亮的皮革内饰装点我的飞行器。要剥下它们高品质的厚皮需要真正的制皮师，但随便哪个老冒险者都能替我砍下一张装饰用的皮。 \n\n噢，想想看吧。它既能防风雨，又很时髦！ \n\n你觉得怎么样？",
