    ["O"] = "莉莉要你使用附魔技能制作1块小块微光碎片，并把订单带给格雷迈恩之墙东北方山丘帐篷里的利奥·萨恩。",
    ["D"] = "等等，$C，你也是附魔师吗？利奥总是借材料给我，我一直不好意思不还这个人情。你能帮我把一块小块微光碎片带给他吗？我当然会付你报酬。",
