  [26284] = {
    ["T"] = "阿佐萨遗物",
    ["O"] = "在闪泥矿井内收集阿佐萨遗物。",
    ["D"] = "据说数千年前，巨魔曾与一个只被称为阿佐萨的族群交战。人们对他们所知甚少，不过包括我在内，一些更古怪的馆员相信这里还有更多表象之下的秘密。\n\n如果你所说属实，风险投资公司确实发现了一批他们的神器，那你就必须把它们带给我。它们属于博物馆！你愿意深入他们的矿井，尽可能多地为我收集这些东西吗？",
