  [26291] = {
    ["T"] = "巨魔遗物",
    ["O"] = "在闪泥矿井内收集巨魔遗物。",
    ["D"] = "传说说，数千年前，巨魔曾与一个只被称为阿佐萨的族群交战。除了他们在战斗中的顽强之外，人们对他们所知甚少。我相信这里还有更多表象之下的秘密。\n\n如果你说的是真的，风险投资公司发现了一批他们的神器，那你就必须把它们带给我。你愿意深入他们的矿井，尽可能多地为我收集这些东西吗？",
