    ["O"] = "使用图莉普的日记找到她的回忆之箱。",
    ["D"] = "我可不是海盗，不像我最好的朋友图莉普。她太厉害了！你知道吗，我曾经亲眼看见她一口把绳子咬成两截。她就是这么凶猛！除非她和丹尼尔在一起…… \n\n他现在是她的未婚夫了，她寄给我这本漂亮的日记，里面写满了他们如何相遇、相爱的故事。他们甚至请我主持婚礼。这真是莫大的荣幸。\n\n可是……你看……他们本该三天前就结婚，却一直没有到场，从那以后我就担心得要命。\n\n图莉普写过她埋下了珍贵的纪念物。也许你能找到他们的回忆之箱，把它指向的任何纪念品带给我？",
