    ["D"] = "我原本以为会有更多内容，但这里似乎只有他们共同珍视的回忆描述。\n\n我会把这些附在她的日记上，让你使用。依我看，他们还在另外两个地方留下了重要纪念物。也许那些东西能帮助我们追踪图莉普？",
