    ["D"] = "欢迎来上课，$N。天灾军团穿过瘟疫之地，在这一带所有居民身上都留下了痕迹。我希望你研究居住在哭泣洞穴中的泥沼兽的演化。你的作业是从那些生物身上取得六份真菌样本。沿着道路向东穿过瘟疫之地，直到来到一座桥边，然后顺着河流向北，就能找到那座洞穴。\n\n如果你见到它们的首领克拉克领主，我建议你离他远点。",
