    ["D"] = "我爬上附近的山脊，刚到顶上就感觉大地在震动。一头巨大的怪物走了过去——像迅猛龙，只是大了十倍！佩特拉告诉我它们叫魔暴龙，而且只在安戈洛环形山出没。 \n\n我的收藏里必须有一颗它们的头。这比我父母带回来的任何东西都更厉害。拜托，$N，替我杀一头魔暴龙，把它的头带回来！",
