    ["T"] = "协助托普西",
    ["O"] = "前往冰湖，放置核心提取器并守住它。找赫布尔·博迪温克拿核心提取器。",
    ["D"] = "你离开的时候，我幸好设法修好了这台机器。话说，你愿意再帮一次忙吗？这次我会付钱！\n\n这台机器叫冰核提取器。我们用它钻进南边的冰湖，研究冰层里的东西。它能提供关于我们气候的有用信息，也能告诉我们攻城引擎能不能开过冰面。\n\n只要把它带到湖中最深处使用，就在那个特别特别小的岛南边。你可能得保护它，防备野生动物！",
  },
  [26692] = {
    ["T"] = "酒馆闪击",
    ["O"] = "在镜湖上方雷霆瀑布的马迪根家附近与他会合。",
    ["D"] = "这正是我需要的——\n\n<马迪根注意到远处的什么东西，突然停下不说话了。>\n\n那是烟吗？山上？不可能……我得用炉石回家！请到雷霆瀑布我家那里和我会合！",
  },
  [26693] = {
    ["T"] = "酒馆闪击",
    ["O"] = "检查马迪根的家，寻找线索。",
    ["D"] = "<一道血迹从弗里茨的尸体延伸进马迪根的家。也许里面有线索可找？>",
  },
  [26694] = {
    ["T"] = "酒馆闪击",
    ["O"] = "去质问狮王之傲旅店后面的那个人，问清马迪根家起火的事。",
    ["D"] = "<拿着便条，你看见马迪根朝狮王之傲旅店方向狂奔而去，一边咒骂，一边气得满脸通红。>\n\n<你大概该跟上他，去质问那个破坏马迪根家、杀死他狗的人。>",
  },
  [26703] = {
    ["T"] = "阿祖拉之手",
    ["O"] = "把马迪根遭遇的事告诉卡莱因。",
    ["D"] = "卡莱因随时都会到。以我对他的了解，他一收拾好东西就会施放传送术。\n\n等他抵达后，我们必须确保他明白他儿子身上发生的事有多严重，并让你们两人踏上追踪马迪根去向的道路。 \n\n阿祖拉之手暂时已经不在我们手中，但至少我们可以试着帮助马迪根。",
  },
  [26727] = {
    ["T"] = "奉献的回响",
    ["O"] = "从蘑菇谷的邪恶的希尔杜尔身上取回塞拉芬的吊坠盒。",
    ["D"] = "我与艾利德林的羁绊只是把我拴在这个世界上的一部分。我的凡人遗骸在与大地合一之前就被洗劫了。\n\n艾利德林在我们结合五周年时送给我一个吊坠盒。那个吊坠盒现在落在诅咒教派手中。我能感觉到它就在这里南边的蘑菇谷。\n\n盗走我遗体物品的盗墓贼，在我生前叫希尔杜尔——一个曾路过我们家的旅行商人。我不知道他如今变成了什么，但他肯定已经不再是商人了。",
  },
  [26729] = {
    ["T"] = "实地考察",
    ["O"] = "在科林路口找到名誉教授寒骨，杀死他，并取回他的日记。",
    ["D"] = "看来这位无名的前教师如今被称作寒骨。这里有张便条显示，他前往科林路口继续搜索了。根据我们对新近复生巫妖的了解，寒骨还没有成长到完全掌握自身力量的程度。这意味着你应该能对付他，不必调动整支军队。\n\n我希望他会掌握更多关于教派在这里寻找何物的信息，但我们也应该趁现在消灭他，别让他变得更强。",
  },
  [26732] = {
    ["T"] = "实地考察",
    ["O"] = "观察会面，并截获寒骨的护命匣。",
    ["D"] = "你把自己藏进箱子里，希望这场会面不要等太久才开始——前提是你及时赶到了。\n\n你的耐心得到了回报，火把光芒掠过堆放的木桶，几道人影在夜色昏暗中浮现。",
  },
  [26749] = {
    ["T"] = "清除竞争",
    ["O"] = "杀死6名天灾士兵、4名地穴捕猎者、2名撕裂尖啸者和一头染疫猪。",
    ["D"] = "我的顾客需要终极购物体验，而我不禁注意到店铺周围晃着几个讨厌的流氓。 \n\n能否请你说服他们换个地方存在？任何说服手段都可以！哈！你会看到的！这会非常壮观！ \n\n哦，还要杀一头那种猪。它吃了我最后一个甜甜圈！",
  },
  [26751] = {
    ["T"] = "挨家挨户营销",
    ["O"] = "通知6名幽灵居民，让他们知道奥古斯图斯疯狂低价大促销！",
    ["D"] = "现在我真正准备好做生意了！所以出去告诉恐惧谷的好人们：购物的时刻到了！ \n\n你可不想错过这个。我的价格疯了！",
  },
  [26765] = {
    ["T"] = "我们有技术",
    ["O"] = "从提尔之手附近或通往奎尔萨拉斯道路上的天灾技工身上收集一把天灾扳手、一把天灾活动扳手和一把天灾锤。",
    ["D"] = "哇，看看这个，$N。有些部件需要诺森德熔炉制造的专用冷铁工具。我没有那些！事实上，我认识的人里没人有！ \n\n但我敢打赌，那些正在抢修这些车辆的天灾技工有。要是附近的家伙身上没有，你可以沿着通往奎尔萨拉斯的道路往北找更多。",
  },
  [26769] = {
    ["T"] = "应得的甜点",
    ["O"] = "从阿祖拉之塔外的井里钓起一份法力污染淤泥。",
    ["D"] = "好，既然你把材料带来了，我会做一块美味蛋糕——但我还需要一样东西：一种味道很重、能压过蛋糕里其他所有味道的东西。\n\n附近那口井从没人用，因为它已经被主人的实验污染了。我确信我们需要的东西就在下面。拿上这根鱼竿，替我钓上一些法力污染淤泥。",
  },
  [26770] = {
    ["T"] = "应得的甜点",
    ["O"] = "把莎拉的蛋糕献给塞欧克瑞图斯。",
    ["D"] = "好了，蛋糕做好了。表面上看，美味极了……但里面哪怕只吃一小口，也保证会让食用者遭受严重的胃部悸动。\n\n把蛋糕带给塔顶的塞欧克瑞图斯。我想这会治好他对糕点的瘾。然后他就会不再抱怨，吃我做的健康又美味的食物了。",
  },
  [26775] = {
    ["T"] = "照料伤员",
    ["O"] = "使用蜘蛛药剂治疗达西护士长野战急救帐篷中中毒的矿工。",
    ["D"] = "现在我们有了这种抗毒剂，就能安心治疗剩下的伤员。给我身后的每个矿工各用一剂，让他们能平安健康地回到家人身边。",
  },
  [26895] = {
    ["T"] = "力量之环：断角",
    ["O"] = "击败断角。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "你准备好迎接第一场战斗了吗？如果准备好了，就告诉我，我会让事情开始。你要做的只是到力量之环里等你的对手到来。\n\n这场战斗的对手是断角，一头凶猛的科多兽。\n\n祝你好运！希望你带了朋友来。\n\n还有记住，只有当你或你的对手面朝下躺在竞技场地板上时，战斗才算结束。",
  },
  [26896] = {
    ["T"] = "力量之环：双子",
    ["O"] = "击败纳迦双子。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "下一场战斗涉及一对搭档——准确地说，是一对双胞胎姐妹。\n\n现在临阵退缩还不算晚，$n。我当然能理解。\n\n但如果你已经准备好活动筋骨，就走进力量之环，等那对双子到来。\n\n最后还站着的人就是赢家！",
  },
  [26897] = {
    ["T"] = "力量之环：石凝",
    ["O"] = "击败石凝。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "你在场上杀疯了，孩子，但食人魔给下一场比赛找了个强援。他们说那家伙是石化蜥蜴还是什么的……他们绝不想让你直接对上他们的冠军。赌注已经高到离谱！\n\n进场去，快点把这一个解决掉！",
  },
  [26898] = {
    ["T"] = "力量之环：温斯顿",
    ["O"] = "击败温斯顿。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "这场战斗会很疼，$n。你有没有足够勇敢、愿意帮你的朋友？我们设法弄来了一只名叫温斯顿的巨猿！相信我，你会需要朋友的，他看起来不可战胜！他硬得像石头！\n\n如果你还想和他打，就走进力量之环，他会来的。",
  },
  [26900] = {
    ["T"] = "力量之环：最终挑战",
    ["O"] = "击败督军卢尔格。如果你获胜，就与巨魔仆从乌恩加交谈以领取奖励。",
    ["D"] = "<菲克正在清点他那堆巨大的金币。>\n\n你替我赚了好多钱，孩子。如果你能击败卢尔格，我保证会让你觉得值得。你在力量之环里吃过的那些苦，最后都会得到回报。\n\n现在进去，让他看看你是什么料！",
  },
  [26901] = {
    ["T"] = "鱼翅汤",
    ["O"] = "从邪恶暗礁内的邪恶鲨鱼身上收集8片完整的鱼翅。",
    ["D"] = "这里的当地人显然很喜欢一种他们称为鱼翅汤的东西。制作过程很别扭，但据说成品对身体健康很有好处。\n\n去暗礁那里，从那片区域的鲨鱼身上收集鱼翅，带给我，这样我就能熬汤了。",
  },
  [26931] = {
    ["T"] = "阿鲁高的伏击",
    ["O"] = "把箱子里的东西给亡灵卫兵基萨佩尔看。",
    ["D"] = "箱子跳太多。箱子里面毛茸茸。箱子舔我手。科尔偷看时，箱子看起来害怕。箱子不坏。给基萨佩尔卫兵看箱子。",
  },
  [26936] = {
    ["T"] = "北岸矿洞",
    ["O"] = "带着历史学家佩奇的消息回到贾斯珀·格林那里。",
    ["D"] = "如果矿洞被鱼人围住了，那格林就该穿上他的大僵尸裤子，把问题处理掉！这已经是他第二次没能完成一件简单任务了。回去告诉他，解决矿洞里挡在他面前的东西。\n\n野外工作很危险，如果他应付不了，我现在就需要知道。",
  },
  [26937] = {
    ["T"] = "北岸矿洞",
    ["O"] = "替贾斯珀·格林清理北岸矿洞。",
    ["D"] = "听着，$N，我没有多少金币，但只要你愿意下到矿洞里把它清理干净，我有的都归你。只要让我把功劳领了，好让我能回屋继续看书。如果你这么做，你就会永远在传承者中有个朋友。\n\n那座矿洞不在常走的路上，过了道路尽头，靠近一个小池塘。沿着磨损的小路往西走就行。",
  },
  [26951] = {
    ["T"] = "时间流的问题",
    ["O"] = "搜寻艾泽拉斯的危险角落，寻找其他时间扰动。",
    ["D"] = "安多哈尔的时间扰动并不是唯一让我感官发痒的扭曲。我怀疑眼下有更大的问题。而一旦牵涉到时间流，我的感觉从不会错。\n\n我的朋友，我和我的龙族还能再用上你的帮助。我必须留下来收拾这个小麻烦，但我怀疑世界上的其他地方也可能受到时间寄生虫影响。我不知道确切位置，但如果你搜寻世界上最危险的角落，我相信你会找到它们。把你的发现告诉我。祝你好运！",
  },
  [26956] = {
    ["T"] = "弓匠的请求",
    ["O"] = "从瘟疫之地的木柴堆中收集10块精灵心木。",
    ["D"] = "接下来我们需要收集制作弩身的木材。笔记上说，纳萨诺斯使用的是高等精灵称为洛米尔的树木，通用语里叫心木。心木能制成优秀武器，放进壁炉也能燃烧很久。\n\n我在想，瘟疫之地各处废墟附近的木柴堆里，也许还留有一些心木。想不想去搜刮一番？",
  },
  [26960] = {
    ["T"] = "英雄崇拜",
    ["O"] = "从瘟疫之地的木柴堆中收集10块精灵心木。",
    ["D"] = "我们一开始做的是件简单差事。接下来这个更容易。\n\n奎尔萨拉斯树木的心木最适合制作弓。既然奎尔萨拉斯已经毁了，你就得四处看看，能不能在洛丹伦废墟周围留下的木柴堆里找到任何心木。快去！",
  },
  [26962] = {
    ["T"] = "英雄崇拜",
    ["O"] = "把游侠玛瑞斯的笔记带给亡灵壁垒的谢尔登·格里姆斯比。",
    ["D"] = "好吧，你需要的东西都齐了。这里有些说明，告诉你该怎么处理这些材料。\n\n现在从你来的地方回去吧。",
  },
  [26969] = {
    ["T"] = "天灾植物学",
    ["O"] = "把真菌样本种进准备好的土壤里，并观察结果。",
    ["D"] = "让我看看你怎么应付真正的植物学。拿上这份土壤样本、真菌和喷壶，到广场上方一个备用花盆那里去。把土壤填进花盆，种下真菌。用喷壶浇一点水，然后观察结果。之后回来向我报告。",
  },
  [26980] = {
    ["T"] = "毕业班恶作剧",
    ["O"] = "从一名血色祈求者身上收集一块硫磺。",
    ["D"] = "接下来我们需要一样能很快生火的东西。血色祈求者随身带着硫磺块，作为施放火焰法术的材料。那大概就能派上用场。也把那东西带回来吧。这会非常史诗！",
  },
  [27009] = {
    ["T"] = "撤离报告",
    ["O"] = "把最终撤离报告交给奥克马斯特镇长。",
    ["D"] = "我确定那就是最后一批撤离者了。你帮了我和这些镇子一个大忙。现在我们终于能把那份报告带回给镇长。\n\n把这个交给他，这样我就知道他不会再盯着我了。",
  },
  [27013] = {
    ["T"] = "魔像陀螺仪",
    ["O"] = "尝试修好安格斯农场的魔像。",
    ["D"] = "我们动手吧！如果能让那台魔像重新运转起来，我就能轻松养活我们的难民；没有它，我们就无能为力。\n\n拿上这些陀螺仪，把它们装上去，看看能不能让它动起来！",
