    ["O"] = "收集10份加林的玉米作物。",
    ["D"] = "如果我们要上路离开这里，就需要食物。幸运的是，我最后一批作物差不多可以收割了，但我不能一边照看它们，一边让家人准备好。\n\n从附近田地里收割我的谷物，并把它准备好让我们带走，我们很快就不会再麻烦你了。",
