    ["O"] = "在高地角落池塘里找到莎拉的玩偶“英雄”。",
    ["D"] = "我哪儿也不去！我在池塘边和我的玩偶英雄玩，可那个坏蛋老绿没有把它还给我。\n\n爸爸说我们要离开，但我不会把英雄丢下！\n\n把我的玩偶拿回来！",
