    ["O"] = "从佐拉雌蝎身上取得3颗佐拉雌蝎大脑。",
    ["D"] = "佐拉虫巢里有一种被称为“虫巢姐妹”的异种虫。这个变种有什么特别之处？它们比其他类型更强，还是更弱？我有太多问题了！我把这件事告诉了远征队里的其他人，但萨西亚似乎认为，如果派出部队去获取样本，就会让我们面临严重危险。\n\n我很不愿意开口，但你能不能替我收集它们的大脑样本，带回来供我研究？",
