    ["O"] = "领取你的远征队补给箱。",
    ["D"] = "",
  },
  [27418] = {
    ["T"] = "洛阿的敬意",
    ["O"] = "在天涯海滩的祭坛上向格拉尔献祭，以赢得他的青睐。",
    ["D"] = "现在，俺还有另一个任务给你。俺要你把这块肉带到天涯海滩的祭坛上，放在那里献给格拉尔。希望他会喜欢这份供品，并现身见我们。\n\n要找到天涯海滩的祭坛，只要从安杰瓦萨往东走，直到抵达沙滩。祭坛就在水边附近。\n\n献上供品后，回安杰瓦萨找俺，俺会奖励你的努力。愿格拉尔指引你的旅程。",
