  [27420] = {
    ["T"] = "两条腿的秃鹫",
    ["O"] = "从马尔冯坠毁飞艇旁的劫掠者手中找回马尔冯的怀表、宽边帽和业余无线电。",
    ["D"] = "我两周前坠毁在这里，而我的飞艇已经被劫掠者占了。\n\n他们和秃鹫没什么两样，从不知哪里扑出来，把不属于他们的东西拆得七零八落。\n\n可是这里就我一个人，而且我还得专注于研究。你能不能行行好，从那些劫掠者手里把我的东西拿回来？你也看到了，我现在身边几乎什么都不剩。",
  },
  [27421] = {
    ["T"] = "营救轻足",
    ["O"] = "护送斥候轻足离开腐化之巢，并沿途保护他免受任何威胁。",
    ["D"] = "谢谢你找到我。我在腐化之巢执行侦察任务时遭到伏击，被打昏了过去。我需要你帮我离开这里，回到安杰瓦萨。你愿意帮我吗？",
  },
  [27423] = {
    ["T"] = "斥候的荣誉",
    ["O"] = "前往西北方的腐化之巢，找到一名正在监视当地情况的斥候影舞者。",
    ["D"] = "仔细听着，冒险者。我派了一名强壮的巨魔影舞者和她的侦察队去西北方的腐化之巢监视情况。他们已经好几个星期没有回报了，我担心他们的安全。我需要有人前往腐化之巢，找到他们。\n\n我不能容忍无能。如果影舞者和她的队伍身处险境，你就有责任找到他们并确保他们安全。去腐化之巢，在找到他们之前不要回来。还有，记住——如果你没能完成这项任务，就要面对我全部的怒火。听明白了吗？",
  },
  [27424] = {
    ["T"] = "队伍分崩",
    ["O"] = "从腐化之巢地表的森提帕尔巨蜂身上收集8根森提帕尔巨蜂毒刺。",
    ["D"] = "我的侦察队其他成员在与昆虫异种虫的战斗中，被麻痹性毒素刺中并昏迷不醒。我很担心他们的安全。我需要腐化之巢地表森提帕尔巨蜂的毒刺来制作一种药膏，清除毒素并帮助他们恢复。",
  },
  [27426] = {
    ["T"] = "站起来",
    ["O"] = "在腐化之巢地表找到并唤醒8名昏迷的斥候。",
    ["D"] = "我的侦察队安危攸关，我们必须尽快唤醒他们。前往腐化之巢，使用我制作的药膏唤醒那些昏迷的斥候。除非你成功唤醒所有斥候，否则不要回来。听明白了吗，$n？",
  },
  [27429] = {
    ["T"] = "乌鲁尔格的报告",
    ["O"] = "把侦察报告带回安杰瓦萨的乌鲁尔格那里。",
    ["D"] = "我们已经成功清除了巢穴里的所有敌对生物，并在异种虫毒刺中发现了一种潜在武器。如果你能把这份报告交给我的上级乌鲁尔格，并告知他我们的成功，我会非常感激。",
  },
  [27432] = {
    ["T"] = "冰凉的陌生人",
    ["O"] = "为沃提·跃日收集8株沙岸海草和6瓶海浪龟水。",
    ["D"] = "这个海象人正因为沙漠的酷热而陷入极大危险。我担心如果没有一个冷却图腾保护他，他撑不了多久。\n\n要制作图腾，我们需要一种叫沙岸海草的特殊海草，它只生长在沙漠海岸；还需要来自乌龟壳里的水。没错，你没听错。乌龟壳。\n\n我知道这会很困难，但我求求你，请帮我收集这些材料。这个海象人的性命就靠它们了。",
  },
  [27433] = {
    ["T"] = "冰凉的陌生人",
    ["O"] = "为天涯海滩的沃提·跃日用月亮井的水装满水晶瓶，并从灌木谷的灌木寻棘者身上收集8根坚韧根须。",
    ["D"] = "我担心冷却图腾的力量还不足以帮助这个海象人。沙漠的酷热太强了，他需要更强大的材料才能恢复。\n\n我听说西北方的灌木谷里有一口月亮井。据说月亮井的水拥有强大的治疗能力。如果能取得一些井水，就能大大增强图腾。\n\n此外，栖息在山谷里的最强灌木怪物据说有强韧的根须，能增强草药疗法的效力。如果你能为我们收集一些根须，那会帮上大忙。\n\n我知道这趟旅程很危险，但我求求你，请帮我取得这些材料。这个海象人的性命就靠它们了。",
  },
  [27434] = {
    ["T"] = "冰凉的陌生人",
    ["O"] = "把水之图腾放在沃提·跃日家中海象人罗克纳身边。",
    ["D"] = "图腾快准备好了，冒险者。我只需要你帮忙把它放到海象人身边。他的状况仍然危急，而图腾会提供他所需的治疗。\n\n你能帮我把图腾放在海象人身边吗？我非常感谢你的帮助。",
  },
  [27437] = {
    ["T"] = "水之祝福",
    ["O"] = "请安杰瓦萨的两名水元素为冷藏箱赐福。",
    ["D"] = "俺看见你眼里的决心和热情了，冒险者。你真心相信拯救海象人的重要性。俺佩服你的意志，也会尽俺所能帮助你。\n\n但要小心，朋友。水元素不是被俺强行束缚的。它们是自愿与俺结下羁绊，俺不能命令它们违背自己的意愿做任何事。\n\n你必须请求水元素援助，并说服它们明白冷藏箱的必要，以及拯救海象人的重要性。如果你能做到，它们就会自愿为冷藏箱注入力量，让它强到足以救下海象人的性命。",
  },
  [27438] = {
    ["T"] = "冰凉的朋友",
    ["O"] = "把注能冷藏箱放在海象人身边，治好他的中暑。",
    ["D"] = "冒险者，在我们拯救海象人的过程中，你发挥了关键作用。没有你的帮助，我们肯定会失败。\n\n我想请你帮最后一个忙。能否由你来把冷藏箱放在海象人身边，救下他的性命？这对我来说会是莫大的荣幸，我知道那个海象人也会心怀感激。",
  },
  [27441] = {
    ["T"] = "脑袋炸开",
    ["O"] = "使用爆炸心灵控制帽，把丹尼斯送进北部的大裂口虫巢，并摧毁里面的哈扎里主脑。",
    ["D"] = "异种虫是简单的野兽，就算少了半个脑子也能“运作”。那边的小丹尼斯就是最好的例子。遗憾的是，这顶帽子是给他的。\n\n异种虫不会攻击他，这样我们就能深入大裂口虫巢，干掉控制它们的主脑。我相信莉琳不会介意牺牲她的宠物。",
  },
  [27449] = {
    ["T"] = "最后倒计时",
    ["O"] = "按下戈达德旁边的起爆器，开始火箭的起飞程序。",
    ["D"] = "就是现在，$n！我们终于要测试这枚火箭，看看一个地精能飞多高了。当然，先做无人测试。既然你一直帮了这么多忙，不如由你来完成这份荣誉，按下我旁边那个起爆器？那会启动测试。",
  },
  [27453] = {
    ["T"] = "死去的讯息",
    ["O"] = "带着坏消息回到传承者万扎那里。",
    ["D"] = "死去巨魔的武器上沾满了人形生物的血。他们在死前狠狠反抗过。你注意到尸体上有些奇怪的发黑皮肤，看起来并不是腐烂造成的。\n\n你检查尸体，发现他们的信使袋已经空了。他们携带的任何讯息都被劫走了，而其他贵重物品却被留了下来。\n\n传承者万扎需要知道这件事。",
  },
  [27469] = {
    ["T"] = "火焰箭头",
    ["O"] = "把火焰箭带给安杰瓦萨的雷米·冷眼。",
    ["D"] = "火焰箭已经完成了，$n。现在是时候让它们派上用场了。我要你把它们送给雷米·冷眼，他会把这些箭分发给我们的新兵，用于对抗异种虫的战斗。",
  },
  [27473] = {
    ["T"] = "注水",
    ["O"] = "从沙丘中央破碎石柱废墟附近坠毁的飞艇上收集8个燃料喷射器。",
    ["D"] = "等等，等等，等等。这里肯定有哪里不对。水压完全达不到我们需要的程度。让我想想……\n\n我知道了！这里西南方，破碎石柱废墟那里，有个我们曾经雇用过的疯狂科学家。他的飞艇坠毁在附近，里面载着一些燃料喷射器。只要稍微改造一下，我就能把它们变成注水器。路有点远，但你能去把它们拿来吗？等你到了沙丘中央，坠毁地点应该很容易看见。",
  },
  [27499] = {
    ["T"] = "平原幽魂",
    ["O"] = "击败尘蹄酋长的灵魂。",
    ["D"] = "嘿，你看起来像那种英雄人物。有空吗？\n\n我们最近遇到些麻烦，有几辆赛车突然偏离赛道，冲到路外撞毁。我知道你在想什么，但相信我，这回真的不是地精科技爆炸。起初我以为是那些侏儒在我们的引擎上动手脚，结果他们的赛车手也遇到了同样的事。\n\n你可能会问，“同样的事”是什么？好吧，有个车祸幸存者说，他看见一个披着尘土毛皮的牛头人酋长幽魂在赛道东边游荡。侏儒说那是海市蜃楼，但我可不觉得海市蜃楼会跑到赛道上，把人吓到失控！\n\n我要你替我调查这件事。需要的话就带上朋友，但把那个幽灵老头赶出道路！",
  },
  [27501] = {
    ["T"] = "神圣之火",
    ["O"] = "为法芬德尔·行路者取回裂开的蹄子。",
    ["D"] = "拿上这个瓶子，在这里的月亮井装满水。如果我的推测正确，月亮井水可以熄灭火焰，让你取回那只蹄子。火焰不会永远熄灭，所以你的动作必须快。\n\n回到裂蹄堡，为我取回裂开的蹄子。半人马和树妖似乎有相近的祖源，我毫不怀疑这只蹄子与此有关。",
  },
  [27510] = {
    ["T"] = "安戈洛狩猎",
    ["O"] = "杀死惧翼，并把它的头带回安戈洛环形山马绍尔营地的S.J.埃尔加丁二世那里。",
    ["D"] = "马绍尔远征队刚进入环形山时，我们经过了一片霍尔阿尼称作铁石高原的地方。那里有一群飞行野兽，其中有一只看起来比其他的更大、更凶猛。我们给它起了个绰号叫惧翼。\n\n你能找到惧翼，并把它的头带给我吗？我觉得那会是比这个更令人印象深刻的战利品。",
  },
  [27553] = {
    ["T"] = "一生心血",
    ["O"] = "在艾伦·霍桑的洞穴里，对肉堆使用霍桑的不稳定溶液。",
    ["D"] = "我打算把我的成果广泛分享出去，就从你开始。你离开时，我翻阅了导师关于憎恶的教诲。万事俱备——你自己看看吧。\n\n<那堆血肉看起来和你离开时一模一样。>\n\n拿起这只瓶子，把里面的东西倒到肉堆上。",
  },
  [27555] = {
    ["T"] = "未完成的任务",
    ["O"] = "在艾伦·霍桑的洞穴里，对肉堆使用霍桑的稳定溶液。",
    ["D"] = "我们再试一次，好吗？\n\n你离开时，我“强化”了那些大脑，而有了灵质，这个生物的心智就会有更多东西分散它对怒火的注意。再加上它越能推理，就越容易控制。\n\n我已经改良了溶液。剩下的只是倒下去，而这项任务又一次落到你身上。",
  },
  [27559] = {
    ["T"] = "优质试剂",
    ["O"] = "使用塔努姆的钢锯，从塔努姆营地东边的冰蓟雪人尸体上采集80根雪人手指。",
    ["D"] = "所——以，那位女士想要她的药水，是吧？那个小地精一点耐心都没有！我把货送过去才一天……！\n\n<塔努姆挠了挠沾满药水的胡子，胡须一把把掉了下来。>\n\n你叫什么来着……$N……？$N，既然你来了，为什么不帮帮这个疲惫的老矮人呢。要做这些药水，我需要东边山丘上那些大野兽身上的雪人手指。没错，手指——要完整的，尤其是爪子！你也能在那边上方的洞穴里找到它们。\n\n现在可别犯恶心！拿上我的钢锯，好好享受吧。",
  },
  [27560] = {
    ["T"] = "怨嚎",
    ["O"] = "杀死塔努姆营地东边悬崖洞穴里的怨嚎。",
    ["D"] = "听着，$N。你听见那声音了吗？\n\n<塔努姆停了下来，你听见东边传来一阵微弱的咆哮。>\n\n我在这儿的整段时间都得忍受这动静！而且我知道是谁搞出来的……就是那边洞穴深处那坨肥毛球！现在嘛，他对我这种……谦逊本事的人来说有点太危险了，但对你来说……？\n\n<塔努姆搓了搓手指，用圆溜溜的小眼睛打量你的装备。与你对视时，他脸上爬起一抹阴险的笑。>\n\n我需要安静才能干活！我会让你觉得值得，$C……？",
  },
  [27566] = {
    ["T"] = "月下哀悼",
    ["O"] = "在夜晚协助德莱文·霜凝，在隐秘林地内击败月狂枭兽。",
    ["D"] = "在梦里，我见过一只孤独的枭兽徘徊在林地里，满怀仇恨。它感觉……绝望，尽管周围看不出有什么明显危险。我怀疑这个生物知道我的意图，却仍被怒火牢牢束缚。\n\n法杖已经完成，但我必须再次借助你的力量。夜幕降临时，林地的植物和动物会彼此调谐：这将成为我们的行动路径。法杖会接入这种调谐；我会直面那股愤怒，而如果我猜得没错，那只孤独的枭兽会成为那股愤怒的化身。\n\n准备好面对前方的危险时，就来和我说话。我会加入你，但我们必须在夜间前往。",
  },
  [27571] = {
    ["T"] = "未知魔法",
    ["O"] = "带着坚固卷轴匣回到泰雷萨兰外的莱琳女士那里。",
    ["D"] = "好了，$C。这样应该就行了！石板我会留下，但你需要拿上这个。\n\n<马里乌斯把一个沉重的卷轴匣交给你，匣子封得很严。>\n\n卷轴就在里面。请把它交给莱琳女士。一路顺风，祝你好运！",
  },
  [27572] = {
    ["T"] = "奥术馆",
    ["O"] = "使用泰雷萨兰法术卷轴打开奥术馆大门，并找到奥术馆宝库。",
    ["D"] = "好，计划是这样……\n\n泰雷萨兰城北缘有一座庞大的奎尔多雷宝库，名为奥术馆。它建在山中，用来守护许多珍宝，而其中的魔法强大到足以在这么多年后仍然保存里面的神器。你找到的那块石板上写着开启大门的咒语。明白我的意思了吗？\n\n那些幽灵不会帮我们，而我怀疑任何活人都说不出那些词，所以你要改用卷轴。根据我的研究，奥术馆最宏伟的宝库位于上层，戒备森严。把里面的东西带给我，$C。",
  },
  [27573] = {
    ["T"] = "奢靡欲望",
    ["O"] = "带着奎尔多雷神器回到泰雷萨兰外的莱琳女士那里。",
    ["D"] = "<莱琳女士会想看看你找到的神器。>",
  },
  [27575] = {
    ["T"] = "梦魇种子",
    ["O"] = "从泰雷萨兰内的萨特营地收集8颗梦魇种子。找到萨特营地中气味的源头。",
    ["D"] = "<种壳已经死了，被它曾经的主人啃掉了一半。这与你以前见过的任何东西都不同……而且闻起来腐臭。>\n\n<这片废墟里有某种东西散发着同样刺鼻的气味，而且你越靠近萨特营地，气味就越强烈。>",
  },
  [27900] = {
    ["T"] = "大地母亲的赐予",
    ["O"] = "从大地母亲安息地的洞穴中取回安舍之心和穆莎之心，并把它们带给观星者纳洛。",
    ["D"] = "在牛头人和矮人之前，在城堡和村庄之前，远古时代的大地母亲曾行走在这片土地上。她的呼吸搅动了风，她的笑声让花朵盛放，而当她最终献出自己来保护她的造物时，我们知道她会以许多形态、在许多时刻回到我们身边。她的信息写在星辰中，由风传递，埋藏在大地里。\n\n预言说，当两轮火月划过天空时，一名外来者会来到我们这里，而你来了。你的任务很简单。你身后，沿山坡往下不远处，有一个洞穴。你会发现黑暗灵魂盘踞其中。击败它们，取回大地母亲留在那里的两件宝物——她子女的双子之心。把它们带回来给我，我会告诉你该如何使用它们。",
  },
  [27902] = {
    ["T"] = "大地母亲的赐予",
    ["O"] = "使用双子之心的力量净化大地母亲之骨。",
    ["D"] = "你现在拥有了注入力量的安舍之心和穆莎之心，它们是大地母亲双子子女的心。这将赐予你力量，击败一个徘徊已久的邪恶。\n\n沿着我帐篷南边的峭壁走，前往那些从大地中突出的巨岩。那就是大地母亲之骨，一个黑暗灵魂在那里藏身，等待出击的时机。它直到接近全盛力量时才会显现——而那个时刻已经近了。但凭借双子之心，你可以击败它。\n\n安舍之心会以大地母亲赐予子女的爱强化你——提升耐力。穆莎之心会削弱你的敌人，使它更容易受到你的攻击。\n\n如果你完成这项任务，你将得到所有大地母亲子女永恒的敬意。",
  },
  [27924] = {
    ["T"] = "复苏与喘息",
    ["O"] = "找到一罐治疗之水，并把它带给洛拉斯林·法博。",
    ["D"] = "不，住手！我、我没有武器，$R。\n\n<这名暗夜精灵看起来惊恐万分。严重的头部伤口正把血渗到洞穴地面上。>\n\n为什么……我会在这里……？喷、喷泉……我……求你……！\n\n<这名精灵快要昏过去了。阿波尼提到过这里的水有治疗特性，附近也许有个水罐。如果他不再神志不清，也许能告诉你更多。>",
