  [27942] = {
    ["T"] = "视界石",
    ["O"] = "从北方洞穴里的库扎杰拉爬行者身上收集20只库扎杰拉之眼。",
    ["D"] = "真让人惊讶，这里的石化蜥蜴和矮人有这么多相同本事。它们能敏锐地感知闪亮东西，也有一样的抗性……\n\n扎昆科在找那些眼睛，就是带着闪光光泽的那种。小心别盯太久，朋友……不然你的眼睛可就移不开了！\n\n闪亮的眼睛就是奖品。可以的话，把它们带来。",
