    ["O"] = "使用震荡器，从北方洞穴里的库扎杰拉爬行者身上采集80片库扎杰拉鳞片。",
    ["D"] = "扎昆科知道血肉诅咒，而我们可不想让诅咒倒过来发生，是吧？\n\n石化蜥蜴鳞片……它们是我们制作巫毒神像需要的材料。灵魂这么说，我们就必须服从。扎昆科这里有根杖，能很轻松地把鳞片弄下来……\n\n小心点，朋友。库扎杰拉可不是能轻视的敌人！",
