    ["O"] = "参加碎矛节庆中的掷斧比赛，然后回到碎矛村的乌娜·吉罗那里。",
    ["D"] = "欢迎来到碎矛节庆，$R！我们隐秘的家园很少允许外人进入，所以你该感到荣幸。任何时候想回家，只要来找我说一声。\n\n不过在你离开前，你该加入这场聚会。尝尝食物和饮料——如果你够勇敢，也可以在灯光下跳舞，甚至到掷斧靶场挑战碎矛冠军布鲁·祖尼尔，检验自己的本事。那些东西都在村子更深处。",
