    ["D"] = "在荆棘谷丛林远东边，有一座岛，我们曾经称它为暗矛岛。很久很久以前，我们被迫逃离那里，向西迁徙，后来又经历了一次同样的事，才定居在你如今在杜隆塔尔海岸外看到的地方。\n\n联盟的侏儒在那座后来被称为吉利吉姆之岛的岛上发现了某种东西，他们想把它挖空！我们不能让他们得到这份资源，也必须保护我们的历史。你愿意帮助我们吗？"
